/****** Object:  UserDefinedFunction [dbo].[UDF_GetDigit2Word]    Script Date: 18-02-2025 21:13:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   FUNCTION [dbo].[UDF_GetDigit2Word] 
(
	@Amount	AS NUMERIC(18,0)
) 
RETURNS NVARCHAR(100)
BEGIN
	DECLARE	@FirstAmount	NVARCHAR(50) 
			,@LastAmount	NVARCHAR(50);
  
	SELECT @FirstAmount = CASE WHEN @Amount >= 10 AND @Amount <= 19 THEN CASE @Amount WHEN 10 THEN 'Ten'
										 WHEN 11 THEN 'Eleven'
										 WHEN 12 THEN 'Twelve'
										 WHEN 13 THEN 'Thirteen'
										 WHEN 14 THEN 'Fourteen'
										 WHEN 15 THEN 'Fifteen'
										 WHEN 16 THEN 'Sixteen'
										 WHEN 17 THEN 'Seventeen'
										 WHEN 18 THEN 'Eighteen'
										 WHEN 19 THEN 'Nineteen'
									ELSE '' END
								ELSE CASE WHEN LEN(@Amount) = 2 THEN CASE LEFT(@Amount,1) 
											WHEN  2 THEN 'Twenty '
											WHEN  3 THEN 'Thirty '
											WHEN  4 THEN 'Forty '
											WHEN  5 THEN 'Fifty '
											WHEN  6 THEN 'Sixty '
											WHEN  7 THEN 'Seventy '
											WHEN  8 THEN 'Eighty '
											WHEN  9 THEN 'Ninety '
										ELSE '' END
									ELSE '' END END

		SELECT @LastAmount = CASE WHEN @Amount >= 10 AND @Amount <= 19 THEN ''
								ELSE CASE RIGHT(@Amount,1) 
											WHEN  1 THEN 'One'
											WHEN  2 THEN 'Two'
											WHEN  3 THEN 'Three'
											WHEN  4 THEN 'Four'
											WHEN  5 THEN 'Five'
											WHEN  6 THEN 'Six'
											WHEN  7 THEN 'Seven'
											WHEN  8 THEN 'Eight'
											WHEN  9 THEN 'Nine'
										ELSE ''
									END END
	RETURN RTRIM(LTRIM(@FirstAmount + @LastAmount))
END

GO
/****** Object:  UserDefinedFunction [dbo].[UDF_GetNumToWord]    Script Date: 18-02-2025 21:13:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   FUNCTION [dbo].[UDF_GetNumToWord]
(
	@Amount AS NUMERIC(18,2)
) 
RETURNS NVARCHAR(MAX)
BEGIN
	DECLARE @Rupees			NUMERIC(18,0)
			,@Paisa			NUMERIC(18,0)
			,@M_CURRENT		NUMERIC(18,0)
			,@StringValue	NVARCHAR(MAX)
			,@M_POSTFIX		NVARCHAR(20)    
			,@Words			NVARCHAR(100)

	SET @Amount = ISNULL(@Amount,0)
	SET @Rupees = LEFT(@Amount,LEN(@Amount)-3)
	SET @Paisa = RIGHT(@Amount,2)
	SET @StringValue = ''

	IF @Rupees = 0 AND @Paisa = 0 
	BEGIN
		SET @StringValue = 'Zero'
	END
	ELSE
	BEGIN
		IF @Rupees = 0
		BEGIN
			SET @StringValue = 'Zero'
		END
		ELSE
		BEGIN
			WHILE @Rupees > 0
			BEGIN
				SELECT @M_CURRENT = 
				CASE  WHEN LEN(@Rupees) = 3  THEN LEFT(@Rupees,1)
					  WHEN LEN(@Rupees) <= 2 THEN LEFT(@Rupees,2)
					  ELSE 
					  CASE    WHEN (LEN(@Rupees)-2) % 2 = 0 THEN LEFT(@Rupees,1) 
							  ELSE LEFT(@Rupees,2) 
							  END
				END
        
				SELECT @Words = [dbo].[UDF_GetDigit2Word] (@M_CURRENT)

				SELECT @M_POSTFIX = CASE WHEN LEN(@Rupees) = 8 OR LEN(@Rupees) = 9 THEN 'Crore' 
											WHEN LEN(@Rupees) = 6 OR LEN(@Rupees) = 7 THEN 'Lakh' 
											WHEN LEN(@Rupees) = 4 OR LEN(@Rupees) = 5 THEN  'Thousand'
											WHEN LEN(@Rupees) = 3 THEN 'Hundred'
											ELSE '' 
									END
        
				SELECT @Rupees = CASE WHEN LEN(@Rupees) > 2 THEN RIGHT(@Rupees,LEN(@Rupees)-LEN(@M_CURRENT)) ELSE 0 END

				SET @StringValue = @StringValue + ' ' + @Words + ' ' + @M_POSTFIX
			END
		END

		IF @Paisa = 0 
		BEGIN
			SET @StringValue = 'Rupees' + @StringValue
		END
		ELSE
		BEGIN
			SELECT @Words = [dbo].[UDF_GetDigit2Word] (@Paisa)
			SET @StringValue = '(Rupees' + @StringValue + 'And ' + @Words + ' Paisa Only)'
		END
	END
    
	RETURN RTRIM(LTRIM(ISNULL(@StringValue,'')))
END
GO
