INSERT [dbo].[JobCreationDetails] ([JobCreationId], [JobId], [JobPostType], [JobName], [JobCategoryId], [EmploymentTypeId], [DepartmentId], [PrimarySkill], [SecondarySkill], [HiringLocationId], [HiringManagerId], [NoOfOpening], [OpeningDate], [ExpiryDate], [SalaryMinRange], [SalaryMaxRange], [MinExperience], [MaxExperience], [JobCreationStatusId], [JobCreationDescription], [JobCreationSkillSet], [CompanyId], [IsActive], [CreatedBy], [CreatedDate], [UpdatedBy], [UpdatedDate]) VALUES (19, N'JOB_9', N'Internal', N'Database Consultant', 2, 1, 3, N'Sql Server', N'MySQL', 1, 1, 5, CAST(N'2025-02-09' AS Date), CAST(N'2025-02-28' AS Date), CAST(714286.00 AS Numeric(11, 2)), CAST(2174603.00 AS Numeric(11, 2)), CAST(5.00 AS Numeric(4, 2)), CAST(12.00 AS Numeric(4, 2)), 1, N'<div><font size="2">As an SQL Developer, you will develop MS-SQL queries and procedures, create custom reports, and modify ERP user forms to enhance organizational productivity. You will also be responsible for designing databases and ensuring their stability, reliability, and performance.</font></div><div><font size="2"><br></font></div><div><font size="2"><b>Responsibilities</b></font></div><div><font size="2">Develop high-quality database solutions.</font></div><div><font size="2">Use T-SQL to develop and implement procedures and functions.</font></div><div><font size="2">Review and interpret ongoing business report requirements.</font></div><div><font size="2">Research required data.</font></div><div><font size="2">Build appropriate and useful reporting deliverables.</font></div><div><font size="2">Analyze existing SQL queries for performance improvements.</font></div><div><font size="2">Suggest new queries.</font></div><div><font size="2">Develop procedures and scripts for data migration.</font></div><div><font size="2">Provide timely scheduled management reporting.</font></div><div><font size="2">Investigate exceptions with regard to asset movements.</font></div><div><font size="2"><br></font></div><div><font size="2"><b>Requirements</b></font></div><div><font size="2">Degree in Computer Science, Engineering, or relevant degree.</font></div><div><font size="2">Proven years of experience as an SQL Developer or similar role.</font></div><div><font size="2">Excellent understanding of T-SQL programming and Microsoft SQL Server.</font></div><div><font size="2">Good knowledge of HTML and JavaScript.</font></div><div><font size="2">Experience with SQL Server Reporting Services, SQL Server Analysis Services, and Transparent Data Encryption (TDE).</font></div><div><font size="2">Familiarity with the practical application of NoSQL\NewSQL databases.</font></div><div><font size="2">Critical thinker and a team player.</font></div><div><font size="2">Good time-management skills and problem-solving skills.</font></div><div><font size="2">Great interpersonal and communication skills.</font></div><div><font size="2"><br></font></div><div><br></div>', N'<div style="font-size: 14px;"><ul><li><span style="font-size: small; text-align: var(--bs-body-text-align);">Testing</span></li><li><span style="font-size: small; text-align: var(--bs-body-text-align);">Coding</span></li><li><span style="font-size: small; text-align: var(--bs-body-text-align);"><b>SQL</b></span></li><li><span style="font-size: small; text-align: var(--bs-body-text-align);">Project Management</span></li><li><span style="font-size: small; text-align: var(--bs-body-text-align);">HTML</span></li><li><span style="font-size: small; text-align: var(--bs-body-text-align);">JavaScript</span></li></ul></div>', 1, 1, 1, CAST(N'2025-02-09T15:21:16.007' AS DateTime), 1, CAST(N'2025-02-09T15:58:36.073' AS DateTime))
GO
