/*=======================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetAssetEmployeeDetails]
 Description		:	Procedure used to retrieve the EmployeeDetails
												(When click on the EmployeeCompanyId DropDown in asset popup screen)
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	21-01-2025
 Version			:	1.0 
 Comment			:	1. Get the EmployeeDetails table have the columns of EmployeeName, Department, Desigination
							for the Given @EmployeeId.
						2. Then return the output parameter values @Status = 1 & @Message = NULL. 
==========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetAssetEmployeeDetails]
(
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		SELECT	DISTINCT EmployeeId
				,CONCAT(FirstName,' ',LastName) AS EmployeeName 
				,ISNULL(DepartmentName,'') AS Department
				,ISNULL(DesignationName,'') AS Designation
				,CONVERT(NVARCHAR(50),DateOfJoining,105) AS DateOfJoining
				,NoticePeriod
		FROM	[dbo].[EmployeeDetails] ED
		LEFT JOIN	[dbo].[DepartmentDetails] DD
			ON	ED.DepartmentId = DD.DepartmentId
		LEFT JOIN	[dbo].[DesignationDetails] DSD
			ON	ED.DesignationId = DSD.DesignationId
		LEFT JOIN	[dbo].[PayrollsettingDetails] PSD
			ON	ED.CompanyId = PSD.CompanyId
		WHERE	EmployeeId = @EmployeeId
		AND		ED.CompanyId = @CompanyId;

		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END 
/*========================================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [dbo].[USP_DD_GetAssetEmployeeDetails]	@LoginUserId	= 1
												,@EmployeeId	= 3
												,@Status		= @Status	OUT
												,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[ReportCategoryDetails] 

===========================================================================================================================================================*/
GO
