/*=======================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetEvaluatorDetails]
 Description		:	Procedure used to Get the Sub InterViewerDetails 
											(When click on the Evaluator Drop down in InterView Schedule screen)
 Input Parameter	:	@LoginUserId, @TVP_InterviewLevelMainInterviewerMappingDetails
						,@TVP_InterviewLevelSubInterviewerMappingDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	27-01-2025
 Version			:	1.0 
 Comment			:	1. Get the EmployeeDetails table have the columns of EvaluatorId, EvaluatorName
							for the Given @TVP_InterviewLevelMainInterviewerMappingDetails &
							@TVP_InterviewLevelSubInterviewerMappingDetails.
						2. Then return the output parameter values @Status = 1 & @Message = NULL. 
==========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetEvaluatorDetails]
(
	@LoginUserId										INT
	,@TVP_InterviewLevelMainInterviewerMappingDetails	TVP_InterviewLevelMainInterviewerMappingDetails		READONLY
	,@TVP_InterviewLevelSubInterviewerMappingDetails	TVP_InterviewLevelSubInterviewerMappingDetails		READONLY	
	,@Status											BIT													OUT
	,@Message											NVARCHAR(500)										OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		DROP TABLE IF EXISTS #EmployeeIdDetails;
		SELECT	*
		INTO	#EmployeeIdDetails
		FROM	(
					SELECT	DISTINCT MainInterviewerId AS EvaluatorId
					FROM	@TVP_InterviewLevelMainInterviewerMappingDetails
					UNION ALL
					SELECT	DISTINCT SubInterviewerId AS EvaluatorId
					FROM	@TVP_InterviewLevelSubInterviewerMappingDetails
				) AS A

		SELECT	EvaluatorId
				,CONCAT(FirstName, ' ', LastName) AS EvaluatorName
		FROM	#EmployeeIdDetails T1
		JOIN	[dbo].[EmployeeDetails] ED
			ON	T1.EvaluatorId = ED.EmployeeId;

		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END 
/*========================================================================================================================================================
	DECLARE	@Status												BIT
			,@Message											NVARCHAR(500)
			,@TVP_InterviewLevelMainInterviewerMappingDetails	TVP_InterviewLevelMainInterviewerMappingDetails
			,@TVP_InterviewLevelSubInterviewerMappingDetails	TVP_InterviewLevelSubInterviewerMappingDetails;

	INSERT INTO @TVP_InterviewLevelMainInterviewerMappingDetails (MainInterviewerId)
	VALUES		(1), (2), (4);
	
	INSERT INTO @TVP_InterviewLevelSubInterviewerMappingDetails (SubInterviewerId)
	VALUES		(5), (6);
		
	EXEC [dbo].[USP_DD_GetEvaluatorDetails]	@LoginUserId										= 1
											,@TVP_InterviewLevelMainInterviewerMappingDetails	= @TVP_InterviewLevelMainInterviewerMappingDetails
											,@TVP_InterviewLevelSubInterviewerMappingDetails	= @TVP_InterviewLevelSubInterviewerMappingDetails
											,@Status											= @Status	OUT
											,@Message											= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails] 

===========================================================================================================================================================*/
GO
