/*=======================================================================================================================================
 Procedure Name 	: [USP_DD_GetLeaveTypeDetails_ByEmployeeId]
 Description		: Procedure used to retrieve the LeaveTypeDetails (When click on the Employee DropDown in all screen popup)
 Input Parameter	: @LoginUserId, @EmployeeId
 Output Parameters	: @Status, @Message
 Author				: Prakash.P
 Created on			: 13-12-2024
 Version			: 1.0 
 Comment			: 1. Get the LeaveTypeDetails table have the Columns of @EmployeeId.
					  2. Then return the output parameter values @Status = 1 & @Message = NULL. 
==========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetLeaveTypeDetails_ByEmployeeId]
(
	@LoginUserId	INT
	,@ModuleName	NVARCHAR(50)
	,@EmployeeId	INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ModuleName = 'Leave'
		BEGIN 
			SELECT	LTGMD.LeaveTypeId
					,LeaveTypeName 
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
				ON	ED.GradeTypeId = LTGMD.GradeTypeId
			JOIN	[dbo].[LeaveTypeDetails] LTD
				ON	LTD.LeaveTypeId = LTGMD.LeaveTypeId
			WHERE	ED.EmployeeId = @EmployeeId
			AND		ED.CompanyId = @CompanyId
			AND		LTD.LeaveTypeId NOT IN (1, 2);
		END 
		ELSE IF @ModuleName = 'Permission'
		BEGIN 
			SELECT	LTGMD.LeaveTypeId
					,LeaveTypeName 
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
				ON	ED.GradeTypeId = LTGMD.GradeTypeId
			JOIN	[dbo].[LeaveTypeDetails] LTD
				ON	LTD.LeaveTypeId = LTGMD.LeaveTypeId
			WHERE	ED.EmployeeId = @EmployeeId
			AND		ED.CompanyId = @CompanyId
			AND		LTD.LeaveTypeId = 1;
		END
		ELSE IF @ModuleName = 'CompOff'
		BEGIN 
			SELECT	LTGMD.LeaveTypeId
					,LeaveTypeName 
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
				ON	ED.GradeTypeId = LTGMD.GradeTypeId
			JOIN	[dbo].[LeaveTypeDetails] LTD
				ON	LTD.LeaveTypeId = LTGMD.LeaveTypeId
			WHERE	ED.EmployeeId = @EmployeeId
			AND		ED.CompanyId = @CompanyId
			AND		LTD.LeaveTypeId = 2;
		END

		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END 
/*========================================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [USP_DD_GetLeaveTypeDetails_ByEmployeeId]	@LoginUserId	=	1
													,@ModuleName	=	'CompOff'
													,@EmployeeId	=	7
													,@Status		=	@Status		OUT
													,@Message		=	@Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[LeaveTypeDetails];
	SELECT	* 
	FROM	[dbo].[LeaveTypeGradeMappingDetails];
	SELECT	* 
	FROM	[dbo].[EmployeeDetails] 

===========================================================================================================================================================*/
GO
