					  and When Click On Edit Option On Grid from UI)
 Input Parameter	: @LoginUserId, @MasterInfoId, @ModuleName
 Output Parameters	: @Status, @Message
 Author				: Dharani.M
 Created on			: 25-07-2023
 Version			: 1.0 
 Comment			: 1.If the @MasterInfoId Is Null,
						    1.1  If the given ModuleName = 'Employee', then Get All the EmployeeDetails have the columns of 
											 EmployeeId			
											,EmployeeName		
							1.3 If the given ModuleName = 'Branch', then Get All the BranchDetails have the columns of 
											 BranchId			
											,BranchName		
						    1.4 If the given ModuleName = 'Designation', then Get All the DesignationDetails have the columns of 
											 DesignationId
											,DesignationName		
							1.5 If the given ModuleName = 'Department', then Get All the DepartmentDetails have the columns of 
											 DepartmentId				
											,DepartmentName		
							1.6 If the given ModuleName = 'ClaimType', then Get All the EmployeeDetails have the columns of 
											ClaimTypeId			
											,ClaimTypeName							
							1.7 If the given ModuleName = 'ReportingTo', then Get All the EmployeeDetails have the columns of 
											EmployeeId			
											,ReportingPersonId			
							1.8 If the given ModuleName = 'UserGroup', then Get All the UserGroupDetails have the columns of 
											 UserGroupId			
											,UserGroupName		
							1.9 If the given ModuleName = 'Gender', then Get All the GenderDetails have the columns of 
											 GenderId				
											,GenderName	
							1.10 If the given ModuleName = 'Religion', then Get All the ReligionDetails have the columns of 
											 ReligionId				
											,ReligionName												
							1.11 If the given ModuleName = 'MaritalStatus', then Get All the MaritalStatusDetails have the columns of 
											 MaritalStatusId		
											,MaritalStatusName	
							1.12 If the given ModuleName = 'Relation', then Get All the RelationDetails have the columns of 
											 RelationId		
											,RelationName
							1.13 If the given ModuleName = 'AccountType', then Get All the RelationDetails have the columns of 
											 AccountTypeId		
											,AccountTypeName
							1.14 If the given ModuleName = 'AttendanceStatus', then Get All the AttendanceStatusDetails have the columns of 
											 AttendanceStatusId			
											,AttendanceStatusName		
							1.15 If the given ModuleName = 'LeaveStatus', then Get all the LeaveStatusDetails have the columns of 
											 LeaveStatusId			
											,LeaveStatusName	
							1.16 If the given ModuleName = 'PermissionStatus', then Get all the PermissionStatusDetails have the columns of 
											 PermissionStatusId			
											,PermissionStatusName
							1.17 If the given ModuleName = 'CompensatoryStatus', then Get all the CompensatoryStatusDetails have the columns of 
											 CompensatoryStatusId			
											,CompensatoryStatusName
							1.18 If the given ModuleName = 'ClaimStatus', then Get all the ClaimStatusDetails have the columns of 
											 ClaimStatusId			
											,ClaimStatusName
							1.19 If the given ModuleName = 'LeaveType', then Get all the LeaveTypeDetails have the columns of 
											 LeaveTypeId			
											,LeaveTypeName
							1.20 If the given ModuleName = 'PayType', then Get all the LeaveTypeDetails have the columns of 
											 PayTypeId			
											,PayTypeName	
							1.21 If the given ModuleName = 'PaymentType', then Get all the LeaveTypeDetails have the columns of 
											 PaymentTypeId			
											,PaymentTypeName
					2. Then return the output parameter  values @Status = 1 & @Message = NULL. 
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetMasterInfoDetails]
(
	@LoginUserId	INT
	,@MasterInfoId	INT
	,@ModuleName	NVARCHAR(50)
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF @MasterInfoId IS NULL
		BEGIN
			--DropDown for Employee based on the LoginUser.
			IF @ModuleName = 'Employee'
			BEGIN
				SELECT	RPD.EmployeeId
						,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
				FROM	[dbo].[EmployeeDetails] ED
				LEFT JOIN	[dbo].[EmployeeDetails] RPD
					ON	ED.EmployeeId = RPD.ReportingPersonId
				WHERE	ED.EmployeeId = @LoginUserId
				AND		ED.CompanyId = @CompanyId
				ORDER BY EmployeeName;
			END 
			--DropDown for BranchDetails
			ELSE IF @ModuleName = 'Branch'
			BEGIN
				SELECT	BranchId			
						,concat(BranchName,', ',State) AS BranchName
				FROM	[dbo].[BranchDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY BranchName;
			END
			--DropDown for Designation
			ELSE IF @ModuleName = 'Designation'
			BEGIN
				SELECT	DesignationId
						,DesignationName
				FROM	[dbo].[DesignationDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY DesignationName;
			END 
			--DropDown for Department
			ELSE IF @ModuleName = 'Department'
			BEGIN
				SELECT	DepartmentId
						,DepartmentName
				FROM	[dbo].[DepartmentDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY DepartmentName;
			END
			--DropDown for ClaimType
			ELSE IF @ModuleName = 'ClaimType'
			BEGIN
				SELECT	 ClaimTypeId
						,ClaimTypeName
				FROM	[dbo].[ClaimTypeDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY ClaimTypeName;
			END
			--DropDown for ReportingTo
			--ELSE IF @ModuleName = 'ReportingTo'
			--BEGIN
			--	--SELECT	RPD.ReportingPersonId
			--	--		,CONCAT(ED.FirstName,' ' ,ED.LastName) AS ReportingPersonName
			--	--FROM	[dbo].[EmployeeDetails] ED
			--	--LEFT JOIN [dbo].[Employeedetails] RPD
			--	--	ON	RPD.EmployeeId = ED.ReportingPersonId
			--	--WHERE	ED.CompanyId = @CompanyId
			--	--ORDER BY ED.EmployeeId;
			--	SELECT	EmployeeId
			--			,CONCAT(FirstName,' ',LastName) AS EmployeeName
			--	FROM	[dbo].[EmployeeDetails] 
			--	WHERE	CompanyId = @CompanyId;
			--END
			--DropDown for UserGroup
			ELSE IF @ModuleName = 'UserGroup'
			BEGIN
				IF @UserGroupId IN (1, 2)
				BEGIN 
					SELECT	UserGroupId
							,UserGroupName
					FROM	[dbo].[UserGroupDetails] 
					--WHERE	CompanyId = @CompanyId
					ORDER BY UserGroupId;
				END 
				ELSE 
				BEGIN 
					SELECT	UserGroupId
							,UserGroupName
					FROM	[dbo].[UserGroupDetails] 
					WHERE	UserGroupName = 'GeneralUser'
					ORDER BY UserGroupId;
				END 
			END	

			--DropDown for Gender
			ELSE IF @ModuleName = 'Gender'
			BEGIN
				SELECT	GenderId
						,GenderName
				FROM	[dbo].[GenderDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY GenderId;
			END
			--DropDown for Religion
			ELSE IF @ModuleName = 'Religion'
			BEGIN
				SELECT	ReligionId
						,ReligionName
				FROM	[dbo].[ReligionDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY ReligionId;
			END

			--DropDown for MaritalStatus
			ELSE IF @ModuleName = 'MaritalStatus'
			BEGIN
				SELECT	MaritalStatusId
						,MaritalStatusName
				FROM	[dbo].[MaritalStatusDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY MaritalStatusId;
			END
			--DropDown for Relation
			ELSE IF @ModuleName = 'Relation'
			BEGIN
				SELECT	RelationId
						,RelationName
				FROM	[dbo].[RelationDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY RelationId;
			END
			--DropDown for Relation
			ELSE IF @ModuleName = 'AccountType'
			BEGIN
				SELECT	AccountTypeId
						,AccountTypeName
				FROM	[dbo].[AccountTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY AccountTypeId;
			END
			--DropDown for LeaveType DropDown To Fetch LeaveTypes In Leave Screen
			ELSE IF @ModuleName = 'LeaveType'
			BEGIN
				SELECT	LeaveTypeId
						,LeaveTypeName
				FROM	[dbo].[LeaveTypeDetails] 
				WHERE	CompanyId = 1
				AND		LeaveTypeId <> 1
				ORDER BY LeaveTypeId;
			END 
			--DropDown for LeaveType
			ELSE IF @ModuleName = 'PermissionType'
			BEGIN
				SELECT	LeaveTypeId AS PermissionTypeId
						,LeaveTypeName AS PermissionTypeName
				FROM	[dbo].[LeaveTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY LeaveTypeId;
			END 
			--DropDown for LeaveType
			ELSE IF @ModuleName = 'CompensatoryOffType'
			BEGIN
				SELECT	LeaveTypeId AS CompensatoryOffTypeId
						,LeaveTypeName AS CompensatoryOffTypeName
				FROM	[dbo].[LeaveTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY LeaveTypeId;
			END 
			--DropDown for PayType
			ELSE IF @ModuleName = 'PayType'
			BEGIN
				SELECT	PayTypeId
						,PayTypeName
				FROM	[dbo].[PayTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY PayTypeId DESC;
			END
			--DropDown for PaymentType
			ELSE IF @ModuleName = 'PaymentType'
			BEGIN
				SELECT	PaymentTypeId
						,PaymentTypeName
				FROM	[dbo].[PaymentTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY PaymentTypeId;
			END
			--DropDown for AttendanceStatus
			ELSE IF @ModuleName = 'AttendanceStatus'
			BEGIN
				SELECT	AttendanceStatusId
						,AttendanceStatusName
				FROM	[dbo].[AttendanceStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY AttendanceStatusId
			END
			--DropDown for LeaveStatus
			ELSE IF @ModuleName = 'LeaveStatus'
			BEGIN
				SELECT	LeaveStatusId AS StatusId
						,LeaveStatusName AS StatusName
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY StatusId;
			END  
			--DropDown for PermissionStatus
			ELSE IF @ModuleName = 'PermissionStatus'
			BEGIN
				SELECT	LeaveStatusId AS StatusId
						,LeaveStatusName AS StatusName
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY StatusId;
			END  
			--DropDown for PermissionStatus
			ELSE IF @ModuleName = 'CompensatoryOffStatus'
			BEGIN
				SELECT	LeaveStatusId AS StatusId
						,LeaveStatusName AS StatusName
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY StatusId;
			END 
			--DropDown for ClaimStatus
			ELSE IF @ModuleName = 'ClaimStatus'
			BEGIN
				SELECT	LeaveStatusId AS ClaimStatusId
						,LeaveStatusName AS ClaimStatusName
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY ClaimStatusId;
			END  
			--DropDown for LeaveStatus
			ELSE IF @ModuleName = 'AdvanceStatus'
			BEGIN
				SELECT	LeaveStatusId		AS StatusId 
						,LeaveStatusName	AS StatusName 
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY LeaveStatusId;
			END 
			--DropDown for LeaveStatus
			ELSE IF @ModuleName = 'LoanStatus'
			BEGIN
				SELECT	LeaveStatusId		AS StatusId 
						,LeaveStatusName	AS StatusName 
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY LeaveStatusId;
			END 
			--DropDown for OverTimeStatus
			ELSE IF @ModuleName = 'OverTimeStatus'
			BEGIN
				SELECT	LeaveStatusId		AS OverTimeStatusId 
						,LeaveStatusName	AS OverTimeStatusName 
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY LeaveStatusId;
			END 
			--DropDown for RegularizationStatus
			ELSE IF @ModuleName = 'RegularizationStatus'
			BEGIN
				SELECT	LeaveStatusId		AS StatusId 
						,LeaveStatusName	AS StatusName 
				FROM	[dbo].[LeaveStatusDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY LeaveStatusId;
			END 
			--DropDown for AttendanceMachine
			ELSE IF @ModuleName = 'AttendanceMachine'
			BEGIN
				SELECT	AttendanceMachineId		AS AttendanceMachineId 
						,AttendanceMachineName	AS AttendanceMachineName 
				FROM	[dbo].[AttendanceMachineDetails] 
				--WHERE	CompanyId = @CompanyId
				ORDER BY AttendanceMachineId;
			END 
			--DropDown for Shift
			ELSE IF @ModuleName = 'Shift'
			BEGIN
				SELECT	ShiftId	
						,ShiftName	
				FROM	[dbo].[ShiftDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY ShiftId;
			END 
				--DropDown for AttendanceMachine
			ELSE IF @ModuleName = 'Currency'
			BEGIN
				SELECT	CurrencyDetailsId		AS CurrencyId 
						,CurrencyName			AS CurrencyName 
				FROM	 [TetroAPPS].[dbo].[CurrencyDetails]
				ORDER BY CurrencyId;
			END 
			--DropDown for EmployeeTypeDetails
			ELSE IF @ModuleName = 'EmployeeType'
			BEGIN
				SELECT	EmployeeTypeId
						,EmployeeType
				FROM	[dbo].[EmployeeTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY EmployeeTypeId;
			END
			--DropDown for GradeType
			ELSE IF @ModuleName = 'GradeType'
			BEGIN
				SELECT	GradeTypeId
						,GradeTypeName
				FROM	[dbo].[GradeTypeDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY GradeTypeId;
			END
			--DropDown for GradeType
			ELSE IF @ModuleName = 'EmployeeStatus'
			BEGIN
				SELECT	EmployeeStatusId
						,EmployeeStatusName
				FROM	[dbo].[EmployeeStatusDetails] 
				WHERE	CompanyId = @CompanyId;
			END

			ELSE IF @ModuleName = 'EmployeeContributionRate'
			BEGIN
				SELECT	1 AS EmployeeContributionRateId
						,'12% of (Basic + DA + RA)' AS EmployeeContributionRateName
				UNION ALL
				SELECT	2 AS EmployeeContributionRateId
						,'Others' AS EmployeeContributionRateName
			END 
			ELSE IF @ModuleName = 'EmployerContributionRate'
			BEGIN
				SELECT	1 AS EmployerContributionRateId
						,'12% of (Basic + DA + RA)' AS EmployerContributionRateName
				UNION ALL
				SELECT  2 AS EmployerContributionRateId
						,'Others' AS EmployerContributionRateName
			END 
			ELSE IF @ModuleName = 'SalaryComponents'
			BEGIN
				SELECT	1 AS SalaryComponentTypeId
						,'Earnings' AS SalaryComponentsType
				UNION ALL
				SELECT	2 AS SalaryComponentTypeId
						,'Deduction' AS SalaryComponentsType
			END 
			ELSE IF @ModuleName = 'SalaryStructure'
			BEGIN
				SELECT	SalaryStructureId		AS SalaryStructureId 
						,SalaryStructureName	AS SalaryStructureName 
				FROM	[dbo].[SalaryStructureDetails] 
				ORDER BY SalaryStructureId;
			END 
			ELSE IF @ModuleName = 'PayrollApproval'
			BEGIN
				SELECT	1 AS PayrollApprovalId
						,'Regularization' AS PayrollApproval
				UNION ALL
				SELECT	2 AS PayrollApprovalId
						,'Leave' AS PayrollApproval
				UNION ALL
				SELECT	3 AS PayrollApprovalId
						,'Permission' AS PayrollApproval
				UNION ALL
				SELECT	4 AS PayrollApprovalId
						,'CompensatoryOff' AS PayrollApproval
				UNION ALL
				SELECT	5 AS PayrollApprovalId
						,'Claim' AS PayrollApproval
				UNION ALL
				SELECT	6 AS PayrollApprovalId
						,'Advance' AS PayrollApproval
				UNION ALL
				SELECT	7 AS PayrollApprovalId
						,'Loan' AS PayrollApproval
			END 

			-- HR Module Drop Downs.			
			ELSE IF @ModuleName = 'JobCategory'
			BEGIN
				SELECT	JobCategoryId
						,JobCategoryName 
				FROM	[dbo].[JobCategoryDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY JobCategoryId
			END 			
			ELSE IF @ModuleName = 'JobCreation'
			BEGIN
				SELECT	JobCreationId
						,JobName 
				FROM	[dbo].[JobCreationDetails]
				WHERE	CompanyId = @CompanyId
				AND		JobCreationStatusId = 1
				ORDER BY JobCreationId DESC;
			END 		
			ELSE IF @ModuleName = 'EmploymentType'
			BEGIN
				SELECT	EmployeeTypeId
						,EmployeeType 
				FROM	[dbo].[EmployeeTypeDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY EmployeeTypeId
			END 
			ELSE IF @ModuleName = 'HiringLocation'
			BEGIN
				SELECT	BranchId AS HiringLocationId
						,City 
				FROM	[dbo].[BranchDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY HiringLocationId
			END 
			ELSE IF @ModuleName = 'HiringManager'
			BEGIN
				SELECT	EmployeeId AS HiringManagerId
						,CONCAT(FirstName,' ',LastName) AS HiringManagerName 
				FROM	[dbo].[EmployeeDetails]
				WHERE	CompanyId = @CompanyId
				AND		ReportingPersonId IS NULL
				ORDER BY HiringManagerId
			END 
			ELSE IF @ModuleName = 'JobCreationStatus'
			BEGIN
				SELECT	JobStatusId 
						,JobStatusName 
				FROM	[dbo].[JobStatusDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY JobStatusId
			END 
			ELSE IF @ModuleName = 'InterviewType'
			BEGIN
				SELECT	1 AS InterviewTypeId 
						,'Face to Face' AS InterviewTypeName 
				UNION ALL 
				SELECT	2 AS InterviewTypeId 
						,'Virtual' AS InterviewTypeName 
			END 
			ELSE IF @ModuleName = 'MainInterviewer'
			BEGIN
				SELECT	EmployeeId AS MainInterviewerId
						,CONCAT(FirstName, ' ', LastName) AS MainInterviewerName
				FROM	[dbo].[EmployeeDetails]
				WHERE	CompanyId = @CompanyId;
			END 
			ELSE IF @ModuleName = 'InterviewLocation'
			BEGIN
				SELECT	BranchId AS InterviewLocationId
						,BranchName AS InterviewLocationName
				FROM	[dbo].[BranchDetails]
				WHERE	CompanyId = @CompanyId;
			END 
			ELSE IF @ModuleName = 'InterviewScheduleStatus'
			BEGIN
				SELECT	InterviewStatusId AS InterviewScheduleStatusId
						,InterviewStatusName
				FROM	[dbo].[InterviewStatusDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY InterviewStatusId
			END 
			ELSE IF @ModuleName = 'InterviewScheduleApproverStatus'
			BEGIN
				SELECT	InterviewStatusId AS InterviewScheduleStatusId
						,InterviewStatusName
				FROM	[dbo].[InterviewStatusDetails]
				WHERE	CompanyId = @CompanyId
				AND		InterviewStatusId IN (4, 5, 6)
				ORDER BY InterviewStatusId
			END 
			ELSE IF @ModuleName = 'AssignedTo'
			BEGIN
				SELECT	EmployeeId
						,EmployeeCompanyId
				FROM	[dbo].[EmployeeDetails]
				WHERE	CompanyId = @CompanyId;
			END 
			ELSE IF @ModuleName = 'AssetCondition'
			BEGIN
				SELECT	1 AS ConditionId
						,'New' AS Condition
				UNION ALL
				SELECT	2 AS ConditionId
						,'Old' AS Condition
			END 
			ELSE IF @ModuleName = 'ResignationType'
			BEGIN
				SELECT	ResignationTypeId
						,ResignationTypeName
				FROM	[dbo].[ResignationTypeDetails]
				WHERE	CompanyId = @CompanyId;
			END 
			ELSE IF @ModuleName = 'AssetType'
			BEGIN
				SELECT	AssetTypeId
						,AssetTypeName
				FROM	[dbo].[AssetTypeDetails]
				WHERE	CompanyId = @CompanyId;
			END  
			ELSE IF @ModuleName = 'HRApprover'
			BEGIN
				SELECT	DISTINCT EmployeeId AS ApproverId
						,CONCAT(FirstName, ' ', LastName) AS ApproverName
				FROM	[dbo].[EmployeeDetails] ED 
				WHERE	DepartmentId = 5
			END 
			ELSE IF @ModuleName = 'ReportingManager'
			BEGIN
				SELECT	DISTINCT RPD.EmployeeId AS ApproverId
						,CONCAT(RPD.FirstName, ' ', RPD.LastName) AS ApproverName
				FROM	[dbo].[EmployeeDetails] ED 
				JOIN [dbo].[EmployeeDetails] RPD
					ON	ED.ReportingPersonId = RPD.EmployeeId
				WHERE	ED.CompanyId = @CompanyId;
			END 
			ELSE IF @ModuleName = 'ApproverStatus'
			BEGIN
				SELECT	ResignationStatusId AS ApproverStatusId
						,ResignationStatusName AS ApproverStatusName
				FROM	[dbo].[ResignationStatusDetails]
				WHERE	CompanyId = @CompanyId
				AND		ResignationStatusId IN (3, 5)
			END 
			ELSE IF @ModuleName = 'ComponentAliasName'
			BEGIN
				SELECT	ComponentAliasNameId
						,ComponentAliasName
				FROM	[dbo].[ComponentAliasNameDetails]
				WHERE	CompanyId = @CompanyId
			END 
			ELSE IF @ModuleName = 'CalculationType'
			BEGIN
				SELECT	CalculationTypeId
						,CalculationTypeName
				FROM	[dbo].[CalculationTypeDetails]
				WHERE	CompanyId = @CompanyId
			END 
			ELSE IF @ModuleName = 'NotificationCategoryName'
			BEGIN
				SELECT	1 AS NotificationCategoryId
						,'Mail' AS NotificationCategoryName
				UNION ALL
				SELECT	2 AS NotificationCategoryId
						,'WhatsApp' AS NotificationCategoryName
				UNION ALL
				SELECT	3 AS NotificationCategoryId
						,'Notication' AS NotificationCategoryName
			END 
			ELSE IF @ModuleName = 'TotalDuration'
			BEGIN
				SELECT	'00:30' AS TotalDurationId 
						,'00:30' AS TotalDuration
				UNION ALL
				SELECT	'01:00' AS TotalDurationId 
						,'01:00' AS TotalDuration
				UNION ALL
				SELECT	'01:30' AS TotalDurationId 
						,'01:30' AS TotalDuration
				UNION ALL
				SELECT	'02:00' AS TotalDurationId 
						,'02:00' AS TotalDuration
			END 
		END
		SELECT	@Status   = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(100),ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END    
/*========================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [dbo].[USP_DD_GetMasterInfoDetails]	@LoginUserId	= 1
												,@MasterInfoId	= NULL
												,@ModuleName	= 'AssetType'
												,@Status		= @Status	OUT
												,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM EmployeeDetails

	UPDATE	EmployeeDetails
	SET		ReportingPersonId = 2
	WHERE	EmployeeId = 3
	SELECT * FROM AccountTypeDetails
	
	SELECT * FROM LeaveStatusDetails
======================================================================================================================*/
	
		
GO
/****** Object:  StoredProcedure [dbo].[USP_DD_GetMasterInfoDetails_ResignationStatus]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetMasterInfoDetails_ResignationStatus]
 Description		:	Procedure used to retrieve the MasterInfoDetails(When Click on Drop down in Resignation Module)
 Input Parameter	:	@LoginUserId, @ModuleName, @ModuleId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	28-01-2025
 Version			:	1.0 
 Comment			:	1. Get the Drop down values for the Given @ModuleName & @ModuleId.
						2. Then return the output parameter  values @Status = 1 & @Message = NULL. 
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetMasterInfoDetails_ResignationStatus]
(
	@LoginUserId	INT
	,@ModuleName	NVARCHAR(50)
	,@ModuleId		INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF @ModuleName = 'Resignation'
		BEGIN 
			SELECT	DISTINCT ResignationStatusId
					,ResignationStatusName 
			FROM	(
						SELECT	RD.ResignationStatusId 
								,ResignationStatusName 
						FROM	[dbo].[ResignationDetails] RD
						JOIN	[dbo].[ResignationStatusDetails] RSD
							ON	RD.ResignationStatusId = RSD.ResignationStatusId
						WHERE	RD.CompanyId = @CompanyId
						AND		ResignationId = @ModuleId
						UNION ALL
						SELECT	ResignationStatusId AS ApproverStatusId
								,ResignationStatusName AS ApproverStatusName
						FROM	[dbo].[ResignationStatusDetails]
						WHERE	CompanyId = @CompanyId
						AND		ResignationStatusId IN (1, 4)
					) AS A;
		END
		SELECT	@Status   = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(100),ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END    
/*========================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [USP_DD_GetMasterInfoDetails_ResignationStatus]	@LoginUserId	= 1
															,@ModuleName	= 'Resignation'
															,@ModuleId		= 22
															,@Status		= @Status	OUT
															,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM EmployeeDetails
	SELECT * FROM RegularizationDetails
	SELECT * FROM LoanDetails
======================================================================================================================*/
	
GO
