/*================================================================================================================================================
 Procedure Name 	:	[USP_DD_GetMasterInfoDetails_Status]
 Description		:	Procedure used to retrieve the MasterInfoDetails(When Click on Drop down in payroll Modules)
 Input Parameter	:	@LoginUserId, @MasterInfoId, @ModuleName
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	16-11-2024
 Version			:	1.0 
 Comment			:	1.
						2. Then return the output parameter  values @Status = 1 & @Message = NULL. 
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetMasterInfoDetails_Status]
(
	@LoginUserId	INT
	,@IsMine		BIT
	,@ModuleName	NVARCHAR(50)
	,@ModuleId		INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF @IsMine = 1
		BEGIN 
			IF @UserGroupId IN (1, 2, 3)
			BEGIN 
				IF @ModuleName = 'RegularizationStatus' 
				BEGIN
					SELECT	RegularizationStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[RegularizationDetails] RD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	RD.RegularizationStatusId = LSD.LeaveStatusId
					WHERE	RegularizationId = 13
					AND		RegularizationStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS RegularizationStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY RegularizationStatusId;
				END 
				ELSE IF @ModuleName = 'LeaveStatus' 
				BEGIN
					SELECT	LD.LeaveStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveDetails] LD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	LD.LeaveStatusId = LSD.LeaveStatusId
					WHERE	LeaveId = @ModuleId
					AND		LD.LeaveStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS LeaveStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY LeaveStatusId;
				END 
				ELSE IF @ModuleName = 'PermissionStatus' 
				BEGIN
					SELECT	PD.PermissionStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[PermissionDetails] PD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	PD.PermissionStatusId = LSD.LeaveStatusId
					WHERE	PermissionId = @ModuleId
					AND		PD.PermissionStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS PermissionStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY PermissionStatusId;
				END 
				ELSE IF @ModuleName = 'CompensatoryOffStatus' 
				BEGIN
					SELECT	COD.CompensatoryOffStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[CompensatoryOffDetails] COD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	COD.CompensatoryOffStatusId = LSD.LeaveStatusId
					WHERE	CompensatoryOffId = @ModuleId
					AND		COD.CompensatoryOffStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS CompensatoryOffStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY CompensatoryOffStatusId;
				END 
				ELSE IF @ModuleName = 'ClaimStatus' 
				BEGIN
					SELECT	CD.ClaimStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[ClaimDetails] CD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	CD.ClaimStatusId = LSD.LeaveStatusId
					WHERE	ClaimId = @ModuleId
					AND		CD.ClaimStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS ClaimStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY ClaimStatusId;
				END 
				ELSE IF @ModuleName = 'AdvanceStatus' 
				BEGIN
					SELECT	AD.AdvanceStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[AdvanceDetails] AD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	AD.AdvanceStatusId = LSD.LeaveStatusId
					WHERE	AdvanceId = @ModuleId
					AND		AD.AdvanceStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS AdvanceStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY AdvanceStatusId;
				END 
				ELSE IF @ModuleName = 'LoanStatus' 
				BEGIN
					SELECT	LD.LoanStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LoanDetails] LD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	LD.LoanStatusId = LSD.LeaveStatusId
					WHERE	LoanId = @ModuleId
					AND		LD.LoanStatusId IN (3, 4)
					UNION ALL 
					SELECT	LeaveStatusId AS AdvanceStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (2, 5)
					ORDER BY LoanStatusId;
				END 
			END 
		END 
		ELSE
		BEGIN 
			IF @UserGroupId IN (1, 2)
			BEGIN 
				IF @ModuleName = 'RegularizationStatus'
				BEGIN
					SELECT	RegularizationStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[RegularizationDetails] RD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	RD.RegularizationStatusId = LSD.LeaveStatusId
					WHERE	RegularizationId = @ModuleId
					AND		RegularizationStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS RegularizationStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY RegularizationStatusId;
				END 
				ELSE IF @ModuleName = 'LeaveStatus' 
				BEGIN
					SELECT	LD.LeaveStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveDetails] LD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	LD.LeaveStatusId = LSD.LeaveStatusId
					WHERE	LD.LeaveId = @ModuleId
					AND		LD.LeaveStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS LeaveStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY LeaveStatusId;
				END 
				ELSE IF @ModuleName = 'PermissionStatus' 
				BEGIN
					SELECT	PD.PermissionStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[PermissionDetails] PD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	PD.PermissionStatusId = LSD.LeaveStatusId
					WHERE	PD.PermissionId = @ModuleId
					AND		PD.PermissionStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS PermissionStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY PermissionStatusId;
				END 
				ELSE IF @ModuleName = 'CompensatoryOffStatus' 
				BEGIN
					SELECT	COD.CompensatoryOffStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[CompensatoryOffDetails] COD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	COD.CompensatoryOffStatusId = LSD.LeaveStatusId
					WHERE	COD.CompensatoryOffId = @ModuleId
					AND		COD.CompensatoryOffStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS CompensatoryOffStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY CompensatoryOffStatusId;
				END 
				ELSE IF @ModuleName = 'ClaimStatus' 
				BEGIN
					SELECT	CD.ClaimStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[ClaimDetails] CD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	CD.ClaimStatusId = LSD.LeaveStatusId
					WHERE	CD.ClaimId = @ModuleId
					AND		CD.ClaimStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS ClaimStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY ClaimStatusId;
				END 
				ELSE IF @ModuleName = 'AdvanceStatus' 
				BEGIN
					SELECT	AD.AdvanceStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[AdvanceDetails] AD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	AD.AdvanceStatusId = LSD.LeaveStatusId
					WHERE	AD.AdvanceId = @ModuleId
					AND		AD.AdvanceStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS AdvanceStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY AdvanceStatusId;
				END 
				ELSE IF @ModuleName = 'LoanStatus' 
				BEGIN
					SELECT	LD.LoanStatusId
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LoanDetails] LD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	LD.LoanStatusId = LSD.LeaveStatusId
					WHERE	LD.LoanId = @ModuleId
					AND		LD.LoanStatusId = 2
					UNION ALL 
					SELECT	LeaveStatusId AS LoanStatusId 
							,LeaveStatusName AS StatusName 
					FROM	[dbo].[LeaveStatusDetails] 
					WHERE	LeaveStatusId IN (3, 4)
					ORDER BY LoanStatusId;
				END 
			END 
			ELSE IF @UserGroupId = 3
			BEGIN 
				IF @ModuleName IN ('RegularizationStatus', 'LeaveStatus', 'PermissionStatus', 'CompensatoryOffStatus'
									,'ClaimStatus', 'AdvanceStatus', 'LoanStatus')
				BEGIN
					SELECT	LeaveStatusId		AS RegularizationStatusId 
							,LeaveStatusName	AS StatusName 
					FROM	[dbo].[LeaveStatusDetails]
					WHERE	LeaveStatusId IN (1, 2, 5)
					ORDER BY LeaveStatusId;
				END 
			END
		END 
		SELECT	@Status   = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(100),ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END    
/*========================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [USP_DD_GetMasterInfoDetails_Status]	@LoginUserId	= 3
												,@IsMine		= 0
												,@ModuleName	= 'LoanStatus'
												,@ModuleId		= 4
												,@Status		= @Status	OUT
												,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM EmployeeDetails
	SELECT * FROM RegularizationDetails
	SELECT * FROM LoanDetails
======================================================================================================================*/
	
GO
