/*============================================================================================================================  
 Procedure Name		:	[dbo].[USP_DD_GetMineMyTeamEmployeeDetails]
 Description		:	Procedure used to retrieve the Mine MyTeam EmployeeDetails
																			(When click on Employee Drop down in all screens)
 Input Parameter	:	@LoginUserId, @IsMine
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	06-12-2024
 Version			:	1.0 
 Comment			:	1. To get the the Employee Name in Employee Drop down in all screen.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.
============================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetMineMyTeamEmployeeDetails]
(	
	@LoginUserId	INT
	,@IsMine		INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @UserGroupId = 1 AND @IsMine = 1
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails]	
			WHERE	EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;
		END 
		ELSE IF @UserGroupId = 1 AND @IsMine = 0
		BEGIN 
			SELECT	RPD.EmployeeId
					,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN	[dbo].[EmployeeDetails] RPD
				ON	ED.EmployeeId = RPD.ReportingPersonId
			WHERE	ED.EmployeeId = @LoginUserId
			AND		ED.CompanyId = @CompanyId
			ORDER BY EmployeeName;
		END 
		ELSE IF @UserGroupId = 2 AND @IsMine = 1
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails]	
			WHERE	EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;
		END 
		ELSE IF @UserGroupId = 2 AND @IsMine = 0
		BEGIN 
			SELECT	RPD.EmployeeId
					,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN	[dbo].[EmployeeDetails] RPD
				ON	ED.EmployeeId = RPD.ReportingPersonId
			WHERE	ED.EmployeeId = @LoginUserId
			AND		ED.CompanyId = @CompanyId
			ORDER BY EmployeeName;
		END 
		ELSE IF @UserGroupId = 3 AND (@IsMine = 0 OR @IsMine = 1)
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails]	
			WHERE	EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;
		END 		
		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_DD_GetMineMyTeamEmployeeDetails]	@LoginUserId	= 7
														,@IsMine		= 1
														,@Status		= @S_Status	 OUT
														,@Message		= @M_Message OUT;
 
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[EmployeeDetails];
=================================================================================================================================================*/
GO
