/*================================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetPayrollPendingApprovalDetails_DropDown]
 Description		:	Procedure used to retrieve the ModuleName Drop Down Details
															(When click on the Drop down in Pending Approval screen)
 Input Parameter	:	@LoginUserId, @FromDate, @IsMine
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	14-02-2025
 Version			:	1.0 
 Comment			:	1.	Get the ModuleName drop down in Payroll Pending Approval screen in Payslip Module
							for the given @LoginUserId, @FromDate, @IsMine.						    
						2.	Then return the output parameter  values @Status = 1 & @Message = NULL. 
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetPayrollPendingApprovalDetails_DropDown]
(
	@LoginUserId	INT
	,@FromDate		DATE
	,@IsMine		BIT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId			TINYINT
			,@ToDate			DATE
			,@RequestCount		INT;

	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @IsMine = 1
		BEGIN 
			SELECT	1 AS PayrollApprovalId
					,CASE WHEN COUNT(RegularizationId) = 0 THEN CONCAT('Regularization', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Regularization', ' ', 'There are ',COUNT(RegularizationId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(RegularizationId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[RegularizationDetails] RD
			WHERE	RD.EmployeeId = @LoginUserId
			AND		RegularizationStatusId = 2
			AND		CONVERT(DATE, [Date]) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	2 AS PayrollApprovalId
					,CASE WHEN COUNT(LeaveId) = 0 THEN CONCAT('Leave', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Leave', ' ', 'There are ',COUNT(LeaveId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(LeaveId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[LeaveDetails]
			WHERE	EmployeeId = @LoginUserId
			AND		LeaveStatusId = 2
			AND		CONVERT(DATE, FromDate) BETWEEN @FromDate AND @ToDate
			UNION ALL		
			SELECT	3 AS PayrollApprovalId
					,CASE WHEN COUNT(PermissionId) = 0 THEN CONCAT('Permission', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Permission', ' ', 'There are ',COUNT(PermissionId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(PermissionId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[PermissionDetails]
			WHERE	EmployeeId = @LoginUserId
			AND		PermissionStatusId = 2
			AND		CONVERT(DATE, PermissionDate) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	4 AS PayrollApprovalId
					,CASE WHEN COUNT(CompensatoryOffId) = 0 THEN CONCAT('CompensatoryOff', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('CompensatoryOff', ' ', 'There are ',COUNT(CompensatoryOffId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(CompensatoryOffId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[CompensatoryOffDetails]
			WHERE	EmployeeId = @LoginUserId
			AND		CompensatoryOffStatusId = 2
			AND		CONVERT(DATE, CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	5 AS PayrollApprovalId
					,CASE WHEN COUNT(ClaimId) = 0 THEN CONCAT('Claim', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Claim', ' ', 'There are ',COUNT(ClaimId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(ClaimId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[ClaimDetails]
			WHERE	RequestedBy = @LoginUserId
			AND		ClaimStatusId = 2
			AND		CONVERT(DATE, ClaimDate) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	6 AS PayrollApprovalId
					,CASE WHEN COUNT(AdvanceId) = 0 THEN CONCAT('Advance', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Advance', ' ', 'There are ',COUNT(AdvanceId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(AdvanceId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[AdvanceDetails]
			WHERE	EmployeeId = @LoginUserId
			AND		AdvanceStatusId = 2
			AND		CONVERT(DATE, AdvanceDate) BETWEEN @FromDate AND @ToDate
			UNION ALL		 
			SELECT	7 AS PayrollApprovalId
					,CASE WHEN COUNT(LoanId) = 0 THEN CONCAT('Loan', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Loan', ' ', 'There are ',COUNT(LoanId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(LoanId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[LoanDetails]
			WHERE	EmployeeId = @LoginUserId
			AND		LoanStatusId = 2
			AND		CONVERT(DATE, LoanDate) BETWEEN @FromDate AND @ToDate; 
		END 
		ELSE 
		BEGIN 
			SELECT	1 AS PayrollApprovalId
					,CASE WHEN COUNT(RegularizationId) = 0 THEN CONCAT('Regularization', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Regularization', ' ', 'There are ',COUNT(RegularizationId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(RegularizationId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[RegularizationDetails] RD
			LEFT JOIN [dbo].[EmployeeDetails] ED
				ON	RD.EmployeeId = ED.EmployeeId	
			WHERE	ED.ReportingPersonId = @LoginUserId
			AND		RegularizationStatusId = 2
			AND		CONVERT(DATE, [Date]) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	2 AS PayrollApprovalId
					,CASE WHEN COUNT(LeaveId) = 0 THEN CONCAT('Leave', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Leave', ' ', 'There are ',COUNT(LeaveId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(LeaveId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	(	SELECT	EmployeeId,  LeaveId
						FROM	[dbo].[LeaveDetails] 
						WHERE	LeaveStatusId = 2
						AND		CONVERT(DATE, FromDate) BETWEEN @FromDate AND @ToDate
					) AS LD
			LEFT JOIN [dbo].[EmployeeDetails] ED 
				ON	LD.EmployeeId = ED.EmployeeId
			WHERE	ED.ReportingPersonId = @LoginUserId
			UNION ALL		
			SELECT	3 AS PayrollApprovalId
					,CASE WHEN COUNT(PermissionId) = 0 THEN CONCAT('Permission', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Permission', ' ', 'There are ',COUNT(PermissionId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(PermissionId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[PermissionDetails] PD 
			LEFT JOIN [dbo].[EmployeeDetails] ED
				ON	PD.EmployeeId = ED.EmployeeId
			WHERE	ED.ReportingPersonId = @LoginUserId
			AND 	PermissionStatusId = 2
			AND		CONVERT(DATE, PermissionDate) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	4 AS PayrollApprovalId
					,CASE WHEN COUNT(CompensatoryOffId) = 0 THEN CONCAT('CompensatoryOff', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('CompensatoryOff', ' ', 'There are ',COUNT(CompensatoryOffId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(CompensatoryOffId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	[dbo].[CompensatoryOffDetails] CD
			JOIN	[dbo].[EmployeeDetails] ED 
				ON	ED.EmployeeId = CD.EmployeeId
			WHERE	ED.ReportingPersonId = @LoginUserId
			AND 	CD.CompensatoryOffStatusId = 2
			AND		CONVERT(DATE, CD.CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
			UNION ALL
			SELECT	5 AS PayrollApprovalId
					,CASE WHEN COUNT(RequestedBy) = 0 THEN CONCAT('Claim', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Claim', ' ', 'There are ',COUNT(RequestedBy),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(RequestedBy) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	(	SELECT	RequestedBy, COUNT(ClaimId) AS [Count]
						FROM	[dbo].[ClaimDetails] 
						WHERE	ClaimStatusId = 2
						AND		CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate
						GROUP BY RequestedBy
					) AS CD
			LEFT JOIN [dbo].[EmployeeDetails] ED
				ON	ED.EmployeeId = CD.RequestedBy
			WHERE	ED.ReportingPersonId = @LoginUserId
			UNION ALL
			SELECT	6 AS PayrollApprovalId
					,CASE WHEN COUNT(CD.EmployeeId) = 0 THEN CONCAT('Advance', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Advance',' ', 'There are ',COUNT(CD.EmployeeId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(CD.EmployeeId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	(	SELECT	EmployeeId, COUNT(AdvanceId) AS [Count] 
						FROM	[dbo].[AdvanceDetails] 
						WHERE	AdvanceStatusId = 2
						AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate
						GROUP BY EmployeeId
					) AS CD
			LEFT JOIN	[dbo].[EmployeeDetails] ED
				ON	ED.EmployeeId = CD.EmployeeId
			WHERE	ED.ReportingPersonId = @LoginUserId
			UNION ALL		 
			SELECT	7 AS PayrollApprovalId
					,CASE WHEN COUNT(LD.EmployeeId) = 0 THEN CONCAT('Loan', ' ', 'There is no Pending Approval.')
						ELSE CONCAT('Loan', ' ', 'There are ',COUNT(LD.EmployeeId),' pending records')
					END AS PayrollApproval
					,CASE WHEN COUNT(LD.EmployeeId) <> 0 THEN 'Red' ELSE 'Green' END AS Status_Colour
			FROM	(	SELECT	EmployeeId, COUNT(LoanId) AS [Count]
						FROM	[dbo].[LoanDetails] 
						WHERE	LoanStatusId = 2
						AND		CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate
						GROUP BY EmployeeId
					) AS LD
			LEFT JOIN [dbo].[EmployeeDetails] ED
				ON	ED.EmployeeId = LD.EmployeeId
			WHERE	ED.ReportingPersonId = @LoginUserId;
		END	
		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC	[dbo].[USP_DD_GetPayrollPendingApprovalDetails_DropDown]	@LoginUserId	= 1
																		,@FromDate		= '2025-01-01'
																		,@IsMine		= 1
																		,@Status		= @S_Status	 OUT
																		,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM RegularizationDetails 
	SELECT * FROM EmployeeDetails 
	 ❅
=================================================================================================================================================*/
GO
