/*===========================================================================================================
 Procedure Name 	: [USP_DD_GetReportingPersonDetails]
 Description		: Procedure used to retrieve the ReportingPersonDetails
 Input Parameter	: @EmployeeId
 Output Parameters	: @Status, @Message
 Author				: Dharani.M
 Created on			: 09-12-2023
 Version			: 1.0 
 Comment			: 1.If the @EmployeeId Is Null,
						    1.1 Get All the EmployeeDetails have the columns of EmployeeId,EmployeeName	
					  2.If the @EmployeeId Is NOT Null,
							2.2 Get the Particular EmployeeDetails have the columns of EmployeeId,EmployeeName	
					  3.Then return the output parameter  values @Status = 1 & @Message = NULL. 
=============================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetReportingPersonDetails]
(
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--If the @EmployeeId Is Null,
		IF @EmployeeId IS NULL
		BEGIN
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] 
			--WHERE	CompanyId = @CompanyId 
			ORDER BY EmployeeId;
		END
		ELSE
		BEGIN
			--If the @EmployeeId Is NOTNULL,
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] 
			WHERE	--CompanyId = @CompanyId 
					EmployeeId <> @EmployeeId
			ORDER BY EmployeeId;
 		END
		SELECT	 @Status   = 1 
				,@Message  = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*==================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_DD_GetReportingPersonDetails]	@LoginUserId	= 7
													,@EmployeeId	= NULL
													,@Status		= @Status   OUT
													,@Message		= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM [dbo].[EmployeeDetails]
=================================================================================================================*/
GO
