/*=============================================================================================================================================================
 Procedure Name 	: [USP_DD_GetReportValueDetails]
 Description		: Procedure used to retrive the ReportValueDetails (When click on the ReportValueInfo DropDown On Grid from UI)
 Input Parameter	: @LoginUserId, @ReportCategoryName
 Output Parameters	: @Status, @Message
 Author				: Prakash.P
 Created on			: 25-07-2023
 Version			: 1.0 
 Comment			: 1.If the @ReportCategoryName = 'Employee', then get the EmployeeDetails have the columns of 
									EmployeeId			AS ReportValueId
									,EmployeeName		AS ReportValueName
					  2.If the @ReportCategoryName = 'Designation', then get the DesignationDetails have the columns of 
									LeaveTypeId			AS ReportValueId
									,LeaveTypeName		AS ReportValueName
					  3.If the @ReportCategoryName = 'Branch', then get the BranchDetails have the columns of 
									LeaveStatusId		AS ReportValueId
									,LeaveStatusName	AS ReportValueName
					  4.If the @ReportCategoryName = 'Department', then get the DepartmentDetails have the columns of 
									LeaveStatusId		AS ReportValueId
									,LeaveStatusName	AS ReportValueName
					  5.If the @ReportCategoryName = 'UserGroup', then get the UserGroupDetails have the columns of 
									LeaveStatusId		AS ReportValueId
									,LeaveStatusName	AS ReportValueName
					  6.If the @ReportCategoryName = 'LeaveType', then get the LeaveTypeDetails have the columns of 
									PayslipId			AS ReportValueId
									,[Year]				AS ReportValueName
					  7.If the @ReportCategoryName IN ('LeaveStatus','PermissionStatus','CompensatoryOffStatus'), then get the LeaveStatusDetails have the columns of 
									LeaveStatusId		AS ReportValueId
									,LeaveStatusName	AS ReportValueName
					  8.If the @ReportCategoryName = 'Month', then get the PayslipDetails have the columns of 
									PayslipId			AS ReportValueId
									,[Year]				AS ReportValueName
					  9. If the @ReportCategoryName IN ('AdvanceStatus','LoanStatus'), then get the LeaveStatusDetails have the columns of 
									LeaveStatusId		AS ReportValueId
									,LeaveStatusName	AS ReportValueName
					  10. Then return the output parameter values @Status = 1 & @Message = NULL.		
============================================================================================================================================*/
CREATE    PROCEDURE [dbo].[USP_DD_GetReportValueDetails]
(
	@LoginUserId			INT
	,@ReportCategoryName	NVARCHAR(100)
	,@Status				BIT				OUT
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId 
			,@userGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId

	BEGIN TRY 
		BEGIN
			IF @ReportCategoryName = 'Summarize'
			BEGIN 
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'EmployeeCount'
			BEGIN
				SELECT	'0' AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'Branch'
			BEGIN
				SELECT	BranchId	AS ReportValueId 
						,BranchName AS ReportValueName
				FROM	[dbo].[BranchDetails]
				WHERE	CompanyId =  @CompanyId  
				UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'Gender'
			BEGIN
				SELECT	GenderId	AS ReportValueId 
						,GenderName AS ReportValueName
				FROM	[dbo].[GenderDetails]
				WHERE	CompanyId =  @CompanyId  
				UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'MaritalStatus'
			BEGIN
				SELECT	MaritalStatusId	AS ReportValueId 
						,MaritalStatusName AS ReportValueName
				FROM	[dbo].[MaritalStatusDetails]
				WHERE	CompanyId =  @CompanyId  
				UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'Department'
			BEGIN
				SELECT	DepartmentId	AS ReportValueId 
						,DepartmentName AS ReportValueName
				FROM	[dbo].[DepartmentDetails]
				WHERE	CompanyId =  @CompanyId  
				UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'Designation'
			BEGIN
				SELECT	DesignationId AS ReportValueId 
						,DesignationName AS ReportValueName
				FROM	[dbo].[DesignationDetails]
				WHERE	CompanyId =  @CompanyId 
			UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'ReportingTo'
			BEGIN
				SELECT	ED.EmployeeId	AS ReportValueId 
						,CONCAT(FirstName,' ',LastName) AS ReportValueName
				FROM	[dbo].[EmployeeDetails]	ED
				WHERE	CompanyId =  @CompanyId  
				UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'UserGroup'
			BEGIN
				SELECT	UserGroupId AS ReportValueId 
						,UserGroupName AS ReportValueName
				FROM	[dbo].[UserGroupDetails]
				WHERE	CompanyId =  @CompanyId 
			UNION 
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'EmployeeType'
			BEGIN
				SELECT	EmployeeTypeId AS ReportValueId 
						,EmployeeType AS ReportValueName
				FROM	[dbo].[EmployeeTypeDetails]
				WHERE	CompanyId =  @CompanyId 
			UNION 
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'EmployeeStatus'
			BEGIN
				SELECT	EmployeeStatusId AS ReportValueId 
						,EmployeeStatusName AS ReportValueName
				FROM	[dbo].[EmployeeStatusDetails]
				WHERE	CompanyId =  @CompanyId 
			UNION 
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'Status'
			BEGIN
				SELECT	1 AS ReportValueId
						,'Leave' AS ReportValueName
				UNION ALL
				SELECT	2 AS ReportValueId
						,'Permission' AS ReportValueName
				UNION ALL
				SELECT	3 AS ReportValueId
						,'CompOff' AS ReportValueName
				UNION ALL
				SELECT	4 AS ReportValueId
						,'Overtime' AS ReportValueName
				UNION ALL
				SELECT	5 AS ReportValueId
						,'Halfday' AS ReportValueName
				UNION ALL
				SELECT	6 AS ReportValueId
						,'Present' AS ReportValueName
				UNION ALL
				SELECT	7 AS ReportValueId
						,'Absent' AS ReportValueName
				UNION ALL
				SELECT	8 AS ReportValueId
						,'LateCheckIn' AS ReportValueName
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
				ORDER BY ReportValueId
			END
			ELSE IF @ReportCategoryName IN ('PunchType')
			BEGIN
				SELECT	1  AS ReportValueId 
						,'CheckIn' AS ReportValueName 
				UNION ALL
				SELECT	2  AS ReportValueId 
						,'CheckOut' AS ReportValueName 
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
				ORDER BY ReportValueId
			END
			ELSE IF @ReportCategoryName IN ('LeaveType')
			BEGIN
				SELECT	LeaveTypeId AS ReportValueId 
						,LeaveTypeName AS ReportValueName
				FROM	[dbo].[LeaveTypeDetails]
				WHERE	CompanyId =  @CompanyId 
			UNION ALL
				SELECT	6 AS ReportValueId
						,'Planned' AS ReportValueName
			UNION ALL
				SELECT	7 AS ReportValueId
						,'UnPlanned' AS ReportValueName
			UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName IN ('LeaveStatus', 'PermissionStatus', 'CompOffStatus','RegularizationStatus'
											,'ClaimStatus')
			BEGIN
				SELECT	LeaveStatusId AS ReportValueId
						,LeaveStatusName AS ReportValueName
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	CompanyId = @CompanyId 
			UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'PermissionType'
			BEGIN
				SELECT	1 AS ReportValueId
						,'Planned' AS ReportValueName
				UNION ALL
				SELECT	2 AS ReportValueId
						,'Unplanned' AS ReportValueName 
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
				ORDER BY ReportValueId
			END 
			ELSE IF @ReportCategoryName = 'ClaimType'
			BEGIN
				SELECT	ClaimTypeId AS ReportValueId
						,ClaimTypeName AS ReportValueName
				FROM	[dbo].[ClaimTypeDetails] PD
				WHERE	CompanyId = @CompanyId
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'ClaimType'
			BEGIN
				SELECT	ClaimTypeId AS ReportValueId
						,ClaimTypeName AS ReportValueName
				FROM	[dbo].[ClaimTypeDetails] PD
				WHERE	CompanyId = @CompanyId
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName IN ('AdvanceStatus','LoanStatus')
			BEGIN
				SELECT	LeaveStatusId AS ReportValueId
						,LeaveStatusName AS ReportValueName
				FROM	[dbo].[LeaveStatusDetails] PD
				WHERE	CompanyId = @CompanyId
			UNION
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
			END
			ELSE IF @ReportCategoryName = 'PayslipStatus'
			BEGIN
				SELECT	1 AS ReportValueId
						,'Processed' AS ReportValueName 
				UNION ALL
				SELECT	2 AS ReportValueId
						,'Not-Processed' AS ReportValueName 
				UNION ALL
				SELECT	0 AS ReportValueId
						,'All' AS ReportValueName
				ORDER BY ReportValueId
			END
		END
		SELECT	@Status = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END
/*=====================================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXEC [USP_DD_GetReportValueDetails]	@LoginUserId			= 1
										,@ReportCategoryName	= 'RegularizationStatus' 
										,@Status				= @Status		OUT
										,@Message				= @Message		OUT

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM ReportCategoryDetails

	SELECT * FRROM 
========================================================================================================================================================*/






GO
