/*=======================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetResignationApproverDetails]
 Description		:	Procedure used to retrieve the EmployeeDetails
										(When click on the Approver DropDown in esignationApprover popup screen)
 Input Parameter	:	@LoginUserId, @ModuleName
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-01-2025
 Version			:	1.0 
 Comment			:	1. Get the EmployeeDetails table have the columns of ApproverId, ApproverName for the 
							Given @EmployeeId.
						2. Then return the output parameter values @Status = 1 & @Message = NULL. 
==========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DD_GetResignationApproverDetails]
(
	@LoginUserId	INT
	,@ModuleName	NVARCHAR(100)
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ModuleName = 'First Level Approval (RM)'
		BEGIN 
			SELECT	RPD.EmployeeId
					,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN	[dbo].[EmployeeDetails] RPD
				ON	ED.ReportingPersonId = RPD.EmployeeId
			WHERE	ED.EmployeeId = @LoginUserId
			AND		ED.CompanyId = @CompanyId
			ORDER BY EmployeeName;
		END 
		ELSE IF @ModuleName = 'Second Level Approval (HR)'
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[DepartmentDetails] DD
				ON	DD.DepartmentId = ED.DepartmentId
			WHERE	DepartmentName LIKE '%HR%'
			ORDER BY EmployeeName;
		END 
		ELSE IF @ModuleName = 'Team'
		BEGIN 
			SELECT	RPD.EmployeeId
					,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN	[dbo].[EmployeeDetails] RPD
				ON	ED.ReportingPersonId = RPD.EmployeeId
			WHERE	ED.EmployeeId = @LoginUserId
			AND		ED.CompanyId = @CompanyId
			ORDER BY EmployeeName;
		END 
		ELSE IF @ModuleName = 'Admin'
		BEGIN 
			SELECT	RPD.EmployeeId
					,CONCAT(RPD.FirstName,' ',RPD.LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN	[dbo].[EmployeeDetails] RPD
				ON	ED.ReportingPersonId = RPD.EmployeeId
			WHERE	ED.EmployeeId = @LoginUserId
			AND		ED.CompanyId = @CompanyId
			ORDER BY EmployeeName;
		END 
		ELSE IF @ModuleName = 'Finance'
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[DepartmentDetails] DD
				ON	DD.DepartmentId = ED.DepartmentId
			WHERE	DepartmentName LIKE '%Finance%'
			ORDER BY EmployeeName;
		END 
		ELSE IF @ModuleName = 'HRApproval'
		BEGIN 
			SELECT	EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[DepartmentDetails] DD
				ON	DD.DepartmentId = ED.DepartmentId
			WHERE	DepartmentName LIKE '%HR%'
			ORDER BY EmployeeName;
		END 
		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END 
/*========================================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [dbo].[USP_DD_GetResignationApproverDetails]	@LoginUserId	= 5
														,@ModuleName	= 'HRApproval'
														,@Status		= @Status	OUT
														,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[ResignationLevelDetails] 

===========================================================================================================================================================*/

GO
