/*=======================================================================================================================================
 Procedure Name 	:	[dbo].[USP_DD_GetSubInterviewerDetails]
 Description		:	Procedure used to Get the Sub InterViewerDetails 
											(When click on the Main Interviewer Drop down in InterView Schedule screen)
 Input Parameter	:	@LoginUserId, @TVP_InterviewLevelMainInterviewerMappingDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	21-01-2025
 Version			:	1.0 
 Comment			:	1. Get the EmployeeDetails table have the columns of EmployeeName, Department, Desigination
							for the Given @EmployeeId.
						2. Then return the output parameter values @Status = 1 & @Message = NULL. 
==========================================================================================================================================*/
CREATE    PROCEDURE [dbo].[USP_DD_GetSubInterviewerDetails]
(
	@LoginUserId										INT
	,@TVP_InterviewLevelMainInterviewerMappingDetails	TVP_InterviewLevelMainInterviewerMappingDetails		READONLY
	,@Status											BIT													OUT
	,@Message											NVARCHAR(500)										OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		SELECT	EmployeeId AS SubInterviewerId
				,CONCAT(FirstName, ' ', LastName) AS SubInterviewerName
		FROM	[dbo].[EmployeeDetails] 
		EXCEPT
		SELECT	MainInterviewerId AS SubInterviewerId
				,CONCAT(FirstName, ' ', LastName) AS SubInterviewerName
		FROM	[dbo].[EmployeeDetails] ED
		LEFT JOIN @TVP_InterviewLevelMainInterviewerMappingDetails T2
			ON	ED.EmployeeId = T2.MainInterviewerId;
		
		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END 
/*========================================================================================================================================================
	DECLARE	@Status												BIT
