/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_DeleteAttendanceMachineDetails]
 Description		:	Procedure is used to delete the given AttendanceMachine (When click on delete button in AttendanceMachine Grid)
 Input Parameter	:	@LoginUserId, @AttendanceMachineId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	15-06-2024
 Version			:	1.0 
 Comment			:	1. Delete the AttendanceMachineDetails for the Given @AttendanceMachineId.
						2. Through the Success POPUP Message as " Record Deleted Successfully.".
===========================================================================================================================================================  */
CREATE   PROCEDURE [dbo].[USP_DeleteAttendanceMachineDetails]
(	
	@LoginUserId			INT
	,@AttendanceMachineId	INT
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId INT;

	-- Declare the Variables.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF NOT EXISTS (SELECT 1 FROM [dbo].[AttendanceMachineDetails] WHERE AttendanceMachineId = @AttendanceMachineId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0
					,@Message   = 'Given AttendanceMachine is Not Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN
				SELECT	DISTINCT CONCAT('TetroPAY/',ED.CompanyId, '/',EDME.EmployeeId) AS EmployeeId 
						,SerialNo 
				FROM	[dbo].[EmployeeDeviceMappingDetails] EDME
				JOIN	[dbo].[AttendanceMachineDetails] AM
					ON	EDME.AttendanceMachineId = AM.AttendanceMachineId
				JOIN  [dbo].[EmployeeDetails] ED
					ON	ED.CompanyId = @CompanyId
				WHERE	EDME.AttendanceMachineId = @AttendanceMachineId 
				AND		EDME.IsActive = 1;

				-- Result set for ESSL Application Credential.
				SELECT	ESSLUserName
						,ESSLPassword
						,WebAddress
				FROM	[dbo].[ESSlCredentialDetails]
				WHERE	CompanyId = @CompanyId;

				DELETE 
				FROM	[dbo].[EmployeeDeviceMappingDetails]
				WHERE	AttendanceMachineId = @AttendanceMachineId;

				DELETE 
				FROM	[dbo].[AttendanceMachineDetails] 
				WHERE	AttendanceMachineId = @AttendanceMachineId 
				AND		CompanyId = @CompanyId;

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status		= 1
					,@Message	= 'Record Deleted Successfully.';
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END
/*====================================================================================================================================================================
	DECLARE  @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_DeleteAttendanceMachineDetails]	@LoginUserId			= 1
													,@AttendanceMachineId	= 16
													,@Status				= @S_Status		OUT
													,@Message				= @M_Message	OUT;

	SELECT @S_Status AS 'STATUS', @M_Message  AS 'MESSAGE';		

	SELECT	* 
	FROM	[dbo].[AttendanceMachineDetails];
=====================================================================================================================================================================*/
GO
