CREATE     PROCEDURE [dbo].[USP_DeleteBranchDetails]
(
	@LoginUserId	INT
	,@BranchId		TINYINT
	,@status		BIT				OUT
	,@Message		NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE  @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
