		END
		ELSE 
		BEGIN TRAN 
			--If the given BranchDetails is exist,then delete the BranchDetails.	
			DELETE 
			FROM	[dbo].[BranchDetails] 
			WHERE	(BranchId = @BranchId)
			AND		(CompanyId = @CompanyId);

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Record Deleted Successfully';  
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
