/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_DeleteCandidateDetails]
 Description		:	Procedure used to Delete the CandidateDetails 
																	(When Click on Delete Button in Candidate Grid)
 Input Parameter	:	@LoginUserId, @CandidateId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. Logic to delete the CandidateDetails table for the Given @CandidateId.
						2. Then through the success message as @Status = 1 & 
								@Message = 'CandidateDetails are deleted Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DeleteCandidateDetails]
(
	@LoginUserId		INT		
	,@CandidateId		INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY		
		BEGIN TRAN 
			--Retrive the Attachment file details for the given claimid.	
			SELECT  AD.AttachmentId
					,AD.ModuleRefId
					,AttachmentFilepath
					,AttachmentFileName
					--,CASE	WHEN AttachmentFileName IS NOT NULL THEN CONCAT(AttachmentFilepath,  '/', AttachmentFileName) END AS AttachmentDeletePath
					--,CASE	WHEN DucumentFileName IS NOT NULL THEN CONCAT(DucumentFileName,  '/', DucumentFilePath) END AS DucumentFilePath
			FROM	[dbo].[AttachmentDetails] AD
			LEFT JOIN [dbo].[CandidateDocumentMappingDetails] CDMD
				ON	AD.ModuleRefId = CDMD.CandidateId
			WHERE	ModuleRefId = @CandidateId;

			DELETE 
			FROM	[dbo].[CandidateDocumentMappingDetails]
			WHERE	CandidateId = @CandidateId;

			DELETE 
			FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails]
			WHERE	CandidateId = @CandidateId;

			DELETE 
			FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails]
			WHERE	CandidateId = @CandidateId;

			DELETE 
			FROM	[dbo].[InterviewScheduleCandidateDetails]
			WHERE	CandidateId = @CandidateId;

			DELETE 
			FROM	[dbo].[CandidateDetails]
			WHERE	CandidateId = @CandidateId
			AND		CompanyId = @CompanyId;

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'CandidateDetails are deleted Successfully.'; 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_DeleteCandidateDetails]	@LoginUserId	= 1
											,@CandidateId	= 7
											,@Status		= @S_Status		OUT
											,@Message		= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT	*
	FROM	[dbo].[CandidateDetails];
======================================================================================================================================*/
GO
