/*====================================================================================================================  
 Procedure Name		:	[USP_DeleteClaimDetails]
 Description		:	Procedure is used to delete given ClaimId(When Click on Delete Button in grid on Claim page)
 Input Parameter	:	@LoginUserId,@ClaimId
 Output Parameters	:	@Status,@Message
 Author				:	Dharani.M
 Created on			:	01-11-2023
 Version			:	1.0 
 Comment			:	1.If the given @ClaimId is not exists,then
							1.1 Through the error POPUP Message as "Given ClaimId is not Exist".
						2.If the given @ClaimId is exists,then Delete the Given ClaimId in ClaimDetails Table and also
						  Delete the Claim Attachment in AttachmentDetails Table,then
							2.1 Through the Success POPUP Message as "Given ClaimId is deleted sucessfully".
=====================================================================================================================*/
CREATE    PROCEDURE [dbo].[USP_DeleteClaimDetails]
(	
	@LoginUserId			INT
	,@ClaimId				INT
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@AttachmentId	INT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	  
		--If the given ExpenseIdId is not exists,then through the error POPUP Message as "Given ClaimId is not Exist".
		IF NOT EXISTS( SELECT 1 FROM [dbo].[ClaimDetails] WHERE ClaimId = @ClaimId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Entered ClaimId is Not Exists';
			RETURN;
		END
		ELSE
		BEGIN TRAN

			SELECT	@Status   = 1
				,@Message = 'Record Deleted Successfully';	
				
			--Retrive the Attachment file details for the given claimid.	
			SELECT  AD.AttachmentId
					,AD.ModuleRefId
					,AttachmentFilepath
					,AttachmentFileName
					,CASE	WHEN AttachmentFileName IS NOT NULL THEN CONCAT(AttachmentFilepath,  '/', AttachmentFileName) END AS AttachmentDeletePath
			FROM	[dbo].[AttachmentDetails] AD
			WHERE	ModuleName = 'Claim' 
			AND		ModuleRefId = @ClaimId
			--AND		CompanyId = @CompanyId;		

			--If the given ModuleRefId is exist,then delete the ClaimId.
			DELETE
			FROM	[dbo].[AttachmentDetails]
			WHERE	ModuleName	= 'Claim'
			AND		ModuleRefId = @ClaimId
			--AND		CompanyId = @CompanyId;
			
			--If the given ClaimId is exist,then delete the ClaimId.	
			DELETE 
			FROM	[dbo].[ClaimDetails] 
			WHERE	ClaimId		= @ClaimId
			AND		CompanyId	= @CompanyId;

		IF @@TRANCOUNT >= 0
		COMMIT TRAN		

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE  @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_DeleteClaimDetails]	@LoginUserId	= 1
										,@ClaimId		= 5
										,@Status		= @S_Status		OUT
										,@Message		= @M_Message	OUT;

	SELECT @S_Status AS 'STATUS', @M_Message  AS 'MESSAGE';		

	SELECT	* 
	FROM	[dbo].[ClaimDetails];	 
	SELECT	* 
	FROM	[dbo].[AttachmentDetails];	 
=================================================================================================================================*/
GO
