/*========================================================================================================================
 Procedure Name	    :   [USP_DeleteEmployeeDetails]
 Description		:	Procedure used to Delete The EmployeeDetails(When Click on Delete Button on grid in landing page)
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	14-08-2023
 Version			:	1.0 
Comment			:		1. If the given EmployeeId is not exists,then return error as @Status = 0 
							and @Message = "Given EmployeeId is not Exist".
						2. If exists,then delete the EmployeeDetails table for the given EmployeeId and return Success
							Message as @Status = 1 and @Message ="Given EmployeeId is deleted sucessfully".
==========================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_DeleteEmployeeDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[DBO].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;      

	SELECT	EmployeeImage 
	FROM	[dbo].[EmployeeDetails] 
	WHERE	EmployeeId	= @EmployeeId 
	AND		CompanyId	= @CompanyId;

	SELECT	CONCAT('TetroPAY/',ED.CompanyId, '/',ED.EmployeeId) AS EmployeeId
			,SerialNo
	FROM	[dbo].[EmployeeDeviceMappingDetails] EDMD
	JOIN	[dbo].[AttendanceMachineDetails] AMD
		ON	EDMD.AttendanceMachineId = AMD.AttendanceMachineId
	JOIN	[dbo].[EmployeeDetails] ED 
		ON	ED.EmployeeId = EDMD.EmployeeId
	WHERE	EDMD.EmployeeId = @EmployeeId
	AND		ED.CompanyId = @CompanyId;

	SELECT	ESSLUserName
			,ESSLPassword
			,WebAddress
	FROM	[dbo].[ESSLCredentialDetails]
	WHERE	CompanyId = @CompanyId;	
				         
	BEGIN TRY		  
		--If the given EmployeeId is not exists,then through the error message as 'Given EmployeeId is not Exists'
		IF NOT EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0 
					,@Message	= 'Given EmployeeId is not Exists';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN
				--Delete the EmployeeShiftMappingDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[EmployeeShiftMappingDetails]
				WHERE	EmployeeId = @EmployeeId;
				
				--Delete the OverTimeDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[OverTimeDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the AdvanceDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[AdvanceDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the LoanDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[LoanDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the CompensatoryOffDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[CompensatoryOffDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the PermissionDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[PermissionDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the LeaveDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[LeaveDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the AttendanceLogDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[AttendanceLogDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;
								
				--Delete the RegularizationDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[RegularizationDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				--Delete the PayslipDetails for the given @EmployeeId.	
				DELETE
				FROM	[dbo].[PayslipDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		CompanyId = @CompanyId;

				DELETE 
				FROM	[dbo].[EmployeePersonalDetails]
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);

				--Delete the EmployeeFamilyMemberDetails for the given EmployeeId
				DELETE
				FROM	[dbo].[EmployeeFamilyMemberDetails]
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);

				--Delete the EmployeeEducationDetails for the given EmployeeId
				DELETE
				FROM	[dbo].[EmployeeEducationDetails]
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);

				--Delete the EmployeeExperienceDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeeExperienceDetails] 
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);			

				--Delete the EmployeeBankDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeeBankDetails] 
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);		
				
				--Delete the EmployeeExperienceDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeeSalaryDetails] 
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);
			
				--Delete the EmployeePFDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeePFDetails] 
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);
				
				DELETE 
				FROM	[dbo].[EmpAttendanceMachineMappingDetails] 
				WHERE	EmployeeId	IN (	SELECT	ED.EmployeeId
											FROM	[dbo].[EmployeeDetails] ED
											WHERE	ED.EmployeeId = @EmployeeId
											AND		CompanyId = @CompanyId
										);
				
				--Delete the EmployeeESIDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeeESIDetails] 
				WHERE	EmployeeId IN (	SELECT	ED.EmployeeId
										FROM	[dbo].[EmployeeDetails] ED
										WHERE	ED.EmployeeId = @EmployeeId
										AND		CompanyId = @CompanyId
									);		

				DELETE 
				FROM	[dbo].[EmployeeDeviceMappingDetails] 
				WHERE	EmployeeId	IN (	SELECT	ED.EmployeeId
											FROM	[dbo].[EmployeeDetails] ED
											WHERE	ED.EmployeeId = @EmployeeId
											AND		CompanyId = @CompanyId
										);
	
				--Delete the LeaveTypeDetails for the given EmployeeId.	
				DELETE
				FROM	[dbo].[LeaveTypeDetails]
				WHERE	CompanyId = @CompanyId
				AND		LeaveTypeId IN (	SELECT	LeaveTypeId 
											FROM	[dbo].[EmployeeDetails] 
											WHERE	EmployeeId = @EmployeeId
											AND		CompanyId = @CompanyId);

				--Delete the DesignationDetails for the given EmployeeId.	
				DELETE
				FROM	[dbo].[DesignationDetails]
				WHERE	DesignationId IN (	SELECT	DesignationId 
											FROM	[dbo].[EmployeeDetails] 
											WHERE	EmployeeId = @EmployeeId
											AND		CompanyId = @CompanyId);

				--Delete the DepartmentDetails for the given EmployeeId.	
				DELETE
				FROM	[dbo].[DepartmentDetails]
				WHERE	CompanyId = @CompanyId
				AND		DepartmentId IN (	SELECT	DepartmentId 
											FROM	[dbo].[EmployeeDetails] 
											WHERE	EmployeeId = @EmployeeId
											AND		CompanyId = @CompanyId
										 );

				--ALTER TABLE [EmployeeDetails] DROP CONSTRAINT FK_EmployeeDetails_DepartmentDetails_DepartmentId

				--Delete the EmployeeDetails for the given EmployeeId
				DELETE 
				FROM	[dbo].[EmployeeDetails] 
				WHERE	EmployeeId = @EmployeeId 
				AND		CompanyId = @CompanyId;


				--Delete the Selected Employee from Userdetails table in TetroPAY database.
				DELETE 
				FROM TETROPAY.DBO.UserDetails
				WHERE	ClientId = SUBSTRING(Db_name(), (CHARINDEX('_',Db_name())+1), LEN(DB_NAME()))
				AND		ChildEmployeeId = @EmployeeId;

			
			IF @@TRANCOUNT>0
			COMMIT TRAN

			SELECT	@Status		= 1
					,@Message	= 'Record Deleted Sucessfully';
		END		
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
