			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_DeleteEmployeeDetails]	 @LoginUserId  = 1
											  ,@EmployeeId = 2
											  ,@Status	   = @S_Status	OUT
											  ,@Message    = @M_Message	OUT;
	SELECT @S_Status AS 'STATUS', @M_Message  AS 'MESSAGE';		

	SELECT * FROM [dbo].[EmployeeDetails];
	
	SELECT * FROM [dbo].[Designationdetails];
=================================================================================================================================*/

