/*========================================================================================================================================================= 
 Procedure Name		:	[dbo].[USP_DeleteShiftDetail]
 Description		:	Procedure is Used to delete the given ShiftId (When Click on delete button in ShiftInfo Grid)
 Input Parameter	:	@LoginUserId, @ShiftId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	27-02-2024
 Version			:	1.0 
 Comment			:	1.If the given @ShiftId is Not Exists, then
							1.1 Through the error POPUP Message as "Given Shift is Not Exist.".
						2.If the given @ShiftId is Exist, then delete the ShiftDetails and then
							2.1 Through the Success POPUP Message as "Record Deleted Successfully.".									 		   
===========================================================================================================================================================  */
CREATE   PROCEDURE [dbo].[USP_DeleteShiftDetails]
(	
	@LoginUserId	INT
	,@ShiftId		TINYINT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variable.
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[DBO].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY		  
		--IF the given ShiftId is exists, then through the error message as @Status = 0 & @Message = 'Given ShiftId is not Exists'	
		IF NOT EXISTS (SELECT 1 FROM [dbo].[ShiftDetails] WHERE ShiftId = @ShiftId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Given ShiftName is Not Exist.';
			RETURN;
		END
		ELSE
		BEGIN		
			BEGIN TRAN
				
				DELETE 
				FROM	[dbo].[EmployeeShiftMappingDetails] 
				WHERE	ShiftId = @ShiftId;

				DELETE 
				FROM	[dbo].[ShiftDetails] 
				WHERE	ShiftId = @ShiftId 
				AND		CompanyId = @CompanyId;

			IF @@TRANCOUNT>0
			COMMIT TRAN

			SELECT	@Status		= 1
					,@Message	= 'Record Deleted Successfully.';				
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE  @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_DeleteShiftDetails]	@LoginUserId	= 1
										,@ShiftId		= 3										
										,@Status		= @S_Status		OUT
										,@Message		= @M_Message	OUT;

	SELECT @S_Status AS 'STATUS', @M_Message  AS 'MESSAGE';		

	SELECT	* 
	FROM	[dbo].[ShiftDetails];
=================================================================================================================================*/
GO
