															,@ProfessionalTaxId		= 2
															,@Status				= @S_Status		OUT
															,@Message				= @M_Message	OUT;

	SELECT @S_Status AS 'STATUS', @M_Message  AS 'MESSAGE';		

	 SELECT	* 
	 FROM	[dbo].[PFDetails];
=================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_ForgetPasswordDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ====================================================================================================================================================================  
 Procedure Name		:  [USP_ForgetPasswordDetails]  
 Description		:  SP to reset the password. (When click on forgotPassword option in login page)
 Input Parameters	:  @OTPMedium, @OTPNumber, @Password  
 Output Parameters	:  @Status, @Message  
 Author				:  Dharani.M
 Created On			:  09-09-2023  
 Version			:  1.0 
 Comments			:  1.If the whether the OTPMedium is Email or MobileNumber?  
 							1.1 The Input OTP medium Can be either MobileNumber or Email,
 								1.1.1 If Entered EmailId is not Exists, Then through Error Message 'Invalid Email'.
 								1.1.2 If Entered ContactNumber is not Exists, Then through Error Message 'Invalid ContactNumber'.
 							1.2 If @Password is NOT NULL, Update the new Password in Table,Then through the Success Message as 'Password Resetted SucessFully.'.  
 							1.3 If @OTPNumber is NULL, Update the new OTP number in Employeedetails table and send Generated OTP in SMS to the given MobileNumber,
 								Then Through the Message as 'OTP Sent to your given mobile Number to reset your Password'.
 									1.3.1 Update the new OTP number in Employeedetails table and send Generated OTP in Email to the given Email,
 										Then Through Message as 'OTP Sent to your given Email to reset your Password'.
 							1.4 If @OTPNumber is NOT NULL, Check the OTP in Employeedetails table and allow the Employee to set the new password message as'OTP Verified'.
 							1.5 If OTP is not verified then through the  error message = 'Incorrect OTP / Expired OTP'
==========================================================================================================================================================================*/  
CREATE     PROCEDURE [dbo].[USP_ForgetPasswordDetails]  
(  
	@OTPMedium	NVARCHAR(100) --  Email / MobileNumber
	,@OTPNumber	NVARCHAR(50)  
	,@Password	NVARCHAR(50)  
	,@Status	BIT           OUT  
	,@Message	NVARCHAR(500) OUT  
)  
AS  
BEGIN  
	SET NOCOUNT ON;

	DECLARE @InputMedium	NVARCHAR(50)  
			,@EmployeeId	INT;
			
	BEGIN TRY
		-- If the whether the OTPMedium is Email or MobileNumber?  
		-- charindex will return the position of the letter in the string 
		IF(SELECT CHARINDEX('@',@OTPMedium)) > 0  
		BEGIN  
			SELECT   @InputMedium = 'Email'; 
			
			SELECT   @EmployeeId = EmployeeId	   
			FROM     [dbo].[EmployeeDetails]   
			WHERE    OfficialEmail = @OTPMedium;  
		END 
		ELSE
		BEGIN  
			SELECT  @InputMedium = 'MobileNumber';  
		     
			SELECT	@EmployeeId	 = EmployeeId	   
			FROM	[dbo].[EmployeeDetails]   
			WHERE	ContactNo = @OTPMedium;  
		END
		--If the given EmailId was not exists ,then through the error message = 'Invalid Email.'
		IF @InputMedium = 'Email'
		BEGIN
			IF NOT EXISTS( SELECT 1 FROM [dbo].[EmployeeDetails] WHERE OfficialEmail = @OTPMedium)  
			BEGIN  
				SELECT	@Status   = 0  
						,@Message = 'Invalid Email.';
				RETURN;
			END 
		END
		--If the given contact number is not exists,then through the error message = 'Invalid ContactNumber.'
		IF @InputMedium = 'MobileNumber'
		BEGIN
			IF NOT EXISTS( SELECT 1 FROM [dbo].[EmployeeDetails] WHERE ContactNo = @OTPMedium)  
			BEGIN  
				SELECT	@Status   = 0  
						,@Message = 'Invalid ContactNumber.';   
				RETURN;
			END 
		END
		
		BEGIN TRAN  
			--Logic for New Password entry screen (screen3)
			IF @Password IS NOT NULL  
			BEGIN  
				UPDATE	[dbo].[EmployeeDetails]  
				SET		[Password]   = @Password
						,UpdatedBy   = 0
						,UpdatedDate = GETDATE()  
				WHERE	EmployeeId   = @EmployeeId;
	
				SELECT	@Status     = 1 
						,@Message   = 'Password Resetted Successfully.';  
			END  
			ELSE  
			BEGIN  
				--Logic for Contactnumber/Email entry screen (screen1)
				IF @OTPNumber IS NULL  
				BEGIN  
					UPDATE	[dbo].[EmployeeDetails]  
					SET		CurrentOTP				= LEFT(CAST(RAND()*1000000000+999999 AS INT),4)  
							,IsCurrentOTPExpired	= 0   
					WHERE	EmployeeId				= @EmployeeId;	 

					--Logic is OTP sent to the contact number.
					IF @InputMedium = 'MobileNumber'  
					BEGIN  
						SELECT	CONCAT(FirstName,' ',LastName) AS EmployeeFullName
								,CurrentOTP  
								,ED.ContactNo AS ContactNumber
								,OfficialEmail AS EmployeeEmail   
						FROM    [dbo].[EmployeeDetails] ED
						WHERE   ED.EmployeeId = @EmployeeId;
  
						SELECT	@Status   = 1 
								,@Message = 'OTP Sent to your given mobile Number to reset your Password';   
					END		
					ELSE  
					--Logic is used to sent the OTP in Email.
					BEGIN  
						SELECT	CONCAT(FirstName,' ',LastName) AS EmployeeFullName
								,CurrentOTP  
								,OfficialEmail AS EmployeeEmail  
						FROM	[dbo].[EmployeeDetails] ED
						WHERE	ED.EmployeeId	= @EmployeeId;
							
						SELECT	@Status   = 1
								,@Message = 'OTP Sent to your given Email to reset your Password';   
					END  
				END  
				ELSE
				-- Logic for OTP entry screen (screen2)
				BEGIN  
					IF (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE EmployeeId	= @EmployeeId AND CurrentOTP = @OTPNumber AND IsCurrentOTPExpired = 0) = 1
					BEGIN  
						SELECT  @Status   = 1
								,@Message = 'OTP Verified';  

					SELECT	@OTPMedium AS EmployeeEmail
       
						UPDATE  [dbo].[EmployeeDetails]  
						SET     IsCurrentOTPExpired   = 1  
								,IsActive             = 1  
						WHERE   EmployeeId = @EmployeeId 
						AND		CurrentOTP = @OTPNumber;        
					END  
					ELSE  
					BEGIN  
						SELECT  @Status    = 0  
								,@Message  = 'Incorrect OTP / Expired OTP';  
					END		
				END  
			END

		IF @@TRANCOUNT > 0  
		COMMIT TRAN  

	END TRY  
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT  @Status   = 0  
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));  
	END CATCH  
END
/*==============================================================================================================
	DECLARE	@Status BIT  
			,@Message NVARCHAR(500)  
	
	EXEC [dbo].[USP_ForgetPasswordDetails]	@OTPMedium  = 'tharanitharan.tetrosoft@gmail.com'
											,@OTPNumber = 8440
											,@Password  ="877815"
											,@Status    = @Status  OUT  
											,@Message   = @Message OUT;
	SELECT @Status AS 'STATUS', @Message  AS 'MESSAGE';
	 
	SELECT	*
	FROM	[dbo].[EmployeeDetails];
==================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_GeneratePaySlipDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=============================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GeneratePaySlipDetails]
 Description		:	Procedure used to insert into the new PaySlipDetails table(INSERT INTO PaySlipDetails from the given SELECT List Columns)
 Input Parameter	:	@LoginUserId ,@Month ,@Year
 Parameters			:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	25-04-2023
 Version			:	1.0 
 Comment			:	1. IF NOT EXISTS,Then 
							1.1 Insert into PaySlipDetails table with 
									Month				AS @Month
									,Year				AS @Year
									,EmployeeId			AS @EmployeeId
									,EffectiveWorkDays	AS @EffectiveWorkDays
									,LOP				AS @LOP
									,BasicPay			AS @BasicPay
									,HRA				AS @HRA
									,OtherAllowance		AS @OtherAllowance
									,PF					AS @PF
									,ESI				AS @ESI
									,IncomeTax			AS @IncomeTax
									,LeaveDeduction		AS @LeaveDeduction
									,TotalEarning		AS @TotalEarning
									,TotalDeduction		AS @TotalDeduction
									,NetPay				AS @NetPay
									,PaymentMode		AS @PaymentMode
									,AdvanceAmount		AS @AdvanceAmount
									,LoanDueAmount		AS LoanDueAmount
									,CompanyId			AS CompanyId
									,CreatedBy			AS @LoginUserId
									,CreatedDate		AS GETDATE() for new PaySlip From the given columns on SELECT statement.
							1.2 Insert into NotificationDetails table for the process of Message and notification to the owner
							1.3 Insert into NotificationDetails table for the process of Message and notification to the employees
						2. Then through the Success POPUP message as 'The PaySlipDetails have been Inserted Successfully'.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GeneratePaySlipDetails]
(
	@LoginUserId	INT
	,@Month			INT
	,@Year			INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE	@LoginUserId	INT		= 1		
	--		,@Month			INT		= 1
	--		,@Year			INT		= 2025;

	DECLARE	@CompanyId							TINYINT
			,@EffectiveWorkDays					INT
			,@Holidays							INT
			,@WeekEnds							INT
			,@EmployeeId						INT				
			,@Start								INT				
			,@End								INT			 
			,@EmployeeTypeId					TINYINT	 		
			,@EarningsCount						INT			 
			,@DeductionsCount					INT
			,@EarningsInsertColumns_Payslip		NVARCHAR(MAX)
			,@DeductionsInsertColumns_Payslip	NVARCHAR(MAX)
			,@EarningsSumColumns				NVARCHAR(MAX)
			,@DeductionsSumColumns				NVARCHAR(MAX)
			,@EarningsColumns					NVARCHAR(MAX)
			,@DeductionsColumns					NVARCHAR(MAX)
			,@SQL								NVARCHAR(MAX)
			,@PaymentTypeId						TINYINT
			,@StartDate							DATETIME = DATEFROMPARTS(@Year, @Month, '01')
			,@EndDate							DATETIME = EOMONTH(DATEFROMPARTS(@Year, @Month, '01'))
			,@PaySlipId							INT;

	SELECT	@CompanyId = CompanyId 	
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId; 

	SELECT	@Holidays = COUNT(HoliDayId) 
	FROM	[dbo].[HoliDayDetails] HD
	WHERE	MONTH(HolidayDate) = @Month 
	AND		YEAR(HolidayDate) = @Year
	AND		CompanyId = @CompanyId
	AND		DATENAME(DW,HolidayDate) NOT IN (SELECT [Day] FROM CompanyWorkingDayDetails WHERE IsWorkingDay = 0);

	SELECT	@EffectiveWorkDays = DAY(EOMONTH(DATEFROMPARTS(@Year,@Month,'01'))); 
	 
	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id				INT		IDENTITY(1,1)
		,PunchDate		DATE
		,CompanyId		TINYINT
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate, CompanyId) 
		VALUES		(@StartDate,@CompanyId);

		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;

	DROP TABLE IF EXISTS #EmpDetails;
	CREATE TABLE #EmpDetails
	(
		Id					INT IDENTITY(1,1)
		,EmployeeId			INT
		,EmployeeTypeId		TINYINT
	)
	INSERT INTO	#EmpDetails(EmployeeId, EmployeeTypeId)
	SELECT		EmployeeId, EmployeeTypeId
	FROM		[dbo].[EmployeeDetails] 
	WHERE		IsActive = 1;

	SELECT	@Start	= MIN(Id)
			,@End	= MAX(Id)
	FROM	#EmpDetails;
	
	BEGIN TRY
		IF EXISTS (SELECT 1 FROM [dbo].[SalaryComponentsDetails] WHERE CompanyId = @CompanyId)
		BEGIN 
			WHILE @Start <= @End
			BEGIN
				SELECT	@EmployeeId = EmployeeId 
						,@EmployeeTypeId = EmployeeTypeId
				FROM	#EmpDetails
				WHERE	Id = @Start;

				IF NOT EXISTS ( SELECT 1 FROM PaySlipDetails_1 WHERE [Month] = @Month AND [Year] = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
				BEGIN 
					IF EXISTS (	SELECT 1 FROM EmployeeSalaryDetails WHERE EmployeeId = @EmployeeId AND ISNULL(CTC,0) = 0)
					BEGIN 
						SELECT	@Status = 0
								,@Message = 'EmployeeSalarydetails are yet to updated for this Employee.';
						GOTO thexit;
					END 
					IF EXISTS(	SELECT	* 
								FROM	[dbo].[EmployeePFDetails] PF
								JOIN	[dbo].[EmployeeSalaryDetails] ESD
									ON	PF.EmployeeId = ESD.EmployeeId
								WHERE	PF.EmployeeId = @EmployeeId 
								AND		(CTC / 12) > 20000
								AND		ISNULL(PFNumber,'') = '')
					BEGIN
						SELECT	@Status   = 1   
								,@Message = 'Required Details for Employee PF info are yet to Updated for this Employee.';
						GOTO thexit;
					END
					IF EXISTS(	SELECT * FROM [dbo].[EmployeeESIDetails] WHERE EmployeeId = @EmployeeId 
								AND	IsESIApplicable = 1 AND ISNULL(EmployeeESIContribution,0) = 0)
					BEGIN
						SELECT	@Status   = 1   
								,@Message = 'Required Details for Employee ESI info are yet to Updated for this Employee';
						GOTO thexit;
					END		
					IF NOT EXISTS (	SELECT 1 FROM [dbo].[EmployeeBankDetails] WHERE EmployeeId = @EmployeeId)
					BEGIN
						SELECT	@Status		= 1   
								,@Message	= 'Required Details for Employee Bank info are yet to Updated for this Employee. '
						GOTO thexit;
					END
					ELSE
					BEGIN TRAN 
						DROP TABLE IF EXISTS #ResultSet_1;
						SELECT	EmployeeId
								,EmployeeName
								,[Month]
								,[Year]
								,EffectiveWorkDays
								,Holidays 
								,SUM(ISNULL(TotalTakenLeave,0)) AS TotalTakenLeave
								,SUM(ISNULL(TakenPermission,0)) AS TakenPermission
								,SUM(ISNULL(TakenCompOff,0)) AS TakenCompOff 
								,CASE WHEN @EffectiveWorkDays <= SUM(ISNULL(TotalWorkingDays,0))
									THEN @EffectiveWorkDays ELSE SUM(ISNULL(TotalWorkingDays,0))
								END AS TotalWorkingDays
								,CASE WHEN @EffectiveWorkDays <= (SUM(ISNULL(TotalWorkingDays,0)))
								THEN 0 ELSE ((@EffectiveWorkDays) - (SUM(ISNULL(TotalWorkingDays,0)))) END AS Remaining 
								,SUM(ISNULL(TotalClaimAmount,0)) AS TotalClaimAmount
								,SUM(ISNULL(TotalAdvanceAmount,0)) AS TotalAdvanceAmount
								,SUM(ISNULL(TotalLoanAmount,0)) AS TotalLoanAmount
						INTO	#ResultSet_1 
						FROM	(
									SELECT	DISTINCT AT.PunchDate AS [Date]
											,ED.EmployeeId	
											,CONCAT(FirstName, ' ', LastName) AS EmployeeName
											,@Month AS [Month]
											,@Year AS [Year]
											,@EffectiveWorkDays AS EffectiveWorkDays
											,@Holidays AS Holidays 
											,ISNULL(TotalTakenLeave,0) AS TotalTakenLeave
											,ISNULL(NoOfHours,0) AS TakenPermission
											,ISNULL(TakenCompOff,0) AS TakenCompOff
											,CASE	WHEN LD.EmployeeId IS NOT NULL AND LD.IsHalfDay = 1 AND (IsFirstHalf = 1 OR IsFirstHalf = 0) AND LSD.EmployeeId IS NOT NULL AND LSD.IsHalfDay IS NOT NULL AND LeaveTypeId = 2 THEN 1
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
													WHEN LD.IsHalfDay IS NULL AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND IsWorkingDay IS NULL AND LSD.EmployeeId IS NULL AND LeaveTypeId = 2 THEN 0
 													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
													WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 0
													WHEN LSD.LeaveTypeId = 2 AND TakenCompOff IS NOT NULL THEN 1
													WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) THEN 1
													WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
													WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
													WHEN PD.EmployeeId IS NULL AND PH.InTime IS NOT NULL AND TotalMinutesPerDay IS NOT NULL AND TotalMinutesPerDay >= 480 THEN 1 
													WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) > 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 1
													WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) < 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 0.5
													WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 480 AND TotalMinutesPerDay > 240 THEN 0.5
												ELSE 0 
											END AS TotalWorkingDays 
											,ISNULL(TotalClaimAmount,0) AS TotalClaimAmount
											,ISNULL(TotalAdvanceAmount,0) AS TotalAdvanceAmount
											,ISNULL(TotalLoanAmount,0) AS TotalLoanAmount
									FROM	(	SELECT	EmployeeId, FirstName, LastName, CompanyId
												FROM	[dbo].[EmployeeDetails]
												WHERE	EmployeeId = @EmployeeId
											) AS ED
									CROSS JOIN #Attendance AT
									LEFT JOIN (
												SELECT	CompanyId, IsWorkingDay, [Day] 
												FROM	[dbo].[CompanyWorkingDayDetails]
												WHERE	IsWorkingDay = 0
												AND		CompanyId = @CompanyId
												) AS CWDD
										ON	CWDD.CompanyId = ED.CompanyId
										AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
									LEFT JOIN [dbo].[HolidayDetails] HD
										ON	AT.PunchDate = HD.HolidayDate
									LEFT JOIN (	
												SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
												FROM	[dbo].[EmployeeShiftMappingDetails] ESMD
												JOIN	[dbo].[EmployeeDetails] ED
													ON	ESMD.EmployeeId = ED.EmployeeId
												LEFT JOIN [dbo].[ShiftDetails] SD
													ON	SD.ShiftId = ESMD.ShiftId 
												) AS ESMD
										ON	ED.EmployeeId = ESMD.EmployeeId 
										AND AT.PunchDate BETWEEN StartDate AND EndDate
									LEFT JOIN	(	
												SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
														,MAX(OutTime) AS OutTime
														,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
														,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
												FROM	(
															SELECT	ED.EmployeeId
																	,PunchDate
																	,CONVERT(TIME,PunchTime) AS InTime
																	,[Status]
																	,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																			AND CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
																		WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																			AND CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
																		ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime))
																	END) AS OutTime
															FROM	[dbo].[EmployeeDetails] ED	
															JOIN	[dbo].[AttendanceLogDetails] ALD	
																ON	ED.EmployeeId = ALD.EmployeeId 
															WHERE	ED.EmployeeId = @EmployeeId
															AND		MONTH(PunchDate) = @Month
															AND		YEAR(PunchDate) = @Year
														) AS ALD
												WHERE	[Status] = 1
												GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate)
											) PH
										ON	ED.EmployeeId = PH.EmployeeId
										AND AT.PunchDate = PH.PunchDate
									LEFT JOIN	(
													SELECT	EmployeeId, FromDate, ToDate, NoOfDays AS TotalTakenLeave
															,IsHalfDay, IsFirstHalf, LeaveStatusId
													FROM	[dbo].[LeaveDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	LeaveStatusId = 3
														AND	LeaveTypeId <> 2
														AND	(MONTH(FromDate) = @Month
														OR	MONTH(ToDate) = @Month)
														AND	(YEAR(FromDate) = @Year
														OR	YEAR(ToDate) = @Year)
												) AS LD
										ON	ED.EmployeeId = LD.EmployeeId
										AND AT.PunchDate BETWEEN LD.FromDate AND LD.ToDate
									LEFT JOIN	(
													SELECT	EmployeeId, PermissionDate
															,DATEDIFF(MINUTE,StartTime,EndTime) AS NoOfHours
													FROM	[dbo].[PermissionDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	PermissionStatusId = 3
														AND	MONTH(PermissionDate) = @Month
														AND	YEAR(PermissionDate) = @Year
												) AS PD
										ON	ED.EmployeeId = PD.EmployeeId
										AND	AT.PunchDate = PD.PermissionDate
									LEFT JOIN	(
													SELECT	EmployeeId, FromDate AS [Date], LeaveTypeId, IsHalfDay
															,NoOfDays AS TakenCompOff
													FROM	[dbo].[LeaveDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	LeaveStatusId = 3 AND LeaveTypeId = 2
														AND	(MONTH(FromDate) = @Month OR MONTH(ToDate) = @Month)
														AND	(YEAR(FromDate) = @Year OR YEAR(ToDate) = @Year)
												) AS LSD
										ON	ED.EmployeeId = LSD.EmployeeId
										AND AT.PunchDate = LSD.[Date]
									LEFT JOIN	(
													SELECT	RequestedBy, ClaimDate, ApprovedAmount AS TotalClaimAmount
													FROM	[dbo].[ClaimDetails]
													WHERE	RequestedBy = @EmployeeId AND ClaimStatusId = 3
													AND		MONTH(ClaimDate) = @Month AND YEAR(ClaimDate) = @Year
												) AS CD
										ON	ED.EmployeeId = CD.RequestedBy
										AND AT.PunchDate = CONVERT(DATE,CD.ClaimDate)
									LEFT JOIN	(
													SELECT	EmployeeId, AdvanceDate, AdvanceAmount AS TotalAdvanceAmount
													FROM	[dbo].[AdvanceDetails]
													WHERE	EmployeeId = @EmployeeId AND AdvanceStatusId = 3
													AND		MONTH(AdvanceDate) = @Month AND	YEAR(AdvanceDate) = @Year 
												) AS AD
										ON	ED.EmployeeId = AD.EmployeeId
										AND AT.PunchDate = CONVERT(DATE,AD.AdvanceDate)
									LEFT JOIN	(
													SELECT	EmployeeId, LoanDate, LoanDueAmount AS TotalLoanAmount
													FROM	[dbo].[LoanDetails] LD
													JOIN	[dbo].[LoanDueDetails] LDD
														ON	LD.LoanId = LDD.LoanId
													WHERE	EmployeeId = @EmployeeId AND LoanStatusId = 3
														AND	MONTH(LoanDate) = @Month AND YEAR(LoanDate) = @Year 
												) AS LND
										ON	ED.EmployeeId = LND.EmployeeId
										AND AT.PunchDate = CONVERT(DATE,LND.LoanDate)
								) AS  A
						GROUP BY EmployeeId, EmployeeName, [Month], [Year], EffectiveWorkDays, Holidays;
				 					   
						DECLARE	@cols			NVARCHAR(MAX)
								,@query_1		NVARCHAR(MAX)
								,@query_2		NVARCHAR(MAX)
								,@FinalQuery	NVARCHAR(MAX);

						SELECT	@cols = STRING_AGG(QUOTENAME(ComponentAliasName), ',')
						FROM	(SELECT DISTINCT ComponentAliasName FROM ComponentAliasNameDetails) AS ComponentList;

						SET @query_1
						= '	DROP TABLE IF EXISTS ##Resultset_2;
							SELECT	EmployeeId, MonthlyIncome, PerDaySalary, PaymentTypeId 
									, ' + @cols + '
							INTO	##Resultset_2
							FROM	(SELECT	DISTINCT ED.EmployeeId
											,ESD.PaymentTypeId
											,CONVERT(NUMERIC(11,2),(CTC / 12)) AS MonthlyIncome
											,CONVERT(NUMERIC(11,2),(CTC / 12 / 31)) AS PerDaySalary
											,ComponentAliasName
											,CASE	WHEN SCD.ComponentAliasNameId = 1 THEN CONVERT(NUMERIC(11,2), (CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100)) / 12)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 2 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 3 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 4 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),10) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 5 THEN ISNULL(Remaining * CONVERT(NUMERIC(11,2),(CTC / 12 / 31)),0)
													WHEN SCD.ComponentAliasNameId = 6 AND (CONVERT(NUMERIC(11,2),CTC) / CONVERT(NUMERIC(11,2),12)) > (CONVERT(NUMERIC(11,2),21000))
													THEN (((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 6 AND (CTC / 12) < 21000 THEN 0
													WHEN SCD.ComponentAliasNameId = 7 AND IsESIApplicable = 1 THEN 
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / 100) / 12))  + 
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100))) +
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) +
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),12) / CONVERT(NUMERIC(11,2),100)))) * 
															((CONVERT(NUMERIC(11,2),0.75) / CONVERT(NUMERIC(11,2),100))) * TotalWorkingDays / 31
															WHEN SCD.ComponentAliasNameId = 7 AND IsESIApplicable = 0 THEN 0
															WHEN SCD.ComponentAliasNameId = 8 AND PTD.ProfessionalTaxId IS NOT NULL AND 
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / 100) / 12))  + 
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100))) +
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) +
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),12) / CONVERT(NUMERIC(11,2),100)))) 
																BETWEEN StartRange AND EndRange THEN HalfYearlyTaxAmount
															WHEN SCD.ComponentAliasNameId = 8 AND (CTC / 12) < 21000 THEN 0 
												ELSE 0 
											END AS Amount';
						SET @query_2 = '	FROM	SalaryStructureDetails SSD 
											JOIN	SalaryStructureComponentMappingDetails SSCMD ON SSD.SalaryStructureId = SSCMD.SalaryStructureId
											JOIN	SalaryComponentsDetails SCD ON SCD.SalaryComponentsId = SSCMD.SalaryComponentsId 
											JOIN	CalculationTypeDetails CTD ON SCD.CalculationTypeId = CTD.CalculationTypeId
											JOIN	EmployeeTypeStructureMappingDetails ESMD ON ESMD.SalaryStructureId = SSD.SalaryStructureId 
											JOIN	EmployeeDetails ED ON ED.EmployeeTypeId = ESMD.EmployeeTypeId
											JOIN	EmployeeSalaryDetails ESD ON ED.EmployeeId = ESD.EmployeeId 
											JOIN	EmployeeESIDetails ESSD ON ED.EmployeeId = ESSD.EmployeeId
											JOIN	ComponentAliasNameDetails CAND ON SCD.ComponentAliasNameId = CAND.ComponentAliasNameId 
											JOIN	#ResultSet_1 RD ON RD.EmployeeId = ED.EmployeeId
											LEFT JOIN BranchDetails BD ON ED.BranchId = BD.BranchId 
											LEFT JOIN ProfessionalTaxDetails PTD ON ED.BranchId = PTD.WorkLocationId
											LEFT JOIN ProfessionalTaxSlabMappingDetails PTSD ON PTD.ProfessionalTaxId = PTSD.ProfessionalTaxId
											LEFT JOIN PaymentTypeDetails PYTD
												ON	PYTD.PaymentTypeId = ESD.PaymentTypeId 
											WHERE	ESMD.EmployeeTypeId = @EmployeeTypeId AND SSCMD.IsActive = 1 AND SCD.StatusActive = 1 AND ED.EmployeeId = @EmployeeId) AS SourceTable
											PIVOT	(SUM(Amount) FOR ComponentAliasName IN (' + @cols + ')) AS PivotTable;';

						SET @FinalQuery = @query_1 + @query_2;
						PRINT @FinalQuery;
						EXEC SP_EXECUTESQL @FinalQuery, N'@EmployeeId INT, @EmployeeTypeId TINYINT', @EmployeeId, @EmployeeTypeId;
			
						DROP TABLE IF EXISTS #Temp;
						SELECT	(Basic + DA + HRA + OtherAllowance) AS GrossWages
								,([Basic] + DA) AS EPFWages
								,([Basic] + DA) AS EPSWages
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),12) / 100) END AS EmployeeShare
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),3.67) / 100) END AS EmployerEmployeeShare
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),8.33) / 100) END AS EmployerShare 
								,Remaining AS NCPDays
								,ESI AS TotalMonthlyWages
								,PT 
						INTO	#Temp
						FROM	##Resultset_2 T1
						JOIN	#ResultSet_1 T2
							ON	T1.EmployeeId = T2.EmployeeId
						WHERE	T1.EmployeeId = @EmployeeId;

						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipPFDetails] WHERE [PFMonth] = @Month AND PFYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipPFDetails](PFMonth, PFYear, EmployeeId, GrossWages, EPFWages, EPSWages, EmployeeShare
										,EmployerEmployeeShare, EmployerShare, NCPDays, CompanyId, CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, GrossWages, EPFWages, EPSWages, EmployeeShare, EmployerEmployeeShare
										,EmployerShare, NCPDays, @CompanyId, @LoginUserId
							FROM		#Temp;
						END 
			
						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipESIDetails] WHERE [ESIMonth] = @Month AND ESIYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipESIDetails](ESIMonth, ESIYear, EmployeeId, TotalMonthlyWages, ReasonCodeforZeroWorkingDay
									,LastWorkingDay, CompanyId, CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, TotalMonthlyWages, 'NA', 'NA', @CompanyId, @LoginUserId
							FROM		#Temp;
						END 

						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipPTDetails] WHERE [PTMonth] = @Month AND PTYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipPTDetails](PTMonth, PTYear, EmployeeId, PTGross, ProfessionalTax, CompanyId 
										,CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, GrossWages, PT, @CompanyId, @LoginUserId
							FROM		#Temp;
						END 

						SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentAliasName,0)), ', ')
						FROM	SalaryComponentsDetails SCD 
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	StatusActive = 1 
						AND		SalaryComponentTypeId = 1; 

						SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentAliasName,'')), ', ')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	StatusActive = 1 
						AND		SalaryComponentTypeId = 2;

						SELECT	@EarningsSumColumns = ISNULL(STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentAliasName),0) + ', 0))', ' + '),'')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 1
						AND		StatusActive = 1;

						SELECT	@DeductionsSumColumns = ISNULL(STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentAliasName),0) + ', 0))', ' + '),'')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 2
						AND		SCD.ComponentAliasNameId NOT IN (5)
						AND		StatusActive = 1;
			
						SELECT	@EarningsCount = COUNT(SalaryComponentsId)
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 1
						AND		StatusActive = 1;

						SELECT	@DeductionsCount = COUNT(SalaryComponentsId)
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 2
						AND		StatusActive = 1;

						WITH OrderedEarnings 
						AS	(
								SELECT	COLUMN_NAME
										,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
								FROM	INFORMATION_SCHEMA.COLUMNS
								WHERE	TABLE_NAME = 'PaySlipDetails_1' 
								AND		COLUMN_NAME LIKE 'Com_Earning_%')
						SELECT	@EarningsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
						FROM	(SELECT TOP (@EarningsCount) COLUMN_NAME FROM OrderedEarnings ORDER BY ColumnNumber) AS SortedEarnings;

						WITH OrderedDeductions
						AS	(
								SELECT	COLUMN_NAME
										,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
								FROM	INFORMATION_SCHEMA.COLUMNS
								WHERE	TABLE_NAME = 'PaySlipDetails_1' 
								AND		COLUMN_NAME LIKE 'Com_Deduction_%')
						SELECT	@DeductionsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
						FROM	(SELECT TOP (@DeductionsCount) COLUMN_NAME FROM OrderedDeductions ORDER BY ColumnNumber) AS SortedEarnings;
					   
						SET @SQL 
							= '	INSERT INTO PaySlipDetails_1 ([Month], [Year], EmployeeId, EffectiveWorkDays, PresentDays, LOP, ' 
											+ @EarningsInsertColumns_Payslip + ', ' + @DeductionsInsertColumns_Payslip + ', 
											ClaimAmount, TotalEarnings, AdvanceAmount, LoanDueAmount, OtherDeduction
											,TotalDeduction, NetPay, PaymentTypeId, PayslipStatus, CompanyId, CreatedBy)
								SELECT	T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.TotalWorkingDays
										,T1.Remaining, ' + @EarningsColumns + ', ' + @DeductionsColumns + ', TotalClaimAmount,
										(' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) AS TotalEarnings,
										TotalAdvanceAmount, TotalLoanAmount, 0
										,(' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount)) AS TotalDeductions,
										((' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) - (' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount))) AS NetPay
										,E.PaymentTypeId, 1, @CompanyId, @LoginUserId
								FROM	#ResultSet_1 T1
								LEFT JOIN ##ResultSet_2 E
									ON	T1.EmployeeId = E.EmployeeId
								GROUP BY T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.Remaining
										,E.PaymentTypeId, TotalClaimAmount, TotalAdvanceAmount, TotalLoanAmount
										,Remaining, PerDaySalary, TotalWorkingDays
										,' + @EarningsColumns + ', ' + @DeductionsColumns + '';

						EXEC SP_EXECUTESQL @SQL, N'@CompanyId TINYINT, @LoginUserId INT'
											,@LoginUserId = @LoginUserId
											,@CompanyId = @CompanyId;

				END
				
				SELECT  @PaySlipId = SCOPE_IDENTITY();
						
				-- Logic to update the Advance Info
				UPDATE	AD
				SET		DueAmount = 0,
						AdvanceStatusId = 6
				FROM	[dbo].[AdvanceDetails] AD
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	AD.AdvanceStatusId = LSD.LeaveStatusId
				WHERE	EmployeeId			= @EmployeeId
				AND		MONTH(AdvanceDate)  = @Month 
				AND		YEAR(AdvanceDate)	= @Year 
				AND		LeaveStatusName		= 'Approved'
				AND		AD.CompanyId		= @CompanyId ; 
							
				-- Logic to update the Loan Info
				UPDATE	LD
				SET		CompletedDue = CompletedDue + 1
						,PendingDues = PendingDues - 1
						,PendingAmount = PendingAmount - DueAmount
				FROM	[dbo].[LoanDetails] LD
				JOIN	[dbo].[LoanDueDetails] LDD
					ON	LD.LoanId = LDD.LoanId
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	LD.LoanStatusId = LSD.LeaveStatusId
				WHERE	EmployeeId			= @EmployeeId
				AND		MONTH(LoanDueDate)	= @Month 
				AND		YEAR(LoanDueDate)	= @Year
				AND		LeaveStatusName		= 'Approved'
				AND		LD.CompanyId		= @CompanyId;

				UPDATE	LDD
				SET		Isclosed = 1  
				FROM	[dbo].[LoanDetails] LD
				JOIN	[dbo].[LoanDueDetails] LDD
					ON	LD.LoanId = LDD.LoanId
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	LD.LoanStatusId		= LSD.LeaveStatusId
				WHERE	EmployeeId			= @EmployeeId
				AND		MONTH(LoanDueDate)	= @Month 
				AND		YEAR(LoanDueDate)	= @Year
				AND		LeaveStatusName		='Approved'
				AND		LD.CompanyId		= @CompanyId;

				IF(		SELECT COUNT(1) 
						FROM	[dbo].[LoanDetails] LD
						JOIN	[dbo].[LoanDueDetails] LDD
							ON	LD.LoanId = LDD.LoanId
						JOIN	[dbo].[LeaveStatusDetails] LSD
							ON	LD.LoanStatusId = LSD.LeaveStatusId
						WHERE	EmployeeId		= @EmployeeId 
						AND		IsClosed		= 0 
						AND		LD.CompanyId	= @CompanyId) = 0
				BEGIN
					UPDATE	LD
					SET		LD.LoanStatusId = 6
					FROM	[dbo].[LoanDetails] LD
					JOIN	[dbo].[LoanDueDetails] LDD
						ON	LD.LoanId = LDD.LoanId
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	LD.LoanStatusId = LSD.LeaveStatusId
					WHERE	EmployeeId			= @EmployeeId
					AND		MONTH(LoanDueDate)	= @Month 
					AND		YEAR(LoanDueDate)	= @Year
					AND		LD.CompanyId		= @CompanyId;
				END 	
				IF @@TRANCOUNT > 0
				COMMIT TRAN
				SELECT	@Status		= 1
						,@Message	= 'PaySlip Generated Successfully.'; 
			SET @Start = @Start + 1;
			END
		END
		Thexit:
			RETURN;
	END TRY
	BEGIN CATCH	
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END     
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GeneratePaySlipDetails]	@LoginUserId = 1
											,@Month		 = 1
											,@Year		 = 2025
											,@Status	 = @S_Status	OUT
											,@Message	 = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT * FROM PaySlipDetails_1;
	SELECT * FROM [dbo].[PayslipPFDetails];
	SELECT * FROM [dbo].[PayslipESIDetails];
	SELECT * FROM [dbo].[PayslipPTDetails];
	SELECT * FROM [dbo].[EmployeeDetails];
	 
	TRUNCATE TABLE PayslipDetails_1;
	TRUNCATE TABLE [dbo].[PayslipPFDetails]
	TRUNCATE TABLE [dbo].[PayslipESIDetails]
	TRUNCATE TABLE [dbo].[PayslipPTDetails] 

	SELECT * FROM LOanDetails
	SELECT * FROM LOanDueDetails
	SELECT * FROM AdvanceDetails
=====================================================================================================================*/	



GO
/****** Object:  StoredProcedure [dbo].[USP_GeneratePaySlipDetails_Test]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=============================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GeneratePaySlipDetails_Test]
 Description		:	Procedure used to insert into the new PaySlipDetails table(INSERT INTO PaySlipDetails from the given SELECT List Columns)
 Input Parameter	:	@LoginUserId ,@Month ,@Year
 Parameters			:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	25-04-2023
 Version			:	1.0 
 Comment			:	1. IF NOT EXISTS,Then 
							1.1 Insert into PaySlipDetails table with 
									Month				AS @Month
									,Year				AS @Year
									,EmployeeId			AS @EmployeeId
									,EffectiveWorkDays	AS @EffectiveWorkDays
									,LOP				AS @LOP
									,BasicPay			AS @BasicPay
									,HRA				AS @HRA
									,OtherAllowance		AS @OtherAllowance
									,PF					AS @PF
									,ESI				AS @ESI
									,IncomeTax			AS @IncomeTax
									,LeaveDeduction		AS @LeaveDeduction
									,TotalEarning		AS @TotalEarning
									,TotalDeduction		AS @TotalDeduction
									,NetPay				AS @NetPay
									,PaymentMode		AS @PaymentMode
									,AdvanceAmount		AS @AdvanceAmount
									,LoanDueAmount		AS LoanDueAmount
									,CompanyId			AS CompanyId
									,CreatedBy			AS @LoginUserId
									,CreatedDate		AS GETDATE() for new PaySlip From the given columns on SELECT statement.
							1.2 Insert into NotificationDetails table for the process of Message and notification to the owner
							1.3 Insert into NotificationDetails table for the process of Message and notification to the employees
						2. Then through the Success POPUP message as 'The PaySlipDetails have been Inserted Successfully'.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GeneratePaySlipDetails_Test]
(
	@LoginUserId	INT
	,@Month			INT
	,@Year			INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE	@LoginUserId	INT		= 1		
	--		,@Month			INT		= 1
	--		,@Year			INT		= 2025;
		
	DECLARE	@CompanyId							TINYINT
			,@EffectiveWorkDays					INT
			,@Holidays							INT
			,@WeekEnds							INT
			,@EmployeeId						INT				
			,@Start								INT				
			,@End								INT			 
			,@EmployeeTypeId					TINYINT	 		
			,@EarningsCount						INT			 
			,@DeductionsCount					INT
			,@EarningsInsertColumns_Payslip		NVARCHAR(MAX)
			,@DeductionsInsertColumns_Payslip	NVARCHAR(MAX)
			,@EarningsSumColumns				NVARCHAR(MAX)
			,@DeductionsSumColumns				NVARCHAR(MAX)
			,@EarningsColumns					NVARCHAR(MAX)
			,@DeductionsColumns					NVARCHAR(MAX)
			,@SQL								NVARCHAR(MAX)
			,@PaymentTypeId						TINYINT
			,@StartDate							DATETIME = DATEFROMPARTS(@Year, @Month, '01')
			,@EndDate							DATETIME = EOMONTH(DATEFROMPARTS(@Year, @Month, '01'));

	SELECT	@CompanyId = CompanyId 	
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId; 

	SELECT	@Holidays = COUNT(HoliDayId) 
	FROM	[dbo].[HoliDayDetails] HD
	WHERE	MONTH(HolidayDate) = @Month 
	AND		YEAR(HolidayDate) = @Year
	AND		CompanyId = @CompanyId
	AND		DATENAME(DW,HolidayDate) NOT IN (SELECT [Day] FROM CompanyWorkingDayDetails WHERE IsWorkingDay = 0);

	SELECT	@EffectiveWorkDays = DAY(EOMONTH(DATEFROMPARTS(@Year,@Month,'01'))); 
	 
	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id				INT		IDENTITY(1,1)
		,PunchDate		DATE
		,CompanyId		TINYINT
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate, CompanyId) 
		VALUES		(@StartDate,@CompanyId);

		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;

	--SELECT * FROM #Attendance;

	DROP TABLE IF EXISTS #EmpDetails;
	CREATE TABLE #EmpDetails
	(
		Id					INT IDENTITY(1,1)
		,EmployeeId			INT
		,EmployeeTypeId		TINYINT
	)
	INSERT INTO	#EmpDetails(EmployeeId, EmployeeTypeId)
	SELECT		EmployeeId, EmployeeTypeId
	FROM		[dbo].[EmployeeDetails] 
	WHERE		IsActive = 1;

	SELECT	@Start	= MIN(Id)
			,@End	= MAX(Id)
	FROM	#EmpDetails;

	--SELECT * FROM #EmpDetails;
	
	BEGIN TRY
		IF EXISTS (SELECT 1 FROM [dbo].[SalaryComponentsDetails] WHERE CompanyId = @CompanyId)
		BEGIN 
			WHILE @Start <= @End
			BEGIN
				SELECT	@EmployeeId = EmployeeId 
						,@EmployeeTypeId = EmployeeTypeId
				FROM	#EmpDetails
				WHERE	Id = @Start;

				IF NOT EXISTS ( SELECT 1 FROM PaySlipDetails_1 WHERE [Month] = @Month AND [Year] = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
				BEGIN 
					IF EXISTS (	SELECT 1 FROM EmployeeSalaryDetails WHERE EmployeeId = @EmployeeId AND ISNULL(CTC,0) = 0)
					BEGIN 
						SELECT	@Status = 0
								,@Message = 'EmployeeSalarydetails are yet to updated for this Employee.';
						GOTO thexit;
					END 
					IF EXISTS(	SELECT	* 
								FROM	[dbo].[EmployeePFDetails] PF
								JOIN	[dbo].[EmployeeSalaryDetails] ESD
									ON	PF.EmployeeId = ESD.EmployeeId
								WHERE	PF.EmployeeId = @EmployeeId 
								AND		(CTC / 12) > 20000
								AND		ISNULL(PFNumber,'') = '')
					BEGIN
						SELECT	@Status   = 1   
								,@Message = 'Required Details for Employee PF info are yet to Updated for this Employee.';
						GOTO thexit;
					END
					IF EXISTS(	SELECT * FROM [dbo].[EmployeeESIDetails] WHERE EmployeeId = @EmployeeId 
								AND	IsESIApplicable = 1 AND ISNULL(EmployeeESIContribution,0) = 0)
					BEGIN
						SELECT	@Status   = 1   
								,@Message = 'Required Details for Employee ESI info are yet to Updated for this Employee';
						GOTO thexit;
					END		
					IF NOT EXISTS (	SELECT 1 FROM [dbo].[EmployeeBankDetails] WHERE EmployeeId = @EmployeeId)
					BEGIN
						SELECT	@Status		= 1   
								,@Message	= 'Required Details for Employee Bank info are yet to Updated for this Employee. '
						GOTO thexit;
					END
					ELSE
					BEGIN TRAN 
						DROP TABLE IF EXISTS #ResultSet_1;
						SELECT	EmployeeId
								,EmployeeName
								,[Month]
								,[Year]
								,EffectiveWorkDays
								,Holidays 
								,SUM(ISNULL(TotalTakenLeave,0)) AS TotalTakenLeave
								,SUM(ISNULL(TakenPermission,0)) AS TakenPermission
								,SUM(ISNULL(TakenCompOff,0)) AS TakenCompOff 
								,CASE WHEN @EffectiveWorkDays <= SUM(ISNULL(TotalWorkingDays,0))
									THEN @EffectiveWorkDays ELSE SUM(ISNULL(TotalWorkingDays,0))
								END AS TotalWorkingDays
								,CASE WHEN @EffectiveWorkDays <= (SUM(ISNULL(TotalWorkingDays,0)))
								THEN 0 ELSE ((@EffectiveWorkDays) - (SUM(ISNULL(TotalWorkingDays,0)))) END AS Remaining
								,SUM(ISNULL(TotalClaimAmount,0)) AS TotalClaimAmount
								,SUM(ISNULL(TotalAdvanceAmount,0)) AS TotalAdvanceAmount
								,SUM(ISNULL(TotalLoanAmount,0)) AS TotalLoanAmount
						INTO	#ResultSet_1 
						FROM	(
									SELECT	DISTINCT AT.PunchDate AS [Date]
											,ED.EmployeeId	
											,CONCAT(FirstName, ' ', LastName) AS EmployeeName
											,@Month AS [Month]
											,@Year AS [Year]
											,@EffectiveWorkDays AS EffectiveWorkDays
											,@Holidays AS Holidays 
											,ISNULL(TotalTakenLeave,0) AS TotalTakenLeave
											,ISNULL(NoOfHours,0) AS TakenPermission
											,ISNULL(TakenCompOff,0) AS TakenCompOff
											,CASE	WHEN LD.EmployeeId IS NOT NULL AND LD.IsHalfDay = 1 AND (IsFirstHalf = 1 OR IsFirstHalf = 0) AND LSD.EmployeeId IS NOT NULL AND LSD.IsHalfDay IS NOT NULL AND LeaveTypeId = 2 THEN 1
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
													WHEN LD.IsHalfDay IS NULL AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND IsWorkingDay IS NULL AND LSD.EmployeeId IS NULL AND LeaveTypeId = 2 THEN 0
 													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
													WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
													WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 0
													WHEN LSD.LeaveTypeId = 2 AND TakenCompOff IS NOT NULL THEN 1
													WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) THEN 1
													WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
													WHEN IsWorkingDay IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 1
													WHEN PD.EmployeeId IS NULL AND PH.InTime IS NOT NULL AND TotalMinutesPerDay IS NOT NULL AND TotalMinutesPerDay >= 480 THEN 1 
													WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) > 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 1
													WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) < 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 0.5
													WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 480 AND TotalMinutesPerDay > 240 THEN 0.5
												ELSE 0
											END AS TotalWorkingDays 
											,ISNULL(TotalClaimAmount,0) AS TotalClaimAmount
											,ISNULL(TotalAdvanceAmount,0) AS TotalAdvanceAmount
											,ISNULL(TotalLoanAmount,0) AS TotalLoanAmount
									FROM	(	SELECT	EmployeeId, FirstName, LastName, CompanyId
												FROM	[dbo].[EmployeeDetails]
												WHERE	EmployeeId = @EmployeeId
											) AS ED
									CROSS JOIN #Attendance AT
									LEFT JOIN (
												SELECT	CompanyId, IsWorkingDay, [Day] 
												FROM	[dbo].[CompanyWorkingDayDetails]
												WHERE	IsWorkingDay = 0
												AND		CompanyId = @CompanyId
												) AS CWDD
										ON	CWDD.CompanyId = ED.CompanyId
										AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
									LEFT JOIN [dbo].[HolidayDetails] HD
										ON	AT.PunchDate = HD.HolidayDate
									LEFT JOIN (	
												SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
												FROM	[dbo].[EmployeeShiftMappingDetails] ESMD
												JOIN	[dbo].[EmployeeDetails] ED
													ON	ESMD.EmployeeId = ED.EmployeeId
												LEFT JOIN [dbo].[ShiftDetails] SD
													ON	SD.ShiftId = ESMD.ShiftId 
												) AS ESMD
										ON	ED.EmployeeId = ESMD.EmployeeId 
										AND AT.PunchDate BETWEEN StartDate AND EndDate
									LEFT JOIN	(	
												SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
														,MAX(OutTime) AS OutTime
														,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
														,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
												FROM	(
															SELECT	ED.EmployeeId
																	,PunchDate
																	,CONVERT(TIME,PunchTime) AS InTime
																	,[Status]
																	,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																			AND CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
																		WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																			AND CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
																		ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime))
																	END) AS OutTime
															FROM	[dbo].[EmployeeDetails] ED	
															JOIN	[dbo].[AttendanceLogDetails] ALD	
																ON	ED.EmployeeId = ALD.EmployeeId 
															WHERE	ED.EmployeeId = @EmployeeId
															AND		MONTH(PunchDate) = @Month
															AND		YEAR(PunchDate) = @Year
														) AS ALD
												WHERE	[Status] = 1
												GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate)
											) PH
										ON	ED.EmployeeId = PH.EmployeeId
										AND AT.PunchDate = PH.PunchDate
									LEFT JOIN	(
													SELECT	EmployeeId, FromDate, ToDate, NoOfDays AS TotalTakenLeave
															,IsHalfDay, IsFirstHalf, LeaveStatusId
													FROM	[dbo].[LeaveDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	LeaveStatusId = 3
														AND	LeaveTypeId <> 2
														AND	(MONTH(FromDate) = @Month
														OR	MONTH(ToDate) = @Month)
														AND	(YEAR(FromDate) = @Year
														OR	YEAR(ToDate) = @Year)
												) AS LD
										ON	ED.EmployeeId = LD.EmployeeId
										AND AT.PunchDate BETWEEN LD.FromDate AND LD.ToDate
									LEFT JOIN	(
													SELECT	EmployeeId, PermissionDate
															,DATEDIFF(MINUTE,StartTime,EndTime) AS NoOfHours
													FROM	[dbo].[PermissionDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	PermissionStatusId = 3
														AND	MONTH(PermissionDate) = @Month
														AND	YEAR(PermissionDate) = @Year
												) AS PD
										ON	ED.EmployeeId = PD.EmployeeId
										AND	AT.PunchDate = PD.PermissionDate
									LEFT JOIN	(
													SELECT	EmployeeId, FromDate AS [Date], LeaveTypeId, IsHalfDay
															,NoOfDays AS TakenCompOff
													FROM	[dbo].[LeaveDetails]
													WHERE	EmployeeId = @EmployeeId
														AND	LeaveStatusId = 3 AND LeaveTypeId = 2
														AND	(MONTH(FromDate) = @Month OR MONTH(ToDate) = @Month)
														AND	(YEAR(FromDate) = @Year OR YEAR(ToDate) = @Year)
												) AS LSD
										ON	ED.EmployeeId = LSD.EmployeeId
										AND AT.PunchDate = LSD.[Date]
									LEFT JOIN	(
													SELECT	RequestedBy, ClaimDate, ApprovedAmount AS TotalClaimAmount
													FROM	[dbo].[ClaimDetails]
													WHERE	RequestedBy = @EmployeeId AND ClaimStatusId = 3
													AND		MONTH(ClaimDate) = @Month AND YEAR(ClaimDate) = @Year
												) AS CD
										ON	ED.EmployeeId = CD.RequestedBy
										AND AT.PunchDate = CD.ClaimDate
									LEFT JOIN	(
													SELECT	EmployeeId, AdvanceDate, AdvanceAmount AS TotalAdvanceAmount
													FROM	[dbo].[AdvanceDetails]
													WHERE	EmployeeId = @EmployeeId AND AdvanceStatusId = 3
													AND		MONTH(AdvanceDate) = @Month AND	YEAR(AdvanceDate) = @Year 
												) AS AD
										ON	ED.EmployeeId = AD.EmployeeId
										AND AT.PunchDate = AD.AdvanceDate
									LEFT JOIN	(
													SELECT	EmployeeId, LoanDate, LoanDueAmount AS TotalLoanAmount
													FROM	[dbo].[LoanDetails] LD
													JOIN	[dbo].[LoanDueDetails] LDD
														ON	LD.LoanId = LDD.LoanId
													WHERE	EmployeeId = @EmployeeId AND LoanStatusId = 3
														AND	MONTH(LoanDate) = @Month AND YEAR(LoanDate) = @Year 
												) AS LND
										ON	ED.EmployeeId = LND.EmployeeId
										AND AT.PunchDate = LND.LoanDate
								) AS  A
						GROUP BY EmployeeId, EmployeeName, [Month], [Year], EffectiveWorkDays, Holidays;
				 					   
						DECLARE	@cols			NVARCHAR(MAX)
								,@query_1		NVARCHAR(MAX)
								,@query_2		NVARCHAR(MAX)
								,@FinalQuery	NVARCHAR(MAX);

						SELECT	@cols = STRING_AGG(QUOTENAME(ComponentAliasName), ',')
						FROM	(SELECT DISTINCT ComponentAliasName FROM ComponentAliasNameDetails) AS ComponentList;

						SET @query_1
						= '	DROP TABLE IF EXISTS ##Resultset_2;
							SELECT	EmployeeId, MonthlyIncome, PerDaySalary, PaymentTypeId 
									, ' + @cols + '
							INTO	##Resultset_2
							FROM	(SELECT	DISTINCT ED.EmployeeId
											,ESD.PaymentTypeId
											,CONVERT(NUMERIC(11,2),(CTC / 12)) AS MonthlyIncome
											,CONVERT(NUMERIC(11,2),(CTC / 12 / 31)) AS PerDaySalary
											,ComponentAliasName
											,CASE	WHEN SCD.ComponentAliasNameId = 1 THEN CONVERT(NUMERIC(11,2), (CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100)) / 12)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 2 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 3 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 4 THEN ((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * (CONVERT(NUMERIC(11,2),10) / CONVERT(NUMERIC(11,2),100)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 5 THEN ISNULL(Remaining * CONVERT(NUMERIC(11,2),(CTC / 12 / 31)),0)
													WHEN SCD.ComponentAliasNameId = 6 AND (CONVERT(NUMERIC(11,2),CTC) / CONVERT(NUMERIC(11,2),12)) > (CONVERT(NUMERIC(11,2),21000))
													THEN (((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12)) * TotalWorkingDays / 31
													WHEN SCD.ComponentAliasNameId = 6 AND (CTC / 12) < 21000 THEN 0
													WHEN SCD.ComponentAliasNameId = 7 AND IsESIApplicable = 1 THEN 
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / 100) / 12))  + 
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100))) +
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) +
															(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
															(CONVERT(NUMERIC(11,2),12) / CONVERT(NUMERIC(11,2),100)))) * 
															((CONVERT(NUMERIC(11,2),0.75) / CONVERT(NUMERIC(11,2),100))) * TotalWorkingDays / 31
															WHEN SCD.ComponentAliasNameId = 7 AND IsESIApplicable = 0 THEN 0
															WHEN SCD.ComponentAliasNameId = 8 AND PTD.ProfessionalTaxId IS NOT NULL AND 
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / 100) / 12))  + 
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),40) / CONVERT(NUMERIC(11,2),100))) +
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) +
																(((CONVERT(NUMERIC(11,2),CTC) * (CONVERT(NUMERIC(11,2),50) / CONVERT(NUMERIC(11,2),100))) / 12) * 
																(CONVERT(NUMERIC(11,2),12) / CONVERT(NUMERIC(11,2),100)))) 
																BETWEEN StartRange AND EndRange THEN HalfYearlyTaxAmount
															WHEN SCD.ComponentAliasNameId = 8 AND (CTC / 12) < 21000 THEN 0 
												ELSE 0 
											END AS Amount';
						SET @query_2 = '	FROM	SalaryStructureDetails SSD 
											JOIN	SalaryStructureComponentMappingDetails SSCMD ON SSD.SalaryStructureId = SSCMD.SalaryStructureId
											JOIN	SalaryComponentsDetails SCD ON SCD.SalaryComponentsId = SSCMD.SalaryComponentsId 
											JOIN	CalculationTypeDetails CTD ON SCD.CalculationTypeId = CTD.CalculationTypeId
											JOIN	EmployeeTypeStructureMappingDetails ESMD ON ESMD.SalaryStructureId = SSD.SalaryStructureId 
											JOIN	EmployeeDetails ED ON ED.EmployeeTypeId = ESMD.EmployeeTypeId
											JOIN	EmployeeSalaryDetails ESD ON ED.EmployeeId = ESD.EmployeeId 
											JOIN	EmployeeESIDetails ESSD ON ED.EmployeeId = ESSD.EmployeeId
											JOIN	ComponentAliasNameDetails CAND ON SCD.ComponentAliasNameId = CAND.ComponentAliasNameId 
											JOIN	#ResultSet_1 RD ON RD.EmployeeId = ED.EmployeeId
											LEFT JOIN BranchDetails BD ON ED.BranchId = BD.BranchId 
											LEFT JOIN ProfessionalTaxDetails PTD ON ED.BranchId = PTD.WorkLocationId
											LEFT JOIN ProfessionalTaxSlabMappingDetails PTSD ON PTD.ProfessionalTaxId = PTSD.ProfessionalTaxId
											LEFT JOIN PaymentTypeDetails PYTD
												ON	PYTD.PaymentTypeId = ESD.PaymentTypeId 
											WHERE	ESMD.EmployeeTypeId = @EmployeeTypeId AND SSCMD.IsActive = 1 AND SCD.StatusActive = 1 AND ED.EmployeeId = @EmployeeId) AS SourceTable
											PIVOT	(SUM(Amount) FOR ComponentAliasName IN (' + @cols + ')) AS PivotTable;';

						SET @FinalQuery = @query_1 + @query_2;
						PRINT @FinalQuery;
						EXEC SP_EXECUTESQL @FinalQuery, N'@EmployeeId INT, @EmployeeTypeId TINYINT', @EmployeeId, @EmployeeTypeId;
			
						DROP TABLE IF EXISTS #Temp;
						SELECT	(Basic + DA + HRA + OtherAllowance) AS GrossWages
								,([Basic] + DA) AS EPFWages
								,([Basic] + DA) AS EPSWages
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),12) / 100) END AS EmployeeShare
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),3.67) / 100) END AS EmployerEmployeeShare
								,CASE WHEN ([Basic] + DA) < 21000 THEN 0 ELSE ([Basic] + DA) * (CONVERT(NUMERIC(11,2),8.33) / 100) END AS EmployerShare 
								,Remaining AS NCPDays
								,ESI AS TotalMonthlyWages
								,PT 
						INTO	#Temp
						FROM	##Resultset_2 T1
						JOIN	#ResultSet_1 T2
							ON	T1.EmployeeId = T2.EmployeeId
						WHERE	T1.EmployeeId = @EmployeeId;

						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipPFDetails] WHERE [PFMonth] = @Month AND PFYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipPFDetails](PFMonth, PFYear, EmployeeId, GrossWages, EPFWages, EPSWages, EmployeeShare
										,EmployerEmployeeShare, EmployerShare, NCPDays, CompanyId, CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, GrossWages, EPFWages, EPSWages, EmployeeShare, EmployerEmployeeShare
										,EmployerShare, NCPDays, @CompanyId, @LoginUserId
							FROM		#Temp;
						END 
			
						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipESIDetails] WHERE [ESIMonth] = @Month AND ESIYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipESIDetails](ESIMonth, ESIYear, EmployeeId, TotalMonthlyWages, ReasonCodeforZeroWorkingDay
									,LastWorkingDay, CompanyId, CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, TotalMonthlyWages, 'NA', 'NA', @CompanyId, @LoginUserId
							FROM		#Temp;
						END 

						IF NOT EXISTS (	SELECT * FROM [dbo].[PayslipPTDetails] WHERE [PTMonth] = @Month AND PTYear = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
						BEGIN
							INSERT INTO [dbo].[PayslipPTDetails](PTMonth, PTYear, EmployeeId, PTGross, ProfessionalTax, CompanyId 
										,CreatedBy)
							SELECT		@Month, @Year, @EmployeeId, GrossWages, PT, @CompanyId, @LoginUserId
							FROM		#Temp;
						END 

						SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentAliasName,0)), ', ')
						FROM	SalaryComponentsDetails SCD 
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	StatusActive = 1 
						AND		SalaryComponentTypeId = 1; 

						SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentAliasName,'')), ', ')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	StatusActive = 1 
						AND		SalaryComponentTypeId = 2;

						SELECT	@EarningsSumColumns = ISNULL(STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentAliasName),0) + ', 0))', ' + '),'')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 1
						AND		StatusActive = 1;

						SELECT	@DeductionsSumColumns = ISNULL(STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentAliasName),0) + ', 0))', ' + '),'')
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 2
						AND		SCD.ComponentAliasNameId NOT IN (5)
						AND		StatusActive = 1;
			
						SELECT	@EarningsCount = COUNT(SalaryComponentsId)
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 1
						AND		StatusActive = 1;

						SELECT	@DeductionsCount = COUNT(SalaryComponentsId)
						FROM	SalaryComponentsDetails SCD
						JOIN	ComponentAliasNameDetails CAND
							ON	SCD.ComponentAliasNameId = CAND.ComponentAliasNameId
						WHERE	SalaryComponentTypeId = 2
						AND		StatusActive = 1;

						WITH OrderedEarnings 
						AS	(
								SELECT	COLUMN_NAME
										,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
								FROM	INFORMATION_SCHEMA.COLUMNS
								WHERE	TABLE_NAME = 'PaySlipDetails_1' 
								AND		COLUMN_NAME LIKE 'Com_Earning_%')
						SELECT	@EarningsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
						FROM	(SELECT TOP (@EarningsCount) COLUMN_NAME FROM OrderedEarnings ORDER BY ColumnNumber) AS SortedEarnings;

						WITH OrderedDeductions
						AS	(
								SELECT	COLUMN_NAME
										,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
								FROM	INFORMATION_SCHEMA.COLUMNS
								WHERE	TABLE_NAME = 'PaySlipDetails_1' 
								AND		COLUMN_NAME LIKE 'Com_Deduction_%')
						SELECT	@DeductionsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
						FROM	(SELECT TOP (@DeductionsCount) COLUMN_NAME FROM OrderedDeductions ORDER BY ColumnNumber) AS SortedEarnings;
					   
						SET @SQL 
							= '	INSERT INTO PaySlipDetails_1 ([Month], [Year], EmployeeId, EffectiveWorkDays, PresentDays, LOP, ' 
											+ @EarningsInsertColumns_Payslip + ', ' + @DeductionsInsertColumns_Payslip + ', 
											ClaimAmount, TotalEarnings, AdvanceAmount, LoanDueAmount, OtherDeduction
											,TotalDeduction, NetPay, PaymentTypeId, PayslipStatus, CompanyId, CreatedBy)
								SELECT	T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.TotalWorkingDays
										,T1.Remaining, ' + @EarningsColumns + ', ' + @DeductionsColumns + ', TotalClaimAmount,
										(' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) AS TotalEarnings,
										TotalAdvanceAmount, TotalLoanAmount, 0
										,(' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount)) AS TotalDeductions,
										((' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) - (' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount))) AS NetPay
										,E.PaymentTypeId, 1, @CompanyId, @LoginUserId
								FROM	#ResultSet_1 T1
								LEFT JOIN ##ResultSet_2 E
									ON	T1.EmployeeId = E.EmployeeId
								GROUP BY T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.Remaining
										,E.PaymentTypeId, TotalClaimAmount, TotalAdvanceAmount, TotalLoanAmount
										,Remaining, PerDaySalary, TotalWorkingDays
										,' + @EarningsColumns + ', ' + @DeductionsColumns + '';

						--PRINT @SQL
						EXEC SP_EXECUTESQL @SQL, N'@CompanyId TINYINT, @LoginUserId INT'
											,@LoginUserId = @LoginUserId
											,@CompanyId = @CompanyId;

				END
				IF @@TRANCOUNT > 0
				COMMIT TRAN
				SELECT	@Status		= 1
						,@Message	= 'PaySlip Generated Successfully.'; 
			SET @Start = @Start + 1;
			END
		END
		Thexit:
			RETURN;
	END TRY
	BEGIN CATCH	
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END     
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GeneratePaySlipDetails_Test]	@LoginUserId = 1
													,@Month		 = 1
													,@Year		 = 2025
													,@Status	 = @S_Status	OUT
													,@Message	 = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT * FROM PaySlipDetails_1;
	SELECT * FROM [dbo].[PayslipPFDetails];
	SELECT * FROM [dbo].[PayslipESIDetails];
	SELECT * FROM [dbo].[PayslipPTDetails];
	SELECT * FROM [dbo].[EmployeeDetails];
	 
	TRUNCATE TABLE PayslipDetails_1;
	TRUNCATE TABLE [dbo].[PayslipPFDetails]
	TRUNCATE TABLE [dbo].[PayslipESIDetails]
	TRUNCATE TABLE [dbo].[PayslipPTDetails] 
=====================================================================================================================*/	
GO
/****** Object:  StoredProcedure [dbo].[USP_GeneratePaySlipDetails_Test_1]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=============================================================================================================================================================================  
 Procedure Name		:	[USP_GeneratePaySlipDetails]
 Description		:	Procedure used to insert into the new PaySlipDetails table(INSERT INTO PaySlipDetails from the given SELECT List Columns)
 Input Parameter	:	@LoginUserId ,@Month ,@Year
 Parameters			:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	25-04-2023
 Version			:	1.0 
 Comment			:	1. IF NOT EXISTS,Then 
							1.1 Insert into PaySlipDetails table with 
									Month				AS @Month
									,Year				AS @Year
									,EmployeeId			AS @EmployeeId
									,EffectiveWorkDays	AS @EffectiveWorkDays
									,LOP				AS @LOP
									,BasicPay			AS @BasicPay
									,HRA				AS @HRA
									,OtherAllowance		AS @OtherAllowance
									,PF					AS @PF
									,ESI				AS @ESI
									,IncomeTax			AS @IncomeTax
									,LeaveDeduction		AS @LeaveDeduction
									,TotalEarning		AS @TotalEarning
									,TotalDeduction		AS @TotalDeduction
									,NetPay				AS @NetPay
									,PaymentMode		AS @PaymentMode
									,AdvanceAmount		AS @AdvanceAmount
									,LoanDueAmount		AS LoanDueAmount
									,CompanyId			AS CompanyId
									,CreatedBy			AS @LoginUserId
									,CreatedDate		AS GETDATE() for new PaySlip From the given columns on SELECT statement.
							1.2 Insert into NotificationDetails table for the process of Message and notification to the owner
							1.3 Insert into NotificationDetails table for the process of Message and notification to the employees
						2. Then through the Success POPUP message as 'The PaySlipDetails have been Inserted Successfully'.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GeneratePaySlipDetails_Test_1]
(
	@LoginUserId	INT
	,@Month			INT
	,@Year			INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId							TINYINT
			,@EffectiveWorkDays					INT
			,@Holidays							INT
			,@WeekEnds							INT
			,@EmployeeId						INT		 
			,@Start								INT
			,@End								INT
			,@EmployeeTypeId					TINYINT	 	
			,@EarningsCount						INT
			,@DeductionsCount					INT
			,@EarningsInsertColumns_Payslip		NVARCHAR(MAX)
			,@DeductionsInsertColumns_Payslip	NVARCHAR(MAX)
			,@EarningsSumColumns				NVARCHAR(MAX)
			,@DeductionsSumColumns				NVARCHAR(MAX)
			,@EarningsColumns					NVARCHAR(MAX)
			,@DeductionsColumns					NVARCHAR(MAX)
			,@SQL								NVARCHAR(MAX)
			,@PaymentTypeId						TINYINT
			,@StartDate							DATETIME = DATEFROMPARTS(@Year, @Month, '01')
			,@EndDate							DATETIME = EOMONTH(DATEFROMPARTS(@Year, @Month, '01'));

	SELECT	@CompanyId = CompanyId 	
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId; 

	SELECT	@Holidays = COUNT(HoliDayId) 
	FROM	[dbo].[HoliDayDetails] HD
	WHERE	MONTH(HolidayDate) = @Month 
	AND		YEAR(HolidayDate) = @Year
	AND		CompanyId = @CompanyId
	AND		DATENAME(DW,HolidayDate) NOT IN (SELECT [Day] FROM CompanyWorkingDayDetails WHERE IsWorkingDay = 0);

	SELECT	@EffectiveWorkDays = DAY(EOMONTH(DATEFROMPARTS(@Year,@Month,'01'))); 

	WITH Calendar
	AS	(
			SELECT	CAST(DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, DATEFROMPARTS(@Year, @Month, 1)) AS DATE) AS Date,
					ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS RowNum
			FROM	master.dbo.spt_values
			WHERE	TYPE = 'P'
	)
	SELECT	@WeekEnds = COUNT(*) 
	FROM	Calendar C
	JOIN	CompanyWorkingDayDetails W
		ON	DATENAME(DW,C.[Date]) = W.[Day]
	WHERE	W.IsWorkingDay = 0
	AND	C.RowNum <= DAY(EOMONTH(DATEFROMPARTS(@Year, @Month, 1)));

	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id			INT		IDENTITY(1,1)
		,PunchDate	DATE
		,CompanyId	TINYINT
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance(PunchDate, CompanyId) 
		VALUES	(@StartDate,@CompanyId);

		SET	@StartDate = DATEADD(DAY,1, @StartDate);
	END;

	DROP TABLE IF EXISTS #EmpDetails;
	CREATE TABLE #EmpDetails
	(
		Id					INT IDENTITY(1,1)
		,EmployeeId			INT
		,EmployeeTypeId		TINYINT
	)
	INSERT INTO	#EmpDetails(EmployeeId, EmployeeTypeId)
	SELECT	EmployeeId, EmployeeTypeId
	FROM	[dbo].[EmployeeDetails] 
	WHERE	IsActive = 1;

	SELECT	@Start	= MIN(Id)
			,@End	= MAX(Id)
	FROM	#EmpDetails;

	BEGIN TRY
		IF NOT EXISTS ( SELECT 1 FROM [dbo].[PaySlipDetails] WHERE [Month] = @Month AND [Year] = @Year AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
		BEGIN 
			BEGIN TRAN 
				WHILE @Start <= @End
				BEGIN
					SELECT	@EmployeeId = EmployeeId 
							,@EmployeeTypeId = EmployeeTypeId
					FROM	#EmpDetails
					WHERE	Id = @Start;

					DROP TABLE IF EXISTS #ResultSet_1;
					SELECT	EmployeeId
							,EmployeeName
							,[Month]
							,[Year]
							,EffectiveWorkDays
							,Holidays
							,WeekEnds
							,SUM(ISNULL(TotalTakenLeave,0)) AS TotalTakenLeave
							,SUM(ISNULL(TakenPermission,0)) AS TakenPermission
							,SUM(ISNULL(TakenCompOff,0)) AS TakenCompOff
							,SUM(ISNULL(TotalWorkingDays,0)) AS TotalWorkingDays
							,(EffectiveWorkDays - SUM(TotalWorkingDays)) AS Remaining
							,SUM(ISNULL(TotalClaimAmount,0)) AS TotalClaimAmount
							,SUM(ISNULL(TotalAdvanceAmount,0)) AS TotalAdvanceAmount
							,SUM(ISNULL(TotalLoanAmount,0)) AS TotalLoanAmount
					INTO	#ResultSet_1 
					FROM	(
								SELECT	DISTINCT AT.PunchDate AS [Date]
										,ED.EmployeeId	
										,CONCAT(FirstName, ' ', LastName) AS EmployeeName
										,@Month AS [Month]
										,@Year AS [Year]
										,@EffectiveWorkDays AS EffectiveWorkDays
										,@Holidays AS Holidays
										,@WeekEnds AS WeekEnds
										,ISNULL(TotalTakenLeave,0) AS TotalTakenLeave
										,ISNULL(NoOfHours,0) AS TakenPermission
										,ISNULL(TakenCompOff,0) AS TakenCompOff
										,CASE	WHEN IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
												WHEN IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
												WHEN IsHalfDay = 1 AND IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
												WHEN IsHalfDay = 1 AND IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay > 480 THEN 1
												WHEN IsHalfDay = 1 AND IsFirstHalf = 0 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
												WHEN IsHalfDay = 1 AND IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay > 480 THEN 1
												WHEN LSD.LeaveTypeId = 2 AND TakenCompOff IS NOT NULL THEN 1
												WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) THEN 1
												WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
												WHEN WeekEndDays = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 1
												WHEN PD.EmployeeId IS NULL AND PH.InTime IS NOT NULL AND TotalMinutesPerDay IS NOT NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 1 
												WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
												AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') < '04:00' THEN 0.5
												WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 0.5
												WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 0.5 
												WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay IS NOT NULL AND TotalMinutesPerDay < 480 THEN 1
											ELSE 0
										END AS TotalWorkingDays
										,ISNULL(TotalClaimAmount,0) AS TotalClaimAmount
										,ISNULL(TotalAdvanceAmount,0) AS TotalAdvanceAmount
										,ISNULL(TotalLoanAmount,0) AS TotalLoanAmount
								FROM	(	SELECT	EmployeeId, FirstName, LastName, CompanyId
											FROM	[dbo].[EmployeeDetails]
											WHERE	EmployeeId = @EmployeeId
										) AS ED
								CROSS JOIN #Attendance AT
								LEFT JOIN (
											SELECT	CompanyId, IsWorkingDay, [Day]
													,CASE WHEN IsWorkingDay = 0 THEN 0 ELSE 1 END AS WeekEndDays	
											FROM	[dbo].[CompanyWorkingDayDetails]
											WHERE	IsWorkingDay = 0
											AND		CompanyId = @CompanyId
										  ) AS CWDD
									ON	CWDD.CompanyId = ED.CompanyId
									AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
								LEFT JOIN [dbo].[HolidayDetails] HD
									ON	AT.PunchDate = HD.HolidayDate
								LEFT JOIN (	
											SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
											FROM	[dbo].[EmployeeShiftMappingDetails] ESMD
											JOIN	[dbo].[EmployeeDetails] ED
												ON	ESMD.EmployeeId = ED.EmployeeId
											LEFT JOIN [dbo].[ShiftDetails] SD
												ON	SD.ShiftId = ESMD.ShiftId 
											) AS ESMD
									ON	ED.EmployeeId = ESMD.EmployeeId 
									AND AT.PunchDate BETWEEN StartDate AND EndDate
								LEFT JOIN	(	
											SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
													,MAX(OutTime) AS OutTime
													,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
													,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
											FROM	(
														SELECT	ED.EmployeeId
																,PunchDate
																,CONVERT(TIME,PunchTime) AS InTime
																,[Status]
																,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																		AND CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
																	WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																		AND CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
																	ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime))
																END) AS OutTime
														FROM	[dbo].[EmployeeDetails] ED	
														JOIN	[dbo].[AttendanceLogDetails] ALD	
															ON	ED.EmployeeId = ALD.EmployeeId 
														WHERE	ED.EmployeeId = @EmployeeId
														AND		MONTH(PunchDate) = @Month
														AND		YEAR(PunchDate) = @Year
													) AS ALD
											WHERE	[Status] = 1
											GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate)
										) PH
									ON	ED.EmployeeId = PH.EmployeeId
									AND AT.PunchDate = PH.PunchDate
								LEFT JOIN	(
												SELECT	EmployeeId, FromDate, ToDate, NoOfDays AS TotalTakenLeave
														,IsHalfDay, IsFirstHalf, LeaveStatusId
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
													AND	LeaveStatusId = 3
													AND	LeaveTypeId <> 2
													AND	(MONTH(FromDate) = @Month
													OR	MONTH(ToDate) = @Month)
													AND	(YEAR(FromDate) = @Year
													OR	YEAR(ToDate) = @Year)
											) AS LD
									ON	ED.EmployeeId = LD.EmployeeId
									AND AT.PunchDate BETWEEN LD.FromDate AND LD.ToDate
								LEFT JOIN	(
												SELECT	EmployeeId, PermissionDate
														,DATEDIFF(MINUTE,StartTime,EndTime) AS NoOfHours
												FROM	[dbo].[PermissionDetails]
												WHERE	EmployeeId = @EmployeeId
													AND	PermissionStatusId = 3
													AND	MONTH(PermissionDate) = @Month
													AND	YEAR(PermissionDate) = @Year
											) AS PD
									ON	ED.EmployeeId = PD.EmployeeId
									AND	AT.PunchDate = PD.PermissionDate
								LEFT JOIN	(
												SELECT	EmployeeId, FromDate AS [Date], LeaveTypeId
														,NoOfDays AS TakenCompOff
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
													AND	LeaveStatusId = 3 AND LeaveTypeId = 2
													AND	(MONTH(FromDate) = @Month OR MONTH(ToDate) = @Month)
													AND	(YEAR(FromDate) = @Year OR YEAR(ToDate) = @Year)
											) AS LSD
									ON	ED.EmployeeId = LSD.EmployeeId
									AND AT.PunchDate = LSD.[Date]
								LEFT JOIN	(
												SELECT	RequestedBy, ClaimDate, ApprovedAmount AS TotalClaimAmount
												FROM	[dbo].[ClaimDetails]
												WHERE	RequestedBy = @EmployeeId AND ClaimStatusId = 3
												AND		MONTH(ClaimDate) = @Month AND YEAR(ClaimDate) = @Year
											) AS CD
									ON	ED.EmployeeId = CD.RequestedBy
									AND AT.PunchDate = CD.ClaimDate
								LEFT JOIN	(
												SELECT	EmployeeId, AdvanceDate, AdvanceAmount AS TotalAdvanceAmount
												FROM	[dbo].[AdvanceDetails]
												WHERE	EmployeeId = @EmployeeId AND AdvanceStatusId = 3
												AND		MONTH(AdvanceDate) = @Month AND	YEAR(AdvanceDate) = @Year 
											) AS AD
									ON	ED.EmployeeId = AD.EmployeeId
									AND AT.PunchDate = AD.AdvanceDate
								LEFT JOIN	(
												SELECT	EmployeeId, LoanDate, LoanDueAmount AS TotalLoanAmount
												FROM	[dbo].[LoanDetails] LD
												JOIN	[dbo].[LoanDueDetails] LDD
													ON	LD.LoanId = LDD.LoanId
												WHERE	EmployeeId = @EmployeeId AND LoanStatusId = 3
													AND	MONTH(LoanDate) = @Month AND YEAR(LoanDate) = @Year 
											) AS LND
									ON	ED.EmployeeId = LND.EmployeeId
									AND AT.PunchDate = LND.LoanDate
							) AS  A
					GROUP BY EmployeeId, EmployeeName, [Month], [Year], EffectiveWorkDays, Holidays, WeekEnds;

					SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentName,0)), ', ')
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1 
					AND		SalaryComponentTypeId = 1; 

					SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(ISNULL(ComponentName,'')), ', ')
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1 
					AND		SalaryComponentTypeId = 2;

					SET @SQL 
					= '	DROP TABLE IF EXISTS ##ResultSet_2;
						SELECT	EmployeeId, MonthlyIncome, PerDaySalary
								, ' + @EarningsColumns + ', ' + @DeductionsColumns + '
								,PaymentTypeId
						INTO	##ResultSet_2
						FROM	(
									SELECT EmployeeId, MonthlyIncome, PerDaySalary, ComponentName
											,ISNULL(ActualValue,0) AS ActualValue, PaymentTypeId
									FROM	(
												SELECT	EmployeeId, MonthlyIncome, PerDaySalary, ComponentName
														,CONVERT(NUMERIC(11,2),(ActualValue)) AS ActualValue
														,PaymentTypeId
												FROM	(
															SELECT	ED.EmployeeId
																	,CONVERT(NUMERIC(11,2), SUM(CTC) / 12) AS MonthlyIncome
																	,CONVERT(NUMERIC(11,2), SUM(CTC) / 12 / @EffectiveWorkDays) AS PerDaySalary
																	,ComponentName
																	,TotalWorkingDays
																	,PaymentTypeId
																	,ISNULL(CASE WHEN EarningType = ''%'' 
																				THEN CONVERT(NUMERIC(11,2), (SUM(CTC) * (EarningAmount/100)) / 12)  
																				ELSE CONVERT(NUMERIC(11,2), (SUM(CTC) * EarningAmount) / 12) 
																	END,0) AS ActualValue
															FROM	[dbo].[SalaryStructureDetails] SSD
															JOIN	[dbo].[SalaryStructureComponentMappingDetails] SSCMD
																ON	SSD.SalaryStructureId = SSCMD.SalaryStructureId
															JOIN	[dbo].[SalaryComponentsDetails] SCD
																ON	SCD.SalaryComponentsId = SSCMD.SalaryComponentsId
															JOIN	[dbo].[EmployeeTypeStructureMappingDetails] ESMD 
																ON	ESMD.SalaryStructureId = SSD.SalaryStructureId 
															JOIN	[dbo].[EmployeeDetails] ED 
																ON	ED.EmployeeTypeId = ESMD.EmployeeTypeId
															JOIN	[dbo].[EmployeeSalaryDetails] ESD 
																ON	ED.EmployeeId = ESD.EmployeeId
															JOIN	#ResultSet_1 RD
																ON	RD.EmployeeId = ED.EmployeeId
															WHERE	ESMD.EmployeeTypeId = @EmployeeTypeId
																AND	SSCMD.IsActive = 1
																AND	SCD.StatusActive = 1
																AND	ED.EmployeeId = @EmployeeId
															GROUP BY ED.EmployeeId, ComponentName, EarningType, EarningAmount
																	,RD.TotalWorkingDays, PaymentTypeId
														) AS S
											) AS A
								) AS SourceTable
						PIVOT	(MAX(ActualValue) 
						FOR		ComponentName 
						IN		(' + @EarningsColumns + ', ' + @DeductionsColumns + ')) AS PivotTable; '

					PRINT @SQL;
					EXEC SP_EXECUTESQL @SQL, N'	@EffectiveWorkDays INT, @EmployeeId INT, @EmployeeTypeId TINYINT'
												,@EffectiveWorkDays, @EmployeeId, @EmployeeTypeId;
										
					SELECT	@EarningsSumColumns = STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentName),0) + ', 0))', ' + ')
							,@EarningsCount = COUNT(SalaryComponentsId)
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	SalaryComponentTypeId = 1
						AND	StatusActive = 1;

					SELECT	@DeductionsSumColumns = STRING_AGG('SUM(ISNULL(' + ISNULL(QUOTENAME(ComponentName),0) + ', 0))', ' + ')
							,@DeductionsCount = COUNT(SalaryComponentsId)
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	SalaryComponentTypeId = 2
						AND	StatusActive = 1;

					WITH EarningColumnDetails 
					AS	(
							SELECT	COLUMN_NAME
									,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
							FROM	INFORMATION_SCHEMA.COLUMNS
							WHERE	TABLE_NAME = 'PayslipDetails' 
							AND		COLUMN_NAME LIKE 'Com_Earning_%'
						)
					SELECT	@EarningsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
					FROM	(SELECT TOP (@EarningsCount) COLUMN_NAME FROM EarningColumnDetails ORDER BY ColumnNumber) AS Earnings;

					WITH DeductionColumnDetails
					AS	(
							SELECT	COLUMN_NAME
									,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
							FROM	INFORMATION_SCHEMA.COLUMNS
							WHERE	TABLE_NAME = 'PayslipDetails' 
							AND		COLUMN_NAME LIKE 'Com_Deduction_%'
						)
					SELECT	@DeductionsInsertColumns_Payslip = STRING_AGG(QUOTENAME(COLUMN_NAME), ', ')
					FROM	(SELECT TOP (@DeductionsCount) COLUMN_NAME FROM DeductionColumnDetails ORDER BY ColumnNumber) AS Deduction;

					SET @SQL 
					= '	INSERT INTO [dbo].[PayslipDetails] ([Month], [Year], EmployeeId, EffectiveWorkDays
									,LOP, '+ @EarningsInsertColumns_Payslip + ', ' + @DeductionsInsertColumns_Payslip + ', 
									ClaimAmount, TotalEarnings, AdvanceAmount, LoanDueAmount, OtherDeduction
									,TotalDeduction, NetPay, PaymentMode, PayslipStatus, CompanyId, CreatedBy)
						SELECT	T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.Remaining,
								' + @EarningsColumns + ', ' + @DeductionsColumns + ', TotalClaimAmount,
								(' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) AS TotalEarnings,
								TotalAdvanceAmount, TotalLoanAmount, CASE WHEN Remaining = 0.00 THEN 0 ELSE (PerDaySalary * ISNULL(Remaining,0)) END, 
								(' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount) + CASE WHEN Remaining = 0.00 THEN 0 ELSE (PerDaySalary * ISNULL(Remaining,0)) END) AS TotalDeductions,
								((' + @EarningsSumColumns + ' + SUM(TotalClaimAmount)) - (' + @DeductionsSumColumns + ' + SUM(TotalAdvanceAmount) + SUM(TotalLoanAmount) + CASE WHEN Remaining = 0.00 THEN 0 ELSE (PerDaySalary * ISNULL(Remaining,0)) END)) AS NetPay
								,E.PaymentTypeId, 1, @CompanyId, @LoginUserId
						FROM	#ResultSet_1 T1
						LEFT JOIN ##ResultSet_2 E
							ON	T1.EmployeeId = E.EmployeeId
						GROUP BY T1.[Month], T1.[Year], T1.EmployeeId, T1.EffectiveWorkDays, T1.Remaining
								,E.PaymentTypeId, TotalClaimAmount, TotalAdvanceAmount, TotalLoanAmount
								,Remaining, PerDaySalary,' + @EarningsColumns + ', ' + @DeductionsColumns + '';

						PRINT @SQL;
						EXEC SP_EXECUTESQL @SQL, N'@CompanyId TINYINT, @LoginUserId INT', @LoginUserId, @CompanyId;
					SET @Start = @Start+1;	
				END
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'PaySlip Generated Successfully.'; 
		END
	END TRY
	BEGIN CATCH	
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END     
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GeneratePaySlipDetails_Test_1]	@LoginUserId = 1
													,@Month		 = 1
													,@Year		 = 2025
													,@Status	 = @S_Status	OUT
													,@Message	 = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM PaySlipDetails
	SELECT * FROM EmployeeDetails
	
	SELECT * FROM AdvanceDetails
	TRUNCATE TABLE PayslipDetails;
=====================================================================================================================*/	
GO
/****** Object:  StoredProcedure [dbo].[USP_GetAdvanceDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetAdvanceDetails]
 Description		:	Procedure used to retrieve the AdvanceDetails (When click on the Advance in SideNavigationBar 
						                                              And When Click On Edit Option On Grid in Advance screen)
 Input Parameter	:	@LoginUserId,@AdvanceId,@FromDate,@ToDate
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	29.08.2023
 Version			:	1.0 
 Comment			:	1.If the given @AdvanceId is NULL,
							1.1 When @UserGroupId Is an SuperAdmin(1)
							   1.1.1 Get the All Counter Box Values have the column of 
							             @OverAllAdvance AS  OverAllAdvance
							            ,@OverAllDue     AS  OverAllDue
							            ,@NoOfRequest    AS  NoOfRequest
							            ,@NoOfRejected   AS  NoOfRejected.					
							   1.1.2 Get All the AdvanceDetails Have the column as AdvanceId, Date, EmployeeId, EmployeeImage
								     ,Employee, AdvanceAmount, DueAmount,AdvanceStatusId,Status, Status_Colour, ApprovedPersonImage, ApprovedBy
								      to show in Grid.
							  1.1.3 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						   2.1 When @UserGroupId Is an GeneralUser(2,3),then 
							  2.1.1 Get the All Counter Box Values have the column of 
							             @OverAllAdvance AS  OverAllAdvance
							            ,@OverAllDue     AS  OverAllDue
							            ,@NoOfRequest    AS  NoOfRequest
							            ,@NoOfRejected   AS  NoOfRejected to show in Counter box.	
							  2.1.2 Get All the AdvanceDetails Have the column as AdvanceId, Date, AdvanceAmount,DueAmount,Status,
										Status_Colour, ApprovedPersonImage, ApprovedBy to show in Grid.
							  2.1.3 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						3. If the given @AdvanceId is Not Null,then 
							3.1 Get the AdvanceDetails with the column of EmployeeId, EmployeeName,AdvanceId, AdvanceDate, 
								AdvanceAmount, DueAmount, AdvanceStatusId, AdvanceStatusName, Description for given @AdvanceId 
								to show the values in popup.
							3.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
======================================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAdvanceDetails]
(	
	@LoginUserId	INT
	,@AdvanceId		INT
	,@FromDate		DATE
	,@Mine			BIT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId			TINYINT
			,@OverAllAdvance	NUMERIC(11,2)
			,@CompletedDue		NUMERIC(11,2)
			,@OverAllDue		NUMERIC(11,2)
			,@NoOfRequest		INT
			,@NoOfRejected		INT
			,@UserGroupId		TINYINT
			,@ToDate			DATE;

	SET @ToDate = EOMONTH(@FromDate);
	
	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		--If the given @AdvanceId is Null, then Get the All the AdvanceDetails.
		IF @AdvanceId IS NULL 	
		BEGIN
			--Logic For OverallAdvance.
			SELECT	@OverAllAdvance = SUM(ISNULL((AdvanceAmount),0))
			FROM	[dbo].[AdvanceDetails]
			WHERE	AdvanceStatusId = 3
			AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
			AND		EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;

			--Logic for CompletedDues.
			SELECT	@CompletedDue = ISNULL(SUM(AdvanceAmount),0)
			FROM	[dbo].[PaySlipDetails] 
			WHERE	CompanyId = @CompanyId
			AND		EmployeeId = @LoginUserId;

			--Logic For OverallDue
			SELECT @OverAllDue = ISNULL(@OverAllAdvance,0) - ISNULL(@CompletedDue,0);

			--Logic For NoOfRequest.
			SELECT	@NoOfRequest = COUNT(AdvanceId)
			FROM	[dbo].[AdvanceDetails]
			WHERE	AdvanceStatusId = 2
			AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
			AND		EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;

			--Logic For NoOfRejected.
			SELECT	@NoOfRejected = COUNT(EmployeeId)
			FROM	[dbo].[AdvanceDetails]
			WHERE	AdvanceStatusId = 4
			AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
			AND		EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;

			--Result set for counter box.
			SELECT	CONCAT(N'₹ ',ISNULL(@OverAllAdvance,0))		AS  'Total Advance'
					,CONCAT(N'₹ ',@OverAllDue)					AS  'Total Due'
					,@NoOfRequest								AS  'No Of Request'
					,@NoOfRejected								AS  'No Of Rejected';

			IF @UserGroupId IN (1,2)
			BEGIN
				IF @Mine = 1
				BEGIN
					SELECT	AD.AdvanceId
							,LEFT(CONVERT(NVARCHAR(50),AD.AdvanceDate,113),11) AS [Date]
							,CONCAT(N'₹ ',AD.AdvanceAmount) AS AdvanceAmount
							,CONCAT(N'₹ ',ISNULL (DueAmount,0)) AS DueAmount
							,AdvanceStatusId  AS StatusId
							,LSD.LeaveStatusName AS [Status]
							,CASE	WHEN LSD.LeaveStatusName = 'Draft' THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Submitted' THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved' THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected' THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled' THEN 'Black'
								ELSE ' '
							END AS Status_Colour
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(AVD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CONCAT(AVD.FirstName,' ',AVD.LastName),'') 
								ELSE '' 
							END AS ApprovedBy
					FROM	[dbo].[AdvanceDetails] AD
					JOIN	[dbo].[EmployeeDetails] ED
						ON	AD.EmployeeId = ED.EmployeeId
					LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	AD.AdvanceStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	AdvanceId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[AdvanceDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
									WHERE LD.CompanyId = @CompanyId
							) AS AVD
						ON	AVD.AdvanceId = AD.AdvanceId
					WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
						AND		AD.EmployeeId=@LoginUserId
					AND		AD.CompanyId = @CompanyId
					ORDER BY AD.AdvanceId DESC; 
				END
				ELSE
				BEGIN
					--Result set for Grid.
					SELECT	AD.AdvanceId
							,LEFT(CONVERT(NVARCHAR(50),AD.AdvanceDate,113),11) AS [Date]
							,AD.EmployeeId
							,RPD.EmployeeImage AS EmpImage
							,Employee					
							,CONCAT(N'₹ ',AD.AdvanceAmount) AS AdvanceAmount
							,CONCAT(N'₹ ',ISNULL (DueAmount,0)) AS DueAmount
							,AdvanceStatusId  AS StatusId
							,LSD.LeaveStatusName AS [Status] 
							,CASE	WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
							ELSE 'Orange'
							END AS [Status_Colour]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(AVD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CONCAT(AVD.FirstName,' ',AVD.LastName),'') 
								ELSE '' 
							END AS ApprovedBy
					FROM	[dbo].[AdvanceDetails] AD
					JOIN	(	SELECT	ED.DesignationId, ED.EmployeeId, ED.EmployeeImage
											,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee 
									FROM	[dbo].[Employeedetails] ED
									LEFT JOIN	[dbo].[Employeedetails] RPD
										ON	RPD.EmployeeId = ED.EmployeeId 
									WHERE	ED.ReportingPersonId = @LoginUserId
								) AS RPD
							ON	AD.EmployeeId = RPD.EmployeeId
					LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	AD.AdvanceStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	AdvanceId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[AdvanceDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
									WHERE LD.CompanyId = @CompanyId
							) AS AVD
						ON	AVD.AdvanceId = AD.AdvanceId
					WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
					AND		AD.CompanyId = @CompanyId
					AND		AdvanceStatusId NOT IN (1, 5)
					ORDER BY AD.AdvanceId DESC; 
				END
			END
			ELSE
			BEGIN
				--Result set for Grid.
				SELECT	AD.AdvanceId
						,LEFT(CONVERT(NVARCHAR(50),AD.AdvanceDate,113),11) AS [Date]
						,CONCAT(N'₹ ',AD.AdvanceAmount) AS AdvanceAmount
						,CONCAT(N'₹ ',ISNULL (DueAmount,0)) AS DueAmount
						,AdvanceStatusId  AS StatusId
						,LSD.LeaveStatusName AS [Status]
						,CASE	WHEN LSD.LeaveStatusName = 'Draft' THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Submitted' THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Approved' THEN 'Green'
								WHEN LSD.LeaveStatusName = 'Rejected' THEN 'Red'
								WHEN LSD.LeaveStatusName = 'Cancelled' THEN 'Black'
							ELSE ' '
						END AS Status_Colour
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(AVD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CONCAT(AVD.FirstName,' ',AVD.LastName),'') 
								ELSE '' 
							END AS ApprovedBy
				FROM	[dbo].[AdvanceDetails] AD
				JOIN	[dbo].[EmployeeDetails] ED
					ON	AD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	AD.AdvanceStatusId = LSD.LeaveStatusId
				LEFT JOIN (	SELECT	AdvanceId, EmployeeImage, FirstName, LastName
							FROM	[dbo].[AdvanceDetails] LD
							JOIN	[dbo].[Employeedetails] ED
								ON	LD.UpdatedBy = ED.EmployeeId 
								WHERE LD.CompanyId = @CompanyId
						) AS AVD
					ON	AVD.AdvanceId = AD.AdvanceId
				WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
					AND		AD.EmployeeId=@LoginUserId
				AND		AD.CompanyId = @CompanyId
				ORDER BY AD.AdvanceId DESC; 
			END
		END
		ELSE
		BEGIN
			--If the given @AdvanceId is Not Null,then get the particular AdvanceDetail.
			SELECT	AD.AdvanceId
					,ED.EmployeeId
					,CONCAT(ED.FirstName , ' ',ED.LastName) AS  EmployeeName	
					,CONVERT(NVARCHAR(50),AD.AdvanceDate,105) AS AdvanceDate
					,AdvanceAmount
					,ISNULL(DueAmount,0) AS DueAmount
					--,(SELECT (SELECT AdvanceMaxAmount
					--		   FROM [PayrollSettingDetails] 
					--		   WHERE AdvanceId = @AdvanceId) - AdvanceAmount) AS RemainingAmount
					,AdvanceStatusId 
					,LeaveStatusName AS AdvanceStatusName
					,ISNULL(AD.[Description],'') AS [Description]
					,CONVERT(NVARCHAR(50),AD.CreatedDate,105) AS CreatedDate
					,ISNULL(Comments,' ') AS Comments
			FROM	[dbo].[AdvanceDetails] AD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	AD.EmployeeId = ED.EmployeeId
			LEFT JOIN [dbo].[LeaveStatusDetails] LSD
				ON	AD.AdvanceStatusId = LSD.LeaveStatusId 
			WHERE	(AdvanceId = @AdvanceId)
			AND		(AD.CompanyId = @CompanyId);
		END
		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetAdvanceDetails]	@LoginUserId	= 1
										,@AdvanceId		= NULL
										,@FromDate		= '2024-10-01' 
										,@Mine			= 0
										,@Status		= @S_Status	 OUT
										,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	AdvanceDetails;	

	SELECT * 
	FROM	EmployeeDetails
=================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetAdvanceLimitDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetAdvanceLimitDetails]
 Description		:	Procedure used to retrieve the Advance / Loan Limit and Due Amount Details 
															   (When select the employee Dropdown in Advance, Loan Save popup)
 Input Parameter	:	@LoginUserId,@EmployeeId,@Module
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	21-11-2024
 Version			:	1.0 
 Comment			:	1. To get the advance and loan Maximum amount for the given input parameter @EmployeeId, @Module.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.
============================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAdvanceLimitDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@ModuleId		INT			
	,@Module		NVARCHAR(50)
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE	@LoginUserId	INT				= 3
	--		,@EmployeeId	INT				= 3
	--		,@ModuleId		INT				= 1
	--		,@Module		NVARCHAR(50)	= 'Advance'

	DECLARE	@CompanyId		TINYINT
			,@LimitAmount	NUMERIC(11,2)
			,@DueAmount		NUMERIC(11,2)
			,@AdvanceAmount	NUMERIC(11,2);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	
	BEGIN TRY	
		IF @Module = 'Advance'
		BEGIN
			IF NOT EXISTS (SELECT AdvanceLimit FROM [dbo].[PayrollsettingDetails] WHERE	CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status		= 0
						,@Message	= 'AdvanceLimit Not set.';
				RETURN;
			END
			ELSE IF NOT EXISTS (SELECT CTC FROM [dbo].[EmployeeSalaryDetails] WHERE	EmployeeId = @EmployeeId)
			BEGIN 
				SELECT	@Status		= 0
						,@Message	= 'CTC Not set.';
				RETURN;
			END 
			ELSE IF @ModuleId IS NULL
			BEGIN
				SELECT	@LimitAmount = ((ISNULL(CTC,0) / 12) * (ISNULL(AdvanceLimit,0) / 100.0) - ISNULL(AdvanceAmount,0))
				FROM	[dbo].[PayrollsettingDetails] PSD
				JOIN	[dbo].[EmployeeDetails] ED 
					ON	PSD.CompanyId = ED.CompanyId
				JOIN	[dbo].[EmployeeSalaryDetails] ESD 
					ON	ED.EmployeeId = ESD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(AdvanceAmount,0)) AS AdvanceAmount
								FROM	[dbo].[AdvanceDetails] 
								WHERE	AdvanceStatusId IN (2, 3)
								AND		EmployeeId = @EmployeeId
								GROUP BY EmployeeId
							) AS AD 
					ON	ED.EmployeeId = AD.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;

				SELECT	@DueAmount = DueAmount
				FROM	[dbo].[AdvanceDetails] 
				WHERE	EmployeeId = @EmployeeId
				AND		AdvanceStatusId = 3
				AND		CompanyId = @CompanyId;

				SELECT	ISNULL(@LimitAmount,0)	AS LimitAmount
						,ISNULL(@DueAmount,0)	AS DueAmount;
			END
			ELSE 
			BEGIN 
				SELECT	@AdvanceAmount = ISNULL(AdvanceAmount,0)
						,@LimitAmount = ((ISNULL(CTC,0) / 12) * (ISNULL(AdvanceLimit,0) / 100.0) - ISNULL(AdvanceAmt,0))
				FROM	[dbo].[PayrollsettingDetails] PSD													
				JOIN	[dbo].[EmployeeDetails] ED 
					ON	PSD.CompanyId = ED.CompanyId
				JOIN	[dbo].[EmployeeSalaryDetails] ESD 
					ON	ED.EmployeeId = ESD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(AdvanceAmount,0)) AS AdvanceAmt
								FROM	[dbo].[AdvanceDetails] 
								WHERE	AdvanceStatusId IN (2, 3)
								AND		EmployeeId = @EmployeeId
								GROUP BY EmployeeId
							) AS AD 
					ON	ED.EmployeeId = AD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(AdvanceAmount,0)) AS AdvanceAmount
								FROM	AdvanceDetails AD1
								WHERE	AdvanceStatusId IN (2, 3)
								AND		EmployeeId = @EmployeeId
								AND		AdvanceId = @ModuleId
								GROUP BY EmployeeId
							) AS AD1
					ON	AD1.EmployeeId = ED.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;

				SELECT	@DueAmount = DueAmount
				FROM	[dbo].[AdvanceDetails] 
				WHERE	EmployeeId = @EmployeeId
				AND		AdvanceStatusId = 3
				AND		CompanyId = @CompanyId;

				SELECT	ISNULL(@AdvanceAmount,0)	AS AdvanceAmount
						,ISNULL(@LimitAmount,0)		AS LimitAmount
						,ISNULL(@DueAmount,0)		AS DueAmount;
			END 

		END
		ELSE IF @Module ='Loan'
		BEGIN
			IF NOT EXISTS (SELECT LoanLimit FROM [dbo].[PayrollsettingDetails] WHERE CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status = 0
						,@Message = 'LoanLimit Not set.'
				RETURN
			END
			ELSE IF NOT EXISTS (SELECT CTC FROM [dbo].[EmployeeSalaryDetails] WHERE	EmployeeId = @EmployeeId)
			BEGIN
				SELECT	@Status = 0
						,@Message = 'CTC Not set.'
				RETURN
			END

			IF @ModuleId IS NULL
			BEGIN
				SELECT	@LimitAmount = ((ISNULL(CTC,0) / 12) * ISNULL(LoanLimit,0) - ISNULL(LoanAmount,0))
				FROM	[dbo].[PayrollsettingDetails] PSD
				JOIN	[dbo].[EmployeeDetails] ED 
					ON	PSD.CompanyId = ED.CompanyId
				JOIN	[dbo].[EmployeeSalaryDetails] ESD 
					ON	ED.EmployeeId = ESD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(LoanAmount,0)) AS LoanAmount
								FROM	[dbo].[LoanDetails] 
								WHERE	LoanStatusId = 3
								AND		EmployeeId = @EmployeeId
								GROUP BY EmployeeId
							) AS LD 
					ON	ED.EmployeeId = LD.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;				

				SELECT	@DueAmount = DueAmount
				FROM	[dbo].[LoanDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		LoanStatusId = 3
				AND		CompanyId = @CompanyId;

				SELECT	ISNULL(@LimitAmount,0)	AS LimitAmount
						,ISNULL(@DueAmount,0)	AS DueAmount;
			END
			ELSE 
			BEGIN 
				SELECT	@AdvanceAmount = ISNULL(LoanAmount,0)
						,@LimitAmount = ((ISNULL(CTC,0) / 12) * ISNULL(LoanLimit,0) - ISNULL(LoanAmt,0))
				FROM	[dbo].[PayrollsettingDetails] PSD
				JOIN	[dbo].[EmployeeDetails] ED 
					ON	PSD.CompanyId = ED.CompanyId
				JOIN	[dbo].[EmployeeSalaryDetails] ESD 
					ON	ED.EmployeeId = ESD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(LoanAmount,0)) AS LoanAmt
								FROM	[dbo].[LoanDetails] 
								WHERE	LoanStatusId IN (2, 3)
								AND		EmployeeId = @EmployeeId
								GROUP BY EmployeeId
							) AS LD 
					ON	ED.EmployeeId = LD.EmployeeId
				LEFT JOIN	(	SELECT	EmployeeId, SUM(ISNULL(LoanAmount,0)) AS LoanAmount
								FROM	[dbo].[LoanDetails] 
								WHERE	LoanStatusId = 3
								AND		EmployeeId = @EmployeeId
								AND		LoanId = @ModuleId
								GROUP BY EmployeeId
							) AS LD1 
					ON	ED.EmployeeId = LD1.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;				

				SELECT	@DueAmount = DueAmount
				FROM	[dbo].[LoanDetails]
				WHERE	EmployeeId = @EmployeeId
				AND		LoanStatusId = 3
				AND		CompanyId = @CompanyId;

				SELECT	ISNULL(@AdvanceAmount,0)	AS AdvanceAmount
						,ISNULL(@LimitAmount,0)		AS LimitAmount
						,ISNULL(@DueAmount,0)		AS DueAmount;

			END 
		END

		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetAdvanceLimitDetails]	@LoginUserId	= 1
											,@EmployeeId	= 7
											,@ModuleId		= 1
											,@Module		= 'Loan'	
											,@Status		= @S_Status	 OUT
											,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[AdvanceDetails];
	SELECT * 
	FROM	[EmployeeDetails];
	SELECT * 
	FROM	LoanDetails 
	SELECT * 
	FROM	[EmployeeSalaryDetails];
=================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetAssetDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetAssetDetails]
 Description		:	Procedure used to retrieve the EmployeeAssetMappingDetails
														(1.When Click on the Asset in side navigation bar 
														 2.When click Edit option in grid from Asset Screen)
 Input Parameter	:	@LoginUserId, @AssetId
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	21-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @EmployeeAssetMappingId IS NULL, then
							1.1 To show the counter box values 
									1. @Total			AS Total
									2. @TotalEmployee	AS TotalEmployee
									3. @GivenAssets		AS GivenAssets
									4. @RemainingAssets	AS RemainingAssets to show the values in Counter Box.
							1.2 Get the EmployeeAssetMappingDetails table have the columns of EmployeeAssetMappingId
								,Date, EmployeeId, AssetType, AssetModel, SerialNumber, Condition, Date to show the 
								values in Grid.
							1.3 Then return the output parameter values @Status = 1 & @Message = NULL.
						2. If the Given @EmployeeAssetMappingId IS NOT NULL, then
							2.1 Get the EmployeeAssetMappingDetails table have the columns of EmployeeAssetMappingId
								,EmployeeId, AssetTypeId, AssetModel, SerialNumber, Condition, IssuedDate
								,AssetDescription for the Given @EmployeeAssetMappingId to show the values 
								in update Popup.
							2.2 Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAssetDetails]
(	
	@LoginUserId	INT
	,@AssetId		INT
	,@FromDate		DATE 
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId				TINYINT
			,@Total					INT
			,@TotalEmployee			INT
			,@GivenAssets			INT
			,@TotalAssetTypes		INT
			,@ToDate				DATE;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SET @ToDate = EOMONTH(@FromDate);

	BEGIN TRY	
		IF @AssetId IS NULL 
		BEGIN 
			SELECT	@Total = COUNT(EmployeeId)
			FROM	[dbo].[AssetDetails];

			SELECT	@TotalEmployee = COUNT(DISTINCT EmployeeId)
			FROM	[dbo].[AssetDetails];

			SELECT	@TotalAssetTypes = COUNT(AssetTypeId)
			FROM	[dbo].[AssetTypeDetails];
			
			SELECT	@GivenAssets = COUNT(DISTINCT AssetTypeId)
			FROM	[dbo].[EmployeeAssetMappingDetails];

			-- Result set for Counter Box.
			SELECT	@Total					AS	Total
					,@TotalEmployee			AS	TotalEmployee
					,@TotalAssetTypes		AS	TotalAssetTypes
					,@GivenAssets			AS	GivenAssets;

			SELECT	AD.AssetId
					,CONVERT(NVARCHAR(50),[Date],106) AS [Date]
					,CONCAT(FirstName, ' ', LastName) AS Employee
					,AssetType
					,TotalAssets
			FROM	[dbo].[AssetDetails] AD
			JOIN	(	SELECT	AssetId
								,STRING_AGG(AssetTypeName, ', ') AS AssetType 
								,COUNT(EAMD.EmployeeAssetMappingId) AS TotalAssets
						FROM	[dbo].[EmployeeAssetMappingDetails] EAMD
						JOIN	[dbo].[AssetTypeDetails] ATD
							ON	EAMD.AssetTypeId = ATD.AssetTypeId
						GROUP BY AssetId						
					) AS EAMD
				ON	AD.AssetId = EAMD.AssetId
			JOIN	[dbo].[EmployeeDetails] ED
				ON	AD.EmployeeId = ED.EmployeeId
			WHERE	ED.CompanyId = @CompanyId
			AND		[Date] BETWEEN @FromDate AND @ToDate
			ORDER BY AssetId DESC;
		END 
		ELSE 
		BEGIN 
			SELECT	AssetId
					,CONVERT(NVARCHAR(50),[Date],105) AS [Date]
					,AD.EmployeeId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName 
					,ISNULL(DepartmentName,'')  AS Department
					,ISNULL(DesignationName,'')  AS Designation
			FROM	[dbo].[AssetDetails] AD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	AD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId
			WHERE	AssetId = @AssetId;

			SELECT	EmployeeAssetMappingId
					,AssetId
					,AssetTypeId
					,AssetModel
					,SerialNumber
					,Condition
					--,CONVERT(NVARCHAR(50),IssuedDate,105) AS IssuedDate  
					,AssetDescription
			FROM	[dbo].[EmployeeAssetMappingDetails]
			WHERE	AssetId = @AssetId;
		END 
		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetAssetDetails]	@LoginUserId	= 1
										,@AssetId		= NULL
										,@FromDate		= '2025-04-01'
										,@Status		= @Status   OUT
										,@Message		= @Message  OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[AssetDetails];
========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetAttendanceInOutDetails_Employee]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*========================================================================================================================= 
 Procedure Name		:	[USP_GetAttendanceInOutDetails_Employee](When Click on DashBoard(Employee) in Side NavigationBar).
 Description		:	Procedure used to retrieve the Dashboard Details
 Input Parameter	:	@LoginUserId,@FromDate,@Todate
 Output Parameters	:	@Status,@Message
 Author				:	Tharanitharan
 Created on			:	05-09-2023
 Version			:	1.0 
 Comment			:	1.Displaying the BreakTime and OverTime Using AttendanceLogDetails Table.
						2.Displaying the Last one Week AttendanceLogDetails Have the Columns of Date,Day,NoOfHours,Status.
						3.Displaying the MonthWise Payroll Details in Percentage.
						4.Displaying the LeaveTypeName,AvailableLeave,TakenLeave for Annual,Casual,SickLeaves.
						5.Displaying the PermissionDetails TakenPermission,RemainingPermissions.
						6.Displaying the CompensatoryOffDetails TakenCompensatoryOff,RemainingCompensatoryOff.
						7.Displaying the Approved and Completed Loan Details.
						8.Displaying the AdvanceDetails Have the Column of Date,AdvanceAmount,AdvanceStatus.
						9.Displaying the UpComing Holidays.
						10.Displaying the Employee's Birthday forr the Given EmployeeId and FromDate and ToDate.
						11.Then return the output Parameters values as @Status=1 and @Message = NULL.
============================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAttendanceInOutDetails_Employee]
(
	@LoginUserId	INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId								TINYINT
			,@StartDate								DATETIME		= DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), '01')
			,@EndDate								DATETIME		= GETDATE()
			,@FromDate								DATE			= GETDATE()
			,@Todate								DATE			= GETDATE()
			,@Break									NVARCHAR(50)
			,@TotalOvertimeHours					NVARCHAR(50);
						
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	--Created TempTable to take Last 7 Days record In AttendanceLogDetails.
	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id			INT		IDENTITY(1,1)
		,PunchDate	DATE
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate) 
		VALUES		(@StartDate);
		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;

	BEGIN TRY			 
		IF	(@FromDate IS NULL AND @Todate IS NULL)
		BEGIN
			SET @FromDate = CONVERT(DATE,GETDATE())
			SET @Todate   = CONVERT(DATE,GETDATE())
 		END

		DROP TABLE IF EXISTS #DetailedDailyData; 
		SELECT	*
		INTO	#DetailedDailyData
		FROM	(
					SELECT	ED.EmployeeId 
							,PunchDate
							,PunchTime AS InTime
							,[Status] 
							,LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) AS OutTime
							,CASE WHEN LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) IS NOT NULL THEN
									CONVERT(VARCHAR(50), ISNULL(CAST((LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) - PunchTime) AS TIME(0)), '00:00:00')) + ' Hrs'
								ELSE CONVERT(VARCHAR(50), ISNULL(CAST((GETDATE() - PunchTime) AS TIME(0)), '00:00:00')) + ' Hrs'
							END AS WorkingHours
							,ALD.CompanyId
					FROM	[dbo].[EmployeeDetails] ED	
					JOIN	[dbo].[AttendanceLogDetails] ALD
						ON	ED.EmployeeId = ALD.EmployeeId 
					WHERE	PunchDate BETWEEN @FromDate AND @Todate
					AND		ED.EmployeeId = @LoginUserId
				 ) IQ
		WHERE [Status] = 1;

		DROP TABLE IF EXISTS #WorkingHours;
		SELECT	EmployeeId
				,PunchDate
				,(	RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) / 3600), 2) + ':' + 
					RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) % 3600 / 60), 2) + ':' + 
					RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) % 60), 2)
				) AS WorkingHours	
		INTO	#WorkingHours
		FROM	#DetailedDailyData
		GROUP BY EmployeeId, PunchDate;

		DROP TABLE IF EXISTS #Resultset_Production;
		SELECT	A.EmployeeId
				,A.PunchDate AS [Date]
				,ISNULL(FORMAT(PunchIn, 'hh:mm tt'), '') AS PunchIn
				,ISNULL(FORMAT(PunchOut, 'hh:mm tt'), '') AS PunchOut
				,STUFF((TRY_CONVERT(VARCHAR(1000), ISNULL(CAST(
				CASE  WHEN MAX(InTime) IS NOT NULL AND MAX(OutTime) IS NULL THEN GETDATE() - MIN(PunchIn)
					ELSE MAX(ALDS.PunchOut) - MIN(ALDS.PunchIn)
				END AS TIME(0)), '00:00')) + ' Hrs'), 6, 3, '') AS TotalHours
				,CONCAT(ISNULL(WH.WorkingHours, '00:00:00 Hrs'), ' Hrs') AS Production
				,CASE  WHEN PunchIn IS NOT NULL THEN CONCAT(CONVERT(NUMERIC(18, 2), CWD.WorkingHours) - CONVERT(NUMERIC(18, 2), 
						ISNULL(CAST(DATEDIFF(MINUTE, PunchIn, PunchOut) / 60.0 AS NUMERIC(18, 2)), 0)), ' Hrs') 
					ELSE CONCAT('00:00', ' Hrs') 
				END AS OverTime
				,ISNULL(FORMAT(DATEADD(MINUTE, DATEDIFF(MINUTE, '00:00', PD.NumberOfHours), 0), 'HH:mm'), '00:00') + ' Hrs' AS PermissionHours
				,WH.WorkingHours
		INTO	#Resultset_Production
		FROM	(	SELECT	A.*, DATENAME(DW, PunchDate) AS [WeekDay]
							,ED.EmployeeId  
							,PunchDate AS PunchDates
							,CompanyId
					FROM	#Attendance A
					JOIN	[dbo].[EmployeeDetails] ED 
						ON	ED.EmployeeId = @LoginUserId
					AND		ED.CompanyId = @CompanyId
				) AS A
		JOIN	(	SELECT	[Day] AS [WeekDay]
							,WorkingHours
							,CompanyId
					FROM	[dbo].[CompanyWorkingDayDetails]
					WHERE	CompanyId = @CompanyId
				) CWD 
			ON	A.CompanyId = CWD.CompanyId 
			AND A.[WeekDay] = CWD.[WeekDay]
		LEFT JOIN (	SELECT	EmployeeId, PunchDate, WorkingHours 
					FROM	#WorkingHours
					) WH 
			ON	CONVERT(DATE, A.PunchDate) = CONVERT(DATE, WH.PunchDate)
			AND A.EmployeeId = WH.EmployeeId
		LEFT JOIN	(	SELECT	DISTINCT ALD.EmployeeId
								,PunchDate
								,PunchTime
								,(	SELECT	MIN(PunchTime) 
									FROM	[AttendanceLogDetails] ALD1
									WHERE	ALD1.EmployeeId = ALD.EmployeeId 
									AND		CONVERT(DATE, ALD1.PunchDate) = CONVERT(DATE, ALD.PunchDate)
									AND		ALD1.[Status] = 1
								) AS PunchIn
								,(	SELECT	MAX(PunchTime)
									FROM	[AttendanceLogDetails] ALD2
									WHERE	ALD2.EmployeeId = ALD.EmployeeId 
									AND		CONVERT(DATE, ALD2.PunchDate) = CONVERT(DATE, ALD.PunchDate)
									AND		ALD2.[Status] = 0
								) AS PunchOut
						FROM	[dbo].[AttendanceLogDetails] AS ALD
						WHERE	(EmployeeId = @LoginUserId)
						AND		(CompanyId = @CompanyId)
					) AS ALDS 
			ON	CONVERT(DATE, A.PunchDate) = CONVERT(DATE, ALDS.PunchDate)
			AND A.EmployeeId = ALDS.EmployeeId
		LEFT JOIN	(	SELECT	TOP 1 EmployeeId 
								,PunchDate AS PunchDates
								,InTime
								,OutTime
						FROM	#DetailedDailyData
						WHERE	OutTime IS NULL
						ORDER BY OutTime DESC
					) AS DDD
			ON	A.EmployeeId = DDD.EmployeeId
			AND	A.PunchDates = DDD.PunchDates
		LEFT JOIN	(	SELECT	EmployeeId, PermissionDate, NumberOfHours
						FROM	[dbo].[PermissionDetails]
						WHERE	EmployeeId = @LoginUserId
						AND		CompanyId = @CompanyId
					) PD
			ON CONVERT(DATE, A.PunchDate) = CONVERT(DATE, PD.PermissionDate)
		GROUP BY A.EmployeeId, A.PunchDate, PunchIn, PunchOut, CWD.WorkingHours, WH.WorkingHours,PD.NumberOfHours;
		
		-- Fetch the attendance log details with a fallback default row
		SELECT TOP 1 CONCAT(FORMAT(ISNULL(ALD.PunchDate, GETDATE()), 'ddd, dd MMM yyyy'),' ',FORMAT(ISNULL(ALD.PunchTime, GETDATE()), 'hh:mm tt')) AS PunchInAt
				,CONCAT(ISNULL(WH.WorkingHours, '00:00:00'), ' Hrs') AS Production
		FROM	[dbo].[AttendanceLogDetails] ALD
		LEFT JOIN #WorkingHours WH 
			ON	ALD.PunchDate = WH.PunchDate
		WHERE	CONVERT(DATE, ALD.PunchDate) = CONVERT(DATE, GETDATE())
		AND		ALD.EmployeeId = @LoginUserId
		AND		ALD.CompanyId = @CompanyId
		UNION ALL
		SELECT	CONCAT(FORMAT(GETDATE(), 'ddd, dd MMM yyyy'),' ',FORMAT(GETDATE(), 'hh:mm tt') ) AS PunchInAt
				,'00:00:00 Hrs' AS Production
		WHERE	NOT EXISTS (	SELECT	1 
								FROM	[dbo].[AttendanceLogDetails] ALD
								WHERE	CONVERT(DATE, ALD.PunchDate) = CONVERT(DATE, GETDATE())
								AND		ALD.EmployeeId = @LoginUserId
								AND		ALD.CompanyId = @CompanyId);

		DROP TABLE IF EXISTS #ResultSet;
		SELECT	DISTINCT ED.EmployeeId
				,CONCAT(FirstName,' ',LastName) AS EmpName
				,CONVERT(VARCHAR(50), AT.PunchDate, 113) AS [Date]
				,AT.PunchDate
				,CONCAT(ISNULL(CONVERT(VARCHAR(1000), DATEADD(SECOND, TotalMinutesPerDay * 60, 0), 108), '00:00:00'),' Hrs') AS WorkingHours
				,ISNULL(BH. [Break],'00:00 Hrs') AS [Break]
		INTO	#ResultSet
		FROM	(SELECT * FROM EmployeeDetails WHERE EmployeeId = @LoginUserId) AS ED
		CROSS JOIN #Attendance AT
		LEFT JOIN (
					SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime
							,MAX(OutTime) AS OutTime
							,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
							,CASE WHEN MAX(OutTime) = GETDATE() THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
					FROM	(
								SELECT	ED.EmployeeId
										,PunchDate
										,LEFT(CONVERT(TIME,PunchTime),8) AS InTime
										,Status
										,LEFT(CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
													AND  CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
											WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
													AND  CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
											ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime))
										END),8) AS OutTime
								FROM	[dbo].[EmployeeDetails] ED	
								JOIN	[dbo].[AttendanceLogDetails] ALD	
									ON	ED.EmployeeId = ALD.EmployeeId 
								WHERE	ED.EmployeeId = @LoginUserId
								AND		PunchDate = CONVERT(DATE, GETDATE())
							) AS ALD
					WHERE	[Status] = 1
					GROUP BY EmployeeId, PunchDate
				) AS PH
			ON ED.EmployeeId = PH.EmployeeId 
			AND AT.PunchDate = PH.PunchDate
		LEFT JOIN (
					SELECT	EmployeeId
							,PunchDate
							,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, SUM(BreakMinutes), 0), 114),'00:00'),5),' Hrs') AS [Break]
					FROM	(
								SELECT	ED.EmployeeId
										,ALD.PunchDate
										,LEAD(ALD.Status) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime) AS A
										,CASE  WHEN ALD.[Status] = 0
											THEN DATEDIFF(MINUTE, ALD.PunchTime, LEAD(ALD.PunchTime) OVER (PARTITION BY ALD.PunchDate ORDER BY ALD.PunchTime))
											ELSE 0 
										END AS BreakMinutes
										,[Status]
								FROM	[dbo].[EmployeeDetails] ED
								JOIN	[dbo].[AttendanceLogDetails] ALD
									ON  ED.EmployeeId = ALD.EmployeeId
								WHERE	ED.EmployeeId = @LoginUserId						
							) AS ALD
					WHERE	[Status] = 0
					GROUP BY EmployeeId, PunchDate
				) AS BH
			ON ED.EmployeeId = BH.EmployeeId 
			AND AT.PunchDate = BH.PunchDate
		WHERE	ED.EmployeeId = @LoginUserId;

		SELECT	ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS PunchIn
				,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
		FROM	(
					SELECT	DISTINCT PunchTime AS PunchIn
							,LEAD(PunchTime) OVER(ORDER BY ALD.PunchTime) AS PunchOut
							,[Status]
					FROM	[dbo].[EmployeeDetails] ED	
					JOIN	[dbo].[AttendanceLogDetails] ALD
						ON	ED.EmployeeId = ALD.EmployeeId 
					WHERE	CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE())
					AND		ED.EmployeeId = @LoginUserId
				) AS A
		WHERE	[Status] = 1;

		;WITH OverTimeCTE 
		AS	(
				SELECT	DISTINCT DATEDIFF(MINUTE, 0, LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE
								,CASE WHEN ALD.LastOutTime > SD.EndTime 
										THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
									ELSE 0 END, 0), 114), 5)) AS OverTime
				FROM	(	SELECT	EmployeeId
									,PunchDate
									,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
							FROM	[dbo].[AttendanceLogDetails]
							WHERE	EmployeeId = @LoginUserId
							GROUP BY EmployeeId, PunchDate
						) AS ALD
				LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD
					ON	ALD.EmployeeId = ESMD.EmployeeId
				LEFT JOIN [dbo].[ShiftDetails] SD
					ON	ESMD.ShiftId = SD.ShiftId
				WHERE  YEAR(PunchDate) = YEAR(GETDATE())
				AND		MONTH(PunchDate) = MONTH(GETDATE())
				AND		ALD.EmployeeId = @LoginUserId
			)
		SELECT	@TotalOvertimeHours = CASE WHEN CONCAT(SUM(OverTime) / 60, ':', RIGHT('00' + CAST(SUM(OverTime) % 60 AS VARCHAR), 2)) = ':'
											THEN '00:00' ELSE CONCAT(SUM(OverTime) / 60, ':', RIGHT('00' + CAST(SUM(OverTime) % 60 AS VARCHAR), 2))
										END 
		FROM	OverTimeCTE;

		SELECT	[Break] 
				,CONCAT(@TotalOvertimeHours,' Hrs') AS OverTime
		FROM	#ResultSet
		WHERE	CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE())
		AND		EmployeeId = @LoginUserId;

		SELECT	DISTINCT MapNumber	
		FROM	[dbo].[BranchDetails]
		WHERE	CompanyId = @CompanyId
		UNION ALL
		SELECT	MapNumber
		FROM	[dbo].[ClientLocationDetails] CLD
		JOIN	[dbo].[EmployeeClientLocationMappingDetails] CLMD
			ON	CLD.ClientLocationId = CLMD.ClientLocationId
		WHERE	CompanyId = @CompanyId
		AND		CLMD.[Status] = 1
		AND		EmployeeId = @LoginUserId;

		SELECT	@Status    = 1  
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0 
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);
			 
	EXEC [dbo].[USP_GetAttendanceInOutDetails_Employee]	@LoginUserId	= 3
														,@Status		= @S_Status		OUT
														,@Message		= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT * FROM EmployeeDetails
	SELECT * FROM AttendanceLogDetails
	
	SELECT * FROM CompensatoryOffDetails
======================================================================================================================*/


GO
/****** Object:  StoredProcedure [dbo].[USP_GetAttendanceLogDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=========================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetAttendanceLogDetails] (When Click on the side Navigation bar Attendance)
 Description		:	Procedure used to retrive the Attendancedetails      
 Input Parameter	:	@LoginUserId,@EmployeeId,@FromDate,@Todate,PunchDate						
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	07-05-2024
 Version			:	1.0 
 Comment			:	1. Declare the StartDate,EndDate to find the Current Month.
						2. If the @PunchDate IS NULL,
							2.1 Get the AttendanceLogDetails have the Columns of PuchDate,PunchIn,PunchOut,Production,Break,OverTime
								to Show in Grid.
						    2.2 Then return the output Parameters values as @Status=1 and @Message = NULL.			   
						3. If the @PunchDate Is NOT NULL,
							3.1 Get the Particular AttendaneLogDetails have the Colums of EmployeeId,EmployeeName,Date,PunchIn,PunchOut
								Status,NoOfHours to show the values in Popup.
							3.2 Then return the output Parameters values as @Status=1 and @Message = NULL.
===========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAttendanceLogDetails]
(
	@LoginUserId	INT
	,@EmployeeId	INT
	,@FromDate		DATETIME
	,@ToDate		DATETIME
	,@Punchdate		DATE
	,@Status		BIT           OUT
	,@Message		NVARCHAR(200) OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId					INT
			,@Remaining					NVARCHAR(50)
			,@Overtime					NVARCHAR(50)
 			,@PunchDateNew				DATE
			,@StartDate					DATETIME = @FromDate
			,@EndDate					DATETIME;

	IF MONTH(@ToDate) = MONTH(GETDATE()) AND  YEAR(@ToDate) = YEAR(GETDATE())
	BEGIN
		SET @EndDate = GETDATE();
	END
	ELSE
	BEGIN
		SET @EndDate = @ToDate;
	END

	IF @Punchdate IS NULL
	BEGIN
		SET @PunchDateNew = CONVERT(DATE,GETDATE());
	END
	ELSE
	BEGIN
		SET @PunchDateNew = @PunchDate;
	END

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	--Temp Table for taking StartDate to CurrentDate
	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id				INT		IDENTITY(1,1)
		,PunchDate		DATE
		,CompanyId		TINYINT
	)

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate, CompanyId) 
		VALUES		(@StartDate,@CompanyId);
		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;

	DROP TABLE IF EXISTS #DetailedDailyData; 
	SELECT	*
	INTO	#DetailedDailyData
	FROM	(
				SELECT	ED.EmployeeId 
						,PunchDate
						,PunchTime AS InTime
						,[Status] 
						,LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) AS OutTime
						--,ISNULL(LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime),PunchTime) AS OutTime
						,((CONVERT(VARCHAR(50),ISNULL(CAST((LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) - PunchTime) AS TIME(0)),'00:00:00'))+ ' Hrs'))AS WorkingHours
						,ALD.CompanyId
					FROM	[dbo].[EmployeeDetails] ED	
					JOIN	[dbo].[AttendanceLogDetails] ALD
					ON	ED.EmployeeId = ALD.EmployeeId 
				WHERE	CONVERT(DATE,PunchDate) = CASE WHEN  @PunchDate IS NULL THEN CONVERT(DATE,PunchDate) ELSE  @PunchDate END 
				AND		ED.EmployeeId = @EmployeeId
			) IQ
	WHERE Status = 1;

	--DROP TABLE IF EXISTS #WorkingHours;
	SELECT	EmployeeId
			,PunchDate
			,(RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) / 3600), 2) + ':' + 
			  RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) % 3600 / 60), 2) + ':' + 
			  RIGHT('0' + CONVERT(VARCHAR, SUM((DATEDIFF(SECOND, '00:00:00', LEFT(WorkingHours, 8)))) % 60), 2)) AS WorkingHours
	INTO	#WorkingHours
	FROM	#DetailedDailyData
	GROUP BY EmployeeId, PunchDate;

	BEGIN TRY
		--Get the AttendanceLogDetails.
		IF @PunchDate IS NULL
		BEGIN
			--Logic for PunchIn At
			SELECT  TOP 1  FORMAT(ISNULL(PunchTime,''),'ddd, dd MMM yyyy hh.mm tt') AS PunchInAt
			FROM	[dbo].[AttendanceLogDetails]
			WHERE	CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE())
			AND		EmployeeId = @EmployeeId
			AND		CompanyId = @CompanyId;
		
			-- Logic for Grid
			DROP TABLE IF EXISTS #Resultset;
			SELECT	A.EmployeeId 
					,A.PunchDate AS [Date] 
					,ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS  PunchIn
					,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
					,CASE	WHEN ProductionHours IS NULL THEN ISNULL(WH.ProductionHours,' ') 
							ELSE  CONCAT(ISNULL(WH.ProductionHours,' '),' Hrs') 
					 END AS  Production
			INTO	#Resultset
			FROM	(	SELECT A.*,DATENAME(DW,PunchDate) AS [WeekDay],ED.EmployeeId   
						FROM #Attendance A, (SELECT * FROM EmployeeDetails
											 WHERE EmployeeId= @EmployeeId
											 AND   CompanyId = @CompanyId)ED )AS A
			JOIN	(
						SELECT [Day] AS [WeekDay], WorkingHours, CompanyId
						FROM	[dbo].[CompanyWorkingDayDetails] CWD
						WHERE CompanyId = @CompanyId
					) CWD
				ON A.CompanyId = CWD.CompanyId 
				AND A.[WeekDay] = CWD.[WeekDay]
			LEFT JOIN	(
							SELECT EmployeeId, PunchDate,WorkingHours AS ProductionHours
							FROM	#WorkingHours
						) WH
				ON	CONVERT(DATE,A.PunchDate) = CONVERT(DATE,WH.PunchDate)
				AND A.EmployeeId = WH.EmployeeId
			LEFT JOIN   (SELECT	DISTINCT	ALD.EmployeeId
											,PunchDate
											,(	SELECT  MIN(PunchTime) 
												FROM	[AttendanceLogDetails] ALD1
												WHERE	ALD1.EmployeeID = ALD.EmployeeId 
												AND		CONVERT(DATE,ALD1.PunchDate) =  CONVERT(DATE,ALD.PunchDate)
												AND		ALD1.[Status] = 1 
											  ) AS PunchIn
											,(	SELECT	MAX(PunchTime)
												FROM	[AttendanceLogDetails] ALD2
												WHERE	ALD2.EmployeeID = ALD.EmployeeId 
			   									AND		CONVERT(DATE,ALD2.PunchDate) = CONVERT(DATE,ALD.PunchDate)
												AND		ALD2.[Status] = 0 
											 ) AS PunchOut
						FROM	[dbo].[AttendanceLogDetails] AS ALD
						WHERE	(CONVERT(DATE,ALD.PunchDate) BETWEEN @FromDate AND @ToDate) 
						AND		(EmployeeId = @EmployeeId)
						AND		(CompanyId = @CompanyId)) AS ALDS
					ON	CONVERT(DATE,A.PunchDate) = CONVERT(DATE,ALDS.PunchDate)
					AND A.EmployeeId = ALDS.EmployeeId
			GROUP BY A.EmployeeId 
					,A.PunchDate
					, PunchIn
					, PunchOut
					,WorkingHours
					,WH.ProductionHours;

			-- Logic for BreakTime, OverTime to show under counter
			SELECT	'01:30 Hrs' AS [Break] 
					,'00:00 Hrs'OverTime
			FROM	#Resultset
			WHERE	CONVERT(DATE,[Date]) = CONVERT(NVARCHAR(50),CONVERT(DATE,GETDATE()),113);

			--Today Activities
			SELECT	ISNULL(FORMAT(InTime,'hh:mm tt'),'') AS PunchIn
					,ISNULL(FORMAT(OutTime,'hh:mm tt'),'') AS PunchOut
			FROM	#DetailedDailyData
			WHERE	CONVERT(DATE,PunchDate) = @PunchDateNew
			AND		EmployeeId = @EmployeeId;
		
			--Resultset for Grid
			SELECT	EmployeeId 
					,CONVERT(VARCHAR(50),[Date],113) AS [Date]
					,DATENAME(WEEKDAY, [Date] ) AS [Day]
					,PunchIn
					,PunchOut
					,ISNULL(Production,' ') AS Production
					,'01:30 Hrs'  AS [Break] 
					,'00:00 Hrs'OverTime 
			FROM	#Resultset
			ORDER BY [Date] DESC;

			END
			ELSE
			BEGIN
				--Get the Particular AttendaneLogDetails have the Colums of EmployeeId,EmployeeCompanyId,EmployeeName,PunchDate,TotalHours,WorkingHours to show the values in Popup.
				SELECT	DISTINCT ED.EmployeeId
								,EmployeeCompanyId
								,CONCAT(ED.FirstName , ' ' , LastName) AS EmployeeName
								,CONVERT(VARCHAR(50),D.PunchDate,105) AS PunchDate
								,STUFF((CONVERT(VARCHAR(50),ISNULL(CAST(CASE WHEN MAX(OutTime) IS NULL THEN GETDATE() - MIN(InTime)
									ELSE MAX(ALD.PunchTime) - MIN(ALD.PunchTime)END AS TIME(0)),'00:00')) + ' Hrs'), 6,3,'') AS TotalHours
								,CASE WHEN MAX(OutTime) IS NULL THEN STUFF((CONVERT(VARCHAR(50),ISNULL(CAST(GETDATE() - MIN(InTime) AS TIME(0)),'00:00')) + ' Hrs'),
									6,3,'')ELSE CONCAT(LEFT(WH.WorkingHours, 5), ' Hrs') 
								 END AS WorkingHours
								--,STUFF(((CONVERT(VARCHAR(50),ISNULL(CAST((MAX(PunchTime) - MIN(PunchTime)) AS TIME(0)),'00:00'))+ ' Hrs')),6,3,'') AS TotalHours
								--,CONCAT(LEFT(WH.WorkingHours,5),' Hrs') AS WorkingHours		
  				FROM	[dbo].[EmployeeDetails] ED
				CROSS JOIN (SELECT * FROM #Attendance WHERE PunchDate = @PunchDate) D
				LEFT JOIN (SELECT * FROM [dbo].[AttendanceLogDetails] 
							WHERE	PunchDate = @PunchDate)ALD
					ON	ALD.EmployeeId = ED.EmployeeId 
				LEFT JOIN #WorkingHours WH 
					ON	ED.EmployeeId = WH.EmployeeId 
				LEFT JOIN #DetailedDailyData DD
					ON ED.EmployeeId = DD.EmployeeId
				WHERE	ED.CompanyId  = @CompanyId
				AND		ED.EmployeeId = @EmployeeId
				GROUP BY ED.EmployeeId
						,EmployeeCompanyId
						,CONCAT(ED.FirstName , ' ' , LastName)
						,D.PunchDate
						,WH.WorkingHours;

				--Get the Particular AttendanceLogDetails have the column of PunchIn,PunchOut,NoOfHours to show in Popup.
				SELECT	ISNULL(FORMAT(InTime,'hh:mm tt'),'') AS PunchIn
						,ISNULL(FORMAT(OutTime,'hh:mm tt'),'') AS PunchOut
						,CASE WHEN OutTime IS NULL THEN CONCAT(ISNULL(CONVERT(VARCHAR(10), DATEDIFF(HOUR, CAST(InTime AS DATETIME), GETDATE())) + ':' +
							RIGHT('0' + CONVERT(VARCHAR(10), DATEDIFF(MINUTE, CAST(InTime AS DATETIME), GETDATE()) % 60), 2), '00'),' Hrs')
							ELSE (STUFF(WorkingHours, 6, 3, ''))
							END AS NoOfHours					
							--,STUFF(WorkingHours, 6,3,'') AS NoOfHours
				FROM	#DetailedDailyData
				WHERE	PunchDate = @PunchDate
				AND		EmployeeId = @EmployeeId; 
			END
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=================================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);
			 
	EXEC [dbo].[USP_GetAttendanceLogDetails_Employee]	@LoginUserId		= 1
														,@EmployeeId		= 3
														,@FromDate			= '2024-05-01'
														,@ToDate			= '2024-05-25'
														,@PunchDate			= '2024-05-04'
														,@IsWeekly			= 1
