/****** Object:  StoredProcedure [dbo].[USP_GetAttendanceLogDetails_Admin]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==================================================================================================================================================
 Procedure Name		:   [USP_GetAttendanceLogDetails_Admin](When Click on the side Navigation bar (Attendance(Admin))
 Description		:	Procedure used to retrive the Attendancedetails      
 Input Parameter	:	@LoginUserId,@EmployeeId,@FromDate,@Todate,@PunchDate						
 Output Parameters	:	@Status,@Message		.                                                                                                                                                                                                                                                                                                                                                                                                            							
 Author				:	Dharani.M
 Created on			:	01-08-2023
 Version			:	1.0 
 Comment			:	1. Declare the StartDate,EndDate to find the Current Month.
						2. Create Temp table to insert date for holding the current month Using While Loop Statement.
						3. Create Temp table to taking WorkingHours.
						4. If the @PunchDate IS NULL,
							4.1 Get the AttendanceLogDetails have the Columns of EmployeeId,EmployeeImageFileName,EmployeeName,Date(Using Pivot Operator in
								Dynamic Concept to Show in Grid.
						    4.2 Then return the output Parameters values as @Status=1 and @Message = NULL.			   
						5. If the @PunchDate Is NOT NULL,
							5.1 Get the Particular AttendaneLogDetails have the Colums of EmployeeId,EmployeeImageFileName,EmployeeName,Date,Status,
								to show in Popup.
							5.2	Get the Particular AttendanceLogDetails have the column of PunchIn,PunchOut,NoOfHours to show in Popup.
							5.3 Then return the output Parameters values as @Status=1 and @Message = NULL.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAttendanceLogDetails_Admin]
(	
	@LoginUserId		INT
	,@EmployeeId		INT
	,@FromDate			DATETIME
	,@Punchdate			INT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(200)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE @LoginUserId		INT			= 1
	--		,@EmployeeId		INT			= NULL
	--		,@FromDate			DATETIME	= '2025-01-01'
	--		,@Punchdate			INT			= NULL

	DECLARE	@ToDate	DATETIME;

	IF (YEAR(@FromDate) = YEAR(GETDATE()) AND MONTH(@FromDate) = MONTH(GETDATE()))
	BEGIN
		SET @ToDate = GETDATE();
	END
	ELSE
	BEGIN
		SET @ToDate = DATEADD(DAY, -1, DATEADD(MONTH, DATEDIFF(MONTH, 0, @FromDate) + 1, 0));
	END

	DECLARE @CompanyId				INT  
			,@StartDate				DATETIME		= @FromDate
			,@EndDate				DATETIME		= @ToDate
			,@Cols					NVARCHAR(MAX)	= '' 
			,@Sql					NVARCHAR(MAX)
			,@Punchdate1			DATE			= NULL
			,@TotalEmployees		INT
			,@PresentEmployees		INT
			,@AbsentEmployees		INT
			,@PlannedLeaves			INT
			,@UnPlannedLeaves		INT
			,@LateCheckIn			INT
			,@PlannedPermission		INT
			,@Holiday				NVARCHAR(50);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT  @Holiday = HolidayName
	FROM	[dbo].[HolidayDetails]
	WHERE	HolidayDate = CONVERT(DATE,DATEFROMPARTS(YEAR(@FromDate) , MONTH(@FromDate), @Punchdate));

	DROP TABLE IF EXISTS #Date;
	CREATE TABLE #Date 
	(
		Id              INT  IDENTITY(1,1)
		,PunchDate		DATE
	)

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO	#Date(PunchDate) 
		VALUES		(@StartDate);
		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;
	
	SELECT	@Punchdate1 = DATEFROMPARTS(CONVERT(VARCHAR(10),YEAR(@ToDate))
						  ,CONVERT(VARCHAR(10),MONTH(@ToDate))
						  ,CONVERT(VARCHAR(10),@PunchDate));

	DROP TABLE IF EXISTS #EmployeeDetails;
	CREATE TABLE #EmployeeDetails
	(
		EmployeeId				INT
		,EmployeeCompanyId		NVARCHAR(100)
		,EmployeeImage			NVARCHAR(1000)
		,EmpName				NVARCHAR(100)
		,ReportingPersonId		INT
		,CompanyId				TINYINT
	);
	
	INSERT INTO #EmployeeDetails(EmployeeId, EmployeeCompanyId, EmployeeImage, EmpName, ReportingPersonId, CompanyId)
	SELECT		ED.EmployeeId, ED.EmployeeCompanyId, ED.EmployeeImage, CONCAT(ED.FirstName,' ',ED.LastName)
				,ED.ReportingPersonId, ED.CompanyId
	FROM	[dbo].[EmployeeDetails] ED
	LEFT JOIN [dbo].[EmployeeDetails] RPD
		ON	RPD.EmployeeId = ED.EmployeeId
	WHERE	ED.ReportingPersonId = @LoginUserId;

	DROP TABLE IF EXISTS #ResultSet_MyTeam;
	CREATE TABLE #ResultSet_MyTeam
	(
		EmployeeId			INT 
		,EmployeeImage		NVARCHAR(1000) 
		,EmployeeName		NVARCHAR(100) 
		,[Date] 			INT
		,PunchDate			DATE
		,TotalHours			NVARCHAR(100) 
		,WorkingHours		NVARCHAR(100) 
		,[Status]			NVARCHAR(100)	
	);
	
	INSERT INTO #ResultSet_MyTeam(EmployeeId, EmployeeImage, EmployeeName, [Date], PunchDate, TotalHours
				,WorkingHours, [Status])
	SELECT	DISTINCT ED.EmployeeId
			,EmployeeImage
			,EmpName AS EmployeeName
			,RIGHT(AT.PunchDate,2) AS [Date] 
			,AT.PunchDate
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, CONVERT(TIME, PH.InTime), CONVERT(TIME, PH.OutTime)), 0), 114),'00:00'),5),' Hrs') AS TotalHours
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5),' Hrs') AS WorkingHours
			,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Leave/CompOff'
					WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'CompOff/Leave'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Leave/Present'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Present/Leave'
					WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'WeekOff' 
					WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Holiday'
					WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Leave'
					WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Absent' 
					WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'CompOff'
					WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'YetToRegularize'
					WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Present' 
					WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Present' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
						AND TotalMinutesPerDay < 240 THEN 'Absent' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'HalfDay' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'HalfDay' 
					ELSE 'Present'
			END AS [Status]
	FROM	#EmployeeDetails AS ED
	CROSS JOIN #Date AT
	LEFT JOIN	(
					SELECT	CompanyId, IsWorkingDay, [Day]
							,CASE WHEN IsWorkingDay = 0 THEN 0 ELSE 1 END AS WeekEndDays	
					FROM	[dbo].[CompanyWorkingDayDetails]
					WHERE	IsWorkingDay = 0
					AND		CompanyId = 1
				) AS CWDD
		ON	CWDD.CompanyId = ED.CompanyId
		AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
	LEFT JOIN [dbo].[HolidayDetails] HD
		ON	AT.PunchDate = HD.HolidayDate
	LEFT JOIN (	
				SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
				FROM EmployeeShiftMappingDetails ESMD
				JOIN	#EmployeeDetails ED
					ON	ESMD.EmployeeId = ED.EmployeeId
				LEFT JOIN ShiftDetails SD
					ON	SD.ShiftId = ESMD.ShiftId 
			) AS ESMD
		ON ED.EmployeeId = ESMD.EmployeeId 
		AND AT.PunchDate BETWEEN StartDate AND EndDate
	LEFT JOIN (
				SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime
						,MAX(OutTime) AS OutTime
						,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
						,CASE WHEN MAX(OutTime) = GETDATE() THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,PunchTime AS InTime
									,Status
									,CASE WHEN LEAD(PunchTime) OVER(PARTITION BY ED.EmployeeId, PunchDate ORDER BY PunchTime) IS NULL 
												AND  CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
										WHEN LEAD(PunchTime) OVER(PARTITION BY ED.EmployeeId, PunchDate ORDER BY PunchTime) IS NULL 
												AND  CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
										ELSE LEAD(PunchTime) OVER(PARTITION BY ED.EmployeeId, PunchDate ORDER BY PunchTime)
									END AS OutTime
							FROM	#EmployeeDetails ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
						) AS ALD
				WHERE	[Status] = 1
				GROUP BY EmployeeId, PunchDate
			) AS PH
		ON ED.EmployeeId = PH.EmployeeId 
		AND AT.PunchDate = PH.PunchDate
	LEFT JOIN (
				SELECT	EmployeeId
						,PunchDate
						,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, SUM(BreakMinutes), 0), 114),'00:00'),5),' Hrs') AS [Break]
				FROM	(
							SELECT	ED.EmployeeId
									,ALD.PunchDate
									,LEAD(ALD.Status) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime) AS A
									,CASE  WHEN ALD.[Status] = 0
										THEN DATEDIFF(MINUTE, ALD.PunchTime, LEAD(ALD.PunchTime) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime))
										ELSE 0 
									END AS BreakMinutes
									,[Status]
							FROM	#EmployeeDetails ED
							JOIN	[dbo].[AttendanceLogDetails] ALD
								ON  ED.EmployeeId = ALD.EmployeeId			
						) AS ALD
				WHERE	[Status] = 0
				GROUP BY EmployeeId, PunchDate
			) AS BH
		ON ED.EmployeeId = BH.EmployeeId 
		AND AT.PunchDate = BH.PunchDate
	LEFT JOIN (
				SELECT	DISTINCT ALD.EmployeeId
						,ALD.PunchDate
						,ALD.LastOutTime
						,SD.StartTime
						,SD.EndTime
						,CONCAT(LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE,CASE WHEN ALD.LastOutTime > SD.EndTime 
																THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
												ELSE 0 END, 0), 114),5),' Hrs') AS OverTime 
				FROM	(
							SELECT	ALD.EmployeeId
									,PunchDate
									,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
							FROM	[dbo].[AttendanceLogDetails] ALD 
							JOIN	#EmployeeDetails ED
								ON	ED.EmployeeId = ALD.EmployeeId
							GROUP BY ALD.EmployeeId, PunchDate
						) AS ALD
				LEFT JOIN	[dbo].[EmployeeShiftMappingDetails] ESMD
					ON	ALD.EmployeeId = ESMD.EmployeeId
				LEFT JOIN	[dbo].[ShiftDetails] SD
					ON	ESMD.ShiftId = SD.ShiftId
				)OH
			ON ED.EmployeeId = OH.EmployeeId 
			AND AT.PunchDate = OH.PunchDate
	LEFT JOIN (
				SELECT	PD.EmployeeId
						,PermissionDate
						,NumberOfHours
						,DATEDIFF(MINUTE,0,NumberOfHours) AS NoOfHours
						,EndTime
						,StartTime
				FROM	[dbo].[PermissionDetails] PD 
				LEFT JOIN #EmployeeDetails ED
					ON	PD.EmployeeId = ED.EmployeeId
				) AS PD
		ON ED.EmployeeId = PD.EmployeeId 
		AND AT.PunchDate = PD.PermissionDate
	LEFT JOIN	(	
				SELECT	EmployeeId, PunchDate, PunchOut
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,MAX(PunchTime) AS PunchOut
									,[Status]
							FROM	#EmployeeDetails ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
							GROUP BY ED.EmployeeId, PunchDate, [Status]
						) AS A
				WHERE	[Status] = 0
				) AS PO
		ON ED.EmployeeId = PO.EmployeeId 
		AND AT.PunchDate = PO.PunchDate
	LEFT JOIN	(
					SELECT	LD.EmployeeId, FromDate, ToDate, LeaveStatusId, IsFirstHalf
							,IsHalfDay, LeaveTypeId
					FROM	[dbo].[LeaveDetails] LD
					JOIN	#EmployeeDetails ED
						ON	LD.EmployeeId = ED.EmployeeId
					AND		LeaveStatusId IN (2, 3)
				) AS LD
		ON ED.EmployeeId = LD.EmployeeId 
		AND AT.PunchDate BETWEEN FromDate AND ToDate
	LEFT JOIN	(
					SELECT	EmployeeId, FromDate, ToDate, LeaveTypeId, IsHalfDay, IsFirstHalf
					FROM	[dbo].[LeaveDetails] 
					WHERE	LeaveStatusId IN (2, 3)
					AND		EmployeeId = @EmployeeId
					AND		LeaveTypeId = 2
				) AS LSD
		ON ED.EmployeeId = LSD.EmployeeId 
		OR AT.PunchDate BETWEEN LSD.FromDate AND LSD.ToDate
	WHERE	ED.ReportingPersonId = @LoginUserId;

	BEGIN TRY
		--Get the AttendanceLogDetails have the Columns of EmployeeId,EmployeeImageFileName,EmployeeName,Date to Show in Grid.
		IF @Punchdate IS NULL
		BEGIN
			--Logic is used to get the TotalEmployees.
			SELECT	@TotalEmployees = COUNT(EmployeeId)
			FROM	[DBO].[EmployeeDetails]
			WHERE	IsActive = 1 
			AND		EmployeeId <> 1
			AND		CompanyId = @CompanyId;

			--Logic is used to get the PresentEmployees.
			SELECT	@PresentEmployees =COUNT(DISTINCT EmployeeId)
			FROM	[dbo].[AttendanceLogDetails]
			WHERE	CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE())
			AND		EmployeeId <> 1
			AND		CompanyId = @CompanyId;
			
			--Logic is used to get the AbsentEmployees.
			SELECT @AbsentEmployees = ISNULL(@TotalEmployees,0) - ISNULL(@PresentEmployees,0);

			--Login for Employees PlannedLeave
			SELECT	@PlannedLeaves = COUNT(EmployeeId)
			FROM	[dbo].[LeaveDetails] LD
			JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	LD.LeaveStatusId = LSD.LeaveStatusId
			WHERE	CONVERT(DATE,FromDate) = CONVERT(DATE,GETDATE()) 
			AND		LSD.LeaveStatusName = 'Approved'
			AND		EmployeeId <> 1
			AND		LD.CompanyId = @CompanyId;

			--Logic for Employees UnPlannedLeave
			SELECT @UnPlannedLeaves = ISNULL((@TotalEmployees),0) - ISNULL((@PresentEmployees),0) - ISNULL((@PlannedLeaves),0);
			
			SELECT	@LateCheckIn = COUNT(DISTINCT ALD.EmployeeId)
			FROM	[dbo].[AttendanceLogDetails] ALD 
			JOIN	[dbo].[EmployeeDetails] ED 
				ON	ALD.EmployeeId = ED.EmployeeId
			JOIN	[dbo].[EmployeeShiftMappingDetails] ESMD 
				ON	ALD.EmployeeId = ESMD.EmployeeId
			JOIN	[dbo].[ShiftDetails] SD 
				ON	ESMD.ShiftId = SD.ShiftId
			WHERE	CONVERT(DATE, PunchDate) = CONVERT(DATE, GETDATE())
			AND		ALD.CompanyId = @CompanyId
			AND		ALD.EmployeeId <> 1
			AND		CONVERT(TIME, PunchTime) > CONVERT(TIME, SD.StartTime);
			-- AND		CONVERT(TIME, PunchTime) < DATEADD(MINUTE, 30, CONVERT(TIME, SD.StartTime));

			SELECT	@PlannedPermission = COUNT(EmployeeId)
			FROM	[dbo].[PermissionDetails] PD	
			JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	PD.PermissionStatusId = LSD.LeaveStatusId
			WHERE	CONVERT(DATE,PermissionDate) = CONVERT(DATE,GETDATE()) 
			AND		LeaveStatusName = 'Approved'
			AND		EmployeeId <> 1
			AND		PD.CompanyId = @CompanyId;

			-- ResultSet for Counter Boxes
			SELECT  CONCAT(@TotalEmployees,' / ',@PresentEmployees,' / ',@AbsentEmployees)		AS 'Total'
					,CONCAT(@PlannedLeaves,' / ', @UnPlannedLeaves)								AS 'Employee Leaves'
					,@LateCheckIn																AS LateCheckIn
					,@PlannedPermission															AS Permission;

			--ResultSet for Grid 
			SELECT @Cols = STUFF((	SELECT DISTINCT ',' + QUOTENAME(RIGHT(CONVERT(NVARCHAR(50),PunchDate),2))
									FROM #Date c
									FOR XML PATH(''), TYPE
								).value('.', 'NVARCHAR(MAX)') ,1,1,'');
			
			SET @Sql = N'SELECT EmployeeId,EmployeeImage,EmployeeName,' + @Cols + '
						 FROM (
								SELECT	EmployeeId
										,EmployeeImage
										,EmployeeName
										,[Date] 
										,[Status]
								FROM	#ResultSet_MyTeam
							)PD
							PIVOT
							(
								MAX(Status)
								FOR	Date 
								IN	(' + @Cols + ')
							) PT 
							ORDER BY EmployeeId ';

			PRINT  @Sql
			EXECUTE SP_EXECUTESQL @Sql;
		END
		ELSE
		BEGIN
			SELECT	DISTINCT ED.EmployeeId
					,EmployeeCompanyId
					,CONCAT(ED.FirstName , ' ' , LastName) AS EmployeeName
					,CONVERT(NVARCHAR(50),DATEFROMPARTS(CONVERT(VARCHAR(10),YEAR(@ToDate))
						  ,CONVERT(VARCHAR(10),MONTH(@ToDate))
						  ,CONVERT(VARCHAR(10),@PunchDate)),105) AS PunchDate
					--,CONVERT(VARCHAR(50),R.PunchDate,105) AS PunchDate
					,TotalHours
					,WorkingHours
			FROM	(	SELECT	EmployeeId, EmployeeCompanyId, FirstName, LastName
						FROM	[dbo].[EmployeeDetails] 
						WHERE	CompanyId  = @CompanyId
						AND		EmployeeId = @EmployeeId
					) AS ED
			LEFT JOIN (	SELECT	EmployeeId, PunchDate, TotalHours, WorkingHours
						FROM	#ResultSet_MyTeam 
						WHERE	PunchDate = @PunchDate1
						AND		EmployeeId = @EmployeeId
					) AS R
				ON	ED.EmployeeId = R.EmployeeId;
			
			SELECT	ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS PunchIn
					,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
					,CONCAT(CASE WHEN PunchOut IS NULL THEN LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PunchIn, CONVERT(TIME, GETDATE())),0), 114),5)
						ELSE LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PunchIn, PunchOut),0), 114),5)  
					END,' Hrs') AS NoOfHours	
					,InLocation
					,OutLocation
			FROM	(
						SELECT	DISTINCT PunchTime AS PunchIn
								,LEAD(PunchTime) OVER(ORDER BY PunchTime) AS PunchOut
								,[Status]
								,[Location] AS InLocation
								,LEAD([Location]) OVER(ORDER BY PunchTime) AS OutLocation
						FROM	AttendanceLogDetails
						WHERE	EmployeeId = @EmployeeId
						AND		PunchDate = @Punchdate1
					) AS A
			WHERE	[Status] = 1;
		END
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=================================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);
			 
	EXEC [dbo].[USP_GetAttendanceLogDetails_Admin]	@LoginUserId =  1
													,@EmployeeId =  NULL
													,@FromDate   =  '2025-01-01'
													,@PunchDate  =  NULL -- '2024-08-26'
													,@Status	 =  @S_Status  OUT
													,@Message	 =  @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT  *
	FROM	[dbo].[AttendanceLogDetails]
	SELECT  *
	FROM	[dbo].[EmployeeDetails];

	SELECT  *
	FROM	LeaveDetails
===================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetAttendanceLogDetails_Employee]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=========================================================================================================================================
Procedure Name		:   [USP_GetAttendanceLogDetails_Employee](When Click on the side Navigation bar 
																						(Attendance(Employee))
Description			:	Procedure used to retrive the Attendancedetails      
Input Parameter		:	@LoginUserId,@EmployeeId,@FromDate,@Todate,PunchDate						
Output Parameters	:	@Status,@Message									
Author				:	Prakash.P
Created on			:	01-08-2023
Version				:	1.0 
Comment				:	1. Declare the StartDate,EndDate to find the Current Month.
						2. If the @PunchDate IS NULL,
							2.1 Get the AttendanceLogDetails have the Columns of PuchDate, PunchIn, PunchOut
								,Production, Break, OverTime to Show in Grid.
							2.2 Then return the output Parameters values as @Status=1 and @Message = NULL.			   
						3. If the @PunchDate Is NOT NULL,
							3.1 Get the Particular AttendaneLogDetails have the Colums of EmployeeId, EmployeeName 
								,Date, PunchIn, PunchOut, Status, NoOfHours to show the values in Popup.
							3.2 Then return the output Parameters values as @Status=1 and @Message = NULL.
===========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAttendanceLogDetails_Employee]
(
	@LoginUserId	INT
	,@EmployeeId	INT
	,@FromDate		DATETIME
	,@Punchdate		DATE
	,@IsWeekly		BIT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(200)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE @LoginUserId	INT			= 1
	--		,@EmployeeId	INT			= 6
	--		,@FromDate		DATETIME	= '2025-01-01'
	--		,@Punchdate		DATE		= NULL
	--		,@IsWeekly		BIT			= 0

	DECLARE	@ToDate	DATETIME;

	IF (YEAR(@FromDate) = YEAR(GETDATE()) AND MONTH(@FromDate) = MONTH(GETDATE()))
	BEGIN
		SET @ToDate = GETDATE();
	END
	ELSE
	BEGIN
		SET @ToDate = DATEADD(DAY, -1, DATEADD(MONTH, DATEDIFF(MONTH, 0, @FromDate) + 1, 0));
	END;

	DECLARE @CompanyId						INT
			,@CurrentMonthWorkingHours 		NVARCHAR(50)
			,@StartDate						DATETIME = @FromDate
			,@EndDate						DATETIME = @ToDate
			,@TodayTotalWorkingHours		NVARCHAR(50)
			,@ThisWeekTotalWorkingHours		NVARCHAR(50)
			,@TotalRemainingHours			VARCHAR(50)
			,@TotalOvertimeHours			NVARCHAR(50)
			,@TotalSeconds					INT
			,@TotalHr						NVARCHAR(50)
			,@StartOfWeek					DATE = DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
			,@EndOfWeek						DATE = DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
			,@TotalWeekHours				NVARCHAR(50)
			,@TSecond						INT
			,@CurrentMonthSeconds			NVARCHAR(50)
			,@RemainingSeconds				INT 
			,@TotalSecond					INT
			,@ThisMonthTotalWorkingHours	NVARCHAR(50)
			,@OverTimeSecond				INT
			,@OverTimeData					INT
			,@WorkingHours					TIME
			,@Holiday						NVARCHAR(50)
			,@UserGroupId					TINYINT
			,@diffTime						NVARCHAR(30)
			,@LastStatus					INT
			,@TotalMonthSecond				INT
			,@CurrentMonth					INT
			,@ThisMonthMinutes				INT
			,@CurrentMonthMinutes			INT
			,@DifferenceMinutes				INT;

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id				INT		IDENTITY(1,1)
		,PunchDate		DATE
		,CompanyId		TINYINT
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate, CompanyId) 
		VALUES		(@StartDate,@CompanyId);

		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;
	
	DROP TABLE IF EXISTS #ResultSet;
	SELECT	DISTINCT ED.EmployeeId
			,CONCAT(FirstName,' ',LastName) AS EmpName
			,CONVERT(VARCHAR(50), AT.PunchDate, 113) AS [Date]
			,DATENAME(DW,AT.PunchDate) AS [Day]
			,AT.PunchDate
			,RIGHT(LEFT(CONVERT(VARCHAR(20), CAST(PH.InTime AS TIME), 100), 7), 8) AS PunchIn
			,ISNULL(FORMAT(PunchOut, 'hh:mm tt'), '') AS PunchOut
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, CONVERT(TIME, PH.InTime), CONVERT(TIME, PH.OutTime)), 0), 114),'00:00'),5),' Hrs') AS TotalHours
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5),' Hrs') AS WorkingHours
			,ISNULL(BH. [Break],'00:00 Hrs') AS [Break]
			,CASE WHEN OutTime_NULL IS NULL AND PH.PunchDate = CONVERT(DATE,GETDATE())
						AND CONVERT(TIME,OH.EndTime) < CONVERT(TIME,OutTime)
					THEN CONCAT(LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.EndTime, CONVERT(TIME, GETDATE())), 0), 114),5),' Hrs')
				ELSE OH.OverTime END AS OverTime
			, CONCAT(LEFT(CASE WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) <= PD.EndTime THEN '00:00 Hrs'
							   WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) > PD.EndTime THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PD.EndTime, CONVERT(TIME, PH.InTime)), 0), 114)
							WHEN CONVERT(TIME, PH.InTime) > OH.StartTime 
							THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.StartTime, CONVERT(TIME, PH.InTime)), 0), 114)  
						ELSE '00:00' END,5), ' Hrs'
				) AS lateCheckin  
			,CONCAT(LEFT(ISNULL(PD.NumberOfHours,'00:00'), 5), ' Hrs') As PermissionHours
  			,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Leave/CompOff'
					WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'CompOff/Leave'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Leave/Present'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Present/Leave'
					WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'WeekEnd' 
					WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Holiday'
					WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Leave'
					WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Absent' 
					WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'CompOff'
					WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'YetToRegularize'
					WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Present' 
					WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Present' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
						AND TotalMinutesPerDay < 240 THEN 'Absent' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'HalfDay' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'HalfDay' 
					ELSE 'Present'
			END AS [Status]
			,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
					WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Yellow'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Green'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Yellow'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Orange'
					WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'Red' 
					WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Red'
					WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Orange'
					WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Red' 
					WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'Pink'
					WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'Red'
					WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Green' 
					WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Green' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
						AND TotalMinutesPerDay < 240 THEN 'Red' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'Blue' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'Blue' 
					ELSE 'Green'
			END AS Status_Colour
	INTO	#ResultSet
	FROM	EmployeeDetails ED
	CROSS JOIN #Attendance AT
	LEFT JOIN	(
					SELECT	CompanyId, IsWorkingDay, [Day] 	
					FROM	[dbo].[CompanyWorkingDayDetails]
					WHERE	IsWorkingDay = 0
					AND		CompanyId = @CompanyId
				) AS CWDD
		ON	CWDD.CompanyId = ED.CompanyId
		AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
	LEFT JOIN [dbo].[HolidayDetails] HD
		ON	AT.PunchDate = HD.HolidayDate
	LEFT JOIN (	
				SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
				FROM	EmployeeShiftMappingDetails ESMD
				JOIN	EmployeeDetails ED
					ON	ESMD.EmployeeId = ED.EmployeeId
				LEFT JOIN ShiftDetails SD
					ON	SD.ShiftId = ESMD.ShiftId 
			) AS ESMD
		ON ED.EmployeeId = ESMD.EmployeeId 
		AND AT.PunchDate BETWEEN StartDate AND EndDate
	LEFT JOIN (
				SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
						,MAX(OutTime) AS OutTime
						,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
						,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,CONVERT(TIME,PunchTime) AS InTime
									,Status
									,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
												AND  CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
										WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
												AND  CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
										ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate ORDER BY CONVERT(TIME,PunchTime))
									END) AS OutTime
							FROM	[dbo].[EmployeeDetails] ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
							WHERE	ED.EmployeeId = @EmployeeId
						) AS ALD
				WHERE	[Status] = 1
				GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate) 
			) AS PH
		ON ED.EmployeeId = PH.EmployeeId 
		AND AT.PunchDate = PH.PunchDate
	LEFT JOIN (
				SELECT	EmployeeId
						,PunchDate
						,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, SUM(BreakMinutes), 0), 114),'00:00'),5),' Hrs') AS [Break]
				FROM	(
							SELECT	ED.EmployeeId
									,ALD.PunchDate
									,LEAD(ALD.Status) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime) AS A
									,CASE  WHEN ALD.[Status] = 0
										THEN DATEDIFF(MINUTE, ALD.PunchTime, LEAD(ALD.PunchTime) OVER (PARTITION BY ALD.PunchDate ORDER BY ALD.PunchTime))
										ELSE 0 
									END AS BreakMinutes
									,[Status]
							FROM	[dbo].[EmployeeDetails] ED
							JOIN	[dbo].[AttendanceLogDetails] ALD
								ON  ED.EmployeeId = ALD.EmployeeId
							WHERE	ED.EmployeeId = @EmployeeId						
						) AS ALD
				WHERE	[Status] = 0
				GROUP BY EmployeeId, PunchDate
			) AS BH
		ON ED.EmployeeId = BH.EmployeeId 
		AND AT.PunchDate = BH.PunchDate
	LEFT JOIN (
				SELECT	DISTINCT ALD.EmployeeId
						,ALD.PunchDate
						,ALD.LastOutTime
						,SD.StartTime
						,SD.EndTime
						,CONCAT(LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE,CASE WHEN ALD.LastOutTime > SD.EndTime 
																THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
												ELSE 0 END, 0), 114),5),' Hrs') AS OverTime 
				FROM	(
							SELECT	EmployeeId
									,PunchDate
									,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
							FROM	[dbo].[AttendanceLogDetails]
							WHERE	EmployeeId = @EmployeeId
							GROUP BY EmployeeId, PunchDate
						) AS ALD
				LEFT JOIN	[dbo].[EmployeeShiftMappingDetails] ESMD
					ON	ALD.EmployeeId = ESMD.EmployeeId
				LEFT JOIN	[dbo].[ShiftDetails] SD
					ON	ESMD.ShiftId = SD.ShiftId
				)OH
			ON ED.EmployeeId = OH.EmployeeId 
			AND AT.PunchDate = OH.PunchDate
	LEFT JOIN (
				SELECT	EmployeeId
						,PermissionDate
						,NumberOfHours
						,DATEDIFF(MINUTE,0,NumberOfHours) AS NoOfHours
						,EndTime
						,StartTime
				FROM	[dbo].[PermissionDetails]	
				WHERE	EmployeeId = @EmployeeId
				) AS PD
		ON ED.EmployeeId = PD.EmployeeId 
		AND AT.PunchDate = PD.PermissionDate
	LEFT JOIN	(	
				SELECT	EmployeeId, PunchDate, PunchOut
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,MAX(PunchTime) AS PunchOut
									,[Status]
							FROM	[dbo].[EmployeeDetails] ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
							WHERE	ED.EmployeeId = @EmployeeId
							GROUP BY ED.EmployeeId, PunchDate, [Status], DATENAME(DW,PunchDate) 
						) AS A
				WHERE	[Status] = 0
				) AS PO
		ON ED.EmployeeId = PO.EmployeeId 
		AND AT.PunchDate = PO.PunchDate
	LEFT JOIN	(
					SELECT	EmployeeId, FromDate, ToDate, LeaveStatusId, IsHalfDay, IsFirstHalf, LeaveTypeId
					FROM	[dbo].[LeaveDetails]
					WHERE	EmployeeId = @EmployeeId
					AND		LeaveStatusId IN (2, 3)
					AND		LeaveTypeId <> 2
				) AS LD
		ON ED.EmployeeId = LD.EmployeeId 
		AND AT.PunchDate BETWEEN FromDate AND ToDate
	LEFT JOIN	(
					SELECT	EmployeeId, FromDate, ToDate, LeaveTypeId, IsHalfDay, IsFirstHalf
					FROM	[dbo].[LeaveDetails] 
					WHERE	LeaveStatusId IN (2, 3)
					AND		EmployeeId = @EmployeeId
					AND		LeaveTypeId = 2
				) AS LSD
		ON ED.EmployeeId = LSD.EmployeeId 
		OR AT.PunchDate BETWEEN LSD.FromDate AND LSD.ToDate
	WHERE	ED.EmployeeId = @EmployeeId;
	 
	DROP TABLE IF EXISTS #EmployeeDetails;
	CREATE TABLE #EmployeeDetails
	(
		EmployeeId				INT
		,EmployeeCompanyId		NVARCHAR(100)
		,EmpName				NVARCHAR(100)
		,ReportingPersonId		INT
		,CompanyId				TINYINT
	);
	
	INSERT INTO #EmployeeDetails(EmployeeId, EmployeeCompanyId, EmpName, ReportingPersonId, CompanyId)
	SELECT		ED.EmployeeId, ED.EmployeeCompanyId, CONCAT(ED.FirstName,' ',ED.LastName)
				,ED.ReportingPersonId, ED.CompanyId
	FROM	[dbo].[EmployeeDetails] ED
	LEFT JOIN [dbo].[EmployeeDetails] RPD
		ON	RPD.EmployeeId = ED.EmployeeId
	WHERE	ED.ReportingPersonId = @EmployeeId;

	DROP TABLE IF EXISTS #ResultSet_MyTeam;
	SELECT	DISTINCT ED.EmployeeId
			,EmpName
			,CONVERT(VARCHAR(50), AT.PunchDate, 113) AS [Date]
			,DATENAME(DW,AT.PunchDate) AS [Day]
			,AT.PunchDate
			,RIGHT(LEFT(CONVERT(VARCHAR(20), CAST(PH.InTime AS TIME), 100), 7), 8) AS PunchIn
			--,ISNULL(FORMAT(PH.InTime, 'hh:mm tt'), '') AS PunchIn
			,ISNULL(FORMAT(PunchOut, 'hh:mm tt'), '') AS PunchOut
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, CONVERT(TIME, PH.InTime), CONVERT(TIME, PH.OutTime)), 0), 114),'00:00'),5),' Hrs') AS TotalHours
			,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5),' Hrs') AS WorkingHours
			,ISNULL(BH. [Break],'00:00 Hrs') AS [Break]
			,CASE WHEN OutTime_NULL IS NULL AND PH.PunchDate = CONVERT(DATE,GETDATE())
						AND CONVERT(TIME,OH.EndTime) < CONVERT(TIME,OutTime)
					THEN CONCAT(LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.EndTime, CONVERT(TIME, GETDATE())), 0), 114),5),' Hrs')
				ELSE OH.OverTime END AS OverTime
			, CONCAT(LEFT(CASE WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) <= PD.EndTime THEN '00:00 Hrs'
							   WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) > PD.EndTime THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PD.EndTime, CONVERT(TIME, PH.InTime)), 0), 114)
							WHEN CONVERT(TIME, PH.InTime) > OH.StartTime 
							THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.StartTime, CONVERT(TIME, PH.InTime)), 0), 114)  
						ELSE '00:00' END,5), ' Hrs'
				) AS lateCheckin
			,CONCAT(LEFT(ISNULL(PD.NumberOfHours,'00:00'), 5), ' Hrs') As PermissionHours
			,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Leave/CompOff'
					WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'CompOff/Leave'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Leave/Present'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Leave/Absent'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Present/Leave'
					WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'WeekEnd' 
					WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Holiday'
					WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Leave'
					WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Absent' 
					WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'CompOff'
					WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'YetToRegularize'
					WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Present' 
					WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Present' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
						AND TotalMinutesPerDay < 240 THEN 'Absent' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'HalfDay' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'HalfDay' 
					ELSE 'Present'
			END AS [Status] 
			,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
					WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Yellow'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Green'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Yellow'
					WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Orange'
					WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'Purple' 
					WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Red'
					WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Orange'
					WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Red' 
					WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'Pink'
					WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'
					),5) > '11:59' THEN 'Red'
					WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Green' 
					WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Green' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
						AND TotalMinutesPerDay < 240 THEN 'Red' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'Blue' 
					WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'Blue' 
					ELSE 'Green'
			END AS Status_Colour
	INTO	#ResultSet_MyTeam
	FROM	#EmployeeDetails AS ED
	CROSS JOIN #Attendance AT
	LEFT JOIN	(
					SELECT	CompanyId, IsWorkingDay, [Day]
							,CASE WHEN IsWorkingDay = 0 THEN 0 ELSE 1 END AS WeekEndDays	
					FROM	[dbo].[CompanyWorkingDayDetails]
					WHERE	IsWorkingDay = 0
					AND		CompanyId = @CompanyId
				) AS CWDD
		ON	CWDD.CompanyId = ED.CompanyId
		AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
	LEFT JOIN [dbo].[HolidayDetails] HD
		ON	AT.PunchDate = HD.HolidayDate
	LEFT JOIN (	
				SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
				FROM EmployeeShiftMappingDetails ESMD
				JOIN	#EmployeeDetails ED
					ON	ESMD.EmployeeId = ED.EmployeeId
				LEFT JOIN ShiftDetails SD
					ON	SD.ShiftId = ESMD.ShiftId 
			) AS ESMD
		ON ED.EmployeeId = ESMD.EmployeeId 
		AND AT.PunchDate BETWEEN StartDate AND EndDate
	LEFT JOIN (
				SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime
						,MAX(OutTime) AS OutTime
						,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
						,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,CONVERT(TIME,PunchTime) AS InTime
									,Status
									,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY ALD.EmployeeId, PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
												AND  CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
										WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY ALD.EmployeeId, PunchDate ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
												AND  CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
										ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY ALD.EmployeeId, PunchDate ORDER BY CONVERT(TIME,PunchTime))
									END) AS OutTime
							FROM	#EmployeeDetails ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
						) AS ALD
				WHERE	[Status] = 1
				GROUP BY EmployeeId, PunchDate
			) AS PH
		ON ED.EmployeeId = PH.EmployeeId 
		AND AT.PunchDate = PH.PunchDate
	LEFT JOIN (
				SELECT	EmployeeId
						,PunchDate
						,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, SUM(BreakMinutes), 0), 114),'00:00'),5),' Hrs') AS [Break]
				FROM	(
							SELECT	ED.EmployeeId
									,ALD.PunchDate
									,LEAD(ALD.Status) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime) AS A
									,CASE  WHEN ALD.[Status] = 0
										THEN DATEDIFF(MINUTE, ALD.PunchTime, LEAD(ALD.PunchTime) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime))
										ELSE 0 
									END AS BreakMinutes
									,[Status]
							FROM	#EmployeeDetails ED
							JOIN	[dbo].[AttendanceLogDetails] ALD
								ON  ED.EmployeeId = ALD.EmployeeId			
						) AS ALD
				WHERE	[Status] = 0
				GROUP BY EmployeeId, PunchDate
			) AS BH
		ON ED.EmployeeId = BH.EmployeeId 
		AND AT.PunchDate = BH.PunchDate
	LEFT JOIN (
				SELECT	DISTINCT ALD.EmployeeId
						,ALD.PunchDate
						,ALD.LastOutTime
						,SD.StartTime
						,SD.EndTime
						,CONCAT(LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE,CASE WHEN ALD.LastOutTime > SD.EndTime 
																THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
												ELSE 0 END, 0), 114),5),' Hrs') AS OverTime 
				FROM	(
							SELECT	ALD.EmployeeId
									,PunchDate
									,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
							FROM	[dbo].[AttendanceLogDetails] ALD 
							JOIN	#EmployeeDetails ED
								ON	ED.EmployeeId = ALD.EmployeeId
							GROUP BY ALD.EmployeeId, PunchDate
						) AS ALD
				LEFT JOIN	[dbo].[EmployeeShiftMappingDetails] ESMD
					ON	ALD.EmployeeId = ESMD.EmployeeId
				LEFT JOIN	[dbo].[ShiftDetails] SD
					ON	ESMD.ShiftId = SD.ShiftId
				)OH
			ON ED.EmployeeId = OH.EmployeeId 
			AND AT.PunchDate = OH.PunchDate
	LEFT JOIN (
				SELECT	PD.EmployeeId
						,PermissionDate
						,NumberOfHours
						,DATEDIFF(MINUTE,0,NumberOfHours) AS NoOfHours
						,EndTime
						,StartTime
				FROM	[dbo].[PermissionDetails] PD 
				LEFT JOIN #EmployeeDetails ED
					ON	PD.EmployeeId = ED.EmployeeId
				) AS PD
		ON ED.EmployeeId = PD.EmployeeId 
		AND AT.PunchDate = PD.PermissionDate
	LEFT JOIN	(	
				SELECT	EmployeeId, PunchDate, PunchOut
				FROM	(
							SELECT	ED.EmployeeId
									,PunchDate
									,MAX(PunchTime) AS PunchOut
									,[Status]
							FROM	#EmployeeDetails ED	
							JOIN	[dbo].[AttendanceLogDetails] ALD	
								ON	ED.EmployeeId = ALD.EmployeeId 
							GROUP BY ED.EmployeeId, PunchDate, [Status]
						) AS A
				WHERE	[Status] = 0
				) AS PO
		ON ED.EmployeeId = PO.EmployeeId 
		AND AT.PunchDate = PO.PunchDate
	LEFT JOIN	(
					SELECT	LD.EmployeeId, FromDate, ToDate, LeaveStatusId, IsHalfDay, IsFirstHalf, LeaveTypeId
					FROM	[dbo].[LeaveDetails] LD
					JOIN	#EmployeeDetails ED
						ON	LD.EmployeeId = ED.EmployeeId
					AND		LeaveStatusId IN (2, 3)
					AND		LeaveTypeId <> 2
				) AS LD
		ON ED.EmployeeId = LD.EmployeeId 
		AND AT.PunchDate BETWEEN LD.FromDate AND LD.ToDate
	LEFT JOIN	(
					SELECT	LSD.EmployeeId, FromDate, ToDate, LeaveTypeId, IsHalfDay, IsFirstHalf
					FROM	[dbo].[LeaveDetails] LSD
					JOIN	#EmployeeDetails ED
						ON	LSD.EmployeeId = ED.EmployeeId
					WHERE	LeaveStatusId IN (2, 3) 
					AND		LeaveTypeId = 2
				) AS LSD
		ON ED.EmployeeId = LSD.EmployeeId 
		AND AT.PunchDate BETWEEN LSD.FromDate AND LSD.ToDate
	WHERE	ED.ReportingPersonId = @EmployeeId;

	SELECT  @Holiday = HolidayName
	FROM	[dbo].[HolidayDetails]
	WHERE	HolidayDate = CONVERT(DATE,DATEFROMPARTS(YEAR(@FromDate) , MONTH(@FromDate), DAY(@Punchdate)));
	
	BEGIN TRY
		IF @PunchDate IS NULL
		BEGIN	
			DROP TABLE IF EXISTS #Statistics;
			SELECT	PunchDate AS [Date]
					,EmployeeId
					,ISNULL(LEFT(WorkingHours,5), '00:00:00') AS Production
			INTO	#Statistics
			FROM	#ResultSet WH
			WHERE	YEAR(PunchDate) = YEAR(CONVERT(DATE,GETDATE())) 
			AND		MONTH(PunchDate) = MONTH(CONVERT(DATE,GETDATE()));

			SELECT	@TodayTotalWorkingHours = LEFT(Production, 8)	
			FROM	#Statistics
			WHERE	CONVERT(DATE, [Date]) = CONVERT(DATE, GETDATE())
			AND		EmployeeId = @LoginUserId;

			BEGIN
				SELECT	@TodayTotalWorkingHours =	CASE WHEN CONCAT(LEFT(Production,5),' Hrs') IS NULL THEN '00:00:00 Hrs'
													   ELSE CONCAT(LEFT(Production,5),' Hrs') END 
				FROM	#Statistics
				WHERE	CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE())
				AND		EmployeeId = @EmployeeId;
			END;

			SELECT	@TotalHr = LEFT(CONVERT(VARCHAR(50),DATEADD(MINUTE, DATEDIFF(MINUTE,StartTime, EndTime),0),114),5)
			FROM	[dbo].[ShiftDetails] SD
			LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD 
				ON	SD.ShiftId = ESMD.ShiftId
			WHERE	ESMD.EmployeeId = @EmployeeId
			AND		CONVERT(DATE, GETDATE()) BETWEEN CONVERT(DATE, StartDate) AND CONVERT(DATE, EndDate)
				
			SELECT	@ThisWeekTotalWorkingHours = CASE WHEN SUM(TotalSeconds) = 0 THEN '00:00'
														ELSE CONCAT(SUM(TotalSeconds) / 3600, ':',(SUM(TotalSeconds) % 3600) / 60) 
												END 
			FROM	(
						SELECT	DISTINCT DATEDIFF(SECOND, 0, CAST(Production AS TIME)) AS TotalSeconds
						FROM	#Statistics
						WHERE	DATEPART(WEEK, [Date]) = DATEPART(WEEK, GETDATE())
						AND		DATEPART(YEAR, [Date]) = DATEPART(YEAR, GETDATE())
					) AS A;

			SELECT	@TotalWeekHours = CONCAT(SUM(DATEDIFF(MINUTE, 0, CONVERT(TIME, Duration))) / 60,':',
										FORMAT(SUM(DATEDIFF(MINUTE, 0, CONVERT(TIME, Duration))) % 60, '00'))
			FROM	(
						SELECT	CASE	WHEN StartTime IS NOT NULL AND EndTime IS NOT NULL 
										THEN FORMAT(DATEADD(MINUTE, DATEDIFF(MINUTE, CONVERT(TIME, StartTime), CONVERT(TIME, EndTime)), 0), 'HH:mm')
									ELSE '00:00' END AS Duration
						FROM	[dbo].[ShiftDetails] SD
						LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD 
							ON	SD.ShiftId = ESMD.ShiftId
						LEFT JOIN  [dbo].[HolidayDetails] HD 
							ON	HD.HolidayDate BETWEEN StartDate AND EndDate
						WHERE	ESMD.EmployeeId = @LoginUserId
						AND		(StartDate BETWEEN @StartOfWeek AND @EndOfWeek)
						AND		(EndDate BETWEEN @StartOfWeek AND @EndOfWeek)
						AND		(HD.HolidayDate IS NULL OR (HD.HolidayDate IS NOT NULL AND ESMD.ShiftId IS NOT NULL))
					) AS A		

			SELECT	@ThisMonthTotalWorkingHours = CASE WHEN SUM(TotalSeconds) = 0 THEN '00:00'
														ELSE CONCAT(SUM(TotalSeconds) / 3600, ':',(SUM(TotalSeconds) % 3600) / 60) 
												END 
			FROM	(
						SELECT	DISTINCT DATEDIFF(SECOND, 0, CAST(Production AS TIME)) AS TotalSeconds
						FROM	#Statistics
						WHERE	DATEPART(MONTH, [Date]) = DATEPART(MONTH, GETDATE())
						AND		DATEPART(YEAR, [Date]) = DATEPART(YEAR, GETDATE())
					) AS A;

			SELECT	@CurrentMonthWorkingHours = CONCAT(	SUM(DATEDIFF(MINUTE, 0, CONVERT(TIME, Duration))) / 60,':',
													FORMAT(SUM(DATEDIFF(MINUTE, 0, CONVERT(TIME, Duration))) % 60, '00'))
			FROM	(
						SELECT	CASE	WHEN StartTime IS NOT NULL AND EndTime IS NOT NULL 
										THEN FORMAT(DATEADD(MINUTE, DATEDIFF(MINUTE, CONVERT(TIME, StartTime), CONVERT(TIME, EndTime)), 0), 'HH:mm')
									ELSE '00:00' END AS Duration
						FROM	[dbo].[ShiftDetails] SD
						LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD 
							ON	SD.ShiftId = ESMD.ShiftId
						LEFT JOIN  [dbo].[HolidayDetails] HD 
							ON	HD.HolidayDate BETWEEN StartDate AND EndDate
						WHERE	EmployeeId = @LoginUserId
						AND		YEAR(StartDate) = YEAR(GETDATE())
						AND		MONTH(StartDate) = MONTH(GETDATE())
						AND		MONTH(EndDate) = MONTH(GETDATE())
						AND		(HD.HolidayDate IS NULL OR (HD.HolidayDate IS NOT NULL AND ESMD.ShiftId IS NOT NULL))
					) AS A	
					
			SET @ThisMonthMinutes = CAST(LEFT(@ThisMonthTotalWorkingHours, CHARINDEX(':', @ThisMonthTotalWorkingHours) - 1) AS INT) * 60
									+ CAST(RIGHT(@ThisMonthTotalWorkingHours, LEN(@ThisMonthTotalWorkingHours) - CHARINDEX(':', @ThisMonthTotalWorkingHours)) AS INT);

			SET @CurrentMonthMinutes = CAST(LEFT(@CurrentMonthWorkingHours, CHARINDEX(':', @CurrentMonthWorkingHours) - 1) AS INT) * 60
										+ CAST(RIGHT(@CurrentMonthWorkingHours, LEN(@CurrentMonthWorkingHours) - CHARINDEX(':', @CurrentMonthWorkingHours)) AS INT);

			SET @DifferenceMinutes = (@CurrentMonthMinutes - @ThisMonthMinutes);

			SELECT	@TotalRemainingHours = CONCAT(@DifferenceMinutes / 60, ':', RIGHT('00' + CAST(@DifferenceMinutes % 60 AS VARCHAR), 2))

			;WITH OverTimeCTE 
			AS	(
					SELECT	DISTINCT DATEDIFF(MINUTE, 0, LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE
									,CASE WHEN ALD.LastOutTime > SD.EndTime 
											THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
										ELSE 0 END, 0), 114), 5)) AS OverTime
					FROM	(	SELECT	EmployeeId
										,PunchDate
										,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
								FROM	[dbo].[AttendanceLogDetails]
								WHERE	EmployeeId = @EmployeeId
								GROUP BY EmployeeId, PunchDate
							) AS ALD
					LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD
						ON	ALD.EmployeeId = ESMD.EmployeeId
					LEFT JOIN [dbo].[ShiftDetails] SD
						ON	ESMD.ShiftId = SD.ShiftId
					WHERE  YEAR(PunchDate) = YEAR(GETDATE())
					AND		MONTH(PunchDate) = MONTH(GETDATE())
					AND		ALD.EmployeeId = @EmployeeId
				)
			SELECT	@TotalOvertimeHours = CASE WHEN CONCAT(SUM(OverTime) / 60, ':', RIGHT('00' + CAST(SUM(OverTime) % 60 AS VARCHAR), 2)) = ':'
												THEN '00:00' ELSE CONCAT(SUM(OverTime) / 60, ':', RIGHT('00' + CAST(SUM(OverTime) % 60 AS VARCHAR), 2))
											END 
			FROM	OverTimeCTE;

			-- First ResultSet for the Statistics Logic.
			SELECT	CASE WHEN ISNULL(@TodayTotalWorkingHours,'') = '' OR ISNULL(@TotalHr,'') = '' THEN '00:00:00 Hrs / 00:00 Hrs' 
						ELSE CONCAT(@TodayTotalWorkingHours,' / ',CONCAT(@TotalHr,' Hrs')) 
					END AS Today
					,CASE WHEN ISNULL(@ThisWeekTotalWorkingHours,'') = '' OR ISNULL(@TotalWeekHours,'') = '' THEN '00:00:00 Hrs / 00:00 Hrs'  
						ELSE CONCAT(CONCAT(@ThisWeekTotalWorkingHours,' Hrs'),' / ',REPLACE(CONCAT(@TotalWeekHours,' Hrs'),': Hrs','00:00 Hrs'))
					END AS ThisWeek
					,CASE WHEN ISNULL(@ThisMonthTotalWorkingHours,'') = '' OR ISNULL(@ThisMonthTotalWorkingHours,'') = '' THEN '00:00:00 Hrs / 00:00 Hrs'  
						ELSE CONCAT(CONCAT(@ThisMonthTotalWorkingHours,' Hrs'),' / ',REPLACE(CONCAT(@CurrentMonthWorkingHours,' Hrs'),': Hrs','00:00 Hrs'))
					END	AS ThisMonth
					,CASE WHEN ISNULL(@TotalRemainingHours,'') = '' OR ISNULL(@CurrentMonthWorkingHours,'') = '' THEN '00:00:00 Hrs / 00:00 Hrs'  
						ELSE CONCAT(CONCAT(@TotalRemainingHours,' Hrs'),' / ',REPLACE(CONCAT(@CurrentMonthWorkingHours,' Hrs'),': Hrs','00:00 Hrs'))
					END AS Remaining
					,CASE WHEN ISNULL(@TotalOvertimeHours,'') = '' OR ISNULL(@CurrentMonthWorkingHours,'') = '' THEN '00:00:00 Hrs / 00:00 Hrs' 
						ELSE CONCAT(CONCAT(@TotalOvertimeHours,' Hrs'),' / ',CONCAT(@CurrentMonthWorkingHours,' Hrs'))
					END AS OverTime

			SELECT	PunchIn, PunchOut, InLocation, OutLocation
			FROM	(
						SELECT	ISNULL(FORMAT(PunchTime,'hh:mm tt'),'')  AS PunchIn
								,ISNULL(FORMAT(LEAD(PunchTime) OVER(ORDER BY ALD.PunchTime),'hh:mm tt'),'')  AS PunchOut
								,ALD.[Location] AS InLocation
								,LEAD(ALD.[Location]) OVER(ORDER BY ALD.PunchTime) AS OutLocation
								,[Status]
						FROM	[dbo].[AttendanceLogDetails] ALD
						WHERE	CONVERT(DATE,ALD.PunchDate) = CONVERT(DATE, GETDATE())
						AND		ALD.EmployeeId = @EmployeeId
					) AS A
			WHERE	[Status] = 1;
			
			IF @UserGroupId IN (1,2)
			BEGIN 
				IF @IsWeekly = 1
				BEGIN
					SELECT	EmployeeId
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,ISNULL(OverTime,'00:00 Hrs') AS OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM	#Resultset R
					WHERE	R.[Date] >= DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE)) 
					AND		R.[Date] < DATEADD(DAY, 8 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
					ORDER BY [Date] DESC, EmployeeId ASC;

					SELECT  EmployeeId
							,EmpName
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,ISNULL(OverTime,'00:00 Hrs') AS OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM    #ResultSet_MyTeam R    
					WHERE   R.[Date] >= DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
					AND		R.[Date] < DATEADD(DAY, 8 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
					ORDER BY [Date] DESC, EmployeeId ASC;
				END
				ELSE
				BEGIN
					SELECT  EmployeeId
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,ISNULL(OverTime,'00:00 Hrs') AS OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM	#Resultset R
					ORDER BY [Date] DESC, EmployeeId ASC;

					SELECT  EmployeeId
							,EmpName
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,ISNULL(OverTime,'00:00 Hrs') AS OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM    #ResultSet_MyTeam R    
					ORDER BY [Date] DESC, EmployeeId ASC;
				END 
			END
			ELSE IF @UserGroupId = 3
			BEGIN 
				IF @IsWeekly = 1
				BEGIN
					SELECT  EmployeeId
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM    #Resultset R
					WHERE   R.[Date] >= DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
					AND		R.[Date] < DATEADD(DAY, 8 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE))
					ORDER BY R.[Date] DESC;
				END
				ELSE
				BEGIN
					SELECT  EmployeeId
							,[Date]
							,[Day]
							,PunchIn
							,PunchOut
							,TotalHours
							,WorkingHours
							,[Break]
							,OverTime
							,lateCheckin
							,PermissionHours
							,[Status]
							,Status_Colour
					FROM    #Resultset R
					ORDER BY R.[Date] DESC;
				END 
			END
		END 
		ELSE
		BEGIN
			SELECT	DISTINCT ED.EmployeeId
					,EmployeeCompanyId
					,CONCAT(ED.FirstName , ' ' , LastName) AS EmployeeName
					,CONVERT(VARCHAR(50),R.PunchDate,105) AS PunchDate
					,TotalHours
					,WorkingHours
			FROM	(	SELECT	EmployeeId, PunchDate, TotalHours, WorkingHours
						FROM	#ResultSet 
						WHERE	PunchDate = @PunchDate
						AND		EmployeeId = @EmployeeId
					) AS R 
			LEFT JOIN (	SELECT	EmployeeId, EmployeeCompanyId, FirstName, LastName
						FROM	[dbo].[EmployeeDetails] 
						WHERE	CompanyId  = @CompanyId
						AND		EmployeeId = @EmployeeId
					) AS ED
				ON	ED.EmployeeId = R.EmployeeId;
			
			SELECT	ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS PunchIn
					,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
					,CONCAT(CASE WHEN PunchOut IS NULL THEN LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PunchIn, CONVERT(TIME, GETDATE())),0), 114),5)
						ELSE LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PunchIn, PunchOut),0), 114),5)  
					END,' Hrs') AS NoOfHours	
					,InLocation
					,OutLocation
			FROM	(
						SELECT	DISTINCT PunchTime AS PunchIn
								,LEAD(PunchTime) OVER(ORDER BY PunchTime) AS PunchOut
								,[Status]
								,[Location] AS InLocation
								,LEAD([Location]) OVER(ORDER BY PunchTime) AS OutLocation
						FROM	AttendanceLogDetails
						WHERE	EmployeeId = @EmployeeId
						AND		PunchDate = @Punchdate
					) AS A
			WHERE	[Status] = 1;
		END
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=================================================================================================================================================
	DECLARE	@S_Status		BIT
			,@M_Message		NVARCHAR(500);
			 
	EXEC [dbo].[USP_GetAttendanceLogDetails_Employee] 	@LoginUserId	=	1
														,@EmployeeId	=	9
														,@FromDate		=	'2025-01-01'
														,@PunchDate		=	'2025-01-10'   
														,@IsWeekly		=	0
														,@Status		=	@S_Status  OUT
														,@Message		=	@M_Message OUT; 

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT  *
	FROM	[dbo].[EmployeeDetails];
	
	SELECT  *
	FROM	[dbo].[LeaveDetails];
	 SELECT * FROM AttendanceLogDetails WHERE PunchDate  = '2025-01-13' AND EmployeeId = 11
===================================================================================================================================================*/

	 
 
GO
