/*================================================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_GetAttendanceMachineDetails]
 Description		:	Procedure used to retrive the AttendanceMachineDetails(Get the Attendance Machine)
 Input Parameter	:	@LoginUserId, @AttendanceMachineId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	15-06-2024
 Version			:	1.0 
  Comment			:	1. Get the AttendanceMachineDetails 
						2. Then return the output Parameter values as @Status = 1 and @Message = NULL.
================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAttendanceMachineDetails]
(	
	@LoginUserId			INT
	,@AttendanceMachineId	INT
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	-- Declare the Variables.
	DECLARE @CompanyId TINYINT;
		
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
		
	BEGIN TRY
		IF @AttendanceMachineId	IS NULL
		BEGIN 
			SELECT	AMD.AttendanceMachineId
					,AttendanceMachineName AS MachineName
					,SerialNo
					,CONCAT(TotalEmployees,0) AS TotalEmployees
					,CASE WHEN AMD.IsActive = 1 THEN 'Active' ELSE 'InActive' END AS [Status]
					,CASE WHEN IsActive = 1 THEN 'Green' ELSE 'Red' END AS Status_Colour
			FROM	[dbo].[AttendanceMachineDetails] AMD
			LEFT JOIN	(	SELECT	AttendanceMachineId
									,COUNT(EmployeeId) AS TotalEmployees
							FROM	[dbo].[EmployeeDeviceMappingDetails] 
							WHERE	IsActive = 1
							GROUP BY AttendanceMachineId
						) AS EDMD
				ON	AMD.AttendanceMachineId = EDMD.AttendanceMachineId
			WHERE	CompanyId = @CompanyId
			ORDER BY AttendanceMachineId DESC;
		END 
		ELSE 
		BEGIN 
			SELECT	AttendanceMachineId
					,AttendanceMachineName 
					,SerialNo
					,MachineDescription 
					,IsActive
			FROM	[dbo].[AttendanceMachineDetails]
			WHERE	CompanyId = @CompanyId
			AND		AttendanceMachineId = @AttendanceMachineId;

			SELECT	EmployeeDeviceMappingId 
					,ED.EmployeeId
					,EmployeeCompanyId
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
					,ISNULL(EDMD.IsActive,0) AS IsActive
			FROM	[dbo].[EmployeeDetails] ED
			LEFT JOIN ( SELECT * FROM [dbo].[EmployeeDeviceMappingDetails] 
						WHERE AttendanceMachineId = 1) EDMD
				ON  ED.EmployeeId = EDMD.EmployeeId
			--WHERE	ED.EmployeeId <>1;
		END 
		SELECT	@Status   = 1
				,@Message = NULL;
		END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(100),ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END    
/*=====================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);
		
	EXEC [dbo].[USP_GetAttendanceMachineDetails]	@LoginUserId			= 1
													,@AttendanceMachineId	= 1
													,@Status				= @Status	OUT
													,@Message				= @Message	OUT;		
	SELECT @Status AS STATUS, @Message AS MESSAGE;
		
	SELECT * FROM AttendanceMachineDetails
	SELECT * FROM [EmployeeDeviceMappingDetails]
	SELECT * FROM EmployeeDetails
=====================================================================================================================*/
GO
