/*============================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetAutoGenerateIdDetails]
 Description		:	Procedure used to Get the AutoGenerateId
														 (When click on plus button in JobCreation screen)
 Input Parameter	:	@LoginUserId, @ModuleName
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. Logic to get the AutoGenerateId for the Given @ModuleName.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.
============================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetAutoGenerateIdDetails]
(	
	@LoginUserId	INT
	,@ModuleName	NVARCHAR(50)
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @ModuleName = 'JobCreation'
		BEGIN 
			SELECT	CASE  WHEN MAX(JobId) IS NULL THEN 'JOB_1' 
						ELSE CONCAT('JOB_', CAST(SUBSTRING(MAX(JobId), PATINDEX('%[0-9]%', MAX(JobId)), LEN(MAX(JobId))) AS INT) + 1)
					END AS JobId
			FROM	(			
						SELECT	JobId
								,JobCreationId
								,ROW_NUMBER() OVER(ORDER BY JobCreationId DESC) AS RN
						FROM	[dbo].[JobCreationDetails]
						WHERE	CompanyId = @CompanyId
					) AS CD
			WHERE	RN = 1;
		END 
		ELSE IF @ModuleName = 'Candidate'
		BEGIN 
			SELECT	CASE  WHEN MAX(InterviewCandidateId) IS NULL THEN 'CND_1' 
						ELSE CONCAT('CND_', CAST(SUBSTRING(MAX(InterviewCandidateId), PATINDEX('%[0-9]%', MAX(InterviewCandidateId)), LEN(MAX(InterviewCandidateId))) AS INT) + 1)
					END AS InterviewCandidateId
			FROM	(			
						SELECT	InterviewCandidateId
								,CandidateId
								,ROW_NUMBER() OVER(ORDER BY CandidateId DESC) AS RN
						FROM	[dbo].[CandidateDetails]
						WHERE	CompanyId = @CompanyId
					) AS CD
			WHERE	RN = 1;
		END 
		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetAutoGenerateIdDetails]	@LoginUserId	= 1
												,@ModuleName	= 'Candidate'
												,@Status		= @S_Status	 OUT
												,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
		
	SELECT * 
	FROM	[dbo].[JobCreationDetails];
=================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetBankTransferStatementDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================  
 Procedure Name		:	[USP_GetBankTransferStatementDetails]
 Description		:	Procedure used to retrive the EmployeeTypeStructureMappingDetails
 Input Parameter	:	@LoginUserId, @SalaryStructureId
 Output Parameters	:	@Status, @Message
 Author				:	Tharani.T
 Created on			:	21-10-2024
 Version			:	1.0 
 Comment			:	1. Get the EmployeeTypeStructureMappingDetails.
=================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetBankTransferStatementDetails]
(
	@LoginUserId	INT
	,@FromDate		DATE
	,@status		BIT				OUT
	,@Message		NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	CONCAT('Bank Transfer Statement for the month of ', FORMAT(@FromDate, 'MMM, yyyy')) AS [Month]
		
		-- Result set for First page of Excel sheet.
		SELECT	BankName
				,COUNT(PayslipId) AS HeadCount
				,SUM(NetPay) AS TotalNetPay
		FROM	[dbo].[CompanyDetails] CD
		JOIN	[dbo].[PaySlipDetails_1] PD
			ON	CD.CompanyId = PD.CompanyId
		WHERE	CD.CompanyId = @CompanyId
		AND		[Month] = MONTH(@FromDate)
		AND		[Year] = YEAR(@FromDate)
		AND		PayslipStatus = 1
		GROUP BY BankName;

		-- Result set for Second page of Excel sheet.
		SELECT	EmployeeCompanyId 
				,CONCAT(FirstName,' ',LastName) AS [Name]
				,DD.DepartmentName AS Department
				,EBD.EmployeeBankName AS BankName
				,EBD.IFSCCode
				,EBD.AccountNumber
				,NetPay AS MonthlySalary
		FROM	[dbo].[PaySlipDetails_1] PD
		JOIN	[dbo].[EmployeeDetails] ED
			ON	PD.EmployeeId = ED.EmployeeId
		JOIN	[dbo].[DepartmentDetails] DD
			ON	DD.DepartmentId = ED.DepartmentId
		JOIN	[dbo].[EmployeeBankDetails] EBD
			ON  EBD.EmployeeId = ED.EmployeeId
		JOIN	[dbo].[EmployeeSalaryDetails] ESD
				ON ESD.EmployeeId = ED.EmployeeId
		ORDER BY EmployeeBankName ASC;
			
		SELECT	@Status	  = 1   
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetBankTransferStatementDetails]	@LoginUserId	= 1
														,@FromDate		= '2025-01-31'
														,@Status		= @S_Status  OUT
														,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM [dbo].[EmployeeSalaryDetails]
	SELECT * FROM [dbo].[EmployeeSalaryDetails]
======================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_GetBranchDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================  
 Procedure Name		:	[USP_GetBranchDetails]
 Description		:	Procedure used to retrive the BranchDetails (When click on BranchIcon in Setting Screen And
																	 When click on Edit Option in BranchInfo on settings Screen)
 Input Parameter	:	@LoginUserId, @BranchId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	02-08-2023
 Version			:	1.0 
 Comment			:	1. If the given @BranchId is Null,then 
							1.1 Get All the BranchDetails with the column of BranchId, BranchName, Location,Country,
								ContactNumber, Emailto show in Grid.
							1.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						2. If the given @BranchId is Not Null,then 
							2.1 Get the particular BranchDetails column of BranchId, BranchName, Address, City, State
								,Country, ZipCode, ContactNumber, Email, website for the given BranchId to show in popup.
							2.2.Then return the output Parameters values as @Status = 1 and @Message = NULL.
=================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetBranchDetails]
(
	@LoginUserId	INT
	,@BranchId		TINYINT
	,@status		BIT				OUT
	,@Message		NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given BranchId is Null, then get all the BranchDetails.
		IF (@BranchId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	BranchId
					,BranchName
					,CONCAT(City,' ',[State]) AS [Location]
					,CONCAT(Country,' - ',ZipCode) AS Country
					,ContactNumber AS ContactNo
					,Email
			FROM	[dbo].[BranchDetails]
			WHERE	CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			--If the given BranchId is Not Null, then get the particular BranchDetails.
			SELECT	BranchId
					,BranchName
					,[Address]
					,City
					,[State]
					,Country
					,ZipCode 
					,ContactNumber	
					,Email
					,MapNumber
			FROM	[dbo].[BranchDetails]
			WHERE	BranchId = @BranchId
			AND		CompanyId = @CompanyId
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetBranchDetails]   @LoginUserId	= 1
										,@BranchId		= 1
										,@Status		= @S_Status  OUT
										,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[BranchDetails];

	ALTER TABLE BranchDetails
	ADD  MapNumber NVARCHAR(100)
	
======================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetBulkDD]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


/*================================================================================================================================================
 Procedure Name 	: [USP_GetBulkDD]
 Description		: 
 Input Parameter	: @LoginUserId
 Output Parameters	: @Status, @Message
 Author				: Prakash.P
 Created on			: 26-08-2024
 Version			: 1.0 
 Comment			: 1.
=============================================================================================================================================*/
CREATE       PROCEDURE [dbo].[USP_GetBulkDD]
(
	@LoginUserId	INT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
			BEGIN
				SELECT	BranchName
				FROM	[dbo].[BranchDetails]
				WHERE	CompanyId = @CompanyId
				ORDER BY BranchId;
			END
			BEGIN
				SELECT	DepartmentName
				FROM	[dbo].[DepartmentDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY DepartmentId;
			END
			BEGIN
				SELECT	DesignationName
				FROM	[dbo].[DesignationDetails] 
				WHERE	CompanyId = @CompanyId
				ORDER BY DesignationId;
			END 
			BEGIN
				SELECT	CONCAT(FirstName,' ',LastName) AS EmployeeName
				FROM	[dbo].[EmployeeDetails] 
				ORDER BY EmployeeId;
			END
			BEGIN 
					SELECT	UserGroupName
					FROM	[dbo].[UserGroupDetails] 
					ORDER BY UserGroupId;
			END	
			BEGIN
				SELECT	EmployeeType
				FROM	[dbo].[EmployeeTypeDetails] 
				ORDER BY EmployeeTypeId;
			END
			BEGIN
				SELECT	GradeTypeName
				FROM	[dbo].[GradeTypeDetails] 
				ORDER BY GradeTypeId;
			END
			BEGIN
				SELECT	EmployeeStatusName
				FROM	[dbo].[EmployeeStatusDetails] 
				ORDER BY EmployeeStatusId;
			END		
			BEGIN
				SELECT	GenderName
				FROM	[dbo].[GenderDetails] 
				ORDER BY GenderId;
			END
			BEGIN
				SELECT	AccountTypeName
				FROM	[dbo].[AccountTypeDetails] 
				ORDER BY AccountTypeId;
			END
			BEGIN
				SELECT	PayTypeName
				FROM	[dbo].[PayTypeDetails] 
				ORDER BY PayTypeId;
			END
			BEGIN
				SELECT	PaymentTypeName
				FROM	[dbo].[PaymentTypeDetails] 
				ORDER BY PaymentTypeId;
			END
			
		SELECT	@Status   = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(100),ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END    
/*========================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500);
		
	EXEC [dbo].[USP_GetBulkDD]	@LoginUserId	= 1
												,@Status		= @Status	OUT
												,@Message		= @Message	OUT;	
												
	SELECT @Status AS STATUS, @Message AS MESSAGE;

======================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetCandidateDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetCandidateDetails]
 Description		:	Procedure used to retrieve the CandidateDetails
														(1.When Click on the Candidate in side navigation bar 
														 2.When click Edit option in grid from Candidate Screen)
 Input Parameter	:	@LoginUserId, @CandidateId
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @CandidateId IS NULL, then
							1.1 To show the counter box values 
									1. @Total AS Total
									2. @Male AS Male
									3. @Female AS Female
									4. @ImmediateJoiner AS ImmediateJoiner to show the values in Counter Box.
							1.2 Get the CandidateDetails table have the columns of CandidateId, Candidate_Id
								,CandidateName, Email, ContactNo, Gender, JobCategory, Experience, CurrentCompany
								,CurrentCTC, ExpectCTC, ExpJoiningDate, Status to show the values in Grid.
							1.3 Then return the output parameter values @Status = 1 & @Message = NULL.
						2. If the Given @CandidateId IS NOT NULL, then
							2.1 Get the CandidateDetails table have the columns of CandidateId, InterviewCandidateId
								,FirstName, LastName, Email, ContactNumber, GenderId, JobCategoryId, CandidateExperience
								,CurrentCompanyName, CurrentCTC, ExpectCTC, IsImmediateJoiner, ExpJoiningDate
								,Description, CandidateStatusId for the Given @JobCreationId to show the values
								in update Popup.
							2.2 Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetCandidateDetails]
(	
	@LoginUserId		INT
	,@CandidateId		INT
	,@FromDate			DATE 
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId			TINYINT
			,@Scheduled			INT
			,@Selected			INT
			,@OfferAccepted		INT
			,@Onboarded			INT
			,@ToDate			DATE;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SET @ToDate = EOMONTH(@FromDate);

	BEGIN TRY	
		IF @CandidateId IS NULL 
		BEGIN 			
			SELECT	@Scheduled = COUNT(CandidateId)
			FROM	[dbo].[CandidateDetails]
			WHERE	CompanyId = @CompanyId
			AND		CandidateStatusId = 2;

			SELECT	@Selected = COUNT(CandidateId)
			FROM	[dbo].[CandidateDetails]
			WHERE	CompanyId = @CompanyId
			AND		CandidateStatusId = 6;

			SELECT	@OfferAccepted = COUNT(CandidateId)
			FROM	[dbo].[CandidateDetails]
			WHERE	CompanyId = @CompanyId
			AND		CandidateStatusId = 8;
			
			SELECT	@Onboarded = COUNT(CandidateId)
			FROM	[dbo].[CandidateDetails]
			WHERE	CompanyId = @CompanyId
			AND		CandidateStatusId = 10;

			-- Result set for Counter Boxes.
			SELECT	@Scheduled			AS Scheduled
					,@Selected			AS Selected
					,@OfferAccepted		AS OfferAccepted
					,@Onboarded			AS Onboarded;

			-- Resultset for Grid.
			SELECT	CandidateId
					,InterviewCandidateId AS Candidate_Id
					,CONCAT(FirstName,' ',LastName) AS CandidateName
					,Email
					,ContactNumber AS ContactNo
					,JobName 
					,CandidateExperience AS Experience
					,CurrentCTC
					,InterviewStatusName AS [Status]
					,CASE	WHEN CandidateStatusId = 1 THEN 'Yellow'
							WHEN CandidateStatusId = 2 THEN 'Pink'
							WHEN CandidateStatusId = 3 THEN 'Orange'
							WHEN CandidateStatusId = 4 THEN 'Brown'
							WHEN CandidateStatusId = 5 THEN 'Red'
							WHEN CandidateStatusId = 6 THEN 'Green'
							WHEN CandidateStatusId = 7 THEN 'Blue'
							WHEN CandidateStatusId = 8 THEN 'Blue'
							WHEN CandidateStatusId = 9 THEN 'Purple'
							WHEN CandidateStatusId = 10 THEN 'Purple'
						ELSE ' '
					END AS Status_Colour
			FROM	[dbo].[CandidateDetails] CD
			JOIN	[dbo].[GenderDetails] GD
				ON	CD.GenderId = GD.GenderId
			LEFT JOIN	[dbo].[JobCreationDetails] JCD
				ON	CD.JobCreationId = JCD.JobCreationId
			LEFT JOIN	[dbo].[InterviewStatusDetails] ISD
				ON	CD.CandidateStatusId = ISD.InterviewStatusId
			WHERE	CD.CompanyId = @CompanyId
			AND		CONVERT(DATE,CD.CreatedDate) BETWEEN @FromDate AND @ToDate
			ORDER BY CandidateId DESC;
		END 
		ELSE 
		BEGIN
			-- Result set for Not Null.
			SELECT	CandidateId
					,InterviewCandidateId
					,FirstName
					,LastName
					,Email
					,ContactNumber
					,GenderId
					,JobCreationId
					,CandidateExperience
					,CurrentCompanyName
					,CurrentCTC
					,ExpectCTC
					,IsImmediateJoiner
					,CONVERT(NVARCHAR(50),ExpJoiningDate,105) AS ExpJoiningDate
					,[Description]
					,CandidateStatusId
					,InterviewStatusName AS CandidateStatusName
					,DesignationId
					,ReportingPersonId
					,GradeTypeId
					,EmployeeStatusId
					,[Address]
					,City
					,[State]
					,Country
					,Zipcode
					,CONVERT(NVARCHAR(50),DateOfBirth,105) AS DateOfBirth
					,ReligionId
					,MaritalStatusId
					,Nationality
					,PersonalEmail
					,AadharNo
					,PANNo
					,PassportNo
					,CONVERT(NVARCHAR(50),PassportExpDate,105) AS PassportExpDate
					,UANNumber
					,PFNumber
					,PayTypeId
					,PaymentTypeId
			FROM	[dbo].[CandidateDetails] CD
			JOIN	[dbo].[InterViewStatusDetails] CSD
				ON	CD.CandidateStatusId = CSD.InterviewStatusId
			WHERE	CandidateId = @CandidateId
			AND		CD.CompanyId = @CompanyId;

			SELECT	AttachmentId
					,ModuleName
					,ModuleRefId
					,AttachmentFileName
					,AttachmentFilePath
			FROM	[dbo].[AttachmentDetails]
			WHERE	ModuleRefId = @CandidateId
			AND		ModuleName = 'Candidate';
		END 
		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetCandidateDetails]	@LoginUserId		= 1
											,@CandidateId		= 15
											,@FromDate			= '2025-01-01'
											,@Status			= @Status   OUT
											,@Message			= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[CandidateDetails];
========================================================================================================================================*/
GO
