/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetCandidateDocumentMappingDetails]
 Description		:	Procedure used to retrieve the CandidateDocumentMappingDetails
															   (1.When Click on the Document tab in Candidate screen)
 Input Parameter	:	@LoginUserId, @CandidateId
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. Get the CandidateDocumentMappingDetails table have the columns of 
								CandidateDocumentMappingId, InterviewDocumentId, CandidateId, DucumentFileName
								,DucumentFilePath, IsActive	for the given @CandidateId.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetCandidateDocumentMappingDetails]
(	
	@LoginUserId		INT
	,@CandidateId		INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		SELECT	CandidateDocumentMappingId
				,IDD.InterviewDocumentId
				,DucumentName
				,DucumentFormat
				,CandidateId
				,DucumentFileName
				,DucumentFilePath
				,ISNULL(CDD.IsActive,0) AS IsActive
		FROM	(	SELECT	CandidateDocumentMappingId, InterviewDocumentId, CandidateId
							,DucumentFileName, DucumentFilePath, IsActive
					FROM	[dbo].[CandidateDocumentMappingDetails] 
					WHERE	CandidateId = @CandidateId
					AND		IsActive = 1
				) AS CDD
		LEFT JOIN	[dbo].[InterviewDocumentDetails] IDD
			ON	IDD.InterviewDocumentId = CDD.InterviewDocumentId;

		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC	[dbo].[USP_GetCandidateDocumentMappingDetails]	@LoginUserId		= 1
															,@CandidateId		= 1
															,@Status			= @Status   OUT
															,@Message			= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[CandidateDocumentMappingDetails];
========================================================================================================================================*/

GO
