SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:   [USP_GetClaimDetails]
 Description		:	Procedure used to retrive the ClaimDetails (1.When Click on the ClaimInfo in side navigation bar 
																	2.When click Edit option in grid from Claim Screen.)
 Input Parameter	:	@LoginUserId,@ClaimId				
 Output Parameters	:	@Status, @Message									
 Author				:	Dharani.M
 Created on			:	01-11-2023
 Version			:	1.0 
 Comment			:	1. If the given @ClaimId is NULL,then
						   1.1 Get the Counter Boxes have the Column of 
										@OverAllClaim		AS OverAll Claim
										,@TotalClaim		AS Total Claim
										,@ApprovedClaim		AS Approved Claim
										,@RequestedClaim	AS Requested Claim 
						   1.2 Get all the ClaimDetails have the columns of ClaimId,ClaimDate,RequestedBy,ClaimType,ClaimAmount 
								ApprovedBy,ApprovedAmount,ClaimStatus,Status_Colour to show in Grid.
						   1.3 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						2. If the given @ClaimId is NOT NULL,then 
							2.1 Get the particular ClaimDetails have the columns of ClaimId,ClaimDate,ClaimTypeId,ClaimAmount,ClaimDescription
								RequestedBy,ApprovedBy,ApprovedAmount,ApproverComments,ClaimStatusId,LeaveStatusName for the given ClaimId to show in popup.
							2.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetClaimDetails]
(	
	@LoginUserId		INT
	,@ClaimId			INT
	,@FromDate			DATE
	,@Mine				BIT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId				TINYINT
			,@UserGroupId			TINYINT
			,@ToDate				DATE
			,@OverAllClaimCount		INT
			,@OverAllClaimAmount	NUMERIC(11,2)
			,@RequestedClaimCount	INT
			,@RequestedClaimAmount	NUMERIC(11,2)
			,@ApprovedClaimCount	INT
			,@ApprovedClaimAmount	NUMERIC(11,2)
			,@RejectedClaimCount	INT
			,@RejectedClaimAmount	NUMERIC(11,2);

	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		--If the given @ClaimId is Null, then Get the All the ClaimDetails.
		IF @ClaimId IS NULL 
		BEGIN
			--Logic For OverallClaim,OverallClaimCount.
			SELECT	@OverAllClaimCount		= COUNT(ClaimId)
					,@OverAllClaimAmount	= SUM(ClaimAmount)
			FROM	[dbo].[ClaimDetails]
			WHERE	CompanyId = @CompanyId
			AND		RequestedBy = @LoginUserId;
			
			--Logic For RequestedClaim,RequestedClaimCount
			SELECT	@RequestedClaimCount	= COUNT(ClaimId)
					,@RequestedClaimAmount	= SUM(ClaimAmount)
			FROM	[dbo].[ClaimDetails] 
			WHERE	ClaimStatusId = 2
			AND		MONTH(ClaimDate) = MONTH(GETDATE()) 
			AND		CompanyId = @CompanyId
			AND		RequestedBy = @LoginUserId;

			--Logic For ApprovedClaim,ApprovedClaimCount
			SELECT	@ApprovedClaimCount	= COUNT(ClaimId)
					,@ApprovedClaimAmount	= SUM(ApprovedAmount)
			FROM	[dbo].[ClaimDetails]
			WHERE	ClaimStatusId = 3
			AND		MONTH(ClaimDate) = MONTH(GETDATE())
			AND		CompanyId = @CompanyId
			AND		RequestedBy = @LoginUserId;
			
			--Logic For @TotalClaim
			SELECT	@RejectedClaimCount = ISNULL(COUNT(ClaimId),0)
					,@RejectedClaimAmount = ISNULL(SUM(ClaimAmount),0)
			FROM	[dbo].[ClaimDetails]
			WHERE	ClaimStatusId = 4
			AND		MONTH(ClaimDate) = MONTH(GETDATE())
			AND		CompanyId = @CompanyId
			AND		RequestedBy = @LoginUserId;

			--Resultset for CounterBox
			SELECT	CONCAT(@OverAllClaimCount,' / ',N'₹ ',ISNULL(@OverAllClaimAmount,0))			AS 'Total'
					,CONCAT(@RequestedClaimCount,' / ',N'₹ ',ISNULL(@RequestedClaimAmount,0))		AS 'Requested'
					,CONCAT(@ApprovedClaimCount,' / ',N'₹ ',ISNULL(@ApprovedClaimAmount,0))		AS 'Approved'
					,CONCAT(@RejectedClaimCount,' / ',N'₹ ',ISNULL(@RejectedClaimAmount,0))		AS 'Rejected'
												
			IF @UserGroupId IN (1,2)
			BEGIN
				IF @Mine =	1
				BEGIN
					SELECT	CD.ClaimId
							,LEFT(CONVERT(NVARCHAR(50),CD.ClaimDate,113),11) AS ClaimDate
							,ClaimTypeName AS ClaimType
							,ClaimAmount
							,ISNULL(ApprovedAmount,0) AS ApprovedAmount
							,LeaveStatusName AS [Status]
							,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange' 
									WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
							ELSE 'Yellow'
							END AS [Status_Colour]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CLD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(CLD.FirstName ,' ',CLD.LastName) 
								ELSE ''
							END AS ApprovedBy
					FROM	[dbo].[ClaimDetails] CD
					JOIN	[dbo].[ClaimTypeDetails] CTD             
						ON	CTD.ClaimTypeId = CD.ClaimTypeId
					LEFT JOIN [dbo].[EmployeeDetails] ED             
						ON	ED.EmployeeId = CD.RequestedBy
					LEFT JOIN [dbo].[LeaveStatusDetails] LSD
							ON	CD.ClaimStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	ClaimId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[ClaimDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
									WHERE LD.CompanyId = @CompanyId
							) AS CLD
						ON	CLD.ClaimId = CD.ClaimId
					WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
					AND		ED.EmployeeId = @LoginUserId 
					AND		CD.CompanyId = @CompanyId
					ORDER BY CD.ClaimId DESC;
				END	
				ELSE
				BEGIN
				--Result set for SuperAdmin,Admin Grid.
					SELECT	CD.ClaimId
							,LEFT(CONVERT(NVARCHAR(50),CD.ClaimDate,113),11) AS ClaimDate
							,ISNULL(RPD.EmployeeImage,' ') AS RequestedPrsnImg
							,RPD.RequestedBy					
							,ClaimTypeName AS ClaimType
							,ClaimAmount
							,ISNULL(ApprovedAmount,0) AS ApprovedAmount
							,LeaveStatusName AS [Status]
							,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange' 
									WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
							ELSE 'Yellow'
							END AS [Status_Colour]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CLD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(CLD.FirstName ,' ',CLD.LastName) 
								ELSE ''
							END AS ApprovedBy
					FROM	[dbo].[ClaimDetails] CD
					JOIN	[dbo].[ClaimTypeDetails] CTD             
						ON	CTD.ClaimTypeId = CD.ClaimTypeId
					JOIN	(	SELECT	ED.DesignationId, ED.EmployeeId, ED.EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS RequestedBy 
							FROM	[dbo].[Employeedetails] ED
							LEFT JOIN	[dbo].[Employeedetails] RPD
								ON	RPD.EmployeeId = ED.EmployeeId 
							WHERE	ED.ReportingPersonId = @LoginUserId
						) AS RPD
					ON	CD.RequestedBy = RPD.EmployeeId
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	CD.ClaimStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	ClaimId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[ClaimDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
									WHERE LD.CompanyId = @CompanyId
							) AS CLD
						ON	CLD.ClaimId = CD.ClaimId
					WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
					AND		CD.CompanyId = @CompanyId
					ORDER BY CD.ClaimId DESC;
				END
				END
				ELSE
				BEGIN
					--Result set for GeneralUser Grid.
					SELECT	CD.ClaimId
							,LEFT(CONVERT(NVARCHAR(50),CD.ClaimDate,113),11) AS ClaimDate
							,ClaimTypeName AS ClaimType
							,ClaimAmount
							,ISNULL(ApprovedAmount,0) AS ApprovedAmount
							,LeaveStatusName AS [Status]
							,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange' 
									WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
							ELSE 'Yellow'
							END AS [Status_Colour]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CLD.EmployeeImage,'') 
								ELSE '' 
							END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(CLD.FirstName ,' ',CLD.LastName) 
								ELSE ''
							END AS ApprovedBy
					FROM	[dbo].[ClaimDetails] CD
					JOIN	[dbo].[ClaimTypeDetails] CTD             
						ON	CTD.ClaimTypeId = CD.ClaimTypeId
					LEFT JOIN [dbo].[EmployeeDetails] ED             
						ON	ED.EmployeeId = CD.RequestedBy
					LEFT JOIN [dbo].[LeaveStatusDetails] LSD
							ON	CD.ClaimStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	ClaimId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[ClaimDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
									WHERE LD.CompanyId = @CompanyId
							) AS CLD
						ON	CLD.ClaimId = CD.ClaimId
					WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
					AND		ED.EmployeeId = @LoginUserId 
					AND		CD.CompanyId = @CompanyId
					ORDER BY CD.ClaimId DESC;
		END
			END
			ELSE
			BEGIN
				--If the given @ClaimId is NOT NULL
				SELECT	ClaimId
						,RequestedBy 
						,CONCAT(ED.FirstName , ' ',ED.LastName) AS RequestedBy					
						,CONVERT(NVARCHAR(50),ClaimDate,105) AS ClaimDate
						,CTD.ClaimTypeId
						,ClaimTypeName AS ClaimType
						,ClaimAmount AS RequestedAmount
						,ClaimDescription
						,ClaimStatusId
						,LeaveStatusName AS ClaimStatus
						,ApprovedBy
						,CONCAT(ED1.FirstName , ' ',ED1.LastName) AS ApprovedBy
						,ApprovedAmount
						,ISNULL(ApproverComments,' ') AS ApproverComments	
						,CONVERT(NVARCHAR(50),CD.CreatedDate,105) AS CreatedDate
				FROM	[dbo].[ClaimDetails] CD
				JOIN	[dbo].[EmployeeDetails] ED             
					ON	ED.EmployeeId = CD.RequestedBy
				JOIN [dbo].[ClaimTypeDetails] CTD             
					ON	CTD.ClaimTypeId = CD.ClaimTypeId
				JOIN [dbo].[LeaveStatusDetails] LSD
					ON	CD.ClaimStatusId = LSD.LeaveStatusId
				LEFT JOIN	[dbo].[EmployeeDetails] ED1
					ON	ED1.EmployeeId = CD.ApprovedBy
				WHERE	ClaimId = @ClaimId 
				AND		CD.CompanyId = @CompanyId;

				--Retrive the Attachment details for the given AttachmentId.	
				SELECT  AD.AttachmentId
						,AD.ModuleRefId
						,AD.ModuleName
						,AttachmentFileName
						,AttachmentFilepath
				FROM	[dbo].[AttachmentDetails] AD
				WHERE	ModuleName = 'Claim' 
				AND		ModuleRefId = @ClaimId;		
		END
		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetClaimDetails]	@LoginUserId	 = 1
										,@ClaimId        = 3
										,@FromDate       = '2025-01-01'
										,@Mine			 = 0
									    ,@Status		 = @Status   OUT
									    ,@Message		 = @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[ClaimDetails];
	SELECT	*
	FROM	[dbo].[ClaimTypeDetails];

	SELECT	*
	FROM	[dbo].[AttachmentDetails];
	SELECT * FROM EmployeeDetails
========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetClientLocationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================  
 Procedure Name		:	[USP_GetClientLocationDetails]
 Description		:	Procedure used to retrive the ClientLocation (When click on ClientLocation in Setting Screen And
																	 When click on Edit Option in ClientLocationInfo on settings Screen)
 Input Parameter	:	@LoginUserId, @ClientLocationId
 Output Parameters	:	@Status, @Message
 Author				:	Tharanitharan.T
 Created on			:	14-12-2024
 Version			:	1.0 
 Comment			:	1. If the given @ClientLocationId is Null,then 
							1.1 Get All the ClientLocationDetails with the column of ClientLocationId, ClientName, Location,Country,
								ContactNumber, Emailto show in Grid.
							1.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						2. If the given @ClientLocationId is Not Null,then 
							2.1 Get the particular ClientLocationDetails column of ClientLocationId, ClientName, Address, City, State
								,Country, ZipCode, ContactNumber, Email, website for the given BranchId to show in popup.
							2.2.Then return the output Parameters values as @Status = 1 and @Message = NULL.
=================================================================================================================================*/
CREATE       PROCEDURE [dbo].[USP_GetClientLocationDetails]
(
	@LoginUserId			INT
	,@ClientLocationId		TINYINT
	,@status				BIT				OUT
	,@Message				NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given BranchId is Null, then get all the BranchDetails.
		IF (@ClientLocationId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	ClientLocationId
					,ClientName
					,CONCAT(City,' ',[State]) AS [Location]
					,CONCAT(Country,' - ',ZipCode) AS Country
					,ContactNumber AS ContactNo
					,Email
			FROM	[dbo].[ClientLocationDetails]
			WHERE	CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			--If the given BranchId is Not Null, then get the particular BranchDetails.
			SELECT	ClientLocationId
					,ClientName
					,[Address]
					,City
					,[State]
					,Country
					,ZipCode 
					,ContactNumber	
					,Email
					,MapNumber
			FROM	[dbo].[ClientLocationDetails]
			WHERE	ClientLocationId = @ClientLocationId
			AND		CompanyId = @CompanyId
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetClientLocationDetails]	@LoginUserId			= 1
												,@ClientLocationId		= null
												,@Status				= @S_Status  OUT
												,@Message				= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[ClientLocationDetails];

======================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetCompanyDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
