/*===============================================================================================================================================================  
 Procedure Name		:	[DBO].[USP_GetCompanyDetails]
 Description		:	Procedure used to retrive the companyDetails (When click on the Setting in Side NavigationBar
						And When click on Edit option in Setting screen)
 Input Parameter	:	@LoginUserId, @CompanyId
 Output Parameters	:	@Status, @Message
 Author				:	Nitya.M
 Created on			:	26-10-2023
 Version			:	1.0 
 Comment			:	1.Get the CompanyDetails with the columns of CompanyId, CompanyName, CompanyLogo,CompanyAddress,CompanyCity, CompanyState, CompanyCountry,
							CompanyZipCode, CompanyContactNumber,CompanyEmail,CompanyWebsite, GSTNumber, BankName, AccountType, AccountName, AccountNumber, 
							IFSCCode for the given CompanyId.
						2. Then return the output Parameters values as @Status = 1 and @Message = NULL.
==================================================================================================================================================================*/
CREATE PROCEDURE [dbo].[USP_GetCompanyDetails]
(	
	@LoginUserId	INT
	,@CompanyId		TINYINT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		SELECT	@Status    = 1 
				,@Message  = NULL;

		SELECT	CD.CompanyId			
				,CompanyName 
				,ISNULL(CompanyLogo,'') AS CompanyLogo
				,CompanyAddress 
				,CompanyCity 
				,CompanyState 
				,CompanyCountry 
				,CompanyZipcode 
				,CompanyContactNumber 
				,CompanyEmail 
				,CompanyWebsite 
				,GSTNumber 
		FROM	[DBO].[CompanyDetails] CD
		LEFT JOIN	[DBO].[CompanySettingDetails] CSD
			ON  CD.CompanyId = CSD.CompanyId
		WHERE	CD.CompanyId = @CompanyId;	

	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [DBO].[USP_GetCompanyDetails]	@LoginUserId  = 1
										,@CompanyId   = 1
										,@Status      = @S_Status	OUT
										,@Message     = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[CompanyDetails];
	SELECT	*
	FROM	[dbo].[CompanySettingDetails];
=============================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_GetCompanyOffDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==============================================================================================================================================================
 Procedure Name	    :   [USP_GetCompanyOffDetails]
 Description		:	Procedure used to retrive the EmployeeSalaryDetails(When click on Edit button in EmployeeSalaryInfo Section in Edit Employee Screen)
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.M
 Created on			:	23-08-2023
 Version			:	1.0
 Comment			:	1. Get the EmployeeSalaryDetails have the column of EmployeeId,PayTypeId,PayTypeName,PaymentTypeId ,PaymentTypeName,CTC,MonthlySalary
=====================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetCompanyOffDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId TINYINT
	 ,@Year INT = YEAR(GETDATE());
		
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		WITH NonWorkingDays AS (
		    SELECT [Day]
		    FROM [DBO].[CompanyWorkingDayDetails]
		    WHERE CompanyId = @CompanyId
		    AND IsWorkingDay = 0
		),
		AllDates AS (
		    SELECT CAST(DATEADD(DAY, Number, DATEFROMPARTS(@Year, 1, 1)) AS DATE) AS Date
		    FROM master..spt_values
		    WHERE Type = 'P' AND DATEADD(DAY, Number, DATEFROMPARTS(@Year, 1, 1)) <= DATEFROMPARTS(@Year, 12, 31)
		),
		FilteredDates AS (
		    SELECT ad.Date
		    FROM AllDates ad
		    JOIN NonWorkingDays nwd ON DATENAME(WEEKDAY, ad.Date) = nwd.Day
		),
		MergedDates AS (
		    SELECT Date
		    FROM FilteredDates
		    UNION
		    SELECT HolidayDate AS Date
		    FROM [DBO].[HolidayDetails]
		    WHERE CompanyId = @CompanyId
			AND IsOptional = 0
		)
		SELECT DISTINCT 
		CONVERT(NVARCHAR(10), Date, 120) AS [Date]
		FROM MergedDates
		ORDER BY [Date]; 
		

		SELECT	@Status		= 1 
				,@Message	= NULL;
		
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetCompanyOffDetails]		@LoginUserId	= 11
												,@EmployeeId	= 11
												,@Status		= @S_Status	 OUT
												,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT * 
	FROM	[dbo].[HolidayDetails];	
	
	SELECT * 
	FROM	[dbo].[CompanyDetails];

================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetCompensatoryOffDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=====================================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetCompensatoryOffDetails]
 Description		:	Procedure used to retrieve the CompensatoryOffdetails (1.When click on the CompensatoryOff in SideNavigationBar 
																			   2.When click on Edit option in Grid CompensatoryOff Screen).
 Input Parameter	:	@LoginUserId,@CompensatoryOffId,@FromDate,@ToDate
 Output Parameters	:	@Status,@Message
 Author				:	Dharani.M
 Created on			:	23-08-2023
 Version			:	1.0 
 Comments			:	1.If the given @CompensatoryOffId is NULL, 
						  1.1 When @UserGroupId Is an SuperAdmin(1)
							  1.1.1 Get the Counter Boxes have the Column of 
										@TotalCompensatoryOff		AS TotalCompensatoryOff
										,@TakenCompensatoryOff		AS TakenCompensatoryOff
										,@AvailableCompensatoryOff	AS AvailableCompensatoryOff
										,@PendingRequest			AS PendingRequest							  
							  1.1.2 Then,Get All the CompensatoryOffdetails with the column of CompensatoryOffId,EmployeeId,EmployeeImage,Employee,Designation,Date,NoOfDays,
							  	Comments,CompensatoryOffStatusId,Status,Status_Colour,ApprovedPersonImage,ApprovedBy  to show in Admin Grid.
							  1.1.3 Then return the output Parameters values as @Status=1 and @Message = NULL.
						  1.2 When @UserGroupId Is an GeneralUser(2,3),then
							  1.2.1 Get the Counter Boxes have the Column of 
										@TotalCompensatoryOff		AS TotalCompensatoryOff
										,@TakenCompensatoryOff		AS TakenCompensatoryOff
										,@AvailableCompensatoryOff	AS AvailableCompensatoryOff
										,@PendingRequest			AS PendingRequest			
							  1.2.2 Then,Get All the CompensatoryOffdetails with the column of CompensatoryOffId,Date,NoOfDays,Comments,CompensatoryOffstatusId,LeaveStatusName,
									Status_Colour,ApprovedPersonImage,ApprovedBy to show in Employee Grid.
							  1.2.3 Then return the output Parameters values as @Status=1 and @Message = NULL.
						3.If the given @CompensatoryOffId is NOT NULL,
						  3.1 Get the CompensatoryOffdetails have the column of CompensatoryOffId,EmployeeId,EmployeeName,CompensatoryOffDate,IsHalfDay,NoOfDays,AvailableCompensatoryOff
								,CompensatoryOffStatusId, LeaveStatusName,CompensatoryOffDescription for the given CompensatoryOffId to show in popup.
						  3.2 Then return the output Parameters values as @Status = 1 and Message = NULL.	
===========================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetCompensatoryOffDetails]
(
	@LoginUserId			INT
	,@CompensatoryOffId		INT
	,@FromDate				DATE
	,@Mine					BIT
	,@Status				BIT				OUT
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--Declaring the Varible for CounterBox.
	DECLARE	@CompanyId					TINYINT
			,@UserGroupId				TINYINT
			,@EmployeeId				INT
			,@TotalCompensatoryOff		INT
			,@TakenCompensatoryOff		INT
			,@RequestCompensatoryOff	INT
			,@ApprovedRequest			INT
			,@CompensatoryOffLeave		INT
			,@ToDate					DATE;

	--SET @ToDate = DATEADD(MONTH, 3, @FromDate);
	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--If the given @CompensatoryOffId is NULL
		IF @CompensatoryOffId IS NULL
		BEGIN
			--Logic for TotalCompensatoryOff
			SELECT	@TotalCompensatoryOff = COUNT(EmployeeId)
			FROM	[dbo].[CompensatoryOffDetails]
			WHERE	EmployeeId = @LoginUserId 
			AND		CompanyId = @CompanyId;

			--Logic for AvailableCompensatoryOff
			SELECT	@RequestCompensatoryOff = COUNT(EmployeeId)
			FROM	[dbo].[CompensatoryOffDetails]
			WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate 
			AND		CompensatoryOffStatusId = 2
			AND		EmployeeId = @LoginUserId 
			AND		CompanyId = @CompanyId;

			--Logic for @PendingRequest
			SELECT	@ApprovedRequest = COUNT(CompensatoryOffId)
			FROM	[dbo].[CompensatoryOffDetails]
			WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate 
			AND		CompensatoryOffStatusId = 3
			AND		EmployeeId = @LoginUserId 
			AND		CompanyId = @CompanyId;

			--Logic for TakenCompensatoryOff
			SELECT	@TakenCompensatoryOff = COUNT(LeaveId)
			FROM	[dbo].[LeaveDetails]
			WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate 
			AND		EmployeeId = @LoginUserId 
			AND		CompanyId = @CompanyId
			AND		LeaveTypeId = 2	
			AND		LeaveStatusId = 3;

			--ResultSet for EmployeeCounterbox
			SELECT @TotalCompensatoryOff		AS	'Total'		
					,@RequestCompensatoryOff	AS	'Request'
					,@ApprovedRequest			AS	'Approved'		
					,@TakenCompensatoryOff		AS	'Taken';			

			IF @UserGroupId IN (1,2)
			BEGIN
				IF @Mine = 1
				BEGIN
					SELECT	CD.CompensatoryOffId
							,CONVERT(NVARCHAR(50),CD.CompensatoryOffDate,113) AS [Date]
							,CONCAT(NoOfDays,' Day') AS NoOfDays
							,ISNULL(Comments,' ') AS Comments
							,CompensatoryOffStatusId AS StatusId
							,LeaveStatusName AS [Status]
							,CASE WHEN LSD.LeaveStatusId IN (3,4,5,6,7) THEN ISNULL(CVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN (3,4,5,6,7) THEN ISNULL(CONCAT(CVD.FirstName,' ',CVD.LastName),'') 
								ELSE ''
							END AS ApprovedBy 
							,CASE	WHEN LSD.LeaveStatusName = 'Draft' THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Submitted' THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved' THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Cancelled' THEN 'Black'
									WHEN LSD.LeaveStatusName = 'Rejected' THEN 'Red'
							ELSE 'Black'
							END AS [Status_Colour]
					FROM	[dbo].[CompensatoryOffDetails] CD
					JOIN	[dbo].[EmployeeDetails] AS ED
		   				ON  CD.EmployeeId = ED.EmployeeId
					JOIN	[dbo].[LeavestatusDetails] AS LSD
						ON  CD.CompensatoryOffStatusId = LSD.LeaveStatusId  
					LEFT JOIN	[dbo].[DesignationDetails] DD
						ON	ED.DesignationId = DD.DesignationId
					LEFT JOIN (	SELECT	CompensatoryOffId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[CompensatoryOffDetails] CD
								JOIN	[dbo].[Employeedetails] ED
									ON	CD.UpdatedBy = ED.EmployeeId 
									WHERE CD.CompanyId = @CompanyId
							) AS CVD
						ON	CVD.CompensatoryOffId = CD.CompensatoryOffId
					WHERE	@FromDate <= @ToDate 
					AND		ED.EmployeeId = @LoginUserId 
					AND		CD.CompanyId  = @CompanyId
					ORDER BY CD.CompensatoryOffId DESC;
				END
				ELSE
				BEGIN
					--ResultSet for AdminGrid
					SELECT	CD.CompensatoryOffId
							,RPD.EmployeeId
							,RPD.EmployeeImage AS EmpImage
							,Employee
							,DD.DesignationName AS Designation
							,CONVERT(NVARCHAR(50),CD.CompensatoryOffDate,113) AS [Date]
							,CONCAT(NoOfDays,' Day') AS NoOfDays
							,ISNULL(Comments,' ') AS Comments
							,CompensatoryOffStatusId  AS StatusId
							,LeaveStatusName AS [Status]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN (3,4,5,6,7) THEN ISNULL(CONCAT(CVD.FirstName,' ',CVD.LastName),'') 
								ELSE ''
							END AS ApprovedBy 
							,CASE	WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
							 ELSE 'Orange'
							 END AS [Status_Colour]
					FROM	[dbo].[CompensatoryOffDetails] CD
					JOIN	(	SELECT	ED.DesignationId, ED.EmployeeId, ED.EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee 
								FROM	[dbo].[Employeedetails] ED
								LEFT JOIN	[dbo].[Employeedetails] RPD
									ON	RPD.EmployeeId = ED.EmployeeId 
								WHERE	ED.ReportingPersonId = @LoginUserId
							) AS RPD
						ON	CD.EmployeeId = RPD.EmployeeId
					JOIN	[dbo].[LeavestatusDetails] AS LSD
						ON  CD.CompensatoryOffStatusId = LSD.LeaveStatusId  
					LEFT JOIN	[dbo].[DesignationDetails] DD
						ON	RPD.DesignationId = DD.DesignationId
					LEFT JOIN (	SELECT	CompensatoryOffId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[CompensatoryOffDetails] CD
								JOIN	[dbo].[Employeedetails] ED
									ON	CD.UpdatedBy = ED.EmployeeId 
									WHERE CD.CompanyId = @CompanyId
							) AS CVD
						ON	CVD.CompensatoryOffId = CD.CompensatoryOffId
					WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
					AND		CD.CompanyId  = @CompanyId
					AND		CD.CompensatoryOffStatusId NOT IN (1, 5)
					ORDER BY CD.CompensatoryOffId DESC;
				END
			END
			ELSE
			BEGIN
				--ResultSet for EmployeeGrid
				SELECT	CD.CompensatoryOffId
						,CONVERT(NVARCHAR(50),CD.CompensatoryOffDate,113) AS [Date]
						,CONCAT(NoOfDays,' Day') AS NoOfDays
						,ISNULL(Comments,' ') AS Comments
						,CompensatoryOffStatusId  AS StatusId
						,LeaveStatusName AS [Status]
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
						,CASE WHEN LSD.LeaveStatusId IN (3,4,5,6,7) THEN ISNULL(CONCAT(CVD.FirstName,' ',CVD.LastName),'') 
								ELSE ''
							END AS ApprovedBy 
						,CASE	WHEN LSD.LeaveStatusName = 'Draft' THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Submitted' THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Approved' THEN 'Green'
								WHEN LSD.LeaveStatusName = 'Cancelled' THEN 'Red'
								WHEN LSD.LeaveStatusName = 'Rejected' THEN 'Red'
						ELSE ' '
						END AS [Status_Colour]
				FROM	[dbo].[CompensatoryOffDetails] CD
				JOIN	[dbo].[EmployeeDetails] AS ED
		   			ON  CD.EmployeeId = ED.EmployeeId
				JOIN	[dbo].[LeavestatusDetails] AS LSD
					ON  CD.CompensatoryOffStatusId = LSD.LeaveStatusId  
				LEFT JOIN	[dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId
				LEFT JOIN (	SELECT	CompensatoryOffId, EmployeeImage, FirstName, LastName
							FROM	[dbo].[CompensatoryOffDetails] CD
							JOIN	[dbo].[Employeedetails] ED
								ON	CD.UpdatedBy = ED.EmployeeId 
								WHERE CD.CompanyId = @CompanyId
						) AS CVD
					ON	CVD.CompensatoryOffId = CD.CompensatoryOffId
				WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
				AND		ED.EmployeeId = @LoginUserId 
				AND		CD.CompanyId  = @CompanyId
				ORDER BY CD.CompensatoryOffId DESC;
			END
		END
		ELSE
		BEGIN
			--If the @CompensatoryOffId is NOT NULL
			SELECT	CompensatoryOffId 
					,ED.EmployeeId
					,CONCAT(ED.FirstName, ' ',ED.LastName)AS EmployeeName
					,CONVERT(NVARCHAR(50),CD.CompensatoryOffDate,105) AS CompensatoryOffDate
					,IsHalfDay
					,NoOfDays
					,'12' AS AvailableCompensatoryOff
					,CompensatoryOffstatusId
					,LeaveStatusName AS CompensatoryOffstatusName
					,CompensatoryOffDescription AS CompensatoryOffDescription
					,Comments AS Comments
					,CONVERT(NVARCHAR(50),CD.CreatedDate,105) AS CreatedDate
			FROM	[dbo].[CompensatoryOffDetails] CD
			JOIN	[dbo].[EmployeeDetails] AS ED
		   		ON  CD.EmployeeId = ED.EmployeeId
			JOIN	[dbo].[LeavestatusDetails] AS LSD
				ON  CD.CompensatoryOffStatusId = LSD.LeaveStatusId  
			LEFT JOIN	[dbo].[DesignationDetails] DD
				ON	ED.DesignationId = DD.DesignationId
			LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
		   		ON  RPD.EmployeeId = ED.ReportingPersonId
			JOIN	[dbo].[CompanySettingDetails] CSD
				ON	CD.CompanyId = CSD.CompanyId
			WHERE  CD.CompensatoryOffId = @CompensatoryOffId
			AND		CD.CompanyId = @CompanyId;
		END
		SELECT  @Status   = 1 
				,@Message  = NULL;		
	END TRY
	BEGIN CATCH
		SELECT  @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================
	DECLARE	 @Status	BIT 
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetCompensatoryOffDetails]  @LoginUserId		= 1
												,@CompensatoryOffId	= 16
												,@FromDate			= '2024-08-02'
												,@Mine				= 1	
												,@Status			= @Status   OUT
												,@Message			= @Message  OUT;
	SELECT @Status AS STATUS, @Message AS MESSAGE; 
	 
	SELECT	*
	FROM	[dbo].[CompensatoryOffDetails];
======================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetDashBoardDetails_Admin]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================================           
 Procedure Name 	:   [USP_GetDashBoardDetails_Admin]
 Description		:	Procedure used to retrive the DashBoardDetails(When Click on Side Navigation Bar DashBoard(Admin))
 Input Parameter	:	@LoginUserId,@FromDate,@ToDate
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	05-09-2023
 Version			:	1.0 
 Comment			:   1.Declare the Variable @CompanyId,@StartDate,@EndDate,@TotalEmployees,@Male,@Female,@Attendance,@PresentEmployee	
							,@AbsentEmployee,@AdvanceAmount,@AdvanceCount,@LoanAmount,@LoanCount,@Leave,@Permission,@CompensantoryOff	
							,@GrossSalary,@PF,@Completed,@InProgress.		
                           1.1 Displaying the counter values on EmployeeDetails have the columns of TotalEmployees,TotalMale,TotalFemale.
						   1.3 Displaying the counter values on AttendanceLogDetails have the columns of TotalPresent and TotalAbsent.
						   1.4 Displaying the counter values on AdvanceDetails have the columns of TotalAdavnce Amount and Count Of Members.
						   1.5 Displaying the counter values on LoanDetails have the columns of TotalLoan Amount and Count Of Members.
						   1.6 Displaying the counter values on PayslipDetails have the columns of GrossSalary/PFmount.
					    2.Logic For PayRoll Result
							2.1 To show the TotalEmployee's completed Payroll Process.
							2.2 To show the TotalEmployee's In-Progress Payroll Process.
					    3.Logic For Department wise Average Gross salary for the TotalEmployees.
					    4.Logic For Gross salary Vs Net Salary
					    5.Logic For Last One Week Attendance 
					    6.Logic for the Day wise AdvanceStatus.
					    7.Logic for the Day wise LoanStatus.
					    8.Logic for the Leave
							8.1 TotalLeave
							8.2 TotalPermission
							8.3 TotalCompensatoryOff
					    9.Logic For Upcoming Holiday
					    10.Displaying the Employee's BirthDay.
						11.Then return the output Parameters values as @Status = 1 and @Message = NULL.
====================================================================================================================================================*/		   
CREATE   PROCEDURE [dbo].[USP_GetDashBoardDetails_Admin]
(
	@LoginUserId    INT
	,@FromDate      DATE
	,@Status        BIT            OUT
	,@Message       NVARCHAR(500)  OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@ToDate	DATE;
	SET @ToDate = EOMONTH(@FromDate);

	DECLARE	@CompanyId						TINYINT
			,@StartDate						DATE			= @FromDate
			,@EndDate						DATE			= @ToDate
			,@TotalEmployees				INT
			,@Male							INT
			,@Female						INT
			,@Attendance					INT
			,@PresentEmployee				INT	
			,@AbsentEmployee				INT
			,@AdvanceAmount					NUMERIC(11,2)
			,@AdvanceCount					NUMERIC(11,2)
			,@LoanAmount					NUMERIC(11,2)
			,@LoanCount						NUMERIC(11,2)
			,@Leave							INT
			,@Permission					INT
			,@CompensantoryOff				INT
			,@GrossSalary					INT
			,@PF							INT
			,@Completed						INT
			,@InProgress					INT
			,@Month							NVARCHAR(50)
			,@TotalEarning					NUMERIC(11,2)
			,@NetPay						NUMERIC(11,2)
			
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	
		--Created TempTable to take Last 7 Days record In AttendanceLogDetails.
		DROP TABLE IF EXISTS #Attendance;
		CREATE TABLE #Attendance 
		(
			Id              INT  IDENTITY(1,1),
			PunchDate		DATE
		);

		WHILE @StartDate <= @EndDate
		BEGIN
			INSERT INTO #Attendance (PunchDate) 
			VALUES (@StartDate);
			SET @StartDate = DATEADD(DAY,1, @StartDate);
		END;

		BEGIN TRY			 
			IF	(@FromDate IS NULL AND @Todate IS NULL)
			BEGIN
				SET @FromDate = CONVERT(DATE,GETDATE())
				SET @Todate   = CONVERT(DATE,GETDATE())
			END
		
			SELECT	@Status		=  1 
					,@Message	= NULL;

		--Displaying the counter values on EmployeeDetails have the columns of TotalEmployees.
		SELECT	@TotalEmployees = COUNT(EmployeeId)
		FROM	[DBO].[EmployeeDetails]
		WHERE   CompanyId = @CompanyId;

		--Displaying the counter values on EmployeeDetails have the columns of TotalMale.
		SELECT	@Male = COUNT(EPD.GenderId)
		FROM	[DBO].[EmployeePersonalDetails] EPD
		JOIN	[DBO].[GenderDetails] GD
			ON	EPD.GenderId = GD.GenderId
		WHERE   GenderName = 'Male'
		AND		CompanyId = @CompanyId;

		--Displaying the counter values on EmployeeDetails have the columns of TotalFeMale.
		SELECT	@Female = COUNT(EPD.GenderId)
		FROM	[DBO].[EmployeePersonalDetails] EPD
		JOIN	[DBO].[GenderDetails] GD
			ON	EPD.GenderId = GD.GenderId
		WHERE   GenderName = 'Female'
		AND		CompanyId = @CompanyId

		--Displaying the counter values on AttendanceLogDetails have the columns of TotalPresent and TotalAbsent.
		SELECT	@PresentEmployee = COUNT(DISTINCT EmployeeId)
		FROM	[dbo].[AttendanceLogDetails]
		WHERE   CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) 
		AND		IsActive = 1 
		AND		CompanyId = @CompanyId;

		SELECT @AbsentEmployee = ISNULL(@TotalEmployees,0) - ISNULL(@PresentEmployee,0);

		--Displaying the counter values on AdvanceDetails have the columns of TotalAdavnce Amount.
		SELECT	@AdvanceAmount = ISNULL(SUM(AdvanceAmount),0)
		FROM	[dbo].[AdvanceDetails] AD
		JOIN	[dbo].[LeaveStatusDetails] LSD
			ON	AD.AdvanceStatusId = LSD.LeaveStatusId
		WHERE	AD.AdvanceStatusId IN (3,5) 
		AND		CONVERT(DATE,AdvanceDate) = CONVERT(DATE,GETDATE()) 
		AND		AD.CompanyId = @CompanyId;

		--Displaying the counter values on AdvanceDetails have the columns of Count Of Members.
		SELECT	@AdvanceCount =COUNT(DISTINCT EmployeeId)
		FROM	[dbo].[AdvanceDetails] AD
		WHERE	AD.AdvanceStatusId IN (3,5)
		AND		CONVERT(DATE,AdvanceDate) = CONVERT(DATE,GETDATE()) 
		AND		AD.CompanyId = @CompanyId;

		--Displaying the counter values on LoanDetails have the columns of TotalLoan Amount.
		SELECT	@LoanAmount = ISNULL(SUM(LoanAmount),0)
		FROM	[dbo].[LoanDetails] LD
		JOIN	[dbo].[LeaveStatusDetails] LSD
			ON	LD.LoanStatusId = LSD.LeaveStatusId
		WHERE	LD.LoanStatusId IN (3,5) 
		AND		CONVERT(DATE,LoanDate) = CONVERT(DATE,GETDATE()) 
		AND		LD.CompanyId = @CompanyId;

		--Displaying the counter values on LoanDetails have the columns of Count Of Members.
		SELECT	@LoanCount = COUNT(DISTINCT EmployeeId)
		FROM	[dbo].[LoanDetails] LD
		WHERE	LD.LoanStatusId IN (3,5) 
		AND		CONVERT(DATE,LoanDate) = CONVERT(DATE,GETDATE()) 
		AND		LD.CompanyId = @CompanyId;

		--Displaying the counter values on PayslipDetails have the columns of GrossSalary
		SELECT  @GrossSalary = SUM(TotalEarnings)
		FROM	[DBO].[PaySlipDetails]
		WHERE	CompanyId = @CompanyId;

		--Displaying the counter values on PayslipDetails have the columns of PF
		SELECT  @PF = SUM(PF)
		FROM	[DBO].[PaySlipDetails]
		WHERE	CompanyId = @CompanyId;

		--ResultSet Counter Box
		SELECT	CONCAT(@TotalEmployees,' / ',@Male ,' / ', @Female)		AS 'Total Employees'			
				,CONCAT(@PresentEmployee,' / ',@AbsentEmployee)			AS Attendance
				,CONCAT(@AdvanceCount,' / ',@AdvanceAmount)				AS Advance	
				,CONCAT(@LoanCount,' / ',@LoanAmount)					AS Loan
				,CONCAT(@GrossSalary,' / ',@PF) 						AS 'GrossSalary-PFAmount'
			
		--To show the TotalEmployee's completed Payroll Process.
		SELECT	@TotalEmployees = COUNT(EmployeeId)
		FROM	[DBO].[EmployeeDetails]
		WHERE   CompanyId = @CompanyId;

		SELECT	@Completed = COUNT(DISTINCT EmployeeId)
		FROM	[dbo].[PaySlipDetails]
		WHERE   CompanyId = @CompanyId;

		--To show the TotalEmployee's In-Progress Payroll Process.
		SELECT @InProgress = ISNULL(@TotalEmployees,0) - ISNULL(@Completed,0);

		--ResultSet For PayrollResult
		--SELECT	@TotalEmployees	AS	TotalEmployees
		--		,@Completed		AS	Completed
		--		,@InProgress	AS  InProgress;

		SELECT	'Jan'	AS [Month]
				,'100'	AS Completed
				,'0'	AS InProgress	
		UNION ALL
		SELECT	'Feb'	AS [Month]
				,'50'	AS Completed
				,'40'	AS InProgress	
		UNION ALL
		SELECT	'Mar'	AS [Month]
				,'100'	AS Completed
				,'0'	AS InProgress
		UNION ALL
		SELECT	'Apr'	AS [Month]
				,'100'	AS Completed
				,'0'	AS InProgress
		UNION ALL
		SELECT	'May'	AS [Month]
				,'90'	AS Completed
				,'90'	AS InProgress
		UNION ALL
		SELECT	'Oct'	AS [Month]
				,'0'	AS Completed
				,'100'	AS InProgress


		--Average GrossSalary         
		SELECT	DesignationName
				, AVG(MonthlySalary) AS AvgGrossSalary
				,CONCAT(CONVERT(NVARCHAR(50),@FromDate,105),' - ',CONVERT(NVARCHAR(50),@ToDate,105)) AS SalaryDate 
		FROM	[dbo].[EmployeeSalaryDetails] ESD
		JOIN	[dbo].[EmployeeDetails] ED
			ON	ESD.EmployeeId =ED.EmployeeId
		LEFT JOIN	[dbo].[DesignationDetails] DD
			ON	ED.DesignationId = DD.DesignationId	
		WHERE	ED.CompanyId = @CompanyId
		GROUP BY  DesignationName

		--MonthWise Employees TotalAmount of GrossSalary And NetPay
		SELECT	@Month			= DATENAME(M,([Month])) 
				,@TotalEarning	= ISNULL(TotalEarnings,0)
				,@NetPay		= ISNULL(NetPay,0)
		FROM	[dbo].[PaySlipDetails]
		WHERE	CompanyId = @CompanyId
		ORDER BY [Month];

		--SELECT	@Month			AS [Month]		
		--		,@TotalEarning	AS GrossPay	 
		--		,@NetPay		AS NetPay;

		SELECT	'Jan'    AS [Month]		
				,'10000' AS GrossPay	 
				,'20000' AS NetPay
				UNION ALL 
		SELECT  'FEB'    AS [Month]		
				,'50000' AS GrossPay	 
				,'40000' AS NetPay
				UNION ALL 
		SELECT  'Mar'    AS [Month]		
				,'40000' AS GrossPay	 
				,'30000' AS NetPay
				UNION ALL 
		SELECT  'Apr'    AS [Month]		
				,'70000' AS GrossPay	 
				,'50000' AS NetPay
				UNION ALL 
		SELECT  'May'    AS [Month]		
				,'75000' AS GrossPay	 
				,'70000' AS NetPay

		--Displaying the Last one Week AttendanceLogDetails Have the Columns of Date,Day,Status.
		--SELECT	CONVERT(NVARCHAR(50),TA.PunchDate,105) AS [Date]  
		--		,LEFT(DATENAME(DW,TA.PunchDate),3) AS [Day]
		--		,CASE WHEN IQ.PunchDate IS NULL THEN 'Absent'
		--			ELSE 'Present' END [Status]
		--FROM	#Attendance AS TA
		--CROSS JOIN (	SELECT	ED.EmployeeId
		--						,ED.FirstName
		--						,ED.LastName 
		--				FROM	[dbo].[EmployeeDetails] AS ED
		--				WHERE	CompanyId = @CompanyId
		--			) E
		--LEFT JOIN   (SELECT	DISTINCT	T1.EmployeeId
		--								,PunchDate
		--								,(	SELECT  MIN(PunchTime) 
		--									FROM	[AttendanceLogDetails] IQ1
		--									WHERE	IQ1.EmployeeID = T1.EmployeeId 
		--									AND		IQ1.PunchDate =  T1.PunchDate
		--									AND		IQ1.[Status] = 1 
		--									AND		CompanyId = @CompanyId
		--									) AS PunchIn
		--								,(	SELECT	MAX(PunchTime)
		--									FROM	[AttendanceLogDetails] IQ2
		--									WHERE	IQ2.EmployeeID = T1.EmployeeId 
		--	   								AND		IQ2.PunchDate = T1.PunchDate
		--									AND		IQ2.[Status] = 0 
		--									AND		CompanyId = @CompanyId
		--									) AS PunchOut
		--			FROM	[dbo].[AttendanceLogDetails] AS T1
		--			) IQ
		--	ON	TA.PunchDate = IQ.PunchDate
		--	WHERE	CONVERT(DATE, IQ.PunchDate) BETWEEN DATEADD(DAY, -7, GETDATE()) AND GETDATE()
		--	AND		E.EmployeeId = IQ.EmployeeId
		--	ORDER BY TA.PunchDate;
		SELECT		'Mon'  AS PunchDay
					,'10'  AS PresentCount
					,'2'   AS AbsentCount
		UNION ALL 
		SELECT		'Tue'  AS PunchDay
					,'12'  AS PresentCount
					,'0'   AS AbsentCount
		UNION ALL 
		SELECT		'Wed'  AS PunchDay
					,'11'  AS PresentCount
					,'1'   AS AbsentCount
		UNION ALL 
		SELECT		'Thu'  AS PunchDay
					,'9'  AS PresentCount
					,'3'   AS AbsentCount
		UNION ALL 
		SELECT		'Fri'  AS PunchDay
					,'10'  AS PresentCount
					,'2'   AS AbsentCount
		UNION ALL 
		SELECT		'Sat'  AS PunchDay
					,'0'  AS PresentCount
					,'0'   AS AbsentCount
		UNION ALL 
		SELECT		'Sun'  AS PunchDay
					,'0'  AS PresentCount
					,'0'   AS AbsentCount

					
		--5.Logic for the Day wise AdvanceStatus.
		SELECT	COUNT(AdvanceId) AS AdvanceCount
				,LeaveStatusName AS  AdvanceStatusName
				,DATENAME(dw,AdvanceDate) AS [Day]
		FROM	[dbo].[AdvanceDetails]  AD
		JOIN	[dbo].[LeaveStatusDetails] LSD
			ON	AD.AdvanceStatusId = LSD.LeaveStatusId
		WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate
		AND		AD.CompanyId = @CompanyId
		GROUP BY  LeaveStatusName,DATENAME(dw,AdvanceDate)
          
		--6.Logic for the Day wise LoanStatus.
		SELECT	COUNT(LoanId) AS [LoanCount]
				,LeaveStatusName AS LoanStatusName
				,DATENAME(dw,LoanDate) AS [Day]
		FROM	[dbo].[LoanDetails]  LD
		JOIN	[dbo].[LeaveStatusDetails] LSD
			ON	LD.LoanStatusId = LSD.LeaveStatusId
		WHERE	CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate
		AND		LD.CompanyId = @CompanyId
		GROUP BY  LeaveStatusName,DATENAME(dw,LoanDate)

		--7.Leave
	--	SELECT	CONVERT(NVARCHAR(50),FromDate,105) AS [Date]
	--			,'Leave' AS [Name]
	--			,COUNT(ISNULL(EmployeeId,0)) AS [Count]
	--	FROM	[dbo].[LeaveDetails] LD 
	--	LEFT JOIN	[dbo].[LeavestatusDetails] LSD 
	--		ON	LD.LeaveStatusId = LSD.LeaveStatusId
	--	WHERE	LeaveStatusName = 'Approved'
	--	AND		CONVERT(DATE,FromDate) = CONVERT(DATE,GETDATE()) 
	--	AND		LD.CompanyId = @CompanyId
	--	GROUP BY FromDate
	--UNION ALL
	--	SELECT	CONVERT(NVARCHAR(50),PermissionDate,105) AS [Date]
	--			,'Permission' AS [Name]
	--			,COUNT(ISNULL(EmployeeId,0)) AS [Count] 
	--	FROM	[dbo].[PermissionDetails] PD
	--	LEFT JOIN	[dbo].[LeavestatusDetails] LSD 
	--		ON	PD.PermissionStatusId = LSD.LeaveStatusId
	--	WHERE	LeaveStatusName = 'Approved'
	--	AND		CONVERT(DATE,PermissionDate) = CONVERT(DATE,GETDATE()) 
	--	AND		PD.CompanyId = @CompanyId
	--	GROUP BY PermissionDate
	--UNION ALL
	--	SELECT	CONVERT(NVARCHAR(50),CompensatoryOffDate,105) AS [Date]	
	--			,'CompensatoryOff' AS [Name]
	--			,COUNT(ISNULL(EmployeeId,0)) AS [Count] 
	--	FROM	[dbo].[CompensatoryoffDetails] CD
	--	LEFT JOIN	[dbo].[LeavestatusDetails] LSD 
	--		ON	CD.CompensatoryoffStatusId = LSD.LeaveStatusId
	--	WHERE	LeaveStatusName = 'Approved'
	--	AND		CONVERT(DATE,CompensatoryoffDate) = CONVERT(DATE,GETDATE()) 
	--	AND		CD.CompanyId = @CompanyId
	--	GROUP BY CompensatoryOffDate;
		Select		'18 Oct'AS [Date]
					,'12'	AS Leave
					,'3'	AS Permission
		UNION ALL
		Select		'19 Oct'AS [Date]
					,'1'	AS Leave
					,'0'	AS Permission
		UNION ALL
		Select		'20 Oct'AS [Date]
					,'4'	AS Leave
					,'1'	AS Permission
		UNION ALL
		Select		'21 Oct'AS [Date]
					,'3'	AS Leave
					,'0'	AS Permission
					
		--8.UpComingHolidays
		SELECT	HolidayId
				, CONCAT(DATENAME(MONTH,HolidayDate), ' ', DAY(HolidayDate)) AS [Day]
				,HolidayName   
		FROM	[dbo].[HolidayDetails]
		WHERE	CONVERT(DATE,HolidayDate) > CONVERT(DATE,GETDATE())
		AND		CompanyId = @CompanyId;

		--9.Displaying the Employee's BirthDay.
		--SELECT	ED.EmployeeId
		--		,CONVERT(NVARCHAR(50),DateOfBirth,105) AS DateOfBirth
		--		,EmployeeImage	
		--		,CONCAT(FirstName,' ',LastName) AS EmployeeName
		--		,DD.DesignationName AS Designation
		--FROM	[dbo].[EmployeeDetails] ED
		--LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD
		--ON			ED.EmployeeId = EPD.EmployeeId
		--LEFT JOIN	[dbo].[DesignationDetails] DD
		--ON			ED.DesignationId = DD.DesignationId
		--WHERE	RIGHT(CONVERT(DATE,DateOfBirth),5) = RIGHT(CONVERT(DATE,GETDATE()),5)
		--AND		ED.CompanyId = @CompanyId;

		SELECT		ED.EmployeeImage	
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
					,CONVERT(NVARCHAR(50),EPD.DateOfBirth,105) AS DateOfBirth
					,DD.DesignationName AS Designation
		FROM		[dbo].[EmployeeDetails] ED
		LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD
			 ON		ED.EmployeeId = EPD.EmployeeId
		LEFT JOIN	[dbo].[DesignationDetails] DD
			ON		ED.DesignationId = DD.DesignationId
		WHERE		MONTH(EPD.DateOfBirth) >= MONTH(GETDATE()) 
					AND MONTH(EPD.DateOfBirth) < MONTH(GETDATE()) + 3
					OR (MONTH(GETDATE()) + 3 > 12 AND MONTH(EPD.DateOfBirth) <= (MONTH(GETDATE()) + 3) % 12)
		ORDER BY	CASE  WHEN MONTH(EPD.DateOfBirth) >= MONTH(GETDATE()) 
					THEN MONTH(EPD.DateOfBirth) 
					ELSE MONTH(EPD.DateOfBirth) + 12 
					END, 
					DAY(EPD.DateOfBirth);

		--11.Displaying the Employee's Anniversarys
		SELECT	ED.EmployeeId
				,CONVERT(NVARCHAR(50),CONCAT(DATENAME(MONTH,DateOfJoining),' ',DAY(DateOfJoining))) AS [Day]
				,EmployeeImage	
				,CONCAT(FirstName,' ',LastName)AS EmployeeName
				,DD.DesignationName AS Designation
		FROM	[dbo].[EmployeeDetails] ED
		LEFT JOIN	[dbo].[DesignationDetails] DD
			ON	ED.DesignationId = DD.DesignationId
		WHERE	RIGHT(CONVERT(DATE,DateOfJoining),5) = RIGHT(CONVERT(DATE,GETDATE()),5)
		AND		ED.CompanyId = @CompanyId;
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0				
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
