/*========================================================================================================================= 
 Procedure Name		:	[USP_GetDashboardDetails_Employee](When Click on DashBoard(Employee) in Side NavigationBar).
 Description		:	Procedure used to retrieve the Dashboard Details
 Input Parameter	:	@LoginUserId,@FromDate,@Todate
 Output Parameters	:	@Status,@Message
 Author				:	Tetrosoft
 Created on			:	05-09-2023
 Version			:	1.0 
 Comment			:	1.Displaying the BreakTime and OverTime Using AttendanceLogDetails Table.
						2.Displaying the Last one Week AttendanceLogDetails Have the Columns of Date,Day,NoOfHours,Status.
						3.Displaying the MonthWise Payroll Details in Percentage.
						4.Displaying the LeaveTypeName,AvailableLeave,TakenLeave for Annual,Casual,SickLeaves.
						5.Displaying the PermissionDetails TakenPermission,RemainingPermissions.
						6.Displaying the CompensatoryOffDetails TakenCompensatoryOff,RemainingCompensatoryOff.
						7.Displaying the Approved and Completed Loan Details.
						8.Displaying the AdvanceDetails Have the Column of Date,AdvanceAmount,AdvanceStatus.
						9.Displaying the UpComing Holidays.
						10.Displaying the Employee's Birthday forr the Given EmployeeId and FromDate and ToDate.
						11.Then return the output Parameters values as @Status=1 and @Message = NULL.
============================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetDashboardDetails_Employee]
(
	@LoginUserId	INT
	,@FromDate		DATE = NULL
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE	@ToDate	DATE;
	SET @ToDate = EOMONTH(@FromDate);

	DECLARE	@CompanyId						TINYINT
			,@StartDate						DATETIME = @FromDate   --GETDATE()-6
			,@EndDate						DATETIME = @Todate	   --GETDATE()
			,@EmployeeId					INT
			,@PunchDateNew					DATETIME
			,@TakenPermission				INT
			,@RemaingingPermission			INT
			,@TotalPermission				INT
			,@TakenCompensatoryOff			INT		
			,@RemaingingCompensatoryOff		INT		
			,@TotalCompensatoryOff			INT;		
			
	SELECT	@CompanyId = CompanyId 
			,@EmployeeId = EmployeeId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	--Created TempTable to take Last 7 Days record In AttendanceLogDetails.
	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id             INT  IDENTITY(1,1),
		PunchDate		DATE,
		CompanyId		TINYINT
	)

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate) 
		VALUES (@StartDate);
		SET @StartDate = DATEADD(DAY,1, @StartDate);
	END;

	BEGIN TRY			 
		IF	(@FromDate IS NULL AND @Todate IS NULL)
		BEGIN
			SET @FromDate = CONVERT(DATE,GETDATE())
			SET @Todate   = CONVERT(DATE,GETDATE())
		END

		--DROP TABLE IF EXISTS #DetailedDailyData; 
		--SELECT	*
		--INTO	#DetailedDailyData
		--FROM	(
		--			SELECT	ED.EmployeeId 
		--					,PunchDate
		--					,PunchTime AS InTime
		--					,[Status] 
		--					,LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) AS OutTime
		--					,((CONVERT(VARCHAR(50),ISNULL(CAST((LEAD(PunchTime) OVER (ORDER BY ALD.PunchTime) - PunchTime) AS TIME(0)),'00:00:00'))+ ' Hrs'))AS WorkingHours
		--					,ALD.CompanyId
		--				FROM	[dbo].[EmployeeDetails] ED	
		--				JOIN	[dbo].[AttendanceLogDetails] ALD
		--				ON	ED.EmployeeId = ALD.EmployeeId 
		--			WHERE	PunchDate BETWEEN @FromDate AND @Todate -- '2023-11-04'
		--			AND ED.EmployeeId = @LoginUserId -- 2 
		--		) IQ
		--WHERE Status = 1;

		--DROP TABLE IF EXISTS #WorkingHours;
		--SELECT	EmployeeId, PunchDate, (RIGHT('0' + CONVERT(VARCHAR,SUM((SUBSTRING(CONVERT(VARCHAR(5), LEFT(WorkingHours,8), 108), 1, 2) * 60 + SUBSTRING(CONVERT(VARCHAR(5), 
		--		LEFT(WorkingHours,8), 108), 4, 2))) / 60),2) + ':' + RIGHT('0' + CONVERT(VARCHAR,SUM((SUBSTRING(CONVERT(VARCHAR(5), LEFT(WorkingHours,8), 108), 1, 2) * 60 +
		--		SUBSTRING(CONVERT(VARCHAR(5),LEFT(WorkingHours,8), 108), 4, 2))) % 60),2)) AS WorkingHours
		--INTO	#WorkingHours
		--FROM	#DetailedDailyData
		--GROUP BY EmployeeId, PunchDate;

		----Logic for PunchIn At
		--SELECT  TOP 1  FORMAT(ISNULL(PunchTime,''),'ddd, dd MMM yyyy hh.mm tt') AS PunchInAt
		--		,CONCAT(ISNULL(WH.WorkingHours,'00:00'),' Hrs') AS Production
		--FROM	[dbo].[AttendanceLogDetails] ALD
		--LEFT JOIN	#WorkingHours WH
		--		ON	ALD.PunchDate = WH.PunchDate 
		--WHERE	CONVERT(DATE,ALD.PunchDate) = CONVERT(DATE,GETDATE())
		--AND		ALD.EmployeeId = @LoginUserId
		--AND		CompanyId = @CompanyId;

		---- Logic for Grid
		--DROP TABLE IF EXISTS #Resultset;
		--SELECT	A.EmployeeId 
		--		,CONVERT(NVARCHAR(50),A.PunchDate,113) AS [Date] 
		--		,ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS  PunchIn
		--		,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
		--		,CONCAT(ISNULL(WH.ProductionHours,'00:00'),' Hrs') AS Production
		--		,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR,((PunchOut-PunchIn) - CAST(WH.ProductionHours AS DATETIME)),114),'00:00'),5), ' Hrs') AS [Break]
		--		--,CASE WHEN PunchIn IS NOT NULL THEN CONCAT(CONVERT(DECIMAL(4,2),CWD.WorkingHours) - (CONVERT(VARCHAR(50),ISNULL(CAST((PunchOut-PunchIn) AS DECIMAL(4,2)),0))),' Hrs') 
		--		--		ELSE CONCAT('00:00',' Hrs') 
		--		-- END AS OverTime
		--INTO	#Resultset
		--FROM	(	SELECT A.*,DATENAME(DW,PunchDate) AS [WeekDay],ED.EmployeeId   
		--			FROM #Attendance A, (SELECT * FROM EmployeeDetails WHERE EmployeeId = @LoginUserId AND CompanyId = @CompanyId)ED )AS A
		--LEFT JOIN	(
		--			SELECT [Day] AS [WeekDay], WorkingHours, CompanyId
		--			FROM	[dbo].[CompanyWorkingDayDetails] CWD
		--			WHERE CompanyId = @CompanyId
		--		) CWD
		--	ON A.CompanyId = CWD.CompanyId 
		--	AND A.[WeekDay] = CWD.[WeekDay]
		--LEFT JOIN	(
		--				SELECT EmployeeId, PunchDate,WorkingHours AS ProductionHours
		--				FROM	#WorkingHours
		--			) WH
		--	ON	A.PunchDate = WH.PunchDate 
		--	AND A.EmployeeId = WH.EmployeeId
		--LEFT JOIN   (SELECT	DISTINCT	ALD.EmployeeId
		--								,PunchDate
		--								,(	SELECT  MIN(PunchTime) 
		--									FROM	[AttendanceLogDetails] ALD1
		--									WHERE	ALD1.EmployeeID = ALD.EmployeeId 
		--									AND		ALD1.PunchDate =  ALD.PunchDate
		--									AND		ALD1.[Status] = 1 
		--									) AS PunchIn
		--								,(	SELECT	MAX(PunchTime)
		--									FROM	[AttendanceLogDetails] ALD2
		--									WHERE	ALD2.EmployeeID = ALD.EmployeeId 
		--	   								AND		ALD2.PunchDate = ALD.PunchDate
		--									AND		ALD2.[Status] = 0 
		--									) AS PunchOut
		--			FROM	[dbo].[AttendanceLogDetails] AS ALD
		--			WHERE	(CONVERT(DATE,ALD.PunchDate) BETWEEN @FromDate AND @ToDate) 
		--			AND		(EmployeeId = @LoginUserId)
		--			AND		(CompanyId = @CompanyId)) AS ALDS
		--		ON	A.PunchDate = ALDS.PunchDate
		--		AND A.EmployeeId = ALDS.EmployeeId
		--GROUP BY A.EmployeeId 
		--		,A.PunchDate
		--		, PunchIn
		--		, PunchOut
		--		,WorkingHours
		--		,WH.ProductionHours;

		---- Logic for BreakTime, OverTime to show under counter
		--SELECT	ISNULL([Break],'00:00 Hrs') AS [Break]
		--		,'01:30 Hrs' AS OverTime
		--FROM	#Resultset
		--WHERE	[Date] = CONVERT(NVARCHAR(50),CONVERT(DATE,GETDATE()),113);

		----Today Activities
		--SELECT	ISNULL(FORMAT(InTime,'hh:mm tt'),'') AS PunchIn
		--		,ISNULL(FORMAT(OutTime,'hh:mm tt'),'') AS PunchOut
		--FROM	#DetailedDailyData
		--WHERE	CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE())
		--AND		EmployeeId = @LoginUserId;

		----2.Displaying the Last one Week AttendanceLogDetails Have the Columns of Date,Day,NoOfHours,Status.
		SELECT	CONCAT(CONVERT(VARCHAR(5), ISNULL(CAST((PunchOut - PunchIn) AS TIME(0)), '00:00')),' Hrs')  AS NoOfHours
				,LEFT(DATENAME(DW,TA.PunchDate),3) AS [Day]
				,CASE	WHEN IQ.PunchDate IS NULL THEN 'Absent'
					ELSE 'Present' END [Status]
				,CONVERT(VARCHAR(20),TA.PunchDate,105) AS PunchDate  
		FROM	#Attendance AS TA
		LEFT JOIN   (SELECT	DISTINCT	T1.EmployeeId
										,PunchDate
										,(	SELECT  MIN(PunchTime) 
											FROM	[AttendanceLogDetails] IQ1
											WHERE	IQ1.EmployeeID = T1.EmployeeId 
											AND		IQ1.PunchDate =  T1.PunchDate
											AND		IQ1.[Status] = 1 
											) AS PunchIn
										,(	SELECT	MAX(PunchTime)
											FROM	[AttendanceLogDetails] IQ2
											WHERE	IQ2.EmployeeID = T1.EmployeeId 
			   								AND		IQ2.PunchDate = T1.PunchDate
											AND		IQ2.[Status] = 0 
											) AS PunchOut
					FROM	[dbo].[AttendanceLogDetails] AS T1
					) IQ
			ON	TA.PunchDate = IQ.PunchDate
			WHERE	CONVERT(DATE,IQ.PunchDate) BETWEEN DATEADD(DAY, -7, GETDATE()) AND GETDATE()
			AND		EmployeeId = @LoginUserId
			ORDER BY PunchDate;
		
		--3.Employee's MonthWise salary
		--SELECT 'Jan' AS [Month],'62.11%' AS SalaryPecentage
		--UNION ALL 
		--SELECT 'Feb' AS [Month],'31.05%' AS SalaryPecentage
		--UNION ALL 
		--SELECT 'Mar' AS [Month],'80.28%' AS SalaryPecentage
		--UNION ALL 
		--SELECT 'Apr' AS [Month],'80.28%' AS SalaryPecentage
		--UNION ALL 
		--SELECT 'May' AS [Month],'80.28%' AS SalaryPecentage
		--UNION ALL 
		--SELECT 'Jun' AS [Month],'80.28%' AS SalaryPecentage

		--SELECT	CASE	WHEN [Month] = 1 THEN  'Jan'
		--				WHEN [Month] = 2 THEN  'Feb'
		--				WHEN [Month] = 3 THEN  'Mar'
		--				WHEN [Month] = 4 THEN  'Apr'
		--				WHEN [Month] = 5 THEN  'May'
		--				WHEN [Month] = 6 THEN  'Jun'
		--				WHEN [Month] = 7 THEN  'Jul'
		--				WHEN [Month] = 8 THEN  'Aug'
		--				WHEN [Month] = 9 THEN  'Sep'
		--				WHEN [Month] = 10 THEN 'Oct'
		--				WHEN [Month] = 11 THEN 'Nov'
		--				WHEN [Month] = 12 THEN 'Dec'
		--		ELSE ''
		--		END AS [Month]
		--		,FORMAT((NetPay / SUM(NetPay) OVER (PARTITION BY EmployeeId)) * 100, '0.00') + '%' AS SalaryPercentage
		--FROM	[dbo].[PaySlipDetails]
		--WHERE	EmployeeId = @LoginUserId;

		SELECT		'Jan'	AS [Month]
					,'100'  AS SalaryPercentage
		UNION ALL
		SELECT		'Feb'	AS [Month]
					,'50'  AS SalaryPercentage
		UNION ALL
		SELECT		'Mar'	AS [Month]
					,'100'  AS SalaryPercentage
		UNION ALL
		SELECT		'Apr'	AS [Month]
					,'96'  AS SalaryPercentage
		UNION ALL
		SELECT		'Jun'	AS [Month]
					,'98'  AS SalaryPercentage
		UNION ALL
		SELECT		'Jul'	AS [Month]
					,'100'  AS SalaryPercentage

		--4.Displaying the PermissionDetails have the column of LeaveTaken,RemainingLeaves.
		--CasualLeave
		SELECT	ISNULL(LeaveTypeName,' ') AS LeaveType
				,CONCAT('Available Casual Leave ', MIN(ISNULL(LeaveCount,0)), ' Days') AS AvailableCasualLeave
				,CONCAT('Taken Leave of ', COUNT(ISNULL(LeaveId,0)), ' Days') AS TakenLeave
				,FORMAT((COUNT(ISNULL(LeaveId,0)) / ISNULL(MIN(LeaveCount), 0)) * 60, '0.00') AS CasualPercentage
		FROM	[dbo].[LeaveDetails] LD
		LEFT JOIN	[dbo].[LeaveTypeDetails] LTD
				ON LTD.LeaveTypeId = LD.LeaveTypeId
		LEFT JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
				ON LTD.LeaveTypeId = LTGMD.LeaveTypeId
		LEFT JOIN	[dbo].[LeavestatusDetails] LSD
				ON LSD.LeaveStatusId = LD.LeaveStatusId
		WHERE	CONVERT(DATE, FromDate) BETWEEN @FromDate AND @ToDate
		AND		LTD.LeaveTypeName	= 'Casual Leave'
		AND		EmployeeId			= @LoginUserId
		AND		LD.CompanyId		= @CompanyId 
		GROUP BY LeaveTypeName;
	
		--SickLeave
		SELECT	LeaveTypeName AS LeaveType
				,CONCAT('Avaliable Sick Leave', MIN(LeaveCount), ' Days') AS AvaliableSickLeave
				,CONCAT('Taken Leave of ', COUNT(LeaveId), ' Days') AS TakenLeave
				,FORMAT((COUNT(ISNULL(LeaveId,0)) / ISNULL(MIN(LeaveCount), 0)) * 60, '0.00') AS SickPercentage
		FROM	[dbo].[LeaveTypeDetails] LTD
		LEFT JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
				ON LTD.LeaveTypeId = LTGMD.LeaveTypeId
		JOIN	[dbo].[LeaveDetails] LD
			ON	LTD.LeaveTypeId = LD.LeaveTypeId
		WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
		AND		LTD.LeaveTypeName = 'Sick Leave' 
		AND		EmployeeId		  = @LoginUserId
		AND		LD.CompanyId	  = @CompanyId 
		GROUP BY LeaveTypeName

		-- Privilege Leave.
		SELECT	LeaveTypeName AS LeaveType
				,CONCAT('Avaliable Privilege Leave', MIN(LeaveCount), ' Days') AS AvaliablePrivilegeLeave
				,CONCAT('Taken Leave of ', COUNT(LeaveId), ' Days') AS TakenLeave
				,FORMAT((COUNT(ISNULL(LeaveId,0)) / ISNULL(MIN(LeaveCount), 0)) * 60, '0.00') AS PrivilegePercentage
		FROM	[dbo].[LeaveTypeDetails] LTD
		LEFT JOIN [dbo].[LeaveTypeGradeMappingDetails] LTGMD
			ON	LTGMD.LeaveTypeId = LTD.LeaveTypeId
		JOIN	[dbo].[LeaveDetails] LD
			ON	LTD.LeaveTypeId = LD.LeaveTypeId
		WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @Todate
		AND		LTD.LeaveTypeName	= 'Privilege Leave' 
		AND		EmployeeId			= @LoginUserId
		AND		LD.CompanyId		= @CompanyId 
		GROUP BY LeaveTypeName;

		--5.Displaying the PermissionDetails TakenPermission,RemainingPermission
		SELECT @TotalPermission = LeaveCount
		FROM	[dbo].[LeaveTypeDetails] LTD
		LEFT JOIN [dbo].[LeaveTypeGradeMappingDetails] LTGMD
			ON	LTGMD.LeaveTypeId = LTD.LeaveTypeId
		WHERE	LTD.LeaveTypeId = 1
		AND		CompanyId = @CompanyId;

		SELECT @TakenPermission = COUNT(PermissionId)
		FROM	[dbo].[PermissionDetails]
		WHERE	EmployeeId = @LoginUserId
		AND		PermissionStatusId = 3
		AND		CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate
		AND		CompanyId = @CompanyId;

		SELECT @RemaingingPermission = (@TotalPermission - @TakenPermission)

		--SELECT  @TakenPermission		AS TakenPermission		
		--		,@RemaingingPermission	AS RemaingingPermission	
		--		,@TotalPermission		AS TotalPermission;	
		SELECT  '01:30'					AS RemaingingPermission	
				,'02:00'				AS TotalPermission

		--6.Displaying the CompensatoryOffDetails TakenCompensatoryOff,RemainingCompensatoryOff
		SELECT @TotalCompensatoryOff = LeaveCount
		FROM	[dbo].[LeaveTypeDetails] LTD
		LEFT JOIN [dbo].[LeaveTypeGradeMappingDetails] LTGMD
			ON	LTGMD.LeaveTypeId = LTD.LeaveTypeId
		WHERE	LTD.LeaveTypeId = 2
		AND		CompanyId = @CompanyId;

		SELECT @TakenCompensatoryOff = COUNT(CompensatoryOffId)
		FROM	[dbo].[CompensatoryOffDetails]
		WHERE	EmployeeId = @LoginUserId
		AND		CompensatoryOffStatusId = 3
		AND		CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
		AND		CompanyId = @CompanyId;

		SELECT @RemaingingCompensatoryOff = (@TotalCompensatoryOff - @TakenCompensatoryOff)

		--SELECT  @TakenCompensatoryOff		AS TakenCompensatoryOff
		--		,@RemaingingCompensatoryOff	AS RemaingingCompensatoryOff
		--		,@TotalCompensatoryOff		AS TotalCompensatoryOff;	


		SELECT  '0'			AS TakenCompensatoryOff
				,'5'		AS RemaingingCompensatoryOff



		--7.Displaying the Approved and Completed LoanDetails.
		SELECT	LeaveStatusName AS LoanStatus
				,SUM(LoanAmount) AS TotalAmount
				,SUM(LoanAmount) AS LoanAmount
		FROM	[dbo].[LoanDetails] LD
		LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
			ON	LD.LoanStatusId = LSD.LeaveStatusId 
		WHERE	LeaveStatusName IN ('Approved', 'Completed')
		AND		EmployeeId = @LoginUserId 
		AND		CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @Todate
		AND		LD.CompanyId = @CompanyId
		GROUP BY LeaveStatusName;

		--8.Displaying the AdvanceDetails Have the Column of Date,AdvanceAmount,AdvanceStatus.
		SELECT	AdvanceId
				,LEFT(CONVERT(NVARCHAR(50),AdvanceDate,113),11) AS [Day]
				,CONCAT('Rs','.',AdvanceAmount) AS AdvanceAmount
				,LeaveStatusName AS AdvanceStatus
				,CASE	WHEN LSD.LeaveStatusName = 'Approved' THEN 'Green'
						WHEN LSD.LeaveStatusName = 'Completed' THEN 'Red'
					ELSE ' '
				 END AS Status_Colour
		FROM	[dbo].[AdvanceDetails] AD
		LEFT JOIN	[dbo].[LeavestatusDetails] LSD
			ON AD.AdvanceStatusId = LSD.LeaveStatusId 
		WHERE	AdvanceStatusId IN (2,6)
		AND		EmployeeId = @LoginUserId
		AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate   		
		AND		AD.CompanyId = @CompanyId ;

		--9.Displaying the UpComing Holidays.
		SELECT	HolidayId
				,CONCAT(DATENAME(MONTH,HolidayDate),' ',DAY(HolidayDate)) AS [Day]
				,HolidayName   
		FROM	[dbo].[HolidayDetails]
		WHERE	CONVERT(Date,HolidayDate) > GETDATE()
		AND		CompanyId = @CompanyId;

		--10.Displaying the Employee's BirthDay.
		SELECT		ED.EmployeeImage	
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
					,CONVERT(NVARCHAR(50),EPD.DateOfBirth,105) AS DateOfBirth
					,DD.DesignationName AS Designation
		FROM		[dbo].[EmployeeDetails] ED
		LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD
			 ON		ED.EmployeeId = EPD.EmployeeId
		LEFT JOIN	[dbo].[DesignationDetails] DD
			ON		ED.DesignationId = DD.DesignationId
		WHERE		MONTH(EPD.DateOfBirth) >= MONTH(GETDATE()) 
					AND MONTH(EPD.DateOfBirth) < MONTH(GETDATE()) + 3
					OR (MONTH(GETDATE()) + 3 > 12 AND MONTH(EPD.DateOfBirth) <= (MONTH(GETDATE()) + 3) % 12)
		ORDER BY	CASE  WHEN MONTH(EPD.DateOfBirth) >= MONTH(GETDATE()) 
					THEN MONTH(EPD.DateOfBirth) 
					ELSE MONTH(EPD.DateOfBirth) + 12 
					END, 
					DAY(EPD.DateOfBirth);

		--ResultSet for GEO.
		--SELECT	MapNumber	
		--FROM	[dbo].[BranchDetails]
		--WHERE	CompanyId = @CompanyId;

		SELECT	@Status    = 1  
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0 
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);
			 
	EXEC [dbo].[USP_GetDashboardDetails_Employee]	@LoginUserId	= 11
													,@FromDate		= '2024-10-01'		
													,@Status		= @S_Status		OUT
													,@Message		= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT * FROM EmployeeDetails
	SELECT * FROM AdvanceDetails
	AttendanceLogDetails
	SELECT * FROM CompensatoryOffDetails
======================================================================================================================*/
GO
