/*==========================================================================================================================================================
 Procedure Name	    :   [USP_GetEmployeeBankDetails]
 Description		:	Procedure used to retrive the EmployeeBankDetails (When click on Edit  button in EmployeeBankInfo Section in Edit Employee Screen)
 Input Parameter	:	@LoginUserId,@EmployeeBankId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	17-08-2023
 Version			:	1.0
 Comment			:	1. Get the EmployeeBankDetails have the column of EmployeeBankId, EmployeeBankName, AccountTypeId, AccountTypeName
							,AccountName, AccountNumber, IFSCCode for the given EmployeeId to show in popup.		
							1.1 Then return the output Parameter values as @Status = 1 and @Message = NULL.
=============================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetEmployeeBankDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId	TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status		= 1 
				,@Message	= NULL;
		--Get the EmployeeBankDetails have the column of EmployeeBankId,EmployeeBankName,AccountTypeId,AccountTypeName,AccountName,AccountNumber,IFSCCode
		BEGIN
			SELECT	EmployeeBankId
					,EmployeeBankName
					,ATD.AccountTypeId
					,ATD.AccountTypeName
					,AccountName
					,AccountNumber
					,IFSCCode 
			FROM	[DBO].[EmployeeBankDetails] EBD
			JOIN	[DBO].[AccountTypeDetails] ATD
				ON	EBD.AccountTypeId =ATD.AccountTypeId
			WHERE	 EmployeeId = @EmployeeId AND CompanyId = @CompanyId;
			
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeBankDetails]	@LoginUserId		= 1
											,@EmployeeId		= 2
											,@Status			= @S_Status	 OUT
											,@Message			= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
	SELECT	* 
	FROM	[dbo].[EmployeeBankDetails];
=================================================================================================================================================*/
GO
