/*=================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetEmployeeDeviceMappingDetails]
 Description		:	Procedure used to Get the EmployeeDevice Mapping Details
																(When Click on Machine Mapping Icon Button in Employee Grid)
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	24-07-2024
 Version			:	1.0 
 Comment			:	1. Get the EmployeeDeviceMappingDetails for the given @EmployeeId.
						2.Then return the output Parameters values as @Status = 1 and @Message = NULL.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeDeviceMappingDetails]
(
	@LoginUserId						INT
	,@EmployeeId						INT   
	,@Status							BIT				OUT	
	,@Message							NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variables.
    DECLARE  @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	
	BEGIN TRY
		SELECT	EmployeeDeviceMappingId
				,EDMD.AttendanceMachineId
				,AttendanceMachineName AS [Device Name]
				,SerialNo AS [Serial No]
				,EDMD.IsBlock AS [Status]
		FROM	[dbo].[EmployeeDeviceMappingDetails] EDMD
		JOIN	[dbo].[AttendanceMachineDetails] AMD
			ON	EDMD.AttendanceMachineId = AMD.AttendanceMachineId
		JOIN	[dbo].[EmployeeDetails] ED 
			ON	ED.EmployeeId = EDMD.EmployeeId
		WHERE	EDMD.EmployeeId = @EmployeeId
		AND		ED.CompanyId = @CompanyId
		AND		EDMD.IsActive = 1;

		SELECT	CONCAT(FirstName,' ',LastName) AS EmployeeName
				,EmployeeCompanyId
		FROM	[dbo].[EmployeeDetails]
		WHERE	EmployeeId = @EmployeeId;

		SELECT	@Status   = 1  
				,@Message = NULL; 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status   = 0
			   ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeDeviceMappingDetails]	@LoginUserId	= 1
														,@EmployeeId	= 32
														,@Status		= @S_Status OUT
														,@Message		= @M_Message OUT;  

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[EmployeeDetails];

	SELECT * FROM [dbo].[EmployeeDeviceMappingDetails]
======================================================================================================================================*/
GO
