/*====================================================================================================================================================
 Procedure Name	    :   [USP_GetEmployeeEducationDetails]
 Description		:	Procedure used to retrive the EmployeeEducationDetails (1.when click on Edit Button in EmployeeEducationInfo Section 
																				  in Edit Employee Screen)
 Input Parameter	:	@LoginUserId,  @EmployeeId, @EducationId	
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	17-08-2023
 Version			:	1.0
 Comment			:	1. If the Entered @EmployeeEducationId Is NULL,then
							1.1 Get the EmployeeEducationDetails have the column of EducationId ,InstituteName ,PeriodFrom ,PeriodTo ,Degree 
								,Course,Grade to Show in popup Grid.		
							1.2  Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If the Entered @EmployeeEducationId is NOT NULL, then
							2.1 Get the EmployeeEducationDetails have the column of EducationId,InstituteName,PeriodFrom,PeriodTo,Degree,Course 
								,Grade for the given EmployeeId to show in popup.
						    2.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeEducationDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@EducationId	INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId  TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given @EducationId is Null, then get all the EmployeeEducationDetails.
		IF (@EducationId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	EmployeeId
					,EducationId 
					,InstituteName
					,CONCAT(Degree,' - ',Course) AS CourseName
					,CONCAT(YEAR(PeriodFrom),' - ', YEAR(PeriodTo)) EducationYear
			FROM	[dbo].[EmployeeEducationDetails]
			WHERE	EmployeeId  = @EmployeeId;
		END
		ELSE 
		BEGIN
			--If the given @EducationId is Not Null, then get the particular EmployeeEducationDetails.
			SELECT	EmployeeId
					,EducationId 
					,InstituteName 
					,CONVERT(NVARCHAR(50),PeriodFrom,105) AS PeriodFrom			
					,CONVERT(NVARCHAR(50),PeriodTo,105)AS PeriodTo	
					,Degree 
					,Course
					,Grade
			FROM	[dbo].[EmployeeEducationDetails] 
			WHERE	EmployeeId  = @EmployeeId 
			AND		EducationId = @EducationId
			ORDER BY PeriodTo;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeEducationDetails]	@LoginUserId	= 1
													,@EmployeeId	= 3
													,@EducationId	= null
													,@Status		= @S_Status	 OUT
													,@Message		= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeEducationDetails];
================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetEmployeeExperienceDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================================================================
 Procedure Name	    :   [USP_GetEmployeeExperienceDetails]
 Description		:	Procedure used to retrive the EmployeeExperienceDetails ((1. when click on Edit Button in  EmployeeExperienceInfo screen
																				 in Employee Screen)
 Input Parameter	:	@LoginUserId,@EmployeeId, @EmployeeExperienceId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	17-08-2023
 Version			:	1.0
 Comment			:	1. If the Entered @EmployeeExperienceId Is NULL,then
 							1.1 Get all the EmployeeExperienceDetails have the column of EmployeeExperienceId, CompanyName ,Location, Designation ,PeriodFrom 
								,PeriodTo to show in Grid.	
							1.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If the Entered @EmployeeExperienceId is NOT NULL, then
							2.1 Get the EmployeeExperienceDetails have the column of EmployeeExperienceId, CompanyName ,Location, Designation ,PeriodFrom 
								,PeriodTo for the given EmployeeId to show in popup.				
							2.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
==============================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetEmployeeExperienceDetails]
(	
	@LoginUserId			 INT
	,@EmployeeId			 INT
	,@EmployeeExperienceId	 TINYINT
	,@Status		         BIT				OUT	
	,@Message		         NVARCHAR(500)	    OUT
	)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId  TINYINT;
			
	--Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given @EmployeeExperienceId is Null, then get all the EmployeeExperienceDetails.
		IF (@EmployeeExperienceId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	EmployeeId
					,EmployeeExperienceId 
					,CompanyName  
					,RIGHT(CONVERT(NVARCHAR(50),PeriodFrom,113),8) AS PeriodFrom
					,RIGHT(CONVERT(NVARCHAR(50),ISNULL(PeriodTo,GETDATE()),113),8) AS PeriodTo	
					,CONCAT(DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())) 
						- CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) THEN 1 ELSE 0 END, 
						CASE WHEN DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())) <= 1 THEN ' year ' ELSE ' years ' END,
						DATEDIFF(MONTH, DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())) 
						- CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) THEN 1 ELSE 0 END, PeriodFrom), ISNULL(PeriodTo, GETDATE())) % 12, 
						' months') AS Duration
			FROM	[dbo].[EmployeeExperienceDetails] 
			WHERE	EmployeeId  = @EmployeeId;
		END
		ELSE 
		BEGIN
			--If the given @EmployeeExperienceId is Not Null, then get the particular EmployeeExperienceDetails.
			SELECT	EmployeeId
					,EmployeeExperienceId
					,CompanyName	
					,[Location]		
					,Designation	
					,CONVERT(NVARCHAR(50),PeriodFrom,105) AS PeriodFrom		
					,CONVERT(NVARCHAR(50),PeriodTo,105) AS PeriodTo		
					,IsPresent
			FROM	[dbo].[EmployeeExperienceDetails] 
			WHERE	EmployeeId  = @EmployeeId 
			AND		EmployeeExperienceId = @EmployeeExperienceId
			ORDER BY PeriodTo DESC;

		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==========================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeExperienceDetails]    @LoginUserId				= 1
													 ,@EmployeeId				= 3
													 ,@EmployeeExperienceId		= NULL
													 ,@Status		       		= @S_Status	 OUT
													 ,@Message		       		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM [dbo].[EmployeeExperienceDetails];
	SELECT * FROM [dbo].[EmployeeDetails];
================================================================================================================================================*/
GO
