/*============================================================================================================================================================================
 Procedure Name	    :   [USP_GetEmployeeFamilyMemberDetails]
 Description		:	Procedure used to retrive the EmployeeFamilyMemberDetails (When click on Edit button in EmployeeFamilyMemberInfo Section in Edit Employee Sccreen)
 Input Parameter	:	@LoginUserId,  @EmployeeId, @EmployeeFamilyMemberId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	17-08-2023
 Version			:	1.0
 Comment			:	1. If the Entered @EmployeeFamilyMemberId Is NULL,then 
 							1.1  Get the EmployeeFamilyMemberDetails have the column of EmployeeFamilyMemberId,Name,Relation,DateOfBirth,ContactNo 
								 To Show in Grid For the Given EmployeeId. 	
							1.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If the Entered @EmployeeFamilyMemberId is NOT NULL, then
							2.1  Get the EmployeeFamilyMemberDetails have the column of EmployeeFamilyMemberId ,PersonName,RelationId ,RelationName
								,DateOfBirth, ContactNo, IsPrimaryContact for the given EmployeeId.		
							2.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
==============================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeFamilyMemberDetails]
(	
	@LoginUserId				INT
	,@EmployeeId				INT
	,@EmployeeFamilyMemberId	TINYINT
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId  TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given @EmployeeFamilyMemberId is Null, then get all the EmployeeFamilyMemberDetails.
		IF (@EmployeeFamilyMemberId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	EmployeeId
					,EmployeeFamilyMemberId 
					,PersonName AS [Name]
					,RelationName AS Relationship
					,ContactNumber AS ContactNo
					,CASE WHEN IsPrimaryContact = 1 THEN 'Yes' ELSE 'No' END AS [Primary Person]
			FROM	[dbo].[EmployeeFamilyMemberDetails] EFMD
			JOIN	[DBO].[RelationDetails] RD
				ON	EFMD.RelationId = RD.RelationId	
			WHERE	EmployeeId = @EmployeeId 
			AND		CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			--If the given @EmployeeFamilyMemberId is Not Null, then get the particular EmployeeFamilyMemberDetails.
			SELECT  EmployeeId
					,EmployeeFamilyMemberId 
					,PersonName
					,RD.RelationId 
					,RD.RelationName
					,ContactNumber
					,IsPrimaryContact
			FROM	[dbo].[EmployeeFamilyMemberDetails] EFMD
			JOIN	[DBO].[RelationDetails] RD
				ON	EFMD.RelationId =RD.RelationId	
			WHERE	EFMD.EmployeeId = @EmployeeId 
			AND		EmployeeFamilyMemberId = @EmployeeFamilyMemberId
			AND		CompanyId = @CompanyId
			ORDER BY IsPrimaryContact DESC
					,EmployeeFamilyMemberId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeFamilyMemberDetails]  @LoginUserId				= 1
													,@EmployeeId				= 1
													,@EmployeeFamilyMemberId	= null
													,@Status					= @S_Status	 OUT
													,@Message					= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeFamilyMemberDetails];

================================================================================================================================*/



GO
/****** Object:  StoredProcedure [dbo].[USP_GetEmployeeIdPrefixDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*================================================================================================================================  
 Procedure Name		:	[DBO].[USP_GetEmployeeIdPrefixDetails]
 Description		:	Procedure used to get EmployeeIdPrefix
 Input Parameter	:	@LoginUserId,@EmpIdPrefix
 Output Parameters	:	@Status, @Message															 
 Author				:	Nithya.M																  
 Created on			:	02-08-2024	
 Version			:	1.0 
 Comment			:	1.Update the CompanyDetails table have the column of
									CompanyName				AS @CompanyName
									,CompanyLogoFileName	AS @CompanyLogoFileName
									
================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetEmployeeIdPrefixDetails]
(
	@LoginUserId						INT
	,@Status							BIT								OUT	
	,@Message							NVARCHAR(500)					OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
	
	DECLARE @BaseValue NVARCHAR(50);
	DECLARE @Prefix NVARCHAR(10);
	DECLARE @NumericBaseValue INT;
	DECLARE @NextId INT;

	SELECT 
	    @BaseValue = EmpIdStartingFrom,
	    @Prefix = EmpIdPrefix
	FROM [DBO].[CompanySettingDetails]
	WHERE IsEmpIdAutomatic = 1 AND CompanyId = @CompanyId;

	--SELECT * FROM [DBO].[CompanySettingDetails]
	
	IF @BaseValue IS NOT NULL AND @Prefix IS NOT NULL
	BEGIN
	    SET @NumericBaseValue = CASE 
	        WHEN PATINDEX('%[0-9]%', @BaseValue) > 0 
	        THEN CAST(SUBSTRING(@BaseValue, PATINDEX('%[0-9]%', @BaseValue), LEN(@BaseValue)) AS INT)
	        ELSE 0
	    END;
	
	    WITH NumericPart AS (
	        SELECT 
	            CAST(SUBSTRING(EmployeeCompanyId, PATINDEX('%[0-9]%', EmployeeCompanyId), LEN(EmployeeCompanyId)) AS INT) AS NumericId
	        FROM 
	            [DBO].[EmployeeDetails]
	        WHERE 
	            CompanyId = @CompanyId
	    ),
	    MaxNumericId AS (
	        SELECT ISNULL(MAX(NumericId), @NumericBaseValue - 1) AS MaxId
	        FROM NumericPart
	    )
	    SELECT @NextId = MaxId + 1
	    FROM MaxNumericId;

	    SELECT CONCAT(@Prefix, @NextId) AS NewEmployeeCompanyId;
		SELECT	@Status    = 1 
				,@Message  = NULL;
	END
	ELSE
	BEGIN
	    SELECT NULL AS NewEmployeeCompanyId;
	END
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [DBO].[USP_GetEmployeeIdPrefixDetails]		@LoginUserId  = 1
													,@Status      = @S_Status	OUT
													,@Message     = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[CompanyDetails];
	SELECT	*
	FROM	[dbo].[CompanySettingDetails];
=============================================================================================================================*/
GO
