/*==============================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_GetEmployeeSalaryDetails]
 Description		:	Procedure used to retrive the EmployeeSalaryDetails(When click on Edit button in EmployeeSalaryInfo Section in Edit Employee Screen)
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	23-08-2023
 Version			:	1.0
 Comment			:	1. Get the EmployeeSalaryDetails have the column of EmployeeId,PayTypeId,PayTypeName,PaymentTypeId ,PaymentTypeName,CTC,MonthlySalary
						   ,BasicPay ,HRA, OtherAllowance for the given	EmployeeId.		
							1.1 Get the EmployeePFDetails have the column of UANNumber,PFNumber,EmployeeContribution,EmployerContribution for the given EmployeeId.	
							1.2 Get the EmployeeESIDetails have the column of IsESIApplicable,EmployeeESINumber,EmployeeESIContribution for the given EmployeeId.	
						2. Then return the output Parameters values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetEmployeeSalaryDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId TINYINT;
		
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status		= 1 
				,@Message	= NULL;

		SELECT	ED.EmployeeId	
				,PTD.PayTypeId
				,PayTypeName
				,PMTD.PaymentTypeId	
				,PaymentTypeName
				,ESD.CTC			
				,ESD.MonthlySalary	
				,ESD.BasicPay		
				,ESD.HRA			
				,ESD.OtherAllowence	
				,EPFD.UANNumber				
				,EPFD.PFNumber				
				,EPFD.EmployeeContribution	
				,EPFD.EmployeerContribution	
				--,CASE WHEN IsESIApplicable = 1 THEN 'Yes'ELSE 'No' 
				-- END AS IsESIApplicable
				,IsESIApplicable
				,EESID.EmployeeESINumber		
				,EESID.EmployeeESIContribution
		FROM	[DBO].[EmployeeDetails] ED
		LEFT JOIN	[DBO].[EmployeeSalaryDetails] ESD
				ON	ED.EmployeeId = ESD.EmployeeId
		LEFT JOIN	[DBO].[EmployeePFDetails] EPFD
				ON	ED.EmployeeId = EPFD.EmployeeId
		LEFT JOIN	[DBO].[EmployeeESIDetails] EESID
				ON	ED.EmployeeId = EESID.EmployeeId
		LEFT JOIN	[DBO].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
		LEFT JOIN	[DBO].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
		LEFT JOIN	[DBO].[DesignationDetails] DE
				ON	ED.DesignationId  = DE.DesignationId 
		LEFT JOIN	[DBO].[EmployeeDetails] RPD
				ON	RPD.EmployeeId  = ED.ReportingPersonId 
		JOIN	[DBO].[PayTypeDetails] PTD
				ON	ESD.PayTypeId = PTD.PayTypeId
		JOIN	[DBO].[PaymentTypeDetails] PMTD	
				ON	ESD.PaymentTypeId = PMTD.PaymentTypeId
		WHERE	ED.EmployeeId = @EmployeeId 
		AND		ED.CompanyId = @CompanyId;
		
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeSalaryDetails]	@LoginUserId	= 11
												,@EmployeeId	= 11
												,@Status		= @S_Status	 OUT
												,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[EmployeeSalaryDetails];

	SELECT * FROM DepartmentDetails

	SELECT * FROM BranchDetails

	SELECT * FROM EmployeeDetails

	UPDATE EmployeeDetails
	SET ReportingPersonId = 7
	WHERE EmployeeId = 11

================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetEmployeeSalaryInfoDetailByCTC]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetEmployeeSalaryInfoDetailByCTC]
 Description		:	Procedure used to retrieve the Dynamic columns based on the salary structure of the employee type (When entering the CTC value)
 Input Parameter	:	@LoginUserId,@CTCAmount,@EmployeeType
 Output Parameters	:	@Status, @Message
 Author				:	Satheesh
 Created on			:	09.11.2024
 Version			:	1.0 
 Comment			:	
======================================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeSalaryInfoDetailByCTC]
(	
	@LoginUserId		INT
	,@CTCAmount			NUMERIC(11,2)
	,@EmployeeTypeId	INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	BEGIN TRY
		SELECT	DISTINCT SSD.SalaryStructureId
				,SalaryStructureName
				,ComponentName
				,CASE WHEN EarningType =  '%' THEN CONVERT(NUMERIC(11,2),(@CTCAmount *(EarningAmount/100))) 
					ELSE (@CTCAmount * EarningAmount) END AS ActualValue
		FROM	[dbo].[SalaryStructureDetails] SSD
		JOIN	[dbo].[SalaryStructureComponentMappingDetails] SSCMD
			ON	SSD.SalaryStructureId = SSCMD.SalaryStructureId
		JOIN	[dbo].[SalaryComponentsDetails] SCD
			ON	SCD.SalaryComponentsId = SSCMD.SalaryComponentsId
		JOIN	[dbo].[EmployeeTypeStructureMappingDetails] ESMD
			ON	ESMD.SalaryStructureId = SSD.SalaryStructureId
		WHERE	ESMD.EmployeeTypeId = @EmployeeTypeId
		AND		SSCMD.IsActive = 1
		AND		SCD.IsActive = 1;

		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeSalaryInfoDetailByCTC]	@LoginUserId		= 1
														,@CTCAmount			= 500000
														,@EmployeeTypeId	= 1
														,@Status			= @S_Status	 OUT
														,@Message			= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
=================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetEmployeeShiftMappingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetEmployeeShiftMappingDetails]
 Description		:	Procedure Used to retrieve the EmployeeShiftMappingDetails
																	(When click on Setting Info SideNavigation Bar
																	 And click on Edit option in Grid from UI)
 Input Parameter	:	@LoginUserId, @ShiftId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-028-2024
 Version			:	1.0
 Comment			:	1. If the given @ShiftId is NULL,then 
							1.1 Get the All ShiftDetails have the columns of ShiftId, ShiftName, StartTime, EndTime, Description
								to show in Grid.		
							1.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If the given @ShiftId is NOT NULL, then 
							2.1 Get the particular ShiftDetails have the Columns of ShiftId, ShiftName, StartTime, EndTime
								,ShiftDescription for the given @ShiftId to show in Grid.					    
							2.2 Then return the output Parameter values as @Status= 1 and @Message = NULL.
 ================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeShiftMappingDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@StartDate		DATE
	,@ShiftDate		INT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variable.
	DECLARE @CompanyId		TINYINT
			,@Cols			NVARCHAR(MAX)
			,@Sql			NVARCHAR(MAX)
			,@FirstDate		DATETIME		= @StartDate
			,@EndDate		DATETIME		= EOMONTH(@StartDate)
			,@UserGroupId	TINYINT
			,@date1			DATE			= NULL;

	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[DBO].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	DROP TABLE IF EXISTS #Date;
	CREATE TABLE #Date 
	(
		Id          INT			 IDENTITY(1,1)
		,[Date]		DATE
	)

	WHILE @FirstDate <= @EndDate
	BEGIN
		INSERT INTO	#Date([Date]) 
		VALUES		(@FirstDate);
		SET			@FirstDate = DATEADD(DAY,1, @FirstDate);
	END;
	
	SELECT @date1 = DATEFROMPARTS(CONVERT(VARCHAR(10), YEAR(@EndDate)),
                              CONVERT(VARCHAR(10), MONTH(@EndDate)),
                              CONVERT(VARCHAR(10), @ShiftDate));

	BEGIN TRY	
		IF @EmployeeId IS NULL	
		BEGIN
			IF @UserGroupId = 1 
			BEGIN 
				SET @Cols = STUFF((	SELECT	DISTINCT ',' + QUOTENAME(RIGHT(CONVERT(NVARCHAR(50), [Date]), 2))
									FROM	#Date
									FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');

				SET @Sql = N'	SELECT	EmployeeId, EmployeeName, EmployeeImage, ' + @Cols + '
								FROM	(
										SELECT	ED.EmployeeId
												,CONCAT(ED.FirstName, '' '', ED.LastName) AS EmployeeName
												,ED.EmployeeImage
												,RIGHT(CONVERT(NVARCHAR(10), D.[Date], 120), 2) AS [Date]
												,CASE WHEN ISNULL(ShiftName, '''') = '''' OR StartTime IS NULL 
													OR EndTime IS NULL THEN NULL
												ELSE CONCAT(ShiftName, '' / '',
												CASE WHEN CAST(LEFT(StartTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(StartTime, 5), 3) + '' AM''
													WHEN CAST(LEFT(StartTime, 2) AS INT) < 12 THEN LEFT(StartTime, 5) + '' AM''
													WHEN CAST(LEFT(StartTime, 2) AS INT) = 12 THEN LEFT(StartTime, 5) + '' PM''
													ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(StartTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(StartTime, 5), 3) + '' PM''
												END, '' / '',
												CASE WHEN CAST(LEFT(EndTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(EndTime, 5), 3) + '' AM''
													WHEN CAST(LEFT(EndTime, 2) AS INT) < 12 THEN LEFT(EndTime, 5) + '' AM''
													WHEN CAST(LEFT(EndTime, 2) AS INT) = 12 THEN LEFT(EndTime, 5) + '' PM''
													ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(EndTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(EndTime, 5), 3) + '' PM''
												END, '' / '', 
												CONCAT(FORMAT(CASE WHEN EndTime >= StartTime THEN DATEDIFF(MINUTE, StartTime, EndTime)
													ELSE DATEDIFF(MINUTE, StartTime, ''23:59:59.999'') + 1 + DATEDIFF(MINUTE, ''00:00:00.000'', EndTime)
												END / 60, ''00''), '':'',
												FORMAT(CASE WHEN EndTime >= StartTime THEN DATEDIFF(MINUTE, StartTime, EndTime)
													ELSE DATEDIFF(MINUTE, StartTime, ''23:59:59.999'') + 1 + DATEDIFF(MINUTE, ''00:00:00.000'', EndTime)
												END % 60, ''00'')) + '' Hrs'' ) END AS Shift
										FROM	[dbo].[EmployeeDetails] ED
										CROSS JOIN #Date D
										LEFT JOIN (	SELECT	ShiftId, EmployeeId,StartDate, EndDate,
															ROW_NUMBER() OVER (PARTITION BY EmployeeId, CONVERT(DATE, StartDate), CONVERT(DATE, EndDate), ShiftId ORDER BY EmployeeShiftMappingId DESC) AS RowNum
													FROM	[dbo].[EmployeeShiftMappingDetails]
													) AS ESMD 
											ON	ED.EmployeeId = ESMD.EmployeeId
											AND CONVERT(DATE, D.[Date]) BETWEEN CONVERT(DATE, ESMD.StartDate) AND ISNULL(CONVERT(DATE, ESMD.EndDate), CONVERT(DATE, D.[Date]))
											AND ESMD.RowNum = 1 
										LEFT JOIN [dbo].[ShiftDetails] SD 
											ON ESMD.ShiftId = SD.ShiftId
										WHERE ED.CompanyId = @CompanyId) AS PivotTable
								PIVOT (
										MAX	(Shift)
										FOR [Date] 
										IN	(' + @Cols + ')
									) AS PT
								ORDER BY EmployeeId;';
				EXEC SP_EXECUTESQL @Sql, N'@CompanyId INT, @EmployeeId INT, @StartDate DATETIME',
										 @CompanyId = @CompanyId, @EmployeeId = @EmployeeId, @StartDate = @StartDate;
            END
			ELSE 
			BEGIN
				SELECT @Cols = STUFF((	SELECT	DISTINCT ',' + QUOTENAME(RIGHT(CONVERT(NVARCHAR(50), [Date]), 2))
										 FROM	#Date D
										 FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');

				SET @Sql = N'	SELECT	EmployeeId, EmployeeName, EmployeeImage,' + @Cols + '
								FROM	(
											SELECT	ED.EmployeeId
													,CONCAT(ED.FirstName, '' '', ED.LastName) AS EmployeeName
													,ED.EmployeeImage
													,RIGHT(CONVERT(NVARCHAR(10), D.[Date], 120), 2) AS [Date]
													,CASE	WHEN CONCAT(ShiftName, '' / '',
															CASE	WHEN CAST(LEFT(StartTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(StartTime, 5), 3) + '' AM''
																	WHEN CAST(LEFT(StartTime, 2) AS INT) < 12 THEN LEFT(StartTime, 5) + '' AM''
																	WHEN CAST(LEFT(StartTime, 2) AS INT) = 12 THEN LEFT(StartTime, 5) + '' PM''
																ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(StartTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(StartTime, 5), 3) + '' PM''
															END, '' / '',
															CASE	WHEN CAST(LEFT(EndTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(EndTime, 5), 3) + '' AM''
																	WHEN CAST(LEFT(EndTime, 2) AS INT) < 12 THEN LEFT(EndTime, 5) + '' AM''
																	WHEN CAST(LEFT(EndTime, 2) AS INT) = 12 THEN LEFT(EndTime, 5) + '' PM''
																ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(EndTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(EndTime, 5), 3) + '' PM''
															END, '' / '', 
															FORMAT(CASE WHEN EndTime >= StartTime THEN DATEDIFF(MINUTE, StartTime, EndTime)
																ELSE DATEDIFF(MINUTE, StartTime, ''23:59:59.999'') + 1 + DATEDIFF(MINUTE, ''00:00:00.000'', EndTime)
															END / 60.0, ''0.00'') + '' Hrs'') = '' /  /  / '' THEN NULL
													ELSE CONCAT(ShiftName, '' / '',
														CASE	WHEN CAST(LEFT(StartTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(StartTime, 5), 3) + '' AM''
																WHEN CAST(LEFT(StartTime, 2) AS INT) < 12 THEN LEFT(StartTime, 5) + '' AM''
																WHEN CAST(LEFT(StartTime, 2) AS INT) = 12 THEN LEFT(StartTime, 5) + '' PM''
															ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(StartTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(StartTime, 5), 3) + '' PM''
														END, '' / '', 
														CASE	WHEN CAST(LEFT(EndTime, 2) AS INT) = 0 THEN ''12'' + RIGHT(LEFT(EndTime, 5), 3) + '' AM''
																WHEN CAST(LEFT(EndTime, 2) AS INT) < 12 THEN LEFT(EndTime, 5) + '' AM''
																WHEN CAST(LEFT(EndTime, 2) AS INT) = 12 THEN LEFT(EndTime, 5) + '' PM''
															ELSE RIGHT(CONCAT(''0'', CAST(CAST(LEFT(EndTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(EndTime, 5), 3) + '' PM''
														END, '' / '', 
														CONCAT(FORMAT(CASE WHEN EndTime >= StartTime THEN DATEDIFF(MINUTE, StartTime, EndTime)
																ELSE DATEDIFF(MINUTE, StartTime, ''23:59:59.999'') + 1 + DATEDIFF(MINUTE, ''00:00:00.000'', EndTime)
														END / 60, ''00''), '':'',
													FORMAT(CASE WHEN EndTime >= StartTime THEN DATEDIFF(MINUTE, StartTime, EndTime)
														ELSE DATEDIFF(MINUTE, StartTime, ''23:59:59.999'') + 1 + DATEDIFF(MINUTE, ''00:00:00.000'', EndTime)
													END % 60, ''00'')) + '' Hrs'') END AS Shift
											FROM	[dbo].[EmployeeDetails] ED
											CROSS JOIN #Date D
											LEFT JOIN ( SELECT	ShiftId, EmployeeId, StartDate, EndDate,
																ROW_NUMBER() OVER (PARTITION BY EmployeeId, CONVERT(DATE, StartDate), CONVERT(DATE, EndDate), ShiftId ORDER BY EmployeeShiftMappingId DESC) AS RowNum
														FROM	[dbo].[EmployeeShiftMappingDetails]
													  ) AS ESMD 
												ON	ED.EmployeeId = ESMD.EmployeeId
												AND CONVERT(DATE, D.[Date]) BETWEEN CONVERT(DATE, ESMD.StartDate) AND ISNULL(CONVERT(DATE, ESMD.EndDate), CONVERT(DATE, D.[Date]))
												AND ESMD.RowNum = 1 
											LEFT JOIN [dbo].[ShiftDetails] SD 
												ON	ESMD.ShiftId = SD.ShiftId
											WHERE	ED.CompanyId = @CompanyId
											AND		ED.EmployeeId = @LoginUserId) AS PivotTable
								PIVOT 
								(
									MAX(Shift)
									FOR [Date] 
									IN (' + @Cols + ')
								) AS PT
								ORDER BY EmployeeId;';

			PRINT @Sql
			EXECUTE SP_EXECUTESQL @Sql, N'@CompanyId INT, @LoginUserId INT', @CompanyId = @CompanyId, @LoginUserId = @LoginUserId;
			END;
		END
		ELSE 
		BEGIN
			SELECT	DISTINCT EmployeeShiftMappingId
					,ED.EmployeeId
					,ESMD.ShiftId
					,ED.FirstName AS EmployeeName
					,FORMAT(DATEFROMPARTS(YEAR(@EndDate),MONTH(@EndDate),
					 @ShiftDate), 'dd/MM/yyyy') AS [Date]
					,ShiftName
					,CASE	WHEN CAST(LEFT(StartTime, 2) AS INT) = 0 THEN '12' + RIGHT(LEFT(StartTime, 5), 3) + ' AM'
							WHEN CAST(LEFT(StartTime, 2) AS INT) < 12 THEN LEFT(StartTime, 5) + ' AM'
							WHEN CAST(LEFT(StartTime, 2) AS INT) = 12 THEN LEFT(StartTime, 5) + ' PM'
							ELSE RIGHT(CONCAT('0', CAST(CAST(LEFT(StartTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(StartTime, 5), 3) + ' PM'
					 END AS StartTime
					,CASE	WHEN CAST(LEFT(EndTime, 2) AS INT) = 0 THEN '12' + RIGHT(LEFT(EndTime, 5), 3) + ' AM'
							WHEN CAST(LEFT(EndTime, 2) AS INT) < 12 THEN LEFT(EndTime, 5) + ' AM'
							WHEN CAST(LEFT(EndTime, 2) AS INT) = 12 THEN LEFT(EndTime, 5) + ' PM'
							ELSE RIGHT(CONCAT('0', CAST(CAST(LEFT(EndTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(EndTime, 5), 3) + ' PM'
						END AS EndTime
					,CASE	WHEN DATEDIFF(MINUTE, StartTime, EndTime) % 60 = 0 THEN 
							RIGHT('0' + CAST(DATEDIFF(HOUR, StartTime, EndTime) AS VARCHAR(2)), 2) + ':00 Hrs'
						ELSE RIGHT('0' + CAST(DATEDIFF(HOUR, StartTime, EndTime) AS VARCHAR(2)), 2) + ':' +
							RIGHT('0' + CAST(DATEDIFF(MINUTE, StartTime, EndTime) % 60 AS VARCHAR(2)), 2) + ' Hrs'
					END AS TotalHours
			FROM	(	SELECT	* FROM	[dbo].[EmployeeDetails] WHERE EmployeeId = @EmployeeId
					) AS ED
			LEFT JOIN	(	SELECT	* FROM	[dbo].[EmployeeShiftMappingDetails]
							WHERE	CONVERT(DATE, @date1) BETWEEN CONVERT(DATE, StartDate) AND CONVERT(DATE, EndDate)
						) AS ESMD
				ON	ED.EmployeeId =  ESMD.EmployeeId
			LEFT JOIN	[dbo].[ShiftDetails] SD
				ON	ESMD.ShiftId = SD.ShiftId;
		END
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeShiftMappingDetails]	@LoginUserId	= 1
													,@EmployeeId	= 1
													,@StartDate		= '2024-11-01'
													,@ShiftDate		= 26
													,@Status		= @S_Status		OUT
													,@Message		= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT	* 
	FROM	[dbo].[Employeedetails];

	SELECT	* 
	FROM	[dbo].[EmployeeShiftMappingDetails];

	SELECT	* 
	FROM	[dbo].[ShiftDetails];
	
==================================================================================================================*/
GO
