/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetEmployeeShiftTimeDetails]
 Description		:	Procedure used to retrive the Employee Shift Time For the Given @EmployeeId	
 Input Parameter	:	@LoginUserId, @EmployeeId				
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	29-03-2024
 Version			:	1.0 
 Comment			:	1.Get the Employee Shift Time Details for the Given @EmployeeId.
						2. Then Return the output parameter values @Status = 1 & @Message = NULL.
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeShiftTimeDetails]
(
	@LoginUserId		INT
	,@EmployeeId		INT
	,@Date				DATE 
	,@Status			BIT				OUT 
	,@Message			NVARCHAR(500)	OUT 
)
AS
BEGIN 
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	--DROP TABLE IF EXISTS Input
	--CREATE TABLE Input
	--(
	--	LoginUserId		INT
	--	,EmployeeId		INT
	--	,[Date]			DATETIME
	--	,CreatedTime	DATETIME
	--);
	--INSERT INTO Input(LoginUserId, EmployeeId, [Date], CreatedTime)
	--VALUES		(@LoginUserId	
	--			 ,@EmployeeId	
	--			 ,@Date	
	--			 ,GETDATE());

	BEGIN TRY
		BEGIN 
			SELECT	ISNULL(FORMAT(CONVERT(DATETIME, StartTime), 'hh:mm tt'), '') AS StartTime
					,ISNULL(FORMAT(CONVERT(DATETIME, EndTime), 'hh:mm tt'), '') AS EndTime
			FROM	(
						SELECT	SD.ShiftId
								,ESMD.EmployeeId
								,ESMD.StartDate
								,StartTime
								,EndTime
								,ESMD.EndDate
								,ROW_NUMBER() OVER (PARTITION BY ESMD.EmployeeId ORDER BY ESMD.EmployeeShiftMappingId DESC) AS RowNum
						FROM	[dbo].[ShiftDetails] SD
						LEFT JOIN [dbo].[EmployeeShiftMappingDetails] ESMD
							ON	SD.ShiftId = ESMD.ShiftId
						WHERE	ESMD.EmployeeId = @EmployeeId
						-- AND		@Date BETWEEN  ESMD.StartDate AND ESMD.EndDate 
						AND		CONVERT(DATE,@Date) BETWEEN CONVERT(DATE,ESMD.StartDate) AND CONVERT(DATE,ESMD.EndDate)
				) AS A
			WHERE	RowNum = 1
		END 
		SELECT	@Status		= 1 
				,@Message	= NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeShiftTimeDetails]	@LoginUserId	= 1
													,@EmployeeId	= 1
													,@Date			= '2024-11-22 18:30:00.000'
													,@Status		= @Status   OUT
													,@Message		= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[EmployeeDetails];
	
	SELECT	*
	FROM	[dbo].[ShiftDetails];

	SELECT	*
	FROM	[dbo].[EmployeeShiftMappingDetails];

========================================================================================================================================*/
GO
