/*===============================================================================================================================  
 Procedure Name		:	[USP_GetEmployeeTypeStructureMappingDetails]
 Description		:	Procedure used to retrive the EmployeeTypeStructureMappingDetails
 Input Parameter	:	@LoginUserId, @SalaryStructureId
 Output Parameters	:	@Status, @Message
 Author				:	Tharani.T
 Created on			:	04-10-2024
 Version			:	1.0 
 Comment			:	1. Get the EmployeeTypeStructureMappingDetails.
=================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetEmployeeTypeStructureMappingDetails]
(
	@LoginUserId						INT
	,@EmployeeTypeStructureMappingId	INT
	,@status							BIT				OUT
	,@Message							NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		IF @EmployeeTypeStructureMappingId IS NULL
		BEGIN
			SELECT	EmployeeTypeStructureMappingId
					,EmployeeType AS [Type]
					,SalaryStructureName AS [Name]
			FROM	[dbo].[EmployeeTypeStructureMappingDetails] ETMD
			JOIN	[dbo].[SalaryStructureDetails] SSD
				ON	ETMD.SalaryStructureId = SSD.SalaryStructureId
			JOIN	[dbo].[EmployeeTypeDetails] ETD
				ON	ETMD.EmployeeTypeId = ETD.EmployeeTypeId
			WHERE	SSD.CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			
			SELECT	EmployeeTypeStructureMappingId
					,EmployeeTypeId 
					,ETMD.SalaryStructureId
					,SSD.SalaryStructureName
			FROM	[dbo].[EmployeeTypeStructureMappingDetails] ETMD
			JOIN	[dbo].[SalaryStructureDetails] SSD
				ON	ETMD.SalaryStructureId = SSD.SalaryStructureId
			WHERE	EmployeeTypeStructureMappingId = @EmployeeTypeStructureMappingId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetEmployeeTypeStructureMappingDetails]	@LoginUserId						= 1
															,@EmployeeTypeStructureMappingId	= null
															,@Status							= @S_Status  OUT
															,@Message							= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[SalaryComponentsDetails];

======================================================================================================================*/

GO
