/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetInterviewScheduleCandidateDetails]
 Description		:	Procedure used to retrieve the InterviewScheduleCandidateDetails
											(1.When Click on the InterviewScheduleDetails tab in Candidate screen)
 Input Parameter	:	@LoginUserId, @CandidateId
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. Get the InterviewScheduleCandidateDetails table have the columns of InterviewScheduleCandidateId
							,InterviewType, InterviewDate, StartTime, TotalDuration, Evaluation
							,EvaluatorId, InterviewScheduleStatusId, InterviewDescription for the given @CandidateId.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetInterviewScheduleCandidateDetails]
(	
	@LoginUserId		INT
	,@CandidateId		INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		SELECT	CandidateStatusId
		FROM	[dbo].[CandidateDetails] CD
		JOIN	[dbo].[JobCreationDetails] JCD
			ON	JCD.JobCreationId = CD.JobCreationId
		LEFT JOIN	[dbo].[BranchDetails] BD
			ON	JCD.HiringLocationId = BD.BranchId
		WHERE	CandidateId = @CandidateId;

		SELECT	InterviewScheduleCandidateId
				,InterviewType
				,CONVERT(NVARCHAR(50),InterviewDate,105) AS InterviewDate 
				,StartTime
				,TotalDuration
				,InterviewLocationId
				,InterviewURL
				,InterviewDescription
				,Evaluation
				,EvaluatorId
				,InterviewScheduleStatusId
				,ApproverComments
				,ISCD.CandidateId
				,RowNumber
				,IsEmailSended
		FROM	[dbo].[InterviewScheduleCandidateDetails] ISCD
		JOIN	[dbo].[CandidateDetails] CD
			ON	ISCD.CandidateId = CD.CandidateId
		JOIN	[dbo].[JobCreationDetails] JCD
			ON	JCD.JobCreationId = CD.JobCreationId
		LEFT JOIN	[dbo].[BranchDetails] BD
			ON	JCD.HiringLocationId = BD.BranchId
		WHERE	ISCD.CandidateId = @CandidateId;

		SELECT	InterviewLevelMainInterviewerMappingId
				,InterviewScheduleCandidateId
				,MainInterviewerId
				,CandidateId
				,RowNumber
		FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails]
		WHERE	CandidateId = @CandidateId;

		SELECT	InterviewLevelSubInterviewerMappingId
				,InterviewScheduleCandidateId
				,SubInterviewerId
				,CandidateId
				,RowNumber
		FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails]
		WHERE	CandidateId = @CandidateId;

		SELECT	CandidateDocumentMappingId
				,IDD.InterviewDocumentId
				,DucumentName
				,DucumentFormat
				,CandidateId
				,DucumentFileName
				,DucumentFilePath
				,CASE WHEN IDD.InterviewDocumentId = 1 THEN 1 ELSE ISNULL(CDD.IsActive,0) END AS IsActive
		FROM	[dbo].[InterviewDocumentDetails] IDD
		LEFT JOIN (	SELECT * FROM [dbo].[CandidateDocumentMappingDetails] WHERE	CandidateId = @CandidateId) AS CDD
			ON	IDD.InterviewDocumentId = CDD.InterviewDocumentId;

		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetInterviewScheduleCandidateDetails]	@LoginUserId		= 1
															,@CandidateId		= 1
															,@Status			= @Status   OUT
															,@Message			= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[JobCreationDetails];
	SELECT	*
	FROM	[dbo].[CandidateDetails];
========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetInterviewScheduleEmailDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================
 Procedure Name 	:   [dbo].[USP_GetInterviewScheduleEmailDetails]
 Description		:	Procedure used to retrive the InterviewScheduleEmailDetails
																	(When click on the Email button InterviewSchedule screen)
 Input Parameter	:	@LoginUserId, @InterviewScheduleId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	12-02-2025
 Version			:	1.0 
 Comment			:	1. Get the interviewer & CandidateDetails for the Given @InterviewScheduleId.
						2. Then return the output Parameters values as @Status=1 and @Message = NULL.
==============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetInterviewScheduleEmailDetails]
(	
	@LoginUserId						INT
	,@InterviewScheduleCandidateId		INT
	,@IsEmailSended						BIT
	,@Status							BIT				OUT	
	,@Message							NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	 
	BEGIN TRY
		IF @InterviewScheduleCandidateId IS NULL 
		BEGIN 
			 SELECT	ISCD.InterviewScheduleCandidateId
					,MailTemplateType
					,MailTemplateContent
					,FirstName AS CandidateName
					,CD.Email AS CandidateEmail
					,InterviewType
					,CONVERT(NVARCHAR(50),InterviewDate,105) AS InterviewDate
					,StartTime
					,TotalDuration
					,CASE WHEN InterviewType = 'Face to Face' THEN BranchName ELSE InterviewURL END AS InterviewLocation
					,MainInterViewerEmail
					,SubInterViewerEmail  
			 FROM	MailTemplateDetails MTD
			 JOIN	[dbo].[CandidateDetails] CD
				ON	MTD.CompanyId = CD.CompanyId
			 JOIN	[dbo].[InterviewScheduleCandidateDetails] ISCD
				ON	CD.CandidateId = ISCD.CandidateId
			 JOIN	(	SELECT	InterviewScheduleCandidateId
								,STRING_AGG(ED.OfficialEmail,', ') AS MainInterViewerEmail
						FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails] MLID
						JOIN	EmployeeDetails ED
							ON	MLID.MainInterviewerId = ED.EmployeeId
						GROUP BY InterviewScheduleCandidateId
					) AS MLID
				ON	MLID.InterviewScheduleCandidateId = ISCD.InterviewScheduleCandidateId
			 JOIN	(	SELECT	InterviewScheduleCandidateId
								,STRING_AGG(ED1.OfficialEmail,', ') AS SubInterViewerEmail  
						FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails] SLID
						 JOIN	EmployeeDetails ED1
							ON	SLID.SubInterviewerId = ED1.EmployeeId
						GROUP BY InterviewScheduleCandidateId
					) AS SLID
				ON	SLID.InterviewScheduleCandidateId = ISCD.InterviewScheduleCandidateId
			 JOIN	[dbo].[BranchDetails] BD
				ON	BD.BranchId = ISCD.InterviewLocationId
			WHERE	IsEmailSended = 0
			AND		MailTemplateType = 'Interview Mail';

			SELECT	Email
					,SMTPNumber
			FROM	NoticationCategoryDetails
			WHERE	NoticationCategoryName = 'Email';

			IF @InterviewScheduleCandidateId = NULL
			BEGIN 
				UPDATE	[dbo].[InterviewScheduleCandidateDetails] 
				SET		IsEmailSended = 1;
			END 
		END 
		ELSE 
		BEGIN
			 SELECT	ISCD.InterviewScheduleCandidateId
					,MailTemplateType
					,MailTemplateContent
					,FirstName AS CandidateName
					,CD.Email AS CandidateEmail
					,InterviewType
					,CONVERT(NVARCHAR(50),InterviewDate,105) AS InterviewDate
					,StartTime
					,TotalDuration
					,CASE WHEN InterviewType = 'Face to Face' THEN BranchName ELSE InterviewURL END AS InterviewLocation
					,MainInterViewerEmail
					,SubInterViewerEmail  
			 FROM	MailTemplateDetails MTD
			 JOIN	[dbo].[CandidateDetails] CD
				ON	MTD.CompanyId = CD.CompanyId
			 JOIN	(	SELECT	CandidateId, InterviewScheduleCandidateId, InterviewLocationId, IsEmailSended, InterviewType
								,InterviewDate, StartTime, TotalDuration, InterviewURL
						FROM	[dbo].[InterviewScheduleCandidateDetails] 
						WHERE	InterviewScheduleCandidateId = @InterviewScheduleCandidateId
					) AS ISCD
				ON	CD.CandidateId = ISCD.CandidateId
			 JOIN	(	SELECT	InterviewScheduleCandidateId
								,STRING_AGG(ED.OfficialEmail,', ') AS MainInterViewerEmail
						FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails] MLID
						JOIN	EmployeeDetails ED
							ON	MLID.MainInterviewerId = ED.EmployeeId
						GROUP BY InterviewScheduleCandidateId
					) AS MLID
				ON	MLID.InterviewScheduleCandidateId = ISCD.InterviewScheduleCandidateId
			 JOIN	(	SELECT	InterviewScheduleCandidateId
								,STRING_AGG(ED1.OfficialEmail,', ') AS SubInterViewerEmail  
						FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails] SLID
						 JOIN	EmployeeDetails ED1
							ON	SLID.SubInterviewerId = ED1.EmployeeId
						GROUP BY InterviewScheduleCandidateId
					) AS SLID
				ON	SLID.InterviewScheduleCandidateId = ISCD.InterviewScheduleCandidateId
			 JOIN	[dbo].[BranchDetails] BD
				ON	BD.BranchId = ISCD.InterviewLocationId
			WHERE	IsEmailSended = 0
			AND		MailTemplateType = 'Interview Mail';
			
			SELECT	Email
					,SMTPNumber
			FROM	NoticationCategoryDetails
			WHERE	NoticationCategoryName = 'Email';

			IF @IsEmailSended = 1
			BEGIN 
				UPDATE	[dbo].[InterviewScheduleCandidateDetails] 
				SET		IsEmailSended = @IsEmailSended
				WHERE	InterviewScheduleCandidateId = @InterviewScheduleCandidateId;
			END 
		END  
		SELECT	@Status   = 1 
				,@Message = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)

	EXEC [dbo].[USP_GetInterviewScheduleEmailDetails]	@LoginUserId						= 1
														,@InterviewScheduleCandidateId		= null
														,@IsEmailSended						= 0
														,@Status							= @S_Status		OUT
														,@Message							= @M_Message	OUT

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[InterviewScheduleCandidateDetails];	
==================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetJobCreationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_GetJobCreationDetails]
 Description		:	Procedure used to retrive the JobCreationDetails
														(1.When Click on the JobCreation in side navigation bar 
														 2.When click Edit option in grid from JobCreation Screen)
 Input Parameter	:	@LoginUserId, @JobCreationId				
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @JobCreationId IS NULL, then
							1.1 To show the counter box values 
									1. @Total AS Total
									2. @Open AS Open
									3. @Closed AS Closed
									4. @Completed AS Completed to show the values in Counter Box.
							1.2 Get the JobCreationDetails table have the columns of JobCreationId, JobId, JobPostType
								,JobName, JobCategory, EmployeeType, Department, HiringLocation, HiringManager 
								,NoOfOpening, OpeningDate, ExpiryDate, SalaryRange, Experience to show the values 
								in Grid.
							1.3 Then return the output parameter values @Status = 1 & @Message = NULL.
						2. If the Given @JobCreationId IS NOT NULL, then
							2.1 Get the JobCreationDetails table have the columns of JobCreationId, JobId, JobPostType
								,JobName, JobCategoryId, EmploymentTypeId, DepartmentId, PrimarySkill, SecondarySkill
								,HiringLocationId, HiringManagerId, NoOfOpening, OpeningDate, ExpiryDate, SalaryMinRange
								,SalaryMaxRange, MinExperience, MaxExperience, JobCreationStatusId, JobCreationDescription
								,JobCreationSkillSet for the Given @JobCreationId to show the values in update Popup.
							2.2 Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetJobCreationDetails]
(	
	@LoginUserId		INT
	,@JobCreationId		INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@Total			INT
			,@Open			INT
			,@OnHold		INT
			,@Closed		INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @JobCreationId IS NULL 
		BEGIN 
			SELECT	@Total = COUNT(JobCreationId)
			FROM	[dbo].[JobCreationDetails]
			WHERE	CompanyId = @CompanyId;
			
			SELECT	@Open = COUNT(JobCreationId)
			FROM	[dbo].[JobCreationDetails]
			WHERE	CompanyId = @CompanyId
			AND		JobCreationStatusId = 1;
			
			SELECT	@OnHold = COUNT(JobCreationId)
			FROM	[dbo].[JobCreationDetails]
			WHERE	CompanyId = @CompanyId
			AND		JobCreationStatusId = 2;
			
			SELECT	@Closed = COUNT(JobCreationId)
			FROM	[dbo].[JobCreationDetails]
			WHERE	CompanyId = @CompanyId
			AND		JobCreationStatusId = 3;

			-- Result set for Counter Boxes.
			SELECT	@Total			AS	Total
					,@Open			AS	[Open]
					,@OnHold		AS	[On-Hold]
					,@Closed		AS	Closed;

			-- Resultset for Grid.
			SELECT	JCD.JobCreationId
					,JobCategoryName AS JobCategory
					,JobStatusName AS [Status]
					,CASE	WHEN JobCreationStatusId = 1 THEN 'Green'
							WHEN JobCreationStatusId = 2 THEN 'Orange'
							WHEN JobCreationStatusId = 3 THEN 'Red'
						ELSE 'Blue'
					END AS Status_Colour
					,'White' AS TextColour
					,JobName
					,JobPostType
					,CONVERT(NVARCHAR(50),OpeningDate,106) AS OpeningDate
					,CONVERT(NVARCHAR(50),ExpiryDate,106) AS ExpiryDate
					,CONCAT(NoOfOpening,' / ',ISNULL(TotalHired,0)) AS TotalHired
			FROM	[dbo].[JobCreationDetails] JCD
			LEFT JOIN	(	SELECT	JobCreationId
									,COUNT(ISNULL(CandidateId,0)) AS TotalHired
							FROM	[dbo].[CandidateDetails] 
							WHERE	CompanyId = @CompanyId
							GROUP BY JobCreationId
						) AS CD
				ON	CD.JobCreationId = JCD.JobCreationId
			JOIN	[dbo].[JobCategoryDetails] JCDG
				ON	JCD.JobCategoryId = JCDG.JobCategoryId
			JOIN	[dbo].[JobStatusDetails] JSD
				ON	JCD.JobCreationStatusId = JSD.JobStatusId
			WHERE	JCD.CompanyId = @CompanyId
			ORDER BY JCD.JobCreationId DESC;
		END 
		ELSE 
		BEGIN
			-- Result set for Not Null.
			SELECT	JobCreationId
					,JobId
					,JobPostType
					,JobName
					,JobCategoryId
					,EmploymentTypeId
					,DepartmentId
					,PrimarySkill
					,SecondarySkill
					,HiringLocationId
					,HiringManagerId
					,NoOfOpening
					,CONVERT(NVARCHAR(50),OpeningDate,105) AS OpeningDate
					,CONVERT(NVARCHAR(50),ExpiryDate,105) AS ExpiryDate
					,SalaryMinRange
					,SalaryMaxRange
					,MinExperience
					,MaxExperience
					,JobCreationStatusId
					,JobCreationDescription
					,JobCreationSkillSet
			FROM	[dbo].[JobCreationDetails]
			WHERE	CompanyId = @CompanyId
			AND		JobCreationId = @JobCreationId;
		END 
		SELECT	 @Status   = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*========================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetJobCreationDetails]	@LoginUserId		= 1
											,@JobCreationId		= NULL
											,@Status			= @Status   OUT
											,@Message			= @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[JobCreationDetails];
========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetLeaveDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==============================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetLeaveDetails]
 Description		:	Procedure used to retrieve the LeaveDetails(1.When click on the Leave in Side NavigationBar).
																  (2.when click on Edit option in Grid in Leave Screen).
 Input Parameter	:	@LoginUserId,@LeaveId,@FromDate,@ToDate
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	23-08-2023
 Version			:	1.0 
 Comments			:	1.If the given @LeaveId is NULL, 
						  1.1 When @UserGroupId Is an SuperAdmin(1)
							1.1.1 Get the Counter Boxes have the Column of 
											@TotalEmployees		AS TotalEmployees
											,@TodayPresents		AS TodayPresents
											,@PlannedLeaves		AS PlannedLeaves
											,@UnPlannedLeaves	AS UnPlannedLeaves
											,@PendingRequest	AS PendingRequest for the given @UserGroupId,FromDate and ToDate.
							1.1.2 Then, Get All the LeaveDetails have the column of LeaveId,EmployeeId,EmployeeImage,Employee,Designation,LeaveType,From,
									To,NoOfDays,Reason,LeaveStatusId,Status,Status_Colour,ApprovedPersonImage,ApprovedBy to show in Grid.
							1.1.3 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						  1.2 When @UserGroupId Is an GeneralUser(2,3),then 
							1.2.1 Get the Counter Boxes have the Column of 
											@TotalAnnualLeave	AS TotalAnnualLeave
											,@AnnualLeave		AS AnnualLeave
											,@TotalMedicalLeave AS TotalMedicalLeave
											,@MedicalLeave		AS MedicalLeave
											,@TotalOtherLeave	AS TotalOtherLeave
											,@OtherLeave		AS OtherLeave
											,@PendingLeave		AS PendingLeave for the given FromDate and ToDate.
							1.2.2 Then,Get All the Leavedetails have the column of LeaveId,LeaveType,From,To,NoOfDays,Reason,Status,Status_Colour,ApprovedPersonImage,ApprovedBy
									for the given @UserGroupId and FromDate and ToDate to show in Grid.
							1.2.3 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2.If the given @LeaveId is NOT NULL,then 
						  2.1 Get the Leavedetails have the column of LeaveId,EmployeeId,EmployeeName,LeaveTypeId,LeaveTypeName,FromDate,ToDate,IsHalfDay,NoOfDays,
						      RemainingLeaves,LeaveStastusId,LeaveStatusName,LeaveDescription for the given LeaveId and FromDate and ToDate to show in popup.
						  2.2 Then return the output Parameter values as @Status = 1 and Message = NULL.	
================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetLeaveDetails]
(
	@LoginUserId	INT
	,@LeaveId		INT
	,@FromDate		DATE
	,@Mine			BIT
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE	@CompanyId					TINYINT
			,@UserGroupId				TINYINT
			,@EmployeeId				INT
			,@TotalSickLeaveCount		INT
			,@TotalCasualLeaveCount		INT
			,@TotalOtherLeaveCount		INT
			,@PendingLeaveRequest		INT
			,@SickLeave					INT
			,@CasualLeave				INT 
			,@OtherLeave				INT
			,@ToDate					DATE;

	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--If the given @LeaveId is NULL
		IF @LeaveId IS NULL
		BEGIN
			--Logic for AnnualLeave
			SELECT	@SickLeave = ISNULL(COUNT(EmployeeId),0)
			FROM	[dbo].[LeaveDetails] LD
			JOIN	[dbo].[LeaveTypeDetails] LTD 
				ON	LD.LeaveTypeId = LTD.LeaveTypeId
			WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
			AND		(LeaveTypeName = 'Sick Leave' 
			OR		LeaveTypeName = 'SickLeave')
			AND		EmployeeId = @LoginUserId
			AND		LD.CompanyId = @CompanyId; 

			--Logic for MedicalLeave
			SELECT	@CasualLeave = ISNULL(COUNT(EmployeeId),0)
			FROM	[dbo].[LeaveDetails] LD
			JOIN	[dbo].[LeaveTypeDetails] LTD 
				ON	LD.LeaveTypeId = LTD.LeaveTypeId
			WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate 
			AND		(LeaveTypeName = 'Casual Leave' 
			OR		LeaveTypeName = 'CasualLeave') 
			AND		EmployeeId = @LoginUserId
			AND		LD.CompanyId = @CompanyId;

			--Logic for OtherLeave	
			SELECT	@OtherLeave = ISNULL(COUNT(EmployeeId),0)
			FROM	[dbo].[LeaveDetails]
			WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
			AND		LeaveTypeId NOT IN (1, 2, 3, 4)
			AND		EmployeeId = @LoginUserId
			AND		CompanyId = @CompanyId;

			--Logic for PendingLeave
			SELECT	@PendingLeaveRequest = ISNULL(COUNT(EmployeeId),0) 
			FROM	[dbo].[LeaveDetails] LD  
			WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
			AND		LeavestatusId = 2 
			AND		EmployeeId = @LoginUserId
			AND		LD.CompanyId = @CompanyId;

			-- Resultset for Employee CounterBox
			SELECT	@SickLeave					AS 'Sick Leave'
					,@CasualLeave				AS 'Causal Leave'
					,@OtherLeave				AS 'Other Leave'
					,@PendingLeaveRequest		AS 'Pending Leave'

			IF @UserGroupId IN (1,2)
			BEGIN
				IF @Mine = 1
				BEGIN
					SELECT	LD.LeaveId
							,LeaveTypeName AS LeaveType 
							,CONVERT(NVARCHAR(50),LD.FromDate,113) AS [From]
							,CONVERT(NVARCHAR(50),LD.ToDate,113) AS [To]
							,CONCAT(CASE	WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END,
									CASE	WHEN FromDate = ToDate THEN ' Day' 
											WHEN FromDate != ToDate  THEN ' Days'
									ELSE 'HalfDay' END ) AS NoOfDays 
							,LSD.LeaveStatusId AS StatusId
							,LeaveStatusName AS [Status]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(LVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN (3,4,5,6,7) THEN CONCAT(LVD.FirstName,' ',LVD.LastName)
									ELSE ' ' 
								END AS ApprovedBy 
							,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
								ELSE 'Yellow'
							END AS Status_Colour
					FROM	[dbo].[LeaveDetails] LD
					JOIN	[dbo].[Employeedetails] ED
						ON	LD.EmployeeId = ED.EmployeeId 
					LEFT JOIN [dbo].[DesignationDetails] DD
						ON	ED.DesignationId = DD.DesignationId 
					LEFT JOIN [dbo].[LeaveTypeDetails] LTD
						ON	LD.LeaveTypeId = LTD.LeaveTypeId
					LEFT JOIN [dbo].[LeaveStatusDetails] LSD
						ON	LD.LeaveStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	LeaveId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[LeaveDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
								WHERE	LD.CompanyId = @CompanyId 
							) AS LVD
						ON	LVD.LeaveId = LD.LeaveId
					WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
					AND		LD.EmployeeId = @LoginUserId
					AND		LD.CompanyId = @CompanyId
					ORDER BY LD.LeaveId DESC;  
				END 
				ELSE
				BEGIN
					SELECT	LD.LeaveId
							,RPD.EmployeeId
							,RPD.EmployeeImage AS EmpImage
							,Employee
							,DD.DesignationName AS Designation
							,LTD.LeaveTypeName AS LeaveType
							,CONVERT(NVARCHAR(50),LD.FromDate,113) AS [From]
							,CONVERT(NVARCHAR(50),LD.ToDate,113) AS [To]
							,CONCAT(CASE	WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END,
									CASE	WHEN FromDate = ToDate	THEN ' Day' 
											WHEN FromDate != ToDate	THEN ' Days'
									ELSE 'HalfDay' END ) AS NoOfDays 
							,LSD.LeaveStatusId  AS StatusId
							,LeaveStatusName AS [Status]
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(LVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
							,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(LVD.FirstName,' ',LVD.LastName)
									ELSE ' ' 
								END AS ApprovedBy 
							,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
									WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
									WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
									WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
								ELSE 'Orange'
							END AS [Status_Colour]
					FROM	[dbo].[LeaveDetails] LD
					JOIN	(	SELECT	ED.DesignationId, ED.EmployeeId, ED.EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee 
								FROM	[dbo].[Employeedetails] ED
								LEFT JOIN	[dbo].[Employeedetails] RPD
									ON	RPD.EmployeeId = ED.EmployeeId 
								WHERE	ED.ReportingPersonId = @LoginUserId
							) AS RPD
						ON	LD.EmployeeId = RPD.EmployeeId
					LEFT JOIN [dbo].[DesignationDetails] DD
						ON	RPD.DesignationId = DD.DesignationId 
					LEFT JOIN [dbo].[LeaveTypeDetails] LTD
						ON	LD.LeaveTypeId = LTD.LeaveTypeId
					LEFT JOIN [dbo].[LeaveStatusDetails] LSD
						ON	LD.LeaveStatusId = LSD.LeaveStatusId
					LEFT JOIN (	SELECT	LeaveId, EmployeeImage, FirstName, LastName
								FROM	[dbo].[LeaveDetails] LD
								JOIN	[dbo].[Employeedetails] ED
									ON	LD.UpdatedBy = ED.EmployeeId 
								WHERE	LD.CompanyId = @CompanyId 
							) AS LVD
						ON	LVD.LeaveId = LD.LeaveId
					WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
					AND		LD.CompanyId = @CompanyId 
					AND		LD.LeaveStatusId IN (2,3,4)
					ORDER BY LD.LeaveId DESC;
				END 
			END
			ELSE
			BEGIN
				--Resultset for EmployeeGrid.
				SELECT	LD.LeaveId
						,LeaveTypeName AS LeaveType 
						,CONVERT(NVARCHAR(50),LD.FromDate,113) AS [From]
						,CONVERT(NVARCHAR(50),LD.ToDate,113) AS [To]
						,CONCAT(CASE	WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END,
								CASE	WHEN FromDate = ToDate THEN ' Day' 
										WHEN FromDate != ToDate  THEN ' Days'
								ELSE 'HalfDay' END ) AS NoOfDays
						,LSD.LeaveStatusId AS StatusId
						,LeaveStatusName AS [Status]
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(LVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(LVD.FirstName,' ',LVD.LastName)
								ELSE ' ' 
						 END AS ApprovedBy 
						,CASE	WHEN LSD.LeaveStatusName = 'Draft'		THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Submitted'	THEN 'Orange'
								WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
								WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
								WHEN LSD.LeaveStatusName = 'Cancelled'	THEN 'Black'
						 ELSE 'Yellow'
						 END AS Status_Colour
				FROM	[dbo].[LeaveDetails] LD
				JOIN	[dbo].[Employeedetails] ED
					ON	LD.EmployeeId = ED.EmployeeId 
				LEFT JOIN [dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId 
				LEFT JOIN [dbo].[LeaveTypeDetails] LTD
					ON	LD.LeaveTypeId = LTD.LeaveTypeId
				LEFT JOIN [dbo].[LeaveStatusDetails] LSD
					ON	LD.LeaveStatusId = LSD.LeaveStatusId
				LEFT JOIN (	SELECT	LeaveId, EmployeeImage, FirstName, LastName
							FROM	[dbo].[LeaveDetails] LD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	LD.UpdatedBy = ED.EmployeeId 
							WHERE	LD.CompanyId = @CompanyId 
						) AS LVD
					ON	LVD.LeaveId = LD.LeaveId
				WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
				AND		LD.EmployeeId = @LoginUserId
				AND		LD.CompanyId = @CompanyId
				ORDER BY LD.LeaveId DESC;  
			END
		END
		ELSE
		BEGIN
			--If the given @LeaveId is NOT NULL
			SELECT	LD.LeaveId
					,ED.EmployeeId
					,ISNULL(CONCAT(FirstName,' ',LastName),0) AS EmployeeName
					,LTD.LeaveTypeId
					,LeaveTypeName
					,CONVERT(NVARCHAR(50),LD.FromDate,105) AS FromDate
					,CONVERT(NVARCHAR(50),LD.ToDate,105) AS ToDate 
					,LD.IsHalfDay
					,IsFirstHalf
					,CASE	WHEN LD.NoOfDays = 1 THEN CONCAT(LD.NoOfDays,' Day')
							WHEN IsHalfDay = 1 THEN CONCAT(LD.NoOfDays,' Day')
						ELSE  CONCAT(LD.NoOfDays,' Days')
					END AS NoOfDays
					,LD.LeaveStatusId 
					,LSD.LeaveStatusName
					,ISNULL(LD.LeaveDescription,' ') AS LeaveDescription 
					,CONVERT(NVARCHAR(50),LD.CreatedDate,105) AS CreatedDate
					,ISNULL(LD.Comments,' ') AS Comments
			FROM	[dbo].[LeaveDetails] LD
			JOIN	[dbo].[Employeedetails] ED
				ON	LD.EmployeeId = ED.EmployeeId 
			LEFT JOIN [dbo].[DesignationDetails] DD
				ON	ED.DesignationId = DD.DesignationId 
			JOIN [dbo].[LeaveTypeDetails] LTD
				ON	LD.LeaveTypeId = LTD.LeaveTypeId
			LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	LD.LeaveStatusId = LSD.LeaveStatusId
			LEFT JOIN	[dbo].[CompanySettingDetails] CSD
				ON	LD.CompanyId = CSD.CompanyId
			WHERE  LD.LeaveId = @LeaveId 
			AND		LD.CompanyId = @CompanyId;
 		END
		SELECT	 @Status   = 1 
				,@Message  = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0	
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*=====================================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetLeaveDetails]	@LoginUserId	 = 1
										,@LeaveId        = null
										,@FromDate       = '2024-10-01'
										,@Mine			 = 0
										,@Status		 = @Status   OUT
										,@Message		 = @Message  OUT;
  
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[LeaveStatusDetails];
	SELECT	*
	FROM	[dbo].[LeaveDetails];
	SELECT * 
	FROM [CompanySettingDetails]
	SELECT * 
	FROM DesignationDetails
	SELECT * 
	FROM EmployeeDetails
	SELECT	*
	FROM	[dbo].[LeaveTypeDetails];
========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetleavetypeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=====================================================================================================================================
 Procedure Name		:   [USP_GetleavetypeDetails]
 Description		:	Procedure used to retrive the Leavetypedetails(When click on the Settings in SideNavigationBar 
						and When Click On Edit Option On Grid from UI)      
 Input Parameter	:	@LoginUserId, @LeavetypeId							
 Output Parameters	:	@Status, @Message									
 Author				:	Dharani.M
 Created on			:	27-11-2023
 Version			:	1.0 
 Comment			:	1.Declare the CompanyId to get CompanyId for Given LoginUserID to use Where Conditions.
						2.If the LeaveTypeId Is Null,
						    2.1 Get All the LeaveTypeDetails have the column of LeaveTypeId,LeaveTypeName,CompanyId.
							2.2 Then return the output Parameters values as @Status=1 and @Message = NULL.
						3.If the LeaveTypeId Is Not Null, 
						    3.1 Get the Leavetypedetails have the column of LeaveTypeId,LeaveTypeName,CompanyId with given LeaveTypeId.
							3.2 Then return the output Parameters values as @Status=1 and @Message = NULL.
========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetleavetypeDetails]
(	
	 @LoginUserId	INT
	,@LeavetypeId	TINYINT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;
	   
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

    BEGIN TRY	
		IF @LeaveTypeId IS NULL	
		BEGIN
			SELECT	LTD.LeavetypeId
					,LeaveTypeName As LeaveName
					,LeaveTypeDescription AS [Description]
			FROM	[dbo].[LeaveTypeDetails] LTD
			WHERE	LTD.CompanyId = @CompanyId
			ORDER BY LTD.LeavetypeId DESC;
			--SELECT	LTD.LeavetypeId
			--		,GradeTypeName AS Grade
			--		,LeaveTypeName As LeaveName
			--		,LeavePeriod
			--		,CASE WHEN IsCarryForward = 1 THEN 'Yes' ELSE 'No' END AS IsCarryFwd
			--		,CASE	WHEN ISNULL(LeaveCount,0) = 1 AND LeaveTypeName <> 'Permission' THEN '1 Day'
			--				WHEN ISNULL(LeaveCount,0) > 1 AND LeaveTypeName <> 'Permission' THEN CONCAT( ISNULL(LeaveCount,0), ' Days')
			--				WHEN LeaveTypeName = 'Permission' THEN CONCAT(ISNULL(LeaveCount,0), ' Hours')
			--			ELSE ''
			--		END AS NoOfDays
			--FROM	[dbo].[LeaveTypeDetails] LTD
			--LEFT JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
			--	ON	LTD.LeaveTypeId = LTGMD.LeaveTypeId
			--LEFT JOIN	[dbo].[GradeTypeDetails] GTD
			--	ON	LTGMD.GradeTypeId = GTD.GradeTypeId
			--WHERE	LTD.CompanyId = @CompanyId
			--ORDER BY LTD.LeavetypeId DESC;
		END
		ELSE
		BEGIN
			SELECT	LeaveTypeId 
					,LeaveTypeName AS Leavetypename
					,LeaveTypeDescription
			FROM	[dbo].[LeaveTypeDetails]
			WHERE	LeaveTypeId = @LeaveTypeId 
			AND		CompanyId = @CompanyId;
		END
		SELECT	 @Status   = 1 
				,@Message  = NULL;
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
