		BEGIN
		SELECT	MailTemplateId
					,MailTemplateType
					,MailTemplateContent	
			FROM	[dbo].[MailTemplateDetails]
			WHERE	MailTemplateId = @MailTemplateId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
