/****** Object:  StoredProcedure [dbo].[USP_GetManualAttendanceDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==================================================================================================================================================
Procedure Name		: [USP_GetManualAttendanceDetails]
Description			: Procedure Will Retrieve the AttendanceLogDetail s
									1. (When Click On Add Manual in AttendanceLog (Admin) Screen.										
Input Parameters	: @LoginUserId, @PunchDate
Output Parameters	: @Status,@Message
Author				: Dharani.M
Created On			: 02-11-2023
Version				: 1.0
Comment				: 1.Get the Total AttendanceLogDetails have the Columns Of EmployeeId,PunchDate,EmployeeImage
						,EmployeeName,AttendanceStatusId,AttendanceStatusName,PunchIn,PunchOut,NoOfHours to show in Grid.
						1.1 Then Return the Output Parameters values @Status = 1, @Message = NULL.
=====================================================================================================================================================*/
CREATE PROCEDURE [dbo].[USP_GetManualAttendanceDetails]
(
	@LoginUserId	INT
	,@PunchDate		DATE
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;
			
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT  @Status   = 1 
				,@Message  = NULL;		

		--Get the Total AttendanceLogDetails to show in Grid.
		SELECT	DISTINCT ED.EmployeeId
				,ISNULL((CONVERT(NVARCHAR(50),PunchDate,113)),'') AS [Date]
				,ISNULL(EmployeeImage,' ') AS EmployeeImage
				,CONCAT(FirstName,' ',LastName) AS EmployeeName
				, CASE WHEN PunchIn IS NULL AND PunchOut IS NULL THEN 'Yet to Checkin'
						WHEN PunchIn IS NOT NULL AND PunchOut IS NOT NULL THEN 'CheckIn'
						WHEN PunchIn IS NOT NULL AND PunchOut IS NULL THEN 'CheckIn'
						ELSE ' ' END AS [Status]
				,ISNULL(FORMAT(PunchIn,'hh:mm tt'),'') AS PunchIn
				,ISNULL(FORMAT(PunchOut,'hh:mm tt'),'') AS PunchOut
				,LEFT(CONVERT(VARCHAR(20),ISNULL(CAST((ISNULL(PunchOut,GETDATE()) - PunchIn) as time(0)),'00:00:00')),5 ) + ' Hrs' AS NoOfHours
				,CASE WHEN PunchIn IS NULL AND PunchOut IS NULL THEN 'Orange'
					WHEN PunchIn IS NOT NULL AND PunchOut IS NOT NULL THEN 'Green'
					WHEN PunchIn IS NOT NULL AND PunchOut IS NULL THEN 'Green'
					ELSE 'Yellow' END AS  [Status_Colour]
		FROM	(SELECT	* FROM [dbo].[EmployeeDetails] WHERE CompanyId = @CompanyId) AS	ED
		LEFT JOIN   (SELECT	DISTINCT	T1.EmployeeId
										,AttendanceLogId
										,T1.AttendanceStatusId
										,PunchDate
										,(	SELECT  MIN(PunchTime) 
											FROM	[AttendanceLogDetails] IQ1
											WHERE	IQ1.EmployeeId = T1.EmployeeId 
											AND		IQ1.PunchDate =  T1.PunchDate
											AND		IQ1.[Status] = 1 
											AND		CompanyId = @CompanyId
										) AS PunchIn
										,(	SELECT	MAX(PunchTime)
											FROM	[AttendanceLogDetails] IQ2
											WHERE	IQ2.EmployeeID = T1.EmployeeId 
			   								AND		IQ2.PunchDate = T1.PunchDate
											AND		IQ2.[Status] = 0 
											AND		CompanyId = @CompanyId
										) AS PunchOut
					FROM	[dbo].[AttendanceLogDetails] AS T1
					WHERE	T1.CompanyId = @CompanyId
					AND		CONVERT(DATE,PunchDate) = CONVERT(DATE,@PunchDate)
					) IQ
		ON	ED.EmployeeId = IQ.EmployeeId
		ORDER BY EmployeeId ASC;		
	END TRY
	BEGIN CATCH
		   SELECT  @Status   = 0
				  ,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=================================================================================================================================
	DECLARE	 @Status	BIT 
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetManualAttendanceDetails]	@LoginUserId	= 41
												,@PunchDate		= '2024-04-03'
												,@Status		= @Status   OUT
												,@Message		= @Message  OUT;
										   
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[AttendanceLogDetails];
	
	SELECT	*
	FROM	[dbo].[EmployeeDetails];
===================================================================================================================================*/
GO
