/****** Object:  StoredProcedure [dbo].[USP_GetNotificationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*===========================================================================================================================================================================
 Procedure Name 	:   [USP_GetNotificationDetails]
 Description		:	Procedure used to retrive the CRM (When click on the CRM in Side NavigationBar 
						and When Click On Edit Option On Grid from UI)
 Input Parameter	:	@LoginUserId, @NotificationId
 Output Parameters	:	@Status, @Message
 Author				:	Dharani.M
 Created on			:	28-09-2023
 Version			:	1.0 
 Comment			:	1. If the given @NotificationId Is NULL,then
							1.1 Get all the Counter Box values with the Column of Total, Scheduled, Sent, Draft to Show in Counter Boxes.
							1.2 Get All the NotificationDetails with the column as NotificationId, Date, NotificationType, MessageTo, DeliveredTo, Status to show on the Grid.
						    1.3 Then return the output Parameter values as @Status = 1 and @Message = NULL.
	                    2. If the given @NotificationId Is NOT NULL, then 
						    2.1 Get the NotificationDetails with the column  of NotificationId, NotificationTypeName, IsInternal, MessageTo, DetailedMessage, MessageStatusId
								,MessageStatusName, ScheduledDate for the given @NotificationId to show the values in popup.
							2.2 Get the NotificationPersonMappingDetails with the column names as NotificationPersonMappingId, PersonId, PersonName, NotificationId for 
								the given @NotificationId to show the values in popup.
							2.3 Then return the output Parameter values as @Status = 1 and @Message = NULL.
=================================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetNotificationDetails]
(	
	@LoginUserId		INT
	,@NotificationId	INT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN      
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@Total			INT
			,@Scheduled		INT
			,@Sent			INT
			,@Draft			INT
			,@MessageTo		NVARCHAR(50);
				
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId; 

	SELECT	@MessageTo = MessageTo
	FROM	[dbo].[NotificationDetails]
	WHERE	NotificationId = @NotificationId 
	AND		CompanyId = @CompanyId;
	
	BEGIN TRY
		--Logic is used to move the record from main table to Temporary table.
		DROP TABLE IF EXISTS #NotificationDetails;

		SELECT	NotificationId, NotificationTypeName, IsInternal, MessageTo, DetailedMessage, 
				ND.MessageStatusId, MessageStatusName, ScheduledDate, IsAuto, ND.CreatedDate
		INTO	#NotificationDetails
		FROM	[dbo].[NotificationDetails] AS ND
		JOIN	[dbo].[MessageStatusDetails] AS MSD
			ON	ND.MessageStatusId = MSD.MessageStatusId		
		WHERE	IsAuto = 0 
		AND		ND.CompanyId = @CompanyId;

		--If the given @NotificationId IS NULL,then Get All the NotificationDetails 
		IF @NotificationId IS NULL
		BEGIN
			--Logic to Count total Notification (IsAuto = 0)
			SELECT	@Total = COUNT(ISNULL((NotificationId),0))
			FROM	#NotificationDetails;

			-- Logic For count of Scheduled Notification (IsAuto = 0)
			SELECT	@Scheduled = COUNT(ISNULL((NotificationId),0))
			FROM	#NotificationDetails 
			WHERE	MessageStatusName = 'Scheduled';
			
			-- Logic For count of Sent Notification (IsAuto = 0)
			SELECT	@Sent = COUNT(ISNULL((NotificationId),0))
			FROM	#NotificationDetails  
			WHERE	MessageStatusName = 'Sent';
			
			-- Logic For count of Draft Notification (IsAuto = 0)			
			SELECT	@Draft = COUNT(ISNULL((NotificationId),0))
			FROM	#NotificationDetails  
			WHERE	MessageStatusName = 'Draft';
						
			--Result Set For Counter Box.
			SELECT	@Total		AS Total
					,@Scheduled AS Scheduled
					,@Sent		AS [Sent]
					,@Draft		AS Draft;
									
			--Result set For Grid.
			SELECT	ND.NotificationId
					,CONVERT(VARCHAR(10),ND.CreatedDate,105) AS [Date]
					,ND.NotificationTypeName AS NotificationType
					,MessageTo
					,CASE WHEN NoOfPersons = 1  THEN 'Single Person'
						  WHEN NoOfPersons <> 1 THEN 'Many'
						ELSE '' 
					END AS DeliveredTo
					,MessageStatusName AS [Status]
			FROM	#NotificationDetails AS ND			
			LEFT JOIN	(	SELECT	NotificationId, COUNT(1) AS NoOfPersons 
							FROM	[dbo].[NotificationPersonMappingdetails]
							GROUP BY NotificationId
						) NPMD
				ON	ND.NotificationId = NPMD.NotificationId;
		END
		ELSE
		BEGIN	
			--If the given @NotificationId Is NOT NULL, then Get the Notificationdetails for the given @NotificationId
			SELECT	NotificationId
					,NotificationTypeName 
					,IsInternal
					,MessageTo				
					,DetailedMessage
					,MessageStatusId
					,MessageStatusName 
					,ScheduledDate
			FROM	#NotificationDetails ND
			WHERE	NotificationId = @NotificationId;
			
			IF @MessageTo = 'Employee'
			BEGIN
				--Get the NotificationPersonMappingdetails for the given @NotificationId	
				SELECT	NotificationPersonMappingId
						,PersonId 
						,CONCAT(FirstName,' ',LastName) AS PersonName
						,NPMD.NotificationId
				FROM	[dbo].[NotificationPersonMappingdetails] AS NPMD
				JOIN	[dbo].[EmployeeDetails] AS EPD
					ON	NPMD.PersonId = EPD.EmployeeId			
				WHERE	NotificationId = @NotificationId;
			END
		END
		SELECT	@Status		=  1 
				,@Message	= NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==========================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);
	
	EXEC [dbo].[USP_GetNotificationDetails]	@LoginUserId		= 1
											,@NotificationId	= 1039
											,@Status			= @S_Status		OUT
											,@Message			= @M_Message	OUT;
	
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

=============================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetNotificationDetails1]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===================================================================================================================================================
 Procedure Name 	:   [USP_GetNotificationDetails1]
 Description		:	Procedure used to retrive the NotificationDetails (When click on the Notification bell button in top of the screen  
 						and When Click On Particular Notification from UI)
 Input Parameter	:	@LoginUserId, @NotificationId
 Output Parameters	:	@Status, @Message
 Author				:	Dharani.M
 Created on			:	28-09-2023 
 Version			:	1.0 
 Comment			:	1. If the given @NotificationId is NULL,then 
 							1.1 Get all the NotificationDetails with the column of NotificationId,NotificationTypeName,DetailedMessage,CreationTime 
								to show in Grid.
 							1.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
 						2 If the given @NotificationId is NOT NULL,then
 							2.1 Get the particular NotificationDetails with the column of NotificationId, NotificationTypeName, DetailedMessage,
 								CreationTime for the given NotificationId to show in popup.
 							2.2 Update the NotificationDetails with the column of NotificationStatus has set to be closed,when it was opened
								for the given NotificationId .
 							2.3 Then return the output Parameters values as @Status = 1 and @Message = NULL.
==================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_GetNotificationDetails1]
(
	@LoginUserId		INT
	,@NotificationId	INT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE	@CompanyId		TINYINT
			,@EmployeeId	INT 
			,@UserGroupId	TINYINT;
	
	SELECT	@CompanyId = CompanyId 
			,@EmployeeId = EmployeeId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--If the @NotificationId IS NULL, Get all the NotificationDetails with the column of NotificationId, NotificationTypeName, DetailedMessage, CreationTime to show in Grid.
		IF @NotificationId IS NULL
		BEGIN	
			IF @UserGroupId = 1
			BEGIN
				SELECT	NotificationId
						,EmployeeImage
						,DetailedMessage
						,CreationTime
				FROM	(	--For Auto message
							SELECT	ND.NotificationId
									,EmployeeImage
									,FirstName
									,ND.NotificationTypeName 	
									,ND.DetailedMessage
									,CASE	WHEN	((DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0) AND DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()) < 60)  
											THEN	CONVERT(VARCHAR,ISNULL(DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()),0)) + ' Mins ago'
											WHEN	DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0
											THEN 	LEFT(CONVERT(VARCHAR,ISNULL(CAST((GETDATE()-ND.CreatedDate) AS TIME(0)),'00:00')),5) + ' Hrs ago'
											ELSE	CONVERT(VARCHAR,ABS(DATEDIFF(dd,GETDATE(),ND.CreatedDate))) +' Days Ago' 
									END AS CreationTime
							FROM	[dbo].[NotificationDetails] ND
							JOIN	[dbo].[EmployeeDetails] ED
								ON  ND.CreatedBy = ED.EmployeeId  
							WHERE   ND.NotificationStatus = 'Open' 
							AND		ND.IsInternal = 1 
							AND		ND.IsAuto = 1
							AND		ND.MessageTo = 'Owner'
							AND		ND.CompanyId = @CompanyId
							)A
					ORDER BY NotificationId DESC;

				--Get the Latest Message Notification poppup
				SELECT	1 AS CurrentMessage
				FROM	[dbo].[NotificationDetails] 
				WHERE	CreatedDate = (SELECT MAX(CreatedDate) FROM [NotificationDetails]);
			END
			ELSE
			BEGIN
				SELECT	NotificationId
						,EmployeeImage
						--,FirstName
						--,NotificationTypeName 	
						,DetailedMessage
						,CreationTime
				FROM	(	--For Auto message
							SELECT	NotificationId
									,EmployeeImage
									,FirstName
									,NotificationTypeName 	
									,DetailedMessage
									,CASE	WHEN	((DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0) AND DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()) < 60)  
											THEN	CONVERT(VARCHAR,ISNULL(DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()),0)) + ' Mins ago'
											WHEN	DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0
											THEN 	LEFT(CONVERT(VARCHAR,ISNULL(CAST((GETDATE()-ND.CreatedDate) AS TIME(0)),'00:00')),5) + ' Hrs ago'
											ELSE	CONVERT(VARCHAR,ABS(DATEDIFF(dd,GETDATE(),ND.CreatedDate))) +' Days Ago' 
									END AS CreationTime
							FROM	[dbo].[NotificationDetails] ND
							JOIN	[dbo].[EmployeeDetails] ED
								ON  ND.EmployeeId = ED.EmployeeId  
							WHERE   NotificationStatus = 'Open' 
							AND		ND.EmployeeId = @LoginUserId
							AND		IsInternal = 1 
							AND		IsAuto = 1
					UNION ALL
						-- For Manual message
						SELECT	ND.NotificationId
								,EmployeeImage
								,FirstName
								,NotificationTypeName 	
								,DetailedMessage
								,CASE	WHEN	((DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0) AND DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()) < 60) THEN 
												CONVERT(VARCHAR,ISNULL(DATEDIFF(MINUTE,ND.CreatedDate,GETDATE()),0)) + ' Mins ago'
										WHEN	DATEDIFF(dd,GETDATE(),ND.CreatedDate) = 0 THEN 
												LEFT(CONVERT(VARCHAR,ISNULL(CAST((GETDATE()-ND.CreatedDate) AS TIME(0)),'00:00')),5) + ' Hrs ago'
										ELSE	CONVERT(VARCHAR,ABS(DATEDIFF(dd,GETDATE(),ND.CreatedDate))) +' Days Ago' 
								END AS CreationTime
						FROM	[dbo].[NotificationDetails] ND	
						LEFT JOIN	(SELECT * FROM [dbo].[NotificationPersonMappingDetails] WHERE PersonId = @EmployeeId)  NPMD
							ON  ND.NotificationId = NPMD.NotificationId
						LEFT JOIN	[dbo].[EmployeeDetails] ED
							ON  NPMD.PersonId = ED.EmployeeId
						WHERE   NotificationStatus = 'Open' 
						AND		IsInternal = 1
						AND		IsAuto = 0 
				)NN
				ORDER BY NotificationId DESC;

				--Get the Latest Message Notification poppup
				SELECT	DetailedMessage AS CurrentMessage
				FROM	[dbo].[NotificationDetails] ND
				LEFT JOIN	(SELECT * FROM [dbo].[NotificationPersonMappingDetails] WHERE PersonId = @EmployeeId)  NPMD
					ON  ND.NotificationId = NPMD.NotificationId
				LEFT JOIN	[dbo].[EmployeeDetails] ED
							ON  NPMD.PersonId = ED.EmployeeId
				WHERE   NotificationStatus = 'Open' 
				--AND		IsInternal = 1
				--AND		IsAuto = 0 
				AND		ND.CreatedDate = (SELECT MAX(CreatedDate) FROM [NotificationDetails])
			;
		END
			SELECT	@Status		= 1
					,@Message	= NULL;
		END	
		ELSE
		BEGIN
			--If the given NotificationId is Not Null,then get the Particular Notification.
			SELECT	NotificationId
					,NotificationTypeName 
					,DetailedMessage
					,CONVERT(NVARCHAR(20), CreatedDate, 100) AS CreationTime
			FROM	[dbo].[NotificationDetails]  
			WHERE	NotificationStatus = 'Open' 
			AND		NotificationId = @NotificationId;
			
			IF EXISTS(SELECT 1 FROM [dbo].[NotificationDetails] WHERE NotificationStatus = 'Open' AND NotificationId = @NotificationId)
			BEGIN
				--Update the NotificationDetail have the column of NotificationStatus has been closed,when it was opened
				UPDATE	[dbo].[NotificationDetails] 
				SET		NotificationStatus	= 'Closed'
						,UpdatedBy			= @LoginUserId	
						,UpdatedDate		= GETDATE()
				WHERE	NotificationStatus	= 'Open' 
				AND		NotificationId		= @NotificationId;			
			END

			SELECT	@Status   = 1 
					,@Message =  NULL;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
