/*=============================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetOverTimeDetails]
 Description		:	Procedure Used to get the OverTimeDetails (1.When click on OverTime in Sidenavigationbar
																   2.When click on Edit option in Grid from UI)
 Input Parameter	:	@LoginUserId, @OverTimeId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-02-2024
 Version			:	1.0 
 Comments			:	1.If the Given @OverTimeId is NULL, then
							1.1 Get the OverTimeDetails table have the Columns of OverTimeId, EmployeeName, Date, StartTime, EndTime
								,TotalHours to show the Values inn Grid.
							1.2 Then return the output paramater values @Status = 1 & @Message = NULL.
						2.If the Given @OverTimeId is NOT NULL, then 
							2.1 Get the OverTimeDetails table have the Columns of OverTimeId, EmployeeId, EmployeeName, Date, StartTime
								,EndTime, TotalHours to show the values in Popup For the Given @OverTimeId.
							2.2 Then return the output parameter values @Status = 1 & @Message = NULL.
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetOverTimeDetails]
(
	@LoginUserId		INT
	,@OverTimeDate		DATETIME
	,@FromDate			DATETIME
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN 
	SET NOCOUNT ON;
	
	DECLARE @CompanyId			TINYINT
			,@UserGroupId		TINYINT
			,@TodayTotalOT		INT
			,@RequestedOT		INT
			,@ApprovedOT		INT
			,@RejectedOT		INT
			,@ToDate			DATE;

	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @OverTimeDate IS NULL
		BEGIN 
			IF @UserGroupId = 1
			BEGIN
				--Logic for Today's Total OverTime
				SELECT	@TodayTotalOT = COUNT(OverTimeId)
				FROM	[dbo].[OverTimeDetails]
				WHERE	CompanyId = @CompanyId 
				AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE());

				--Logic for RequestedOT Employee
				SELECT	 @RequestedOT = COUNT(OverTimeId)
				FROM	[dbo].[OverTimeDetails] OTD
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
				WHERE	OTD.CompanyId = @CompanyId 
				AND		LeaveStatusName = 'Submitted'
				AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
				--AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE());

				--Logic for ApprovedOT Employee
				SELECT	 @ApprovedOT = COUNT(OverTimeId)
				FROM	[dbo].[OverTimeDetails] OTD
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
				WHERE	OTD.CompanyId = @CompanyId 
				AND		LeaveStatusName = 'Approved'
				AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate;

				--Logic for RejectedOT Employee
				SELECT	 @RejectedOT = COUNT(OverTimeId)
				FROM	[dbo].[OverTimeDetails] OTD
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
				WHERE	OTD.CompanyId = @CompanyId 
				AND		LeaveStatusName = 'Rejected'
				AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate;

				--ResultSet for CounterBox
				SELECT	@TodayTotalOT		AS [Today OT's]
						,@RequestedOT		AS [Requested OT's]
						,@ApprovedOT		AS [Approved OT's]	
						,@RejectedOT		AS [Rejected OT's];
					
				-- Result set for Grid SuperAdmin.
				SELECT	OTD.OverTimeId
						,ED.EmployeeImage AS EmpImage
						,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee
						,LEFT(CONVERT(NVARCHAR(50),[Date],113),11) AS [Date]
						,CASE	WHEN TRY_CAST(OTD.StartTime AS DATETIME) IS NOT NULL 
								THEN FORMAT(TRY_CAST(OTD.StartTime AS DATETIME), 'hh:mm tt')
							ELSE 'Invalid Time'
						 END AS StartTime
						,CASE	WHEN TRY_CAST(OTD.EndTime AS DATETIME) IS NOT NULL 
								THEN FORMAT(TRY_CAST(OTD.EndTime AS DATETIME), 'hh:mm tt')
							ELSE 'Invalid Time'
						 END AS EndTime
						,TotalHours
						,OverTimeStatusId
		   				,LSD.LeaveStatusName AS [Status]
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(OTVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
						,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CONCAT(OTVD.FirstName,' ',OTVD.LastName),0) 
								ELSE ' ' 
						END AS ApprovedBy 
						,CASE	WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
								WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
						ELSE 'Orange'
						END AS [Status_Colour]
				FROM	[dbo].[OverTimeDetails] OTD
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON	OTD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[LeavestatusDetails] AS LSD
					ON  OTD.OverTimeStatusId = LSD.LeaveStatusId  
				LEFT JOIN (	SELECT	OverTimeId, EmployeeImage, FirstName, LastName
							FROM	[dbo].[OverTimeDetails] PD
							JOIN	[dbo].[Employeedetails] ED
								ON	PD.UpdatedBy = ED.EmployeeId 
								WHERE PD.CompanyId = @CompanyId
						) AS OTVD
					ON	OTVD.OverTimeId = OTD.OverTimeId
				WHERE	OTD.CompanyId = @CompanyId 
				AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
				ORDER BY OTD.OverTimeId DESC;
		END 
		ELSE 
		BEGIN
			--Logic for Today's Total OverTime
			SELECT	@TodayTotalOT = COUNT(OverTimeId)
			FROM	[dbo].[OverTimeDetails]
			WHERE	CompanyId = @CompanyId 
			AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE())
			AND		EmployeeId = @LoginUserId;

			--Logic for RequestedOT Employee
			SELECT	 @RequestedOT = COUNT(OverTimeId)
			FROM	[dbo].[OverTimeDetails] OTD
			LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
			WHERE	OTD.CompanyId = @CompanyId 
			AND		LeaveStatusName = 'Submitted'
			--AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE())
			AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
			AND		EmployeeId = @LoginUserId;

			--Logic for ApprovedOT Employee
			SELECT	 @ApprovedOT = COUNT(OverTimeId)
			FROM	[dbo].[OverTimeDetails] OTD
			LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
			WHERE	OTD.CompanyId = @CompanyId 
			AND		LeaveStatusName = 'Approved'
			AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
			--AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE())
			AND		EmployeeId = @LoginUserId;

			--Logic for RejectedOT Employee
			SELECT	 @RejectedOT = COUNT(OverTimeId)
			FROM	[dbo].[OverTimeDetails] OTD
			LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
				ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
			WHERE	OTD.CompanyId = @CompanyId 
			AND		LeaveStatusName = 'Rejected'
			AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
			--AND		CONVERT(DATE,[Date]) = CONVERT(DATE,GETDATE())
			AND		EmployeeId = @LoginUserId;

			--ResultSet for CounterBox
			SELECT	@TodayTotalOT		AS [Today OT's]
					,@RequestedOT		AS [Requested OT's]	
					,@ApprovedOT		AS [Approved OT's]	
					,@RejectedOT		AS [Rejected OT's];
					
			-- Result set for Grid General/User.
			SELECT	OTD.OverTimeId
					,LEFT(CONVERT(NVARCHAR(50),[Date],113),11) AS [Date]
					,CASE	WHEN TRY_CAST(OTD.StartTime AS DATETIME) IS NOT NULL 
							THEN FORMAT(TRY_CAST(OTD.StartTime AS DATETIME), 'hh:mm tt')
						ELSE 'Invalid Time'
					 END AS StartTime
					,CASE	WHEN TRY_CAST(OTD.EndTime AS DATETIME) IS NOT NULL 
							THEN FORMAT(TRY_CAST(OTD.EndTime AS DATETIME), 'hh:mm tt')
						ELSE 'Invalid Time'
					 END AS EndTime
					,TotalHours
					,OverTimeStatusId
		   			,LSD.LeaveStatusName AS [Status]
					,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(OTVD.EmployeeImage,'') ELSE '' END AS ApprovePrsnImg
					,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(CONCAT(OTVD.FirstName,' ',OTVD.LastName),0) 
							ELSE ' ' 
					END AS ApprovedBy 
					,CASE	WHEN LSD.LeaveStatusName = 'Approved'	THEN 'Green'
							WHEN LSD.LeaveStatusName = 'Rejected'	THEN 'Red'
					ELSE 'Orange'
					END AS [Status_Colour]
			FROM	[dbo].[OverTimeDetails] OTD
			LEFT JOIN	[dbo].[EmployeeDetails] ED
				ON	OTD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[LeavestatusDetails] AS LSD
				ON  OTD.OverTimeStatusId = LSD.LeaveStatusId  
			LEFT JOIN (	SELECT	OverTimeId, EmployeeImage, FirstName, LastName
						FROM	[dbo].[OverTimeDetails] PD
						JOIN	[dbo].[Employeedetails] ED 
							ON	PD.UpdatedBy = ED.EmployeeId 
							WHERE PD.CompanyId = @CompanyId
					) AS OTVD
				ON	OTVD.OverTimeId = OTD.OverTimeId
			WHERE	OTD.CompanyId = @CompanyId 
			AND		CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate
			AND		OTD.EmployeeId = @LoginUserId 
			ORDER BY OTD.OverTimeId DESC;
		END
			END
			ELSE
			BEGIN
				IF @UserGroupId = 1
				BEGIN
					--Result set for NOT NULL SuperAdmin.
					SELECT	OverTimeId
							,OTD.EmployeeId
							,CONCAT(FirstName,' ',LastName) AS EmpName
							,CONVERT(NVARCHAR(50),[Date],105) AS [Date]
							,StartTime
							,EndTime
							,TotalHours
							,ISNULL(Comments,' ') AS Comments
					FROM	[dbo].[OverTimeDetails] OTD
					JOIN	[dbo].[EmployeeDetails] ED
						ON	OTD.EmployeeId = ED.EmployeeId
					WHERE	OTD.CompanyId = @CompanyId 
					AND		CONVERT(DATE,[Date]) = @OverTimeDate;
				END
				ELSE 
				BEGIN
					--Result set for NOT NULL Employees.
					SELECT	OverTimeId
							,OTD.EmployeeId
							,CONCAT(FirstName,' ',LastName) AS EmpName
							,CONVERT(NVARCHAR(50),[Date],105) AS [Date]
							,StartTime
							,EndTime
							,TotalHours
							,ISNULL(Comments,' ') AS Comments
							,OverTimeStatusId
							,LeaveStatusName AS [OverTimeStatusName]
					FROM	[dbo].[OverTimeDetails] OTD
					JOIN	[dbo].[EmployeeDetails] ED
						ON	OTD.EmployeeId = ED.EmployeeId
					LEFT JOIN	[dbo].[LeavestatusDetails] LSD
						ON	OTD.OverTimeStatusId = LSD.LeaveStatusId
					WHERE	OTD.CompanyId = @CompanyId 
					AND		CONVERT(DATE,[Date]) = @OverTimeDate;
				END
			END 
			SELECT	@Status = 1
					,@Message = NULL;
	END TRY 
	BEGIN CATCH
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetOverTimeDetails]	@LoginUserId	=  5
										,@OverTimeDate	=  NULL  --'2024-09-01'
										,@FromDate		=  '2024-08-01'
										,@Status		=  @S_Status  OUT
										,@Message		=  @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT  *
	FROM	[dbo].[OverTimeDetails]
========================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetOverTimeShiftDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===========================================================================================================  
 Procedure Name		:	[dbo].[USP_GetOverTimeShiftDetails]
 Description		:	Procedure Used to get the OverTimeDetails 
 Input Parameter	:	@LoginUserId, @EmployeeId,@IsForeNoon,@OTDate,
 Output Parameters	:	@Status, @Message				
 Author				:	Dharani.M
 Created on			:	12-04-2024
 Version			:	1.0 
 Comments			:	1.Get the Remaining ShiftTime for the Employee.
						2.Then return the output parameter values @Status = 1 & @Message = NULL.
=============================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetOverTimeShiftDetails]
(
	@LoginUserId	INT
	,@EmployeeId	INT
	,@IsForeNoon	BIT
	,@OTDate		DATE
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN 
	SET NOCOUNT ON;

	--DECLARE @LoginUserId	INT = 1
	--		,@EmployeeId	INT = 4
	--		,@IsForeNoon	BIT = 0
	--		,@OTDate		DATE= '2024-04-12';

	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		BEGIN 
			SELECT	CASE WHEN @IsForeNoon = 1 THEN '00:01:00:000000' ELSE LEFT(DATEADD(mi,0,EndTime),5) END AS StartTime
					,CASE WHEN @IsForeNoon = 1 THEN LEFT(DATEADD(mi,-1,StartTime),5)  ELSE '23:59' END AS EndTime
			FROM	[dbo].[ShiftDetails] SD 
			JOIN	(	SELECT	* 
							FROM	[dbo].[EmployeeShiftMappingDetails]
							WHERE	IsActive = 1
							AND		EmployeeId = @EmployeeId
							AND		CONVERT(DATE,@OTDate) BETWEEN StartDate AND EndDate
						)ESMD
				ON	SD.ShiftId = ESMD.ShiftId
			WHERE	CompanyId  = @CompanyId;
		END
		SELECT	@Status = 1
				,@Message = NULL;
	END TRY  
	BEGIN CATCH
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*===============================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetOverTimeShiftDetails]	@LoginUserId	=  1
												,@EmployeeId	=  4
												,@IsForeNoon	=  0	--1 - am ,0 - pm
												,@OTDate        =  '2024-04-12'
												,@Status		=  @S_Status  OUT
												,@Message		=  @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT  *
	FROM	[dbo].[OverTimeDetails]
	SELECT * FROM EmployeeShiftMappingDetails
	SELECT * FROM ShiftDetails

	EmployeeDetails
=====================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetPaymentDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
