GO

/*===============================================================================================================================   Procedure Name		:	[USP_GetPaymentDetails] Description		:	Procedure used to retrive the PaymentDetails Input Parameter	:	@LoginUserId, @BranchId Output Parameters	:	@Status, @Message Author				:	Tharani T Created on			:	26-10-2024 Version			:	1.0  Comment			:	=================================================================================================================================*/CREATE     PROCEDURE [dbo].[USP_GetPaymentDetails](	@LoginUserId	INT	,@status		BIT				OUT	,@Message		NVARCHAR(500)   OUT)ASBEGIN	SET NOCOUNT ON;		DECLARE @CompanyId  TINYINT;		SELECT	@CompanyId = CompanyId 	FROM	[dbo].[EmployeeDetails]	WHERE	EmployeeId = @LoginUserId;	BEGIN TRY		SELECT	@Status	  = 1   				,@Message = NULL;				BEGIN			SELECT	UserPaymentId					,PaymentType					,PaymentPlan					,PaymentAmount			FROM	[dbo].[UserPaymentDetails]			WHERE	CompanyId = @CompanyId;		END			END TRY	BEGIN CATCH		SELECT	@Status		= 0				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	END CATCHEND/*==================================================================================================================	DECLARE	 @S_Status	BIT			,@M_Message	NVARCHAR(500);	EXEC [dbo].[USP_GetPaymentDetails]	   @LoginUserId		= 1											,@Status		= @S_Status  OUT											,@Message		= @M_Message OUT;	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;	SELECT	* 	FROM	[dbo].[UserPaymentDetails];======================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetPayOutComeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================   Procedure Name		:	[USP_GetPayOutComeDetails] Description		:	Procedure used to retrive the BranchDetails (When click on BranchIcon in Setting Screen And																	 When click on Edit Option in BranchInfo on settings Screen) Input Parameter	:	@LoginUserId, @ModuleName, @StartDate Output Parameters	:	@Status, @Message Author				:	Tharani T Created on			:	16-09-2024 Version			:	1.0 	=================================================================================================================================*/CREATE   PROCEDURE [dbo].[USP_GetPayOutComeDetails](	@LoginUserId	INT	,@ModuleName	NVARCHAR(500) 	,@Month			INT
	,@Year			INT	,@status		BIT				OUT	,@Message		NVARCHAR(500)   OUT)ASBEGIN	SET NOCOUNT ON;		DECLARE @CompanyId						TINYINT			,@TotalAmount					NUMERIC(11,2)			,@EmployeeContributionAmount	NUMERIC(11,2)			,@EmployerContributionAmount	NUMERIC(11,2)			,@TotalAdvanceAmount			NUMERIC(11,2);		SELECT	@CompanyId = CompanyId 	FROM	[dbo].[EmployeeDetails]	WHERE	EmployeeId = @LoginUserId;	BEGIN TRY		SELECT	@Status	  = 1   				,@Message = NULL;			IF @ModuleName = 'PF'		BEGIN			SELECT	@TotalAmount  = SUM(EPFWages)			FROM	[dbo].[PayslipPFDetails] 			WHERE	PFMonth = @Month			AND		PFYear = @Year;						SELECT	@TotalAmount  = SUM(EmployeeShare)			FROM	[dbo].[PayslipPFDetails]			WHERE	PFMonth = @Month			AND		PFYear = @Year;						SELECT	@TotalAmount  = SUM(EmployerEmployeeShare)			FROM	[dbo].[PayslipPFDetails]			WHERE	PFMonth = @Month			AND		PFYear = @Year;						SELECT	@TotalAmount  = SUM(AdvanceAmount)			FROM	[dbo].[PayslipPFDetails] PD			JOIN	[dbo].[AdvanceDetails] AD				ON	PD.EmployeeId = AD.EmployeeId 			WHERE	PFMonth = @Month			AND		PFYear = @Year;  			SELECT	@TotalAmount					AS TotalAmount										,@EmployeeContributionAmount	AS EmployeeShare					,@EmployerContributionAmount	AS EmployerShare					,@TotalAdvanceAmount			AS AdvanceAmount;			SELECT	UANNumber AS UAN
					,CONCAT(FirstName, ' ',LastName) AS EmployeeName
					,GrossWages
					,EPFWages
					,EPSWages
					,EmployeeShare AS EEShareRemitted
					,EmployerEmployeeShare AS EPSContributionRemitted
					,EmployerShare AS ERShareRemitte
					,NCPDays 					,AdvanceAmount AS Advance			FROM	[dbo].[PayslipPFDetails] PFD			JOIN	[dbo].[EmployeeDetails] ED				ON	PFD.EmployeeId = ED.EmployeeId			JOIN	[dbo].[EmployeePFDetails] EPFD				ON	PFD.EmployeeId = EPFD.EmployeeId			JOIN	[dbo].[PayslipDetails_1] PD				ON	PFD.EmployeeId = PD.EmployeeId			WHERE	PFD.PFMonth = @Month			AND		PFD.PFYear = @Year;		END		ELSE IF @ModuleName = 'ESI'		BEGIN			SELECT	@TotalAmount  = COUNT(TotalMonthlyWages)			FROM	[dbo].[PayslipESIDetails];						SELECT	@EmployeeContributionAmount  = SUM(TotalMonthlyWages)			FROM	[dbo].[PayslipESIDetails]			WHERE	ESIMonth = @Month			AND		ESIYear = @Year;						SELECT	@EmployerContributionAmount  = SUM(TotalMonthlyWages)			FROM	[dbo].[PayslipESIDetails]			WHERE	ESIMonth = @Month			AND		ESIYear = @Year;						SELECT	@TotalAdvanceAmount  = SUM(TotalMonthlyWages)			FROM	[dbo].[PayslipESIDetails]			WHERE	ESIMonth = @Month			AND		ESIYear = @Year;  			SELECT	@TotalAmount					AS TotalESIAmount										,@EmployeeContributionAmount	AS CurrentMonthESI					,@EmployerContributionAmount	AS EmployerShare					,@TotalAdvanceAmount			AS AdvanceAmount;			SELECT	ROW_NUMBER() OVER(ORDER BY ESI.EmployeeId) AS EmployeeNumber
					,CONCAT(FirstName, ' ',LastName) AS IpName
					,EmployeeESINumber AS IpNumber
					,TotalMonthlyWages
					,ReasonCodeforZeroWorkingDay
					,LastWorkingDay 			FROM	[dbo].[PayslipESIDetails] ESI			JOIN	[dbo].[EmployeeDetails] ED				ON	ESI.EmployeeId = ED.EmployeeId			JOIN	[dbo].[EmployeeESIDetails] EESI				ON	ESI.EmployeeId = EESI.EmployeeId			WHERE	ESI.ESIMonth = @Month			AND		ESI.ESIYear = @Year;		END		ELSE IF @ModuleName = 'PT'		BEGIN			SELECT	@TotalAMount = SUM(ProfessionalTax)			FROM	[dbo].[PayslipPTDetails];						SELECT	@EmployeeContributionAmount = SUM(PTGross)			FROM	[dbo].[PayslipPTDetails]			WHERE	PTMonth = @Month			AND		PTYear = @Year;						SELECT	@EmployerContributionAmount = SUM(ProfessionalTax)			FROM	[dbo].[PayslipPTDetails]			WHERE	PTMonth = @Month			AND		PTYear = @Year;			SELECT	@TotalAmount					AS TotalTax										,@EmployeeContributionAmount	AS TotalGrossPay					,@EmployerContributionAmount	AS EmployerShare					,10								AS CurrentMonthTax;			SELECT	ROW_NUMBER() OVER(ORDER BY PT.EmployeeId) AS EmployeeNumber
					,CONCAT(FirstName, ' ',LastName) AS EmployeeName
					,CONCAT(DATENAME(MONTH,PTMonth), '', PTYear) AS [Month]
					,EmployeeType AS PayrollType
					,PTGross
					,BD.[State] AS [State]
					,BD.City AS RegisteredLocation
					,ProfessionalTax 			FROM	[dbo].[PayslipPTDetails] PT			JOIN	[dbo].[EmployeeDetails] ED				ON	PT.EmployeeId = ED.EmployeeId			JOIN	[dbo].[EmployeeTypeDetails] ETD				ON	ETD.EmployeeTypeId = ED.EmployeeTypeId			JOIN	[dbo].[BranchDetails] BD				ON	ED.BranchId = BD.BranchId			WHERE	PT.PTMonth = @Month			AND		PT.PTYear = @Year;		END		ELSE IF @ModuleName = 'TDS'		BEGIN			SELECT	1 AS CounterBox1					,1 AS CounterBox2					,1 AS CounterBox3					,1 AS CounterBox4;			SELECT	1						AS EmployeeNumber					,'Veer Varma M'		AS EmployeeName					,'Regualr'				AS PayrollType					,'AWIPC3490N'			AS PanNumber					,'100'					AS IncomeTax					,'0'					AS Surcharge					,'100'					AS Cess					,'2500'					AS TotalTaxAmount		UNION ALL 			SELECT	2						AS EmployeeNumber					,'Jerusal Jose A'				AS EmployeeName					,'Regualr'				AS PayrollType					,'TN55667567'			AS PanNumber					,'150'					AS IncomeTax					,'0'					AS Surcharge					,'80'					AS Cess					,'2800'					AS TotalTaxAmount		UNION ALL 			SELECT	3						AS EmployeeNumber					,'Rakesh Y'			AS EmployeeName					,'Regualr'				AS PayrollType					,'EECPM8147G'			AS PanNumber					,'200'					AS IncomeTax					,'0'					AS Surcharge					,'150'					AS Cess					,'3000'					AS TotalTaxAmount		UNION ALL 			SELECT	4						AS EmployeeNumber					,'Shaila CM'				AS EmployeeName					,'Regualr'				AS PayrollType					,'GZPPD0770L'			AS PanNumber					,'120'					AS IncomeTax					,'0'					AS Surcharge					,'90'					AS Cess					,'3500'					AS TotalTaxAmount		UNION ALL 			SELECT	5						AS EmployeeNumber					,'Yeshwanth R'			AS EmployeeName					,'Regualr'				AS PayrollType					,'DDBPK0070B'			AS PanNumber					,'200'					AS IncomeTax					,'0'					AS Surcharge					,'120'					AS Cess					,'1500'					AS TotalTaxAmount		UNION ALL 			SELECT	6						AS EmployeeNumber					,'Tharanitharan'		AS EmployeeName					,'Regualr'				AS PayrollType					,'CDJPT2197R'			AS PanNumber					,'200'					AS IncomeTax					,'0'					AS Surcharge					,'150'					AS Cess					,'3300'					AS TotalTaxAmount		UNION ALL 			SELECT	7				AS EmployeeNumber					,'Prakash'		AS EmployeeName					,'Regualr'		AS PayrollType					,'1316546165'	AS PanNumber					,'300'			AS IncomeTax					,'0'			AS Surcharge					,'170'			AS Cess					,'3600'			AS TotalTaxAmount		UNION ALL 			SELECT	8				AS EmployeeNumber					,'Karthick'		AS EmployeeName					,'Regualr'		AS PayrollType					,'AGRG464523'	AS PanNumber					,'400'			AS IncomeTax					,'0'			AS Surcharge					,'200'			AS Cess					,'4000'			AS TotalTaxAmount		UNION ALL 			SELECT	9				AS EmployeeNumber					,'Gowsalya'		AS EmployeeName					,'Regualr'		AS PayrollType					,'TBN4645664'	AS PanNumber					,'450'			AS IncomeTax					,'0'			AS Surcharge					,'220'			AS Cess					,'4200'			AS TotalTaxAmount		UNION ALL 			SELECT	10				AS EmployeeNumber					,'Kavinesh'		AS EmployeeName					,'Regualr'		AS PayrollType					,'FGDT987984'	AS PanNumber					,'500'			AS IncomeTax					,'0'			AS Surcharge					,'250'			AS Cess					,'5000'			AS TotalTaxAmount		END	END TRY	BEGIN CATCH		SELECT	@Status		= 0				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	END CATCHEND/*==================================================================================================================	DECLARE	 @S_Status	BIT			,@M_Message	NVARCHAR(500);	EXEC [dbo].[USP_GetPayOutComeDetails]	@LoginUserId	= 3											,@ModuleName	= 'PF'											,@Month			= 1
											,@Year			= 2025											,@Status		= @S_Status  OUT											,@Message		= @M_Message OUT;	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;	SELECT	* 	FROM	[dbo].[ESIDetails];======================================================================================================================*/			
GO
/****** Object:  StoredProcedure [dbo].[USP_GetPayrollApprovalDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetPayrollApprovalDetails]
 Description		:	Procedure used to retrieve the AdvanceDetails (When click on the Advance in SideNavigationBar 
						                                              And When Click On Edit Option On Grid in Advance screen)
 Input Parameter	:	@LoginUserId,@FromDate,@ToDate
 Output Parameters	:	@Status, @Message
 Author				:	Tharani.T
 Created on			:	29.09.2024
 Version			:	1.0 
 Comment			:	
======================================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetPayrollApprovalDetails]
(	
	@LoginUserId		INT
	,@PayrollApproval	INT 
	,@FromDate			DATE 
	,@Mine				BIT
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT
			,@ToDate	DATE;

	SET @ToDate = EOMONTH(@FromDate);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @Mine = 1 
		BEGIN
			SELECT	DISTINCT CASE WHEN CAST(COUNT(ISNULL(PayrollApproval, 0)) AS VARCHAR) = 0 THEN 'There is no Pending Approval.' 
							ELSE CONCAT('There are ',CAST(COUNT(ISNULL(PayrollApproval, 0)) AS VARCHAR),' pending records')
					END AS PayrollApproval
					,CASE WHEN SUM(PayrollApproval) = 0 THEN 'Green' ELSE 'Red' END AS Status_Colour
			FROM	(
						SELECT	COUNT(RegularizationId) AS PayrollApproval 
						FROM	[dbo].[RegularizationDetails] RD
						WHERE	RD.EmployeeId = 1
						AND		RegularizationStatusId = 2
						AND		CONVERT(DATE, [Date]) BETWEEN '2025-01-01' AND '2025-01-01'
						UNION ALL
						SELECT	COUNT(LeaveId) AS PayrollApproval 
						FROM	[dbo].[LeaveDetails]
						WHERE	EmployeeId = 1
						AND		LeaveStatusId = 2
						AND		CONVERT(DATE, FromDate) BETWEEN @FromDate AND @ToDate
						UNION ALL		
						SELECT	COUNT(PermissionId) AS PayrollApproval 
						FROM	[dbo].[PermissionDetails]
						WHERE	EmployeeId = @LoginUserId
						AND		PermissionStatusId = 2
						AND		CONVERT(DATE, PermissionDate) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(CompensatoryOffId) AS PayrollApproval 
						FROM	[dbo].[CompensatoryOffDetails]
						WHERE	EmployeeId = @LoginUserId
						AND		CompensatoryOffStatusId = 2
						AND		CONVERT(DATE, CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(ClaimId) AS PayrollApproval 
						FROM	[dbo].[ClaimDetails]
						WHERE	RequestedBy = @LoginUserId
						AND		ClaimStatusId = 2
						AND		CONVERT(DATE, ClaimDate) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(AdvanceId) AS PayrollApproval 
						FROM	[dbo].[AdvanceDetails]
						WHERE	EmployeeId = @LoginUserId
						AND		AdvanceStatusId = 2
						AND		CONVERT(DATE, AdvanceDate) BETWEEN @FromDate AND @ToDate
						UNION ALL		 
						SELECT	COUNT(LoanId) AS PayrollApproval 
						FROM	[dbo].[LoanDetails]
						WHERE	EmployeeId = @LoginUserId
						AND		LoanStatusId = 2
						AND		CONVERT(DATE, LoanDate) BETWEEN @FromDate AND @ToDate
					) AS PA
			WHERE	PayrollApproval = 1;

			IF @PayrollApproval = 1
			BEGIN 
				SELECT	RD.RegularizationId
						,EmployeeId
						,CONVERT(NVARCHAR(50),[Date], 106) AS [Date]
						,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
						,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
						,RD.RegularizationStatusId
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[RegularizationDetails] RD
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	RD.RegularizationStatusId = LSD.LeaveStatusId
				WHERE	CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate 
				AND		RD.RegularizationStatusId = 2
				AND		RD.EmployeeId = @LoginUserId
				AND		RD.CompanyId = @CompanyId 
				ORDER BY RD.RegularizationId DESC;
			END
			ELSE IF @PayrollApproval = 2
			BEGIN 
				SELECT	LD.LeaveId
						,EmployeeId
						,LTD.LeaveTypeName AS LeaveType
						,CONVERT(NVARCHAR(50),LD.FromDate,106) AS [From]
						,CONVERT(NVARCHAR(50),LD.ToDate,106) AS [To]
						,CONCAT(CASE WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END
								,CASE WHEN FromDate = ToDate THEN ' Day' WHEN FromDate != ToDate THEN ' Days'
										ELSE 'HalfDay' 
						END) AS NoOfDays
						,LSD.LeaveStatusId
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[LeaveDetails] LD
				JOIN	[dbo].[LeaveTypeDetails] LTD
					ON	LD.LeaveTypeId = LTD.LeaveTypeId
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	LD.LeaveStatusId = LSD.LeaveStatusId
				WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
				AND		EmployeeId = @LoginUserId
				AND		LD.CompanyId = @CompanyId 
				AND		LSD.LeaveStatusId = 2
				ORDER BY LD.LeaveId DESC;
			END
			ELSE IF @PayrollApproval = 3
			BEGIN 
				SELECT	PD.PermissionId
						,EmployeeId
						,CONVERT(NVARCHAR(50),PD.PermissionDate,106) AS [Date]
						,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
						,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
						,STUFF((CONVERT(VARCHAR(8),ISNULL(CAST((CONVERT(DATETIME,EndTime) - CONVERT(DATETIME,StartTime)) AS TIME),'00:00')) + ' Hrs'),6,3,'')  AS NoOfHours
						,PermissionStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[PermissionDetails] AS PD
				LEFT JOIN [dbo].[LeavestatusDetails] AS LSD
					ON  PD.PermissionStatusId = LSD.LeaveStatusId  
				WHERE	CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate 
				AND		PD.EmployeeId = @LoginUserId
				AND		PD.CompanyId = @CompanyId
				AND		PD.PermissionStatusId = 2
				ORDER BY PD.PermissionId DESC; 
			END
			ELSE IF @PayrollApproval = 4
			BEGIN 
				SELECT	CD.CompensatoryOffId
						,EmployeeId
						,CONVERT(NVARCHAR(50),CD.CompensatoryOffDate,106) AS [Date]
						,CONCAT(NoOfDays,' Day') AS NoOfDays
						,CompensatoryOffStatusId 
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[CompensatoryOffDetails] CD
				JOIN	[dbo].[LeavestatusDetails] AS LSD
					ON  CD.CompensatoryOffStatusId = LSD.LeaveStatusId  
				WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate 
				AND		EmployeeId = @LoginUserId
				AND		CompensatoryOffStatusId = 2
				AND		CD.CompanyId  = @CompanyId
				ORDER BY CD.CompensatoryOffId DESC; 
			END 
			ELSE IF @PayrollApproval = 5
			BEGIN 
				SELECT	CD.ClaimId
						,CONVERT(NVARCHAR(50),CD.ClaimDate,106) AS ClaimDate
						,ClaimTypeName AS ClaimType
						,CONCAT(N'₹ ',ClaimAmount) AS ClaimAmount
						,LSD.LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[ClaimDetails] CD
				JOIN	[dbo].[ClaimTypeDetails] CTD             
					ON	CTD.ClaimTypeId = CD.ClaimTypeId
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	CD.ClaimStatusId = LSD.LeaveStatusId
				WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
				AND		RequestedBy = @LoginUserId
				AND		ClaimStatusId = 2
				AND		CD.CompanyId = @CompanyId
				ORDER BY CD.ClaimId DESC;
			END
			ELSE IF @PayrollApproval = 6
			BEGIN 
				SELECT	AD.AdvanceId
						,AD.EmployeeId
						,CONVERT(NVARCHAR(50),AD.AdvanceDate,106) AS [Date]
						,CONCAT(N'₹ ',AD.AdvanceAmount) AS AdvanceAmount
						,CONCAT(N'₹ ',ISNULL (DueAmount,0)) AS DueAmount
						,AdvanceStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[AdvanceDetails] AD
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	AD.AdvanceStatusId = LSD.LeaveStatusId
				WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate
				AND		EmployeeId = @LoginUserId
				AND		AdvanceStatusId = 2
				AND		AD.CompanyId = @CompanyId
				ORDER BY AD.AdvanceId DESC; 
			END
			ELSE IF @PayrollApproval = 7
			BEGIN 
				SELECT	LD.LoanId
						,LD.EmployeeId	
						,CONVERT(NVARCHAR(50),LD.LoanDate,106) AS [Date]
						,CONCAT(N'₹ ',LD.LoanAmount) AS LoanAmount
						,NoOfDues
						,CONCAT(N'₹ ',ISNULL(DueAmount,0)) AS DueAmount
						,PendingDues
						,CONCAT(N'₹ ',ISNULL(PendingAmount,0)) AS PendingAmount
						,LoanStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[LoanDetails] LD
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	LD.LoanStatusId = LSD.LeaveStatusId
				WHERE	CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate 
				AND		EmployeeId = @LoginUserId
				AND		LoanStatusId = 2
				AND		LD.CompanyId = @CompanyId
				ORDER BY LD.LoanId DESC;  
			END
		END
		ELSE
		BEGIN
			SELECT	DISTINCT CASE WHEN CAST(COUNT(ISNULL(PayrollApproval, 0)) AS VARCHAR) = 0 THEN 'There is no Pending Approval.' 
							ELSE CONCAT('There are ',CAST(COUNT(ISNULL(PayrollApproval, 0)) AS VARCHAR),' pending records')
					END AS PayrollApproval
					,CASE WHEN SUM(PayrollApproval) = 0 THEN 'Green' ELSE 'Red' END AS Status_Colour
			FROM	(
						SELECT	COUNT(RegularizationId) AS PayrollApproval 
						FROM	[dbo].[RegularizationDetails] RD
						LEFT JOIN [dbo].[EmployeeDetails] ED
							ON	RD.EmployeeId = ED.EmployeeId	
						WHERE	ED.ReportingPersonId = @LoginUserId
						AND		RegularizationStatusId = 2
						AND		CONVERT(DATE, [Date]) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(LeaveId) AS PayrollApproval 
						FROM	(	SELECT	EmployeeId,  LeaveId
									FROM	[dbo].[LeaveDetails] 
									WHERE	LeaveStatusId = 2
									AND		CONVERT(DATE, FromDate) BETWEEN @FromDate AND @ToDate
								) AS LD
						LEFT JOIN [dbo].[EmployeeDetails] ED 
							ON	LD.EmployeeId = ED.EmployeeId
						WHERE	ED.ReportingPersonId = @LoginUserId
						UNION ALL		
						SELECT	COUNT(PermissionId) AS PayrollApproval 
						FROM	[dbo].[PermissionDetails] PD 
						LEFT JOIN [dbo].[EmployeeDetails] ED
							ON	PD.EmployeeId = ED.EmployeeId
						WHERE	ED.ReportingPersonId = @LoginUserId
						AND 	PermissionStatusId = 2
						AND		CONVERT(DATE, PermissionDate) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(CompensatoryOffId) AS PayrollApproval 
						FROM	[dbo].[CompensatoryOffDetails] CD
						JOIN	[dbo].[EmployeeDetails] ED 
							ON	ED.EmployeeId = CD.EmployeeId
						WHERE	ED.ReportingPersonId = @LoginUserId
						AND 	CD.CompensatoryOffStatusId = 2
						AND		CONVERT(DATE, CD.CompensatoryOffDate) BETWEEN @FromDate AND @ToDate
						UNION ALL
						SELECT	COUNT(RequestedBy) AS PayrollApproval 
						FROM	(	SELECT	RequestedBy, COUNT(ClaimId) AS [Count]
									FROM	[dbo].[ClaimDetails] 
									WHERE	ClaimStatusId = 2
									AND		CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate
									GROUP BY RequestedBy
								) AS CD
						LEFT JOIN [dbo].[EmployeeDetails] ED
							ON	ED.EmployeeId = CD.RequestedBy
						WHERE	ED.ReportingPersonId = @LoginUserId
						UNION ALL
						SELECT	COUNT(CD.EmployeeId) AS PayrollApproval 
						FROM	(	SELECT	EmployeeId, COUNT(AdvanceId) AS [Count] 
									FROM	[dbo].[AdvanceDetails] 
									WHERE	AdvanceStatusId = 2
									AND		CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate
									GROUP BY EmployeeId
								) AS CD
						LEFT JOIN	[dbo].[EmployeeDetails] ED
							ON	ED.EmployeeId = CD.EmployeeId
						WHERE	ED.ReportingPersonId = @LoginUserId
						UNION ALL		 
						SELECT	COUNT(LD.EmployeeId) AS PayrollApproval 
						FROM	(	SELECT	EmployeeId, COUNT(LoanId) AS [Count]
									FROM	[dbo].[LoanDetails] 
									WHERE	LoanStatusId = 2
									AND		CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate
									GROUP BY EmployeeId
								) AS LD
						LEFT JOIN [dbo].[EmployeeDetails] ED
							ON	ED.EmployeeId = LD.EmployeeId
						WHERE	ED.ReportingPersonId = @LoginUserId
					) AS PA
			WHERE	PayrollApproval = 1

			IF @PayrollApproval = 1
			BEGIN 
				SELECT	RD.RegularizationId
						,RD.EmployeeId
						,CONCAT(FirstName, ' ',LastName) AS Employee
						,CONVERT(NVARCHAR(50),[Date], 106) AS [Date]
						,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
						,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
						,RD.RegularizationStatusId
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	[dbo].[RegularizationDetails] RD
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	RD.RegularizationStatusId = LSD.LeaveStatusId
				LEFT JOIN [dbo].[EmployeeDetails] ED
					ON	RD.EmployeeId = ED.EmployeeId	
				WHERE	CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate 
				AND		RD.RegularizationStatusId = 2
				AND		ED.ReportingPersonId = @LoginUserId
				AND		RD.CompanyId = @CompanyId 
				ORDER BY RD.RegularizationId DESC;
			END
			ELSE IF @PayrollApproval = 2
			BEGIN 
				SELECT	LD.LeaveId
						,ED.EmployeeId
						,ED.EmployeeImage AS EmpImage
						,ISNULL(CONCAT(ED.FirstName,' ',ED.LastName),'') AS Employee
						,DD.DesignationName AS Designation
						,LTD.LeaveTypeName AS LeaveType
						,CONVERT(NVARCHAR(50),LD.FromDate,106) AS [From]
						,CONVERT(NVARCHAR(50),LD.ToDate,106) AS [To]
						,CONCAT(CASE WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END,
									CASE WHEN FromDate = ToDate	THEN ' Day' WHEN FromDate != ToDate	THEN ' Days'
									ELSE 'HalfDay' 
						 END) AS NoOfDays
						,LSD.LeaveStatusId
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	LeaveId, EmployeeId, LeaveStatusId, LeaveTypeId
									,FromDate, ToDate, NoOfDays
							FROM	[dbo].[LeaveDetails] 
							WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
							AND		CompanyId = @CompanyId 
							AND		LeaveStatusId = 2
						) AS LD
				LEFT JOIN	[dbo].[Employeedetails] ED
					ON	LD.EmployeeId = ED.EmployeeId 
				LEFT JOIN [dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId 
				LEFT JOIN [dbo].[LeaveTypeDetails] LTD
					ON	LD.LeaveTypeId = LTD.LeaveTypeId
				LEFT JOIN [dbo].[LeaveStatusDetails] LSD
					ON	LD.LeaveStatusId = LSD.LeaveStatusId
				WHERE	ED.ReportingPersonId = @LoginUserId
				ORDER BY LD.LeaveId DESC;
			END
			ELSE IF @PayrollApproval = 3
			BEGIN 
				SELECT	PD.PermissionId
						,ED.EmployeeId
						,ED.EmployeeImage AS EmpImage
						,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee
						,CONVERT(NVARCHAR(50),PD.PermissionDate,106) AS [Date]
						,DesignationName AS Designation
						,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
						,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
						,STUFF((CONVERT(VARCHAR(8),ISNULL(CAST((CONVERT(DATETIME,EndTime) - CONVERT(DATETIME,StartTime)) AS TIME),'00:00')) + ' Hrs'),6,3,'')  AS NoOfHours
						,PermissionStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	*
							FROM	[dbo].[PermissionDetails] 
							WHERE	CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate 
							AND		CompanyId = @CompanyId
							AND		PermissionStatusId = 2
						) AS PD
				LEFT JOIN	[dbo].[EmployeeDetails] AS ED
					ON  PD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[LeavestatusDetails] AS LSD
					ON  PD.PermissionStatusId = LSD.LeaveStatusId  
				LEFT JOIN	[dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId
				WHERE	ED.ReportingPersonId = @LoginUserId
				ORDER BY PD.PermissionId DESC; 
			END
			ELSE IF @PayrollApproval = 4
			BEGIN 
				SELECT	COD.CompensatoryOffId
						,ED.EmployeeId
						,ED.EmployeeImage AS EmpImage
						,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee
						,DD.DesignationName AS Designation
						,CONVERT(NVARCHAR(50),COD.CompensatoryOffDate,106) AS [Date]
						,NoOfDays
						,CompensatoryOffStatusId 
						,LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	CompensatoryOffStatusId, EmployeeId, CompensatoryOffId
									,NoOfDays, CompensatoryOffDate
							FROM	[dbo].[CompensatoryOffDetails] CD
							WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate 
							AND		CD.CompensatoryOffStatusId = 2
							AND		CD.CompanyId  = @CompanyId
						) AS COD
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON  COD.EmployeeId = ED.EmployeeId
				JOIN	[dbo].[LeavestatusDetails] AS LSD
					ON  COD.CompensatoryOffStatusId = LSD.LeaveStatusId  
				LEFT JOIN	[dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId
				WHERE	ED.ReportingPersonId = @LoginUserId
				AND		CompensatoryOffStatusId NOT IN (1, 5)
				ORDER BY COD.CompensatoryOffId DESC; 
			END 
			ELSE IF @PayrollApproval = 5
			BEGIN  
				SELECT	CD.ClaimId
						,ISNULL(ED.EmployeeImage,' ')  AS EmpImage
						,CONCAT(ED.FirstName,' ',ED.LastName) AS Employee	
						,CONVERT(NVARCHAR(50),CD.ClaimDate,106) AS ClaimDate
						,ClaimTypeName AS ClaimType
						,CONCAT(N'₹ ',ClaimAmount) AS ClaimAmount
						,LSD.LeaveStatusName AS [Status]
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	ClaimTypeId, ClaimAmount, RequestedBy
									,ClaimStatusId, ClaimId, ClaimDate
							FROM	[dbo].[ClaimDetails] 
							WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
							AND		CompanyId = @CompanyId
							AND		ClaimStatusId = 2
						) AS CD
				JOIN	[dbo].[ClaimTypeDetails] CTD             
					ON	CTD.ClaimTypeId = CD.ClaimTypeId
				LEFT JOIN	[dbo].[EmployeeDetails] ED             
					ON	ED.EmployeeId = CD.RequestedBy
				JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	CD.ClaimStatusId = LSD.LeaveStatusId
				WHERE	ED.ReportingPersonId = @LoginUserId
				ORDER BY CD.ClaimId DESC;
			END
			ELSE IF @PayrollApproval = 6
			BEGIN  
				SELECT	AD.AdvanceId
						,AD.EmployeeId
						,ED.EmployeeImage AS EmpImage
						,CONCAT(ED.FirstName ,' ',ED.LastName) AS Employee	
						,CONVERT(NVARCHAR(50),AD.AdvanceDate,106) AS [Date]
						,CONCAT(N'₹ ',AD.AdvanceAmount) AS AdvanceAmount
						,CONCAT(N'₹ ',ISNULL(DueAmount,0)) AS DueAmount
						,AdvanceStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	EmployeeId, AdvanceStatusId, AdvanceId, AdvanceDate
									,DueAmount, AdvanceAmount
							FROM	[dbo].[AdvanceDetails] 
							WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate 
							AND		AdvanceStatusId = 2
							AND		CompanyId = @CompanyId
						) AS AD
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON	AD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	AD.AdvanceStatusId = LSD.LeaveStatusId
				WHERE	ED.ReportingPersonId = @LoginUserId
				ORDER BY AD.AdvanceId DESC; 
			END
			ELSE IF @PayrollApproval = 7
			BEGIN  
				SELECT	LD.LoanId
						,LD.EmployeeId
						,ED.EmployeeImage AS EmpImage
						,CONCAT(ED.FirstName ,' ',ED.LastName) AS Employee			
						,CONVERT(NVARCHAR(50),LD.LoanDate,106) AS [Date]
						,CONCAT(N'₹ ',LD.LoanAmount) AS LoanAmount
						,NoOfDues
						,CONCAT(N'₹ ',ISNULL(DueAmount,0)) AS DueAmount
						,PendingDues
						,CONCAT(N'₹ ',PendingAmount) AS PendingAmount
						,LoanStatusId 
						,LSD.LeaveStatusName AS [Status] 
						,'Orange' AS [Status_Colour]
				FROM	(	SELECT	EmployeeId, LoanStatusId, LoanId, LoanAmount, LoanDate, DueAmount
									,PendingAmount, PendingDues, NoOfDues	
							FROM	[dbo].[LoanDetails] 
							WHERE	CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate 
							AND		LoanStatusId = 2
							AND		CompanyId = @CompanyId
						) AS LD
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON	LD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[LeaveStatusDetails] LSD
					ON	LD.LoanStatusId = LSD.LeaveStatusId
				WHERE	ED.ReportingPersonId = @LoginUserId
				ORDER BY LD.LoanId DESC;  
			END
		END	
		SELECT	@Status    = 1 
				,@Message  = NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetPayrollApprovalDetails]	@LoginUserId		= 1
												,@PayrollApproval	=  1
												,@FromDate			= '2025-01-01'
												,@Mine				= 1
												,@Status			= @S_Status	 OUT
												,@Message			= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM RegularizationDetails 
	SELECT * FROM EmployeeDetails 
=================================================================================================================================================*/


GO
/****** Object:  StoredProcedure [dbo].[USP_GetPayrollApprovalMailDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetPayrollApprovalMailDetails]
 Description		:	Procedure used to retrieve the AdvanceDetails (When click on the Advance in SideNavigationBar 
						                                              And When Click On Edit Option On Grid in Advance screen)
 Input Parameter	:	@LoginUserId,@FromDate,@ToDate
 Output Parameters	:	@Status, @Message
 Author				:	Tharani.T
 Created on			:	20.10.2024
 Version			:	1.0 
 Comment			:	
======================================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetPayrollApprovalMailDetails]
(	
	@LoginUserId		INT
	,@FromDate			DATE
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@UserGroupId	TINYINT
			,@ToDate		DATE;

	SET @ToDate = EOMONTH(@FromDate);
	
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		-- Result set for main sended information.
		SELECT	Email AS FromMail
				,SMTPNumber
				,RPD.OfficialEmail AS ToMail
				,'Pending Approvals.' AS [Subject]
				,CONCAT('Dear ',RPD.FirstName, ' ', RPD.LastName, QUOTENAME(RPD.EmployeeCompanyId)) AS FirstLine
				,'I hope you are doing well.' AS SecondLine
				,CONCAT('I kindly request your approval for my pending payroll module request. Please review and approve it at your earliest convenience. Let me know if any further information is required. This request has been submitted by ', ED.FirstName, ' ', ED.LastName, QUOTENAME(ED.EmployeeCompanyId)) AS ThirdLine
		FROM	[dbo].[NoticationCategoryDetails] NCD
		JOIN	[dbo].[EmployeeDetails] ED 
			ON	NCD.CompanyId = ED.CompanyId
		LEFT JOIN [dbo].[EmployeeDetails] RPD 
			ON	ED.ReportingPersonId = RPD.EmployeeId
		WHERE	ED.EmployeeId = @LoginUserId
		AND		NCD.IsActive = 1;

		-- Result set Module Based RequestDetails.
		SELECT	'Regularization' AS ModuleName
				,CONVERT(NVARCHAR(50),[Date], 106) AS [Date]
				,CASE WHEN PunchType = 1 THEN 'CheckIn' ELSE 'CheckOut' END AS [Type]
				,ISNULL(FORMAT(CONVERT(DATETIME,InOutTime),'hh:mm tt'),'') AS Total
		FROM	[dbo].[RegularizationDetails]
		WHERE	CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate 
		AND		RegularizationStatusId = 2
		AND		EmployeeId = @LoginUserId
		AND		CompanyId = @CompanyId 
		UNION ALL
		SELECT	'Leave' AS ModuleName
				,CONCAT(CONVERT(NVARCHAR(50),LD.FromDate,106),' - ',CONVERT(NVARCHAR(50),LD.ToDate,106)) AS [Date]
				,LTD.LeaveTypeName AS [Type]
				,CONCAT(CASE WHEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),3,1)) = '0' THEN (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,1)) ELSE (SUBSTRING (CONVERT(NVARCHAR(10),NoOfDays),1,3)) END
						,CASE WHEN FromDate = ToDate THEN ' Day' WHEN FromDate != ToDate THEN ' Days'
								ELSE 'HalfDay' 
				END) AS NoOfDays
		FROM	[dbo].[LeaveDetails] LD
		JOIN	[dbo].[LeaveTypeDetails] LTD
			ON	LD.LeaveTypeId = LTD.LeaveTypeId
		WHERE	CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate
		AND		EmployeeId = @LoginUserId
		AND		LD.CompanyId = @CompanyId 
		AND		LD.LeaveStatusId = 2
		UNION ALL
		SELECT	'Permission' AS ModuleName
				,CONVERT(NVARCHAR(50),PermissionDate,106) AS [Date]
				,CONCAT(ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),''),' to ',ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'')) AS TotalTime
				,STUFF((CONVERT(VARCHAR(8),ISNULL(CAST((CONVERT(DATETIME,EndTime) - CONVERT(DATETIME,StartTime)) AS TIME),'00:00')) + ' Hrs'),6,3,'')  AS NoOfHours
		FROM	[dbo].[PermissionDetails]
		WHERE	CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate 
		AND		EmployeeId = @LoginUserId
		AND		CompanyId = @CompanyId
		AND		PermissionStatusId = 2
		UNION ALL
		SELECT	'CompensatoryOff' AS ModuleName
				,CONVERT(NVARCHAR(50),CompensatoryOffDate,106) AS [Date]
				,CONCAT(NoOfDays,' Day') AS NoOfDays
				,'' AS Total
		FROM	[dbo].[CompensatoryOffDetails]
		WHERE	CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate 
		AND		EmployeeId = @LoginUserId
		AND		CompensatoryOffStatusId = 2
		AND		CompanyId = @CompanyId
		UNION ALL
		SELECT	'Claim' AS ModuleName
				,CONVERT(NVARCHAR(50),CD.ClaimDate,106) AS ClaimDate
				,ClaimTypeName AS [Type]
				,CONCAT(N'₹ ',ClaimAmount) AS ClaimAmount
		FROM	[dbo].[ClaimDetails] CD
		JOIN	[dbo].[ClaimTypeDetails] CTD             
			ON	CTD.ClaimTypeId = CD.ClaimTypeId
		WHERE	CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate 
		AND		RequestedBy = @LoginUserId
		AND		ClaimStatusId = 2
		AND		CD.CompanyId = @CompanyId
		UNION ALL
		SELECT	'Advance' AS ModuleName
				,CONVERT(NVARCHAR(50),AdvanceDate,106) AS [Date]
				,CONCAT(N'₹ ',AdvanceAmount) AS AdvanceAmount
				,CONCAT(N'₹ ',ISNULL (DueAmount,0)) AS DueAmount
		FROM	[dbo].[AdvanceDetails]
		WHERE	CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate
		AND		EmployeeId = @LoginUserId
		AND		AdvanceStatusId = 2
		AND		CompanyId = @CompanyId
		UNION ALL
		SELECT	'Loan' AS ModuleName
				,CONVERT(NVARCHAR(50),LoanDate,106) AS [Date]
				,CONCAT(N'₹ ',LoanAmount) AS LoanAmount
				,CONCAT(N'₹ ',ISNULL(DueAmount,0)) AS DueAmount
		FROM	[dbo].[LoanDetails]
		WHERE	CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate 
		AND		EmployeeId = @LoginUserId
		AND		LoanStatusId = 2
		AND		CompanyId = @CompanyId;
		
		SELECT	@Status    = 1 
				,@Message  = 'Mail Sent Successfully.';	
	END TRY
	BEGIN CATCH
		SELECT	@Status    = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*==================================================================================================================
	DECLARE	@S_Status	 BIT
			,@M_Message	 NVARCHAR(500);

	EXEC [dbo].[USP_GetPayrollApprovalMailDetails]	@LoginUserId		= 3
													,@FromDate			= '2025-01-01'
													,@Status			= @S_Status	 OUT
													,@Message			= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

=================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetPayrollsettingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================================================  
 Procedure Name		:	[DBO].[USP_GetPayrollsettingDetails]
 Description		:	Procedure used to retrive the companyDetails (When click on the Setting in Side NavigationBar
						And When click on Edit option in Setting screen)
 Input Parameter	:	@LoginUserId, @CompanyId
 Output Parameters	:	@Status, @Message
 Author				:	Tetrosoft
 Created on			:	22-02-2023
 Version			:	1.0 
 Comment			:	1.Get the CompanyDetails with the columns of  IsPayrollManual,PayrollDate,SalaryPaymentMode	,PayslipModel,Currency,AdvanceLimit	,AdvanceMaxAmount,LoanLimit,LoanMaxAmount		
						  for the given PayrollsettingId.
						2. Get all the CompanyWorkingdayDetails with the columns of CompanyWorkingDayId,Day,IsWorkingDay	 
						   CompanyId for the given CompanyId.
						2.1 Then return the output Parameters values as @Status = 1 and @Message = NULL.
==================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetPayrollsettingDetails]
(	
	@LoginUserId				INT
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT

	SELECT	@CompanyId = CompanyId
	FROM	EmployeeDetails
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status    = 1 
				,@Message  = NULL;

		-- Result set for Company PayrollSettingDetails.
		SELECT	 IsPayrollManual
				,ProcessingMonth
				,CONVERT(NVARCHAR(20),PayrollDate,105) AS PayrollDate
				,PSD.PaymentTypeId
				,PaymentTypeName 
				,PayslipModel		
				,CurrencyId			
				,AdvanceLimit		
				,LoanLimit		
				,PSD.PayTypeId
				,PayTypeName 
				,NoticePeriod
		FROM	[dbo].[PayrollSettingDetails] PSD
		LEFT JOIN	[dbo].[PaymentTypeDetails] PMTD
			ON	PSD.PaymentTypeId = PMTD.PaymentTypeId
		LEFT JOIN	[dbo].[PayTypeDetails] PTD
			ON	PSD.PayTypeId = PTD.PayTypeId
		WHERE	PSD.CompanyId = @CompanyId;

		-- Result set for CompanyBankDetails.
		SELECT	CompanyBankId
				,BankName
				,AccountType
				,AccountName
				,AccountNumber
				,IFSCCode
		FROM	[dbo].[CompanyBankDetails]
		WHERE	CompanyId = @CompanyId;

		-- Result set for Company OtherSettingDetails.
		SELECT	CompanySettingId	
				,IsEmpIdAutomatic	
				,EmpIdPrefix		
				,EmpIdStartingFrom	
		FROM	[DBO].[CompanySettingDetails]
		WHERE	CompanyId = @CompanyId;

		-- Result set for CompanyWorkingDayDetails.
		SELECT	CompanyWorkingDayId	
				,[Day]				
				,IsWorkingDay
				,CompanyId			
		FROM	[DBO].[CompanyWorkingDayDetails]	
		WHERE	CompanyId = @CompanyId;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [DBO].[USP_GetPayrollsettingDetails]	@LoginUserId			 = 1
												,@Status				 = @S_Status	OUT
												,@Message				 = @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[PayrollSettingDetails];
=============================================================================================================================*/



GO
/****** Object:  StoredProcedure [dbo].[USP_GetPaySlipDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetPaySlipDetails]
 Description		:	Procedure used to retrive the PayslipDetails (When Click on the Payslip Info in side navigation bar 
						and when click on Payslip Column link on grid from UI)
 Input Parameter	:	@LoginUserId, @PaySlipId, @Year						
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	27-12-2023
 Version			:	1.0 
 Comment			:	1. If the given @PaySlipId is NULL,then
						   1.1 When LoginUserId as a SuperAdmin Get the counter box values Total Earning,Total Deduction,Net Pay,No of MonthProcessed to show in Counter box.
						   1.2 Get all the PayslipDetails have the columns of Payslipid, Month, EmployeeId, Name, Designation Payslip to show in Grid.
						   1.3 When LoginUserId as a GeneralUser Get the counter box values Total Earning, Total Deduction, Net Pay, No of Month Processed to show in Counter box.
						   1.4 Get all the PayslipDetails have the columns of Payslipid, Month, EmployeeId,TotalEarning,TotalDeduction,NetPay Payslip to show in Grid.												   
						   1.5 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						2. If the given @PaySlipId is NOT NULL,then 
							2.1 Get the particular PayslipDetails have the columns of PaySlipId, Month, CompanyLogo, CompanyName, CompanyAddress,PaySlip, Name,EmployeeCompanyId,Designation,
								EffectiveWorkDays, LOP, PaymentMode, EmployeeBankName, AccountNumber,PANNo, UANNumber, PFNumber, BasicPay, HRA, OtherAllowance, Claim, Bonus,PF,ESI,
								IncomeTax, LeaveDeduction, AdvanceAmount, LoanAmount, OtherDeduction, TotalEarning, TotalDeduction, NetPay, InWords for  the given PayslipId to show in Document.
							2.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
===============================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetPaySlipDetails]
(
	@LoginUserId	INT
	,@PaySlipId		INT
	,@Month			INT
	,@Year			INT
	,@Status		BIT           OUT
	,@Message		NVARCHAR(200) OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE	@LoginUserId	INT	= 1
	--		,@PaySlipId		INT	= NULL
	--		,@Month			INT	= 1
	--		,@Year			INT	= 2025
	
	DECLARE	@CompanyId				TINYINT
			,@EarningsCount			INT
			,@UserGroupId			TINYINT
			,@PayrollStatus			NVARCHAR(100)
			,@DeductionsCount		INT
			,@SQL					NVARCHAR(MAX)
			,@EarningsColumns		NVARCHAR(MAX)
			,@DeductionsColumns		NVARCHAR(MAX);

	SELECT	@CompanyId	= CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	 
	SELECT	@EarningsCount = COUNT(SalaryComponentsId)
	FROM	[dbo].[SalaryComponentsDetails]
	WHERE	SalaryComponentTypeId = 1 
	AND		StatusActive = 1;

	SELECT	@DeductionsCount = COUNT(SalaryComponentsId)
	FROM	[dbo].[SalaryComponentsDetails]
	WHERE	SalaryComponentTypeId = 2 
	AND		StatusActive = 1;
	 
	BEGIN TRY	
		IF @PaySlipId IS NULL	
		BEGIN
			IF @UserGroupId = 1
			BEGIN
				--ResultSet For counterboxes 
				SELECT	CONCAT(N'₹ ',ISNULL(SUM(TotalEarnings),0)) AS 'Total Earning'
						,CONCAT(N'₹ ',ISNULL(SUM(TotalDeduction),0)) AS 'Total Deduction'
						,CONCAT(N'₹ ',ISNULL(SUM(NetPay),0)) AS 'Net Pay'
						,ISNULL(COUNT(DISTINCT (CONVERT(VARCHAR,[Month])+CONVERT(VARCHAR,[Year]))),0) AS 'No of Month Processed'
				FROM    [dbo].[PaySlipDetails_1]
				WHERE	[Month] = @Month
				AND		[Year] = @Year;
				
				IF EXISTS(SELECT 1 FROM [dbo].[PaySlipDetails_1] WHERE [Month] = @Month AND [Year] = @Year AND PayslipStatus = 1)
				BEGIN
					SET @PayrollStatus = 'Processed'
				END
				ELSE IF NOT EXISTS(SELECT 1 FROM [dbo].[PaySlipDetails_1] WHERE [Month] = @Month AND [Year] = @Year)
				BEGIN  
					SET @PayrollStatus = 'Generate';
				END 
				ELSE IF (( SELECT COUNT(DISTINCT PayslipStatus) FROM [dbo].[PaySlipDetails_1] WHERE [Month] = @Month AND [Year] = @Year) = 2)
				BEGIN
					SET @PayrollStatus = 'ReGenerate'
				END;
				
				SELECT	DISTINCT @PayrollStatus AS PayrollStatus   
						,CONCAT(CASE WHEN COUNT(TotalEmployees) = 0 THEN '0 %'
									ELSE CAST((COUNT(ProcessedEmployees) * 100.0) / (COUNT(TotalEmployees)) AS INT) 
								END, ' %') AS PayslipProgress 
					FROM	(	SELECT	EmployeeId, COUNT(DISTINCT EmployeeId) AS TotalEmployees
								FROM	EmployeeDetails 
								GROUP BY EmployeeId
							) AS ED
					LEFT JOIN  (	SELECT	EmployeeId, COUNT(DISTINCT EmployeeId) AS ProcessedEmployees
									FROM	PaySlipDetails_1 
									WHERE	[Month] = @Month 
									AND		[Year] = @Year
									GROUP BY EmployeeId
								) AS PD 
						ON	ED.EmployeeId = PD.EmployeeId;
						 					 
				SELECT	PD.PaySlipId
						,ISNULL(CONCAT(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01') ) , ' - ' ,CONVERT(NVARCHAR(30), PD.[Year])),'') AS [Month]
						,ED.EmployeeCompanyId AS EmployeeId 
						,ED.FirstName AS [Name]	
						,DesignationName 
						,CASE	WHEN PayslipStatus = 1 THEN CONCAT(ED.EmployeeCompanyId,' - ',(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01'))) ,'-',(CONVERT(NVARCHAR(30), PD.[Year]))) 		
								ELSE '' 
						 END AS PaySlip	
						 ,CASE	WHEN PayslipStatus = 1 THEN 'Processed'
								ELSE 'Not-Processed' 
						 END AS [Status]
						,CASE	WHEN PayslipStatus = 1 THEN 'Green'
								ELSE 'Red'
						END AS [Status_Colour]
				FROM	[dbo].[PaySlipDetails_1] PD
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON	PD.EmployeeId = ED.EmployeeId
				LEFT JOIN	[dbo].[DesignationDetails] DD
					ON	ED.DesignationId = DD.DesignationId
				WHERE	PD.[Month] = @Month
				AND		PD.[Year] = @Year;				
			END
			ELSE
			BEGIN
				SELECT	CONCAT(N'₹ ',ISNULL(SUM(TotalEarnings),0)) AS 'Total Earning'
						,CONCAT(N'₹ ',ISNULL(SUM(TotalDeduction),0)) AS 'Total Deduction'
						,CONCAT(N'₹ ',ISNULL(SUM(NetPay),0)) AS 'Net Pay'
						,ISNULL(COUNT(DISTINCT (CONVERT(VARCHAR,[Month])+CONVERT(VARCHAR,[Year]))),0) AS 'No of Month Processed'
				FROM    [dbo].[PaySlipDetails_1]
				WHERE   EmployeeId = @LoginUserId
				AND		[Year] = @Year; 

				SELECT	DISTINCT @PayrollStatus AS PayrollStatus   
						,CONCAT(CASE WHEN COUNT(12) = 0 THEN '0 %'
									ELSE CAST((COUNT(ProcessedEmployees) * 100.0) / (COUNT(12)) AS INT) 
						END, ' %') AS PayslipProgress 
				FROM	(	SELECT	EmployeeId, COUNT(DISTINCT EmployeeId) AS TotalEmployees
							FROM	EmployeeDetails 
							GROUP BY EmployeeId
						) AS ED
				LEFT JOIN  (	SELECT	EmployeeId, COUNT(DISTINCT EmployeeId) AS ProcessedEmployees
								FROM	PaySlipDetails_1 
								WHERE	[Year] = @Year
								AND		EmployeeId = @LoginUserId
								GROUP BY EmployeeId
							) AS PD 
					ON	ED.EmployeeId = PD.EmployeeId;				
			
				--ResultSet For EmployeeGrid 			 
				SELECT	DISTINCT ISNULL(PD.PaySlipId,0) AS PaySlipId 
						,ISNULL(CONCAT(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01') ) , ' - ' ,CONVERT(NVARCHAR(30), PD.[Year])),'') AS [Month]
						,ED.EmployeeCompanyId 
						,TotalEarnings
						,TotalDeduction
						,NetPay
						,CASE	WHEN PayslipStatus = 1 THEN CONCAT(ED.EmployeeCompanyId,' - ',(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01'))) ,'-',(CONVERT(NVARCHAR(30), PD.[Year]))) 		
								ELSE '' 
						 END AS PaySlip				
						,CASE	WHEN PayslipStatus = 1 THEN 'Processed'
								ELSE 'Not-Processed' 
						 END AS [Status]
						,CASE	WHEN PayslipStatus = 1 THEN 'Green'
								ELSE 'Red'
						END AS [Status_Colour]
				FROM	[dbo].[EmployeeDetails] ED
				JOIN	[dbo].[PaySlipDetails_1] PD
					ON	ED.EmployeeId = PD.EmployeeId
				WHERE   PD.EmployeeId  = @LoginUserId
				AND		PD.[Year] = @Year;
			END
		END
		ELSE -- EmployeeBankDetails EmployeeSalaryDetails
		BEGIN
			SELECT	PayslipId 
					,CompanyLogo 
					,CompanyName
					,CompanyAddress
					,CONCAT(CompanyCity, ' - ', CompanyZipcode)  AS CompanyState
					,'Payslip for the month of ' AS PaySlip
					,FORMAT(DATEFROMPARTS(PD.[Year], PD.[Month], 1), 'MMMM yyyy') AS [Month]
					,CONCAT(FirstName, ' ', LastName) AS [Name]	
					,EmployeeCompanyId AS EmployeeId
					,BranchName AS [Location]
					,DepartmentName AS Department
					,DesignationName AS Designation
					,FORMAT(CAST(DateOfBirth AS DATE), 'dd-MMM-yyyy') AS DateOfBirth
					,FORMAT(CAST(DateOfJoining AS DATE), 'dd-MMM-yyyy') AS DateOfJoining
					,FORMAT(DATEFROMPARTS(YEAR(PD.CreatedDate), MONTH(PD.CreatedDate), 1), 'MMMM yyyy') AS PayPeriod
					,CONVERT(NVARCHAR(50), PD.CreatedDate, 103) AS PayDate
					,EffectiveWorkDays  
					,CONVERT(NUMERIC(3,1),LOP) AS LOPDays  
					,EmployeeBankName AS BankName
					,EBD.AccountNumber 
					,PANNo AS PANnumber
					,UANNumber 
					,PFNumber
				    ,N'₹' AS Currency
					,NetPay 
					,CASE WHEN PD.NetPay < 0 THEN '' ELSE [dbo].[UDF_GetNumToWord](PD.NetPay) END AS InWords
			FROM	[dbo].[CompanyDetails] CD
			JOIN	(	SELECT	PayslipId, CompanyId, NetPay, EmployeeId, [Year]
								,[Month], CreatedDate, EffectiveWorkDays, LOP 
						FROM	[dbo].[PayslipDetails_1]
						WHERE	PayslipId = @PayslipId
					) AS PD
				ON	CD.CompanyId = PD.CompanyId
			JOIN	[dbo].[EmployeeDetails] ED
				ON	PD.EmployeeId = ED.EmployeeId
			JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId
			LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD
				ON	ED.EmployeeId = EPD.EmployeeId
			LEFT JOIN	[dbo].[EmployeePFDetails] EPFD
				ON	ED.EmployeeId = EPFD.EmployeeId
			LEFT JOIN	[dbo].[EmployeeBankDetails] EBD
				ON	ED.EmployeeId = EBD.EmployeeId;

			DROP TABLE IF EXISTS #EarningColumns;
			WITH EarningColumnDetails 
			AS	(
					SELECT	COLUMN_NAME
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Earning_%'
				),
			EarningComponentDetails
			AS	(
					SELECT	ComponentName
							,SalaryComponentTypeId
							,ROW_NUMBER() OVER (PARTITION BY SalaryComponentTypeId ORDER BY SalaryComponentsId) AS ColumnNumber
							,'Earnings' AS ComponentType
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1
					AND		SalaryComponentTypeId = 1
				)
			SELECT	ECD.COLUMN_NAME AS PayslipColumn
					,ECCD.ComponentName AS SalaryComponent
					,ECCD.ComponentType
			INTO	#EarningColumns
			FROM	EarningColumnDetails ECD
			JOIN	EarningComponentDetails ECCD
				ON	ECD.ColumnNumber = ECCD.ColumnNumber
				AND ECCD.ComponentType = 'Earnings'
			UNION ALL
			SELECT	'ClaimAmount' AS ClaimAMount
					,'ClaimAmount' AS ClaimAMount
					,'Earnings' AS ComponentType
			UNION ALL
			SELECT	'OtherEarnings' AS OtherEarnings
					,'OtherEarnings' AS OtherEarnings
					,'Earnings' AS ComponentType
			UNION ALL
			SELECT	'TotalEarnings' AS TotalEarnings
					,'TotalEarnings' AS TotalEarnings
					,'Earnings' AS ComponentType;

			DROP TABLE IF EXISTS #DeductionColumns;
			;WITH DeductionColumnDetails
			AS	(
					SELECT	COLUMN_NAME
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Deduction_%'
				),
			DeductionComponentDetails
			AS	(
					SELECT	ComponentName
							,SalaryComponentTypeId
							,ROW_NUMBER() OVER (PARTITION BY SalaryComponentTypeId ORDER BY SalaryComponentsId) AS ColumnNumber
							,'Deductions' AS ComponentType
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1
					AND		SalaryComponentTypeId = 2
				)
			SELECT	DCD.COLUMN_NAME AS PayslipColumn
					,DCCD.ComponentName AS SalaryComponent
					,DCCD.ComponentType
			INTO	#DeductionColumns
			FROM	DeductionColumnDetails DCD
			JOIN	DeductionComponentDetails DCCD
				ON	DCD.ColumnNumber = DCCD.ColumnNumber 
				AND	DCCD.ComponentType = 'Deductions'
			UNION ALL
			SELECT	'AdvanceAmount' AS AdvanceAmount
					,'AdvanceAmount' AS AdvanceAmount
					,'Deductions' AS ComponentType
			UNION ALL
			SELECT	'LoanDueAmount' AS LoanDueAmount
					,'LoanDueAmount' AS LoanDueAmount
					,'Deductions' AS ComponentType
			UNION ALL
			SELECT	'OtherDeduction' AS OtherDeduction
					,'OtherDeduction' AS OtherDeduction
					,'Deductions' AS ComponentType
			UNION ALL
			SELECT	'TotalDeduction' AS TotalDeduction
					,'TotalDeduction' AS TotalDeduction
					,'Deductions' AS ComponentType

			SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			FROM	#EarningColumns 
			WHERE	ComponentType = 'Earnings';

			SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			FROM	#DeductionColumns 
			WHERE	ComponentType = 'Deductions';

			SET @SQL 
				= '	WITH PivotedData 
					AS	(
							SELECT	PayslipId, ' + @EarningsColumns + ', ' + @DeductionsColumns + '
							FROM	PayslipDetails_1
							WHERE	PayslipId = @PaySlipId
						)
					SELECT	CM.SalaryComponent AS ComponentsName, ISNULL(U.ActualValue,0) AS Amount, CM.ComponentType AS EarningsName
					FROM	PivotedData
							UNPIVOT
							(
								ActualValue 
								FOR	PayslipColumn 
								IN	(' + @EarningsColumns + ', ' + @DeductionsColumns + ')
							) AS U
					FULL OUTER JOIN (SELECT * FROM #EarningColumns UNION ALL SELECT * FROM #DeductionColumns) AS CM
						ON	CM.PayslipColumn = U.PayslipColumn;';

			PRINT @SQL; 
			EXEC SP_EXECUTESQL @SQL, N'@PaySlipId INT', @PaySlipId;
		END
		SELECT	@Status    = 1 
				,@Message  = NULL;			
	END TRY	
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===========================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);
	
	EXEC [dbo].[USP_GetPaySlipDetails]	@LoginUserId	=	1
										,@PaySlipId		=	4
										,@Month			=	1
										,@Year			=	2025
										,@Status		=	@Status		OUT
										,@Message		=	@Message	OUT;	

	SELECT @Status AS STATUS, @Message AS MESSAGE;
		                              
	SELECT	* 
	FROM	[dbo].[PayslipDetails_1];

	TRUNCATE TABLE PayslipDetails_1

	SELECT * FROM PayrollSettingDetails 
	SELECT	* 
	FROM	[dbo].[EmployeeDetails];

==================================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_GetPaySlipDetails_Test]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetPaySlipDetails_Test]
 Description		:	Procedure used to retrive the PayslipDetails (When Click on the Payslip Info in side navigation bar 
						and when click on Payslip Column link on grid from UI)
 Input Parameter	:	@LoginUserId, @PaySlipId, @Year						
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	27-12-2023
 Version			:	1.0 
 Comment			:	1. If the given @PaySlipId is NULL,then
						   1.1 When LoginUserId as a SuperAdmin Get the counter box values Total Earning,Total Deduction,Net Pay,No of MonthProcessed to show in Counter box.
						   1.2 Get all the PayslipDetails have the columns of Payslipid, Month, EmployeeId, Name, Designation Payslip to show in Grid.
						   1.3 When LoginUserId as a GeneralUser Get the counter box values Total Earning, Total Deduction, Net Pay, No of Month Processed to show in Counter box.
						   1.4 Get all the PayslipDetails have the columns of Payslipid, Month, EmployeeId,TotalEarning,TotalDeduction,NetPay Payslip to show in Grid.												   
						   1.5 Then return the output Parameters values as @Status = 1 and @Message = NULL.
						2. If the given @PaySlipId is NOT NULL,then 
							2.1 Get the particular PayslipDetails have the columns of PaySlipId, Month, CompanyLogo, CompanyName, CompanyAddress,PaySlip, Name,EmployeeCompanyId,Designation,
								EffectiveWorkDays, LOP, PaymentMode, EmployeeBankName, AccountNumber,PANNo, UANNumber, PFNumber, BasicPay, HRA, OtherAllowance, Claim, Bonus,PF,ESI,
								IncomeTax, LeaveDeduction, AdvanceAmount, LoanAmount, OtherDeduction, TotalEarning, TotalDeduction, NetPay, InWords for  the given PayslipId to show in Document.
							2.2 Then return the output Parameters values as @Status = 1 and @Message = NULL.
===============================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetPaySlipDetails_Test]
(
	@LoginUserId	INT
	,@PaySlipId		INT
	,@Year			INT
	,@Status		BIT           OUT
	,@Message		NVARCHAR(200) OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId				TINYINT
			,@EarningsCount			INT
			,@UserGroupId			TINYINT
			,@PayrollStatus			NVARCHAR(100)
			,@DeductionsCount		INT
			,@SQL					NVARCHAR(MAX) = ''
			,@EarningsColumns		NVARCHAR(MAX) = ''
			,@DeductionsColumns		NVARCHAR(MAX) = '';

	SELECT	@CompanyId	= CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	 
	SELECT	@EarningsCount = COUNT(SalaryComponentsId)
	FROM	SalaryComponentsDetails
	WHERE	SalaryComponentTypeId = 1 
	AND		StatusActive = 1;

	SELECT	@DeductionsCount = COUNT(SalaryComponentsId)
	FROM	SalaryComponentsDetails
	WHERE	SalaryComponentTypeId = 2 
	AND		StatusActive = 1;

	BEGIN TRY	
		IF @PaySlipId IS NULL	
		BEGIN
			IF @UserGroupId = 1
			BEGIN
				--ResultSet For counterboxes 
				SELECT   ISNULL(SUM(TotalEarnings),0) AS 'Total Earning'
						,ISNULL(SUM(TotalDeduction),0) AS 'Total Deduction'
						,ISNULL(SUM(NetPay),0) AS 'Net Pay'
						,ISNULL(COUNT(DISTINCT (CONVERT(VARCHAR,[Month])+CONVERT(VARCHAR,[Year]))),0) AS 'No of Month Processed'
				FROM    PaySlipDetails_1; 

				--PaySlip Processed's status
				IF (( SELECT COUNT(DISTINCT PayslipStatus) FROM PaySlipDetails_1 ) = 1)
				BEGIN
					IF EXISTS(SELECT 1 FROM PaySlipDetails_1 WHERE PayslipStatus = 1)
					BEGIN
						SET @PayrollStatus = 'Processed'
					END
					ELSE IF EXISTS(SELECT 1 FROM PaySlipDetails_1 WHERE PayslipStatus = 2)
					BEGIN 
						SET @PayrollStatus = 'Generate'
					END
				END
				ELSE IF (( SELECT COUNT(DISTINCT PayslipStatus) FROM PaySlipDetails_1 ) = 2)
				BEGIN
					SET @PayrollStatus = 'ReGenerate'
				END

				-- Resdultset for Payslip status
				SELECT	@PayrollStatus AS PayrollStatus;
				
				SELECT	PD.PaySlipId
						,ISNULL(CONCAT(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01') ) , ' - ' ,CONVERT(NVARCHAR(30), PD.[Year])),'') AS [Month]
						,ED.EmployeeCompanyId AS EmployeeId 
						,ED.FirstName AS [Name]	
						,DesignationName 
						,CASE	WHEN PayslipStatus = 1 THEN CONCAT(ED.EmployeeCompanyId,' - ',(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01'))) ,'-',(CONVERT(NVARCHAR(30), PD.[Year]))) 		
								ELSE '' 
						 END AS PaySlip	
						 ,CASE	WHEN PayslipStatus = 1 THEN 'Processed'
								ELSE 'Not-Processed' 
						 END AS [Status]
						,CASE	WHEN PayslipStatus = 1 THEN 'Green'
								ELSE 'Red'
						END AS [Status_Colour]
				FROM	PaySlipDetails_1 PD
				JOIN	EmployeeDetails ED
					ON	PD.EmployeeId = ED.EmployeeId
				LEFT JOIN	DesignationDetails DD
					ON	ED.DesignationId = DD.DesignationId
				WHERE	PD.[Year] = @Year;				
			END
			ELSE
			BEGIN
				SELECT   ISNULL(SUM(TotalEarnings),0) AS 'Total Earning'
						,ISNULL(SUM(TotalDeduction),0) AS 'Total Deduction'
						,ISNULL(SUM(NetPay),0) AS 'Net Pay'
						,ISNULL(COUNT(DISTINCT (CONVERT(VARCHAR,[Month])+CONVERT(VARCHAR,[Year]))),0) AS 'No of Month Processed'
				FROM    PaySlipDetails_1
				WHERE   EmployeeId = @LoginUserId
				AND		[Year] = @Year; 

				SELECT @PayrollStatus AS PayrollStatus;
			
				--ResultSet For EmployeeGrid 			 
				SELECT	DISTINCT ISNULL(PD.PaySlipId,0) AS PayslipId 
						,ISNULL(CONCAT(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01') ) , ' - ' ,CONVERT(NVARCHAR(30), PD.[Year])),'') AS [Month]
						,ED.EmployeeCompanyId 
						,TotalEarnings
						,TotalDeduction
						,NetPay
						,CASE	WHEN PayslipStatus = 1 THEN CONCAT(ED.EmployeeCompanyId,' - ',(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01'))) ,'-',(CONVERT(NVARCHAR(30), PD.[Year]))) 		
								ELSE '' 
						 END AS PaySlip				
						,CASE	WHEN PayslipStatus = 1 THEN 'Processed'
								ELSE 'Not-Processed' 
						 END AS [Status]
						,CASE	WHEN PayslipStatus = 1 THEN 'Green'
								ELSE 'Red'
						END AS [Status_Colour]
				FROM	EmployeeDetails ED
				JOIN	PaySlipDetails_1 PD
					ON	ED.EmployeeId = PD.EmployeeId
				WHERE   PD.EmployeeId  = @LoginUserId
				AND		PD.[Year] = @Year;
			END
		END
		ELSE -- EmployeeBankDetails EmployeeSalaryDetails
		BEGIN
			SELECT	PayslipId 
					,CompanyLogo 
					,CompanyName
					,CONCAT(CompanyAddress,' ',CompanyCity, ' - ', CompanyZipcode) AS CompanyAddress
					,CONCAT('Payslip for the month of ', ISNULL(CONCAT(DATENAME(MONTH, DATEFROMPARTS(PD.[Year],PD.[Month],'01') ) , ' ' ,CONVERT(NVARCHAR(30), PD.[Year])),'')) AS PaySlip
					,FORMAT(DATEFROMPARTS(PD.[Year], PD.[Month], 1), 'MMMM yyyy') AS [Month]
					,CONCAT(FirstName, ' ', LastName) AS [Name]	
					,EmployeeCompanyId AS EmployeeId
					,DesignationName AS Designation
					,FORMAT(CAST(DateOfBirth AS DATE), 'dd-MMM-yyyy') AS DateOfBirth
					,FORMAT(CAST(DateOfJoining AS DATE), 'dd-MMM-yyyy') AS DateOfJoining
					,FORMAT(DATEFROMPARTS(YEAR(PD.CreatedDate), MONTH(PD.CreatedDate), 1), 'MMMM yyyy') AS PayPeriod
					,CONVERT(NVARCHAR(50), PD.CreatedDate, 103) AS PayDate
					,EffectiveWorkDays  
					,CONVERT(NUMERIC(3,1),LOP) AS LOPDays  
					,EmployeeBankName AS BankName
					,EBD.AccountNumber 
					,PANNo AS PANnumber
					,UANNumber 
					,PFNumber
					,NetPay 
					,[dbo].[UDF_GetNumToWord](PD.NetPay) AS InWords
			FROM	CompanyDetails CD
			JOIN	(SELECT	* FROM PaySlipDetails_1 WHERE PayslipId = 3) AS PD
				ON	CD.CompanyId = PD.CompanyId
			JOIN	EmployeeDetails ED
				ON	PD.EmployeeId = ED.EmployeeId
			LEFT JOIN	DesignationDetails DSD
				ON	ED.DesignationId = DSD.DesignationId
			LEFT JOIN	EmployeePersonalDetails EPD
				ON	ED.EmployeeId = EPD.EmployeeId
			LEFT JOIN	EmployeePFDetails EPFD
				ON	ED.EmployeeId = EPFD.EmployeeId
			LEFT JOIN	EmployeeBankDetails EBD
				ON	ED.EmployeeId = EBD.EmployeeId;

			DROP TABLE IF EXISTS #ColumnMapping;

			WITH OrderedEarnings 
			AS (
					SELECT	COLUMN_NAME
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Earning_%'
				),
			OrderedDeductions 
			AS	(
					SELECT	COLUMN_NAME
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Deduction_%'
				),
			OrderedComponents
			AS	(
					SELECT	ComponentName
							,SalaryComponentTypeId
							,ROW_NUMBER() OVER (PARTITION BY SalaryComponentTypeId ORDER BY SalaryComponentsId) AS ColumnNumber
							,CASE WHEN SalaryComponentTypeId = 1 THEN 'Earnings' ELSE 'Deductions' END AS ComponentType
					FROM	SalaryComponentsDetails
					WHERE	StatusActive = 1
				)
			SELECT	E.COLUMN_NAME AS PayslipColumn
					,C.ComponentName AS SalaryComponent
					,C.ComponentType
			INTO	#ColumnMapping
			FROM	OrderedEarnings E
			JOIN	OrderedComponents C
				ON	E.ColumnNumber = C.ColumnNumber
				AND C.ComponentType = 'Earnings'
			UNION ALL
			SELECT	D.COLUMN_NAME AS PayslipColumn
					,C.ComponentName AS SalaryComponent
					,C.ComponentType
			FROM	OrderedDeductions D
			JOIN	OrderedComponents C 
				ON	D.ColumnNumber = C.ColumnNumber 
				AND	C.ComponentType = 'Deductions';

-- Generate dynamic column lists for Earnings and Deductions
SELECT @EarningsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
FROM #ColumnMapping WHERE ComponentType = 'Earnings';

SELECT @DeductionsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
FROM #ColumnMapping WHERE ComponentType = 'Deductions';

-- Ensure NULL handling for STRING_AGG
SET @EarningsColumns = ISNULL(@EarningsColumns, '');
SET @DeductionsColumns = ISNULL(@DeductionsColumns, '');

-- Construct the dynamic SQL query
SET @SQL = 
'	SELECT CM.SalaryComponent AS ComponentsName, 
			U.ActualValue AS Amount, 
			CM.ComponentType AS EarningsName,
			NULL AS ClaimAmount, NULL AS OtherEarnings, NULL AS TotalEarnings,
			NULL AS AdvanceAmount, NULL AS LoanDueAmount, NULL AS OtherDeduction,
			NULL AS TotalDeduction, NULL AS NetPay
	FROM (
			SELECT PayslipId, ' + @EarningsColumns + ' 
			FROM PayslipDetails_1
			WHERE PayslipId = @PayslipId
		) AS PivotedData
	UNPIVOT
	(
		ActualValue FOR PayslipColumn IN (' + @EarningsColumns + ')
	) AS U
	JOIN #ColumnMapping CM ON U.PayslipColumn = CM.PayslipColumn

UNION ALL

	SELECT CM.SalaryComponent AS ComponentsName, 
			U.ActualValue AS Amount, 
			CM.ComponentType AS EarningsName,
			ClaimAmount, OtherEarnings, TotalEarnings,
			AdvanceAmount, LoanDueAmount, OtherDeduction,
			TotalDeduction, NetPay
	FROM (
			SELECT PayslipId, ' + @DeductionsColumns + ', 
				   ClaimAmount, OtherEarnings, TotalEarnings, 
				   AdvanceAmount, LoanDueAmount, OtherDeduction, 
				   TotalDeduction, NetPay
			FROM PayslipDetails_1
			WHERE PayslipId = @PayslipId
		) AS PivotedData
	UNPIVOT
	(
		ActualValue FOR PayslipColumn IN (' + @DeductionsColumns + ')
	) AS U
	JOIN #ColumnMapping CM ON U.PayslipColumn = CM.PayslipColumn;';

-- Debugging: Print the query
PRINT @SQL;  

-- Execute the dynamic SQL query
EXEC SP_EXECUTESQL @SQL, N'@PayslipId INT', @PayslipId;


			--SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			--FROM	#ColumnMapping 
			--WHERE	ComponentType = 'Earnings';

			--SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			--FROM	#ColumnMapping
			--WHERE	ComponentType = 'Deductions';

			--SET @SQL	
			--	= '	SELECT	CM.SalaryComponent AS ComponentsName, U.ActualValue AS Amount, CM.ComponentType AS EarningsName
			--				,ISNULL(ClaimAmount,0) AS ClaimAmount, ISNULL(OtherEarnings,0) AS OtherEarnings
			--				,ISNULL(TotalEarning,0) AS TotalEarning, ISNULL(AdvanceAmount,0) AS AdvanceAmount
			--				,ISNULL(LoanDueAmount,0) AS LoanDueAmount, ISNULL(OtherDeduction,0) AS OtherDeduction
			--				,ISNULL(TotalDeduction,0) AS TotalDeduction, ISNULL(NetPay,0) AS NetPay
			--		FROM	(
			--					SELECT	PayslipId, ' + @EarningsColumns + ', ' + @DeductionsColumns + ' 
			--							,ClaimAmount, OtherEarnings, TotalEarning, AdvanceAmount, LoanDueAmount
			--							,OtherDeduction, TotalDeduction, NetPay
			--					FROM	PayslipDetails_1
			--					WHERE	PayslipId = @PayslipId
			--				) AS PivotedData
			--			UNPIVOT
			--			(
			--				ActualValue 
			--				FOR	PayslipColumn 
			--				IN	(' + @EarningsColumns + ', ' + @DeductionsColumns + ')
			--			) AS U
			--		JOIN	#ColumnMapping CM ON U.PayslipColumn = CM.PayslipColumn;';

			--PRINT @SQL;  
			--EXEC SP_EXECUTESQL @SQL, N'@PayslipId INT', @PayslipId;
		END
		SELECT	@Status    = 1 
				,@Message  = NULL;			
	END TRY	
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
