/*===============================================================================================================================  
 Procedure Name		:	[USP_GetSalaryComponentsDetails]
 Description		:	Procedure used to retrive the BranchDetails (When click on BranchIcon in Setting Screen And
																	 When click on Edit Option in BranchInfo on settings Screen)
 Input Parameter	:	@LoginUserId, @BranchId
 Output Parameters	:	@Status, @Message
 Author				:	Tharani T
 Created on			:	30-09-2024
 Version			:	1.0 
 Comment			:	
=================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetSalaryComponentsDetails]
(
	@LoginUserId			INT
	,@SalaryComponentsId	TINYINT
	,@status				BIT				OUT
	,@Message				NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		IF (@SalaryComponentsId IS NULL)
		BEGIN
			SELECT	SalaryComponentsId
					,CASE WHEN SalaryComponentTypeId = 1 THEN 'Earnings' ELSE 'Deduction' END AS SalaryComponentsType
					,ComponentName	
					,CalculationTypeName
					,(CAST(EarningAmount AS VARCHAR(20)) + ' ' + EarningType + ' of ' + CalculationTypeName) AS EarningAmount
					,StatusActive
			FROM	[dbo].[SalaryComponentsDetails] SCD
			LEFT JOIN	[dbo].[CalculationTypeDetails] CTD
				ON	SCD.CalculationTypeId = CTD.CalculationTypeId
			WHERE	SCD.CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
		SELECT	SalaryComponentsId
				,ComponentName
				,SalaryComponentTypeId
				,SCD.ComponentAliasNameId
				,ComponentAliasName
				,SCD.CalculationTypeId	
				,CalculationTypeName
				,EarningAmount	
				,EarningType
				,StatusActive
		FROM	[dbo].[SalaryComponentsDetails] SCD
		LEFT JOIN	[dbo].[ComponentAliasNameDetails] SAD
			ON	SCD.ComponentAliasNameId = SAD.ComponentAliasNameId
		LEFT JOIN	[dbo].[CalculationTypeDetails] CTD
			ON	SCD.CalculationTypeId = CTD.CalculationTypeId
		WHERE	SalaryComponentsId = @SalaryComponentsId 
		AND		SCD.CompanyId = @CompanyId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetSalaryComponentsDetails]	 @LoginUserId			= 1
												,@SalaryComponentsId	= 1
												,@Status				= @S_Status  OUT
												,@Message				= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[SalaryComponentsDetails];

======================================================================================================================*/

GO
