/*===============================================================================================================================  
 Procedure Name		:	[USP_GetSalaryStructureDetails]
 Description		:	Procedure used to retrive the SalaryStructureDetails
 Input Parameter	:	@LoginUserId, @SalaryStructureId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	03-10-2024
 Version			:	1.0 
 Comment			:	1. Get the SalaryStructureDetails.
=================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetSalaryStructureDetails]
(
	@LoginUserId			INT
	,@SalaryStructureId		INT
	,@status				BIT				OUT
	,@Message				NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		IF @SalaryStructureId IS NULL
		BEGIN
			SELECT	SalaryStructureId
					,SalaryStructureName 
			FROM	[dbo].[SalaryStructureDetails]
			WHERE	CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			SELECT	SalaryStructureId
					,SalaryStructureName
			FROM	[dbo].[SalaryStructureDetails]
			WHERE	SalaryStructureId = @SalaryStructureId 
			AND		CompanyId = @CompanyId;
		
			SELECT	SSMD.SalaryStructureComponentMappingId
					,SSMD.SalaryStructureId
					,SSMD.SalaryComponentsId
					,SSMD.IsActive
					,SCD.ComponentName
					,CASE WHEN SCD.SalaryComponentTypeId = 1 THEN 'Earnings' 
						ELSE 'Deduction' END AS SalaryComponentsType
			FROM	[dbo].[SalaryComponentsDetails] SCD 
			LEFT JOIN	(	SELECT	*
							FROM	[dbo].[SalaryStructureComponentMappingDetails] 
							WHERE	SalaryStructureId = @SalaryStructureId
						) AS SSMD
				ON	SSMD.SalaryComponentsId = SCD.SalaryComponentsId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetSalaryStructureDetails]	@LoginUserId			= 1
												,@SalaryStructureId		= 4
												,@Status				= @S_Status  OUT
												,@Message				= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[SalaryComponentsDetails];
	SELECT	* 
	FROM	[dbo].[SalaryStructureDetails];

======================================================================================================================*/
GO
