/*===============================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_GetShiftDetails]
 Description		:	Procedure Used to retrieve the ShiftDetails (When click on Setting Info SideNavigation Bar
						And click on Edit option in Grid from UI)
 Input Parameter	:	@LoginUserId, @ShiftId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	27-02-2024
 Version			:	1.0
 Comment			:	1. If the given @ShiftId is NULL,then 
							1.1 Get the All ShiftDetails have the columns of ShiftId, ShiftName, StartTime, EndTime, Description
								to show in Grid.		
							1.2 Then return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If the given @ShiftId is NOT NULL, then 
							2.1 Get the particular ShiftDetails have the Columns of ShiftId, ShiftName, StartTime, EndTime
								,ShiftDescription for the given @ShiftId to show in Grid.					    
							2.2 Then return the output Parameter values as @Status= 1 and @Message = NULL.
 ================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetShiftDetails]
(	
	@LoginUserId	INT
	,@ShiftId		TINYINT
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variable.
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[DBO].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		-- If the Given @ShiftNameId is NULL, then Get the ShiftNameDetails.		
		IF @ShiftId IS NULL	
		BEGIN
			SELECT	ShiftId
					,ShiftName
					,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
					,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
					,CASE WHEN IsActive = 1 THEN 'Active' ELSE 'InActive' END AS [Status]
					,CASE WHEN IsActive = 1 THEN 'Green' ELSE 'Red' END AS Status_Colour
					--,ISNULL(ShiftDescription,'') AS [Description]
			FROM	[dbo].[ShiftDetails]
			WHERE	CompanyId = @CompanyId
			ORDER BY ShiftId DESC, IsActive DESC;
		END
		ELSE
		BEGIN
			-- Get the Particular ShiftNameDetails for the given @ShiftNameId.	
			SELECT	ShiftId
					,ShiftName
					,ISNULL(FORMAT(CONVERT(DATETIME,StartTime),'hh:mm tt'),'') AS StartTime
					,ISNULL(FORMAT(CONVERT(DATETIME,EndTime),'hh:mm tt'),'') AS EndTime
					,ISNULL(ShiftDescription,'') AS ShiftDescription
					,IsActive
					,IsAllowanceApplicable
					,AllowanceAmount
			FROM	[dbo].[ShiftDetails]
			WHERE	ShiftId = @ShiftId 
			AND		CompanyId = @CompanyId;
		END
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetShiftDetails]	@LoginUserId	= 15
										,@ShiftId		= NULL
										,@Status		= @S_Status	OUT
										,@Message		= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	
	SELECT	* 
	FROM	[dbo].[ShiftDetails];
	Employeedetails
==================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_GetShiftStartEndTimeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================  
 Procedure Name		:	[dbo].[USP_GetShiftStartEndTimeDetails]
 Description		:	Procedure used to retrive the Shift StartTime EndTime 
												(When click on ShiftName in Dropdown in Insert & Update Shift Screen)
 Input Parameter	:	@LoginUserId, @ShiftId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	21-08-2024
 Version			:	1.0 
 Comment			:	1. Logic will get the Shift StartTime, EndTime, TotalHours for the Given @ShiftId
						2. Then return the output Parameters values as @Status = 1 and @Message = NULL.
=================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_GetShiftStartEndTimeDetails]
(
	@LoginUserId	INT
	,@ShiftId		INT
	,@status		BIT				OUT
	,@Message		NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
    SELECT
        CASE 
            WHEN CAST(LEFT(StartTime, 2) AS INT) = 0 THEN '12' + RIGHT(LEFT(StartTime, 5), 3) + ' AM'
            WHEN CAST(LEFT(StartTime, 2) AS INT) < 12 THEN LEFT(StartTime, 5) + ' AM'
            WHEN CAST(LEFT(StartTime, 2) AS INT) = 12 THEN LEFT(StartTime, 5) + ' PM'
            ELSE RIGHT(CONCAT('0', CAST(CAST(LEFT(StartTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(StartTime, 5), 3) + ' PM'
        END AS StartTime,
        CASE 
            WHEN CAST(LEFT(EndTime, 2) AS INT) = 0 THEN '12' + RIGHT(LEFT(EndTime, 5), 3) + ' AM'
            WHEN CAST(LEFT(EndTime, 2) AS INT) < 12 THEN LEFT(EndTime, 5) + ' AM'
            WHEN CAST(LEFT(EndTime, 2) AS INT) = 12 THEN LEFT(EndTime, 5) + ' PM'
            ELSE RIGHT(CONCAT('0', CAST(CAST(LEFT(EndTime, 2) AS INT) - 12 AS VARCHAR(2))), 2) + RIGHT(LEFT(EndTime, 5), 3) + ' PM'
        END AS EndTime,
        CASE 
            WHEN DATEDIFF(MINUTE, 
                CONVERT(DATETIME, StartTime, 108), 
                CASE 
                    WHEN EndTime < StartTime THEN DATEADD(DAY, 1, CONVERT(DATETIME, EndTime, 108))
                    ELSE CONVERT(DATETIME, EndTime, 108)
                END
            ) % 60 = 0 
            THEN RIGHT('0' + CAST(DATEDIFF(HOUR, 
                CONVERT(DATETIME, StartTime, 108), 
                CASE 
                    WHEN EndTime < StartTime THEN DATEADD(DAY, 1, CONVERT(DATETIME, EndTime, 108))
                    ELSE CONVERT(DATETIME, EndTime, 108)
                END
            ) AS VARCHAR(2)), 2) + ':00 Hrs'
            ELSE RIGHT('0' + CAST(DATEDIFF(HOUR, 
                CONVERT(DATETIME, StartTime, 108), 
                CASE 
                    WHEN EndTime < StartTime THEN DATEADD(DAY, 1, CONVERT(DATETIME, EndTime, 108))
                    ELSE CONVERT(DATETIME, EndTime, 108)
                END
            ) AS VARCHAR(2)), 2) + ':' +
                 RIGHT('0' + CAST(DATEDIFF(MINUTE, 
                CONVERT(DATETIME, StartTime, 108), 
                CASE 
                    WHEN EndTime < StartTime THEN DATEADD(DAY, 1, CONVERT(DATETIME, EndTime, 108))
                    ELSE CONVERT(DATETIME, EndTime, 108)
                END
            ) % 60 AS VARCHAR(2)), 2) + ' Hrs'
        END AS TotalHours
    FROM [dbo].[ShiftDetails]
    WHERE ShiftId = @ShiftId;

    SELECT @Status = 1, @Message = NULL;
END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_GetShiftStartEndTimeDetails]	@LoginUserId	= 11
													,@ShiftId		= 13
													,@Status		= @S_Status  OUT
													,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[ShiftDetails];

======================================================================================================================*/
GO
