/*===============================================================================================================================  
 Procedure Name		:	[USP_GetStatutoryPFDetails]
 Description		:	Procedure used to retrive the BranchDetails (When click on BranchIcon in Setting Screen And
																	 When click on Edit Option in BranchInfo on settings Screen)
 Input Parameter	:	@LoginUserId, @BranchId
 Output Parameters	:	@Status, @Message
 Author				:	Tharani T
 Created on			:	16-09-2024
 Version			:	1.0 
 Comment			:	
=================================================================================================================================*/
CREATE         PROCEDURE [dbo].[USP_GetStatutoryPFDetails]
(
	@LoginUserId	INT
	,@EmployeePFId	TINYINT
	,@status		BIT				OUT
	,@Message		NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId  TINYINT;
	
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status	  = 1   
				,@Message = NULL;		

		--If the given BranchId is Null, then get all the BranchDetails.
		IF (@EmployeePFId IS NULL)
		--Result set For Grid 
		BEGIN
			SELECT	EmployeePFId
					,EmployeePFNumber
					,DeductionCycle
					,EmployeeContributionRateId
					,EmployeeContributionRate
					,EmployerContributionRateId
					,EmployerContributionRate	
					,VoluntaryProvidentFund
			FROM	[dbo].[PFDetails]
			WHERE	CompanyId = @CompanyId;
		END
		ELSE 
		BEGIN
			--If the given BranchId is Not Null, then get the particular BranchDetails.
			SELECT	EmployeePFId
					,EmployeePFNumber
					,DeductionCycle
					,EmployeeContributionRateId
					,EmployeeContributionRate
					,EmployerContributionRateId
					,EmployerContributionRate	
					,VoluntaryProvidentFund
			FROM	[dbo].[PFDetails]
			WHERE	EmployeePFId=@EmployeePFId AND 
					CompanyId = @CompanyId;
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
