/* ====================================================================================================================      
	Procedure Name		: [USP_GetUserAccessDetails]	      
	Description			: Procedure used to get the UserAccessDetails (When click on userAccess in Right side top of the screen)  
	Input Parameters	: @LoginUserId    
	Output Parameters	: @Status, @Message      
	Author				: Nithya.M     
	Created On			: 11-03-2023      
	Version				: 1.0     
	Comments			: 1.Get the User Access Detail.
====================================================================================================================*/         
CREATE   PROCEDURE [dbo].[USP_GetUserAccessDetails]      
(      
	@LoginUserId 	INT            
	,@Status		BIT				OUT      
	,@Message		NVARCHAR(500)	OUT      
)      
AS      
BEGIN         
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		--Get The User Access Details.	
		SELECT	ModuleId
				,ModuleName
				,ModuleActionId
				,ModuleActionName
				,IsParent
				,ParentModuleId
				,[SuperAdmin] AS SuperAdmin
				,ISNULL([Admin],0) AS [Admin]
				,ISNULL([GeneralUser],0) AS GeneralUser
		FROM
				( SELECT	DISTINCT MAD.ModuleId
							,MD.ModuleName
							,UGAMD.ModuleActionId
							,MAD.ModuleActionName
							,IsParent
							,ParentModuleId
							,UGD.UserGroupName 
							,CONVERT(INT,UGAMD.IsActive) AS IsActive
					FROM	[dbo].[ModuleDetails] MD
					JOIN	[dbo].[ModuleActionDetails] MAD
						ON	MD.ModuleId = MAD.ModuleId
					JOIN	[dbo].[UserGroupActionMappingDetails] UGAMD
						ON	MAD.ModuleActionId = UGAMD.ModuleActionId 
					JOIN	[dbo].[UserGroupDetails] UGD
						ON	UGAMD.UserGroupId = UGD.UserGroupId	
					WHERE	MAD.IsActive = 1
				) AS ST
			PIVOT
				(
					MAX		(IsActive)
					FOR		UserGroupName 
					IN		([SuperAdmin],[Admin],[GeneralUser])
				) AS PT;

		SELECT	@Status   = 1      
				,@Message = NULL;      
         
	END TRY      
	BEGIN CATCH      
		SELECT	@Status   = 0      
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));      
	END CATCH       
END            
/*============================================================================================      
	DECLARE @Status		BIT      
			,@Message	NVARCHAR(500) 
			
	EXEC [dbo].[USP_GetUserAccessDetails]	@LoginUserId 	= 1         
											,@Status		= @Status	OUT      
											,@Message		= @Message	OUT;
											
	SELECT @Status AS 'STATUS', @Message  AS 'MESSAGE';

	 SELECT	* 
	FROM	[dbo].[EmployeeDetails];
	SELECT * FROM ModuleActionDetails
	SELECT * FROM UserGroupActionMappingDetails;
	SELECT * FROM UserGroupDetails;
==============================================================================================*/		
GO
