/*======================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertAdvanceDetails]
 Description		:	Procedure used to create the new AdvanceDetails (When Click on Save Button in Advance Screen popup)
 Input Parameter	:	@LoginUserId,@EmployeeId,@AdvanceDate,@AdvanceAmount,@DueAmount,@Description
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	30-08-2023
 Version			:	1.0 
 Comment			:	1. If the Entered AdvanceDate along with EmployeeId is already exist,then
							1.1 Through the error message as @Status = 0 And @Message = "Entered AdvanceDate along with EmployeeId is already Exists'
						2. If the Entered AdvanceDate along with EmployeeId is not exist,then
							2.1 Procedure will insert 
									AdvanceDate		 AS	@AdvanceDate
									,EmployeeId		 AS	@EmployeeId
									,AdvanceAmount	 AS	@AdvanceAmount
									,DueAmount		 AS	@DueAmount
									,AdvanceStatusId AS @AdvanceStatusId
									,Description	 AS	@Description
									,CompanyId		 AS	@CompanyId
									,CreatedBy		 AS	@EmployeeId
									,CreatedDate	 AS	GETDATE() into the AdvanceDetails for the new advance.								
						3.Then through the success Message as @Status = 1 and @Message = 'The New AdvanceDetails have been Created Successfully'.
=========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertAdvanceDetails]
(
	@LoginUserId		INT
	,@EmployeeId		INT
	,@AdvanceDate		DATETIME
	,@AdvanceAmount		NUMERIC(11,2)
	,@DueAmount			NUMERIC(11,2)	
    ,@Description		NVARCHAR(500)
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	 
	DECLARE	@CompanyId		TINYINT
			,@AdvanceId		INT;
		   
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		BEGIN TRAN
			INSERT INTO [dbo].[AdvanceDetails] (AdvanceDate, EmployeeId, AdvanceAmount, DueAmount, AdvanceStatusId
						,CompanyId, CreatedBy)
			VALUES		(@AdvanceDate
						,@EmployeeId
						,@AdvanceAmount
						,@DueAmount
						,2
						,@CompanyId
						,@LoginUserId);

			SELECT @AdvanceId = SCOPE_IDENTITY();

			IF EXISTS (SELECT 1 FROM [dbo].[AdvanceDetails] WHERE AdvanceId = @AdvanceId AND AdvanceStatusId = 2)
			BEGIN
				INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
							,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
							,SMS_To, IsAuto, CompanyId, CreatedBy)					
				SELECT	@AdvanceId
						,'Advance'
						,1
						,'Owner'
						,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME( ED.EmployeeCompanyId), ' has requesting '
							,'Advance Amount of ', N'₹ ',CONVERT(NVARCHAR(30),AD.AdvanceAmount), ' on '
							,CONVERT(NVARCHAR(30),AD.AdvanceDate,106),'.')
						,3
						,UD.EmployeeId
						,'Open'
						,'Open'
						,UD.ContactNo
						,1
						,@CompanyId
						,@LoginUserId
				FROM	[dbo].[AdvanceDetails] AS AD
				JOIN	[dbo].[EmployeeDetails] AS ED
					ON	ED.EmployeeId = AD.EmployeeId
				LEFT JOIN	(	SELECT	ED.EmployeeId
										,ED.FirstName
										,ED.EmployeeCompanyId
										,ED.ContactNo
								FROM	[dbo].[EmployeeDetails] AS ED 
								LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
									ON	ED.EmployeeId = RPD.ReportingPersonId
								WHERE	RPD.EmployeeId = @LoginUserId
							) AS  UD
					ON	ED.EmployeeId = AD.EmployeeId
				WHERE	AdvanceId = @AdvanceId 
				AND		AD.CompanyId  = @CompanyId;
			END

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'New Advance added Successfully.';  

		IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
		BEGIN 
			SELECT	Email AS FromMail
					,SMTPNumber
			FROM	NoticationCategoryDetails
			WHERE	IsActive = 1;

			-- Result set for Email sended.
			SELECT  RPD.OfficialEmail AS ToMail	
					,'Request for Advance Approval' AS [Subject]
					,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
					,CONCAT('I am writing to formally request Advance on ', CONVERT(NVARCHAR(50), @AdvanceDate, 106)
						,' and the Advance amount is ',@AdvanceAmount, '. The request has been submitted by {' , ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId
						, '] } for your approval.') AS SecondLine
					,'I kindly request you to review and approve my Advance at your earliest convenience.' AS ThirdLine
					,'Please let me know if you require any further information regarding my request.' AS FourthLine
					,'Thank You.' AS FifthLine
					,' ' AS SixthLine
			FROM	[dbo].[EmployeeDetails] ED 
			LEFT JOIN [dbo].[EmployeeDetails] RPD 
				ON	ED.ReportingPersonId = RPD.EmployeeId
			WHERE	ED.EmployeeId = @EmployeeId;
		END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);	
		
	EXEC [dbo].[USP_InsertAdvanceDetails]	@LoginUserId		= 1 
											,@EmployeeId		= 3
											,@AdvanceDate		= '2025-01-06'				
											,@AdvanceAmount		= 1000		
											,@DueAmount			= 500
											,@Description		= ' '
											,@Status			= @S_Status	 OUT			
											,@Message			= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;										

	SELECT	*
	FROM [dbo].[AdvanceDetails];
	SELECT	*
	FROM [dbo].[LeaveStatusDetails];
	SELECT * FROM PayrollSettingDetails

	DELETE FROM [dbo].[AdvanceDetails] WHERE AdvanceId = 14
===================================================================================================================================================================*/
GO
