/*=============================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertAttendanceMachineDetails]
 Description		:	Procedure used to insert the new AttendanceMachineDetails
													(When Click on Insert Button in AttendanceMachine Info PopupPage)
 Input Parameter	:	@LoginUserId, @AttendanceMachineName, @SerialNo, @MachineDescription.
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	15-06-2024
 Version			:	1.0 
 Comment			:	1. Insert into Attendance Machine Details 
						2. Then through the Success POPUP message as 'Record Added Successfully.'.
=========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertAttendanceMachineDetails]
(
	@LoginUserId						INT
	,@AttendanceMachineName				NVARCHAR(100)       
	,@SerialNo							NVARCHAR(100) 
	,@MachineDescription				NVARCHAR(200)
	,@IsActive							BIT
	,@TVP_EmployeeDeviceMappingDetails	TVP_EmployeeDeviceMappingDetails	READONLY
	,@Status							BIT									OUT	
	,@Message							NVARCHAR(500)						OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variables.
	DECLARE @CompanyId				TINYINT
			,@AttendanceMachineId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF EXISTS (SELECT 1 FROM [dbo].[AttendanceMachineDetails] WHERE CompanyId = @CompanyId AND AttendanceMachineName = @AttendanceMachineName)
		BEGIN 
			SELECT	@Status		= 0
					,@Message	= 'Given MachineName is already Exists.'
			RETURN;
		END 
		ELSE 
		BEGIN       
			BEGIN TRAN
				INSERT INTO [dbo].[AttendanceMachineDetails] (AttendanceMachineName, SerialNo, MachineDescription
							,CompanyId, IsActive, CreatedBy, CreatedDate)
				VALUES		(@AttendanceMachineName	
							,@SerialNo				
							,@MachineDescription
							,@CompanyId
							,@IsActive
							,@LoginUserId
							,GETDATE());

				SELECT	@AttendanceMachineId = SCOPE_IDENTITY();

				INSERT INTO [dbo].[EmployeeDeviceMappingDetails](EmployeeId, AttendanceMachineId, IsActive, IsBlock
							,CreatedBy, CreatedDate)
				SELECT		EmployeeId, @AttendanceMachineId, [Status], 0, @LoginUserId, GETDATE()
				FROM		@TVP_EmployeeDeviceMappingDetails;

				-- Result set for Biomatric Machine Details.
				SELECT	CONCAT('TetroPAY/',ED.CompanyId,'/',ED.EmployeeId) AS EmployeeId
						,CONCAT(FirstName,' ',LastName) AS EmployeeName
						,CardNumber
						,SerialNo
				FROM	(	SELECT	AttendanceMachineId, SerialNo
							FROM	[dbo].[AttendanceMachineDetails] AMD
							WHERE	AttendanceMachineId = @AttendanceMachineId
							AND		CompanyId = @CompanyId
						) AS AMD
				LEFT JOIN [dbo].[EmployeeDeviceMappingDetails] EDMD 
					ON	EDMD.AttendanceMachineId = AMD.AttendanceMachineId AND IsACtive = 1
				LEFT JOIN [dbo].[EmployeeDetails] ED	
				ON   ED.EmployeeId = EDMD.EmployeeId;
				
				-- Result set for ESSL Application Credential.
				SELECT	ESSLUserName
						,ESSLPassword
						,WebAddress
				FROM	[dbo].[ESSlCredentialDetails]
				WHERE	CompanyId = @CompanyId;

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status		= 1
					,@Message	= 'Record Added Successfully.'
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status							BIT
			,@M_Message							NVARCHAR(500)
			,@TVP_EmployeeDeviceMappingDetails	TVP_EmployeeDeviceMappingDetails;
			
	INSERT INTO @TVP_EmployeeDeviceMappingDetails (EmployeeId, Status)
	VALUES		(4, 1)
				,(5, 0)
				--,(5, 0);

	EXEC [dbo].[USP_InsertAttendanceMachineDetails]	@LoginUserId						= 1
													,@AttendanceMachineName				= 'Machine 2'
													,@SerialNo							= 'MACHINE_102'
													,@MachineDescription				= 'Machine 2 - JPN22400511'
													,@IsActive							= 1 
													,@TVP_EmployeeDeviceMappingDetails	= @TVP_EmployeeDeviceMappingDetails
													,@Status							= @S_Status	 OUT
													,@Message							= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[AttendanceMachineDetails];
	SELECT	*
	FROM	[dbo].[EmployeeDeviceMappingDetails];
	SELECT	*
	FROM	[dbo].[EmployeeDetails];
======================================================================================================================================*/
GO
