											,@CandidateExperience		= 2.5
											,@CurrentCompanyName		= 'Tetrosoft'
											,@CurrentCTC				= 200000
											,@ExpectCTC					= 500000
											,@IsImmediateJoiner			= 0
											,@ExpJoiningDate			= '2025-04-10'
											,@Description				= 'This candidate is ok for in our company.'
											,@TVP_AttachmentDetails		= @TVP_AttachmentDetails
