/****** Object:  StoredProcedure [dbo].[USP_InsertClaimDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[USP_InsertClaimDetails]
 Description		:	Procedure used to insert the new Claimdetails 
																(When Click on Insert Button in ClaimInfo PopupPage)
 Input Parameter	:	@LoginUserId, @ClaimDate, @ClaimTypeId, @RequestedBy, @ClaimDescription
						,@ClaimAmount, @TVP_AttachmentDetails
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	01-11-2023
 Version			:	1.0 
 Comment			:	1. If the Entered ClaimTypeId along with ClaimDescription is already exist,then
							1.1 Through the error message as @Status = 0 And @Message = "Entered ClaimTypeId along with ClaimDescription is already Exists"
						2. If the Entered ClaimTypeId along with ClaimDescription is not exist,then
						3. Insert into ClaimDetails tables with	 ClaimDate			AS @ClaimDate
																,ClaimTypeId		AS @ClaimTypeId
																,ClaimAmount		AS @ClaimAmount
																,ClaimDescription	AS @ClaimDescription
																,CompanyId			AS @CompanyId
																,CreatedBy			AS @LoginUserId
																,CreatedDate		AS GETDATE() into the ClaimDetails for the New Claim.
						4.Then through the Success Popup message as'The New ClaimDetails has been Created Successfully'.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertClaimDetails]
(
	@LoginUserId				INT		
	,@ClaimDate					DATE
	,@ClaimTypeId				TINYINT
	,@RequestedBy				INT
	,@ClaimDescription			NVARCHAR(2000)
	,@ClaimAmount				NUMERIC(18,2)
	,@TVP_AttachmentDetails		TVP_AttachmentDetails	READONLY
	,@Status					BIT					 	OUT	
	,@Message					NVARCHAR(500)		 	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId				TINYINT
			,@ClaimId				INT 
			,@LeaveStatusName		NVARCHAR(50);

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeavestatusDetails];	

	BEGIN TRY				
		--If exist,Return the error message as @Status = 0 And @Message = "Entered ClaimTypeId along with ClaimDescription is already Exists"
        IF EXISTS( SELECT 1 FROM [dbo].[ClaimDetails] WHERE CONVERT(DATE,ClaimDate) = CONVERT(DATE,@ClaimDate) AND ClaimTypeId = @ClaimTypeId AND ClaimDescription = @ClaimDescription)
		BEGIN
			SELECT	 @Status  = 0
					,@Message = 'Entered ClaimType and Date is already Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				--Procedure will insert the new ClaimDetails
				INSERT INTO [dbo].[ClaimDetails](ClaimDate, ClaimTypeId, ClaimAmount, ClaimDescription
							,RequestedBy, ClaimStatusId, CompanyId, CreatedBy)
				VALUES		(@ClaimDate			
							,@ClaimTypeId		
							,@ClaimAmount		
							,@ClaimDescription	
							,@RequestedBy
							,2
							,@CompanyId
							,@LoginUserId);
		
			SELECT @ClaimId = SCOPE_IDENTITY();

			--Procedure will insert in the AttachmentDetails.
			INSERT INTO	[dbo].[AttachmentDetails] (ModuleRefId, ModuleName, AttachmentFileName, AttachmentFilepath
						,CreatedBy, CreatedDate)
			SELECT		@ClaimId, 'Claim', AttachmentFileName, AttachmentFilepath, @LoginUserId, GETDATE() 
			FROM		@TVP_AttachmentDetails;
			
			IF @LeaveStatusName = 'Submitted'
			BEGIN
				INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName, IsInternal
							,DetailedMessage, SMSStatus, EmployeeId, NotificationStatus, SMS_To, IsAuto, MessageTo
							,MessageStatusId, CompanyId, CreatedBy, CreatedDate)					
				SELECT	@ClaimId
						,'Claim'
						,1
						,CONCAT('Dear Sir, I am ', [Name], ' I need to claim the Claim Amount of ', N'₹ ',@ClaimAmount
							,' For using in this purpose of ',ClaimTypeName,' .')
						,'Open'
						,UD.EmployeeId
						,'Open'
						,UD.ContactNo
						,1
						,'Owner'
						,3
						,1
						,@LoginUserId
						,GETDATE()
				FROM	[dbo].[ClaimDetails] AS CD
				JOIN	[DBO].[ClaimTypeDetails] CTD
					ON	CD.ClaimTypeId = CTD.ClaimTypeId
				JOIN	[DBO].[EmployeeDetails] ED
					ON	CD.RequestedBy = ED.EmployeeId
				JOIN	(	SELECT	ED.EmployeeId
									,ED.FirstName
									,ED.EmployeeCompanyId
									,ED.ContactNo
									,RPD.FirstName AS [Name]
							FROM	[dbo].[EmployeeDetails] AS ED 
							LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
								ON	ED.EmployeeId = RPD.ReportingPersonId
							WHERE	RPD.EmployeeId = @LoginUserId
						) AS  UD
					ON	ED.EmployeeId = CD.RequestedBy
				WHERE	ClaimId = @ClaimId
				AND		CD.CompanyId  = @CompanyId;
			END

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'ClaimDetails are Added Successfully.'; 
				
		IF @LeaveStatusName = 'Submitted'
		BEGIN 
			IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				-- Result set for Email sended.
				SELECT  DISTINCT RPD.OfficialEmail AS ToMail	
						,'Request for Claim Approval' AS [Subject]
						,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
						,CONCAT('I am writing to formally request Claim on ', CONVERT(NVARCHAR(50), @ClaimDate, 106)
							,' for ', ClaimTypeName	,', the claim amount is ',@ClaimAmount,'. The request has been submitted by {' , ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId
							, '] } for your approval.') AS SecondLine
						,'I kindly request you to review and approve my Claim at your earliest convenience.' AS ThirdLine
						,'Please let me know if you require any further information regarding my request.' AS FourthLine
						,'Thank You.' AS FifthLine
						,' ' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN [dbo].[EmployeeDetails] RPD 
					ON	ED.ReportingPersonId = RPD.EmployeeId
				LEFT JOIN [dbo].[ClaimDetails] CD 
					ON	ED.EmployeeId = CD.RequestedBy
				LEFT JOIN [dbo].[ClaimTypeDetails] CTD 
					ON	CD.ClaimTypeId = CTD.ClaimTypeId
				WHERE	ED.EmployeeId = @RequestedBy;
			END 
		END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
