/****** Object:  StoredProcedure [dbo].[USP_InsertCompensatoryOffDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:	[dbo].[USP_InsertCompensatoryOffDetails]
 Description		:	Procedure used to retrieve the CompensatoryOffDetails	
																(When Click on save button in CompensatoryOff popup)
 Input Parameters	:	@LoginUserId, @EmployeeId, @CompensatoryOffDate, @IsHalfDay, @NoOfDays
						,@CompensatoryOffDescription.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	23-08-2023
 Version			:	1.0 
 Comment			:	1. If the Given CompensatoryOffDate along with EmployeeId is already Exist, then
							1.1 Through the error message as @Status = 0 And 
									@Message = "Entered CompOffDate is already Exist.'
						2. If the CompensatoryOffDate along with EmployeeId is Not exist, then 
							2.1 Insert into CompensatoryOffDetails table have the columns of 
									EmployeeId					AS @EmployeeId
									,CompensatoryOffDate		AS @CompensatoryOffDate
									,IsHalfDay					AS @IsHalfDay
									,NoOfDays					AS @NoOfDays
									,CompensatoryOffDescription AS @CompensatoryOffDescription
									,CompensatoryOffStatusId	AS 2 (Submitted)
									,CreatedBy					AS @LoginUserId.
							2.2 Then through the success Message as @Status = 1 And 
									@Message = "New CompOffDetails have been Created Successfully.".
=========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertCompensatoryOffDetails]
(	
	@LoginUserId					INT
	,@EmployeeId					INT
	,@CompensatoryOffDate			DATE 
	,@IsHalfDay						BIT
	,@NoOfDays						INT
	,@CompensatoryOffDescription	NVARCHAR(200)
	,@Status						BIT				OUT	
	,@Message						NVARCHAR(500)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId				TINYINT
			,@CompensatoryOffId		INT
			,@LeaveStatusName		NVARCHAR(50);
   
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeavestatusDetails];

	BEGIN TRY	
		IF EXISTS(SELECT 1 FROM [dbo].[CompensatoryOffDetails] WHERE CompensatoryOffDate = @CompensatoryOffDate AND EmployeeId = @EmployeeId AND CompensatoryOffStatusId IN (1,2,3))
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Entered CompOffDate is already Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[CompensatoryOffDetails](EmployeeId, CompensatoryOffDate, IsHalfDay, NoOfDays
							,CompensatoryOffDescription, CompensatoryOffTypeId,	CompensatoryOffStatusId, CompanyId
							,CreatedBy)
				VALUES		(@EmployeeId
							,@CompensatoryOffDate
							,@IsHalfDay
							,CASE WHEN @IsHalfDay = 1 THEN 0.5 ELSE 1 END
							,@CompensatoryOffDescription
							,2
							,2
							,@CompanyId 
							,@LoginUserId);

				SELECT @CompensatoryOffId = SCOPE_IDENTITY();

				IF @LeaveStatusName = 'Submitted'
				BEGIN
					IF (	SELECT	COUNT(1) 
							FROM	[dbo].[NotificationDetails] 
							WHERE	NotificationModuleRefId = @CompensatoryOffId
							AND		NotificationTypeName = 'CompensatoryOff') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)					
						SELECT	@CompensatoryOffId
								,'CompensatoryOff'
								,1
								,'Owner'
								,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME( ED.EmployeeCompanyId), ' has requesting CompOff On '  
									,CONVERT(NVARCHAR(30),CD.CompensatoryOffDate,106),'.')
								,3
								,UD.EmployeeId
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[CompensatoryOffDetails] AS CD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = CD.EmployeeId
						JOIN	(	SELECT	ED.EmployeeId
											,ED.FirstName
											,ED.EmployeeCompanyId
									FROM	[dbo].[EmployeeDetails] AS ED 
									LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
										ON	ED.EmployeeId = RPD.ReportingPersonId
									WHERE	RPD.EmployeeId = @LoginUserId
								) AS  UD
							ON	ED.EmployeeId = CD.EmployeeId
						WHERE	CompensatoryOffId = @CompensatoryOffId 
						AND		CD.CompanyId	= @CompanyId;
					END		
				END
				
			IF @@TRANCOUNT >= 0
			COMMIT TRAN
			
			SELECT	@Status		= 1   
					,@Message	= 'New CompOffDetails have been Created Successfully.';  
					
			IF @LeaveStatusName = 'Submitted'
			BEGIN 
				IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					-- Result set for Email sended.
					SELECT  RPD.OfficialEmail AS ToMail	
							,'Request for CompOff Approval' AS [Subject]
							,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
							,CONCAT('I am writing to formally request CompOff on ', CONVERT(NVARCHAR(50), @CompensatoryOffDate, 106)
								,'. The request has been submitted by {' , ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId
								, '] } for your approval.') AS SecondLine
							,'I kindly request you to review and approve my CompOff at your earliest convenience.' AS ThirdLine
							,'Please let me know if you require any further information regarding my request.' AS FourthLine
							,'Thank You.' AS FifthLine
							,' ' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN [dbo].[EmployeeDetails] RPD 
						ON	ED.ReportingPersonId = RPD.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
		ROLLBACK TRAN;
	END CATCH
END
/*=======================================================================================================================================
	DECLARE	 @S_Status	BIT
		    ,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_InsertCompensatoryOffDetails]	@LoginUserId					= 3
													,@EmployeeId					= 3
													,@CompensatoryOffDate			= '2025-02-12'
													,@IsHalfDay						= 0
													,@NoOfDays						= 1
													,@CompensatoryOffDescription	= ' '
													,@Status						= @S_Status		OUT
													,@Message						= @M_Message	OUT;									   
 										  
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[CompensatoryOffDetails];
	SELECT	* 
	FROM	[dbo].[LeaveStatusDetails];


	EmployeeDetails
=========================================================================================================================================*/
GO
