/*=================================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_InsertEmployeeDetails]
 Description		:	Procedure used to Insert the EmployeeDetails ( 1. When click on Add employee button Employee screen 
																	   2. When click on Edit button Employee screen)
 Input Parameter	:	@LoginUserId, EmployeeCompanyId, @EmployeeImage ,@FirstName, @LastName	,@OfficialEmail	 ,@Password	,@Address, @City, @State, @Country
						, @Zipcode, @ContactNo, @DateOfJoining, @BranchId, @DepartmentId, @DesignationId, @ReportingPersonId, @UserGroupId, @IsLoginUser.					
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	17-08-2023
 Version			:	1.0 
 Comment			:	1. If the given EmployeeId Is Already Exists In EmployeeDetails Table, then Update the EmployeeDetails Table have the Column of
										EmployeeCompanyId	AS @EmployeeCompanyId
										,EmployeeImage		AS @EmployeeImage		
										,FirstName			AS @FirstName			
										,LastName 			AS @LastName 			
										,OfficialEmail 		AS @OfficialEmail 		
										,Password 			AS @Password 			
										,Address			AS @Address			
										,City 				AS @City 				
										,State 				AS @State 				
										,Country 			AS @Country 			
										,Zipcode			AS @Zipcode			
										,ContactNo			AS @ContactNo			
										,DateOfJoining		AS @DateOfJoining		
										,BranchId 			AS @BranchId 			
										,DepartmentId		AS @DepartmentId		
										,DesignationId		AS @DesignationId		
										,ReportingPersonId 	AS @ReportingPersonId 	
										,UserGroupId 		AS @UserGroupId 		
										,IsLoginUser		AS @IsLoginUser
										,UpdatedBy			AS @LoginUserId	
										,UpdatedDate		AS GETDATE() for the given EmployeeId.
							1.1 Then through the Output parameter @Status = 1 & @Message = 'The EmployeeDetails are Updated Sucessfully'
						2. OR Else Insert the given data's Into EmployeeDetails table have the columns of	
										EmployeeCompanyId	AS @EmployeeCompanyId
										,EmployeeImage		AS @EmployeeImage		
										,FirstName			AS @FirstName			
										,LastName 			AS @LastName 			
										,OfficialEmail 		AS @OfficialEmail 		
										,Password 			AS @Password 			
										,Address			AS @Address			
										,City 				AS @City 				
										,State 				AS @State 				
										,Country 			AS @Country 			
										,Zipcode			AS @Zipcode			
										,ContactNo			AS @ContactNo			
										,DateOfJoining		AS @DateOfJoining		
										,BranchId 			AS @BranchId 			
										,DepartmentId		AS @DepartmentId		
										,DesignationId		AS @DesignationId		
										,ReportingPersonId 	AS @ReportingPersonId 	
										,UserGroupId 		AS @UserGroupId 		
										,IsLoginUser		AS @IsLoginUser
										,CreatedBy			AS @LoginUserId	
										,CreatedDate		AS GETDATE()	
							2.1 Then through the Output parameter @Status = 1 & @Message = 'New EmployeeDetails have been Created Sucessfully'.
===============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertEmployeeDetails]
(
	@LoginUserId								INT
	,@EmployeeId								INT
	,@EmployeeCompanyId							NVARCHAR(100)
	,@EmployeeImage								NVARCHAR(500)
	,@FirstName									NVARCHAR(50)
	,@LastName									NVARCHAR(50)
	,@OfficialEmail								NVARCHAR(100)
	,@Password									NVARCHAR(50)
	,@Address									NVARCHAR(200)
	,@City										NVARCHAR(100)
	,@State										NVARCHAR(100)
	,@Country									NVARCHAR(100)
	,@Zipcode									NVARCHAR(100)
	,@ContactNo									NVARCHAR(100)
	,@DateOfJoining								DATETIME		
	,@BranchId									TINYINT			
	,@DepartmentId								TINYINT			
	,@DesignationId								TINYINT			
	,@ReportingPersonId							INT				
	,@UserGroupId								TINYINT			
	,@IsLoginUser								BIT	
	,@CardNumber								NVARCHAR(50)
	,@EmployeeTypeId							TINYINT
	,@GradeTypeId								TINYINT
	,@EmployeeStatusId							TINYINT
	,@TVP_EmployeeDeviceMappingDetails			TVP_EmployeeDeviceMappingDetails		READONLY
	,@Status									BIT										OUT
	,@Message									NVARCHAR(500)							OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId  = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		BEGIN TRAN  
			BEGIN
				-- If not exist, insert EmployeeCompanyId into the EmployeeDetails for the new Employee,Then through the success Message as @Status = 1 And @Message = "New EmployeeDetails have been created Sucessfully".
				INSERT INTO [dbo].[EmployeeDetails](EmployeeCompanyId, EmployeeImage, FirstName, LastName
							,OfficialEmail, [Password], [Address], City, [State], Country, Zipcode, ContactNo
							,DateOfJoining, BranchId, DepartmentId, DesignationId, ReportingPersonId, UserGroupId
							,IsLoginUser, CardNumber, EmployeeTypeId, GradeTypeId, EmployeeStatusId, CompanyId
							,CreatedBy, CreatedDate)				
				VALUES		(@EmployeeCompanyId
							,@EmployeeImage 
							,@FirstName
							,@LastName
							,@OfficialEmail	
							,@Password
							,@Address
							,@City
							,@State
							,@Country
							,@Zipcode
							,@ContactNo
							,@DateOfJoining		
							,@BranchId
							,@DepartmentId
							,@DesignationId
							,@ReportingPersonId
							,@UserGroupId
							,@IsLoginUser
							,@CardNumber
							,@EmployeeTypeId
							,@GradeTypeId
							,@EmployeeStatusId
							,@CompanyId
							,@LoginUserId
							,GETDATE());
							
				SELECT	@EmployeeId = SCOPE_IDENTITY();

				MERGE	[dbo].[EmployeeDeviceMappingDetails]	AS TARGET
				USING	@TVP_EmployeeDeviceMappingDetails		AS SOURCE
					ON	(TARGET.EmployeeDeviceMappingId = SOURCE.EmployeeDeviceMappingId
					AND	TARGET.EmployeeId = @EmployeeId)
				WHEN MATCHED THEN
				UPDATE 
				SET		TARGET.EmployeeId				= @EmployeeId
						,TARGET.AttendanceMachineId		= SOURCE.AttendanceMachineId
						,TARGET.IsActive				= 1
						,TARGET.IsBlock					= 0
						,TARGET.Updatedby				= @LoginUserId 
						,TARGET.UpdatedDate				= GETDATE()
				WHEN NOT MATCHED BY TARGET THEN
				INSERT	(EmployeeId, AttendanceMachineId, IsActive, IsBlock, CreatedBy, CreatedDate)
				VALUES	(@EmployeeId
						,SOURCE.AttendanceMachineId
						,1
						,0
						,@LoginUserId
						,GETDATE())
				WHEN NOT MATCHED BY SOURCE AND TARGET.EmployeeId = @EmployeeId THEN
				DELETE;

				-- Result set for Biomatric Machine Details.
				SELECT	CONCAT('TetroPAY/',ED.CompanyId,'/',ED.EmployeeId) AS EmployeeId
						,CONCAT(FirstName,' ',LastName) AS EmployeeName
						,CardNumber
						,SerialNo
				FROM	[dbo].[EmployeeDetails] ED	
				LEFT JOIN[dbo].[EmployeeDeviceMappingDetails] EAMMD 
					ON   ED.EmployeeId = EAMMD.EmployeeId
				LEFT JOIN [dbo].[AttendanceMachineDetails] AMD
					ON	EAMMD.AttendanceMachineId = AMD.AttendanceMachineId
				WHERE	ED.EmployeeId = @EmployeeId;

				-- Result set for ESSL Application Credential.
				SELECT	ESSLUserName
						,ESSLPassword
						,WebAddress
				FROM	[dbo].[ESSlCredentialDetails]
				WHERE	CompanyId = @CompanyId;
													
				SELECT	@Status = 1
						,@Message = 'Record added successfully.'

				DECLARE	@ClientId NVARCHAR(100);

				SELECT	@ClientId = SUBSTRING(DB_NAME(), CHARINDEX('_', DB_NAME()) + 1, LEN(DB_NAME()));

				IF @IsLoginUser = 1
				BEGIN
					IF NOT EXISTS(	SELECT	* FROM [TetroPAY].[dbo].[UserDetails] WHERE UserPhoneNumber = @ContactNo)
					BEGIN 
						INSERT INTO [TetroPAY].[dbo].[UserDetails] (FirstName, LastName, UserPhoneNumber, UserEmail
									,UserPassword, UserGroupId, ClientId, ChildEmployeeId, CompanyId, CreatedBy, CreatedDate)
						VALUES		(@FirstName
									,@LastName
									,@ContactNo
									,@OfficialEmail	
									,@Password
									,@UserGroupId
									,@ClientId
									,@EmployeeId
									,@CompanyId
									,@LoginUserId
									,GETDATE());
					END 
					ELSE 
					BEGIN 
						UPDATE	[TetroPAY].[dbo].[UserDetails]
						SET		FirstName			= @FirstName
								,LastName			= @LastName
								,UserPhoneNumber	= @ContactNo
								,UserEmail			= @OfficialEmail
								,UserPassword		= @Password
								,UserGroupId		= @UserGroupId
								,UpdatedBy			= @LoginUserId
								,UpdatedDate		= GETDATE()
						WHERE	UserPhoneNumber		= @ContactNo
						AND		CompanyId			= @CompanyId;
					END 
				END 
			END 
		IF @@TRANCOUNT > 0
		COMMIT TRAN

	END TRY
	BEGIN CATCH 
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message   = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	 @S_Status									BIT
			,@M_Message									NVARCHAR(500)
			,@TVP_EmpAttendanceMachineMappingDetails	TVP_EmpAttendanceMachineMappingDetails;

	INSERT INTO @TVP_EmpAttendanceMachineMappingDetails(AttendanceMachineId)
	VALUES		(2);
			
	EXEC [dbo].[USP_InsertEmployeeDetails]  @LoginUserId								=	15
											,@EmployeeId								=	null
											,@EmployeeCompanyId							=	'TET_101'
											,@EmployeeImage								=	'Employee/Default.jpg'
											,@FirstName									=	'Nithya'
											,@LastName									=	'Manivel'
