											,@Password									=	'Login123'
											,@Address									=	'Indra street,TNP'
											,@City										=	'Gobi'
											,@State										=	'TamilNadu'
											,@Country									=	'India'
											,@Zipcode									=	'628506'
											,@ContactNo									=	'9791002845'
											,@DateOfJoining								=	'12-04-2021'
											,@BranchId									=	1
											,@DepartmentId								=	33
											,@DesignationId								=	8
											,@ReportingPersonId							=	15
											,@UserGroupId								=	1
											,@IsLoginUser								=	14563
											,@CardNumber								= '567890'
											,@EmployeeTypeId							= 1
											,@GradeTypeId								= 1
											,@EmployeeStatusId							= 1
											,@TVP_EmpAttendanceMachineMappingDetails	= @TVP_EmpAttendanceMachineMappingDetails
											,@Status									= @S_Status  OUT
											,@Message									= @M_Message OUT

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE ;


SELECT	*
