/****** Object:  StoredProcedure [dbo].[USP_InsertEmployeeDetails_BulkInsert]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=================================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_InsertEmployeeDetails_BulkInsert]
 Description		:	Procedure used to Insert the EmployeeDetails 
															(When click on Save button Employee Bulk Upload screen)
 Input Parameter	:	@LoginUserId, @TVP_EmployeeDetails.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	01-02-2025
 Version			:	1.0 
 Comment			:	1. Record will insert into EmployeeDetails table by using the table valued parameter
							(@TVP_EmployeeDetails) for the Given @LoginUserId.
						2. Then through the Output parameter @Status = 1 & @Message = 'Record Added Successfully.'.
===============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertEmployeeDetails_BulkInsert]
(
    @LoginUserId				INT
	,@IsInsert					BIT
	,@TVP_EmployeeDetails		TVP_EmployeeDetails		READONLY
	,@Status					BIT						OUT
	,@Message					NVARCHAR(500)			OUT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CompanyId TINYINT;

    SELECT	@CompanyId = CompanyId
    FROM	[dbo].[EmployeeDetails]
    WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF @IsInsert = 0
		BEGIN
			DROP TABLE IF EXISTS #Result
			CREATE TABLE #Result 
			(
				EmployeeCompanyId		NVARCHAR(100)
				,FirstName				NVARCHAR(50) 
				,LastName				NVARCHAR(50) 
				,ContactNo				NVARCHAR(100)
				,OfficialEmail			NVARCHAR(100)
				,[Password]				NVARCHAR(50) 
				,DateOfJoining			DATETIME	
				,BranchName				NVARCHAR(50)
				,DepartmentName			NVARCHAR(50)
				,DesignationName		NVARCHAR(50)
				,ReportingPersonName	NVARCHAR(50)
				,UserGroupName			NVARCHAR(50)
				,EmployeeTypeName		NVARCHAR(100)
				,GradeTypeName			NVARCHAR(100)
				,EmployeeStatusName		NVARCHAR(100)
				,GenderName				NVARCHAR(100)
				,PersonalEmail			NVARCHAR(100)
				,AadharNo				NVARCHAR(100)
				,PANNo					NVARCHAR(100) 
				,EmployeeBankName		NVARCHAR(100)
				,AccountTypeName		NVARCHAR(100)
				,AccountName			NVARCHAR(100)
				,AccountNumber			NVARCHAR(100)
				,IFSCCode				NVARCHAR(100)
				,PayTypeName			NVARCHAR(100)
				,PaymentTypeName		NVARCHAR(100)
				,CTC					NUMERIC(11,2)
				,UANNumber				NVARCHAR(100)
				,PFNumber				NVARCHAR(100)
				,EmployeeESINumber		NVARCHAR(100)
				,MailStatus				NVARCHAR(50)
				,ContactNoStatus		NVARCHAR(50)
				,AadharNoStatus			NVARCHAR(50)
				,PANNoStatus			NVARCHAR(50)
				,AccountNoStatus		NVARCHAR(50)
				,UANNoStatus			NVARCHAR(50)
				,PFNoStatus				NVARCHAR(50)
			);
			
			INSERT INTO #Result(EmployeeCompanyId, FirstName, LastName, ContactNo, OfficialEmail, [Password]
						,DateOfJoining, BranchName, DepartmentName, DesignationName, ReportingPersonName, UserGroupName		
						, EmployeeTypeName, GradeTypeName, EmployeeStatusName, GenderName, PersonalEmail, AadharNo			
						, PANNo, EmployeeBankName, AccountTypeName, AccountName, AccountNumber, IFSCCode, PayTypeName		
						, PaymentTypeName, CTC, UANNumber, PFNumber, EmployeeESINumber, MailStatus, ContactNoStatus	
						, AadharNoStatus, PANNoStatus, AccountNoStatus, UANNoStatus, PFNoStatus)
			SELECT	EmployeeCompanyId, FirstName, LastName, ContactNo, OfficialEmail, [Password]
					,DateOfJoining, BranchName, DepartmentName, DesignationName
					,ReportingPersonName, UserGroupName, EmployeeTypeName, GradeTypeName, EmployeeStatusName
					,GenderName, PersonalEmail, AadharNo, PANNo, EmployeeBankName, AccountTypeName, AccountName
					,AccountNumber, IFSCCode, PayTypeName, PaymentTypeName, CTC, UANNumber, PFNumber
					,EmployeeESINumber
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeeDetails] ED		WHERE ED.OfficialEmail = TVP.OfficialEmail) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.OfficialEmail = TVP.OfficialEmail
										AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.OfficialEmail IS NULL OR LTRIM(RTRIM(TVP.OfficialEmail)) = '' THEN 'Red'
										ELSE 'Green'
					END AS [MailStatus]
					,CASE	WHEN EXISTS	(SELECT 1 FROM [dbo].[EmployeeDetails] ED		WHERE ED.ContactNo = TVP.ContactNo) OR
									EXISTS (SELECT 1 FROM @TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.ContactNo = TVP.ContactNo
											AND INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.ContactNo IS NULL OR LTRIM(RTRIM(TVP.ContactNo)) = '' THEN 'Red'
							ELSE 'Green'
					END AS [ContactNoStatus]
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeePersonalDetails] EPD	WHERE EPD.AadharNo = TVP.AadharNo) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.AadharNo = TVP.AadharNo
											AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.AadharNo IS NULL OR LTRIM(RTRIM(TVP.AadharNo)) = '' THEN 'Red'
							ELSE 'Green'
					END AS [AadharNoStatus]
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeePersonalDetails] EPD	WHERE EPD.PANNo = TVP.PANNo) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.PANNo = TVP.PANNo
											AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.PANNo IS NULL OR LTRIM(RTRIM(TVP.PANNo)) = '' THEN 'Red'
							ELSE 'Green'
					END AS [PANNoStatus]
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeeBankDetails] EBD	WHERE EBD.AccountNumber = TVP.AccountNumber) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.AccountNumber = TVP.AccountNumber
											AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.AccountNumber IS NULL OR LTRIM(RTRIM(TVP.AccountNumber)) = '' THEN 'Red'
							ELSE 'Green'
					END AS [AccountNoStatus]
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeePFDetails] EPFD	WHERE EPFD.UANNumber = TVP.UANNumber) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.UANNumber = TVP.UANNumber
											AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' 
							WHEN TVP.UANNumber IS NULL OR LTRIM(RTRIM(TVP.UANNumber)) = '' THEN 'Red'
							ELSE 'Green'
					END AS [UANNoStatus]
					,CASE	WHEN	EXISTS (SELECT	1  FROM	[dbo].[EmployeePFDetails] EPFD	WHERE EPFD.PFNumber = TVP.PFNumber) OR 
									EXISTS (SELECT	1  FROM	@TVP_EmployeeDetails INNER_TVP	WHERE INNER_TVP.PFNumber = TVP.PFNumber
											AND		INNER_TVP.EmployeeCompanyId <> TVP.EmployeeCompanyId) THEN 'Red' ELSE 'Green'
					END AS [PFNoStatus]
			FROM	@TVP_EmployeeDetails TVP;
           
			SELECT	EmployeeCompanyId, FirstName, LastName, ContactNo, OfficialEmail, [Password]
					,CONVERT(NVARCHAR(50),DateOfJoining,105) AS DateOfJoining, BranchName, DepartmentName, DesignationName
					,ReportingPersonName, UserGroupName, EmployeeTypeName, GradeTypeName, EmployeeStatusName
					,GenderName, PersonalEmail, AadharNo, PANNo, EmployeeBankName, AccountTypeName, AccountName
					,AccountNumber, IFSCCode, PayTypeName, PaymentTypeName, CTC, UANNumber, PFNumber
					,EmployeeESINumber, MailStatus, ContactNoStatus, AadharNoStatus, PANNoStatus, AccountNoStatus
					,UANNoStatus, PFNoStatus
			FROM	#Result;

			SELECT	@Status		= 1
					,@Message	= NULL;
		END 
		ELSE 
		BEGIN	
			BEGIN TRAN
				DROP TABLE IF EXISTS #InsertedEmployees;
				CREATE TABLE #InsertedEmployees
				(
					EmployeeId				INT
					,EmployeeCompanyId		NVARCHAR(50)
				);

				INSERT INTO [dbo].[EmployeeDetails](EmployeeCompanyId, FirstName, LastName, OfficialEmail, [Password]
							,ContactNo, DateOfJoining, BranchId, DepartmentId, DesignationId, ReportingPersonId
							,UserGroupId, EmployeeTypeId, GradeTypeId, EmployeeStatusId, IsLoginUser
							,CompanyId, CreatedBy)
				OUTPUT INSERTED.EmployeeId, INSERTED.EmployeeCompanyId INTO #InsertedEmployees (EmployeeId, EmployeeCompanyId)
				SELECT	TVP.EmployeeCompanyId, TVP.FirstName, TVP.LastName, TVP.OfficialEmail, 'Login@123', TVP.ContactNo
						,TVP.DateOfJoining, BD.BranchId, DD.DepartmentId, DSD.DesignationId, ED.ReportingPersonId
						,UGD.UserGroupId, ETD.EmployeeTypeId, GTD.GradeTypeId, ESD.EmployeeStatusId, 1, @CompanyId
						,@LoginUserId
				FROM	@TVP_EmployeeDetails TVP
				JOIN	[dbo].[BranchDetails] BD
					ON	TVP.BranchName = BD.BranchName
				JOIN	[dbo].[DepartmentDetails] DD
					ON	TVP.DepartmentName = DD.DepartmentName
				JOIN	[dbo].[DesignationDetails] DSD
					ON	TVP.DesignationName = DSD.DesignationName
				JOIN	[dbo].[UserGroupDetails] UGD
					ON	TVP.UserGroupName = UGD.UserGroupName
				JOIN	[dbo].[EmployeeTypeDetails] ETD
					ON	TVP.EmployeeTypeName = ETD.EmployeeType
				JOIN	[dbo].[GradeTypeDetails] GTD
					ON	TVP.GradeTypeName = GTD.GradeTypeName
				JOIN	[dbo].[EmployeeStatusDetails] ESD
					ON	TVP.EmployeeStatusName = ESD.EmployeeStatusName
				LEFT JOIN	[dbo].[EmployeeDetails] ED
					ON	TVP.ReportingPersonName = ED.FirstName;
			
				INSERT INTO [dbo].[EmployeePersonalDetails](GenderId, PersonalEmail, AadharNo, PANNo, EmployeeId, CreatedBy)
				SELECT	GD.GenderId, TVP.PersonalEmail, TVP.AadharNo, TVP.PANNo,	IE.EmployeeId, @LoginUserId 
				FROM	#InsertedEmployees IE
				JOIN	@TVP_EmployeeDetails TVP
					ON	IE.EmployeeCompanyId = TVP.EmployeeCompanyId
				JOIN	GenderDetails GD
					ON	GD.GenderName = TVP.GenderName;
				
				INSERT INTO [dbo].[EmployeeBankDetails](EmployeeBankName, AccountTypeId, AccountName, AccountNumber
							,IFSCCode, EmployeeId, CreatedBy)
				SELECT	TVP.EmployeeBankName, ATD.AccountTypeId, TVP.AccountName, TVP.AccountNumber, TVP.IFSCCode
						,IE.EmployeeId, @LoginUserId 
				FROM	#InsertedEmployees IE
				JOIN	@TVP_EmployeeDetails TVP
					ON	IE.EmployeeCompanyId = TVP.EmployeeCompanyId
				JOIN	AccountTypeDetails ATD
					ON	ATD.AccountTypeName = TVP.AccountTypeName;

				INSERT INTO [dbo].[EmployeeSalaryDetails](TVP.PayTypeId, TVP.PaymentTypeId, TVP.CTC, EmployeeId
							,CreatedBy)
				SELECT	PTD.PayTypeId, PYTD.PaymentTypeId, TVP.CTC, IE.EmployeeId, @LoginUserId 
				FROM	#InsertedEmployees IE
				JOIN	@TVP_EmployeeDetails TVP
					ON	IE.EmployeeCompanyId = TVP.EmployeeCompanyId
				JOIN	[dbo].[PayTypeDetails] PTD
					ON	PTD.PayTypeName = TVP.PayTypeName
				JOIN	[dbo].[PaymentTypeDetails] PYTD
					ON	PYTD.PaymentTypeName = TVP.PaymentTypeName;
			
				INSERT INTO [dbo].[EmployeePFDetails](UANNumber, PFNumber, EmployeeId, CreatedBy)
				SELECT	TVP.UANNumber, TVP.PFNumber, IE.EmployeeId, @LoginUserId
				FROM	#InsertedEmployees IE
				JOIN	@TVP_EmployeeDetails TVP
					ON	IE.EmployeeCompanyId = TVP.EmployeeCompanyId;
			
				INSERT INTO [dbo].[EmployeeESIDetails](TVP.EmployeeESINumber, EmployeeId, CreatedBy)
				SELECT	TVP.EmployeeESINumber, IE.EmployeeId, @LoginUserId 
				FROM	#InsertedEmployees IE
				JOIN	@TVP_EmployeeDetails TVP
					ON	IE.EmployeeCompanyId = TVP.EmployeeCompanyId;
				
			IF @@TRANCOUNT >= 0

			COMMIT TRAN;
			SELECT	@Status		= 1
					,@Message	= 'Record added Successfully.';
        END
    END TRY
    BEGIN CATCH
		ROLLBACK TRAN;
        SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	
    END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status				BIT
			,@M_Message				NVARCHAR(500)
			,@TVP_EmployeeDetails	TVP_EmployeeDetails;

	INSERT INTO @TVP_EmployeeDetails(EmployeeCompanyId, FirstName, LastName, ContactNo, OfficialEmail, [Password]				
				,DateOfJoining, BranchName, DepartmentName, DesignationName, ReportingPersonName, UserGroupName			
				,EmployeeTypeName, GradeTypeName, EmployeeStatusName, GenderName, PersonalEmail, AadharNo, PANNo					 
				,EmployeeBankName, AccountTypeName, AccountName, AccountNumber, IFSCCode, PayTypeName, PaymentTypeName		
				,CTC, UANNumber, PFNumber, EmployeeESINumber)
	VALUES		('TET_201', 'Karthick', 'K', '9965377028', 'karthick@gmail.com', 'Login@123', '2025-01-01', 'Chennai'
				,'Full Stack', 'Full Stack Developer', 'Satheesh', 'GeneralUser', 'Full-Time', 'Grade A'
				,'Permanent', 'Male', 'karthick123@gmail.com', '9900887760', '12345670890', 'Indian Bank', 'Saving'
				,'Karthick', '1234500901234', 'IND56789', 'Monthly', 'Account', 300000, '123405', '6708901', 'ESI1023')
				,('TET_202', 'Mani', 'C', '9965377009', 'mani@gmail.com', 'Login@123', '2025-01-01', 'Chennai'
				,'Full Stack', 'Full Stack Developer', 'Satheesh', 'GeneralUser', 'Full-Time', 'Grade A'
				,'Permanent', 'Male', 'karthick123@gmail.com', '9900887766', '1234567890', 'Indian Bank', 'Saving'
				,'Karthick', '12345678901234', 'IND56789', 'Monthly', 'Account', 300000, '12345', '678901', 'ESI123')

	EXEC [dbo].[USP_InsertEmployeeDetails_BulkInsert]	@LoginUserId			= 1
														,@IsInsert				= 0
