/****** Object:  StoredProcedure [dbo].[USP_InsertEmployeeShiftMappingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==================================================================================================================================================
 Procedure Name		:	 [dbo].[USP_InsertEmployeeShiftMappingDetails]
 Description		:	 Procedure Used to Insert the New EmployeeShiftMappingDetails
													(When click on Insert button in EmployeeShiftMapping Info Screen)
 Input Parameters	:	 @LoginUserId, @DepartmentId, @ShiftId, @IsWeekly, @StartDate, @EndDate, @Description 
 Output Parameters	:	 @Status, @Message												  
 Author				:	 Prakash.P												 	     
 Created on			:	 20-08-2024
 Version			:	 1.0 
 Comment			:	 1. Insert Into EmployeeShiftMappingDetails table have the columns of 
								DepartmentId		AS @DepartmentId
								,EmployeeId			AS @EmployeeId
								,ShiftId			AS @ShiftId
								,IsWeekly			AS @IsWeekly
								,StartDate			AS @StartDate
								,EndDate			AS @EndDate
								,Description		AS @Description
								,CreatedBy			AS @LoginUserId
								,CreatedDate		AS GETDATE() for new Shift in EmployeeShiftMappingDetails Table.
						  2. Then through the success Message as @Status = 1 And @Message = "Record Added Successfully.".
====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertEmployeeShiftMappingDetails]
(
	@LoginUserId			INT	
	,@DepartmentId			TINYINT
	,@ShiftId				TINYINT
	,@StartDate				DATETIME
	,@EndDate				DATETIME
	,@Description			NVARCHAR(500)
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT 
)
AS
BEGIN
	SET NOCOUNT ON; 

	--DECLARE	@LoginUserId		INT				= 1
	--		,@DepartmentId		TINYINT			= 23
	--		,@ShiftId			TINYINT			= 2
	--		,@StartDate			DATETIME		= '2024-10-05'
	--		,@EndDate			DATETIME		= '2024-10-06'	
	--		,@Description		NVARCHAR(500)	= 'Testing Purpose'

	-- Declare the Variable.
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[DBO].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	
	DROP TABLE IF EXISTS #Shift;
	CREATE TABLE #Shift 
	(
		Id					INT		IDENTITY(1,1)
		,DifferentsDate		DATE
	)

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Shift (DifferentsDate) 
		VALUES		(@StartDate);
		SET			@StartDate = DATEADD(DAY, 1, @StartDate);;
	END;

	BEGIN TRY	
		IF NOT EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] ED	WHERE DepartmentId = @DepartmentId)
		BEGIN 
			SELECT	@Status		= 0		
					,@Message	= 'No Employee''s'' are mapped in this department, please fill all the employee''s'' Department.'
		END 
		ELSE
		BEGIN 
			BEGIN TRAN  
				DROP TABLE IF EXISTS #EmployeeShiftMappingDetails;
				CREATE TABLE #EmployeeShiftMappingDetails
				(
					DepartmentId		TINYINT
					,EmployeeId			INT
					,ShiftId			TINYINT
					,IsWeekly			BIT
					,StartDate			DATETIME
					,EndDate			DATETIME
					,[Description]		NVARCHAR(500)
				);

				INSERT INTO #EmployeeShiftMappingDetails (DepartmentId, EmployeeId, ShiftId, IsWeekly, StartDate, EndDate, [Description])
				SELECT		@DepartmentId, ED.EmployeeId, @ShiftId, 0, SH.DifferentsDate, SH.DifferentsDate, @Description 
				FROM		[dbo].[EmployeeDetails] ED
				CROSS JOIN	#Shift SH           
				WHERE		ED.DepartmentId = @DepartmentId;

				MERGE	[dbo].[EmployeeShiftMappingDetails]		AS TARGET  
				USING	#EmployeeShiftMappingDetails			AS SOURCE  
					ON	TARGET.EmployeeId		= SOURCE.EmployeeId    
					AND TARGET.DepartmentId		= SOURCE.DepartmentId 
					AND TARGET.StartDate		= SOURCE.StartDate      
					AND TARGET.EndDate			= SOURCE.EndDate
				WHEN MATCHED THEN  
				UPDATE    
				SET	TARGET.ShiftId           = SOURCE.ShiftId  
					,TARGET.StartDate        = SOURCE.StartDate  
					,TARGET.EndDate          = SOURCE.EndDate   
					,TARGET.[Description]    = SOURCE.[Description]   
					,TARGET.Updatedby        = @LoginUserId  
					,TARGET.UpdatedDate      = GETDATE()  
				WHEN NOT MATCHED BY TARGET THEN  
				INSERT (EmployeeId, DepartmentId, ShiftId, StartDate, EndDate, [Description], CreatedBy, CreatedDate)  
				VALUES (SOURCE.EmployeeId
						,SOURCE.DepartmentId
						,SOURCE.ShiftId
						,SOURCE.StartDate
						,SOURCE.EndDate
						,SOURCE.[Description]
						,@LoginUserId
						,GETDATE())
				WHEN NOT MATCHED BY SOURCE AND TARGET.DepartmentId = @DepartmentId 
				AND TARGET.StartDate BETWEEN (SELECT MIN(DifferentsDate) FROM #Shift) AND (SELECT MAX(DifferentsDate) FROM #Shift)
				THEN DELETE;  
				--INSERT INTO [dbo].[EmployeeShiftMappingDetails] (DepartmentId, EmployeeId, ShiftId, StartDate
				--			,EndDate, [Description], CreatedBy, CreatedDate)
				--SELECT		@DepartmentId	
				--			,ED.EmployeeId	
				--			,@ShiftId		
				--			,@StartDate		
				--			,@EndDate		
				--			,@Description	
				--			,@LoginUserId
				--			,GETDATE()
				--FROM		[dbo].[EmployeeDetails] ED
				--WHERE		DepartmentId = @DepartmentId;
		
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status		= 1   
					,@Message	= 'Record Added Successfully.';  
		END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_InsertEmployeeShiftMappingDetails]	@LoginUserId			= 11										
														,@DepartmentId			= 23
														,@ShiftId				= 3
														,@StartDate				= '2024-10-08'
														,@EndDate				= '2024-10-08'
														,@Description			= ''
														,@Status				= @S_Status		OUT
														,@Message				= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeShiftMappingDetails_Test];
	
	SELECT	* 
	FROM	[dbo].[DepartmentDetails];
	
	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
	SELECT	* 
	FROM	[dbo].[ShiftDetails];
======================================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_InsertEmployeeTypeStructureMappingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertEmployeeTypeStructureMappingDetails]
 Description		:	Procedure used to insert the new EmployeeTypeStructureMappingDetails
														(When Click on Insert Button in EmployeeTypeStructureMappingDetails screen)
 Input Parameter	:	@LoginUserId, @EmployeeTypeStructureMappingId.
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	016-09-2024
 Version			:	1.0 
 Comment			:	Insert and Update the EmployeeTypeStructureMappingDetails For the Given @EmployeeTypeStructureMappingId.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertEmployeeTypeStructureMappingDetails]
(
	@LoginUserId						INT	
	,@EmployeeTypeStructureMappingId	INT
	,@EmployeeTypeId					TINYINT
	,@SalaryStructureId					INT
	,@Status							BIT				OUT	
	,@Message							NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF EXISTS(	SELECT	1 FROM	[dbo].[EmployeeTypeStructureMappingDetails] 
					WHERE	EmployeeTypeStructureMappingId = @EmployeeTypeStructureMappingId)
		BEGIN
			IF EXISTS(	SELECT	1 FROM	[dbo].[EmployeeTypeStructureMappingDetails]
						WHERE	EmployeeTypeStructureMappingId <> @EmployeeTypeStructureMappingId
						AND		EmployeeTypeId = @EmployeeTypeId
						AND		SalaryStructureId = @SalaryStructureId)
			BEGIN 
				SELECT	@Status = 0 
						,@Message = 'Given Details are already Exist.'
				RETURN;
			END 
			ELSE 
			BEGIN TRAN  
				UPDATE	[dbo].[EmployeeTypeStructureMappingDetails] 
				SET		EmployeeTypeId					= @EmployeeTypeId
						,SalaryStructureId				= @SalaryStructureId	
						,UpdatedBy						= @LoginUserId
						,UpdatedDate					= GETDATE()
				WHERE	EmployeeTypeStructureMappingId	= @EmployeeTypeStructureMappingId;
				
				IF @@TRANCOUNT >= 0
				COMMIT TRAN

				SELECT	@Status = 1 
						,@Message = 'Changes Saved successfully.'
			END
			ELSE
			BEGIN
				IF EXISTS (	SELECT	1 
							FROM	[dbo].[EmployeeTypeStructureMappingDetails]
							WHERE	@EmployeeTypeStructureMappingId IS NULL 
							AND		EmployeeTypeId = @EmployeeTypeId 
							AND		SalaryStructureId = @SalaryStructureId
						  )
				BEGIN 
					SELECT	@Status = 0
							,@Message = 'Given Details are already Exist.'
					RETURN;
				END 
				ELSE 
				BEGIN TRAN  
					INSERT INTO [dbo].[EmployeeTypeStructureMappingDetails](EmployeeTypeId, SalaryStructureId, CreatedBy, CreatedDate)
					VALUES		(@EmployeeTypeId		
								,@SalaryStructureId
								,@LoginUserId
								,GETDATE());
							
					IF @@TRANCOUNT >= 0
					COMMIT TRAN

					SELECT	@Status   = 1   
								,@Message = 'Record Added Sucessfully'; 
			END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status		BIT
			,@M_Message		NVARCHAR(500)
			
	EXEC [dbo].[USP_InsertEmployeeTypeStructureMappingDetails]	@LoginUserId						= 1
																,@EmployeeTypeStructureMappingId	= 2
																,@EmployeeTypeId					= 1
																,@SalaryStructureId					= 1
																,@Status							= @S_Status		OUT
																,@Message							= @M_Message	OUT;
	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeTypeStructureMappingDetails];
	
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_InsertHolidayDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*=============================================================================================================================================================================  
 Procedure Name		:	[USP_InsertHolidayDetails]
 Description		:	Procedure used to insert the new Holidaydetails (When Click on Insert Button in HolidayInfo PopupPage)
 Input Parameter	:	@LoginUserId,@HolidayDate,@HolidayName,@IsOptional.
 Output Parameters	:	@Status,@Message
 Author				:	Nithya
 Created on			:	30-05-2023
 Version			:	1.0 
 Comment			:  1. Check the Given HolidayDate is already exists or not?
						  1.1 If exist,Return the error message as @Status = 0 And @Message = "Entered HolidayDate already Exists".
					   2. Check the Given HolidayName is already exists or not?
						  2.1 If exist,Return the error message as @Status = 0 And @Message = "Entered HolidayName already Exists".
					   3. If Both Above Conditions are not exist,  
					   4. Insert into HolidayDetails tables with @HolidayDate As HolidayDate
																  ,@HolidayName As HolidayName
																  ,@IsOptional AS IsOptional
																  ,@CompanyId As CompanyId
																  ,CreatedBy AS @LoginUserId
																  ,CreatedDate As GETDATE()
						5.Then through the Success POPUP message as'The New Holidaydetails has been created Successfully'.
=========================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_InsertHolidayDetails]
(
	@LoginUserId	 INT
	,@HolidayDate    DATETIME      
	,@HolidayName    NVARCHAR(100) 
	,@IsOptional	 BIT			
	,@Status		 BIT			OUT	
	,@Message		 NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId	TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status   = 1   
				,@Message = 'Record Added Successfully';  

		--If the Given HolidayDate is already exists In the HolidayDetails Table,Return the error message as @Status = 0 And @Message = "Given HolidayDate And Combination is Already Exists''
		IF EXISTS(SELECT 1 FROM [dbo].[HolidayDetails] WHERE HolidayDate= @HolidayDate AND  CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Entered HolidayDate already Exists';
			RETURN;
		END
		--If the Given HolidayDate,HolidayName is already exists In the HolidayDetails Table,Return the error message as @Status = 0 And @Message = "Given HolidayName And Combination is Already Exists'
		ELSE IF EXISTS(SELECT 1 FROM [dbo].[HolidayDetails] WHERE HolidayDate = @HolidayDate AND HolidayName = @HolidayName  AND CompanyId=@CompanyId)
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Entered HolidayName already Exists';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				--Procedure will insert the new HolidayDetails			
				INSERT INTO [dbo].[HolidayDetails](HolidayDate,HolidayName,IsOptional,CompanyId,CreatedBy,CreatedDate)		   
				VALUES	(@HolidayDate
						,@HolidayName
						,@IsOptional
						,@CompanyId
						,@LoginUserId
						,GETDATE());
			
			IF @@TRANCOUNT >0
			COMMIT TRAN
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)
			
	EXEC [dbo].[USP_InsertHolidayDetails]	@LoginUserId	= 1
											,@HolidayDate   = '2024-01-13'
											,@HolidayName   = 'Pongal'
											,@IsOptional	= 0
											,@Status		= @S_Status	 OUT
											,@Message		= @M_Message OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[HolidayDetails];
======================================================================================================================================*/
GO
