/*===========================================================================================================================================
Procedure Name		: [dbo].[USP_InsertLeaveDetails]
Description			: Procedure used to Insert the New LeaveDetails(When Click On save in Leave PopUp Screen)
Input Parameters	: @LoginUserId,@EmployeeId,@LeaveTypeId,@FromDate,@ToDate,@IsHalfDay,@LeaveDescription,@LeaveStatusId.
OutPut Parameters	: @Status,@Message
Author				: Dharani.M
Created On			: 23-08-2023
Version				: 1.0
Comment				: 1.If the Given FromDate along with EmployeeId and LeaveStatus (1,2,3) is already exists, then
						1.1 If Exists, then Return the Error Popup Message @Status = 0 and @Message = 'Entered LeaveDate is already Exists'
						1.2 If Not Exists, then Insert Into LeaveDetails 
									EmployeeId			AS @EmployeeId
									,LeaveTypeId		AS @LeaveTypeId
									,FromDate			AS @FromDate
									,ToDate				AS @ToDate
									,IsHalfDay			AS @IsHalfDay
									,NoOfDays			AS @NoOfDays Using Case Statement DateDiff Between FromDate And ToDate
									,LeaveDescription	AS @LeaveDescription
									,LeaveStatusId		AS @LeaveStatusId
									,EmployeeId			AS @EmployeeId
									,CreatedBy			AS @LoginUserId
									,CreatedDate		AS GETDATE() for the new Leave.
						1.3 Then Through the Success Message as Status = 1 and Message = 'New LeaveDetails Have Been Created Sucessfully'.
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertLeaveDetails]
(	
	@LoginUserId			INT
	,@EmployeeId			INT
	,@LeaveTypeId			TINYINT
	,@FromDate				DATETIME
	,@ToDate				DATETIME		= NULL
	,@IsHalfDay				BIT
	,@IsFirstHalf			BIT				= NULL
	,@NoOfDays				NUMERIC(5,2)
	,@LeaveDescription		NVARCHAR(400)
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId			TINYINT
			,@LeaveId			INT 
			,@LeaveStatusName	NVARCHAR(50);
		   
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeavestatusDetails];	

	BEGIN TRY	
		IF EXISTS(	SELECT	1
					FROM	[dbo].[LeaveDetails]  
					WHERE	EmployeeId = @EmployeeId
					AND		LeaveTypeId NOT IN (2)
					AND		LeaveStatusId IN (1, 2, 3)
					AND		((FromDate = @FromDate AND ToDate = @ToDate)
					OR		(@FromDate BETWEEN FromDate AND ToDate)
					OR		(@ToDate BETWEEN FromDate AND ToDate)
					OR		(FromDate BETWEEN @FromDate AND @ToDate) 
					OR		(ToDate BETWEEN @FromDate AND @ToDate)))
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Entered LeaveDate is already Exists.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[LeaveDetails](FromDate, ToDate, IsHalfDay, IsFirstHalf, NoOfDays, LeaveDescription
							,LeaveStatusId, LeaveTypeId, EmployeeId, CompanyId, CreatedBy, CreatedDate)
				VALUES		(@FromDate
							,@ToDate
							,@IsHalfDay
							,@IsFirstHalf
							,@NoOfDays
							,@LeaveDescription
							,2
							,@LeaveTypeId
							,@EmployeeId 
							,@CompanyId
							,@EmployeeId
							,GETDATE());

				SELECT @LeaveId = SCOPE_IDENTITY();

				--NotificationDetails
				IF @LeaveStatusName = 'Submitted'
				BEGIN
					INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
								,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
								,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)					
					SELECT	@LeaveId
							,'Leave'
							,1
							,'Owner'
							,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME(ED.EmployeeCompanyId), ' has requesting Leave On ',
								CONVERT(NVARCHAR(30),@FromDate,105) ,' to ' , CONVERT(NVARCHAR(30),@ToDate,105))
							,3
							,UD.EmployeeId
							,'Open'
							,'Open'
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
					FROM	[dbo].[LeaveDetails] AS LD
					JOIN	[dbo].[EmployeeDetails] ED
						ON	LD.EmployeeId = ED.EmployeeId
					JOIN	(	SELECT	ED.EmployeeId
										,ED.FirstName
										,ED.EmployeeCompanyId
								FROM	[dbo].[EmployeeDetails] AS ED 
								LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
									ON	ED.EmployeeId = RPD.ReportingPersonId
								WHERE	RPD.EmployeeId = @LoginUserId
							) AS  UD
						ON	ED.EmployeeId = LD.EmployeeId
					WHERE	LeaveId = @LeaveId 
					AND		LD.CompanyId  = @CompanyId;
				END

			IF @@TRANCOUNT > 0
			COMMIT TRAN
			
			SELECT	 @Status  = 1   
					,@Message = 'New LeaveDetails have been created Successfully.';  

			IF @LeaveStatusName = 'Submitted'
			BEGIN 
				IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					-- Result set for Email sended.
					SELECT  RPD.OfficialEmail AS ToMail	
							,'Request for Leave Approval' AS [Subject]
							,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
							,CONCAT('I am writing to formally request leave on ', CONVERT(NVARCHAR(50), @FromDate, 106)
								,' to ', CONVERT(NVARCHAR(50), @Todate, 106),'. The request has been submitted by {'
								, ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId, '] } for your approval.') AS SecondLine
							,'I kindly request you to review and approve my leave at your earliest convenience.' AS ThirdLine
							,'Please let me know if you require any further information regarding my request.' AS FourthLine
							,'Thank You.' AS FifthLine
							,' ' AS SixthLine
					FROM	EmployeeDetails ED 
					LEFT JOIN EmployeeDetails RPD 
						ON	ED.ReportingPersonId = RPD.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=======================================================================================================================================
	DECLARE	 @S_Status	BIT
		    ,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_InsertLeaveDetails]	@LoginUserId	    = 3
										,@EmployeeId		= 3
										,@LeaveTypeId       = 3
										,@FromDate			= '2025-02-04'
										,@ToDate			= '2025-02-05'
										,@IsHalfDay         = 0
										,@IsFirstHalf		= NULL 
										,@NoOfDays			= 2
										,@LeaveDescription  = ''
										,@Status			= @S_Status		OUT
										,@Message		    = @M_Message	OUT;
 										  
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[LeaveDetails];	
	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
	SELECT	*
	FROM	[dbo].[LeaveTypeDetails];
	SELECT *
	FROM	[dbo].[NotificationDetails];

	SELECT * FROM  Input_Values 

=========================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_InsertLeavetypeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
