/*======================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertLoanDetails]
 Description		:	Procedure used to create the new LoanDetails (When Click on Save Button in Loan Screen popup)
 Input Parameter	:	@LoginUserId,@EmployeeId, @LoanDate, @LoanAmount,@NoOfDues, @DueAmount, @CompletedDue,@PendingDues,@PendingAmount,@Description
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	30-08-2023
 Version			:	1.0 
 Comment			:	1. If the Entered LoanDate along with EmployeeId is already exist,then
							1.1 Through the error message as @Status = 0 And @Message = "Entered LoanDate along with EmployeeId is already Exists'
						2. If the Entered LoanDate along with EmployeeId is not exist,then
							2.1 Procedure will insert 
									LoanDate		AS	@LoanDate
									,EmployeeId		AS	@EmployeeId
									,LoanAmount		AS	@LoanAmount
									,NoOfDues		AS  @NoOfDues
									,DueAmount		AS	@DueAmount
									,CompletedDue   AS  @CompletedDue
								    ,PendingDues    AS  @PendingDues
									,PendingAmount  AS  @PendingAmount
									,LoanStatusId	AS	@LoanStatusId
									,Description	AS	@Description
									,CompanyId		AS	@CompanyId
									,CreatedBy		AS	@EmployeeId
									,CreatedDate	AS	GETDATE() into the LoanDetails for the new Loan.								
						3.Then through the success Message as @Status = 1 and @Message = 'The New LoanDetails have been Created Successfully'.
=====================================================================================================================================================================*/
CREAtE   PROCEDURE [dbo].[USP_InsertLoanDetails]
(
	@LoginUserId		INT
	,@EmployeeId		INT
	,@LoanDate			DATETIME		
	,@LoanAmount		NUMERIC(11,2)
	,@NoOfDues			TINYINT			
	,@DueAmount			NUMERIC(11,2)
	,@CompletedDue		INT
	,@PendingDues		TINYINT			
	,@PendingAmount		NUMERIC(11,2)
	,@Description		NVARCHAR(500)
	,@Status			BIT				OUT	
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	 
	DECLARE	@CompanyId	TINYINT
			,@LoanId	INT;
		   
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
				
	BEGIN TRY	
		IF EXISTS(	SELECT	1
					FROM	[dbo].[LoanDetails] AD
					JOIN	[dbo].[LeaveStatusDetails] LSD
						ON	AD.LoanStatusId = LSD.LeaveStatusId
					WHERE	MONTH(LoanDate) = MONTH(@LoanDate) 
					AND		YEAR(LoanDate)  = YEAR (@LoanDate) 
					AND		EmployeeId = @EmployeeId
					AND		AD.CompanyId  = @CompanyId 
					AND		AD.LoanStatusId = 3)
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'You are already got an Loan of this month,So cannot request again.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN
				INSERT INTO [dbo].[LoanDetails] (LoanDate, EmployeeId, LoanAmount, NoofDues, DueAmount, CompletedDue
							,PendingDues, PendingAmount, LoanStatusId, [Description], CompanyId, CreatedBy)
				VALUES		(@LoanDate		
							,@EmployeeId	
							,@LoanAmount	
							,@NoOfDues		
							,@DueAmount		
							,@CompletedDue  
							,@PendingDues	
							,@PendingAmount	
							,2
							,@Description	
							,@CompanyId
							,@EmployeeId);

				SELECT @LoanId = SCOPE_IDENTITY();
								
				IF EXISTS(SELECT 1 FROM [dbo].[LoanDetails] WHERE LoanId = @LoanId AND LoanStatusId = 2 AND CompanyId = @CompanyId)
				BEGIN
					INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
								,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
								,SMS_To, IsAuto, CompanyId, CreatedBy)							
					SELECT	@LoanId
							,'Loan'
							,1
							,'Owner'
							,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME( ED.EmployeeCompanyId), ' has requesting ' 
								,'Loan Amount of ', N'₹ ',CONVERT(NVARCHAR(30),LD.LoanAmount),' on '
								,CONVERT(NVARCHAR(30),LD.LoanDate,106),'.')
							,3
							,UD.EmployeeId         
							,'Open'
							,'Open' 
							,UD.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
					FROM	[dbo].[LoanDetails] AS LD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	ED.EmployeeId = LD.EmployeeId	
					JOIN	(	SELECT	ED.EmployeeId
										,ED.FirstName
										,ED.EmployeeCompanyId
										,ED.ContactNo
								FROM	[dbo].[EmployeeDetails] AS ED 
								LEFT JOIN [dbo].[EmployeeDetails] AS RPD
									ON	ED.EmployeeId = RPD.ReportingPersonId
								WHERE	RPD.EmployeeId = @LoginUserId
							) AS  UD
						ON	ED.EmployeeId = LD.EmployeeId
					WHERE	LoanId = @LoanId 	
					AND		LD.CompanyId = @CompanyId;
				END
					
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'New LoanDetails are Added Successfully.';  

					
			IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				-- Result set for Email sended.
				SELECT  RPD.OfficialEmail AS ToMail	
						,'Request for Loan Approval' AS [Subject]
						,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
						,CONCAT('I am writing to formally request Loan on ', CONVERT(NVARCHAR(50), @LoanDate, 106)
							,' and the Loan amount is ',@LoanAmount, '. The request has been submitted by {' , ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId
							, '] } for your approval.') AS SecondLine
						,'I kindly request you to review and approve my Loan at your earliest convenience.' AS ThirdLine
						,'Please let me know if you require any further information regarding my request.' AS FourthLine
						,'Thank You.' AS FifthLine
						,' ' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN [dbo].[EmployeeDetails] RPD 
					ON	ED.ReportingPersonId = RPD.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);	
		
	EXEC [dbo].[USP_InsertLoanDetails]	@LoginUserId		 = 1
										,@EmployeeId		 = 3
										,@LoanDate			 = '2025-01-10'
										,@LoanAmount		 = 12000
										,@NoOfDues			 = 6
										,@DueAmount			 = 0
										,@CompletedDue  	 = 0
										,@PendingDues		 = 6
										,@PendingAmount		 = 12000
										,@Description		 = ' '
				                        ,@Status		     = @S_Status	 OUT			
										,@Message		     = @M_Message    OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;										
	  
	
	SELECT * FROM LoanDetails;
	SELECT * FROM LoanDueDetails;
	SELECT	*
	FROM [dbo].[LeaveStatusDetails];
	SELECT * 
	FROM EmployeeDetails
	SELECT * FROM NotificationDetails ORDER BY NotificationId DESC
	SELECT	*
	FROM [dbo].[MessageStatusDetails];
======================================================================================================================================*/
GO
