/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertMailTemplateDetails]
 Description		:	
 Input Parameter	:	
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	11-02-2025
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE PROCEDURE [dbo].[USP_InsertMailTemplateDetails]
(
	@LoginUserId				INT	
	,@MailTemplateId			TINYINT
	,@MailTemplateType			NVARCHAR(50)
	,@MailTemplateContent		NVARCHAR(MAX)
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
        IF EXISTS(SELECT 1 FROM [dbo].[MailTemplateDetails] WHERE MailTemplateId = @MailTemplateId AND CompanyId = @CompanyId)
		BEGIN
			BEGIN TRAN 
				UPDATE	[dbo].[MailTemplateDetails]
				SET		MailTemplateContent		=	@MailTemplateContent
						--,MailTemplateType		=   @MailTemplateType
						,UpdatedBy				=	@LoginUserId
						,UpdatedDate			=	GETDATE()
				WHERE	CompanyId				=	@CompanyId
				AND		MailTemplateId			=	@MailTemplateId;
			
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'Changes Saved Successfully.'; 
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[MailTemplateDetails](MailTemplateType, MailTemplateContent, CompanyId, CreatedBy)
				VALUES		(@MailTemplateType			
							,@MailTemplateContent	
							,@CompanyId
							,@LoginUserId);
		
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'Record Added Successfully.'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500)	

	EXEC [dbo].[USP_InsertMailTemplateDetails]	@LoginUserId			= 1
