												,@MailTemplateContent	= 'System.Data.SqlClient.SqlException: Cannot find either column dbo or the user-defined function or aggregate dbo.UDF_GetNumToWord, or the name is ambiguous.'
												,@Status				= @S_Status		OUT
												,@Message				= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	 SELECT *  FROM [dbo].[MailTemplateDetails];
	 TRUNCATE TABLE MailTemplateDetails
