/*=================================================================================================================================================
Procedure Name		: [USP_InsertManualAttendanceDetails]
Description			: Procedure Will Insert the AttendanceLogDetails(When Click On save Button in AddManual - AttendanceLog(Admin)Screen.
Input Parameters	: @LoginUserId, @PunchDate, @TVP_AttendanceDetails
Output Parameters	: @Status, @Message
Author				: Dharani.M
Created On			: 11-08-2023
Version				: 1.0
Comment				: 1.Declare the CompanyId to get CompanyId for Given LoginUserID to use Where Conditions.
					  2.Declare the EmployeeId,PunchOut,MINId,MAXId to take the Minimum,Maximum Id in Temp Table #Attendance.
					  3.Created Temp Table #Attendance to Take the Employees PunchIn And PunchOut from TableValuesparameter.
					    3.1 Using While Loop Statement Insert / Update the given Employee Attendance detail as below.
							3.1.1.If there was records for given employeeId on the given date,then
							3.1.2 Delete the AttendanceLogDetails Record with the Given PunchDate,EmployeeId,
							3.1.3 Then Insert the New Record in AttendanceLogDetails Table(CheckIn)
							3.1.4 IF PunchOut value is Not Null, then Insert the CheckOut in AttendanceLogDetails Table
							3.1.5.If there was no records for given employeeId on the given date,then
								3.2 Then Insert the New Record in AttendanceLogDetails Table(CheckIn)
								3.3 IF PunchOut value is Not Null, then
									3.3.1 Insert the CheckOut in AttendanceLogDetails Table,
									3.3.2 Insert the CheckIn in AttendanceLogDetails Table.
						4.Then through the Sucess Message as Status = 1 And Message = 'The New AttendanceDetails have been created Sucessfully' 
========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertManualAttendanceDetails]
(
	@LoginUserId			INT
	,@PunchDate				DATE
	,@TVP_AttendanceDetails	TVP_AttendanceDetails	READONLY
	,@Status				BIT						OUT
	,@Message				NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		INT
			,@EmployeeId	INT
			,@PunchOut		DATETIME 
			,@MINId			INT 
			,@MAXId			INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
	
	BEGIN TRY 
		--Temp table for PunchIn and PunchOut
		DROP TABLE IF EXISTS #Attendance;
		CREATE TABLE #Attendance 
		(
			Id						INT  IDENTITY(1,1)
			,EmployeeId				INT
			,PunchIn				DATETIME
			,PunchOut				DATETIME
			,AttendanceStatusId		INT
		)

		INSERT INTO	#Attendance(EmployeeId, PunchIn, PunchOut)
		SELECT		EmployeeId, PunchIn, PunchOut 
		FROM		@TVP_AttendanceDetails
		WHERE		PunchIn IS NOT NULL;

		SELECT	@MINId = MIN(Id)
				,@MAXId = MAX(Id)
		FROM	#Attendance;

		BEGIN TRAN
			WHILE @MINId <= @MAXId
			BEGIN
				SELECT	@EmployeeId = EmployeeId
						,@PunchOut = PunchOut
				FROM	#Attendance
				WHERE	Id = @MINId;

				--If exist,Return the error message as @Status = 0 And @Message = "Entered PunchIn was already Exists'
				IF EXISTS( SELECT * FROM [dbo].[AttendanceLogDetails] WHERE PunchDate = @PunchDate AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
				BEGIN
					--Delete the AttendanceLogDetails Record with Given PunchDate,EmployeeId
					DELETE 
					FROM	[dbo].[AttendanceLogDetails]
					WHERE	PunchDate = @PunchDate 
					AND		EmployeeId = @EmployeeId
					AND		CompanyId = @CompanyId;

					--Insert the New Record in AttendanceLogDetails Table(CheckIn) 
					INSERT INTO [dbo].[AttendanceLogDetails](PunchDate,PunchTime,[Status],IsManual,[Location],AttendanceStatusId,
								EmployeeId,CompanyId,CreatedBy,CreatedDate)
					SELECT      @PunchDate,PunchIn,1,1,'Add Manual',AttendanceStatusId,@EmployeeId,@CompanyId,@loginUserId,GETDATE()
					FROM		#Attendance
					WHERE	Id = @MINId;

					--IF @PunchOut is Not Null
					IF @PunchOut IS NOT NULL
					BEGIN
						--Insert the New Record in AttendanceLogDetails Table(CheckOut) 
						INSERT INTO [dbo].[AttendanceLogDetails](PunchDate,PunchTime,[Status],IsManual,[Location],AttendanceStatusId,
									EmployeeId,CompanyId,CreatedBy,CreatedDate)
						SELECT      @PunchDate,PunchOut,0,1,'Add Manual',AttendanceStatusId,@EmployeeId,@CompanyId,@loginUserId,GETDATE()
						FROM		#Attendance
						WHERE	Id = @MINId;
					END
				END
				ELSE 
				BEGIN
					--Insert the New Record in AttendanceLogDetails Table(CheckIn) 
					INSERT INTO [dbo].[AttendanceLogDetails](PunchDate,PunchTime,[Status],IsManual,[Location],AttendanceStatusId,
								EmployeeId,CompanyId,CreatedBy,CreatedDate)
					SELECT      @PunchDate,PunchIn,1,1,'Add Manual',AttendanceStatusId,@EmployeeId,@CompanyId,@loginUserId,GETDATE()
					FROM		#Attendance
					WHERE	Id = @MINId;

					IF @PunchOut IS NOT NULL
					BEGIN
						--Insert the New Record in AttendanceLogDetails Table(CheckOut) 
						INSERT INTO [dbo].[AttendanceLogDetails](PunchDate,PunchTime,[Status],IsManual,[Location],AttendanceStatusId,
									EmployeeId,CompanyId,CreatedBy,CreatedDate)
						SELECT      @PunchDate,PunchOut,0,1,'Add Manual',AttendanceStatusId,@EmployeeId,@CompanyId,@loginUserId,GETDATE()
						FROM		#Attendance
						WHERE		Id = @MINId;
					END			
				END	
			
				SET @MINId = @MINId + 1

			END
	
		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1  
				,@Message = 'Record Added Sucessfully.';
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status  = 0
			  ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	
	END CATCH
END
/*==================================================================================================================== 
    DECLARE @S_Status               BIT
	       ,@M_Message              NVARCHAR(500)
		   ,@TVP_AttendanceDetails  TVP_AttendanceDetails;

	INSERT INTO @TVP_AttendanceDetails (EmployeeId,PunchIn,PunchOut)
	VALUES		(5, '2024-08-05 14:30:00',NULL)
				--,(2,'09:30:00','18:30:00')
				--,(1,'09:30:00','18:30:00');

	EXEC [dbo].[USP_InsertManualAttendanceDetails]	@LoginUserId			= 1	 
													,@PunchDate				= '2024-08-05'
													,@TVP_AttendanceDetails	= @TVP_AttendanceDetails
													,@Status				= @S_Status  OUT	
													,@Message				= @M_Message OUT

	SELECT @S_Status AS STATUS,@M_Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[AttendanceLogDetails] ORDER BY AttendanceLogId DESC
	SELECT	*
	FROM	[dbo].[EmployeeDetails];

	DELETE FROM	[dbo].[AttendanceLogDetails] WHERE AttendanceLogId IN (5906,5905,5904)
==========================================================================================================================*/
GO
