/*=============================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertOverTimeDetails]
 Description		:	Procedure Used to Insert the OverTimeDetails (1.When click on Save Button in OverTime Info Popup Page)
 Input Parameter	:	@LoginUserId, @TVP_OverTimeDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-02-2024
 Version			:	1.0 
 Comments			:	1.Logic will insert into OverTimeDetails table have the Columns of 
										EmployeeId		AS EmployeeId	
										,[Date]			AS [Date]		
										,StartTime		AS StartTime	
										,EndTime		AS EndTime	
										,TotalHours		AS TotalHours for the new insert.
						2. Then return the output parameter values @Status = 1 & @Message = 'Record Added Successfully.'
=============================================================================================================================================*/
CREATE    PROCEDURE [dbo].[USP_InsertOverTimeDetails]
(
	@LoginUserId			INT
	,@TVP_OverTimeDetails	TVP_OverTimeDetails READONLY
	,@Status				BIT					OUT
	,@Message				NVARCHAR(500)		OUT
)
AS
BEGIN 
	SET NOCOUNT ON;

	DECLARE @CompanyId			TINYINT
			,@ContactNumber		NVARCHAR(50)
			,@OverTimeId		INT
			,@LeaveStatusName	NVARCHAR(50) 
			,@Counting			INT
			
	SELECT	@CompanyId = CompanyId
			,@ContactNumber = ContactNo
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeavestatusDetails];	

	BEGIN TRY
		BEGIN TRAN 
			INSERT INTO [dbo].[OverTimeDetails](EmployeeId, [Date], IsForeNoon, StartTime, EndTime, TotalHours, OverTimeStatusId
						,Comments, CompanyId, CreatedBy, CreatedDate)
			SELECT		EmployeeId, [Date], IsForeNoon, StartTime, EndTime, TotalHours, 2, Comments, @CompanyId
						,@LoginUserId, GETDATE()
			FROM		@TVP_OverTimeDetails;
								
			--Procedure to insert NotificationDetail from multiple tables.
			IF @LeaveStatusName  = 'Submitted'
			BEGIN
				INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, MessageTo, DetailedMessage
							,NotificationStatus, SMSStatus, EmployeeId, SMS_To, IsInternal, MessageStatusId, IsAuto, CompanyId, CreatedBy
							,CreatedDate)							
				SELECT	@OverTimeId
						,'OverTime'
						,'Owner'
						,'Dear Sir, ' + ED.FirstName + QUOTENAME(ED.EmployeeCompanyId) + ' has requested OverTime On ' +  
						 CONVERT(VARCHAR, CAST(LEFT(OTD.StartTime,5) AS DATETIME), 108) + ' To ' + CONVERT(VARCHAR, CAST(LEFT(OTD.EndTime,5) AS DATETIME), 108)							
						,'Open'
						,'Open'
						,UD.EmployeeId       
						,UD.ContactNo
						,1
						,3
						,1
						,@CompanyId
						,@LoginUserId
						,GETDATE()
				FROM	@TVP_OverTimeDetails AS OTD
				JOIN	[dbo].[EmployeeDetails] AS ED
					ON	ED.EmployeeId = OTD.EmployeeId	
				JOIN	(	SELECT	EmployeeId
									,FirstName
									,ContactNo	
							FROM	[dbo].[EmployeeDetails] AS ED 
							WHERE	UserGroupId = 1
						) AS  UD
					ON	ED.EmployeeId = OTD.EmployeeId
				--WHERE	OverTimeId = @OverTimeId
				--AND		OTD.CompanyId = @CompanyId;
			END

		IF @@TRANCOUNT > 0
		COMMIT TRAN

		SELECT	@Status = 1 
				,@Message = 'Record Added Successfully.';
	END TRY 
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
/*============================================================================================================================================
	DECLARE	@Status					BIT
			,@Message				NVARCHAR(500)
			,@TVP_OverTimeDetails	TVP_OverTimeDetails

	INSERT INTO @TVP_OverTimeDetails (EmployeeId, [Date], StartTime, EndTime, TotalHours, Comments)
	VALUES		(4, '2024-08-25', '09:00', '12:00', '2',' ')
				,(5, '2024-08-26', '12:00', '13:00', '1',' ')
				,(6, '2024-08-26', '10:00', '11:00', '1',' ');
				
	EXEC	[dbo].[USP_InsertOverTimeDetails]	@LoginUserId			= 1	
												,@TVP_OverTimeDetails	= @TVP_OverTimeDetails
												,@Status				=  @Status  OUT
												,@Message				=  @Message OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM OverTimeDetails

    SELECT * FROM [dbo].[OverTimeDetails_NewId];

	SELECT * FROM EmployeeDetails

	SELECT * FROM NotificationDetails ORDER BY NotificationId DESC


	DELETE FROM NotificationDetails WHERE NotificationId IN (74, 75)
=============================================================================================================================================*/
GO
