/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertPaymentDetails]
 Description		:	Procedure used to insert the new PaymentDetails
 Input Parameter	:	@LoginUserId, 
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	26-10-2024
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_InsertPaymentDetails]
(
	@LoginUserId		INT	
	,@PaymentType		NVARCHAR(50)
	,@PaymentPlan		NVARCHAR(50)
	,@PaymentAmount		NUMERIC(11,2)
	,@Status			BIT						OUT	
	,@Message			NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId				TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY					
		IF EXISTS( SELECT 1 FROM [dbo].[UserPaymentDetails] WHERE	CompanyId = @CompanyId)
		BEGIN
			BEGIN TRAN  
				UPDATE	[dbo].[UserPaymentDetails]
				SET		PaymentType			= @PaymentType
						,PaymentPlan		= @PaymentPlan
						,PaymentAmount		= @PaymentAmount
						,UpdatedBy			= @LoginUserId
						,UpdatedDate		= GETDATE()
				WHERE	CompanyId			= @CompanyId;
				
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'Record Added Sucessfully'; 
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[UserPaymentDetails](PaymentType, PaymentPlan, PaymentAmount, CompanyId
							,CreatedBy, CreatedDate)
				VALUES		(@PaymentType	
							,@PaymentPlan
							,@PaymentAmount
							,@CompanyId
							,@LoginUserId
							,GETDATE());

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'Record Added Sucessfully'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status		BIT
			,@M_Message		NVARCHAR(500)
			
	EXEC [dbo].[USP_InsertPaymentDetails]	@LoginUserId			= 1
