/*=======================================================================================================================================================
 Procedure Name		:	[dbo].[USP_InsertPermissionDetails]
 Description		:	Procedure used to Insert the PermissionDetails
																	(When Click on save in Permission popup Screen)
 Input Parameters	:	@LoginUserId, @EmployeeId, @PermissionDate, @StartTime, @EndTime, @PermissionDescription.
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	23-08-2023
 Version			:	1.0 
 Comment			:	1.If the Given PermissionDate along with EmployeeId is already exists,then 
							1.1 Through the error message as @Status = 0 And 
									@Message = "Given PermissionDate is already Exist.'
						2 If the Given PermissionDate along with EmployeeId is already not exist, then 
							2.1 Insert into PermissionDetails table have the columns of 
									PermissionDate			AS @PermissionDate
									,EmployeeId				AS @EmployeeId
									,StartTime				AS @StartTime
									,EndTime				AS @EndTime
									,NumberOfHours			AS Differene Between @StartTime & @EndTime
									,PermissionDescription	AS @PermissionDescription
									,PermissionStatusId		AS 2(Submitted)
									,CreatedBy				AS @LoginUserId
									,CreatedDate			AS GETDATE().
							2.2 Then through the success Message as @Status = 1 And 
									@Message = "New PermissionDetails have been created Successfully.".
=========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertPermissionDetails]
(	
	@LoginUserId				INT
	,@EmployeeId				INT
	,@PermissionDate			DATE
	,@StartTime					TIME
	,@EndTime					TIME
	,@PermissionDescription		NVARCHAR(400)
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@PermissionId	INT;
		   
	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
        IF EXISTS( SELECT 1 FROM [dbo].[PermissionDetails] WHERE PermissionDate = @PermissionDate AND EmployeeId = @EmployeeId AND PermissionStatusId IN (1,2,3))
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Given PermissionDate is already Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[PermissionDetails](EmployeeId, PermissionDate, StartTime, EndTime, NumberOfHours
							,PermissionDescription, PermissionTypeId, PermissionStatusId, CompanyId, CreatedBy)
				VALUES		(@EmployeeId
							,@PermissionDate
							,@StartTime
							,@EndTime
							,CAST(DATEADD(SECOND, DATEDIFF(SECOND, @StartTime, @EndTime), '00:00:00') AS TIME)
							,@PermissionDescription
							,1
							,2
							,@CompanyId
							,@EmployeeId);

				SELECT @PermissionId = SCOPE_IDENTITY();

				BEGIN
					IF (SELECT	COUNT(1) FROM [dbo].[NotificationDetails] 
						WHERE	NotificationModuleRefId = @PermissionId AND	NotificationTypeName = 'Permission') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)					
						SELECT	@PermissionId
								,'Permission'
								,1
								,'Owner'
								,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME(ED.EmployeeCompanyId), ' has requested permission to be excused from '  
												,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
												RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
												CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
											,' to ',
												RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
												RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
												CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
												,' on ',CONVERT(NVARCHAR(50),@PermissionDate,106),'.')
								,3
								,UD.EmployeeId
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[PermissionDetails] AS PD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = PD.EmployeeId
						LEFT JOIN	(	SELECT	DISTINCT ED.EmployeeId
												,ED.FirstName
												,ED.EmployeeCompanyId
										FROM	[dbo].[EmployeeDetails] AS ED 
										LEFT JOIN [dbo].[EmployeeDetails] AS RPD
											ON	ED.EmployeeId = RPD.ReportingPersonId
										WHERE	RPD.ReportingPersonId = @LoginUserId
									) AS  UD
							ON	ED.EmployeeId = PD.EmployeeId
						WHERE	PermissionId = @PermissionId
						AND		PD.CompanyId  = @CompanyId;
					END
				END

			IF @@TRANCOUNT >= 0
			COMMIT TRAN
			
			SELECT	@Status		= 1   
					,@Message	= 'New PermissionDetails have been created Successfully.';  
			
			IF EXISTS(SELECT 1 FROM [dbo].[NoticationCategoryDetails] WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				-- Result set for Email sended.
				SELECT  RPD.OfficialEmail AS ToMail	
						,'Request for Permission Approval' AS [Subject]
						,CONCAT('Dear ', RPD.FirstName, ' ', RPD.LastName, ',') AS FirstLine
						,CONCAT('I am writing to formally request Permission on '
							,RIGHT('0' + CAST(DATEPART(HOUR, CAST(@StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
							RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
							CASE WHEN DATEPART(HOUR, CAST(@StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END,' to ',
							RIGHT('0' + CAST(DATEPART(HOUR, CAST(@EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
							RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
							CASE WHEN DATEPART(HOUR, CAST(@EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
							,' on ',CONVERT(NVARCHAR(50),@PermissionDate,106),'. The request has been submitted by {'
							, ED.FirstName, ' ', ED.LastName, ' [', ED.EmployeeCompanyId, '] } for your approval.') AS SecondLine
						,'I kindly request you to review and approve my Permission at your earliest convenience.' AS ThirdLine
						,'Please let me know if you require any further information regarding my request.' AS FourthLine
						,'Thank You.' AS FifthLine
						,' ' AS SixthLine
				FROM	EmployeeDetails ED 
				LEFT JOIN EmployeeDetails RPD 
					ON	ED.ReportingPersonId = RPD.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=======================================================================================================
	DECLARE	 @S_Status	BIT
		    ,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_InsertPermissionDetails]	@LoginUserId	            = 3
												,@EmployeeId				= 3
												,@PermissionDate			= '2025-01-04'
												,@StartTime					= '11:20:00'
												,@EndTime					= '13:00:00'
												,@PermissionDescription		= ' '     
												,@Status			        = @S_Status		OUT
												,@Message		            = @M_Message	OUT

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[PermissionDetails];

	SELECT *
	FROM	[dbo].[NotificationDetails];
	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
	DELETE FROM NotificationDetails WHERE NotificationId = 11
======================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_InsertRegularizationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================================
 Procedure Name		:	[dbo].[USP_InsertRegularizationDetails]
 Description		:	Procedure used to Insert the RegularizationDetails
															(When Click on save in Regularization insert popup Screen)
 Input Parameters	:	@LoginUserId, @EmployeeId, @Date, @StartTime, @EndTime, @Reason.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	06-04-2024
 Version			:	1.0 
 Comment			:	1. If the Given @Date & EmployeeId is already Exists, then 
							1.1 Through the Error message as @Status = 0 & @Message = 'Given Date is already Exists.'
						2. IF the Given @Date & EmployeeId is already not Exists, then 
							2.1 Insert into RegularizationDetails table have the Columns of 
								EmployeeId					AS @EmployeeId
								,Date						AS @Date
								,StartTime					AS @StartTime
								,EndTime					AS @EndTime
								,Reason						AS @Reason
								,RegularizationStatusId		AS 2(Submitted)
								,CreatedBy					AS @LoginUserId.
							2.2 Then through the success Message as @Status = 1 And
								@Message = "New RegularizationDetails have been created Successfully.".
=========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertRegularizationDetails]
(	
	@LoginUserId	INT
	,@EmployeeId	INT
	,@Date			DATE
	,@PunchType		INT
	,@InOutTime		TIME
	,@Reason		NVARCHAR(500)
	,@Status		BIT			  OUT	
	,@Message		NVARCHAR(500) OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the variables.
	DECLARE	@CompanyId				TINYINT
			,@RegularizationId		INT
			,@LeaveStatusName		NVARCHAR(50);
		   
	SELECT	@CompanyId	= CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeavestatusDetails];	

	BEGIN TRY	
		--IF EXISTS (SELECT 1 FROM [dbo].[RegularizationDetails] WHERE EmployeeId = @EmployeeId AND [Date] = @Date AND CompanyId = @CompanyId)
		--BEGIN
		--	SELECT	@Status		= 0
		--			,@Message	= 'Given Date & Employee is already Exists.';  
		--	RETURN;
		--END
		--ELSE 
		BEGIN TRAN  
			--Insert the RegularizationDetails.
			INSERT INTO [dbo].[RegularizationDetails](EmployeeId, [Date], PunchType, InOutTime, Reason
						,RegularizationStatusId, CompanyId, CreatedBy)
			VALUES		(@EmployeeId
						,@Date
						,@PunchType
						,@InOutTime
						,@Reason
						,2
						,@CompanyId
						,@LoginUserId);

			SELECT @RegularizationId = SCOPE_IDENTITY();

			--NotificationDetails
			IF @LeaveStatusName = 'Submitted'
			BEGIN
				INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
							,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
							,SMS_To, IsAuto, CompanyId, CreatedBy)					
				SELECT		@RegularizationId
							,'Regularization'
							,1
							,'Owner'
							,CONCAT('Dear Sir, ', ED.FirstName, QUOTENAME(ED.EmployeeCompanyId), ' has requested Regularization On ' ,  
									@InOutTime,'. And the reason is ', @Reason,'.')
							,3
							,UD.EmployeeId
							,'Open'
							,'Open'
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
				FROM	[dbo].[RegularizationDetails] AS RD
				JOIN	[DBO].[EmployeeDetails] ED
					ON	RD.EmployeeId = ED.EmployeeId
				JOIN	(	SELECT	ED.EmployeeId
									,ED.FirstName
									,ED.EmployeeCompanyId
							FROM	[dbo].[EmployeeDetails] AS ED 
							LEFT JOIN	[dbo].[EmployeeDetails] AS RPD
								ON	ED.EmployeeId = RPD.ReportingPersonId
							WHERE	RPD.EmployeeId = @LoginUserId
						) AS  UD
					ON	ED.EmployeeId = RD.EmployeeId
				WHERE	RegularizationId = @RegularizationId 
				AND		RD.CompanyId  = @CompanyId;
			END 

			IF @@TRANCOUNT >= 0
			COMMIT TRAN
			
			SELECT	 @Status  = 1   
					,@Message = 'New RegularizationDetails have been created Successfully.';  

			IF @LeaveStatusName = 'Submitted'
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					-- Result set for Email sended.
					SElECT	RPD.OfficialEmail AS ToMail			
							,'Request for Attendance Regularization' AS [Subject]
							,CONCAT('Dear ',CONCAT(RPD.FirstName,'',RPD.LastName),',') AS FirstLine
							,CONCAT('This is to formally notify you regarding my attendance regularization request for ',CONVERT(NVARCHAR(50),@Date,106), ', as I forgot to check in. The request has been submitted by {', CONCAT(ED.FirstName,'',ED.LastName), QUOTENAME(ED.EmployeeCompanyId),'} for your approval.')  AS SecondLine
							,'I kindly request you to review and approve the necessary corrections at your earliest convenience' AS ThirdLine
							,'For any further clarification, please let me know.' AS FourthLine
							,'Thank You' AS FifthLine
							,'' AS SixthLine
					FROM	EmployeeDetails ED 
					LEFT JOIN EmployeeDetails RPD 
						ON	ED.ReportingPersonId = RPD.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
