 Input Parameter	:	@LoginUserId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@TVP_AttachmentDetails
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	016-09-2024
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertSalaryComponentsDetails]
(
	@LoginUserId					INT	
	,@ComponentName					NVARCHAR(50)
	,@SalaryComponentTypeId			INT
	,@ComponentAliasNameId			TINYINT
	,@CalculationTypeId				INT
	,@EarningAmount					NUMERIC(11,2)
	,@EarningType					NVARCHAR(20)
	,@Description					NVARCHAR(500)
	,@Status						BIT						OUT	
	,@Message						NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId		TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
		
        IF EXISTS( SELECT 1 FROM [dbo].[SalaryComponentsDetails] WHERE  ComponentName = @ComponentName)
		BEGIN
			SELECT	 @Status  = 0
					,@Message = 'Entered ComponentName is already Exists';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[SalaryComponentsDetails](ComponentName, SalaryComponentTypeId
							,ComponentAliasNameId, CalculationTypeId, EarningAmount, EarningType, StatusActive
							,[Description], CompanyId, CreatedBy)
				VALUES	(@ComponentName			
						,@SalaryComponentTypeId	
						,@ComponentAliasNameId
						,@CalculationTypeId
						,@EarningAmount
						,@EarningType
						,1
						,@Description
						,@CompanyId
						,@LoginUserId);

		
		IF @@TRANCOUNT >0
			COMMIT TRAN

			SELECT	@Status   = 1   
				,@Message = 'Record Added Sucessfully'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
