/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertSalaryStructureDetails]
 Description		:	Procedure used to insert the new SalaryStructureDetails
																	(When Click on Insert Button in SalaryStructure PopupPage)
 Input Parameter	:	@LoginUserId, 
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	016-09-2024
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_InsertSalaryStructureDetails]
(
	@LoginUserId									INT	
	,@SalaryStructureName							NVARCHAR(100)
	,@TVP_SalaryStructureComponentMappingDetails	TVP_SalaryStructureComponentMappingDetails	READONLY
	,@Status										BIT											OUT	
	,@Message										NVARCHAR(500)								OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId				TINYINT
			,@SalaryStructureId		INT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
		
        IF EXISTS( SELECT 1 FROM [dbo].[SalaryStructureDetails] WHERE  SalaryStructurename = @SalaryStructureName)
		BEGIN
			SELECT	 @Status  = 0
					,@Message = 'Entered SalaryStructureName is already Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				INSERT INTO [dbo].[SalaryStructureDetails](SalaryStructureName, CompanyId, CreatedBy, CreatedDate)
				VALUES		(@SalaryStructureName		
							,@CompanyId
							,@LoginUserId
							,GETDATE());

				SELECT	@SalaryStructureId  = SCOPE_IDENTITY();

				INSERT INTO [dbo].[SalaryStructureComponentMappingDetails](SalaryStructureId, SalaryComponentsId
							,IsActive, CreatedBy, CreatedDate)
				SELECT		@SalaryStructureId, SalaryComponentsId, IsActive, @LoginUserId, GETDATE()
				FROM		@TVP_SalaryStructureComponentMappingDetails;

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
				,@Message = 'Record Added Sucessfully'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
