/*====================================================================================================================================================   Procedure Name		:	[USP_InsertStatutoryESIDetails] Description		:	Procedure used to insert the new Claimdetails (When Click on Insert Button in ClaimInfo PopupPage) Input Parameter	:	@LoginUserId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@TVP_AttachmentDetails Output Parameters	:	@Status,@Message Author				:	Tharani.T Created on			:	016-09-2024 Version			:	1.0  Comment			:	=====================================================================================================================================================*/CREATE          PROCEDURE [dbo].[USP_InsertStatutoryESIDetails](	@LoginUserId				INT		,@EmployeeESINumber			NVARCHAR(50)	,@DeductionCycle			NVARCHAR(50)	,@EmployeeContribution		NVARCHAR(50)	,@EmployerContribution		NVARCHAR(50)	,@ISEmployerContribution	BIT	,@Status					BIT						OUT		,@Message					NVARCHAR(500)			OUT)ASBEGIN	SET NOCOUNT ON;		DECLARE @CompanyId		TINYINT;	SELECT	@CompanyId	= CompanyId 	FROM	[dbo].[EmployeeDetails]	WHERE	EmployeeId = @LoginUserId;	BEGIN TRY						--If exist,Return the error message as @Status = 0 And @Message = "Entered ClaimTypeId along with ClaimDescription is already Exists"        IF EXISTS( SELECT 1 FROM [dbo].[ESIDetails] WHERE  EmployeeESINumber = @EmployeeESINumber)		BEGIN			SELECT	 @Status  = 0					,@Message = 'Entered EmployeePFNumber is already Exists';			RETURN;		END		ELSE		BEGIN			BEGIN TRAN  				--Procedure will insert the new ClaimDetails				INSERT INTO [dbo].[ESIDetails](EmployeeESINumber,DeductionCycle,EmployeeContribution,EmployerContribution,ISEmployerContribution,CompanyId,CreatedBy,CreatedDate)				VALUES	(@EmployeeESINumber									,@DeductionCycle								,@EmployeeContribution								,@EmployerContribution						,@ISEmployerContribution						,@CompanyId						,@LoginUserId						,GETDATE());				IF @@TRANCOUNT >0			COMMIT TRAN			SELECT	@Status   = 1   				,@Message = 'Record Added Sucessfully'; 		END	END TRY	BEGIN CATCH		ROLLBACK TRAN;		SELECT	@Status   = 0				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	END CATCHEND/*====================================================================================================================================	DECLARE	 @S_Status						BIT			,@M_Message						NVARCHAR(500)		EXEC [dbo].[USP_InsertStatutoryESIDetails]	@LoginUserId				= 15												,@EmployeeESINumber			= '2024-02-23'												,@DeductionCycle			= 7												,@EmployeeContribution		= 3												,@EmployerContribution		= 'dgdfg '												,@ISEmployerContribution	= '500'												,@Status				= @S_Status		OUT												,@Message				= @M_Message	OUT;	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;	 SELECT * 	 FROM [dbo].[ESIDetails]======================================================================================================================================*/
