/*====================================================================================================================================================   Procedure Name		:	[USP_InsertStatutoryProfessionalTaxDetails] Description		:	Procedure used to insert the new Claimdetails (When Click on Insert Button in ClaimInfo PopupPage) Input Parameter	:	@LoginUserId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@TVP_AttachmentDetails Output Parameters	:	@Status,@Message Author				:	Tharani.T Created on			:	016-09-2024 Version			:	1.0  Comment			:	=====================================================================================================================================================*/CREATE   PROCEDURE [dbo].[USP_InsertStatutoryProfessionalTaxDetails](	@LoginUserId								INT		,@WorkLocationId							INT
	,@ProfessionalTaxNumber						NVARCHAR(50)
	,@DeductionCycle							NVARCHAR(50)	,@TVP_ProfessionalTaxSlabMappingDetails		TVP_ProfessionalTaxSlabMappingDetails READONLY	,@Status									BIT						OUT		,@Message									NVARCHAR(500)			OUT)ASBEGIN	SET NOCOUNT ON;		DECLARE @CompanyId				TINYINT			,@ProfessionalTaxId		INT;	SELECT	@CompanyId	= CompanyId 	FROM	[dbo].[EmployeeDetails]	WHERE	EmployeeId = @LoginUserId;	BEGIN TRY						 IF EXISTS( SELECT 1 FROM [dbo].[ProfessionalTaxDetails] WHERE  ProfessionalTaxNumber = @ProfessionalTaxNumber)		BEGIN			SELECT	 @Status  = 0					,@Message = 'Entered ProfessionalTaxNumber is already Exists';			RETURN;		END		ELSE		BEGIN			BEGIN TRAN  				--Procedure will insert the new ClaimDetails				INSERT INTO [dbo].[ProfessionalTaxDetails](WorkLocationId, ProfessionalTaxNumber, DeductionCycle							,CompanyId,CreatedBy,CreatedDate)				VALUES		(@WorkLocationId										,@ProfessionalTaxNumber								,@DeductionCycle										,@CompanyId							,@LoginUserId							,GETDATE());				SELECT @ProfessionalTaxId = SCOPE_IDENTITY();				INSERT INTO [dbo].[ProfessionalTaxSlabMappingDetails](StartRange, EndRange, HalfYearlyTaxAmount
							,ProfessionalTaxId, CreatedBy, CreatedDate)				SELECT		StartRange, EndRange, HalfYearlyTaxAmount, @ProfessionalTaxId, @LoginUserId, GETDATE()				FROM		@TVP_ProfessionalTaxSlabMappingDetails;					IF @@TRANCOUNT >= 0			COMMIT TRAN			SELECT	@Status   = 1   				,@Message = 'Record Added Sucessfully'; 		END	END TRY	BEGIN CATCH		ROLLBACK TRAN;		SELECT	@Status   = 0				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));	END CATCHEND/*====================================================================================================================================	DECLARE	 @S_Status						BIT			,@M_Message						NVARCHAR(500)		EXEC [dbo].[USP_InsertStatutoryProfessionalTaxDetails]	@LoginUserId				= 15															,@EmployeeESINumber			= '2024-02-23'															,@DeductionCycle			= 7															,@EmployeeContribution		= 3															,@EmployerContribution		= 'dgdfg '															,@ISEmployerContribution	= '500'															,@Status				= @S_Status		OUT															,@Message				= @M_Message	OUT;	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;	 	 SELECT * 	 FROM [dbo].[ProfessionalTaxDetails]	 SELECT * 	 FROM [dbo].[ProfessionalTaxSlabMappingDetails]======================================================================================================================================*/
GO
