/*======================================================================================================================================  
 Procedure Name		:	[dbo].[USP_InsertSubscriptionDetails]  
 Description		:	Procedure used to insert the new Subscription Details(When click on Subscribe button in Website)
 Input Parameter	:	@LoginUserId, @Email
 Output Parameters	:	@Status, @Message
 Author				:	TharaniTharan T
 Created on			:	16-07-2024
 Version			:	1.0 
 Comment			:	1. Procedure used to Insert the ContactUsDetails_Website table.
						2. Then through the Success POPUP message as 'Record Added Successfully.'.
=========================================================================================================================================*/
CREATE      PROCEDURE [dbo].[USP_InsertSubscriptionDetails] 
(
	@Email			NVARCHAR(100)
	,@Status		BIT				OUT	
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @SubscriptionId	INT;

	BEGIN TRY
		BEGIN TRAN
			INSERT INTO [dbo].[SubscriptionDetails](Email, CreatedBy, CreatedDate)
			VALUES		(@Email, 1, GETDATE());

			SELECT	@SubscriptionId  = SCOPE_IDENTITY();
						
		IF @@TRANCOUNT > 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Thank you for confirming your subscription.';  

		SELECT	Email, @Message AS [Message]
		FROM	[dbo].[SubscriptionDetails]
		WHERE	SubscriptionId = @SubscriptionId

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);								
												
	EXEC [dbo].[USP_InsertSubscriptionDetails]	@Email		= 'prakash@gmail.com'
												,@Status	= @S_Status		OUT
												,@Message	= @M_Message	OUT;	
										
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT * FROM [dbo].[SubscriptionDetails];
======================================================================================================================================*/

GO
