/*====================================================================================================================================  
 Procedure Name		:	[USP_InsertUpdateClientLocationDetails]
 Description		:	Procedure used to create the new BranchDetails(When Click on Insert Button in ClientLocationInfo PopupPage)
 Input Parameter	:	@LoginUserId, @ClientName, @Address, @City, @State, @Country, @ZipCode, @ContactNo, @Email
 Output Parameters	:	@Status, @Message
 Author				:	Tharanitharan.T
 Created on			:	14-12-2024
 Version			:	1.0 
 Comment			:	
==================================================================================================================================== */
CREATE     PROCEDURE [dbo].[USP_InsertUpdateClientLocationDetails]
(
	@LoginUserId		INT	
	,@ClientLocationId	INT
	,@ClientName		NVARCHAR(100)
	,@Address			NVARCHAR(200)
	,@City				NVARCHAR(100)		
	,@State				NVARCHAR(100)
	,@Country			NVARCHAR(100)		
	,@ZipCode			NVARCHAR(100)	
	,@ContactNumber		NVARCHAR(100)	
	,@Email				NVARCHAR(100)
	,@MapNumber			NVARCHAR(100)
	,@status			BIT				OUT
	,@Message			NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @companyId TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		BEGIN 
			IF @ClientLocationId IS NULL
			BEGIN 
				IF EXISTS(SELECT 1 FROM [dbo].[ClientLocationDetails] WHERE  ClientName = @ClientName AND  CompanyId = @CompanyId)
				BEGIN
					SELECT	@Status   = 0
							,@Message = 'Entered Client Name already Exists.';
					RETURN;
				END
				ELSE 
				BEGIN TRAN  
					INSERT INTO [dbo].[ClientLocationDetails] (ClientName,[Address],City,[State],Country,ZipCode,ContactNumber,Email,MapNumber,CompanyId,CreatedBy,CreatedDate)		   
					VALUES		(@ClientName
								,@Address
								,@City
								,@State
								,@Country
								,@ZipCode
								,@ContactNumber
								,@Email
								,@MapNumber
								,@CompanyId
								,@LoginUserId
								,GETDATE());

				IF @@TRANCOUNT >= 0
				COMMIT TRAN

				SELECT	@Status   = 1   
						,@Message = 'Record Added Sucessfully.';  
	
			END		
			ELSE
			BEGIN 
				IF  EXISTS (SELECT 1 FROM [dbo].[ClientLocationDetails] WHERE ClientLocationId <> @ClientLocationId AND ClientName = @ClientName AND CompanyId = @CompanyId)
				BEGIN
					SELECT	@Status   = 0 
							,@Message = 'Given Client Name is already mapped with another BranchId.'
					RETURN;
				END
				ELSE
				BEGIN
					BEGIN TRAN
						UPDATE	[dbo].[ClientLocationDetails]
						SET		ClientName			= @ClientName	
								,[Address]			= @Address	
								,City				= @City		
								,[State]			= @State	
								,Country			= @Country	
								,ZipCode			= @ZipCode	
								,ContactNumber		= @ContactNumber	
								,Email				= @Email	
								,MapNumber			= @MapNumber
								,UpdatedBy			= @LoginUserId
								,UpdatedDate		= GETDATE()
						WHERE	ClientLocationId	= @ClientLocationId 
						AND		CompanyId			= @CompanyId;

					IF @@TRANCOUNT >= 0
					COMMIT TRAN
					
					SELECT	@Status   = 1   
							,@Message = 'Changes Saved Sucessfully.';  

				END
			END 
		END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)
		
	EXEC [dbo].[USP_InsertUpdateClientLocationDetails]	@LoginUserId		= 1
														,@ClientLocationId	= 1
														,@ClientName		= 'Test User'
														,@Address			= '14,Sai Sadhan Street,Chennai'
														,@City				= 'Chennai'
														,@State				= 'TamilNadu'
														,@Country			= 'India'
														,@ZipCode			= '600002'
														,@ContactNumber		= '9791332885'
														,@Email				= 'tetrosoft14@gmail.com'
														,@MapNumber			= '01'
														,@Status			= @S_Status	 OUT
														,@Message			= @M_Message OUT;	
											
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[ClientLocationDetails];
	
======================================================================================================================================*/
GO
