/*=================================================================================================================================================
 Procedure Name		:	[dbo].[USP_ManageDeviceMappingDetails]
 Description		:	Procedure used to Update the Existing BranchDetails(When Click on Update Button in setting Page)
 Input Parameter	:	@LoginUserId, @EmployeeId, @TVP_EmployeeDeviceMappingDetails.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	18-06-2024
 Version			:	1.0 
 Comment			:	1. 
						2.Then return the output Parameters values as @Status = 1 and @Message = 'Changes Saved Successfully.'.
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_ManageDeviceMappingDetails]
(
	@LoginUserId						INT
	,@EmployeeId						INT   
	,@TVP_EmployeeDeviceMappingDetails	TVP_EmployeeDeviceMappingDetails	READONLY
	,@Status							BIT									OUT	
	,@Message							NVARCHAR(500)						OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variables.
    DECLARE  @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId; 

	BEGIN TRY
		BEGIN TRAN
			MERGE	[dbo].[EmployeeDeviceMappingDetails]	AS TARGET
			USING	@TVP_EmployeeDeviceMappingDetails		AS SOURCE
				ON	(TARGET.EmployeeDeviceMappingId = SOURCE.EmployeeDeviceMappingId
				AND	TARGET.EmployeeId = @EmployeeId)
			WHEN MATCHED THEN
			UPDATE 
			SET		TARGET.EmployeeId				= @EmployeeId
					,TARGET.AttendanceMachineId		= SOURCE.AttendanceMachineId
					,TARGET.IsBlock					= SOURCE.IsBlock
					,TARGET.IsActive				= 1
					,TARGET.Updatedby				= @LoginUserId 
					,TARGET.UpdatedDate				= GETDATE()
			WHEN NOT MATCHED BY TARGET THEN
			INSERT	(EmployeeId, AttendanceMachineId, IsBlock, IsActive, CreatedBy, CreatedDate)
			VALUES	(@EmployeeId
					,SOURCE.AttendanceMachineId
					,IsBlock
					,1
					,@LoginUserId
					,GETDATE())
			WHEN NOT MATCHED BY SOURCE AND TARGET.EmployeeId = @EmployeeId THEN
			DELETE;

		IF @@TRANCOUNT >= 0
		COMMIT TRAN		
			
		SELECT	@Status   = 1  
				,@Message = 'Changes Saved Successfully.'; 

		SELECT	CONCAT('TetroPAY/',ED.CompanyId, '/',ED.EmployeeId) AS EmployeeId
				,CONCAT(FirstName,' ',LastName) AS EmployeeName
				,SerialNo
				,EDMD.IsBlock AS [Status]
		FROM	[dbo].[EmployeeDeviceMappingDetails] EDMD
		JOIN	[dbo].[AttendanceMachineDetails] AMD
			ON	EDMD.AttendanceMachineId = AMD.AttendanceMachineId
		JOIN	[dbo].[EmployeeDetails] ED 
			ON	ED.EmployeeId = EDMD.EmployeeId
		WHERE	EDMD.EmployeeId = @EmployeeId
		AND		ED.CompanyId = @CompanyId;

		SELECT	ESSLUserName
				,ESSLPassword
				,WebAddress
		FROM	[dbo].[ESSLCredentialDetails]
		WHERE	CompanyId = @CompanyId;

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status   = 0
			   ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE @S_Status							BIT
			,@M_Message							NVARCHAR(500)
			,@TVP_EmployeeDeviceMappingDetails	TVP_EmployeeDeviceMappingDetails;

	INSERT INTO @TVP_EmployeeDeviceMappingDetails (EmployeeId, Status)
	VALUES		(5, 1), (6,0);
		
	EXEC [dbo].[USP_ManageDeviceMappingDetails]	@LoginUserId						= 15
												,@EmployeeId						= 51
												,@TVP_EmployeeDeviceMappingDetails	= @TVP_EmployeeDeviceMappingDetails
												,@Status							= @S_Status OUT
												,@Message							= @M_Message OUT;  

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[EmployeeDetails];

	SELECT * FROM [dbo].[EmployeeDeviceMappingDetails]
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_RemainingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=================================================================================================================================
 Procedure Name		:	[dbo].[USP_RemainingDetails]
 Description		:	Procedure used to retrieve the Remaining(Leave,Permission,CompensatoryOff)
 Input Parameter	:	@LoginUserId
 Output Parameters	:	@Status,@Message
 Author				:	Dharani.M
 Created on			:	06-12-2023
 Version			:	1.0 
 Comments			:	1.IF @ModuleName = Leave then Get the RemainingLeave using LeaveDetails Table.
						2.IF @ModuleName = Permission then Get the RemainingHours using PermisionDetails Table.
						3.IF @ModuleName = CompensatoryOff then Get the RemainingCompensatoryOff using CompensatoryOffDetails Table.
						4.Then return the output Parameters values as @Status=1 and @Message = NULL.
===================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_RemainingDetails]
(
	@LoginUserId		INT
	,@ModuleId			INT
	,@EmployeeId		INT
	,@ModuleName		NVARCHAR(50)
	,@LeaveTypeId		TINYINT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN 
	BEGIN TRY 
		--DECLARE @LoginUserId		INT				= 3
		--		,@EmployeeId		INT				= 3
		--		,@ModuleName		NVARCHAR(50)	= 'Leave'
		--		,@LeaveTypeId		TINYINT			= 1;
				
		DECLARE	@CompanyId			TINYINT
				,@LeavePeriod		NVARCHAR(50)
				,@GradeTypeId		TINYINT
				,@IsCarryForward	BIT
				,@Date				INT
				,@YearEnd			INT
				,@Year				INT;

		SELECT	@CompanyId = CompanyId
				,@GradeTypeId = GradeTypeId
		FROM	[dbo].[EmployeeDetails]
		WHERE	EmployeeId = @LoginUserId;

		SELECT	@LeavePeriod = LeavePeriod
				,@IsCarryForward = IsCarryForward
		FROM	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
		JOIN	[dbo].[GradeTypeDetails] GTD
			ON	LTGMD.GradeTypeId = GTD.GradeTypeId
		WHERE	LeaveTypeId = @LeaveTypeId
		AND		LTGMD.GradeTypeId = @GradeTypeId;
		
		DROP TABLE IF EXISTS #Month;
		CREATE TABLE #Month
		(
			Id			INT		IDENTITY(1,1)
			,Months		INT		
			,FromDate	DATE
			,ToDate		DATE
			,CompanyId	TINYINT
		);
		DROP TABLE IF EXISTS #Quaterly;
		CREATE TABLE #Quaterly
		(
			Id			INT		IDENTITY(1,1)
			,Quaterly	INT	
			,FromDate	DATE
			,ToDate		DATE
			,CompanyId	TINYINT
		);
		DROP TABLE IF EXISTS #HalfYearly;
		CREATE TABLE #HalfYearly
		(
			Id				INT		IDENTITY(1,1)
			,HalfYearly		INT		
			,FromDate		DATE
			,ToDate			DATE
			,CompanyId		TINYINT
		);
		DROP TABLE IF EXISTS #Yearly;
		CREATE TABLE #Yearly
		(
			Id				INT		IDENTITY(1,1)
			,Yearly			INT		
			,FromDate		DATE
			,ToDate			DATE
			,CompanyId		TINYINT
		);

		IF @ModuleName = 'Leave'
		BEGIN
			IF @ModuleId IS NULL
			BEGIN 
				SELECT	DISTINCT CASE WHEN @LeaveTypeId = 2 THEN ISNULL(TakenCompOff,0) 
							ELSE ISNULL(TakenLeave,0) END AS TakenLeave
						,CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TakenCompOff,0))
							ELSE (ISNULL(TotalLeave,0) - ISNULL(TakenLeave,0)) 
						END AS Remaining
				FROM	(
							SELECT  DISTINCT CASE	WHEN LTGD.LeavePeriod = 'Monthly' 
													THEN (DATEDIFF(MONTH, CASE WHEN YEAR(LTGD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTGD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTGD.LeaveCount
													WHEN LTGD.LeavePeriod = 'Quaterly' 
													THEN (DATEDIFF(QUARTER, CASE WHEN YEAR(LTGD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTGD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTGD.LeaveCount
													WHEN LTGD.LeavePeriod = 'Half-Yearly' 
													THEN LTGD.LeaveCount * 2
													WHEN LTGD.LeavePeriod = 'Yearly' THEN LTGD.LeaveCount
										ELSE 0 
									END AS TotalLeave
									,ISNULL(TakenLeave,0) AS TakenLeave
									,ISNULL(TotalCompOff,0) AS TotalCompOff
									,ISNULL(TakenCompOff,0) AS TakenCompOff
							FROM    (	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount, LTD.LeaveTypeId
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
									) AS LTGD
							LEFT JOIN	(	SELECT	LeaveTypeId, EmployeeId
													,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
											FROM	[dbo].[LeaveDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		LeaveTypeId = @LeaveTypeId
											AND		LeaveStatusId IN (2, 3)
											GROUP BY LeaveTypeId, EmployeeId
										) AS LD
								ON	LTGD.LeaveTypeId = LD.LeaveTypeId
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId
										) AS LCD
								ON	LTGD.LeaveTypeId = LCD.LeaveTypeId
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId
										) AS COD
								ON	LTGD.LeaveTypeId = COD.CompensatoryOffTypeId
						) AS A

				IF @LeavePeriod = 'Monthly'
				BEGIN 
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE MONTH(CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 12
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Month(Months,FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS( @year, @Date, '01'), 
									EOMONTH(DATEFROMPARTS( @year, @Date, '01')),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	Months,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,TotalLeave
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,ISNULL(TakenLeave,0) AS TakenLeave, (ISNULL(TotalLeave,0) - ISNULL(TakenLeave,0)) AS Remaining
					FROM	(
								SELECT	DISTINCT Months
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,TakenLeave
								FROM	#Month M1
								LEFT JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
														,LTD.LeaveTypeId, CompanyId, MaxCarryForward
												FROM	[dbo].[LeaveTypeDetails] LTD
												JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
													ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
												WHERE   LTD.LeaveTypeId = @LeaveTypeId
												AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,MONTH(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, MONTH(FromDate)
										) AS LD
									ON	M1.Months = LD.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId
										) AS LCD
								ON	LTGD.LeaveTypeId = LCD.LeaveTypeId
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId
										) AS COD
								ON	LTGD.LeaveTypeId = COD.CompensatoryOffTypeId
							) AS A
				END 
				ELSE IF @LeavePeriod = 'Quaterly'
				BEGIN	
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE DATEPART(QUARTER,CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 4
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Quaterly(Quaterly, FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1),
									EOMONTH(DATEADD(MONTH, 2, DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1))),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	DISTINCT Quaterly
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalLeave, TakenLeave
							,(TotalLeave - ISNULL(TakenLeave,0)) AS Remaining
					FROM	(
								SELECT	DISTINCT Quaterly
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
								FROM	#Quaterly M1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
										) AS LD
									ON	M1.Quaterly = LD.FromDate
							) A
				END
				ELSE IF @LeavePeriod = 'Half-Yearly'
				BEGIN 
					SELECT	@Date = CASE WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 
										 WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) = YEAR(GETDATE()) THEN 1
										ELSE 2 END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 2
					FROM	[dbo].[LeaveTypeDetails];

					--UPDATE [LeaveTypeDetails] SET CreatedDate = '2025-01-20 15:44:42.943'

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #HalfYearly(HalfYearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 1, 1)  
										ELSE DATEFROMPARTS(@Year, 7, 1)                
									END
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 6, 30) 
										ELSE EOMONTH(DATEFROMPARTS(@Year, 12, 1))    
									END
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT HalfYearly
							,TotalLeave
							,TakenLeave
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,(TotalLeave - ISNULL(TakenLeave,0)) AS Remaining
					FROM	(
								SELECT	DISTINCT HalfYearly
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
								FROM	#HalfYearly M1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
										) AS LD
									ON ((M1.HalfYearly = 1 AND LD.FromDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND LD.FromDate IN (3, 4)))
							) A
				END 
				ELSE IF @LeavePeriod = 'Yearly'
				BEGIN 
					SELECT	@Date = YEAR(CreatedDate)
							,@Year = YEAR(CreatedDate)
							,@YearEnd = @Date
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Yearly(Yearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,DATEFROMPARTS(@Year, 1, 1)	
									,DATEFROMPARTS(@Year, 12, 31)					
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT Yearly
							,TotalLeave
							,TakenLeave
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,(TotalLeave - ISNULL(TakenLeave,0)) AS Remaining
					FROM	(
								SELECT	DISTINCT Yearly
										,Y1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
								FROM	#Yearly Y1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	Y1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,YEAR(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, YEAR(FromDate)
										) AS LD
									ON	Y1.Yearly = LD.FromDate
							) A
				END 
			END 
			ELSE 
			BEGIN 
				SELECT	DISTINCT CASE WHEN @LeaveTypeId = 2 THEN ISNULL(TakenCompOff,0) 
							ELSE ISNULL(TakenLeave,0) END AS TakenLeave
						,CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TotalTakenCompOff,0))
							ELSE (ISNULL(TotalLeave,0) - ISNULL(TakenLeave,0)) 
						END AS Remaining
				FROM	(
							SELECT  DISTINCT CASE	WHEN LTGD.LeavePeriod = 'Monthly' 
													THEN (DATEDIFF(MONTH, CASE WHEN YEAR(LTGD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTGD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTGD.LeaveCount
													WHEN LTGD.LeavePeriod = 'Quaterly' 
													THEN (DATEDIFF(QUARTER, CASE WHEN YEAR(LTGD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTGD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTGD.LeaveCount
													WHEN LTGD.LeavePeriod = 'Half-Yearly' 
													THEN LTGD.LeaveCount * 2
													WHEN LTGD.LeavePeriod = 'Yearly' THEN LTGD.LeaveCount
										ELSE 0 
									END AS TotalLeave
									,ISNULL(TakenLeave,0) AS TakenLeave
									,ISNULL(TotalCompOff,0) AS TotalCompOff
									,ISNULL(TakenCompOff,0) AS TakenCompOff
									,ISNULL(TotalTakenCompOff,0) AS TotalTakenCompOff
							FROM    (	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount, LTD.LeaveTypeId
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
									) AS LTGD
							LEFT JOIN	(	SELECT	LeaveTypeId
													,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
											FROM	[dbo].[LeaveDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		LeaveTypeId = @LeaveTypeId
											AND		LeaveStatusId IN (2, 3)
											GROUP BY LeaveTypeId
										) AS LD
								ON	LTGD.LeaveTypeId = LD.LeaveTypeId
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveId = @ModuleId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId
										) AS LCD
								ON	LTGD.LeaveTypeId = LCD.LeaveTypeId
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalTakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays, MONTH(FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD1
								ON	LTGD.LeaveTypeId = LCD1.LeaveTypeId
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId
										) AS COD
								ON	LTGD.LeaveTypeId = COD.CompensatoryOffTypeId
						) AS A

				IF @LeavePeriod = 'Monthly'
				BEGIN 
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE MONTH(CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 12
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Month(Months,FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS( @year, @Date, '01'), 
									EOMONTH(DATEFROMPARTS( @year, @Date, '01')),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	Months
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalLeave
							,ISNULL(TakenLeave,0) AS TakenLeave
							,CASE WHEN TotalLeave = TotalTakenLeave THEN 0.00 ELSE CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TotalTakenCompOff,0))
												ELSE (TotalLeave - ISNULL(TakenLeave,0)) END
											END AS Remaining
					FROM	(
								SELECT	DISTINCT Months
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,TakenLeave
										,TotalTakenLeave
								FROM	#Month M1
								LEFT JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
														,LTD.LeaveTypeId, CompanyId, MaxCarryForward
												FROM	[dbo].[LeaveTypeDetails] LTD
												JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
													ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
												WHERE   LTD.LeaveTypeId = @LeaveTypeId
												AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,MONTH(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												AND		LeaveId = @ModuleId
												GROUP BY LeaveTypeId, MONTH(FromDate)
										) AS LD
									ON	M1.Months = LD.FromDate
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TotalTakenLeave
														,MONTH(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, MONTH(FromDate)
											) AS LD1
									ON	M1.Months = LD1.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays, MONTH(FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveId = @ModuleId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD
								ON	M1.Months = LCD.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalTakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays, MONTH(FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = 3
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = 2
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD1
								ON	M1.Months = LCD1.FromDate
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,MONTH(CompensatoryOffDate) AS CompOffDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId, MONTH(CompensatoryOffDate)
										) AS COD
								ON	M1.Months = COD.CompOffDate
							) AS A
				END 
				ELSE IF @LeavePeriod = 'Quaterly'
				BEGIN	
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE DATEPART(QUARTER,CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 4
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Quaterly(Quaterly, FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1),
									EOMONTH(DATEADD(MONTH, 2, DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1))),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	DISTINCT Quaterly
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalLeave
							,CASE WHEN @LeaveTypeId = 2 THEN ISNULL(TakenCompOff,0) ELSE ISNULL(TakenLeave,0) END AS TakenLeave
							,CASE WHEN TotalLeave = TotalTakenLeave THEN 0.00 ELSE CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TotalTakenCompOff,0))
												ELSE (TotalLeave - ISNULL(TakenLeave,0)) END
											END AS Remaining
					FROM	(
								SELECT	DISTINCT Quaterly
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
										,TotalTakenLeave
										,TakenCompOff
										,TotalTakenCompOff
										,TotalCompOff
								FROM	#Quaterly M1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												AND		LeaveId = @ModuleId
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
										) AS LD
									ON	M1.Quaterly = LD.FromDate
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TotalTakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
											) AS LD1
									ON	M1.Quaterly = LD1.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveId = @ModuleId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD
								ON	M1.Quaterly = LCD.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalTakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = 3
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = 2
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD1
								ON	M1.Quaterly = LCD1.FromDate
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,DATEPART(QUARTER,CompensatoryOffDate) AS CompOffDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId, DATEPART(QUARTER,CompensatoryOffDate)
										) AS COD
								ON	M1.Quaterly = COD.CompOffDate
							) A
				END
				ELSE IF @LeavePeriod = 'Half-Yearly'
				BEGIN 
					SELECT	@Date = CASE WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 
										 WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) = YEAR(GETDATE()) THEN 1
										ELSE 2 END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 2
					FROM	[dbo].[LeaveTypeDetails];

					--UPDATE [LeaveTypeDetails] SET CreatedDate = '2025-01-20 15:44:42.943'

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #HalfYearly(HalfYearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 1, 1)  
										ELSE DATEFROMPARTS(@Year, 7, 1)                
									END
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 6, 30) 
										ELSE EOMONTH(DATEFROMPARTS(@Year, 12, 1))    
									END
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT HalfYearly
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalLeave
							,TakenLeave
							,CASE WHEN TotalLeave = TotalTakenLeave THEN 0.00 ELSE CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TotalTakenCompOff,0))
												ELSE (TotalLeave - ISNULL(TakenLeave,0)) END
											END AS Remaining
					FROM	(
								SELECT	DISTINCT HalfYearly
										,M1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
										,TotalTakenLeave
										,TotalCompOff
								FROM	#HalfYearly M1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												AND		LeaveId = @ModuleId
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
										) AS LD
									ON ((M1.HalfYearly = 1 AND LD.FromDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND LD.FromDate IN (3, 4)))
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TotalTakenLeave
														,DATEPART(QUARTER,FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, DATEPART(QUARTER,FromDate)
											) AS LD1
									ON ((M1.HalfYearly = 1 AND LD1.FromDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND LD1.FromDate IN (3, 4)))
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveId = @ModuleId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD
								ON	((M1.HalfYearly = 1 AND LCD.FromDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND LCD.FromDate IN (3, 4)))
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalTakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = 3
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = 2
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD1
								ON	((M1.HalfYearly = 1 AND LCD1.FromDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND LCD1.FromDate IN (3, 4)))
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,DATEPART(QUARTER,CompensatoryOffDate) AS CompOffDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId, DATEPART(QUARTER,CompensatoryOffDate)
										) AS COD
								ON	((M1.HalfYearly = 1 AND COD.CompOffDate IN (1, 2))
								OR (M1.HalfYearly = 2 AND COD.CompOffDate IN (3, 4)))
							) A
				END 
				ELSE IF @LeavePeriod = 'Yearly'
				BEGIN 
					SELECT	@Date = YEAR(CreatedDate)
							,@Year = YEAR(CreatedDate)
							,@YearEnd = @Date
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Yearly(Yearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,DATEFROMPARTS(@Year, 1, 1)	
									,DATEFROMPARTS(@Year, 12, 31)					
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT Yearly
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalLeave
							,TakenLeave
							,CASE WHEN TotalLeave = TotalTakenLeave THEN 0.00 ELSE CASE WHEN @LeaveTypeId = 2 THEN (ISNULL(TotalCompOff,0) - ISNULL(TotalTakenCompOff,0))
											ELSE (TotalLeave - ISNULL(TakenLeave,0)) END
										END AS Remaining
					FROM	(
								SELECT	DISTINCT Yearly
										,Y1.FromDate
										,ToDate
										,MaxCarryForward
										,LeaveCount AS TotalLeave
										,ISNULL(TakenLeave,0) AS TakenLeave
										,TotalTakenLeave
										,TotalCompOff
								FROM	#Yearly Y1
								JOIN	(	SELECT	LeavePeriod, LTD.CreatedDate, LeaveCount
													,LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	Y1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TakenLeave
														,YEAR(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveId = @ModuleId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, YEAR(FromDate)
										) AS LD
									ON	Y1.Yearly = LD.FromDate
								LEFT JOIN	(	SELECT	LeaveTypeId
														,SUM(ISNULL(NoOfDays,0)) AS TotalTakenLeave
														,MONTH(FromDate) AS FromDate
												FROM	[dbo].[LeaveDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		LeaveTypeId = @LeaveTypeId
												AND		LeaveStatusId IN (2, 3)
												GROUP BY LeaveTypeId, MONTH(FromDate)
											) AS LD1
									ON	Y1.Yearly = LD1.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = @EmployeeId
														AND		LeaveId = @ModuleId
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = @LeaveTypeId
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD
								ON	Y1.Yearly = LCD.FromDate
							LEFT JOIN	(	SELECT	LTD.LeaveTypeId
													,FromDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalTakenCompOff
											FROM	[dbo].[LeaveTypeDetails] LTD
											LEFT JOIN (
														SELECT	LeaveTypeId,NoOfDays,DATEPART(QUARTER,FromDate) AS FromDate
														FROM	[dbo].[LeaveDetails] LD
														WHERE	EmployeeId = 3
														AND		LeaveStatusId IN (2, 3)
													) AS LD
												ON	LD.LeaveTypeId = LTD.LeaveTypeId
											WHERE	LTD.LeaveTypeId = 2
											GROUP BY LTD.LeaveTypeId, FromDate
										) AS LCD1
								ON	Y1.Yearly = LCD1.FromDate
							LEFT JOIN	(	SELECT	CompensatoryOffTypeId
													,EmployeeId
													,DATEPART(QUARTER,CompensatoryOffDate) AS CompOffDate
													,SUM(ISNULL(NoOfDays,0)) AS TotalCompOff
											FROM	[dbo].[CompensatoryOffDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		CompensatoryOffTypeId = @LeaveTypeId
											AND		CompensatoryOffStatusId = 3
											GROUP BY CompensatoryOffTypeId, EmployeeId, DATEPART(QUARTER,CompensatoryOffDate)
										) AS COD
								ON	Y1.Yearly = COD.CompOffDate
							) A
				END 
			END 
		END
		IF @ModuleName = 'Permission'
		BEGIN 
			IF @ModuleId IS NULL
			BEGIN
				SELECT	DISTINCT ISNULL(TakenPermission,'00:00') AS TakenPermission
						,FORMAT(DATEADD(SECOND,CASE		WHEN ISNULL(TotalPermission, '00:00') = '00:00' THEN 0
													ELSE DATEDIFF(SECOND, 0, CONVERT(TIME, TotalPermission))
												END 
								- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')), 0), 'HH:mm') AS Remaining
				FROM	(	SELECT	CASE	WHEN LTGD.LeavePeriod = 'Monthly'  THEN PermissionCount
											WHEN LTGD.LeavePeriod = 'Quarterly' THEN PermissionCount
											WHEN LTGD.LeavePeriod = 'Half-Yearly' THEN PermissionCount
											WHEN LTGD.LeavePeriod = 'Yearly' THEN PermissionCount

										ELSE '00:00'
									END AS TotalPermission
									,ISNULL(TakenPermission,'00:00') AS TakenPermission
							FROM    (	SELECT	LeavePeriod, LTD.CreatedDate, PermissionCount, LTD.LeaveTypeId
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
									) AS LTGD
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TakenPermission
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											GROUP BY PermissionTypeId
										) AS LD
								ON	LTGD.LeaveTypeId = LD.PermissionTypeId
						) AS A;

				IF @LeavePeriod = 'Monthly'
				BEGIN 
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE MONTH(CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 12
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Month(Months,FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS( @year, @Date, '01'), 
									EOMONTH(DATEFROMPARTS( @year, @Date, '01')),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	Months,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,TotalPermission
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,ISNULL(TakenPermission,'00:00') AS TakenLeave
							,FORMAT(DATEADD(SECOND,CASE		WHEN ISNULL(TotalPermission, '00:00') = '00:00' THEN 0
														ELSE DATEDIFF(SECOND, 0, CONVERT(TIME, TotalPermission))
													END 
									- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')), 0), 'HH:mm') AS Remaining
					FROM	(
								SELECT	DISTINCT Months
										,M1.FromDate
										,ToDate
										,PermissionCount AS TotalPermission
										,MaxCarryForward
										,TakenPermission
								FROM	#Month M1
								LEFT JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
														,MaxCarryForward
												FROM	[dbo].[LeaveTypeDetails] LTD
												JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
													ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
												WHERE   LTD.LeaveTypeId = @LeaveTypeId
												AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	PermissionTypeId
														,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TakenPermission
														,MONTH(PermissionDate) AS PermissionDate
												FROM	[dbo].[PermissionDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		PermissionTypeId = @LeaveTypeId
												AND		PermissionStatusId IN (2, 3)
												GROUP BY PermissionTypeId, MONTH(PermissionDate)
										) AS LD
									ON	M1.Months = LD.PermissionDate
							) AS A
				END
				ELSE IF @LeavePeriod = 'Quaterly'
				BEGIN	
					SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE DATEPART(QUARTER,CONVERT(DATE, CreatedDate)) END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 4
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Quaterly(Quaterly, FromDate,ToDate, CompanyId)
						VALUES		(@Date, 
									DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1),
									EOMONTH(DATEADD(MONTH, 2, DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1))),
									@CompanyId)

						SET @Date = @Date + 1
					END 

					SELECT	DISTINCT Quaterly
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,TotalPermission
							,ISNULL(TakenPermission,'00:00') AS TakenPermission
							,FORMAT(DATEADD(
											SECOND,
											CASE 
												WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
												ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
											END
											- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
											0
										), 
										'HH:mm'
									) AS Remaining
					FROM	(
								SELECT	DISTINCT Quaterly
										,M1.FromDate
										,ToDate
										,PermissionCount AS TotalPermission
										,MaxCarryForward
										,ISNULL(TakenPermission,'00:00') AS TakenPermission
								FROM	#Quaterly M1
								JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
													,MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	PermissionTypeId
														,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
														,DATEPART(QUARTER,PermissionDate) AS PermissionDate
												FROM	[dbo].[PermissionDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		PermissionTypeId = @LeaveTypeId
												AND		PermissionStatusId IN (2, 3)
												GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
										) AS LD
									ON	M1.Quaterly = DATEPART(QUARTER,PermissionDate)
							) A
				END
				ELSE IF @LeavePeriod = 'Half-Yearly'
				BEGIN 
					SELECT	@Date = CASE WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 
											WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) = YEAR(GETDATE()) THEN 1
										ELSE 2 END
							,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
							,@YearEnd = 2
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #HalfYearly(HalfYearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 1, 1)  
										ELSE DATEFROMPARTS(@Year, 7, 1)                
									END
									,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 6, 30) 
										ELSE EOMONTH(DATEFROMPARTS(@Year, 12, 1))    
									END
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT HalfYearly
							,TotalPermission
							,ISNULL(TakenPermission,'00:00') AS TakenPermission
							,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
							,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
							,@IsCarryForward AS IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,FORMAT(DATEADD(
											SECOND,
											CASE 
												WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
												ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
											END
											- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
											0
										), 
										'HH:mm'
									) AS Remaining
					FROM	(
								SELECT	DISTINCT HalfYearly
										,M1.FromDate
										,ToDate
										,PermissionCount AS TotalPermission
										,MaxCarryForward
										,ISNULL(TakenPermission,'00:00') AS TakenPermission
								FROM	#HalfYearly M1
								JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId, MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	M1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	PermissionTypeId
														,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
														,DATEPART(QUARTER,PermissionDate) AS PermissionDate
												FROM	[dbo].[PermissionDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		PermissionTypeId = @LeaveTypeId
												AND		PermissionStatusId IN (2, 3)
												GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
										) AS PD
									ON ((M1.HalfYearly = 1 AND PD.PermissionDate IN (1, 2))
										OR (M1.HalfYearly = 2 AND PD.PermissionDate IN (3, 4)))
							) A
				END 
				ELSE IF @LeavePeriod = 'Yearly'
				BEGIN 
					SELECT	@Date = YEAR(CreatedDate)
							,@Year = YEAR(CreatedDate)
							,@YearEnd = @Date
					FROM	[dbo].[LeaveTypeDetails];

					WHILE @Date <= @YearEnd
					BEGIN 
						INSERT INTO #Yearly(Yearly, FromDate, ToDate, CompanyId)
						VALUES		(@Date
									,DATEFROMPARTS(@Year, 1, 1)	
									,DATEFROMPARTS(@Year, 12, 31)					
									,@CompanyId)

						SET @Date = @Date + 1
					END

					SELECT	DISTINCT Yearly
							,TotalPermission
							,ISNULL(TakenPermission,'00:00') AS TakenPermission
							,@IsCarryForward
							,ISNULL(MaxCarryForward,0) AS MaxCarryForward
							,FORMAT(DATEADD(
											SECOND,
											CASE 
												WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
												ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
											END
											- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
											0
										), 
										'HH:mm'
									) AS Remaining
					FROM	(
								SELECT	DISTINCT Yearly
										,PermissionCount AS TotalPermission
										,MaxCarryForward
										,ISNULL(TakenPermission,0) AS TakenPermission
								FROM	#Yearly Y1
								JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
													,MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
											) AS LTGD
									ON	Y1.CompanyId = LTGD.CompanyId
								LEFT JOIN	(	SELECT	PermissionTypeId
														,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
														,DATEPART(QUARTER,PermissionDate) AS PermissionDate
												FROM	[dbo].[PermissionDetails]
												WHERE	EmployeeId = @EmployeeId
												AND		PermissionTypeId = @LeaveTypeId
												AND		PermissionStatusId IN (2, 3)
												GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
										) AS PD
									ON	Y1.Yearly = PD.PermissionDate
							) A
				END 
			END 
			ELSE 
			BEGIN 
				SELECT	DISTINCT ISNULL(TakenPermission,'00:00') AS TakenPermission
					,FORMAT(DATEADD(SECOND,CASE		WHEN ISNULL(TotalPermission, '00:00') = '00:00' THEN 0
												ELSE DATEDIFF(SECOND, 0, CONVERT(TIME, TotalPermission))
											END 
							- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')), 0), 'HH:mm') AS Remaining
			FROM	(	SELECT	CASE	WHEN LTGD.LeavePeriod = 'Monthly'  THEN PermissionCount
										WHEN LTGD.LeavePeriod = 'Quarterly' THEN PermissionCount
										WHEN LTGD.LeavePeriod = 'Half-Yearly' THEN PermissionCount
										WHEN LTGD.LeavePeriod = 'Yearly' THEN PermissionCount

									ELSE '00:00'
								END AS TotalPermission
								,ISNULL(TakenPermission,'00:00') AS TakenPermission
						FROM    (	SELECT	LeavePeriod, LTD.CreatedDate, PermissionCount, LTD.LeaveTypeId
									FROM	[dbo].[LeaveTypeDetails] LTD
									JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
										ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
									WHERE   LTD.LeaveTypeId = @LeaveTypeId
									AND		GradeTypeId = @GradeTypeId
								) AS LTGD
						LEFT JOIN	(	SELECT	PermissionTypeId
												,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TakenPermission
										FROM	[dbo].[PermissionDetails]
										WHERE	EmployeeId = @EmployeeId
										AND		PermissionTypeId = @LeaveTypeId
										AND		PermissionStatusId IN (2, 3)
										GROUP BY PermissionTypeId
									) AS LD
							ON	LTGD.LeaveTypeId = LD.PermissionTypeId
					) AS A;

			IF @LeavePeriod = 'Monthly'
			BEGIN 
				SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE MONTH(CONVERT(DATE, CreatedDate)) END
						,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
						,@YearEnd = 12
				FROM	[dbo].[LeaveTypeDetails];

				WHILE @Date <= @YearEnd
				BEGIN 
					INSERT INTO #Month(Months,FromDate,ToDate, CompanyId)
					VALUES		(@Date, 
								DATEFROMPARTS( @year, @Date, '01'), 
								EOMONTH(DATEFROMPARTS( @year, @Date, '01')),
								@CompanyId)

					SET @Date = @Date + 1
				END 

				SELECT	Months
						,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
						,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
						,TotalPermission
						,@IsCarryForward AS IsCarryForward
						,ISNULL(MaxCarryForward,0) AS MaxCarryForward
						,ISNULL(TakenPermission,'00:00') AS TakenPermission
						,CASE WHEN TotalPermission = TotalTakenPermission THEN '00:00' ELSE FORMAT(DATEADD(SECOND,CASE		WHEN ISNULL(TotalPermission, '00:00') = '00:00' THEN 0
													ELSE DATEDIFF(SECOND, 0, CONVERT(TIME, TotalPermission))
												END 
								- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')), 0), 'HH:mm') 
						END AS Remaining
				FROM	(
							SELECT	DISTINCT Months
									,M1.FromDate
									,ToDate
									,PermissionCount AS TotalPermission
									,MaxCarryForward
									,TakenPermission
									,TotalTakenPermission
							FROM	#Month M1
							LEFT JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
													,MaxCarryForward
											FROM	[dbo].[LeaveTypeDetails] LTD
											JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
												ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
											WHERE   LTD.LeaveTypeId = @LeaveTypeId
											AND		GradeTypeId = @GradeTypeId
										) AS LTGD
								ON	M1.CompanyId = LTGD.CompanyId
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TakenPermission
													,MONTH(PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											AND		PermissionId = @ModuleId
											GROUP BY PermissionTypeId, MONTH(PermissionDate)
									) AS LD
								ON	M1.Months = LD.PermissionDate
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TotalTakenPermission
													,MONTH(PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											GROUP BY PermissionTypeId, MONTH(PermissionDate)
									) AS LD1
								ON	M1.Months = LD1.PermissionDate
						) AS A
			END
			ELSE IF @LeavePeriod = 'Quaterly'
			BEGIN	
				SELECT	@Date = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 ELSE DATEPART(QUARTER,CONVERT(DATE, CreatedDate)) END
						,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
						,@YearEnd = 4
				FROM	[dbo].[LeaveTypeDetails];

				WHILE @Date <= @YearEnd
				BEGIN 
					INSERT INTO #Quaterly(Quaterly, FromDate,ToDate, CompanyId)
					VALUES		(@Date, 
								DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1),
								EOMONTH(DATEADD(MONTH, 2, DATEFROMPARTS(@Year, (@Date - 1) * 3 + 1, 1))),
								@CompanyId)

					SET @Date = @Date + 1
				END 

				SELECT	DISTINCT Quaterly
						,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
						,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
						,@IsCarryForward AS IsCarryForward
						,ISNULL(MaxCarryForward,0) AS MaxCarryForward
						,TotalPermission
						,ISNULL(TakenPermission,'00:00') AS TakenPermission
						,CASE WHEN TotalTakenPermission = TotalPermission THEN '00:00' ELSE FORMAT(DATEADD(
										SECOND,
										CASE 
											WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
											ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
										END
										- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
										0
									), 
									'HH:mm'
								) 
						END AS Remaining
				FROM	(
							SELECT	DISTINCT Quaterly
									,M1.FromDate
									,ToDate
									,PermissionCount AS TotalPermission
									,MaxCarryForward
									,ISNULL(TakenPermission,'00:00') AS TakenPermission
									,TotalTakenPermission
							FROM	#Quaterly M1
							JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
												,MaxCarryForward
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
										) AS LTGD
								ON	M1.CompanyId = LTGD.CompanyId
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											AND		PermissionId = @ModuleId
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS LD
								ON	M1.Quaterly = DATEPART(QUARTER,PermissionDate)
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TotalTakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS LD1
								ON	M1.Quaterly = LD1.PermissionDate
						) A
			END
			ELSE IF @LeavePeriod = 'Half-Yearly'
			BEGIN 
				SELECT	@Date = CASE WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) < YEAR(GETDATE()) THEN 1 
										WHEN MONTH(CreatedDate) <= 6 AND YEAR(CreatedDate) = YEAR(GETDATE()) THEN 1
									ELSE 2 END
						,@Year = CASE WHEN YEAR(CreatedDate) < YEAR(GETDATE()) THEN YEAR(CreatedDate) ELSE YEAR(GETDATE()) END
						,@YearEnd = 2
				FROM	[dbo].[LeaveTypeDetails];

				WHILE @Date <= @YearEnd
				BEGIN 
					INSERT INTO #HalfYearly(HalfYearly, FromDate, ToDate, CompanyId)
					VALUES		(@Date
								,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 1, 1)  
									ELSE DATEFROMPARTS(@Year, 7, 1)                
								END
								,CASE	WHEN @Date = 1 THEN DATEFROMPARTS(@Year, 6, 30) 
									ELSE EOMONTH(DATEFROMPARTS(@Year, 12, 1))    
								END
								,@CompanyId)

					SET @Date = @Date + 1
				END

				SELECT	DISTINCT HalfYearly
						,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
						,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
						,@IsCarryForward AS IsCarryForward
						,ISNULL(MaxCarryForward,0) AS MaxCarryForward
						,TotalPermission
						,ISNULL(TakenPermission,'00:00') AS TakenPermission
						,CASE WHEN TotalTakenPermission = TotalPermission THEN '00:00' ELSE  FORMAT(DATEADD(
										SECOND,
										CASE 
											WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
											ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
										END
										- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
										0
									), 
									'HH:mm'
								) 
						END AS Remaining
				FROM	(
							SELECT	DISTINCT HalfYearly
									,M1.FromDate
									,ToDate
									,PermissionCount AS TotalPermission
									,MaxCarryForward
									,ISNULL(TakenPermission,'00:00') AS TakenPermission
									,TotalTakenPermission
							FROM	#HalfYearly M1
							JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId, MaxCarryForward
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
										) AS LTGD
								ON	M1.CompanyId = LTGD.CompanyId
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											AND		PermissionId = @ModuleId
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS PD
								ON ((M1.HalfYearly = 1 AND PD.PermissionDate IN (1, 2))
									OR (M1.HalfYearly = 2 AND PD.PermissionDate IN (3, 4)))
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TotalTakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS LD1
								ON	((M1.HalfYearly = 1 AND LD1.PermissionDate IN (1, 2))
									OR (M1.HalfYearly = 2 AND LD1.PermissionDate IN (3, 4)))
						) A
			END 
			ELSE IF @LeavePeriod = 'Yearly'
			BEGIN 
				SELECT	@Date = YEAR(CreatedDate)
						,@Year = YEAR(CreatedDate)
						,@YearEnd = @Date
				FROM	[dbo].[LeaveTypeDetails];

				WHILE @Date <= @YearEnd
				BEGIN 
					INSERT INTO #Yearly(Yearly, FromDate, ToDate, CompanyId)
					VALUES		(@Date
								,DATEFROMPARTS(@Year, 1, 1)	
								,DATEFROMPARTS(@Year, 12, 31)					
								,@CompanyId)

					SET @Date = @Date + 1
				END

				SELECT	DISTINCT Yearly
						,CONVERT(NVARCHAR(50),FromDate,105) AS FromDate
						,CONVERT(NVARCHAR(50),ToDate,105) AS ToDate
						,@IsCarryForward
						,ISNULL(MaxCarryForward,0) AS MaxCarryForward
						,TotalPermission
						,ISNULL(TakenPermission,'00:00') AS TakenPermission
						,CASE WHEN TotalTakenPermission = TotalPermission THEN '00:00' ELSE FORMAT(DATEADD(
										SECOND,
										CASE 
											WHEN ISNULL(TRY_CAST(TotalPermission AS TIME), '00:00') = '00:00' THEN 0
											ELSE DATEDIFF(SECOND, 0, TRY_CAST(TotalPermission AS TIME))
										END
										- DATEDIFF(SECOND, 0, ISNULL(TakenPermission, '00:00')),
										0
									), 
									'HH:mm'
								) 
						END AS Remaining
				FROM	(
							SELECT	DISTINCT Yearly
									,PermissionCount AS TotalPermission
									,MaxCarryForward
									,ISNULL(TakenPermission,0) AS TakenPermission
									,TotalTakenPermission
									,FromDate
									,ToDate
							FROM	#Yearly Y1
							JOIN	(	SELECT	LeavePeriod, PermissionCount, LTD.LeaveTypeId, CompanyId
												,MaxCarryForward
										FROM	[dbo].[LeaveTypeDetails] LTD
										JOIN    [dbo].[LeaveTypeGradeMappingDetails] LTGD
											ON	LTD.LeaveTypeId = LTGD.LeaveTypeId
										WHERE   LTD.LeaveTypeId = @LeaveTypeId
										AND		GradeTypeId = @GradeTypeId
										) AS LTGD
								ON	Y1.CompanyId = LTGD.CompanyId
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'), 5) AS TakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											AND		PermissionId = @ModuleId
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS PD
								ON	Y1.Yearly = PD.PermissionDate
							LEFT JOIN	(	SELECT	PermissionTypeId
													,LEFT(FORMAT(DATEADD(SECOND, SUM(DATEDIFF(SECOND, 0, NumberOfHours)), 0), 'HH:mm:ss'),5) AS TotalTakenPermission
													,DATEPART(QUARTER,PermissionDate) AS PermissionDate
											FROM	[dbo].[PermissionDetails]
											WHERE	EmployeeId = @EmployeeId
											AND		PermissionTypeId = @LeaveTypeId
											AND		PermissionStatusId IN (2, 3)
											GROUP BY PermissionTypeId, DATEPART(QUARTER,PermissionDate)
									) AS LD1
								ON	Y1.Yearly = LD1.PermissionDate
						) A
				END 
			END 
		END
		ELSE IF @ModuleName = 'CompensatoryOff'
		BEGIN 
			SELECT	DISTINCT TakenCompOff AS TakenCompensatoryOff
					,CASE WHEN Remaining < 0 THEN 0 ELSE Remaining END AS Remaining
					,DateDifference
			FROM 
					(
						SELECT	ISNULL(TakenCompOff,0) AS TakenCompOff
								,ISNULL(TotalCompOff,0) - ISNULL(TakenCompOff,0) AS Remaining
								,CASE	WHEN @LeavePeriod = 'Monthly'	THEN LEFT(CONVERT(NVARCHAR(50),DATEADD(MM, 1, (GETDATE())),120),10) 
										WHEN @LeavePeriod = 'Quaterly'	THEN LEFT(CONVERT(NVARCHAR(50),DATEADD(QQ, 1, (GETDATE())),120),10) 
										WHEN @LeavePeriod = 'Yearly'	THEN LEFT(CONVERT(NVARCHAR(50),DATEADD(YY, 1, (GETDATE())),120),10) 
									ELSE ''
								END AS DateDifference
						FROM	(	SELECT	DISTINCT LTD.LeaveTypeId, TotalCompOff, TakenCompOff
											,CASE	WHEN LTD.LeavePeriod = 'Monthly' 
													THEN (DATEDIFF(MONTH, CASE WHEN YEAR(LTD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTD.LeaveCount
													WHEN LTD.LeavePeriod = 'Quaterly' 
													THEN (DATEDIFF(QUARTER, CASE WHEN YEAR(LTD.CreatedDate) < YEAR(GETDATE()) THEN DATEFROMPARTS(YEAR(GETDATE()),'01','01') ELSE LTD.CreatedDate END, DATEFROMPARTS(YEAR(GETDATE()), 12, 30)) + 1) * LTD.LeaveCount
													WHEN LTD.LeavePeriod = 'Half-Yearly' THEN LTD.LeaveCount * 2
													WHEN LTD.LeavePeriod = 'Yearly' THEN LTD.LeaveCount
												ELSE 0 
											END AS TotalLeave
									FROM	(	SELECT	CompanyId, IsCarryForward, LeavePeriod, LeaveCount
														,LTD.LeaveTypeId, MaxCarryForward, LTD.CreatedDate
												FROM	[dbo].[LeaveTypeDetails] LTD 
												JOIN	[dbo].[LeaveTypeGradeMappingDetails] LTGMD
													ON	LTD.LeaveTypeId = LTGMD.LeaveTypeId
												WHERE	LTD.LeaveTypeId = @LeaveTypeId
											) AS LTD
									LEFT JOIN	(	SELECT	CompensatoryOffTypeId
															,EmployeeId
															,ISNULL(SUM(ISNULL(NoOfDays,0)),0) AS TotalCompOff
													FROM	[dbo].[CompensatoryOffDetails] 
													WHERE	EmployeeId = @EmployeeId 
													AND		CompensatoryOffStatusId = @LeaveTypeId
													AND		CompanyId = @CompanyId
													GROUP BY CompensatoryOffTypeId, EmployeeId
												) LD
										ON	LD.CompensatoryOffTypeId = LTD.LeaveTypeId
									LEFT JOIN	(
													SELECT	LeaveTypeId, EmployeeId, SUM(ISNULL(NoOfDays,0)) AS TakenCompOff
													FROM	[dbo].[LeaveDetails]
													WHERE	LeaveTypeId = @LeaveTypeId
													AND		EmployeeId = @EmployeeId
													AND		CompanyId = @CompanyId
													GROUP BY LeaveTypeId, EmployeeId
												) AS LCD
										ON	LD.EmployeeId = LCD.EmployeeId
								) AS LTD
						) AS C
		END
		SELECT  @Status   = 1 
				,@Message  = NULL;		
	END TRY
	BEGIN CATCH
		SELECT  @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===================================================================================================================================
	DECLARE	 @Status	BIT 
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_RemainingDetails]	@LoginUserId		= 2
										,@ModuleId			= NULL
										,@EmployeeId		= 2
										,@LeaveTypeId		= 2
										,@ModuleName		= 'CompensatoryOff'
										,@Status			= @Status   OUT	
										,@Message			= @Message  OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;
	 
	SELECT * FROM [dbo].[LeaveDetails] 
	SELECT	* FROM [dbo].[CompensatoryOffDetails]  
	WHERE	EmployeeId = 8 AND CompensatoryOffTypeId = 2
	SELECT * FROM [dbo].[PermissionDetails]
	SELECT * FROM LeaveTypeDetails;  
	SELECT * FROM LeaveTypeGradeMappingDetails;  
	SELECT * FROM EmployeeDetails;
	SELECT * FROM LeaveStatusDetails;
===================================================================================================================================*/
	
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_AdvanceDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_AdvanceDetails]
 Description		:	Procedure used to retrive the AdvanceDetails (When click on AdvanceCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-08-2023
 Version			:	1.0 
 Comment			:	1. If The Given @ReportCategory ='Employee' and @ReportValue = 0 then get all the records Else given @ReportValue <> 0 then 
								get the given reportvalue record have the columns of AdvanceId, Date, EmployeeId, EmployeeImage, Employee,
								,AdvanceAmount, DueAmount, Status, Status_Colour, ApprovedPersonImage, ApprovedBy to show in Grid.
							1.1 Then Return the output Parameter values as @Status = 1 and @Message = NULL.
						2. If The Given @ReportCategory ='AdvanceStatus' and @ReportValue = 0 then get all the records Else given @ReportValue <> 0 then 
								get the given reportvalue record have the columns of AdvanceId, Date, EmployeeId, EmployeeImage, Employee,
								,AdvanceAmount, DueAmount, Status, Status_Colour, ApprovedPersonImage, ApprovedBy to show in Grid.
							2.1 Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_AdvanceDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME 
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT		
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT 
			,@DSqlQuery		NVARCHAR(MAX);
		
	SELECT	@CompanyId = CompanyId  
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Advance Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation  
					,CONCAT(N'₹ ',SUM(ISNULL(AdvanceAmount,0))) AS AdvanceAmount
					,CONCAT(N'₹ ',SUM(ISNULL(DueAmount,0))) AS DueAmount
			FROM	[dbo].[AdvanceDetails] AD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	AD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId 
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName;
 		END 
		ELSE 
		BEGIN   
			SET	@DSqlQuery = '	SELECT	BranchName AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation 
										,CONVERT(NVARCHAR(50),AdvanceDate,106) AS [Date]
										,CONCAT(NCHAR(8377),'''',ISNULL(AdvanceAmount,0)) AS AdvanceAmount
										,CONCAT(NCHAR(8377),'''',ISNULL(DueAmount,0)) AS DueAmount
										,LeaveStatusName AS [Status]
										,CASE WHEN AD.AdvanceStatusId IN(3,4,5,6,7) THEN ISNULL(AAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN AD.AdvanceStatusId IN(3,4,5,6,7) THEN CONCAT(AAD.FirstName,'' '',AAD.LastName)
												ELSE '' ''
										END AS ApprovedBy 
								FROM	[dbo].[AdvanceDetails] AD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	AD.EmployeeId = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId  
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	AD.AdvanceStatusId = LSD.LeaveStatusId
								LEFT JOIN	(	SELECT	AdvanceId, EmployeeImage, FirstName, LastName
												FROM	[dbo].[AdvanceDetails] AD
												JOIN	[dbo].[Employeedetails] ED
													ON	AD.EmployeeId = ED.EmployeeId 
												WHERE	AD.CompanyId = @CompanyId 
											) AS AAD
									ON	AD.AdvanceId = AAD.AdvanceId ' 
		 
			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Advance Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,AdvanceDate);'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Advance Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,AdvanceDate);'
			END 
			ELSE IF @ReportCategory = 'Status'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Advance Report' AS ReportName
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	AD.AdvanceStatusId = CASE WHEN @ReportValue = 0 THEN AD.AdvanceStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,AdvanceDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,AdvanceDate);'
			END
		
		PRINT @DSqlQuery;
		EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
											,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
	END
		 SELECT	@Status = 1 
				,@Message = NULL;

	END TRY 
	BEGIN CATCH 
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_AdvanceDetails] @LoginUserId			= 1
										   ,@FromDate			=  NULL -- '2025-02-01'
										   ,@ToDate				=  NULL -- '2025-02-28'
										   ,@ReportCategory		= 'Status'
										   ,@ReportValue		= 2
										   ,@Status				= @Status	OUT
										   ,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[AdvanceDetails];

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_AttendanceLogDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=========================================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_Rpt_AttendanceLogDetails]
 Description		:	Procedure used to retrive the AttendanceLog ReportDetails (When click on the ReportInfo in SideNavigationBar 
						and When Click On AttendanceCategory On Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-08-2023
 Version			:	2.0 
 Comment			:	1. Get the AttendanceLogDetails Report for the Given @LoginUserId, @FromDate, @ToDate
							,@ReportCategory, @ReportValue to show the values in Grid.
						2. Then return the output parameter values @Status = 1 & @Message = NULL.
==================================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_AttendanceLogDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--DECLARE	@LoginUserId		INT				= 1
	--		,@FromDate			DATETIME		= '2025-01-01'
	--		,@ToDate			DATETIME		= '2025-01-31'
	--		,@ReportCategory	NVARCHAR(100)	= 'Status'
	--		,@ReportValue		SQL_VARIANT		= 8

	DECLARE @CompanyId			TINYINT
			,@StartDate			DATETIME  
			,@EndDate			DATETIME  
			,@EffectiveWorkDays	INT;
 
	IF @FromDate IS NULL AND @ToDate IS NULL 
	BEGIN 
		SET	@StartDate	= DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), '01')
		SET @EndDate	= DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), DAY(GETDATE()))
	END 
	ELSE 
	BEGIN 
		SET @StartDate	= @FromDate
		SET @EndDate	= @ToDate
	END  
	SELECT	@EffectiveWorkDays = DAY(EOMONTH(DATEFROMPARTS(YEAR(@FromDate),MONTH(@FromDate),'01'))); 

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	DROP TABLE IF EXISTS #Attendance;
	CREATE TABLE #Attendance 
	(
		Id				INT		IDENTITY(1,1)
		,PunchDate		DATE
		,CompanyId		TINYINT
	);

	WHILE @StartDate <= @EndDate
	BEGIN
		INSERT INTO #Attendance (PunchDate, CompanyId) 
		VALUES		(@StartDate,@CompanyId);

		SET			@StartDate = DATEADD(DAY,1, @StartDate);
	END;
	 	 
	BEGIN TRY
		IF @ReportCategory IN ('Branch', 'Department', 'Status')
		BEGIN 
	
			DROP TABLE IF EXISTS #ResultSet;
			SELECT	DISTINCT ED.EmployeeId
					,ED.BranchId
					,BranchName AS Branch
					,ED.DepartmentId
					,DepartmentName AS Department
					,CONCAT(EmployeeCompanyId, ' - ', FirstName,' ',LastName) AS EmpName
					,CONVERT(VARCHAR(50), AT.PunchDate, 113) AS [Date]
					,DATENAME(DW,AT.PunchDate) AS [Day]
					,AT.PunchDate
					,RIGHT(LEFT(CONVERT(VARCHAR(20), CAST(PH.InTime AS TIME), 100), 7), 8) AS PunchIn
					,ISNULL(FORMAT(PunchOut, 'hh:mm tt'), '') AS PunchOut
					,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, CONVERT(TIME, PH.InTime), CONVERT(TIME, PH.OutTime)), 0), 114),'00:00'),5),' Hrs') AS TotalHours
					,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5),' Hrs') AS WorkingHours
					,ISNULL(BH. [Break],'00:00 Hrs') AS [Break]
					,CASE WHEN OutTime_NULL IS NULL AND PH.PunchDate = CONVERT(DATE,GETDATE())
								AND CONVERT(TIME,OH.EndTime) < CONVERT(TIME,OutTime)
							THEN CONCAT(LEFT(CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.EndTime, CONVERT(TIME, GETDATE())), 0), 114),5),' Hrs')
						ELSE OH.OverTime END AS OverTime
					, CONCAT(LEFT(CASE WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) <= PD.EndTime THEN '00:00 Hrs'
									   WHEN PD.EmployeeId IS NOT NULL AND CONVERT(TIME, PH.InTime) > PD.EndTime THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, PD.EndTime, CONVERT(TIME, PH.InTime)), 0), 114)
									WHEN CONVERT(TIME, PH.InTime) > OH.StartTime 
									THEN CONVERT(VARCHAR(12),DATEADD(MINUTE,DATEDIFF(MINUTE, OH.StartTime, CONVERT(TIME, PH.InTime)), 0), 114)  
								ELSE '00:00' END,5), ' Hrs'
						) AS lateCheckin  
					,CONCAT(LEFT(ISNULL(PD.NumberOfHours,'00:00'), 5), ' Hrs') As PermissionHours
  					,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Leave/CompOff'
							WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'CompOff/Leave'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Leave/Absent'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Leave/Present'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Leave/Absent'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Present/Leave'
							WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'WeekEnd' 
							WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Holiday'
							WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Leave'
							WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Absent' 
							WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'CompOff'
							WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'YetToRegularize'
							WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Present' 
							WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Present' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
								AND TotalMinutesPerDay < 240 THEN 'Absent' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'HalfDay' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'HalfDay' 
							ELSE 'Present'
					END AS [Status]
					,CASE	WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
							WHEN LSD.IsHalfDay = 1 AND LSD.IsFirstHalf = 0 AND LSD.EmployeeId IS NOT NULL AND LSD.LeaveTypeId = 2 THEN 'Orange'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Yellow'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Green'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 'Yellow'
							WHEN LD.IsHalfDay = 1 AND LD.IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND TotalMinutesPerDay > 240 THEN 'Orange'
							WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') AND (ESMD.StartTime IS NULL OR ESMD.EndTime IS NULL) THEN 'Red' 
							WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 'Red'
							WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) AND LD.LeaveTypeId <> 2 AND (PH.InTime IS NULL OR ISNULL(PH.InTime,'') = '') AND HolidayId IS NULL THEN 'Orange'
							WHEN LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND  LSD.EmployeeId IS NULL THEN 'Red' 
							WHEN LSD.EmployeeId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND IsWorkingDay IS NULL THEN 'Pink'
							WHEN LEFT(ISNULL(CONVERT(VARCHAR(12),DATEADD(MINUTE, TotalMinutesPerDay, 0), 114),'00:00'),5) > '11:59' THEN 'Red'
							WHEN NoOfHours IS NULL AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay, 0) >= 480 THEN 'Green' 
							WHEN NoOfHours IS NULL AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay, 0), 114), '00:00') >= '08:00' THEN 'Green' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) 
								AND TotalMinutesPerDay < 240 THEN 'Red' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(TotalMinutesPerDay + NoOfHours, 0) < 480 THEN 'Blue' 
							WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, TotalMinutesPerDay + NoOfHours, 0), 114), '00:00') < '08:00' THEN 'Blue' 
							ELSE 'Green'
					END AS Status_Colour
					,LD.FromDate AS LeaveStartDate
					,LD.ToDate AS LeaveEndDate
					,PD.PermissionDate
					,LSD.FromDate AS CompOffDate
					,LSD.ToDate AS CompOffEndDate
					,ESMD.StartTime
					,ESMD.EndTime 
					,ED.CompanyId
			INTO	#ResultSet
			FROM	[dbo].[EmployeeDetails] ED
			JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			CROSS JOIN #Attendance AT
			LEFT JOIN	(
							SELECT	CompanyId, IsWorkingDay, [Day] 	
							FROM	[dbo].[CompanyWorkingDayDetails]
							WHERE	IsWorkingDay = 0
							AND		CompanyId = @CompanyId
						) AS CWDD
				ON	CWDD.CompanyId = ED.CompanyId
				AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
			LEFT JOIN [dbo].[HolidayDetails] HD
				ON	AT.PunchDate = HD.HolidayDate
			LEFT JOIN (	
						SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
						FROM	EmployeeShiftMappingDetails ESMD
						JOIN	EmployeeDetails ED
							ON	ESMD.EmployeeId = ED.EmployeeId
						LEFT JOIN ShiftDetails SD
							ON	SD.ShiftId = ESMD.ShiftId 
					) AS ESMD
				ON ED.EmployeeId = ESMD.EmployeeId 
				AND AT.PunchDate BETWEEN StartDate AND EndDate
			LEFT JOIN (
						SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
								,MAX(OutTime) AS OutTime
								,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
								,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
						FROM	(
									SELECT	ED.EmployeeId
											,PunchDate
											,CONVERT(TIME,PunchTime) AS InTime
											,Status
											,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
														AND  CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
												WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
														AND  CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
												ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime))
											END) AS OutTime
									FROM	[dbo].[EmployeeDetails] ED	
									JOIN	[dbo].[AttendanceLogDetails] ALD	
										ON	ED.EmployeeId = ALD.EmployeeId  
								) AS ALD
						WHERE	[Status] = 1
						GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate) 
					) AS PH
				ON ED.EmployeeId = PH.EmployeeId 
				AND AT.PunchDate = PH.PunchDate
			LEFT JOIN (
						SELECT	EmployeeId
								,PunchDate
								,CONCAT(LEFT(ISNULL(CONVERT(VARCHAR(12), DATEADD(MINUTE, SUM(BreakMinutes), 0), 114),'00:00'),5),' Hrs') AS [Break]
						FROM	(
									SELECT	ED.EmployeeId
											,ALD.PunchDate
											,LEAD(ALD.Status) OVER (PARTITION BY ALD.EmployeeId, ALD.PunchDate ORDER BY ALD.PunchTime) AS A
											,CASE  WHEN ALD.[Status] = 0
												THEN DATEDIFF(MINUTE, ALD.PunchTime, LEAD(ALD.PunchTime) OVER (PARTITION BY ALD.PunchDate ORDER BY ALD.PunchTime))
												ELSE 0 
											END AS BreakMinutes
											,[Status]
									FROM	[dbo].[EmployeeDetails] ED
									JOIN	[dbo].[AttendanceLogDetails] ALD
										ON  ED.EmployeeId = ALD.EmployeeId 				
								) AS ALD
						WHERE	[Status] = 0
						GROUP BY EmployeeId, PunchDate
					) AS BH
				ON ED.EmployeeId = BH.EmployeeId 
				AND AT.PunchDate = BH.PunchDate
			LEFT JOIN (
						SELECT	DISTINCT ALD.EmployeeId
								,ALD.PunchDate
								,ALD.LastOutTime
								,SD.StartTime
								,SD.EndTime
								,CONCAT(LEFT(CONVERT(VARCHAR(50), DATEADD(MINUTE,CASE WHEN ALD.LastOutTime > SD.EndTime 
																		THEN DATEDIFF(MINUTE, SD.EndTime, ALD.LastOutTime) 
														ELSE 0 END, 0), 114),5),' Hrs') AS OverTime 
						FROM	(
									SELECT	EmployeeId
											,PunchDate
											,MAX(CONVERT(TIME, PunchTime)) AS LastOutTime
									FROM	[dbo].[AttendanceLogDetails] 
									GROUP BY EmployeeId, PunchDate
								) AS ALD
						LEFT JOIN	[dbo].[EmployeeShiftMappingDetails] ESMD
							ON	ALD.EmployeeId = ESMD.EmployeeId
						LEFT JOIN	[dbo].[ShiftDetails] SD
							ON	ESMD.ShiftId = SD.ShiftId
						)OH
					ON ED.EmployeeId = OH.EmployeeId 
					AND AT.PunchDate = OH.PunchDate
			LEFT JOIN (
						SELECT	EmployeeId
								,PermissionDate
								,NumberOfHours
								,DATEDIFF(MINUTE,0,NumberOfHours) AS NoOfHours
								,EndTime
								,StartTime
						FROM	[dbo].[PermissionDetails]	 
						) AS PD
				ON ED.EmployeeId = PD.EmployeeId 
				AND AT.PunchDate = PD.PermissionDate
			LEFT JOIN	(	
						SELECT	EmployeeId, PunchDate, PunchOut
						FROM	(
									SELECT	ED.EmployeeId
											,PunchDate
											,MAX(PunchTime) AS PunchOut
											,[Status]
									FROM	[dbo].[EmployeeDetails] ED	
									JOIN	[dbo].[AttendanceLogDetails] ALD	
										ON	ED.EmployeeId = ALD.EmployeeId  
									GROUP BY ED.EmployeeId, PunchDate, [Status], DATENAME(DW,PunchDate) 
								) AS A
						WHERE	[Status] = 0
						) AS PO
				ON ED.EmployeeId = PO.EmployeeId 
				AND AT.PunchDate = PO.PunchDate
			LEFT JOIN	(
							SELECT	EmployeeId, FromDate, ToDate, LeaveStatusId, IsHalfDay, IsFirstHalf, LeaveTypeId
							FROM	[dbo].[LeaveDetails]
							WHERE	LeaveStatusId IN (2, 3)
							AND		LeaveTypeId <> 2
						) AS LD
				ON ED.EmployeeId = LD.EmployeeId 
				AND AT.PunchDate BETWEEN FromDate AND ToDate
			LEFT JOIN	(
							SELECT	EmployeeId, FromDate, ToDate, LeaveTypeId, IsHalfDay, IsFirstHalf
							FROM	[dbo].[LeaveDetails] 
							WHERE	LeaveStatusId IN (2, 3) 
							AND		LeaveTypeId = 2
						) AS LSD
				ON ED.EmployeeId = LSD.EmployeeId 
				OR AT.PunchDate BETWEEN LSD.FromDate AND LSD.ToDate;
			 
			DECLARE	@DSQLQuery	NVARCHAR(MAX);

			SET @DSQLQuery = '	SELECT	Branch
										,Department
										,EmpName	
										,[Date]
										,[Day] 
										,ISNULL(PunchIn, '''') AS PunchIn
										,ISNULL(PunchOut, '''') AS PunchOut
										,ISNULL(TotalHours,''00:00 Hrs'') AS TotalHours
										,ISNULL(WorkingHours,''00:00 Hrs'') AS WorkingHours	
										,ISNULL([Break],''00:00 Hrs'') AS	[Break]
										,ISNULL(OverTime,''00:00 Hrs'') AS OverTime	
										,ISNULL(lateCheckin,''00:00 Hrs'') AS lateCheckin
										,ISNULL(PermissionHours,''00:00 Hrs'') AS PermissionHours
										,[Status]
								FROM	#ResultSet '

			IF @ReportCategory = 'Branch'
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	BranchId = CASE wHEN @ReportValue = 0 THEN BranchId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY PunchDate, EmployeeId ASC; '
			END 
			ELSE IF @ReportCategory = 'Department'
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	DepartmentId = CASE wHEN @ReportValue = 0 THEN DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY PunchDate, EmployeeId ASC; '
			END  
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 1
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Leave' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	(@FromDate IS NULL AND @ToDate IS NULL) OR ((CONVERT(DATE,LeaveStartDate) BETWEEN @FromDate AND @ToDate) OR (CONVERT(DATE,LeaveEndDate) BETWEEN @FromDate AND @ToDate))
													AND		[Status] = ''Leave''
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 2
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Permission' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY PunchDate, EmployeeId ASC; '	
			END        
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 3
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'CompensatoryOff' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR ((CONVERT(DATE,CompOffDate) BETWEEN @FromDate AND @ToDate) OR (CONVERT(DATE,CompOffEndDate) BETWEEN @FromDate AND @ToDate))) 
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 4
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'OverTime' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	(@FromDate IS NULL AND @ToDate IS NULL) OR ((CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate)) 
													AND		(OverTime <> ''00:00 Hrs'')
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 5
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'HalfDay' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													AND		([Status] = ''HalfDay'')
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 6
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Present' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													AND		([Status] = ''Present'')
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 7
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Absent' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													AND		([Status] = ''Absent'')
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
			ELSE IF @ReportCategory = 'Status' AND @ReportValue = 8
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'LateCheckIn' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Attendance Report' AS ReportName 

				SELECT	@DSQLQuery = @DSQLQuery + '	WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PunchDate) BETWEEN @FromDate AND @ToDate))
													AND		(LateCheckIn <> ''00:00 Hrs'')
													ORDER BY PunchDate, EmployeeId ASC; '	
			END     
		 
			PRINT @DSQLQuery;
			EXEC SP_EXECUTESQL @DSQLQuery, N' @ReportValue SQL_VARIANT, @FromDate DATETIME, @ToDate DATETIME'
											  ,@ReportValue, @FromDate, @ToDate;
		END 
		ELSE IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Summarize' END AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Attendance Report' AS ReportName;

			DROP TABLE IF EXISTS #ResultSet_1;
			SELECT	EmployeeId
					,Branch
					,Department
					,EmployeeName 
					,EffectiveWorkDays	
					,SUM(ISNULL(TotalTakenLeave,0)) AS TotalTakenLeave
					,SUM(ISNULL(TakenPermission,0)) AS TakenPermission
					,SUM(ISNULL(TakenCompOff,0)) AS TakenCompOff 
					,CASE WHEN @EffectiveWorkDays <= SUM(ISNULL(TotalWorkingDays,0))
						THEN @EffectiveWorkDays ELSE SUM(ISNULL(TotalWorkingDays,0))
					END AS TotalWorkingDays
					,CASE WHEN @EffectiveWorkDays <= (SUM(ISNULL(TotalWorkingDays,0)))
					THEN 0 ELSE ((@EffectiveWorkDays) - (SUM(ISNULL(TotalWorkingDays,0)))) END AS LOP 
					,COUNT(LateCheckIn) AS TotalLateCheckIn 
			INTO	#ResultSet_1 
			FROM	( 
						SELECT	DISTINCT AT.PunchDate AS [Date]
								,ED.EmployeeId	
								,BranchName AS Branch
								,DepartmentName AS Department
								,CONCAT(EmployeeCompanyId,' - ',FirstName, ' ', LastName) AS EmployeeName 
								,@EffectiveWorkDays AS EffectiveWorkDays 
								,ISNULL(TotalTakenLeave,0) AS TotalTakenLeave
								,ISNULL(NoOfHours,0) AS TakenPermission
								,ISNULL(TakenCompOff,0) AS TakenCompOff
								,CASE	WHEN LD.EmployeeId IS NOT NULL AND LD.IsHalfDay = 1 AND (IsFirstHalf = 1 OR IsFirstHalf = 0) AND LSD.EmployeeId IS NOT NULL AND LSD.IsHalfDay IS NOT NULL AND LeaveTypeId = 2 THEN 1
										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NOT NULL AND LeaveTypeId = 2 THEN 0.5
										WHEN LD.IsHalfDay IS NULL AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') AND HolidayId IS NULL AND IsWorkingDay IS NULL AND LSD.EmployeeId IS NULL AND LeaveTypeId = 2 THEN 0
 										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 1 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND LD.EmployeeId IS NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 0.5
										WHEN LD.IsHalfDay = 1 AND IsFirstHalf = 0 AND PH.InTime IS NOT NULL AND ISNULL(TotalMinutesPerDay,0) <> 0 AND TotalMinutesPerDay >= 480 AND TotalMinutesPerDay >= 240 THEN 1
										WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 240 THEN 0
										WHEN LSD.LeaveTypeId = 2 AND TakenCompOff IS NOT NULL THEN 1
										WHEN LD.EmployeeId IS NOT NULL AND LD.LeaveStatusId IN (2, 3) THEN 1
										WHEN HolidayId IS NOT NULL AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
										WHEN IsWorkingDay = 0 AND (PH.InTime IS NULL OR PH.InTime = '') THEN 1
										WHEN PD.EmployeeId IS NULL AND PH.InTime IS NOT NULL AND TotalMinutesPerDay IS NOT NULL AND TotalMinutesPerDay >= 480 THEN 1 
										WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) > 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 1
										WHEN PH.PunchDate <> CONVERT(DATE, GETDATE()) AND (TotalMinutesPerDay + NoOfHours) < 480 AND (TotalMinutesPerDay + NoOfHours) IS NOT NULL THEN 0.5
										WHEN PH.InTime IS NOT NULL AND TotalMinutesPerDay < 480 AND TotalMinutesPerDay > 240 THEN 0.5
									ELSE 0
								END AS TotalWorkingDays  
								,CASE WHEN LD.EmployeeId IS NULL AND PD.EmployeeId IS NULL AND Counts IS NOT NULL THEN Counts END AS LateCheckIn
						FROM	(	SELECT	EmployeeId, FirstName, LastName, CompanyId, EmployeeCompanyId
											,BranchId, DepartmentId
									FROM	[dbo].[EmployeeDetails] 
								) AS ED
						LEFT JOIN	[dbo].[BranchDetails] BD
							ON	ED.BranchId = BD.BranchId
						LEFT JOIN	[dbo].[DepartmentDetails] DD
							ON	ED.DepartmentId = DD.DepartmentId
						CROSS JOIN #Attendance AT
						LEFT JOIN (
									SELECT	CompanyId, IsWorkingDay, [Day] 
									FROM	[dbo].[CompanyWorkingDayDetails]
									WHERE	IsWorkingDay = 0
									AND		CompanyId = @CompanyId
									) AS CWDD
							ON	CWDD.CompanyId = ED.CompanyId
							AND DATENAME(DW,AT.PunchDate) = CWDD.[Day]
						LEFT JOIN [dbo].[HolidayDetails] HD
							ON	AT.PunchDate = HD.HolidayDate
						LEFT JOIN (	
									SELECT	ESMD.EmployeeId, StartTime, EndTime, StartDate, EndDate
									FROM	[dbo].[EmployeeShiftMappingDetails] ESMD
									JOIN	[dbo].[EmployeeDetails] ED
										ON	ESMD.EmployeeId = ED.EmployeeId
									LEFT JOIN [dbo].[ShiftDetails] SD
										ON	SD.ShiftId = ESMD.ShiftId  
									WHERE	(StartDate BETWEEN @FromDate AND @ToDate
										OR	EndDate BETWEEN @FromDate AND @ToDate)
									) AS ESMD
							ON	ED.EmployeeId = ESMD.EmployeeId 
							AND AT.PunchDate BETWEEN StartDate AND EndDate
						LEFT JOIN	(	
									SELECT	EmployeeId, PunchDate, MIN(InTime) AS InTime, DATENAME(DW,PunchDate) AS [Day]
											,MAX(OutTime) AS OutTime
											,SUM(DATEDIFF(MINUTE, InTime, OutTime)) AS TotalMinutesPerDay
											,CASE WHEN MAX(OutTime) = CONVERT(TIME,GETDATE()) THEN NULL ELSE MAX(OutTime) END AS OutTime_NULL
									FROM	(
												SELECT	ED.EmployeeId
														,PunchDate
														,CONVERT(TIME,PunchTime) AS InTime
														,[Status]
														,CONVERT(TIME,CASE WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																AND CONVERT(DATE,PunchDate) = CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ',LEFT(CONVERT(TIME,GETDATE()),12)))
															WHEN LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime)) IS NULL 
																AND CONVERT(DATE,PunchDate) <> CONVERT(DATE,GETDATE()) THEN CONVERT(DATETIME,CONCAT(CONVERT(DATE,PunchDate), ' ','18:30:000'))
															ELSE LEAD(CONVERT(TIME,PunchTime)) OVER(PARTITION BY PunchDate, ALD.EmployeeId ORDER BY CONVERT(TIME,PunchTime))
														END) AS OutTime
												FROM	[dbo].[EmployeeDetails] ED	
												JOIN	[dbo].[AttendanceLogDetails] ALD	
													ON	ED.EmployeeId = ALD.EmployeeId  
												WHERE	PunchDate BETWEEN @FromDate AND @ToDate
											) AS ALD
									WHERE	[Status] = 1
									GROUP BY EmployeeId, PunchDate, DATENAME(DW,PunchDate)
								) PH
							ON	ED.EmployeeId = PH.EmployeeId
							AND AT.PunchDate = PH.PunchDate
						LEFT JOIN	(
										SELECT	EmployeeId, FromDate, ToDate, NoOfDays AS TotalTakenLeave
												,IsHalfDay, IsFirstHalf, LeaveStatusId
										FROM	[dbo].[LeaveDetails]
										WHERE	LeaveStatusId = 3
											AND	LeaveTypeId <> 2 
											AND	(FromDate BETWEEN @FromDate AND @ToDate
											OR	ToDate BETWEEN @FromDate AND @ToDate)
									) AS LD
							ON	ED.EmployeeId = LD.EmployeeId
							AND AT.PunchDate BETWEEN LD.FromDate AND LD.ToDate
						LEFT JOIN	(
										SELECT	EmployeeId, PermissionDate
												,DATEDIFF(MINUTE,StartTime,EndTime) AS NoOfHours
										FROM	[dbo].[PermissionDetails]
										WHERE	PermissionStatusId = 3 
										AND		PermissionDate BETWEEN @FromDate AND @ToDate
									) AS PD
							ON	ED.EmployeeId = PD.EmployeeId
							AND	AT.PunchDate = PD.PermissionDate
						LEFT JOIN	(
										SELECT	EmployeeId, FromDate AS [Date], LeaveTypeId, IsHalfDay
												,NoOfDays AS TakenCompOff
										FROM	[dbo].[LeaveDetails]
										WHERE	LeaveStatusId = 3 AND LeaveTypeId = 2 
										AND		FromDate BETWEEN @FromDate AND @ToDate
									) AS LSD
							ON	ED.EmployeeId = LSD.EmployeeId
							AND AT.PunchDate = LSD.[Date]
						LEFT JOIN	(	
										SELECT	EmployeeId
												,PunchDate
												,Counts
										FROM	(
												SELECT	ALD.EmployeeId
														,PunchDate
														,CASE WHEN LEFT(StartTime,5) < LEFT(InTime,5) THEN COUNT(ALD.EmployeeId) ELSE 0 END AS Counts
												FROM	[dbo].[EmployeeShiftMappingDetails] ESMD
												JOIN	[dbo].[EmployeeDetails] ED
													ON	ESMD.EmployeeId = ED.EmployeeId
												LEFT JOIN [dbo].[ShiftDetails] SD
													ON	SD.ShiftId = ESMD.ShiftId  
												LEFT JOIN	(	SELECT	EmployeeId
																		,PunchDate
																		,MIN(CONVERT(TIME, PunchTime)) AS InTime 
																FROM	[dbo].[AttendanceLogDetails] 
																GROUP BY EmployeeId, PunchDate
															) AS ALD
													ON	ESMD.EmployeeId = ALD.EmployeeId  
													AND	ALD.PunchDate BETWEEN StartDate AND EndDate 
												GROUP BY ALD.EmployeeId, PunchDate, StartTime, InTime
												) AS A
										WHERE	Counts = 1   
										AND		PunchDate BETWEEN @FromDate AND @ToDate
									) AS  A
							ON	A.EmployeeId = ED.EmployeeId
							AND AT.PunchDate = A.PunchDate
					) AS S
			GROUP BY EmployeeId, EmployeeName, EffectiveWorkDays, Branch, Department;
			
			SELECT	* 
			FROM	#ResultSet_1;
		END 
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*=================================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXECUTE	[dbo].[USP_Rpt_AttendanceLogDetails] @LoginUserId		= 1
												 ,@FromDate			= NULL -- '2025-01-01'
												 ,@ToDate			= NULL -- '2025-01-31'
												 ,@ReportCategory	= 'Summarize'
												 ,@ReportValue		=  0
												 ,@Status			= @S_Status		OUT
												 ,@Message			= @M_Message	OUT; 

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT  *
	FROM	[dbo].[AttendanceLogDetails];
	SELECT  *
	FROM	[dbo].[AdvanceDetails];

===================================================================================================================================================*/
	
	
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_ClaimDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_ClaimDetails]
 Description		:	Procedure used to retrieve the ClaimDetails (When click on ClaimCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	30-08-2023
 Version			:	2.0 
 Comment			:	1. Get the Claim ReportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_ClaimDetails]
(
	@LoginUserId		INT
	,@FromDate			DATE
	,@ToDate			DATE
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Claim Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation 
					,ClaimTypeName AS ClaimType
					,CONCAT(N'₹ ',SUM(ISNULL(ClaimAmount,0))) AS TotalAmount
			FROM	[dbo].[ClaimDetails] CD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	CD.RequestedBy = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId
			LEFT JOIN	[dbo].[ClaimTypeDetails] CTD
				ON	CD.ClaimTypeId = CTD.ClaimTypeId
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName
					 ,ClaimTypeName
 		END 
		ELSE 
		BEGIN
			SET	@DSqlQuery = '	SELECT	BranchName	AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation 
										,ClaimTypeName AS ClaimType
										,CONVERT(NVARCHAR(50),ClaimDate,106) AS [Date]
										,CONCAT(NCHAR(8377),'' '',ClaimAmount) AS Amount 
										,CONCAT(NCHAR(8377),'' '',ISNULL(ApprovedAmount,0)) AS  ApprovedAmount
										,LeaveStatusName AS [Status] 
										,CASE WHEN CD.ClaimStatusId IN(3,4,5,6,7) THEN ISNULL(CAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN CD.ClaimStatusId IN(3,4,5,6,7) THEN CONCAT(CAD.FirstName,'' '',CAD.LastName)
												ELSE '' ''
										END AS ApprovedBy 
								FROM	[dbo].[ClaimDetails] CD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	CD.RequestedBy = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId
								JOIN	[dbo].[ClaimTypeDetails] CTD
									ON	CD.ClaimTypeId = CTD.ClaimTypeId
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	CD.ClaimStatusId = LSD.LeaveStatusId
								LEFT JOIN (	SELECT	ClaimId, EmployeeImage, FirstName, LastName
											FROM	[dbo].[ClaimDetails] CD
											JOIN	[dbo].[Employeedetails] ED
												ON	CD.ApprovedBy = ED.EmployeeId 
											WHERE	CD.CompanyId = @CompanyId 
											) AS CAD
									ON	CD.ClaimId = CAD.ClaimId '

		
				IF @ReportCategory = 'Branch'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Claim Report' AS ReportName
					FROM	[dbo].[BranchDetails]
					WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,ClaimDate);'
				END 
				ELSE IF @ReportCategory =  'Department'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Claim Report' AS ReportName
					FROM	[dbo].[DepartmentDetails]
					WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,ClaimDate);'
				END
				ELSE IF @ReportCategory =  'ClaimType'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE ClaimTypeName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Claim Report' AS ReportName
					FROM	[dbo].[ClaimTypeDetails]
					WHERE	ClaimTypeId = CASE WHEN @Reportvalue = 0 THEN ClaimTypeId ELSE @ReportValue END;
			
					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	CD.ClaimTypeId = CASE WHEN @ReportValue = 0 THEN CD.ClaimTypeId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,ClaimDate);'
				END
				ELSE IF @ReportCategory = 'Status'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Claim Report' AS ReportName
					FROM	[dbo].[LeaveStatusDetails]
					WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	CD.ClaimStatusId = CASE WHEN @ReportValue = 0 THEN CD.ClaimStatusId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ClaimDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,ClaimDate);'
				END
		
			PRINT @DSqlQuery;
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
												,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
		END
		SELECT	@Status = 1 
				,@Message = NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_ClaimDetails]	@LoginUserId		= 1
											,@FromDate			= '2024-01-01'
											,@ToDate			= '2025-02-28'
											,@ReportCategory	= 'Status'
											,@ReportValue		= 3
											,@Status			= @Status	OUT
											,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM ClaimDetails

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_CompensatoryOffDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_CompensatoryOffDetails]
 Description		:	Procedure used to retrieve the CompensatoryOffDetails (When click on CompensatoryOffCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	30-08-2023
 Version			:	2.0 
 Comment			:	1. Get the CompensatoryOff ReportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
							2.1 Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_CompensatoryOffDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'CompensatoryOff Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation 
					,SUM(ISNULL(COD.NoOfDays,0)) AS ApprovedCompOff
					,SUM(ISNULL(NoOfDays,0)) AS UsedCompOff
			FROM	[dbo].[CompensatoryOffDetails] COD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	COD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId 
			LEFT JOIN	(	SELECT	EmployeeId 
							FROM	LeaveDetails 
							WHERE	LeaveTypeId = 2 
							AND		LeaveStatusId = 3
						) LD
				ON	COD.EmployeeId = LD.EmployeeId
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName
		END 
		ELSE 
		BEGIN 
			SET	@DSqlQuery = '	SELECT	BranchName	AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation  
										,CONVERT(NVARCHAR(50),CompensatoryOffDate,106) AS [Date]
										,CONCAT(COD.NoOfDays,'' Day'') AS ApprovedCompOff
										,CONCAT(ISNULL(LD.NoOfDays,0), '' Day'') AS UsedCompOff
										,LeaveStatusName AS [Status]
										,CASE WHEN COD.CompensatoryOffStatusId IN(3,4,5,6,7) THEN ISNULL(CAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN COD.CompensatoryOffStatusId IN(3,4,5,6,7) THEN CONCAT(CAD.FirstName,'' '',CAD.LastName)
												ELSE '' ''
										END AS ApprovedBy 
								FROM	[dbo].[CompensatoryOffDetails] COD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	COD.EmployeeId = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId 
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	COD.CompensatoryOffStatusId = LSD.LeaveStatusId
								LEFT JOIN (	SELECT	CompensatoryOffId, EmployeeImage, FirstName, LastName
											FROM	[dbo].[CompensatoryOffDetails] COD
											JOIN	[dbo].[Employeedetails] ED
												ON	COD.Updatedby = ED.EmployeeId 
											WHERE	COD.CompanyId = @CompanyId
											) AS CAD
									ON	COD.CompensatoryOffId = CAD.CompensatoryOffId 
								LEFT JOIN	(	SELECT	EmployeeId, FromDate, ToDate, NoOfDays
												FROM	LeaveDetails 
												WHERE	LeaveTypeId = 2 
												AND		LeaveStatusId = 3
											) LD 
									ON	COD.EmployeeId = LD.EmployeeId '
		
			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'CompensatoryOff Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,CompensatoryOffDate);'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'CompensatoryOff Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,CompensatoryOffDate);'
			END
			ELSE IF @ReportCategory = 'Status'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'CompensatoryOff Report' AS Reportname
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	COD.CompensatoryOffStatusId = CASE WHEN @ReportValue = 0 THEN COD.CompensatoryOffStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,CompensatoryOffDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,CompensatoryOffDate);'
			END
		
			PRINT @DSqlQuery
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
												,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
		END 
		SELECT	@Status		= 1 
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_CompensatoryOffDetails]	@LoginUserId		= 1
													,@FromDate			= NULL -- '2025-01-01'
													,@ToDate			= NULL -- '2025-01-30'
													,@ReportCategory	= 'Status'
													,@ReportValue		= 4
													,@Status			= @Status	OUT
													,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM CompensatoryOffDetails

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_EmployeeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_EmployeeDetails]
 Description		:	Procedure used to retrive the EmployeeDetails(When click on EmployeeCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-08-2023
 Version			:	2.0
 Comment			:	1. Get the Employee ReportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_EmployeeDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN 
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX)
			,@SQL			NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ReportCategory = 'EmployeeCount'
		BEGIN
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Employee Report' AS ReportName;

			SELECT	BranchName
					,DepartmentName AS Department
					,COUNT(ED.EmployeeId) AS TotalEmployee  
					,ISNULL(NewlyJoined,0) AS NewlyJoined
					,ISNULL(ResignationEmployees,0) AS ResignationEmployees
					,(COUNT(ED.EmployeeId) - ISNULL(ResignationEmployees,0)) AS ActiveEmployee
					,ISNULL(InActiveEmployee,0) AS InActiveEmployee
			FROM	[dbo].[BranchDetails] BD 
			CROSS JOIN	[dbo].[DepartmentDetails] DD 
			LEFT JOIN [dbo].[EmployeeDetails] ED 
				ON	ED.BranchId = BD.BranchId
				AND	ED.DepartmentId = DD.DepartmentId
				AND ED.CompanyId = @CompanyId
			LEFT JOIN	(	SELECT	EmployeeId
									,COUNT(EmployeeId) AS NewlyJoined 
							FROM	[dbo].[EmployeeDetails] 
							WHERE	CompanyId = @CompanyId
							AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
							GROUP BY EmployeeId
						) AS ED1 
				ON	ED.EmployeeId = ED1.EmployeeId
			LEFT JOIN	(	SELECT	EmployeeId
									,COUNT(EmployeeId) AS ResignationEmployees  
							FROM	[dbo].[ResignationDetails] 
							WHERE	ResignationStatusId = 3
							AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,ResignationDate) BETWEEN @FromDate AND @ToDate))
							GROUP BY EmployeeId
						) AS RD
				ON	RD.EmployeeId = ED.EmployeeId
			LEFT JOIN	(	SELECT	EmployeeId
									,COUNT(EmployeeId) AS InActiveEmployee  
							FROM	[dbo].[EmployeeDetails]
							WHERE	IsActive = 0
							GROUP BY EmployeeId
						) AS ED2 
				ON	ED.EmployeeId = ED2.EmployeeId
			GROUP BY BranchName, DepartmentName, NewlyJoined, ResignationEmployees, InActiveEmployee;
		END 
		ELSE 
		BEGIN 
			SET	@DSqlQuery = '	SELECT	DISTINCT ED.EmployeeId
										,BranchName AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(FirstName,'' '',LastName) AS EmpName
										,DesignationName AS Designation
										,ContactNo
										,OfficialEmail AS Email
										,CONVERT(NVARCHAR(50),DateOfJoining,106) AS DateOfJoining
										,GenderName AS Gender
										,CONVERT(NVARCHAR(50),DateOfBirth,106) AS DOB
										,AadharNo AS AadhaarNo
										,PANNo
										,PersonalEmail 
										,ISNULL(PersonName,'''') AS PrimaryContact
										,ISNULL(RelationName,'''') AS Relation
										,ISNULL(EFMD.ContactNumber,'''') AS ContactNo
										,CONCAT(Degree, '' - '', Course) AS Degree 
										,TotalExperience AS Experience
										,ISNULL(TotalAssets,0) AS TotalAssets
										,EmployeeBankName AS BankName
										,AccountTypeName AS AccountType
										,AccountName
										,AccountNumber AS AccountNo
										,IFSCCode
										,CTC
										,CONVERT(NUMERIC(11,2),(CTC / 12)) AS MonthlySalary
										,ISNULL(PFNumber,'''') AS PFNo
										,ISNULL(EmployeeESINumber,'''') AS ESINo
								FROM	[dbo].[EmployeeDetails] ED 
								LEFT JOIN	[dbo].[BranchDetails] BD 
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD 
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD 
									ON	ED.EmployeeId = EPD.EmployeeId
								LEFT JOIN	[dbo].[DesignationDetails] DSD 
									ON	ED.DesignationId = DSD.DesignationId
								LEFT JOIN	[dbo].[GenderDetails] GD 
									ON	EPD.GenderId = GD.GenderId
								LEFT JOIN	(	SELECT	EmployeeId
														,PersonName
														,RelationName
														,ContactNumber
												FROM	[dbo].[EmployeeFamilyMemberDetails] EFMD
												JOIN	[dbo].[RelationDetails] RD
													ON	RD.RelationId = EFMD.RelationId
												WHERE	IsPrimaryContact = 1
											) AS EFMD 
									ON	ED.EmployeeId = EFMD.EmployeeId
								LEFT JOIN	(
												SELECT	EmployeeId, PeriodTo, Degree, Course
												FROM	(
															SELECT	ED.EmployeeId,
																	CONVERT(DATE, EED.PeriodTo) AS PeriodTo,
																	EED.Degree,
																	EED.Course,
																	ROW_NUMBER() OVER (PARTITION BY ED.EmployeeId ORDER BY EED.PeriodTo DESC) AS RN
															FROM	EmployeeDetails ED
															LEFT JOIN EmployeeEducationDetails EED  
																ON	ED.EmployeeId = EED.EmployeeId
														) AS RankedData
												WHERE	RN = 1
											) AS EED
									ON	ED.EmployeeId = EED.EmployeeId
								LEFT JOIN	(	SELECT	EmployeeId
														,CONCAT(SUM(DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE()))) - SUM(CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) 
														THEN 1 ELSE 0 END), CASE WHEN SUM(DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE()))) <= 1 
														THEN '' year '' ELSE '' years '' END,SUM(DATEDIFF(MONTH, DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())) 
														- CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) 
														THEN 1 ELSE 0 END, PeriodFrom), ISNULL(PeriodTo, GETDATE()))) % 12,'' months'') AS TotalExperience
												FROM	[dbo].[EmployeeExperienceDetails]
												GROUP BY EmployeeId
											) AS EEPD 
									ON	ED.EmployeeId = EEPD.EmployeeId
								LEFT JOIN	(	SELECT	EmployeeId, COUNT(EAMD.AssetId) AS TotalAssets
												FROM	[dbo].[AssetDetails] AD 
												LEFT JOIN [dbo].[EmployeeAssetMappingDetails] EAMD
													ON	AD.AssetId = EAMD.AssetId
												GROUP BY EmployeeId
											) AS AD
									ON	ED.EmployeeId = AD.EmployeeId
								LEFT JOIN	[dbo].[EmployeeBankDetails] EBD 
									ON	ED.EmployeeId = EBD.EmployeeId
								LEFT JOIN	[dbo].[EmployeeSalaryDetails] ESD 
									ON	ED.EmployeeId = ESD.EmployeeId
								LEFT JOIN	[dbo].[EmployeePFDetails] EPFD 
									ON	ED.EmployeeId = EPFD.EmployeeId
								LEFT JOIN	[dbo].[EmployeeESIDetails] EESID 
									ON	ED.EmployeeId = EESID.EmployeeId
								LEFT JOIN	[dbo].[AccountTypeDetails] ATD 
									ON	EBD.AccountTypeId = ATD.AccountTypeId '

			SET	@SQL =	'	SELECT	DISTINCT BranchName AS Branch
										,DepartmentName AS Department
										,CONCAT(EmployeeCompanyId,'' - '',FirstName,'' '',LastName) AS EmpName
										,DesignationName AS Designation
										,ContactNo
										,OfficialEmail AS Email
										,CONVERT(NVARCHAR(50),DateOfJoining,106) AS DateOfJoining
										,AadharNo AS AadhaarNo
										,PANNo
										,CONCAT(Degree, '' - '', Course) AS Degree 
										,TotalExperience AS Experience
								FROM	[dbo].[EmployeeDetails] ED 
								LEFT JOIN	[dbo].[BranchDetails] BD 
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD 
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[EmployeePersonalDetails] EPD 
									ON	ED.EmployeeId = EPD.EmployeeId
								LEFT JOIN	[dbo].[DesignationDetails] DSD 
									ON	ED.DesignationId = DSD.DesignationId
								LEFT JOIN	(	SELECT	EmployeeId
														,CONCAT(SUM(DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE()))) - SUM(CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) 
														THEN 1 ELSE 0 END), CASE WHEN SUM(DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE()))) <= 1 
														THEN '' year '' ELSE '' years '' END,SUM(DATEDIFF(MONTH, DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())) 
														- CASE WHEN DATEADD(YEAR, DATEDIFF(YEAR, PeriodFrom, ISNULL(PeriodTo, GETDATE())), PeriodFrom) > ISNULL(PeriodTo, GETDATE()) 
														THEN 1 ELSE 0 END, PeriodFrom), ISNULL(PeriodTo, GETDATE()))) % 12,'' months'') AS TotalExperience
												FROM	[dbo].[EmployeeExperienceDetails]
												GROUP BY EmployeeId
											) AS EEPD 
									ON	ED.EmployeeId = EEPD.EmployeeId
								LEFT JOIN	(
												SELECT	EmployeeId, PeriodTo, Degree, Course
												FROM	(
															SELECT	ED.EmployeeId,
																	CONVERT(DATE, EED.PeriodTo) AS PeriodTo,
																	EED.Degree,
																	EED.Course,
																	ROW_NUMBER() OVER (PARTITION BY ED.EmployeeId ORDER BY EED.PeriodTo DESC) AS RN
															FROM	EmployeeDetails ED
															LEFT JOIN EmployeeEducationDetails EED  
																ON	ED.EmployeeId = EED.EmployeeId
														) AS RankedData
												WHERE	RN = 1
											) AS EED
									ON	ED.EmployeeId = EED.EmployeeId '

			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'

				SELECT	@SQL = @SQL + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName; '
			END 
			ELSE IF @ReportCategory = 'Gender'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE GenderName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[GenderDetails]
				WHERE	GenderId = CASE WHEN @Reportvalue = 0 THEN GenderId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	EPD.GenderId = CASE WHEN @ReportValue = 0 THEN EPD.GenderId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'

				SELECT	@SQL = @SQL + '	WHERE	EPD.GenderId = CASE WHEN @ReportValue = 0 THEN EPD.GenderId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName; '
			END
			ELSE IF @ReportCategory = 'MaritalStatus'
			BEGIN
				SELECT	DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE MaritalStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[MaritalStatusDetails]
				WHERE	MaritalStatusId = CASE WHEN @Reportvalue = 0 THEN MaritalStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	EPD.MaritalStatusId = CASE WHEN @ReportValue = 0 THEN EPD.MaritalStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'

				SELECT	@SQL = @SQL +  'WHERE	EPD.MaritalStatusId = CASE WHEN @ReportValue = 0 THEN EPD.MaritalStatusId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName;'
			END
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'
													
				SELECT @SQL = @SQL + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName; '
			END
			ELSE IF @ReportCategory = 'Designation'
			BEGIN 
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DesignationName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[DesignationDetails]
				WHERE	DesignationId = CASE WHEN @Reportvalue = 0 THEN DesignationId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DesignationId = CASE WHEN @ReportValue = 0 THEN ED.DesignationId ELSE @reportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'

				SELECT @SQL = @SQL + '	WHERE	ED.DesignationId = CASE WHEN @ReportValue = 0 THEN ED.DesignationId ELSE @reportValue END
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName;'
			END  
			ELSE IF @ReportCategory = 'ReportingTo'
			BEGIN
				SELECT	DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE CONCAT(RPD.FirstName,' ',RPD.LastName) END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[EmployeeDetails] ED
				LEFT JOIN [dbo].[EmployeeDetails] RPD
					ON	RPD.EmployeeId = ED.ReportingPersonId 
				WHERE	ED.ReportingPersonId = CASE WHEN @ReportValue = 0 THEN ED.ReportingPersonId ELSE @ReportValue END; 

				SELECT  @DSqlQuery = @DSqlQuery + '	WHERE	ED.ReportingPersonId = CASE WHEN @ReportValue = 0 THEN ED.ReportingPersonId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'
													
				SELECT  @SQL = @SQL + '	WHERE	ED.ReportingPersonId = CASE WHEN @ReportValue = 0 THEN ED.ReportingPersonId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName; '
			END
			ELSE IF @ReportCategory = 'UserGroup'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE UserGroupName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration 
						,'Employee Report' AS ReportName
				FROM	[dbo].[UserGroupDetails]
				WHERE	UserGroupId = CASE WHEN @Reportvalue = 0 THEN UserGroupId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.UserGroupId = CASE WHEN @ReportValue = 0 THEN ED.UserGroupId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'
													
				SELECT @SQL = @SQL + '	WHERE	ED.UserGroupId = CASE WHEN @ReportValue = 0 THEN ED.UserGroupId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName;'
			END
			ELSE IF @ReportCategory = 'EmployeeType'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE EmployeeType END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[EmployeeTypeDetails]
				WHERE	EmployeeTypeId = CASE WHEN @Reportvalue = 0 THEN EmployeeTypeId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.EmployeeTypeId = CASE WHEN @ReportValue = 0 THEN ED.EmployeeTypeId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'
													
				SELECT @SQL = @SQL + '	WHERE	ED.EmployeeTypeId = CASE WHEN @ReportValue = 0 THEN ED.EmployeeTypeId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName;'
			END
			ELSE IF @ReportCategory = 'EmployeeStatus'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE EmployeeStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Employee Report' AS ReportName
				FROM	[dbo].[EmployeeStatusDetails]
				WHERE	EmployeeStatusId = CASE WHEN @Reportvalue = 0 THEN EmployeeStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.EmployeeStatusId = CASE WHEN @ReportValue = 0 THEN ED.EmployeeStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
													ORDER BY ED.EmployeeId;'
													
				SELECT @SQL = @SQL + '	WHERE	ED.EmployeeStatusId = CASE WHEN @ReportValue = 0 THEN ED.EmployeeStatusId ELSE @ReportValue END 
										AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,DateOfJoining) BETWEEN @FromDate AND @ToDate))
										ORDER BY BranchName;'
			END

			PRINT @DSqlQuery;
			EXECUTE SP_EXECUTESQL @DSqlQuery, N' @CompanyId TINYINT, @ReportValue SQL_VARIANT, @FromDate DATETIME, @ToDate DATETIME ',
												 @CompanyId, @ReportValue, @FromDate, @ToDate;
			PRINT @SQL;
			EXECUTE SP_EXECUTESQL @SQL, N' @CompanyId TINYINT, @ReportValue SQL_VARIANT, @FromDate DATETIME, @ToDate DATETIME ',
										   @CompanyId, @ReportValue, @FromDate, @ToDate;
		END 
		SELECT	@Status		= 1
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
/*==================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)
	
	EXECUTE [dbo].[USP_Rpt_EmployeeDetails] @LoginUserId		= 1
											,@FromDate			= NULL -- '2022-09-01'
											,@ToDate			= NULL -- '2023-05-30'
											,@ReportCategory	= 'Branch'
											,@ReportValue		= 0
											,@Status			= @Status	OUT
											,@Message			= @Message	OUT

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM ReportcategoryDetails WHERE ReportName = 'Employee'
	 
===================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_EmployeeDetails_ByEmployeeId]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*======================================================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_Rpt_EmployeeDetails_ByEmployeeId]
 Description		:	Procedure used to retrive the EmployeeDetails (1.When click on EmployeeInfo in Side Navigation bar
																	   2.when click on edit option in Grid on Employee landing page).
 Input Parameter	:	@LoginUserId, @EmployeeId
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	10-02-2025
 Version			:	1.0 
 Comment			:	1. Get the EmloyeeDetails for the Given @EmployeeId.	
						2. Then return the output Parameter values as @Status = 1 and @Message = NULL.
===========================================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_EmployeeDetails_ByEmployeeId]
(	
	@LoginUserId			INT
	,@EmployeeId			INT
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		SELECT	ISNULL(ED.EmployeeImage,' ') AS EmployeeImage	
				,ED.FirstName
				,ED.LastName
				,ED.EmployeeCompanyId 
				,DD.DepartmentName
				,CONVERT(NVARCHAR(50),ED.DateOfJoining,105) AS DateOfJoining
				,ED.ContactNo 
				,ED.OfficialEmail  
				,ED.[Address]
				,ED.City
				,ED.Zipcode
				,ED.[State]
				,ED.Country
				,ISNULL(CONCAT(RPD.FirstName,' ',RPD.LastName),0)  AS ReportingPerson
				,BD.BranchName 
				,DE.DesignationName 
				,RPD.EmployeeImage  AS ReportingPrsnImg
				,EmployeeType
				,GradeTypeName
				,EmployeeStatusName 
				,UGD.UserGroupName  
		FROM	[DBO].[EmployeeDetails] ED
		LEFT JOIN	[DBO].[BranchDetails] BD
			ON	ED.BranchId = BD.BranchId
		LEFT JOIN	[DBO].[DepartmentDetails] DD
			ON	ED.DepartmentId = DD.DepartmentId
		LEFT JOIN	[DBO].[DesignationDetails] DE
			ON	ED.DesignationId = DE.DesignationId 
		LEFT JOIN	[DBO].[EmployeeDetails] RPD
			ON	RPD.EmployeeId = ED.ReportingPersonId
		JOIN	[DBO].[UserGroupDetails] UGD
			ON	ED.UserGroupId = UGD.UserGroupId 
		JOIN	[DBO].[EmployeeTypeDetails] ETD
			ON	ED.EmployeeTypeId = ETD.EmployeeTypeId 
		JOIN	[DBO].[GradeTypeDetails] GTD
			ON	ED.GradeTypeId = GTD.GradeTypeId 
		JOIN	[DBO].[EmployeeStatusDetails] ESD
			ON	ED.EmployeeStatusId = ESD.EmployeeStatusId 
		WHERE	ED.EmployeeId = @EmployeeId 
		AND		ED.CompanyId = @CompanyId;

		SELECT	GenderName
				,CONVERT(NVARCHAR(20),DateOfBirth, 106) AS DateOfBirth
				,ReligionName
				,MaritalStatusName
				,Nationality
				,PersonalEmail
				,AadharNo
				,PANNo
				,PassportNo 
				,CONVERT(NVARCHAR(20),PassportExpDate,106) AS PassportExpDate
		FROM	[DBO].[EmployeePersonalDetails] EPD 
		LEFT JOIN	[DBO].[GenderDetails] GD
			ON	EPD.GenderId = GD.GenderId
		LEFT JOIN	[DBO].[ReligionDetails] RD	
			ON	EPD.ReligionId = RD.ReligionId 
		LEFT JOIN	[DBO].[MaritalStatusDetails] MD
			ON	EPD.MaritalStatusId=MD.MaritalStatusId
		WHERE	EPD.EmployeeId = @EmployeeId
		AND		GD.CompanyId = @CompanyId;

		SELECT	EmployeeBankName
				,AccountTypeName
				,AccountName
				,AccountNumber
				,IFSCCode 
		FROM	[dbo].[EmployeeBankDetails] EBD 
		JOIN	[dbo].[AccountTypeDetails] ATD
			ON	EBD.AccountTypeId = ATD.AccountTypeId
		WHERE	EBD.EmployeeId = @EmployeeId
		AND		ATD.CompanyId = @CompanyId;

			SELECT	EducationId 
					,CONCAT(InstituteName,'.') AS InstituteName
					,Concat(Degree,' (',Course,')') AS DegreeCourse
					,CONCAT(YEAR(PeriodFrom),' - ', YEAR(PeriodTo)) EducationYear
			FROM	[dbo].[EmployeeEducationDetails] 
			WHERE	EmployeeId  = @EmployeeId
			ORDER BY PeriodTo DESC;

			WITH CTE 
			AS	(
					SELECT	EmployeeExperienceId
							,PeriodFrom
							,PeriodTo
							,DATEDIFF(YEAR, PeriodFrom, PeriodTo) AS YearDiff
							,DATEDIFF(MONTH, PeriodFrom, PeriodTo) - (DATEDIFF(YEAR, PeriodFrom, PeriodTo) * 12) AS MonthDiff
					FROM	[EmployeeExperienceDetails]
				)
			SELECT	EmployeeId
					,EED.EmployeeExperienceId 
					,CONCAT(Designation,' ', 'at',' ' ,CompanyName ) AS DesignationCompanyName
					,RIGHT(CONVERT(NVARCHAR(50),EED.PeriodFrom,113),8) AS PeriodFrom	
					,CASE WHEN IsPresent = 1 THEN CONCAT(CONCAT(CASE WHEN YearDiff = 1 THEN CAST(YearDiff AS VARCHAR(5)) + ' year '
																	ELSE CAST(YearDiff AS VARCHAR(5)) + ' years ' END,
						CASE	WHEN MonthDiff = 1 THEN CAST(MonthDiff AS VARCHAR(5)) + ' month'
										ELSE CAST(MonthDiff AS VARCHAR(5)) + ' months' END ), ' (Still Working)') 
						ELSE CONCAT(CASE	WHEN YearDiff = 1 THEN CAST(YearDiff AS VARCHAR(5)) + ' year '
											ELSE CAST(YearDiff AS VARCHAR(5)) + ' years '
										END,
									CASE	WHEN MonthDiff = 1 THEN CAST(MonthDiff AS VARCHAR(5)) + ' month'
											ELSE CAST(MonthDiff AS VARCHAR(5)) + ' months'
										END
									)
					END AS  PeriodTo 
			FROM	[dbo].[EmployeeExperienceDetails]  EED
			JOIN	CTE 
				ON	EED.EmployeeExperienceId = CTE.EmployeeExperienceId
			WHERE	EmployeeId = @EmployeeId
			ORDER BY PeriodTo DESC;
			 
			SELECT	PayTypeName 
					,PaymentTypeName
					,ESD.CTC	
					,CONVERT(NUMERIC(11,2),(ESD.CTC / 12)) AS MonthlySalary 
					,ESD.BasicPay		
					,ESD.HRA			
					,ESD.OtherAllowence	
					,EPFD.UANNumber				
					,EPFD.PFNumber				
					,EPFD.EmployeeContribution	
					,EPFD.EmployeerContribution	
					,EESID.IsESIApplicable		
					,EESID.EmployeeESINumber		
					,EESID.EmployeeESIContribution
			FROM	[DBO].[EmployeeSalaryDetails] ESD 
			LEFT JOIN	[DBO].[EmployeePFDetails] EPFD
				ON	ESD.EmployeeId = EPFD.EmployeeId
			LEFT JOIN	[DBO].[EmployeeESIDetails] EESID
				ON	ESD.EmployeeId = EESID.EmployeeId    
			JOIN	[DBO].[PayTypeDetails] PTD
				ON	ESD.PayTypeId = PTD.PayTypeId
			JOIN	[DBO].[PaymentTypeDetails] PMTD	
				ON	ESD.PaymentTypeId = PMTD.PaymentTypeId
			WHERE	ESD.EmployeeId = @EmployeeId 
			AND		PTD.CompanyId = @CompanyId; 

			SELECT	@Status		= 1
					,@Message	= NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*===============================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_Rpt_EmployeeDetails_ByEmployeeId]	@LoginUserId	= 1
														,@EmployeeId	= 3
														,@Status		= @S_Status	 OUT
														,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 

================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_LeaveDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
