/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_LeaveDetails]
 Description		:	Procedure used to retrieve the LeaveDetails (When click on LeaveCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	30-08-2023
 Version			:	2.0 
 Comment			:	1. Get the Leave ReportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_LeaveDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Leave Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation 
					,LeaveTypeName AS LeaveType 
					,SUM(ISNULL(NoOfDays,0)) AS NoOfDays
			FROM	[dbo].[LeaveDetails] LD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	LD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId
			LEFT JOIN	[dbo].[LeaveTypeDetails] LTD
				ON	LD.LeaveTypeId = LTD.LeaveTypeId
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName
					 ,LeaveTypeName;
		END 
		ELSE 
		BEGIN	
			SET	@DSqlQuery = '	SELECT	BranchName	AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation 
										,CONVERT(NVARCHAR(50),Fromdate,106) AS FromDate
										,CONVERT(NVARCHAR(50),Todate,106) AS ToDate 
										,LeaveTypeName AS LeaveType 
										,NoOfDays
										--,5 AS TotalCount
										,LeaveStatusName AS [Status]
										,CASE WHEN LD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(LAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN LD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(LAD.FirstName,'' '',LAD.LastName)
												ELSE '' ''
											END AS ApprovedBy 
								FROM	[dbo].[LeaveDetails] LD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	LD.EmployeeId = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId
								JOIN	[dbo].[LeaveTypeDetails] LTD
									ON	LD.LeaveTypeId = LTD.LeaveTypeId
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	LD.LeaveStatusId = LSD.LeaveStatusId
								LEFT JOIN (	SELECT	LeaveId, EmployeeImage, FirstName, LastName
											FROM	[dbo].[LeaveDetails] LD
											JOIN	[dbo].[Employeedetails] ED
												ON	LD.Updatedby = ED.EmployeeId 
											WHERE	LD.CompanyId = @CompanyId 
											) AS LAD
									ON	LAD.LeaveId = LD.LeaveId '
		
				IF @ReportCategory = 'Branch'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Leave Report' AS ReportName
					FROM	[dbo].[BranchDetails]
					WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,FromDate);'
				END 
				ELSE IF @ReportCategory =  'Department'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Leave Report' AS ReportName
					FROM	[dbo].[DepartmentDetails]
					WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,FromDate);'
				END
				ELSE IF @ReportCategory =  'LeaveType'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveTypeName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Leave Report' AS ReportName
					FROM	[dbo].[LeaveTypeDetails]
					WHERE	LeaveTypeId = CASE WHEN @Reportvalue = 0 THEN LeaveTypeId ELSE @ReportValue END;
			
					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	LD.LeaveTypeId = CASE WHEN @ReportValue  = 0 THEN LD.LeaveTypeId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,FromDate);'
				END
				ELSE IF @ReportCategory = 'Status'
				BEGIN
					SELECT  DISTINCT @ReportCategory AS ReportCategory
							,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
							,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
								ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
							END AS Duration
							,'Leave Report' AS Reportname
					FROM	[dbo].[LeaveStatusDetails]
					WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

					SELECT @DSqlQuery = @DSqlQuery + '	WHERE	LD.LeaveStatusId = CASE WHEN @ReportValue = 0 THEN LD.LeaveStatusId ELSE @ReportValue END 
														AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,FromDate) BETWEEN @FromDate AND @ToDate))
														ORDER BY CONVERT(DATE,FromDate);'
				END
		
			PRINT @DSqlQuery
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
												,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
		END 
		SELECT	@Status = 1 
				,@Message = NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_LeaveDetails]	@LoginUserId		= 1
											,@FromDate			= NULL --- '2025-01-01'
											,@ToDate			= NULL --- '2025-01-28'
											,@ReportCategory	= 'Summarize'
											,@ReportValue		= 0
											,@Status			= @Status	OUT
											,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM LeaveDetails

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_LoanDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_LoanDetails]
 Description		:	Procedure used to retrieve the LoanDetails (When click on Loan ReportCategory in report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-08-2023
 Version			:	1.0 
 Comment			:	1. Get the Loan ReportDetails for the given @FromDate, @ToDate, @ReportCategory, @ReportValue to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_Rpt_LoanDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN 
	SET NOCOUNT ON;

	DECLARE	@CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Loan Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation  
					,CONCAT(N'₹ ',SUM(ISNULL(LoanAmount,0))) AS LoanAmount
					,CONCAT(N'₹ ',SUM(ISNULL(LoanDueAmount,0))) AS ClosedDueAmount
					,CONCAT(N'₹ ',SUM(ISNULL(LoanDueAmount,0))) AS OpenedDueAmount 
			FROM	[dbo].[LoanDetails] LD
			LEFT JOIN [dbo].[LoanDueDetails] LDD
				ON	LDD.LoanId = LD.LoanId
			JOIN	[dbo].[EmployeeDetails] ED
				ON	LD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId 
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,LoanDueDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName, Isclosed;
 		END 
		ELSE 
		BEGIN 
			SET @DSqlQuery = '	SELECT	BranchName AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation 
										,CONVERT(NVARCHAR(50),LoanDate,106) AS [Date]
										,CONCAT(NCHAR(8377),'' '',ISNULL(LoanAmount,0)) AS LoanAmount
										,CONCAT(NCHAR(8377),'' '',ISNULL(DueAmount,0)) AS DueAmount
										,LeaveStatusName AS [Status]
										,CASE WHEN LD.LoanStatusId IN(3,4,5,6,7) THEN ISNULL(LAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN LD.LoanStatusId IN(3,4,5,6,7) THEN CONCAT(LAD.FirstName,'' '',LAD.LastName)
											ELSE '' ''
										END AS ApprovedBy 
								FROM	[dbo].[LoanDetails] LD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	LD.EmployeeId = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId  
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	LD.LoanStatusId = LSD.LeaveStatusId
								LEFT JOIN	(	SELECT	LoanId, EmployeeImage, FirstName, LastName
												FROM	[dbo].[LoanDetails] LD
												JOIN	[dbo].[Employeedetails] ED
													ON	LD.EmployeeId = ED.EmployeeId 
												WHERE	LD.CompanyId = @CompanyId 
											) AS LAD
									ON	LD.LoanId = LAD.LoanId '
		
			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Loan Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,LoanDate);'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Loan Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,LoanDate);'
			END 
			ELSE IF @ReportCategory = 'Status'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Loan Report' AS ReportName
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	LD.LoanStatusId = CASE WHEN @ReportValue = 0 THEN LD.LoanStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,LoanDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,LoanDate);'
			END
		
			PRINT @DSqlQuery;
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
												,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
	END 
		SELECT	@Status   = 1 
				,@Message = NULL;		
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==============================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_Rpt_LoanDetails]	@LoginUserId		= 1
										,@FromDate			=  '2024-03-01'
										,@ToDate			=  '2025-03-31'
										,@ReportCategory	= 'Summarize'
										,@ReportValue		= 0
										,@Status			= @S_Status		OUT 
										,@Message			= @M_Message	OUT;	
										
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[LoanDetails];
	SELECT * FROM ReportCategoryDetails
================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_OverallReportDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=====================================================================================================================================================
 ProcedureName		: [dbo].[USP_Rpt_OverallReportDetails]
 Description		: Procedure used to get the Report Details(When click on ReportName in Report screen)
 InputParameter		: @LoginUserId, @ReportName, @FromDate, @ToDate,@Month,@Year, @ReportCategory, @ReportValue
 Output Parameter	: @Status, @Message
 Author				: Dharani.M
 Version			: 1.0
 Comment			: 1. If the Given @ReportName = 'Employee', then call the [dbo].[USP_Rpt_EmployeeDetails] Report SP and 
						 Get the output for Employee Report with the columns of EmployeeId, EmployeeCompanyId, EmployeeImage,Employee,Email,ContactNo,
						 DateOfJoining, Designation,ReportingPersonName.

					  2. If the given @ReportName = 'Attendance', then call the [dbo].[USP_Rpt_AttendanceDetails] Report SP and 
						 Get the output for Attendance Report with the columns of AttendanceLogId, Date, PunchIn, PunchOut, Production,Break.

					  3. If the given @ReportName = 'Leave', then call the [dbo].[USP_Rpt_LeaveDetails] Report SP and 
						 Get the output for Leave report with the columns of LeaveId, EmployeeId, EmployeeImage, Employee, Designation,
						 LeaveType, From, To, NoOfDays, Reason, Status.

					  4. If the given @ReportName = 'Permission', then call the [dbo].[USP_Rpt_PermissionDetails] Report SP and 
						 Get the output for Permission Report with the column of PermissionId, Date, EmployeeId, EmployeeImage, Employee,
						 StartTime, EndTime, NoOfHours, Reason, Status.

					  5. If the given @ReportName = 'CompensatoryOff', then call the [dbo].[USP_Rpt_CompensatoryOffDetails] Report SP and 
						 Get the output for CompensatoryOff Report with the column of CompensatoryOffId, Date, EmployeeId, EmployeeImage,Employee
						 NoOfDays, Comments, Status. 

					  6. If the given @ReportName = 'Advance', then call the [dbo].[USP_Rpt_AdvanceDetails] Report SP and 
						 Get the output for Advance Report with the column of AdvanceId, Date, EmployeeId, EmployeeImage, Employee,AdvanceAmount
						 ,DueAmount, Status, Status_Colour, ApprovedPersonImage, ApprovedBy.

					  7. If the given @ReportName = 'Loan', then call the [dbo].[USP_Rpt_LoanDetails] Report SP and 
						 Get the output for Loan Report with the column of LoanId, Date, EmployeeId, EmployeeImage, Employee, LoanAmount,
						 NoOfDues, DueAmount, PendingDues, PendingAmount, Status, Status_Colour, ApprovedPersonImage, ApprovedBy .

					  8. If the given @ReportName = 'PaySlip', then call the [dbo].[USP_Rpt_PaySlipDetails] Report SP and 
						 Get the output for PaySlip Report with the column of [Month],EmployeeCompanyId, EmployeeName, DesignationName,
						 BasicPay, HRA, OtherAllowance,PF,ESI,IncomeTax,TotalEarning,TotalDeduction, NetPay, PaySlipName.

					  9. If the given @ReportName = 'Claim', then call the [dbo].[USP_Rpt_ClaimDetails] Report SP and 
						 Get the output for Claim Report with the column of ClaimDate,EmployeeEmployeeId, EmployeeName, ClaimType,
						 ClaimAmount, ApprovedPersonAmount, ApprovedPersonImage,ApprovedBy,ClaimStatus.

					  10. Then Return the output parameter values @Status = 1 & @Message = NULL.
=========================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_Rpt_OverallReportDetails]
(
	@LoginUserId		INT
	,@ReportName		NVARCHAR(100)
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@Month				TINYINT
	,@Year				INT
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		INT
	,@IsInsert			BIT
	,@Status			NVARCHAR(500)	OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId TINYINT;

	-- Logic To Get SchoolId Of Given LoginUserId to Use in Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	---- Logic to set @Fromdate and @Todate if they are NULL (For Initial Screen Load)
	--IF @FromDate IS NULL 
	--BEGIN
	--	SELECT  @FromDate = DATEADD(DD, 1, EOMONTH(DATEADD(MM, -1,GETDATE()))) ;
	--END
	--IF @ToDate IS NULL 
	--BEGIN
	--	SELECT @ToDate = GETDATE();
	--END

	BEGIN TRY 
		-- Resultset for CompanyHeader
		SELECT	 CompanyId			
				,CompanyName 
				,IsNULL(CompanyLogo,'') AS CompanyLogoName
				,CONCAT(CompanyAddress,',',CompanyCity) as Address
				,CONCAT(CompanyState,', ',CompanyCountry,', ',CompanyZipcode) as Location
				,CONCAT(CompanyContactNumber,', ',CompanyEmail) as Contact
				,CompanyWebsite AS Website
				,GSTNumber 
		FROM	[dbo].[CompanyDetails] 
		WHERE	CompanyId = @CompanyId;	

		IF (@ReportName = 'Employee')
		BEGIN 
			EXECUTE	[dbo].[USP_Rpt_EmployeeDetails]	@LoginUserId		= @LoginUserId	
													,@FromDate			= @FromDate		
													,@ToDate			= @ToDate		
													,@ReportCategory	= @ReportCategory
													,@ReportValue		= @ReportValue	
													,@Status			= @Status		OUT
													,@Message			= @Message		OUT;
		END
		ELSE
		IF  (@ReportName = 'Attendance')
		BEGIN
			EXECUTE	[dbo].[USP_Rpt_AttendanceLogDetails] @LoginUserId		= @LoginUserId	
														,@FromDate			= @FromDate		
														,@ToDate			= @ToDate		
														,@ReportCategory	= @ReportCategory
														,@ReportValue		= @ReportValue	
														,@Status			= @Status		OUT
														,@Message			= @Message		OUT;
	;
		END 
		ELSE IF  (@ReportName = 'Leave')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_LeaveDetails]	@LoginUserId		= @LoginUserId	
													,@FromDate			= @FromDate		
													,@ToDate			= @ToDate		
													,@ReportCategory	= @ReportCategory
													,@ReportValue		= @ReportValue	
													,@Status			= @Status		OUT
													,@Message			= @Message		OUT;
		END
		ELSE IF (@ReportName = 'Permission')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_PermissionDetails]	@LoginUserId		= @LoginUserId	
														,@FromDate			= @FromDate		
														,@ToDate			= @ToDate		
														,@ReportCategory	= @ReportCategory
														,@ReportValue		= @ReportValue	
														,@Status			= @Status		OUT
														,@Message			= @Message		OUT;
		END
		ELSE IF  (@ReportName = 'CompensatoryOff')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_CompensatoryOffDetails]	@LoginUserId		= @LoginUserId	
															,@FromDate			= @FromDate		
															,@ToDate			= @ToDate		
															,@ReportCategory	= @ReportCategory
															,@ReportValue		= @ReportValue	
															,@Status			= @Status		OUT
															,@Message			= @Message		OUT;

		END 
		ELSE IF  (@ReportName = 'Advance')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_AdvanceDetails] @LoginUserId			= @LoginUserId	
												   ,@FromDate			= @FromDate		
												   ,@ToDate				= @ToDate		
												   ,@ReportCategory		= @ReportCategory
												   ,@ReportValue		= @ReportValue	
												   ,@Status				= @Status		OUT
												   ,@Message			= @Message		OUT;
		END 
		ELSE IF (@ReportName = 'Loan')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_LoanDetails]	@LoginUserId		= @LoginUserId	
												,@FromDate			= @FromDate		
												,@ToDate			= @ToDate		
												,@ReportCategory	= @ReportCategory
												,@ReportValue		= @ReportValue	
												,@Status			= @Status			OUT
												,@Message			= @Message			OUT;
		END	
		ELSE IF  (@ReportName = 'PaySlip')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_PaySlipDetails]	@LoginUserId		= @LoginUserId	
													,@FromDate			= @FromDate		
													,@ToDate			= @ToDate
													,@Month				= @Month
													,@Year				= @Year
													,@Reportcategory	= @ReportCategory
													,@ReportValue		= @ReportValue	
													,@Status			= @Status		OUT
													,@Message			= @Message		OUT;
		END
		ELSE IF  (@ReportName = 'Claim')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_ClaimDetails]	@LoginUserId		= @LoginUserId	
													,@FromDate			= @FromDate		
													,@ToDate			= @ToDate		
													,@ReportCategory	= @ReportCategory
													,@ReportValue		= @ReportValue	
													,@Status			= @Status		OUT
													,@Message			= @Message		OUT;
		END
		ELSE IF  (@ReportName = 'OverTime')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_OverTimeDetails]	@LoginUserId		= @LoginUserId	
													,@FromDate			= @FromDate		
													,@ToDate			= @ToDate		
													,@ReportCategory	= @ReportCategory
													,@ReportValue		= @ReportValue	
													,@Status			= @Status		OUT
													,@Message			= @Message		OUT;
		END
		ELSE IF  (@ReportName = 'Regularization')
		BEGIN
			EXECUTE [dbo].[USP_Rpt_RegularizationDetails]	@LoginUserId		= @LoginUserId	
															,@FromDate			= @FromDate		
															,@ToDate			= @ToDate		
															,@ReportCategory	= @ReportCategory
															,@ReportValue		= @ReportValue	
															,@Status			= @Status		OUT
															,@Message			= @Message		OUT;
		END
		ELSE 
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Invalid Report Name'
		END
		SELECT	@Status = 1
				,@Message = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@Status	BIT
			,@Message	NVARCHAR(500)

	EXEC  [dbo].[USP_Rpt_OverallReportDetails]	@LoginUserId		= 1
												,@ReportName		= 'Employee'
												,@FromDate			= NULL--  '2024-04-01'
												,@ToDate			= NULL--  '2024-04-30'
												,@Month				= NULL
												,@Year				= NULL
												,@ReportCategory	= 'Department'
												,@ReportValue		= 1
												,@IsInsert			= 0
												,@Status			= @Status		OUT
												,@Message			= @Message		OUT;
	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM AdvanceDetails

	SELECT * FROM ReportcategoryDetails

	SELECT * FROM PermissionDetails

	SELECT * FROM CompensatoryOffDetails
	
	SELECT * FROM EmployeeDetails
	SELECT * FROM  LoanDetails

==================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_OverTimeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_OverTimeDetails]
 Description		:	Procedure used to retrive the OverTimeDetails (When click on OverTimeCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Dharani.M
 Created on			:	22-03-2024
 Version			:	1.0 
 Comment			:	1. If The Given @ReportCategory ='Employee' and @ReportValue = 0 then get all the records Else given @ReportValue <> 0 then 
								get the given reportvalue record have the columns of OverTimeId,EmpId,Date,StartTime,EndTime,TotalHours to show in Grid.
							1.1 Then Return the output Parameter values as @Status = 1 and @Message = NULL.
========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_OverTimeDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME 
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT		
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@UserGroupId	TINYINT
			,@DSqlQuery		NVARCHAR(MAX);
		
	SELECT	@CompanyId = CompanyId 
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		--Resulset for Report Grid in Advance Category.
		SELECT @DSqlQuery = 'SELECT	OverTimeId
									,CONCAT(FirstName,'' '',LastName) AS EmpName
									,CONVERT(NVARCHAR(50),[Date],105) AS [Date]
									,StartTime
									,EndTime
									,TotalHours
							FROM	[dbo].[OverTimeDetails] OTD
							LEFT JOIN	[dbo].[EmployeeDetails] ED
								ON	OTD.EmployeeId = ED.EmployeeId
							WHERE	(OTD.EmployeeId = CASE WHEN @UserGroupId = 1 THEN OTD.EmployeeId ELSE @LoginUserId END) 
							AND		(CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate) 
							AND		(OTD.CompanyId = @CompanyId) '

			IF @ReportCategory = 'Employee'
			BEGIN
				-- Resultset for ReportName, InputDateRange and Inputvalue
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE CONCAT(FirstName,' ',LastName) END AS ReportValue
						,CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105)) AS Duration, 
						'Employee Report' AS Reportname
				FROM	[dbo].[EmployeeDetails]
				WHERE	EmployeeId = CASE WHEN @Reportvalue = 0 THEN EmployeeId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + ' AND ED.EmployeeId = CASE WHEN  @Reportvalue = 0  THEN ED.EmployeeId ELSE @ReportValue END
														ORDER BY ED.EmployeeId DESC;'
			END
			--PRINT @DSqlQuery
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT, @UserGroupId TINYINT, @LoginUserId INT',
												@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId, @UserGroupId = @UserGroupId, @LoginUserId = @LoginUserId;
		SELECT	@Status = 1 
				,@Message = NULL;

	END TRY 
	BEGIN CATCH 
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_OverTimeDetails] @LoginUserId		= 1
										   ,@FromDate			= '2024-03-01'
										   ,@ToDate				= '2024-03-30'
										   ,@ReportCategory		= 'Employee'
										   ,@ReportValue		= 0
										   ,@Status				= @Status	OUT
										   ,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[AdvanceDetails];

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_PayslipDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*========================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_PayslipDetails]
 Description		:	Procedure used to retrive the PayslipReportDetails (When click on payslip ReportCategory in Report Screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @reportCategory, @ReportValue
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-08-2023
 Version			:	1.0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 Comment			:	1. Get the Payslip ReportDetails for the Given @EmployeeId.
						2. Then return the outpu parameter values @Status = 1 & @Message = NULL.
============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_PayslipDetails]
(
	@LoginUserId		INT
	,@FromDate			DATE
	,@ToDate			DATE 
	,@Reportcategory	NVARCHAR(100)	
	,@ReportValue		SQL_VARIANT	
	,@Status			BIT				OUT
	,@Message			NVARCHAR(200)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;
	 
	DECLARE	@CompanyId				TINYINT
			,@EarningsCount			INT
			,@DeductionsCount		INT
			,@SQL					NVARCHAR(MAX)
			,@EarningsColumns		NVARCHAR(MAX)
			,@DeductionsColumns		NVARCHAR(MAX)
			,@EarningComponents		NVARCHAR(MAX)
			,@DeductionComponents	NVARCHAR(MAX)
			,@ComponentColumns		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId  
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Payslip Report' AS ReportName;

			SELECT BranchName AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation 
					,SUM(ISNULL(TotalEarnings, 0)) AS GrossPay
					,SUM(ISNULL(TotalDeduction, 0)) AS Deduction
					,SUM(ISNULL(NetPay, 0)) AS NetPay
			FROM	PayslipDetails_1 PD
			JOIN	[dbo].[EmployeeDetails] ED 
				ON	PD.EmployeeId = ED.EmployeeId
			LEFT JOIN [dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN [dbo].[DepartmentDetails] DD 
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN [dbo].[DesignationDetails] DSD 
				ON	ED.DesignationId = DSD.DesignationId 
			WHERE	((@FromDate IS NULL AND @FromDate IS NULL) OR ([Month] BETWEEN MONTH(@FromDate) AND MONTH(@ToDate)))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName
			ORDER BY EmployeeCompanyId;
		END 
		ELSE 
		BEGIN 
			DROP TABLE IF EXISTS #EarningColumns, #DeductionColumns;
			WITH EarningColumnDetails
			AS	(
					SELECT	COLUMN_NAME 
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Earning_%'
				),
			EarningComponentDetails 
			AS	(
					SELECT ComponentName
							,SalaryComponentTypeId 
						   ,ROW_NUMBER() OVER (PARTITION BY SalaryComponentTypeId ORDER BY SalaryComponentsId) AS ColumnNumber
						   ,'Earnings' AS ComponentType
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1
					AND		SalaryComponentTypeId = 1
				)
			SELECT	ECD.COLUMN_NAME AS PayslipColumn
					,ECCD.ComponentName AS SalaryComponent
					,ECCD.ComponentType
			INTO	#EarningColumns
			FROM	EarningColumnDetails ECD
			JOIN	EarningComponentDetails ECCD 
				ON	ECD.ColumnNumber = ECCD.ColumnNumber
				AND ECCD.ComponentType = 'Earnings';

			WITH DeductionColumnDetails 
			AS	(
					SELECT	COLUMN_NAME
							,CAST(RIGHT(COLUMN_NAME, CHARINDEX('_', REVERSE(COLUMN_NAME)) - 1) AS INT) AS ColumnNumber
					FROM	INFORMATION_SCHEMA.COLUMNS
					WHERE	TABLE_NAME = 'PayslipDetails_1' 
					AND		COLUMN_NAME LIKE 'Com_Deduction_%'
				),
			DeductionComponentDetails
			AS	(
					SELECT	ComponentName
							,SalaryComponentTypeId 
						   ,ROW_NUMBER() OVER (PARTITION BY SalaryComponentTypeId ORDER BY SalaryComponentsId) AS ColumnNumber
						   ,'Deductions' AS ComponentType
					FROM	[dbo].[SalaryComponentsDetails]
					WHERE	StatusActive = 1
					AND		SalaryComponentTypeId = 2
				)
			SELECT	DCD.COLUMN_NAME AS PayslipColumn
					,DCCD.ComponentName AS SalaryComponent 
					,DCCD.ComponentType
			INTO	#DeductionColumns
			FROM	DeductionColumnDetails DCD
			JOIN	DeductionComponentDetails DCCD 
				ON	DCD.ColumnNumber = DCCD.ColumnNumber 
				AND DCCD.ComponentType = 'Deductions';

			SELECT	@EarningsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			FROM	#EarningColumns 
			WHERE	ComponentType = 'Earnings';

			SELECT	@DeductionsColumns = STRING_AGG(QUOTENAME(PayslipColumn), ', ')
			FROM	#DeductionColumns 
			WHERE	ComponentType = 'Deductions';

			SELECT	@EarningComponents = STRING_AGG(QUOTENAME(EC.SalaryComponent), ', ')   
			FROM	#EarningColumns EC
			LEFT JOIN SalaryComponentsDetails SCD 
				ON	EC.SalaryComponent = SCD.ComponentName;

			SELECT	@DeductionComponents = STRING_AGG(QUOTENAME(DC.SalaryComponent), ', ')    
			FROM	#DeductionColumns DC
			LEFT JOIN SalaryComponentsDetails SCD 
				ON	DC.SalaryComponent = SCD.ComponentName;

			SET @ComponentColumns = @EarningComponents + ', [ClaimAmount], [OtherEarnings], [TotalEarnings], ' 
								    + @DeductionComponents + ', [AdvanceAmount], [LoanDueAmount], [OtherDeduction], [TotalDeduction]';

			
			SET @SQL = 'DROP TABLE IF EXISTS ##TempTable;
						WITH UnpivotedData 
						AS	(
								SELECT	EmployeeId, Branch, Department
										,EffectiveWorkDays, PresentDays, LOP, SalaryComponent, ComponentValue, NetPay
										,PaymentTypeId, PayslipStatus, [Month], [Year]
								FROM	(
										SELECT	PD.EmployeeId, BD.BranchName AS Branch, DD.DepartmentName AS Department, 
												PD.EffectiveWorkDays, PD.PresentDays, PD.LOP, [Month], [Year], 
												' + @EarningsColumns + ', ClaimAmount, OtherEarnings, TotalEarnings, 
												' + @DeductionsColumns + ', AdvanceAmount, LoanDueAmount, OtherDeduction, TotalDeduction,
												PD.NetPay, PD.PaymentTypeId, PD.PayslipStatus
										FROM	PaySlipDetails_1 PD
										JOIN	[dbo].[EmployeeDetails] ED 
											ON	PD.EmployeeId = ED.EmployeeId
										LEFT JOIN [dbo].[BranchDetails] BD
											ON	ED.BranchId = BD.BranchId
										LEFT JOIN [dbo].[DepartmentDetails] DD 
											ON	ED.DepartmentId = DD.DepartmentId
										LEFT JOIN [dbo].[DesignationDetails] DSD 
											ON	ED.DesignationId = DSD.DesignationId
									) p
								UNPIVOT 
								(
									ComponentValue 
									FOR	PayslipColumn 
									IN	(' + @EarningsColumns + ', ClaimAmount, OtherEarnings, TotalEarnings, ' 
										+ @DeductionsColumns + ', AdvanceAmount, LoanDueAmount, OtherDeduction
										,TotalDeduction)
								) AS unpvt
								JOIN (	SELECT PayslipColumn, SalaryComponent FROM #EarningColumns
										UNION ALL
										SELECT PayslipColumn, SalaryComponent FROM #DeductionColumns
										UNION ALL
										SELECT ''ClaimAmount'', ''ClaimAmount''
										UNION ALL
										SELECT ''OtherEarnings'', ''OtherEarnings''
										UNION ALL
										SELECT ''TotalEarnings'', ''TotalEarnings''
										UNION ALL
										SELECT ''AdvanceAmount'', ''AdvanceAmount''
										UNION ALL
										SELECT ''LoanDueAmount'', ''LoanDueAmount''
										UNION ALL
										SELECT ''OtherDeduction'', ''OtherDeduction''
										UNION ALL
										SELECT ''TotalDeduction'', ''TotalDeduction''
									) AS Mapping
								ON	unpvt.PayslipColumn = Mapping.PayslipColumn
							)
				SELECT	EmployeeId, Branch, Department, [Month], [Year]
						,EffectiveWorkDays, PresentDays, LOP, ' + @ComponentColumns + ', NetPay, PaymentTypeId
						,PayslipStatus
				INTO	##TempTable
				FROM	UnpivotedData
				PIVOT	
					(
						SUM	(ComponentValue) 
						FOR SalaryComponent 
						IN (' + @ComponentColumns + ')
					) AS PivotTable
				ORDER BY EmployeeId;';
			PRINT @SQL;
			EXEC SP_EXECUTESQL @SQL

			DECLARE @DSqlQuery NVARCHAR(MAX);

			SET	@DSqlQuery = '	SELECT	Branch, Department
										,ED.EmployeeCompanyId AS EmployeeId, CONCAT(ED.FirstName, '' '', ED.LastName) AS EmployeeName
										,CONCAT(CASE	WHEN [Month] = 1 THEN ''Jan''
														WHEN [Month] = 2 THEN ''Feb''
														WHEN [Month] = 3 THEN ''Mar''
														WHEN [Month] = 4 THEN ''Apr''
														WHEN [Month] = 5 THEN ''May''
														WHEN [Month] = 6 THEN ''Jun''
														WHEN [Month] = 7 THEN ''Jul''
														WHEN [Month] = 8 THEN ''Aug''
														WHEN [Month] = 9 THEN ''Sep''
														WHEN [Month] = 10 THEN ''Oct''
														WHEN [Month] = 11 THEN ''Nov''
														WHEN [Month] = 12 THEN ''Dec''
													ELSE ''''
										END,'' - '', [Year]) AS [Month]											
										, EffectiveWorkDays, PresentDays, LOP, [Basic Salary]
										,HRA, DA, [Other Allowances], ClaimAmount, ISNULL(OtherEarnings,0) AS OtherEarnings
										,TotalEarnings, Leave, PF, ESI, PT, AdvanceAmount, LoanDueAmount, OtherDeduction
										,TotalDeduction, NetPay, PaymentTypeName AS PaymentType
										,CASE WHEN PayslipStatus = 1 THEN ''Processed'' ELSE ''Not-Processed'' 
										END AS PayslipStatus
								FROM	##TempTable T1
								JOIN	[dbo].[EmployeeDetails] ED 
									ON	T1.EmployeeId = ED.EmployeeId
								LEFT JOIN [dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN [dbo].[DepartmentDetails] DD 
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN [dbo].[DesignationDetails] DSD 
									ON	ED.DesignationId = DSD.DesignationId 
								LEFT JOIN [dbo].[PaymentTypeDetails] PTD 
									ON	T1.PaymentTypeId = PTD.PaymentTypeId '

			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Payslip Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @FromDate IS NULL) OR ([Month] BETWEEN MONTH(@FromDate) AND MONTH(@ToDate)))
													ORDER BY [Month];'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Payslip Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @FromDate IS NULL) OR ([Month] BETWEEN MONTH(@FromDate) AND MONTH(@ToDate)))
													ORDER BY [Month];'
				PRINT @DSqlQuery;
				EXEC SP_EXECUTESQL @DSqlQuery, N' @FromDate DATE, @ToDate DATE, @ReportValue SQL_VARIANT', @FromDate, @ToDate, @ReportValue;
			END 
			ELSE IF @ReportCategory =  'PayslipStatus'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE 'Processed' END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Payslip Report' AS ReportName 
			
				--SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
				--									AND		((@FromDate IS NULL AND @FromDate IS NULL) OR ([Month] BETWEEN MONTH(@FromDate) AND MONTH(@ToDate)))
				--									ORDER BY [Month];'
				PRINT @DSqlQuery;
				EXEC SP_EXECUTESQL @DSqlQuery, N' @FromDate DATE, @ToDate DATE, @ReportValue SQL_VARIANT', @FromDate, @ToDate, @ReportValue;
			END 
		END
		  SELECT	@Status	   = 1   
				,@Message  = NULL;
	END TRY
	BEGIN CATCH
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),'')); 
	END CATCH
END
/*==============================================================================================================================================
	DECLARE	 @Status	BIT
			,@Message	NVARCHAR(500);

	EXEC [dbo].[USP_Rpt_PaySlipDetails]	@LoginUserId		=  1
										,@FromDate			=  NULL -- '2025-01-01'
										,@ToDate			=  NULL -- '2025-01-28' 
										,@Reportcategory	= 'PayslipStatus'
										,@ReportValue		= 2
										,@Status			= @Status	OUT
										,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;  

	SELECT	* 
	FROM	[dbo].[PayslipDetails_1];
	SELECT	*
	FROM	[dbo].[EmployeePersonalDetails];

	SELECT	*
	FROM	[dbo].[EmployeeOfficialDetails];

==================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_PermissionDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================== 
 Procedure Name		:	[dbo].[USP_Rpt_PermissionDetails]
 Description		:	Procedure used to retrieve the PermissionDetails (When click on PermissionCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	30-08-2023
 Version			:	2.0 
 Comment			:	1. Get the Permission ReportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_PermissionDetails]
(
	@LoginUserId		INT
	,@FromDate			DATETIME
	,@ToDate			DATETIME
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ReportCategory = 'Summarize'
		BEGIN 
			SELECT  DISTINCT @ReportCategory AS ReportCategory
					,'All' AS ReportValue
					,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
						ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
					END AS Duration
					,'Permission Report' AS ReportName;

			SELECT	BranchName	AS Branch
					,DepartmentName AS Department
					,EmployeeCompanyId AS EmpId
					,CONCAT(ED.FirstName,'',ED.LastName) AS EmpName
					,DesignationName AS Designation 
					,LeaveTypeName AS LeaveType 
					,CONCAT(ISNULL(FORMAT(DATEADD(MINUTE, SUM(DATEDIFF(MINUTE,StartTime,EndTime)), 0), 'HH:mm'),'00:00'),' Hrs') AS NumberOfHours
			FROM	[dbo].[PermissionDetails] PD
			JOIN	[dbo].[EmployeeDetails] ED
				ON	PD.EmployeeId = ED.EmployeeId
			LEFT JOIN	[dbo].[BranchDetails] BD
				ON	ED.BranchId = BD.BranchId
			LEFT JOIN	[dbo].[DepartmentDetails] DD
				ON	ED.DepartmentId = DD.DepartmentId
			LEFT JOIN	[dbo].[DesignationDetails] DSD
				ON	ED.DesignationId = DSD.DesignationId
			LEFT JOIN	[dbo].[LeaveTypeDetails] LTD
				ON	PD.PermissionTypeId = LTD.LeaveTypeId
			WHERE	((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
			GROUP BY BranchName, DepartmentName, EmployeeCompanyId, CONCAT(ED.FirstName,'',ED.LastName), DesignationName	
					 ,LeaveTypeName	
		END 
		ELSE 
		BEGIN 
			SET	@DSqlQuery = '	SELECT	BranchName	AS Branch
										,DepartmentName AS Department
										,EmployeeCompanyId AS EmpId
										,CONCAT(ED.FirstName,'''',ED.LastName) AS EmpName
										,DesignationName AS Designation 
										,CASE WHEN PD1.PermissionId IS NOT NULL THEN ''UnPlanned'' ELSE ''Planned'' END AS PermissionType
										,CONVERT(NVARCHAR(50),PermissionDate,106) AS [Date]
										,CONCAT(ISNULL(FORMAT(DATEADD(MINUTE, DATEDIFF(MINUTE,StartTime,EndTime), 0), ''HH:mm''),''00:00''),'' Hrs'') AS NoOfHours
										,LeaveStatusName AS [Status] 
										,CASE WHEN PD.PermissionStatusId IN(3,4,5,6,7) THEN ISNULL(PAD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
										,CASE WHEN PD.PermissionStatusId IN(3,4,5,6,7) THEN CONCAT(PAD.FirstName,'' '',PAD.LastName) ELSE '' ''
										END AS ApprovedBy 
								FROM	[dbo].[PermissionDetails] PD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	PD.EmployeeId = ED.EmployeeId
								LEFT JOIN	[dbo].[BranchDetails] BD
									ON	ED.BranchId = BD.BranchId
								LEFT JOIN	[dbo].[DepartmentDetails] DD
									ON	ED.DepartmentId = DD.DepartmentId
								LEFT JOIN	[dbo].[DesignationDetails] DSD
									ON	ED.DesignationId = DSD.DesignationId
								JOIN	[dbo].[LeaveTypeDetails] LTD
									ON	PD.PermissionTypeId = LTD.LeaveTypeId
								JOIN	[dbo].[LeavestatusDetails] LSD
									ON	PD.PermissionStatusId = LSD.LeaveStatusId
								LEFT JOIN (	SELECT	PermissionId, EmployeeImage, FirstName, LastName
											FROM	[dbo].[PermissionDetails] PD
											JOIN	[dbo].[Employeedetails] ED
												ON	PD.Updatedby = ED.EmployeeId 
											WHERE	PD.CompanyId = @CompanyId 
											) AS PAD
									ON	PAD.PermissionId = PD.PermissionId
								LEFT JOIN	(	SELECT	PermissionId
												FROM	PermissionDetails
												WHERE	CONVERT(DATE,PermissionDate) < CONVERT(DATE,CreatedDate)
											) AS PD1
									ON	PD.PermissionId = PD1.PermissionId '
								
			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Permission Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,PermissionDate);'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Permission Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,PermissionDate);'
			END
			ELSE IF @ReportCategory =  'PermissionType'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE CASE WHEN @ReportValue = 'UnPlanned' THEN 'UnPlanned' ELSE 'Planned' END END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Permission Report' AS ReportName;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	PD.PermissionId = CASE WHEN @ReportValue  = 1 THEN PD1.PermissionId 
																WHEN @ReportValue  = 2 AND PD1.PermissionId  IS NULL THEN PD.PermissionId 
																WHEN @ReportValue = 0 THEN PD.PermissionId END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,PermissionDate);'
			END
			ELSE IF @ReportCategory = 'Status'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Permission Report' AS Reportname
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	PD.PermissionStatusId = CASE WHEN @ReportValue = 0 THEN PD.PermissionStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,PermissionDate) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,PermissionDate);'
			END
		
			PRINT @DSqlQuery
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT '
												,@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
		END 
		SELECT	@Status		= 1 
				,@Message	= NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_PermissionDetails]	@LoginUserId		= 1
												,@FromDate			= NULL -- '2025-01-01'
												,@ToDate			= NULL -- '2025-01-30'
												,@ReportCategory	= 'PermissionType'
												,@ReportValue		= 2
												,@Status			= @Status	OUT
												,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;
	
	SELECT	* 
	FROM	[dbo].[PermissionDetails];

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_Rpt_RegularizationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*===============================================================================================================================================================
 ProcedureName		:	[dbo].[USP_Rpt_RegularizationDetails]
 Description		:	Procedure used to retrieve the RegularizationDetails (When click on RegularizationCategory in Report screen)
 Input Parameter	:	@LoginUserId, @FromDate, @ToDate, @ReportCategory, @ReportValue		
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	09-02-2025
 Version			:	2.0
 Comment			:	1. Get the Regularization reportDetails for the Given @FromDate, @ToDate, @ReportCategory, @ReportValue
							to show the values in Grid.
						2. Then Return the output Parameter values as @Status = 1 and @Message = NULL.
======================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_Rpt_RegularizationDetails]
(
	@LoginUserId		INT
	,@FromDate			DATE
	,@ToDate			DATE
	,@ReportCategory	NVARCHAR(100)
	,@ReportValue		SQL_VARIANT
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId		TINYINT
			,@DSqlQuery		NVARCHAR(MAX);

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		SET	@DSqlQuery = '	SELECT	BranchName	AS Branch
									,DepartmentName AS Department
									,EmployeeCompanyId AS EmpId
									,CONCAT(ED.FirstName,'' '',ED.LastName) AS EmpName
									,CONVERT(NVARCHAR(50),[Date],106) AS [Date]
									,DesignationName AS Designation
									,CASE WHEN PunchType = 1 THEN ''CheckIn'' ELSE ''CheckOut'' END AS [Type]
									,ISNULL(FORMAT(CONVERT(DATETIME,InOutTime),''hh:mm tt''),'''') AS [Time]
									,LeaveStatusName AS [Status]
									,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN ISNULL(RVD.EmployeeImage,'''') ELSE '''' END AS ApprovePrsnImg
									,CASE WHEN LSD.LeaveStatusId IN(3,4,5,6,7) THEN CONCAT(RVD.FirstName,'' '',RVD.LastName)
											ELSE '' '' 
										END AS ApprovedBy 
							FROM	[dbo].[RegularizationDetails] RD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	RD.EmployeeId = ED.EmployeeId
							JOIN	[dbo].[BranchDetails] BD
								ON	ED.BranchId = BD.BranchId
							JOIN	[dbo].[DepartmentDetails] DD
								ON	ED.DepartmentId = DD.DepartmentId
							JOIN	[dbo].[DesignationDetails] DSD
								ON	ED.DesignationId = DSD.DesignationId
							JOIN	[dbo].[LeavestatusDetails] LSD
								ON	RD.RegularizationStatusId = LSD.LeaveStatusId
							LEFT JOIN (	SELECT	RegularizationId, EmployeeImage, FirstName, LastName
										FROM	[dbo].[RegularizationDetails] RD
										JOIN	[dbo].[Employeedetails] ED
											ON	RD.Updatedby = ED.EmployeeId 
										WHERE	RD.CompanyId = 1 
										) AS RVD
								ON	RVD.RegularizationId = RD.RegularizationId ' 

		
			IF @ReportCategory = 'Branch'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE BranchName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Regularization Report' AS ReportName
				FROM	[dbo].[BranchDetails]
				WHERE	BranchId = CASE WHEN @Reportvalue = 0 THEN BranchId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.BranchId = CASE WHEN @ReportValue = 0 THEN ED.BranchId ELSE @ReportValue END
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,[Date]);'
			END 
			ELSE IF @ReportCategory =  'Department'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE DepartmentName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Regularization Report' AS ReportName
				FROM	[dbo].[DepartmentDetails]
				WHERE	DepartmentId = CASE WHEN @Reportvalue = 0 THEN DepartmentId ELSE @ReportValue END;
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	ED.DepartmentId = CASE WHEN @ReportValue  = 0 THEN ED.DepartmentId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,[Date]);'
			END
			ELSE IF @ReportCategory =  'PunchType'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE CASE WHEN PunchType = 1 THEN 'CheckIn' ELSE 'CheckOut' END END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Regularization Report' AS ReportName
				FROM	[dbo].[RegularizationDetails]
				WHERE	(@ReportValue = 0 OR @ReportValue = PunchType);
			
				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	RD.PunchType = CASE WHEN @ReportValue  = 0 THEN RD.PunchType ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,[Date]);'
			END
			ELSE IF @ReportCategory = 'RegularizationStatus'
			BEGIN
				SELECT  DISTINCT @ReportCategory AS ReportCategory
						,CASE WHEN @ReportValue = 0 THEN 'All' ELSE LeaveStatusName END AS ReportValue
						,CASE WHEN  @FromDate IS NULL AND @ToDate IS NULL THEN ''
							ELSE CONCAT(CONVERT(NVARCHAR(50),@FromDate,105), ' to ',CONVERT(NVARCHAR(50),@ToDate,105))
						END AS Duration
						,'Regularization Report' AS Reportname
				FROM	[dbo].[LeaveStatusDetails]
				WHERE	LeaveStatusId = CASE WHEN @Reportvalue = 0 THEN LeaveStatusId ELSE @ReportValue END;

				SELECT @DSqlQuery = @DSqlQuery + '	WHERE	RD.RegularizationStatusId = CASE WHEN @ReportValue = 0 THEN RD.RegularizationStatusId ELSE @ReportValue END 
													AND		((@FromDate IS NULL AND @ToDate IS NULL) OR (CONVERT(DATE,[Date]) BETWEEN @FromDate AND @ToDate))
													ORDER BY CONVERT(DATE,[Date]);'
			END
		
			PRINT @DSqlQuery
			EXECUTE SP_EXECUTESQL @DSqlQuery, N'@FromDate DATETIME, @ToDate DATETIME, @ReportValue SQL_VARIANT, @CompanyId TINYINT',
												@FromDate = @FromDate, @ToDate = @ToDate, @ReportValue = @ReportValue, @CompanyId = @CompanyId;
		SELECT	@Status = 1 
				,@Message = NULL;
	END TRY 
	BEGIN CATCH 
		SELECT	@Status = 0
				,@Message = CONVERT(NVARCHAR(500),ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END 
/*===============================================================================================================================================
	DECLARE	@Status		BIT
			,@Message	NVARCHAR(500)

	EXECUTE [dbo].[USP_Rpt_RegularizationDetails]	@LoginUserId		= 1
													,@FromDate			= NULL -- '2024-04-01'
													,@ToDate			= NULL -- '2024-04-29'
													,@ReportCategory	= 'RegularizationStatus'
													,@ReportValue		= 0
													,@Status			= @Status	OUT
													,@Message			= @Message	OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM RegularizationDetails

==============================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_SignUpDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=========================================================================================================================================================  
 Procedure Name		:	[USP_SignUpDetails]
 Description		:	Procedure used to insert the new EmployeeDetails,CompanyDetails (When Click on SignUp Button in Login Screen)
 Input Parameter	:	@FirstName,@LastName,@CompanyName,@ContactNo,@OfficialEmail.
 Output Parameters	:	@Status,@Message
 Author				:	Dharani.M
 Created on			:	11-09-2023
 Version			:	1.0 
 Comment			:  1. Check the Given ContactNo is already exists or not?
						  1.1 If exist,Return the error message as @Status = 0 And @Message = "Entered CompanyName Already Exists. Cant Signup."
					   2. Check the Given OfficialEmail is already exists or not?
						  2.1 If exist,Return the error message as @Status = 0 And @Message = "Entered ContactNo Already Registered.".
					   3. Check the Given CompanyName is already exists or not?
						  3.1 If exist,Return the error message as @Status = 0 And @Message = "Entered OfficialEmail Already Registered.".
					   4. If Both Above Conditions are not exist,  
					   5. Insert into CompanyDetails tables have the column of 
																CompanyName		AS @CompanyName
																,CompanyEmail	AS @OfficialEmail
																,IsActive		AS 1
					   6.Insert into EmployeeDetails tables have the column of
																FirstName		AS @FirstName
																,LastName		AS @LastName
																,ContactNo		AS @ContactNo
																,OfficialEmail	AS @OfficialEmail
																,[Password]		AS 'Login@123'
																,UserGroupId	AS 1
																,IsLoginUser	AS 1
																,CompanyId		AS @CompanyId
																,IsActive		AS 0
					   7.Then,Activate the User/Company.
					   8.Then through the Success POPUP message as "SignUp Completed.Login with the credentials which you got in welcome mail to your Mailid."
						  has been created Successfully'.
=================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_SignUpDetails]
(
	@FirstName			NVARCHAR(100)
	,@LastName			NVARCHAR(100)
	,@UserCountry		NVARCHAR(50)
	,@CompanyName		NVARCHAR(100)
	,@Email				NVARCHAR(200)
	,@ContactNumber		NVARCHAR(200)
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT
			,@UserId INT;

	BEGIN TRY
		--If the Given CompanyName is already exists or not?Return the error message as @Status = 0 And @Message = "Entered CompanyName Already Exists. Cant Signup."
		IF EXISTS (SELECT 1 FROM [dbo].[CompanyDetails] WHERE CompanyName = @CompanyName)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Entered CompanyName Already Exists. Cant Signup.'
			RETURN;
		END
		-- If the Given ContactNo is already exists or not?Return the error message as @Status = 0 And @Message = "Entered ContactNo already Exist.".
		IF EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE ContactNo = @ContactNumber)
		BEGIN
			SELECT @Status		= 0
					,@Message	= 'Entered ContactNo Already Registered.'
			RETURN;
		END
		--If the Given OfficialEmail is already exists or not?Return the error message as @Status = 0 And @Message = "Entered Email already Exist.".
		ELSE IF EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE OfficialEmail = @Email)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Entered OfficialEmail Already Registered.'
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN 
				--Procedure Will Insert the CompanyDetails(CompanyName)
				INSERT INTO [dbo].[CompanyDetails](CompanyName, CompanyContactNumber, CompanyEmail,IsActive)
				VALUES		(@CompanyName, @ContactNumber, @Email, 1);

				SELECT @CompanyId = SCOPE_IDENTITY();

				--Procedure Will Insert the EmployeeDetails(FirstName,LastName,ContactNo,OfficialEmail)
				INSERT INTO [dbo].[EmployeeDetails](FirstName,LastName,ContactNo,Country,OfficialEmail,[Password], UserGroupId, CompanyId,IsLoginUser,IsActive)
				VALUES		(@FirstName
							,@LastName
							,@ContactNumber
							,@UserCountry
							,@Email
							,'Login@123'
							,1
							,@CompanyId
							,1
							,0);
				
				SELECT @UserId = SCOPE_IDENTITY();

				-- Activate User / Company
				EXEC [dbo].[USP_UpdateActivateUserDetails]	@LoginUserId	= 1
															,@UserId		= @UserId
															,@IsActive		= 1
															,@Status		= @Status	OUT
															,@Message		= @Message	OUT;

				SELECT	FirstName
						,OfficialEmail AS Email
						,ContactNo AS  ContactNumber
						,CONCAT('"',[Password],'"') AS [Password]
				FROM	[dbo].[EmployeeDetails]
				WHERE	EmployeeId = @UserId
				AND		CompanyId = @CompanyId;

			IF @@TRANCOUNT>0
			COMMIT TRAN

			SELECT	@Status   = 1    
					,@Message = 'SignUp Completed. Login with the credentials which you got in welcome mail to your Mailid.';  
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));		
	END CATCH
END
/*==================================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)
			
	EXEC [dbo].[USP_SignUpDetails]	@FirstName			= '456dfg'
									,@LastName			= 'M'
									,@CompanyName		= 'fgfdf'
									,@ContactNumber		= '4567876543'
									,@UserCountry		='ghgdfg'
									,@Email				= 'fghjhg@gmail.com'
									,@Status			= @S_Status	 OUT
									,@Message			= @M_Message OUT;		
									
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[EmployeeDetails];
	SELECT	*
	FROM	[dbo].[CompanyDetails];

========================================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateActivateUserDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==========================================================================================================================  
 Procedure Name		:	[USP_UpdateActivateUserDetails]
 Description		:	Procedure used to Activate the Employee
 Input Parameter	:	@LoginUserId,@EmployeeId,@IsActive
 Output Parameters	:	@Status,@Message
 Author				:	Dharani.M
 Created on			:	11-09-2023
 Version			:	1.0 
 Comment			:	1.If the Given EmployeeId is Not exists.Then
						  1.1 Return the error message as @Status = 0 And @Message = "Entered EmployeeId Not Exists".
						2.If the given EmployeeId is Exists.
						  2.1 Upadate the EmployeeDetails Have the Column of
									IsActive		AS @IsActive
									,UpdatedBy		AS @EmployeeId
									,UpdatedDate	AS GETDATE().
						3.Then return the output Parameter values as @Status = 1 and @Message = 'User Activated Successfully.'
================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateActivateUserDetails]
(
	@LoginUserId	INT
	,@UserId		INT
	,@IsActive		BIT
	,@Status		BIT				OUT		
	,@Message		NVARCHAR(500)	OUT	
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId	= @UserId;

	BEGIN TRY
		--If Exists, returns the Error msg as Status = 0 And Message = "Entered User is Not Exist.".	
		IF NOT EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE EmployeeId = @UserId AND CompanyId = @CompanyId)
		BEGIN
			SELECT @Status   = 0 
				   ,@Message = 'Given User is not Exist.';
			RETURN;
		END
		BEGIN
			BEGIN TRAN
				--If Exists,Update the UserDetails
				UPDATE	[dbo].[EmployeeDetails]
				SET		IsActive			= @IsActive
						,Updatedby			= @LoginUserId 
						,UpdatedDate  		= GETDATE()
				WHERE	EmployeeId			= @UserId 
				AND		CompanyId			= @CompanyId;

			IF @@TRANCOUNT >0
			COMMIT TRAN

			SELECT	 @Status  = 1   
					,@Message = 'User Activated Successfully.';  
		END
	END TRY  
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	 @Status  = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateActivateUserDetails]	@LoginUserId	= 1
												,@EmployeeId	= 2
												,@IsActive		= 1
												,@Status		= @S_Status		OUT
												,@Message		= @M_Message	OUT;		
												
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
=================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateAdvanceDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*======================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_UpdateAdvanceDetails]
 Description		:	Procedure used to Update the existing AdvanceDetails ( When Click on Update Button in Advance Screen popup)
 Input Parameter	:	@LoginUserId,@EmployeeId,@AdvanceId, @AdvanceDate, @AdvanceAmount, @DueAmount, @AdvanceStatusId, @Description				
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	29-08-2023
 Version			:	1.0 
 Comment			:   1. procedure will used to update the AdvanceDetails have the columns of 
									AdvanceDate			AS @AdvanceDate
									,EmployeeId			AS @EmployeeId
									,AdvanceAmount		AS @AdvanceAmount
									,DueAmount			AS @DueAmount
									,AdvanceStatusId	AS @AdvanceStatusId
									,Description		AS @Description
									,UpdatedBy			AS @EmployeeId
									,UpdatedDate		AS GETDATE() for the given AdvanceId.
						2.Then return the output Parameter values as @Status = 1 and @Message = 'The AdvanceDetails are updated Successfully.'
=============================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateAdvanceDetails]
(
	@LoginUserId			INT
	,@EmployeeId			INT
	,@AdvanceId				INT
	,@AdvanceDate			DATETIME	
    ,@AdvanceAmount			NUMERIC(11,2)	
	,@DueAmount				NUMERIC(11,2)
	,@AdvanceStatusId		TINYINT
	,@Description			NVARCHAR(500)
	,@Comments				NVARCHAR(500)
	,@Status				BIT				OUT
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE  @CompanyId		TINYINT
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;
		 
	BEGIN TRY
		BEGIN TRAN 
			UPDATE	[dbo].[AdvanceDetails]
			SET		EmployeeId			= @EmployeeId
					,AdvanceDate		= @AdvanceDate	
					,AdvanceAmount		= @AdvanceAmount	
					,DueAmount			= @DueAmount
					,AdvanceStatusId	= @AdvanceStatusId
					,[Description]		= @Description
					,Comments			= @Comments
					,Updatedby			= @LoginUserId 
					,UpdatedDate		= GETDATE()
			WHERE	AdvanceId			= @AdvanceId 
			AND		CompanyId			= @CompanyId 

			IF @AdvanceStatusId IN (3, 4)
			BEGIN
				IF (SELECT COUNT(1) FROM [dbo].[NotificationDetails] WHERE	NotificationModuleRefId = @AdvanceId
					AND	 NotificationTypeName = 'Advance') <> 2
				BEGIN		
					INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName, IsInternal
								,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
								,SMS_To, IsAuto, CompanyId, CreatedBy)							
					SELECT	@AdvanceId
							,'Advance'
							,1			
							,'Employee'
							,CASE WHEN @AdvanceStatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your Advance', 
									' request has been approved on ', CONVERT(NVARCHAR(30),AD.UpdatedDate,106),
										'. Please Contact our Manager.') 
								ELSE CONCAT('Dear ', ED.FirstName, ', Your Advance', 
									' request has been rejected on ', CONVERT(NVARCHAR(30),AD.UpdatedDate,106),
										'. Please Contact our Manager.') 
							END 
							,3
							,ED.EmployeeId  
							,'Open'
							,'Open'       
							,ED.ContactNo	
							,1
							,@CompanyId
							,@LoginUserId	 
					FROM	[dbo].[AdvanceDetails] AS AD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	ED.EmployeeId = AD.EmployeeId			
					WHERE	AdvanceId = @AdvanceId 
					AND		AD.CompanyId = @CompanyId;
				END
			END
				
		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Changes Saved Successfully.'
				
		IF @AdvanceStatusId IN (3, 4)
		BEGIN 
			IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				SELECT	DISTINCT ED.OfficialEmail AS ToMail
						,CASE WHEN @AdvanceStatusId = 3 THEN 'Approval of Advance' ELSE 'Rejected of Advance' 
						END AS [Subject]
						,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
						,'I hope you are doing well.' AS SecondLine
						,CASE WHEN @AdvanceStatusId = 3 THEN CONCAT('This is to inform you that your request for Advance on '
								,CONVERT(NVARCHAR(50),@AdvanceDate,106),' and the advance amount of ', @AdvanceAmount
								,' has been approved by {', EmployeeName, QUOTENAME(AD.EmployeeCompanyId),'}.')
							ELSE CONCAT('This is to inform you that your request for Advance on '
								,CONVERT(NVARCHAR(50),@AdvanceDate,106),' and the advance amount of ', @AdvanceAmount
								,' has been Rejected by {', EmployeeName, QUOTENAME(AD.EmployeeCompanyId),'}.')
						END AS ThirdLine
						,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
						,'For any further assistance, feel free to reach out.' AS FifthLine
						,'Thank You.' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN (	SELECT	AD.EmployeeId, AD.AdvanceId, EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
									,EmployeeCompanyId
							FROM	[dbo].[AdvanceDetails] AD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	AD.Updatedby = ED.EmployeeId 
							WHERE	AD.CompanyId = @CompanyId 
							AND		AdvanceId = @AdvanceId
							) AS AD
					ON	AD.EmployeeId = ED.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==========================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500)
			  
	EXEC [dbo].[USP_UpdateAdvanceDetails]	@LoginUserId		= 1
											,@EmployeeId		= 3
											,@AdvanceId			= 15
										    ,@AdvanceDate		= '2025-01-10'				
											,@AdvanceAmount		= 1250		
											,@DueAmount			= 500
											,@AdvanceStatusId	= 4
											,@Description		= ' '
											,@Comments			= '  '
											,@Status			= @S_Status	 OUT			
											,@Message			= @M_Message OUT;	
											
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT *
	FROM	[dbo].[AdvanceDetails];
	SELECT *
	FROM	[dbo].[LeavestatusDetails];
	SELECT *
	FROM	[dbo].[NotificationDetails];
============================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateAssetDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateAssetDetails]
 Description		:	Procedure used to Update the new EmployeeAssetMappingDetails 
															(When Click on Update Button in Asset PopupPage)
 Input Parameter	:	@LoginUserId, @TVP_EmployeeAssetMappingDetails.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	21-01-2025
 Version			:	1.0 
 Comment			:	1. Logic will Update into EmployeeAssetMappingDetails table have the Columns of 
							EmployeeAssetMappingId, EmployeeId, AssetTypeId, AssetModel, SerialNumber
							,Condition, IssuedDate, AssetDescription to use in Table valued parameter 
							@TVP_EmployeeAssetMappingDetails.
						2. Then return the output parameter values @Status = 1 & 
												@Message = 'Asset Updated Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateAssetDetails]
(
	@LoginUserId						INT		
	,@AssetId							INT
	,@EmployeeId						INT
	,@Date								DATE
	,@TVP_EmployeeAssetMappingDetails	TVP_EmployeeAssetMappingDetails READONLY
	,@Status							BIT								OUT	
	,@Message							NVARCHAR(500)					OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
		 BEGIN TRAN
			UPDATE	[dbo].[AssetDetails]
			SET		EmployeeId		= @EmployeeId
					,[Date]			= @Date
					,UpdatedBy		= @LoginUserId
					,UpdatedDate	= GETDATE()
			WHERE	AssetId			= @AssetId;

			MERGE	[dbo].[EmployeeAssetMappingDetails]		AS TARGET  
			USING	@TVP_EmployeeAssetMappingDetails		AS SOURCE  
				ON	TARGET.EmployeeAssetMappingId = SOURCE.EmployeeAssetMappingId 
				AND	TARGET.AssetId	= @AssetId
			WHEN MATCHED THEN  
			UPDATE    
			SET		TARGET.AssetTypeId			= SOURCE.AssetTypeId  
					,TARGET.AssetModel			= SOURCE.AssetModel    
					,TARGET.SerialNumber		= SOURCE.SerialNumber
					,TARGET.Condition			= SOURCE.Condition
					,TARGET.AssetDescription	= SOURCE.AssetDescription
					,TARGET.Updatedby			= @LoginUserId  
					,TARGET.UpdatedDate			= GETDATE()  
			WHEN NOT MATCHED BY TARGET THEN  
			INSERT	(AssetId, AssetTypeId, AssetModel, SerialNumber, Condition, AssetDescription, CreatedBy)  
			VALUES	(@AssetId
					,AssetTypeId
					,AssetModel
					,SerialNumber
					,Condition
					,AssetDescription
					,@LoginUserId)
			WHEN NOT MATCHED BY SOURCE AND TARGET.AssetId = @AssetId THEN
			DELETE;

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Asset Updated Successfully.'; 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
