/*=============================================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateAttendanceMachineDetails]
 Description		:	Procedure used to Update the AttendanceMachineDetails
													(When Click on Update Button in AttendanceMachine Info PopupPage)
 Input Parameter	:	@LoginUserId, @AttendanceMachineId, @AttendanceMachineName, @SerialNo, @MachineDescription.
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	15-06-2024
 Version			:	1.0 
 Comment			:	1. Update the AttendanceMachineDetails for the given @AttendanceMachineId.
						2. Then through the Success POPUP message as 'Changes Saved Successfully.'.
=========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateAttendanceMachineDetails]
(
    @LoginUserId						INT
    ,@AttendanceMachineId				INT
    ,@AttendanceMachineName				NVARCHAR(100)       
    ,@SerialNo							NVARCHAR(100) 
    ,@MachineDescription				NVARCHAR(200)    
	,@IsActive							BIT
    ,@TVP_EmployeeDeviceMappingDetails  TVP_EmployeeDeviceMappingDetails	READONLY      
    ,@Status							BIT									OUT  
    ,@Message							NVARCHAR(500)						OUT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Declare the Variables.
    DECLARE @CompanyId  TINYINT;

    SELECT  @CompanyId = CompanyId 
    FROM    [dbo].[EmployeeDetails]
    WHERE   EmployeeId = @LoginUserId;

    BEGIN TRY
        IF EXISTS (  SELECT  1 
                     FROM    [dbo].[AttendanceMachineDetails]
                     WHERE   CompanyId = @CompanyId 
                     AND     AttendanceMachineName = @AttendanceMachineName
                     AND     AttendanceMachineId != @AttendanceMachineId)
        BEGIN 
            SELECT  @Status      = 0
                    ,@Message    = 'Entered MachineName is already mapped.';
            RETURN;
        END 
        ELSE 
        BEGIN       
            BEGIN TRAN
                UPDATE [dbo].[AttendanceMachineDetails]
                SET     AttendanceMachineName	= @AttendanceMachineName
                        ,SerialNo				= @SerialNo
                        ,MachineDescription		= @MachineDescription
						,IsActive				= @IsActive
                        ,UpdatedBy				= @LoginUserId 
                        ,UpdatedDate			= GETDATE()
                WHERE   AttendanceMachineId		= @AttendanceMachineId
                AND     CompanyId				= @CompanyId;

                 DECLARE @MergeOutput TABLE
                (
                    MergeAction                 NVARCHAR(10)
                    ,EmployeeDeviceMappingId    INT
                    ,EmployeeId                 INT
                    ,OldStatus                  BIT
                    ,NewStatus                  BIT
                );

				--AND TARGET.IsActive != SOURCE.Status
			  
                MERGE   [dbo].[EmployeeDeviceMappingDetails]	AS TARGET
                USING   @TVP_EmployeeDeviceMappingDetails		AS SOURCE
                    ON  (TARGET.EmployeeDeviceMappingId = SOURCE.EmployeeDeviceMappingId)
                    AND (TARGET.AttendanceMachineId = @AttendanceMachineId)
				WHEN MATCHED   THEN
                UPDATE 
                SET     TARGET.EmployeeId				= SOURCE.EmployeeId
                        ,TARGET.IsActive                = SOURCE.[Status]
						,TARGET.IsBlock                 = TARGET.IsBlock
                        ,TARGET.Updatedby               = @LoginUserId 
                        ,TARGET.UpdatedDate             = GETDATE()
				WHEN NOT MATCHED BY TARGET THEN
				INSERT	(EmployeeId, AttendanceMachineId, IsActive, IsBlock, CreatedBy, CreatedDate)
				VALUES	(SOURCE.EmployeeId
						,SOURCE.AttendanceMachineId
						,SOURCE.[Status]
						,0
						,@LoginUserId
						,GETDATE())
				WHEN NOT MATCHED BY SOURCE AND TARGET.AttendanceMachineId = @AttendanceMachineId
				THEN DELETE
                OUTPUT CASE 
                          WHEN inserted.EmployeeDeviceMappingId IS NOT NULL AND deleted.IsActive != inserted.IsActive 
                          THEN (CASE WHEN inserted.IsActive = 1 THEN 'INSERT' ELSE 'Delete' END)
                          ELSE $action 
                       END AS [Action]
                       ,ISNULL(inserted.EmployeeDeviceMappingId, deleted.EmployeeDeviceMappingId) AS EmployeeDeviceMappingId
                       ,ISNULL(inserted.EmployeeId, deleted.EmployeeId) AS EmployeeId
                       ,deleted.IsActive AS OldStatus
                       ,inserted.IsActive AS NewStatus
                INTO    @MergeOutput;

            IF @@TRANCOUNT >= 0
            COMMIT TRAN

            -- Return the newly added, deleted, and status-changed records
            SELECT  @Status     = 1
                    ,@Message   = 'Changes Saved Successfully.';
			
			-- Result set for Biomatrix.
			SELECT MergeAction
					,CONCAT('TetroPAY/',ED.CompanyId,'/',ED.EmployeeId) AS EmployeeId
					,SerialNo
					,CONCAT(FirstName,' ',LastName) AS EmployeeName
					,CardNumber
            FROM	@MergeOutput MO
			JOIN	[dbo].[EmployeeDetails] ED
				ON	MO.EmployeeId = ED.EmployeeId
			JOIN	[dbo].[EmployeeDeviceMappingDetails] EDMD
				ON	ED.EmployeeId = EDMD.EmployeeId
			JOIN	[dbo].[AttendanceMachineDetails] AMD
				ON	EDMD.AttendanceMachineId = AMD.AttendanceMachineId
			WHERE	MergeAction <> 'UPDATE';
		
			-- Result set for ESSL Application Credential.
			SELECT	ESSLUserName
					,ESSLPassword
					,WebAddress
			FROM	[dbo].[ESSlCredentialDetails]
			WHERE	CompanyId = @CompanyId;
        END
    END TRY
    BEGIN CATCH
        ROLLBACK TRAN;
        SELECT  @Status   = 0
                ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));     
    END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status							BIT
			,@M_Message							NVARCHAR(500)
			,@TVP_EmployeeDeviceMappingDetails	TVP_EmployeeDeviceMappingDetails;
			
	INSERT INTO @TVP_EmployeeDeviceMappingDetails (EmployeeDeviceMappingId, EmployeeId, Status, AttendanceMachineId)
	VALUES		(28, 23, 1, 32)
				,(29, 24, 0, 32)
				--,(18, 5, 0, 3)
				--,(NULL, 6, 1, 2);

	EXEC [dbo].[USP_UpdateAttendanceMachineDetails]	@LoginUserId						= 1
													,@AttendanceMachineId				= 32
													,@AttendanceMachineName				= 'Machine 1'
													,@SerialNo							= 'JPN224111'
													,@MachineDescription				= 'Machine 1 - JPN2241000511'
													,@IsActive							= 1
													,@TVP_EmployeeDeviceMappingDetails	= @TVP_EmployeeDeviceMappingDetails
													,@Status							= @S_Status	 OUT
													,@Message							= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[dbo].[AttendanceMachineDetails];
	
	SELECT	*
	FROM	[dbo].[EmployeeDeviceMappingDetails];
	
	SELECT	*
	FROM	[dbo].[EmployeeDetails];
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateBranchDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
