/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateCandidateDetails]
 Description		:	Procedure used to Update the new CandidateDetails 
																(When Click on Update Button in Candidate PopupPage)
 Input Parameter	:	@LoginUserId, @CandidateId, @InterviewCandidateId, @FirstName, @LastName, @Email
						,@ContactNumber, @GenderId, @JobCategoryId, @CandidateExperience, @CurrentCompanyName
						,@CurrentCTC, @ExpectCTC, @IsImmediateJoiner, @ExpJoiningDate, @Description
						,@TVP_AttachmentDetails.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @InterviewCandidateId is already Exists, then 
							1.1 Through the Error message as @Status = 0 & @Message = 'Given CandidateId is already Exist.'
						2. If the Given @InterviewCandidateId is Not Exists, then 
							2.1 Logic will insert into CandidateDetails table have the Columns of 
									InterviewCandidateId		AS	@InterviewCandidateId
									,FirstName					AS	@FirstName
									,LastName					AS	@LastName
									,Email						AS	@Email
									,ContactNumber				AS	@ContactNumber
									,GenderId					AS	@GenderId
									,JobCategoryId				AS	@JobCategoryId
									,CandidateExperience		AS	@CandidateExperience
									,CurrentCompanyName			AS	@CurrentCompanyName
									,CurrentCTC					AS	@CurrentCTC
									,ExpectCTC					AS	@ExpectCTC
									,IsImmediateJoiner			AS	@IsImmediateJoiner
									,ExpJoiningDate				AS	@ExpJoiningDate
									,Description				AS	@Description
									,CandidateStatusId			AS	@CandidateStatusId
									,CompanyId					AS	@CompanyId
									,CreatedBy					AS	@CreatedBy
							2.2 Then return the output parameter values @Status = 1 & 
									@Message = 'New Candidate Added Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateCandidateDetails]
(
	@LoginUserId				INT		
	,@CandidateId				INT		
	,@InterviewCandidateId		NVARCHAR(50)
	,@FirstName					NVARCHAR(100)
	,@LastName					NVARCHAR(100)
	,@Email						NVARCHAR(200)
	,@ContactNumber				NVARCHAR(50)
	,@GenderId					TINYINT
	,@JobCreationId				INT
	,@CandidateExperience		NUMERIC(4,2)
	,@CurrentCompanyName		NVARCHAR(200)
	,@CurrentCTC				NUMERIC(11,2)
	,@ExpectCTC					NUMERIC(11,2)
	,@IsImmediateJoiner			BIT
	,@ExpJoiningDate			DATE
	,@Description				NVARCHAR(1000)
	,@DesignationId				TINYINT
	,@ReportingPersonId			TINYINT
	,@GradeTypeId				TINYINT
	,@EmployeeStatusId			TINYINT	
	,@Address					NVARCHAR(200)
	,@City						NVARCHAR(100)
	,@State						NVARCHAR(100)
	,@Country					NVARCHAR(100)
	,@Zipcode					NVARCHAR(100)
	,@DateOfBirth				DATETIME
	,@ReligionId				TINYINT
	,@MaritalStatusId			TINYINT
	,@Nationality				NVARCHAR(50)
	,@PersonalEmail				NVARCHAR(100)
	,@AadharNo					NVARCHAR(100)
	,@PANNo						NVARCHAR(100)
	,@PassportNo				NVARCHAR(100)
	,@PassportExpDate			DATETIME
	,@UANNumber					NVARCHAR(100)
	,@PFNumber					NVARCHAR(100)
	,@PayTypeId					TINYINT
	,@PaymentTypeId				TINYINT
	,@TVP_AttachmentDetails		TVP_AttachmentDetails	READONLY
	,@Status					BIT						OUT	
	,@Message					NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
		 IF EXISTS( SELECT	1 FROM [dbo].[CandidateDetails]
					WHERE	InterviewCandidateId = @InterviewCandidateId 
					AND		CandidateId <> @CandidateId 
					AND		CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Given CandidateId is already Exist.';
			RETURN;
		END
		ELSE 
		BEGIN	
			BEGIN TRAN 
				UPDATE	[dbo].[CandidateDetails]
				SET		InterviewCandidateId			=	@InterviewCandidateId
						,FirstName						=	@FirstName
						,LastName						=	@LastName
						,Email							=	@Email
						,ContactNumber					=	@ContactNumber
						,GenderId						=	@GenderId
						,JobCreationId					=	@JobCreationId
						,CandidateExperience			=	@CandidateExperience
						,CurrentCompanyName				=	@CurrentCompanyName
						,CurrentCTC						=	@CurrentCTC
						,ExpectCTC						=	@ExpectCTC
						,IsImmediateJoiner				=	@IsImmediateJoiner
						,ExpJoiningDate					=	@ExpJoiningDate
						,[Description]					=	@Description
						,DesignationId					=	@DesignationId		
						,ReportingPersonId				=	@ReportingPersonId	
						,GradeTypeId					=	@GradeTypeId
						,EmployeeStatusId				=	@EmployeeStatusId
						,[Address]						=	@Address			
						,City							=	@City				
						,[State]						=	@State			
						,Country						=	@Country			
						,Zipcode						=	@Zipcode			
						,DateOfBirth					=	@DateOfBirth		
						,ReligionId						=	@ReligionId			
						,MaritalStatusId				=	@MaritalStatusId	
						,Nationality					=	@Nationality		
						,PersonalEmail					=	@PersonalEmail		
						,AadharNo						=	@AadharNo			
						,PANNo							=	@PANNo				
						,PassportNo						=	@PassportNo			
						,PassportExpDate				=	@PassportExpDate	
						,UANNumber						=	@UANNumber			
						,PFNumber						=	@PFNumber			
						,PayTypeId						=	@PayTypeId			
						,PaymentTypeId					=	@PaymentTypeId		
						,UpdatedBy						=	@LoginUserId
						,UpdatedDate					=	GETDATE()
				WHERE	CandidateId						=	@CandidateId
				AND		CompanyId						=	@CompanyId;
				
				MERGE	[dbo].[AttachmentDetails]	AS TARGET  
				USING	@TVP_AttachmentDetails		AS SOURCE  
					ON	TARGET.AttachmentId = SOURCE.AttachmentId 
					AND TARGET.ModuleRefId = @CandidateId
				WHEN MATCHED THEN  
				UPDATE    
				SET		TARGET.AttachmentFileName	= SOURCE.AttachmentFileName    
						,TARGET.AttachmentFilepath	= SOURCE.AttachmentFilepath
						,TARGET.Updatedby			= @LoginUserId  
						,TARGET.UpdatedDate			= GETDATE()  
				WHEN NOT MATCHED THEN  
				INSERT	(ModuleName, ModuleRefId, AttachmentFileName, AttachmentFilepath, CreatedBy)  
				VALUES	('Candidate'  
						,@CandidateId  
						,SOURCE.AttachmentFileName
						,SOURCE.AttachmentFilepath
						,@LoginUserId)
				WHEN NOT MATCHED BY SOURCE AND TARGET.ModuleRefId = @CandidateId THEN  
				DELETE;  

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'CandidateDetails Are updated Successfully.'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
