/****** Object:  StoredProcedure [dbo].[USP_UpdateCandidateDocumentMappingDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateCandidateDocumentMappingDetails]
 Description		:	Procedure used to Update the new CandidateDocumentMappingDetails 
													(When Click on Upload Button in Document tab in Candidate screen)
 Input Parameter	:	@LoginUserId, @CandidateId, @TVP_CandidateDocumentMappingDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1.Using the merge statement to insert, update & Delete by using @TVP_CandidateDocumentMappingDetails
						2. Then return the output parameter values @Status = 1 & 
									@Message = 'Document Uploaded Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateCandidateDocumentMappingDetails]
(
	@LoginUserId							INT		
	,@CandidateId							INT	
	,@TVP_CandidateDocumentMappingDetails	TVP_CandidateDocumentMappingDetails		READONLY
	,@Status								BIT										OUT	
	,@Message								NVARCHAR(500)							OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		BEGIN TRAN
			MERGE	[dbo].[CandidateDocumentMappingDetails]	AS TARGET  
			USING	@TVP_CandidateDocumentMappingDetails	AS SOURCE  
				ON	TARGET.CandidateDocumentMappingId = SOURCE.CandidateDocumentMappingId   
				AND TARGET.CandidateId = @CandidateId
			WHEN MATCHED THEN  
			UPDATE    
			SET		TARGET.InterviewDocumentId				=	SOURCE.InterviewDocumentId			
					,TARGET.DucumentFileName				=	SOURCE.DucumentFileName				
					,TARGET.DucumentFilePath				=	SOURCE.DucumentFilePath			
					,TARGET.IsActive						=	SOURCE.IsActive		
					,TARGET.UpdatedBy						=	@LoginUserId
					,TARGET.UpdatedDate						=	GETDATE()
			WHEN NOT MATCHED BY TARGET THEN  
			INSERT	(InterviewDocumentId, CandidateId, DucumentFileName, DucumentFilePath, IsActive, CreatedBy)  
			VALUES	(SOURCE.InterviewDocumentId			
					 ,@CandidateId			
					 ,SOURCE.DucumentFileName				
					 ,SOURCE.DucumentFilePath			
					 ,SOURCE.IsActive
					 ,@LoginUserId)
			WHEN NOT MATCHED BY SOURCE AND TARGET.CandidateId = @CandidateId THEN  
			DELETE;

		IF @@TRANCOUNT >= 0  
		COMMIT TRAN  

		SELECT	@Status   = 1        
				,@Message = 'Document Uploaded Successfully.';
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status								BIT
			,@M_Message								NVARCHAR(500)
			,@TVP_CandidateDocumentMappingDetails	TVP_CandidateDocumentMappingDetails

	INSERT INTO @TVP_CandidateDocumentMappingDetails(CandidateDocumentMappingId, InterviewDocumentId, DucumentFileName
				,DucumentFilePath, IsActive)
	VALUES		(171, 1, 'DucumentFileName_1','DucumentFilePath_1', 1)
				,(172, 2, 'DucumentFileName_2','DucumentFilePath_2', 1)
				,(173, 3, 'DucumentFileName_3','DucumentFilePath_3', 1)
				,(174, 4, 'DucumentFileName_4','DucumentFilePath_4', 1)
				,(175, 5, 'DucumentFileName_5','DucumentFilePath_5', 1)
				,(176, 6, 'DucumentFileName_6','DucumentFilePath_6', 1)
				,(177, 7, 'DucumentFileName_7','DucumentFilePath_7', 1)
				,(178, 8, 'DucumentFileName_8','DucumentFilePath_8', 1)
				,(179, 9, 'DucumentFileName_9','DucumentFilePath_9', 1)
				,(180, 10, 'DucumentFileName_10','DucumentFilePath_10', 1);

	EXEC [dbo].[USP_UpdateCandidateDocumentMappingDetails]	@LoginUserId							= 1
															,@CandidateId							= 1
															,@TVP_CandidateDocumentMappingDetails	= @TVP_CandidateDocumentMappingDetails
															,@Status								= @S_Status		OUT
