/****** Object:  StoredProcedure [dbo].[USP_UpdateClaimDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=============================================================================================================================================  
 Procedure Name		: [dbo].[USP_UpdateClaimDetails]  
 Description		: Procedure used to Update the existing ClaimDetails (When Click on Update Button in Claim Screen popup)  
 Input Parameter	: @LoginUserId,@ClaimId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@ApprovedBy,@ApprovedAmount,  
						@ApproverComments,@ClaimStatusId,@TVP_AttachmentDetails  
 Output Parameters	: @Status,@Message  
 Author				: Prakash.P 
 Created on			: 01-11-2023  
 Version			: 1.0   
 Comment			: 1. Procedure will used to Update the ClaimDetails have the columns of   
							 ClaimDate   AS @ClaimDate  
							 ,ClaimTypeId  AS @ClaimTypeId  
							 ,ClaimAmount  AS @ClaimAmount  
							 ,ClaimDescription AS @ClaimDescription  
							 ,RequestedBy  AS @RequestedBy  
							 ,ApprovedBy   AS @ApprovedBy  
							 ,ApprovedAmount  AS @ApprovedAmount  
							 ,ApproverComments AS @ApproverComments  
							 ,ClaimStatusId  AS @ClaimStatusId  
							 ,CompanyId   AS  @CompanyId  
							 ,UpdatedBy   AS  @EmployeeId  
							 ,UpdatedDate  AS  GETDATE() for the given ClaimId.  
					  2.Procedure Will Delete and insert the AttachmentDetails.  
					  3.Then return the output Parameter values as @Status = 1 and @Message = 'The ClaimDetails are Updated Successfully'.  
=============================================================================================================================================*/  
CREATE   PROCEDURE [dbo].[USP_UpdateClaimDetails]  
(  
	@LoginUserId				INT  
	,@ClaimId					INT  
	,@ClaimDate					DATE  
	,@ClaimTypeId				TINYINT  
	,@RequestedBy				INT  
	,@ClaimDescription			NVARCHAR(2000)  
	,@ClaimAmount				NUMERIC(11,2)  
	,@ApprovedBy				INT  
	,@ApprovedAmount			NUMERIC(11,2)			= NULL
	,@ApproverComments			NVARCHAR(2000)
	,@ClaimStatusId				TINYINT
	,@TVP_AttachmentDetails		TVP_AttachmentDetails	READONLY  
	,@Status					BIT						OUT   
	,@Message					NVARCHAR(500)			OUT  
)  
AS  
BEGIN  
	SET NOCOUNT ON;  
  
	DECLARE @CompanyId		TINYINT  
			,@UserGroupId	TINYINT;

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]  
	WHERE	EmployeeId = @LoginUserId; 

	BEGIN TRY  
		BEGIN TRAN    
		   UPDATE	[dbo].[ClaimDetails]  
		   SET		ClaimDate			= @ClaimDate     
					,ClaimTypeId		= @ClaimTypeId    
					,ClaimAmount		= @ClaimAmount    
					,ClaimDescription	= @ClaimDescription   
					,RequestedBy		= @RequestedBy    
					,ApprovedBy			= @ApprovedBy    
					,ApprovedAmount		= @ApprovedAmount   
					,ApproverComments	= @ApproverComments   
					,ClaimStatusId		= @ClaimStatusId    
					,Updatedby			= @LoginUserId   
					,UpdatedDate		= GETDATE()  
		   WHERE	ClaimId				= @ClaimId   
		   AND		CompanyId			= @CompanyId;  
  
			MERGE	[dbo].[AttachmentDetails]	AS TARGET  
			USING	@TVP_AttachmentDetails		AS SOURCE  
				ON	TARGET.AttachmentId = SOURCE.AttachmentId    
			WHEN MATCHED THEN  
			UPDATE    
			SET		TARGET.ModuleName			= SOURCE.ModuleName  
					,TARGET.ModuleRefId			= SOURCE.ModuleRefId  
					,TARGET.AttachmentFileName	= SOURCE.AttachmentFileName    
					,TARGET.Updatedby			= @LoginUserId  
					,TARGET.UpdatedDate			= GETDATE()  
			WHEN NOT MATCHED BY Target THEN  
			INSERT	(ModuleName, ModuleRefId, AttachmentFileName, AttachmentFilepath, IsActive, CreatedBy, CreatedDate)  
			VALUES	('Claim'  
					,@ClaimId  
					,SOURCE.AttachmentFileName
					,SOURCE.AttachmentFilepath
					,1
					,@LoginUserId
					,GETDATE())
			WHEN NOT MATCHED BY SOURCE THEN  
			DELETE;  

			IF @ClaimStatusId IN (3, 4)
			BEGIN
				IF (	SELECT	COUNT(1) 
						FROM	[dbo].[NotificationDetails]
						WHERE	NotificationModuleRefId = @ClaimId
						AND		NotificationTypeName = 'Claim'
					) <> 2
				BEGIN						
					INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
								,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
								,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)							
					SELECT	@ClaimId
							,'Claim'
							,1
							,'Employee'
							,CASE WHEN @ClaimStatusId = 3 THEN CONCAT('Dear ',FirstName, ' Your Claim has been approved and the amount is ',N'₹ ',@ApprovedAmount,
																	' please contact our manager to claim the amount.')
								ELSE CONCAT('Dear ',FirstName, ' Your Claim has been rejected and the amount is ',N'₹ ',@ApprovedAmount,
																	' please contact our manager to claim the amount.')
							END
							,3
							,ED.EmployeeId         
							,'Open'
							,'Open'
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
					FROM	[dbo].[ClaimDetails] AS CD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	ED.EmployeeId = CD.RequestedBy			
					WHERE	ClaimId = @ClaimId
					AND		CD.CompanyId = @CompanyId;
				END
			END 
     
		IF @@TRANCOUNT >= 0  
		COMMIT TRAN  

		SELECT	@Status   = 1        
				,@Message = 'ClaimDetails are updated Successfully.';   
				
		IF @ClaimStatusId IN (3, 4)
		BEGIN 
			IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				SELECT	DISTINCT ED.OfficialEmail AS ToMail
						,CASE WHEN @ClaimStatusId = 3 THEN 'Approval of Claim' ELSE 'Rejected of Claim' 
						 END AS [Subject]
						,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
						,'I hope you are doing well.' AS SecondLine
						,CASE WHEN @ClaimStatusId = 3 THEN CONCAT('This is to inform you that your request for Claim on '
								,CONVERT(NVARCHAR(50),@ClaimDate,106),' for ', ClaimTypeName	,'
								, the claim amount is ',@ClaimAmount,' has been approved by {'
								,EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}. The approved amount is '
								,@ApprovedAmount,' and the reason is ', @ApproverComments,'.')
							ELSE CONCAT('This is to inform you that your request for Claim on '
								,CONVERT(NVARCHAR(50),@ClaimDate,106),' for ', ClaimTypeName ,', the claim amount is ',@ClaimAmount,
								' has been Rejected by {', EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}. The reason is ', @ApproverComments,'.')
						END AS ThirdLine
						,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
						,'For any further assistance, feel free to reach out.' AS FifthLine
						,'Thank You.' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN (	SELECT	CD.RequestedBy, CD.ClaimId, EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
									,EmployeeCompanyId
							FROM	[dbo].[ClaimDetails] CD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	CD.ApprovedBy = ED.EmployeeId 
							WHERE	CD.CompanyId = @CompanyId 
							AND		ClaimId = @ClaimId
							) AS COD
					ON	COD.RequestedBy = ED.EmployeeId
				LEFT JOIN [dbo].[ClaimDetails] CD 
					ON	ED.EmployeeId = CD.RequestedBy
				LEFT JOIN [dbo].[ClaimTypeDetails] CTD 
					ON	CD.ClaimTypeId = CTD.ClaimTypeId
				WHERE	ED.EmployeeId = @RequestedBy;
			END 
		END 
	END TRY  
	BEGIN CATCH  
		ROLLBACK TRAN;  
		SELECT	@Status   = 0  
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));  
	END CATCH  
END  
/*==================================================================================================================  
	 DECLARE	@S_Status     BIT  
			   ,@M_Message     NVARCHAR(500)  
			   ,@TVP_AttachmentDetails  TVP_AttachmentDetails;   
  
	 INSERT INTO @TVP_AttachmentDetails ( AttachmentFileName)  
								VALUES ('Claim');  
  
	 EXEC [dbo].[USP_UpdateClaimDetails]	@LoginUserId			= 1  
											,@ClaimId				= 15
											,@ClaimDate				= '2025-01-15'   
											,@ClaimTypeId			= 1  
											,@RequestedBy			= 3  
											,@ClaimDescription		= ' '  
											,@ClaimAmount			= 500.00  
											,@ApprovedBy			= 1  
											,@ApprovedAmount		= 400  
											,@ApproverComments		= 'This is Enough for your Claim Type.'  
											,@ClaimStatusId			= 4
											,@TVP_AttachmentDetails	= @TVP_AttachmentDetails  
											,@Status				= @S_Status  OUT  
											,@Message				= @M_Message OUT;  
  
	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;  
  
	 SELECT *   
	 FROM [dbo].[ClaimDetails]   
	 SELECT *   
	 FROM [dbo].[AttachmentDetails];  
	 SELECT *   
	 FROM [dbo].[ClaimTypeDetails];  
==================================================================================================================*/  
GO
