/*================================================================================================================================  
 Procedure Name		:	[DBO].[USP_UpdateCompanyDetails]
 Description		:	Procedure used to update the CompanyDetails (When Click on Update Button in setting PopupPage)
 Input Parameter	:	UserId, @CompanyId, @CompanyName, @CompanyLogoFileName, @CompanyAddress, @CompanyCity,@CompanyState, 
						@CompanyCountry, @CompanyZipCode, @CompanyContactNumber, @CompanyEmail, @CompanyWebsite,@GSTNumber, @BankName,
						@AccountType, @AccountName, @AccountNumber, @IFSCCode,@IsEmpIdAutomatic,@EmpIdPrefix,@EmpIdStartingFrom				
 Output Parameters	:	@Status, @Message															 
 Author				:	Nithya.M																	  
 Created on			:	26-10-2023	
 Version			:	1.0 
 Comment			:	1.Update the CompanyDetails table have the column of
									CompanyName				AS @CompanyName
									,CompanyLogoFileName	AS @CompanyLogoFileName
									,CompanyAddress			AS @CompanyAddress
									,CompanyCity			AS @CompanyCity
									,CompanyState			AS @CompanyState
									,CompanyCountry			AS @CompanyCountry
									,CompanyZipCode			AS @CompanyZipCode
									,CompanyContactNumber	AS @CompanyContactNumber
									,CompanyEmail			As @CompanyEmail
									,CompanyWebsite			AS @CompanyWebsite
									,GSTNumber				As @GSTNumber
									,BankName				AS @BankName
									,AccountType			AS @AccountType
									,AccountName			As @AccountName
									,AccountNumber			AS @AccountNumber
									,IFSCCode				AS @IFSCCode 
									,UpdatedBy				AS @LoginUserId 
									,UpdatedDate			AS GETDATE() for the given companyId.
						1.1. IF SalaryProcessingDate record is already exists in CompanySettingDetails table then update the CompanySettingDetails as 
									IsEmpIdAutomatic    AS @IsEmpIdAutomatic	
									,EmpIdPrefix		AS @EmpIdPrefix
									,EmpIdStartingFrom	AS @EmpIdStartingFrom
									,UpdatedBy			AS @LoginUserId 
									,UpdatedDate		AS GETDATE()  
							 OR ELSE Insert the CompanySettingDetails table as
									IsEmpIdAutomatic    AS @IsEmpIdAutomatic	
									,EmpIdPrefix		AS @EmpIdPrefix
									,EmpIdStartingFrom	AS @EmpIdStartingFrom
									,CreatedBy			AS @LoginUserId 
									,CreatedDate		AS GETDATE()  
						2.Then return the output Parameters values as @Status = 1 and @Message = 'The CompanyDetails are Updated Successfully'.
================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateCompanyDetails]
(
	@LoginUserId						INT
	,@CompanyId							TINYINT
	,@CompanyName						NVARCHAR(100)
	,@CompanyLogo						NVARCHAR(4000) = Null
	,@CompanyAddress					NVARCHAR(200)
	,@CompanyCity						NVARCHAR(50)
	,@CompanyState						NVARCHAR(50)
	,@CompanyCountry					NVARCHAR(50)
	,@CompanyZipCode					NVARCHAR(50)
	,@CompanyContactNumber				NVARCHAR(100)
	,@CompanyEmail						NVARCHAR(100)
	,@CompanyWebsite					NVARCHAR(100)
	,@GSTNumber							NVARCHAR(100) 
	,@Status							BIT								OUT	
	,@Message							NVARCHAR(500)					OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @ClientId INT;
			

	SELECT	@ClientId = MasterClientId
	FROM	[DBO].[CompanyDetails]
	WHERE	CompanyId = @CompanyId;

	BEGIN TRY
		SELECT	@Status   = 1   
				,@Message = 'Changes Saved Successfully.';  

		BEGIN TRAN  
			--Update the CompanyDetails table for the given companyId.			
			UPDATE	[DBO].[CompanyDetails]
			SET		CompanyName				= @CompanyName
					,CompanyLogo			= CASE	WHEN @CompanyLogo IS NULL THEN CompanyLogo
													ELSE @CompanyLogo 
											   END	
					,CompanyAddress			= @CompanyAddress	
					,CompanyCity			= @CompanyCity
					,CompanyState			= @CompanyState
					,CompanyCountry			= @CompanyCountry
					,CompanyZipCode			= @CompanyZipCode
					,CompanyContactNumber	= @CompanyContactNumber
					,CompanyEmail			= @CompanyEmail
					,CompanyWebsite			= @CompanyWebsite	
					,GSTNumber				= @GSTNumber
					,UpdatedBy				= @LoginUserId 
					,UpdatedDate			= GETDATE()
			WHERE	CompanyId	            = @CompanyId;

			--Update the ClientDetails table in Main TetroPAY database.			
			UPDATE	[TETROPAY].[DBO].[ClientDetails]
			SET		ClientName		= @CompanyName
					,UpdatedBy		= @LoginUserId 
					,UpdatedDate	= GETDATE()
			WHERE	ClientId	    = @ClientId;

			--Update the SignupDetails table in TetroAPPS database.			
			UPDATE	[TETROAPPS].[DBO].[SignupDetails]
			SET		CompanyName		= @CompanyName
					,UpdatedBy		= @LoginUserId 
					,UpdatedDate	= GETDATE()
			WHERE	ProductClientId	= @ClientId;

			IF @@TRANCOUNT > 0
		COMMIT TRAN

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)

	EXEC [DBO].[USP_UpdateCompanyDetails]	@LoginUserId					= 1
											,@CompanyId						= 1
											,@CompanyName					= 'Tetrosoft'
											,@CompanyLogo					= 'Default.jpeg'
											,@CompanyAddress				= '71,Konnadikal T.N.Palayam,Gobi'	
											,@CompanyCity					= 'Gobi'
											,@CompanyState					= 'Tamil Nadu'
											,@CompanyCountry				= 'India'
											,@CompanyZipCode				= '638541'
											,@CompanyContactNumber			= '9566396876'
											,@CompanyEmail					= 'tetrosoft@gmail.com'
											,@CompanyWebsite				= 'www.tetrosoft.co.in'	
											,@GSTNumber						= '4398HRF8REF'
											,@Status						= @S_Status		OUT
											,@Message						= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[CompanyDetails]; 	
	SELECT	*
	FROM	[DBO].[CompanySettingDetails]; 
	SELECT	*
	FROM	[DBO].[CompanyWorkingDayDetails]; 
	SELECT	*
	FROM	[DBO].[EmployeePersonalDetails]; 
