/****** Object:  StoredProcedure [dbo].[USP_UpdateCompensatoryOffDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*========================================================================================================================================================
Procedure Name		:	[dbo].[USP_UpdateCompensatoryOffDetails]
Description			:	Procedure used to Update the existing CompensatoryOffDetails
						  									(When Click On Update button in CompensatoryOff popup)
Input Parameters	:	@LoginUserId, @CompensatoryOffId, @EmployeeId, @CompensatoryOffDate, @IsHalfDay, @NoOfDays
						,@CompensatoryOffDescription, @CompensatoryOffStatusId, @Comments.
Output Parameters	:	@Status,@Message
Author				:	Prakash.P
Created On			:	23-08-2023
Version				:	1.0
Comments			:	1.If the Given CompensatoryOffDate is already Mapped with another CompensatoryOffId, then
						  1.1 Returns the Error msg as @Status = 0 And 
								@Message = "Given CompOffDate is already Exist."
						2. If Not exists, then Update the CompensatoryOffDetails have the columns of
								EmployeeId						AS	@EmployeeId
								,CompensatoryOffDate			AS	@CompensatoryOffDate
								,IsHalfDay						AS	@IsHalfDay
								,NoOfDays						AS	@NoOfDays
								,CompensatoryOffStatusId		AS	@CompensatoryOffStatusId
								,CompensatoryOffDescription		AS	@CompensatoryOffDescription
								,UpdatedBy						AS	@LoginUserId.
						   2.1 Then through the Success message as @Status = 1 and 
									@Message = "CompOffDetails are Updated Successfully."
===========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateCompensatoryOffDetails]
(
	@LoginUserId					INT
	,@CompensatoryOffId				INT
	,@EmployeeId					INT
	,@CompensatoryOffDate			DATE 
	,@IsHalfDay						BIT
	,@NoOfDays						INT
	,@CompensatoryOffDescription	NVARCHAR(200)
	,@CompensatoryOffStatusId		TINYINT
	,@Comments						NVARCHAR(1000)
	,@Status						BIT				OUT	
	,@Message						NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--IF EXISTS (SELECT 1 FROM [dbo].[CompensatoryOffDetails] WHERE CompensatoryOffId <> @CompensatoryOffId AND CompensatoryOffDate = @CompensatoryOffDate AND EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
		--BEGIN
		--	SELECT	@Status		= 0 
		--			,@Message	= 'Given CompOffDate is already Exist.';
		--	RETURN;
		--END
		--ELSE
		BEGIN
			BEGIN TRAN
				UPDATE	[dbo].[CompensatoryOffDetails]
				SET		EmployeeId					= @EmployeeId
						,CompensatoryOffDate		= @CompensatoryOffDate
						,IsHalfDay					= @IsHalfDay
						,NoOfDays					= CASE WHEN @IsHalfDay = 1 THEN 0.5 ELSE 1 END
						,CompensatoryOffDescription	= @CompensatoryOffDescription
						,CompensatoryOffStatusId	= @CompensatoryOffStatusId
						,Comments					= @Comments
						,Updatedby					= @LoginUserId
						,UpdatedDate				= GETDATE()		
				WHERE	CompensatoryOffId			= @CompensatoryOffId
				AND		CompanyId					= @CompanyId;

				IF @CompensatoryOffStatusId IN (3, 4)
				BEGIN
					IF (	SELECT	COUNT(1) 
							FROM	[dbo].[NotificationDetails] 
							WHERE	NotificationModuleRefId = @CompensatoryOffId
							AND		NotificationTypeName = 'CompensatoryOff') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)							
						SELECT	@CompensatoryOffId
								,'CompensatoryOff'
								,1
								,'Employee'
								,CASE WHEN @CompensatoryOffStatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your CompOff request has been approved on ' 
												,CONVERT(NVARCHAR(30),CD.CompensatoryOffDate,106)) 
										ELSE CONCAT('Dear ', ED.FirstName, ', Your CompOff request has been rejected on ' 
												,CONVERT(NVARCHAR(30),CD.CompensatoryOffDate,106))
								END
								,3
								,ED.EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[CompensatoryOffDetails] AS CD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = CD.EmployeeId			
						WHERE	CompensatoryOffId = @CompensatoryOffId;
					END
				END 

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	 @Status  = 1   
					,@Message = 'CompOffDetails are Updated Successfully.';  

			IF @CompensatoryOffStatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @CompensatoryOffStatusId = 3 THEN 'Approval of CompOff' ELSE 'Rejected of CompOff' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @CompensatoryOffStatusId = 3 THEN CONCAT('This is to inform you that your request for CompOff on '
									,CONVERT(NVARCHAR(50),@CompensatoryOffDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for CompOff on '
									,CONVERT(NVARCHAR(50),@CompensatoryOffDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}. The reason is ', @Comments,'.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	COD.EmployeeId, COD.CompensatoryOffId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId
								FROM	[dbo].[CompensatoryOffDetails] COD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	COD.Updatedby = ED.EmployeeId 
								WHERE	COD.CompanyId = @CompanyId 
								AND		CompensatoryOffId = @CompensatoryOffId
								) AS COD
						ON	COD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END
	END TRY  
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateCompensatoryOffDetails]	@LoginUserId					= 1
													,@EmployeeId					= 3
													,@CompensatoryOffId				= 23
													,@CompensatoryOffDate			= '2025-01-12'
													,@IsHalfDay						= 0
													,@NoOfDays						= 1
													,@CompensatoryOffStatusId		= 4
													,@CompensatoryOffDescription	= ' '
													,@Comments						= 'Yeah i am reject your CompOff'
													,@Status						= @S_Status		OUT
													,@Message						= @M_Message	OUT;												 
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[CompensatoryOffDetails];
	SELECT	* 
	FROM	[dbo].[EmployeeDetails];
=================================================================================================================================*/
GO
