/*=======================================================================================================================================================
 Procedure Name		:   [dbo].[USP_UpdateEmployeeCheckListMappingDetails]
 Description		:	Procedure used to Update the EmployeeCheckListMappingDetails
											(When Click on the update button in Check List Tabl in Resignation screen)
 Input Parameter	:	@LoginUserId, @ResignationId				
 Output Parameters	:	@Status, @Message									
 Author				:	Prakash.P
 Created on			:	24-01-2025
 Version			:	1.0 
 Comment			:	1. Update the EmployeeCheckListMappingDetails For the Given @ResignationId
						2. Then return the output parameter values @Status = 1 & @Message = NULL.									
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateEmployeeCheckListMappingDetails]
(	
	@LoginUserId							INT
	,@TVP_EmployeeCheckListMappingDetails	TVP_EmployeeCheckListMappingDetails	READONLY
	,@Status								BIT				OUT	
	,@Message								NVARCHAR(500)	OUT
)	
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		MERGE	[dbo].[EmployeeCheckListMappingDetails]	AS TARGET
		USING	@TVP_EmployeeCheckListMappingDetails	AS SOURCE
			ON	TARGET.EmployeeCheckListMappingId = SOURCE.EmployeeCheckListMappingId
		WHEN MATCHED THEN 
		UPDATE 
		SET		TARGET.ApproverEmployeeId	=	SOURCE.ApproverEmployeeId	
				,TARGET.CheckListId			=	SOURCE.CheckListId
				,TARGET.CheckListStatusId	=	SOURCE.CheckListStatusId
				,TARGET.CheckListComments	=	SOURCE.CheckListComments
				,TARGET.UpdatedBy			=	@LoginUserId
				,TARGET.UpdatedDate			=	GETDATE()
		WHEN NOT MATCHED BY TARGET THEN 
		INSERT	(ResignationId, ApproverEmployeeId, CheckListId, CheckListStatusId, CheckListComments, CreatedBy)
		VALUES	(SOURCE.ResignationId
				,SOURCE.ApproverEmployeeId	
				,SOURCE.CheckListId
				,SOURCE.CheckListStatusId
				,SOURCE.CheckListComments
				,@LoginUserId)
		WHEN NOT MATCHED BY SOURCE THEN 
		DELETE;

		SELECT	 @Status   = 1 
				,@Message  = 'Check Status Updated Successfully.';	
	END TRY
	BEGIN CATCH
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH 
END
