/*=================================================================================================================================================
 Procedure Name		:	[dbo].[USP_UpdateEmployeeClientLocationMappingDetails]
 Description		:	Procedure used to update EmployeeClientLocationMappingDetails.
																(When Click on toggle button Employee Not null block)
 Input Parameter	:	@LoginUserId, @EmployeeId, @TVP_EmployeeClientLocationMappingDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	14-12-2024
 Version			:	1.0 
 Comment			:	1. Update the EmployeeClientLocationMappingDetails for the given @EmployeeId and 
							@TVP_EmployeeClientLocationMappingDetails.
						2.Then return the output Parameters values as @Status = 1 and @Message = NULL.
=======================================================================================================================================================*/
CREATE    	PROCEDURE [dbo].[USP_UpdateEmployeeClientLocationMappingDetails]
(
	@LoginUserId									INT
	,@EmployeeId									INT 
	,@TVP_EmployeeClientLocationMappingDetails		TVP_EmployeeClientLocationMappingDetails	READONLY	
	,@Status										BIT											OUT	
	,@Message										NVARCHAR(500)								OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	-- Declare the Variables.
    DECLARE  @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	DROP TABLE IF EXISTS TVP_EmployeeClientLocationMappingDetails;
	CREATE TABLE TVP_EmployeeClientLocationMappingDetails
	(
		EmployeeClientLocationMappingId		INT
		,EmployeeId							INT
		,ClientLocationId					TINYINT
		,[Status]							BIT
		,IsActive							BIT
		,CreatedBy							INT
		,CreatedDate						DATETIME
		,UpdatedBy							INT
		,UpdatedDate						DATETIME
	)

	INSERT INTO TVP_EmployeeClientLocationMappingDetails(EmployeeClientLocationMappingId, ClientLocationId
				,Status, CreatedBy, CreatedDate)
	SELECT		EmployeeClientLocationMappingId, ClientLocationId, [Status], @LoginUserId, GETDATE()
	FROM		@TVP_EmployeeClientLocationMappingDetails;
	
	BEGIN TRY
		BEGIN TRAN 
			MERGE	[dbo].[EmployeeClientLocationMappingDetails]		AS TARGET 
			USING	@TVP_EmployeeClientLocationMappingDetails			AS SOURCE
				ON	TARGET.EmployeeClientLocationMappingId = SOURCE.EmployeeClientLocationMappingId
				AND TARGET.EmployeeId = @EmployeeId
			WHEN MATCHED THEN
				UPDATE	
				SET		TARGET.EmployeeId							=	@EmployeeId
						,TARGET.ClientLocationId					=	SOURCE.ClientLocationId
						,TARGET.[Status]							=	SOURCE.[Status]
						,TARGET.UpdatedBy							=	@LoginUserId
						,TARGET.UpdatedDate							=	GETDATE()
			WHEN NOT MATCHED THEN
				INSERT (EmployeeId, ClientLocationId, [Status], CreatedBy, CreatedDate)
				VALUES	(@EmployeeId
						,SOURCE.ClientLocationId
						,SOURCE.[Status]
						,@LoginUserId
						,GETDATE())
			WHEN NOT MATCHED BY SOURCE AND TARGET.EmployeeId = @EmployeeId THEN 
			DELETE;

		IF @@TRANCOUNT > 0
		COMMIT TRAN 

		SELECT	@Status		= 1
				,@Message	= 'Changes Saved Successfully.';
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status   = 0
			   ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
