										,UpdatedDate				AS GETDATE() for the given EmployeeId.
							1.1 Then through the Output parameter @Status = 1 & @Message =  'The EmployeeExperienceDetails are Updated Successfully.'			
						2. OR Else Insert Into the EmployeeExperienceDetails table have the columns of	
										CompanyName 				AS @CompanyName 		 
										,Location					AS @Location			 
										,Designation				AS @Designation		 
										,PeriodFrom 				AS @PeriodFrom 		 
										,PeriodTo					AS @PeriodTo 
										,EmployeeId					AS @EmployeeId
										,CreatedBy					AS @LoginUserId	
										,CreatedDate				AS GETDATE()
							2.1 Then through the Output parameter @Status = 1 & @Message = 'The New EmployeeExperienceDetails have been Created Successfully.'
==============================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_UpdateEmployeeExperienceDetails]
(	
	@LoginUserId				INT
	,@EmployeeId				INT
	,@EmployeeExperienceId		TINYINT
	,@CompanyName 				NVARCHAR(100)	
	,@Location					NVARCHAR(100)	
	,@Designation				NVARCHAR(100)	
	,@PeriodFrom 				DATETIME		
	,@PeriodTo					DATETIME	
	,@IsPresent					BIT
	,@Status					BIT				OUT
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;	

	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId  = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		BEGIN TRAN  
			IF EXISTS (SELECT 1 FROM [dbo].[EmployeeExperienceDetails] WHERE EmployeeId = @EmployeeId  AND   EmployeeExperienceId = @EmployeeExperienceId)
			--If EXIST, then update the [EmployeeExperienceDetails] 
			BEGIN
				SELECT	@Status   = 1
						,@Message = 'Changes Saved Successfully.';

				UPDATE	[dbo].[EmployeeExperienceDetails]
				SET		CompanyName 	   = @CompanyName 	
						,[Location]		   = @Location		
						,Designation	   = @Designation	
						,PeriodFrom 	   = @PeriodFrom 	
						,PeriodTo		   = @PeriodTo	
						,IsPresent		   = @IsPresent
						,Updatedby		   = @LoginUserId
						,UpdatedDate       = GETDATE()
				WHERE   EmployeeId         = @EmployeeId
				AND     EmployeeExperienceId = @EmployeeExperienceId;
			END	
			ELSE 
			BEGIN
				SELECT	@Status		= 1
						,@Message	=  'Record added successfully.'

				--If NOT EXIST, then insert the EmployeeExperienceDetails for the new Employee,Then through the success Message as @Status = 1 And @Message = "The New EmployeeExperienceDetails have been Created Successfully".
				INSERT INTO [dbo].[EmployeeExperienceDetails](CompanyName, [Location], Designation, PeriodFrom, PeriodTo,IsPresent ,EmployeeId, CreatedBy ,CreatedDate)
				VALUES		(@CompanyName 	
							,@Location		
							,@Designation	
							,@PeriodFrom 	
							,@PeriodTo	
							,@IsPresent
							,@EmployeeId
							,@LoginUserId
							,GETDATE());
			END 
		IF @@TRANCOUNT > 0
		COMMIT TRAN

	END TRY
	BEGIN CATCH 
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message   = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
