/*===========================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_UpdateEmployeeShiftMappingDetails]
 Description		:	Procedure Used to Update the Existing EmployeeShiftMappingDetails 
																	(When click on Update button in Shift Grid)
 Input Parameter	:	@LoginUserId, @EmployeeShiftMappingId, @DepartmentId, @ShiftId, @IsWeekly, @StartDate
						,@EndDate, @Description 
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-08-2024
 Version			:	1.0 
 Comment			:   1. Procedure will update EmployeeShiftMappingDetails table have the columns of 
								DepartmentId		AS @DepartmentId
								,EmployeeId			AS @EmployeeId
								,ShiftId			AS @ShiftId
								,IsWeekly			AS @IsWeekly
								,StartDate			AS @StartDate
								,EndDate			AS @EndDate
								,Description		AS @Description
								,CreatedBy			AS @LoginUserId
								,CreatedDate		AS GETDATE() for the Given @EmployeeId.
						2 Then return the output Parameters values as @Status = 1 & @Message = 'Changes Saved Successfully.'.
============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateEmployeeShiftMappingDetails]
(
	@LoginUserId					INT
	,@EmployeeShiftMappingId		INT			=	NULL
	,@DepartmentId					TINYINT		=	NULL
	,@EmployeeId					INT
	,@ShiftId						INT
	,@IsWeekly						BIT			=	NULL
	,@StartDate						DATETIME	=	NULL
	,@EndDate						DATETIME	=	NULL
	,@CurrentDate					INT
	,@Description					NVARCHAR(500)
	,@Status						BIT				OUT	
	,@Message						NVARCHAR(500)	OUT

)
AS
BEGIN
	SET NOCOUNT ON;

	--DROP TABLE IF EXISTS InPut_123
	--CREATE TABLE InPut_123
	--(
	--	LoginUserId					INT
	--	,EmployeeShiftMappingId		INT	
	--	,DepartmentId				TINYINT		
	--	,EmployeeId					INT
	--	,ShiftId					INT
	--	,IsWeekly					BIT			
	--	,StartDate					DATETIME	
	--	,EndDate					DATETIME	
	--	,CurrentDate				INT
	--	,[Description]				NVARCHAR(500)
	--)

	--INSERT INTO InPut_123(LoginUserId,EmployeeShiftMappingId ,DepartmentId  ,EmployeeId ,ShiftId ,IsWeekly				
	--			,StartDate,EndDate,CurrentDate,[Description])
	--VALUES		(@LoginUserId			
	--			,@EmployeeShiftMappingId
	--			,@DepartmentId			
	--			,@EmployeeId			
	--			,@ShiftId				
	--			,@IsWeekly				
	--			,@StartDate				
	--			,@EndDate				
	--			,@CurrentDate			
	--			,@Description);

	BEGIN TRY
		BEGIN TRAN 		

			SELECT	@DepartmentId = DepartmentId
			FROM	[dbo].[EmployeeDetails]
			WHERE	EmployeeId = @EmployeeId;

			SET @StartDate = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), @CurrentDate);

			DELETE FROM [dbo].[EmployeeShiftMappingDetails]
			WHERE EmployeeId = @EmployeeId
			AND StartDate = @StartDate
			AND EndDate = @StartDate;

			INSERT INTO [dbo].[EmployeeShiftMappingDetails] (DepartmentId, EmployeeId, ShiftId, StartDate
						,EndDate, [Description], CreatedBy, CreatedDate)
			VALUES		(@DepartmentId	
						,@EmployeeId	
						,@ShiftId		
						,@StartDate	
						,@StartDate	
						,@Description	
						,@LoginUserId
						,GETDATE());

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status		= 1   
				,@Message	= 'Changes Saved Successfully.';  
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateEmployeeShiftMappingDetails]	@LoginUserId				= 11		
														,@EmployeeShiftMappingId	= null
														,@DepartmentId				= 4
														,@EmployeeId				= 11
														,@ShiftId					= 13
														,@IsWeekly					= NULL
