														,@Message					= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * FROM [dbo].[EmployeeShiftMappingDetails];
	SELECT * FROM ShiftDetails

	SELECT * FROM InPut_123
=================================================================================================================================*/
