/****** Object:  StoredProcedure [dbo].[USP_UpdateGridStatusDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=======================================================================================================================================
Procedure Name		: [dbo].[USP_UpdateGridStatusDetails]
Description			: Procedure used to Update the exixting AdvanceStatusDetails(When Click On Status DropDown in Advance Screen)
Input Parameters	: @LoginUserId,@LeaveId,@AdvanceStatusId    
Output Parameters	: @Status,@Message
Author				: Tharani.T
Created On			: 11-10-2024
Version				: 1.0
Comments			: 
============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateGridStatusDetails]
(
	@LoginUserId	INT
	,@ModuleName	NVARCHAR(500)
	,@ModuleId		INT
	,@StatusId		INT
	,@Comments		NVARCHAR(1000)
	,@Status		BIT				OUT
	,@Message		NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId			TINYINT
			,@Date				DATE
			,@StartTime			TIME
			,@EndTime			TIME
			,@EmployeeId		INT;

	SELECT @CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY 
		IF @ModuleName ='Regularization'
		BEGIN 
			BEGIN TRAN 
				UPDATE	[dbo].[RegularizationDetails]
				SET		RegularizationStatusId	= @StatusId	
						,Comments				= @Comments
						,UpdatedBy				= @LoginUserId
						,UpdatedDate			= GETDATE()
				WHERE	RegularizationId		= @ModuleId 
				AND		CompanyId				= @CompanyId;

				SELECT	@Date			= [Date]
						,@StartTime		= StartTime	
						,@EndTime		= EndTime	
						,@EmployeeId	= EmployeeId
				FROM	[dbo].[RegularizationDetails]
				WHERE	RegularizationId = @ModuleId
				AND		CompanyId		 = @CompanyId;

				IF @StatusId  = 3
				BEGIN
					DELETE 
					FROM	[dbo].[AttendanceLogDetails] 
					WHERE	EmployeeId = @EmployeeId
					AND		CONVERT(DATE,PunchDate) = CONVERT(DATE,@Date);

					INSERT INTO [dbo].[AttendanceLogDetails](PunchDate, PunchTime, [Status], IsManual, [Description]
								, AttendanceStatusId, EmployeeId, CompanyId, CreatedBy, CreatedDate)
					VALUES		(@Date, @StartTime, 1, 1, NULL, 3, @EmployeeId, @CompanyId, @LoginUserId, GETDATE())
								,(@Date, @EndTime, 0, 1, NULL, 3, @EmployeeId, @CompanyId, @LoginUserId, GETDATE());
				END 

				-- NotificationDetails
			IF @StatusId IN (3, 4)
			BEGIN
				INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
							,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
							,SMS_To, IsAuto, CompanyId, CreatedBy)	                     
				SELECT  @ModuleId
						,'Regularization'
						,1
						,'Employee'
						,CASE WHEN @StatusId = 3 THEN 
							CONCAT('Dear ', ED.FirstName, ', Your Regularization', QUOTENAME(RD.RegularizationId), ' request has been approved on ' 
									,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
								,' To ',
									RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
									, ' for the date of ', CONVERT(NVARCHAR(50),@Date,105),'.')
								ELSE CONCAT('Dear ', ED.FirstName, ', Your Regularization', QUOTENAME(RD.RegularizationId), ' request has been rejected on ' 
									,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
								,' To ',
									RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
									, ' for the date of ', CONVERT(NVARCHAR(50),@Date,105),'.')
								END			
						,3
						,@EmployeeId
						,'Open'
						,'Open'
						,ED.ContactNo
						,1
						,@CompanyId
						,@LoginUserId
				FROM    [dbo].[RegularizationDetails] AS RD
				JOIN    [dbo].[EmployeeDetails] AS ED
					ON  ED.EmployeeId = RD.EmployeeId            
				WHERE   RegularizationId = @ModuleId;
			END

			IF @@TRANCOUNT  > 0
			COMMIT TRAN 

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';
					
			IF @StatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @StatusId = 3 THEN 'Approval of Attendance Regularization' 
								ELSE 'Rejected of Attendance Regularization' END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for attendance regularization for ', CONVERT(NVARCHAR(50),@Date,106)
																				,' has been approved by {', EmployeeName, QUOTENAME(RVD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for attendance regularization for ', CONVERT(NVARCHAR(50),@Date,106)
												,' has been Rejected by {', EmployeeName, QUOTENAME(RVD.EmployeeCompanyId),'}.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	EmployeeDetails ED 
					LEFT JOIN (	SELECT	RD.EmployeeId, RegularizationId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId
								FROM	[dbo].[RegularizationDetails] RD
								JOIN	[dbo].[Employeedetails] ED
									ON	RD.Updatedby = ED.EmployeeId 
								WHERE	RD.CompanyId = @CompanyId 
								AND		RegularizationId = @ModuleId
								) AS RVD
						ON	RVD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 

		END 
		ELSE IF @ModuleName ='Leave'
		BEGIN 
			BEGIN TRAN
				UPDATE	[dbo].[LeaveDetails]
				SET		LeaveStatusId	= @StatusId
						,Comments		= @Comments
						,UpdatedBy		= @LoginUserId
						,UpdatedDate	= GETDATE()
				WHERE	LeaveId			= @ModuleId 
				AND		CompanyId		= @CompanyId;

				IF @StatusId IN (3, 4)
				BEGIN
					--Restrict the number of occurance not more than twice in NotificationDetails table
					IF (	SELECT	COUNT(1) 
							FROM	[dbo].[NotificationDetails] 
							WHERE	NotificationModuleRefId = @ModuleId 
							AND		NotificationTypeName = 'Leave') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
									,MessageTo, DetailedMessage, EmployeeId, SMSStatus, NotificationStatus, SMS_To
									,MessageStatusId, IsAuto, CompanyId, UpdatedBy, UpdatedDate)							
						SELECT	@ModuleId
								,'Leave'
								,1
								,'Employee'
								,CASE WHEN @StatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your Leave request has been approved on ' 
															,CONVERT(NVARCHAR(30),LD.FromDate,105),' to ', CONVERT(NVARCHAR(30),LD.ToDate,105))
									ELSE CONCAT('Dear ', ED.FirstName, ', Your Leave request has been rejected on ' 
															,CONVERT(NVARCHAR(30),LD.FromDate,105),' to ', CONVERT(NVARCHAR(30),LD.ToDate,105))
								END
								,ED.EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,3
								,1
								,@CompanyId
								,@LoginUserId
								,GETDATE()
						FROM	[dbo].[LeaveDetails] AS LD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = LD.EmployeeId			
						WHERE	LeaveId = @ModuleId
						AND		LD.CompanyId = @CompanyId;
					END
				END 
			IF @@TRANCOUNT  > 0
			COMMIT TRAN;

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';
					
			IF @StatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @StatusId = 3 THEN 'Approval of Leave' ELSE 'Rejected of Leave' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for Leave for '
									,CONVERT(NVARCHAR(50),FromDate,106), ' to ', CONVERT(NVARCHAR(50),ToDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for Leave for '
									,CONVERT(NVARCHAR(50),FromDate,106), ' to ',CONVERT(NVARCHAR(50),ToDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	LD.EmployeeId, LD.LeaveId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,FromDate, ToDate
										,EmployeeCompanyId
								FROM	[dbo].[LeaveDetails] LD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	LD.Updatedby = ED.EmployeeId 
								WHERE	LD.CompanyId = @CompanyId 
								AND		LeaveId = @ModuleId
								) AS LD
						ON	LD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END 
		ELSE IF @ModuleName ='Permission'
		BEGIN 
			BEGIN TRAN
				UPDATE	[dbo].[PermissionDetails]
				SET		PermissionStatusId	= @StatusId	
						,Comments			= @Comments
						,UpdatedBy			= @LoginUserId
						,UpdatedDate		= GETDATE()
				WHERE	PermissionId		= @ModuleId 
				AND		CompanyId = @CompanyId;

				IF @StatusId IN (3, 4)
				BEGIN
					IF (SELECT	COUNT(1) FROM [dbo].[NotificationDetails] 
						WHERE	NotificationModuleRefId = @ModuleId
						AND		NotificationTypeName = 'Permission') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)							
						SELECT	@ModuleId
								,'Permission'
								,1
								,'Employee'
								,CASE WHEN @StatusId = 3 THEN 
										CONCAT('Dear ', ED.FirstName, ', Your Permission', QUOTENAME( PD.PermissionId), ' request has been approved on ' 
											,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
										,' To ',
											RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END)
									ELSE CONCAT('Dear ', ED.FirstName, ', Your Permission', QUOTENAME( PD.PermissionId), ' request has been rejected on ' 
											,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
										,' To ',
											RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
											, '. Please Contact our Manager.')
								END 
								,3
								,ED.EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[PermissionDetails] AS PD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = PD.EmployeeId			
						WHERE	PermissionId = @ModuleId;
					END
				END 

			IF @@TRANCOUNT  > 0
			COMMIT TRAN;

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';
	
			IF @StatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @StatusId = 3 THEN 'Approval of Permission' ELSE 'Rejected of Permission' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for Permission '
								,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
								RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
								CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END,' to ',
								RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
								RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
								CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
								,' on ',CONVERT(NVARCHAR(50),PermissionDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for Permission '
									,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END,' to ',
									RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
									,' on ',CONVERT(NVARCHAR(50),PermissionDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}. The reason is ',@Comments)
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	PD.EmployeeId, PD.PermissionId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId, PermissionDate, StartTime, EndTime
								FROM	[dbo].[PermissionDetails] PD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	PD.Updatedby = ED.EmployeeId 
								WHERE	PD.CompanyId = @CompanyId 
								AND		PermissionId = @ModuleId
								) AS LD
						ON	LD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END 
		ELSE IF @ModuleName ='CompensatoryOff'
		BEGIN 
			BEGIN TRAN
				UPDATE	[dbo].[CompensatoryOffDetails]
				SET		CompensatoryOffStatusId	= @StatusId	
						,Comments				= @Comments
						,UpdatedBy				= @LoginUserId
						,UpdatedDate			= GETDATE()
				WHERE	CompensatoryOffId		= @ModuleId 
				AND		CompanyId = @CompanyId;
			
				IF @StatusId IN (3, 4)
				BEGIN
					IF (	SELECT	COUNT(1) 
							FROM	[dbo].[NotificationDetails] 
							WHERE	NotificationModuleRefId = @ModuleId
							AND		NotificationTypeName = 'CompensatoryOff') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)							
						SELECT	@ModuleId
								,'CompensatoryOff'
								,1
								,'Employee'
								,CASE WHEN @StatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your CompOff request has been approved on ' 
												,CONVERT(NVARCHAR(30),CD.CompensatoryOffDate,106)) 
										ELSE CONCAT('Dear ', ED.FirstName, ', Your CompOff request has been rejected on ' 
												,CONVERT(NVARCHAR(30),CD.CompensatoryOffDate,106))
								END
								,3
								,ED.EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[CompensatoryOffDetails] AS CD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = CD.EmployeeId			
						WHERE	CompensatoryOffId = @ModuleId;
					END
				END 
				
			IF @@TRANCOUNT  >= 0
			COMMIT TRAN;

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';

			IF @StatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @StatusId = 3 THEN 'Approval of CompOff' ELSE 'Rejected of CompOff' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for CompOff on '
									,CONVERT(NVARCHAR(50),CompensatoryOffDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for CompOff on '
									,CONVERT(NVARCHAR(50),CompensatoryOffDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(COD.EmployeeCompanyId),'}. The reason is ', @Comments,'.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	COD.EmployeeId, COD.CompensatoryOffId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId, CompensatoryOffDate
								FROM	[dbo].[CompensatoryOffDetails] COD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	COD.Updatedby = ED.EmployeeId 
								WHERE	COD.CompanyId = @CompanyId 
								AND		CompensatoryOffId = @ModuleId
								) AS COD
						ON	COD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END 
		ELSE IF @ModuleName ='OverTime'
		BEGIN 
			UPDATE	[dbo].[OverTimeDetails]
			SET		OverTimeStatusId	= @StatusId	
					,Comments			= @Comments
					,UpdatedBy			= @LoginUserId
					,UpdatedDate		= GETDATE()
			WHERE	OverTimeId			= @ModuleId 
			AND		CompanyId = @CompanyId;
		END 
		ELSE IF @ModuleName ='Advance'
		BEGIN 
			BEGIN TRAN
				UPDATE	[dbo].[AdvanceDetails]
				SET		AdvanceStatusId	= @StatusId	
						,Comments		= @Comments
						,UpdatedBy		= @LoginUserId
						,UpdatedDate	= GETDATE()
				WHERE	AdvanceId		= @ModuleId  
				AND		CompanyId		= @CompanyId;
			
				IF @StatusId IN (3, 4)
				BEGIN
					IF (SELECT COUNT(1) FROM [dbo].[NotificationDetails] WHERE	NotificationModuleRefId = @ModuleId
						AND	 NotificationTypeName = 'Advance') <> 2
					BEGIN		
						INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName, IsInternal
									,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
									,SMS_To, IsAuto, CompanyId, CreatedBy)							
						SELECT	@ModuleId
								,'Advance'
								,1			
								,'Employee'
								,CASE WHEN @StatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your Advance', 
										' request has been approved on ', CONVERT(NVARCHAR(30),AD.UpdatedDate,106),
											'. Please Contact our Manager.') 
									ELSE CONCAT('Dear ', ED.FirstName, ', Your Advance', 
										' request has been rejected on ', CONVERT(NVARCHAR(30),AD.UpdatedDate,106),
											'. Please Contact our Manager.') 
								END 
								,3
								,ED.EmployeeId  
								,'Open'
								,'Open'       
								,ED.ContactNo	
								,1
								,@CompanyId
								,@LoginUserId	 
						FROM	[dbo].[AdvanceDetails] AS AD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = AD.EmployeeId			
						WHERE	AdvanceId = @ModuleId 
						AND		AD.CompanyId = @CompanyId;
					END
				END
				
			IF @@TRANCOUNT  > 0
			COMMIT TRAN;

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';
					
		IF @StatusId IN (3, 4)
		BEGIN 
			IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				SELECT	DISTINCT ED.OfficialEmail AS ToMail
						,CASE WHEN @StatusId = 3 THEN 'Approval of Advance' ELSE 'Rejected of Advance' 
						END AS [Subject]
						,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
						,'I hope you are doing well.' AS SecondLine
						,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for Advance on '
								,CONVERT(NVARCHAR(50),AdvanceDate,106),' and the advance amount of ', AdvanceAmount
								,' has been approved by {', EmployeeName, QUOTENAME(AD.EmployeeCompanyId),'}.')
							ELSE CONCAT('This is to inform you that your request for Advance on '
								,CONVERT(NVARCHAR(50),AdvanceDate,106),' and the advance amount of ', AdvanceAmount
								,' has been Rejected by {', EmployeeName, QUOTENAME(AD.EmployeeCompanyId),'}.')
						END AS ThirdLine
						,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
						,'For any further assistance, feel free to reach out.' AS FifthLine
						,'Thank You.' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN (	SELECT	AD.EmployeeId, AD.AdvanceId, EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
									,EmployeeCompanyId, AdvanceDate, AdvanceAmount
							FROM	[dbo].[AdvanceDetails] AD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	AD.Updatedby = ED.EmployeeId 
							WHERE	AD.CompanyId = @CompanyId 
							AND		AdvanceId = @ModuleId
							) AS AD
					ON	AD.EmployeeId = ED.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END
		END 
		ELSE IF @ModuleName ='Loan'
		BEGIN
			BEGIN TRAN 
				UPDATE	[dbo].[LoanDetails]
				SET		LoanStatusId	= @StatusId
						,Comments		= @Comments
						,UpdatedBy		= @LoginUserId
						,UpdatedDate	= GETDATE()
				WHERE	LoanId			= @ModuleId
				AND		CompanyId		= @CompanyId;

				DECLARE	@Start			INT		= 1
						,@End			INT		
						,@LoanDate		DATE
						,@LoanDueDate	DATE
						,@NoOfDues		INT
						,@DueAmount		NUMERIC(11,2)

				SELECT	@NoOfDues = NoOfDues
						,@LoanDate = LoanDate
						,@DueAmount = DueAmount
				FROM	[dbo].[LoanDetails]
				WHERE	LoanId = @ModuleId;

				SET @End = @NoOfDues;

				DROP TABLE IF EXISTS #TempTable;
				CREATE TABLE #TempTable
				(
					Id		INT		IDENTITY(1,1),
					[Date]	DATE	
				);

				SET @LoanDueDate = DATEFROMPARTS(YEAR(@LoanDate), MONTH(@LoanDate), 1);

				WHILE @Start <= @End
				BEGIN 
					INSERT INTO #TempTable([Date])
					VALUES (DATEADD(MONTH, @Start, @LoanDueDate))

					SET @Start = @Start + 1
				END 
				 
				IF NOT EXISTS (	SELECT 1 FROM [dbo].[LoanDueDetails] WHERE @StatusId = 3 AND LoanId = @ModuleId)
				BEGIN 
					INSERT INTO [dbo].[LoanDueDetails](LoanDueDate, LoanDueAmount, Isclosed, LoanId, CreatedBy)
					SELECT		[Date], @DueAmount, 0, @ModuleId, @LoginUserId
					FROM	#TempTable;
				END 
				
			IF @StatusId IN (3, 4)
			BEGIN
				IF (SELECT COUNT(1)	FROM [dbo].[NotificationDetails] WHERE NotificationModuleRefId = @ModuleId
					AND	NotificationTypeName = 'Loan') <> 2
				BEGIN		
					INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName, IsInternal
								,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
								,SMS_To, IsAuto, CompanyId, CreatedBy)							
					SELECT	@ModuleId
							,'Loan'
							,1
							,'Employee'
							,CASE WHEN @StatusId = 3 THEN CONCAT('Dear, ',  ED.FirstName, ' Your Loan request has been approved on ' 
										,CONVERT(NVARCHAR(30),LD.LoanDate,106) , ' .Please Contact Our Manager.')
								ELSE CONCAT('Dear, ',  ED.FirstName, ' Your Loan request has been rejected on ' 
								,CONVERT(NVARCHAR(30),LD.LoanDate,106) , ' .Please Contact Our Manager.')
							END
							,3
							,ED.EmployeeId  
							,'Open'
							,'Open'       
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
					FROM	[dbo].[LoanDetails] AS LD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	LD.EmployeeId = ED.EmployeeId			
					WHERE	LoanId = @ModuleId
					AND		LD.CompanyId = @CompanyId;
				END
			END
			IF @@TRANCOUNT  > 0
			COMMIT TRAN;

			SELECT	@Status		= 1
					,@Message	= 'Status Updated Successfully.';

			IF @StatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @StatusId = 3 THEN 'Approval of Loan' ELSE 'Rejected of Loan' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @StatusId = 3 THEN CONCAT('This is to inform you that your request for Loan on '
									,CONVERT(NVARCHAR(50),LoanDate,106),' and the Loan amount of ', LoanAmount
									,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for Loan on '
									,CONVERT(NVARCHAR(50),LoanDate,106),' and the Loan amount of ', LoanAmount
									,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId)
									,'}, and the reason is ', @Comments,'.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	LD.EmployeeId, LD.LoanId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId, LoanDate, LoanAmount
								FROM	[dbo].[LoanDetails] LD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	LD.Updatedby = ED.EmployeeId 
								WHERE	LD.CompanyId = @CompanyId 
								AND		LoanId = @ModuleId
								) AS LD
						ON	LD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END
		END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500),ISNULL(ERROR_Message(),''));	
	END	CATCH

END
