/****** Object:  StoredProcedure [dbo].[USP_UpdateHolidayDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*================================================================================================================================================================
 Procedure Name		:	[USP_UpdateHolidaydetails]
 Description		:	Procedure used to Update the Existing Holidaydetails for given @HolidayId(When Click on Update Button in HolidayInfo PopupPage) 
 Input Parameter	:	@LoginUserId,@HolidayId,@HolidayDate,@HolidayName,@IsOptional.
 Output Parameters	:	@Status, @Message
 Author				:	Tetrosoft
 Created on			:	30-05-2023
 Version			:	1.0 
 Comment			:	1. Check the entered HolidayId is Exists or Not?
							1.1 If NOT Exists, returns the Error msg as Status = 0 And Message = 'Given HolidayId Is Not Available'
						2. Check the Given HolidayDate is already exists or not with another HolidayId.
							2.1 If Exists, returns the Error msg as Status = 0 And Message = "Entered HolidayDate is already Existed with another HolidayId"
						3. Check the Given HoildayName is already exists or not with another HolidayId.
							3.1 If Exists, returns the Error msg as Status = 0 And Message = "Entered HolidayName is already Existed with another HolidayId"
				        4. If Not Exists, 
						    4.1. Update The HolidayDetails With the Columns @HolidayDate As HolidayDate
																			,@HolidayName As HolidayName
																			,@IsOptional AS IsOptional
																			,UpdatedBy as @LoginUserId
																			,UpdatedDate as Getdate() for given @HolidayId 
						2.Then return the output Parameters values as @Status= 1 and @Message = 'The Given Holiday details are updated Successfully''.
================================================================================================================================================================*/
CREATE     PROCEDURE [dbo].[USP_UpdateHolidayDetails]
(
	@LoginUserId	 INT
	,@HolidayId      TINYINT
	,@HolidayDate    DATETIME      
	,@HolidayName    NVARCHAR(100) 
	,@IsOptional	 BIT			
	,@Status		 BIT			OUT	
	,@Message		 NVARCHAR(500)	OUT
)
AS 
BEGIN
	SET NOCOUNT ON;	

    DECLARE  @CompanyId TINYINT;
	
	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status   = 1   
				,@Message =  'Changes Saved Successfully.';

		--If NOT Exists, returns the Error msg as Status = 0 And Message = "Given HolidayId was not Exists."		
		IF NOT EXISTS (SELECT 1 FROM [dbo].[HolidayDetails] WHERE HolidayId = @HolidayId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Given HolidayId Is Not Available'
			RETURN;
		END
		--If  Given HolidayDate is already exists In the HolidayDetails Table, returns the Error msg as Status = 0 And Message = "Entered HolidayDate was already Existed with another HolidayId"
		ELSE IF EXISTS (SELECT 1 FROM [dbo].[HolidayDetails] WHERE HolidayId <> @HolidayId AND HolidayDate = @HolidayDate AND CompanyId = @CompanyId )
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Entered HolidayDate is already Existed with another HolidayId'
			RETURN;
		END
		--If  Given HolidayName is already exists In the HolidayDetails Table, returns the Error msg as Status = 0 And Message = "Entered HolidayName was already Existed with another HolidayId"
		ELSE IF EXISTS (SELECT 1 FROM [dbo].[HolidayDetails] WHERE HolidayId <> @HolidayId AND HolidayName = @HolidayName AND CompanyId = @CompanyId )
		BEGIN
			SELECT	@Status   = 0
					,@Message = 'Entered HolidayName is already Existed with another HolidayId'
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN 
				--Update Holidaydetails
				UPDATE	[dbo].[HolidayDetails]
				SET		HolidayDate     = @HolidayDate   
						,HolidayName    = @HolidayName   
						,IsOptional	    = @IsOptional	
						,Updatedby		= @LoginUserId 
						,UpdatedDate	= GETDATE()
				WHERE	HolidayId		= @HolidayId AND CompanyId = @CompanyId;
		
			IF @@TRANCOUNT > 0
			COMMIT TRAN
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)
				   									  
	EXEC [dbo].[USP_UpdateHolidayDetails] @LoginUserId	  = 1
										  ,@HolidayId     = 1
										  ,@HolidayDate   = '2023-06-29'
										  ,@HolidayName   = 'Bakrid'
										  ,@IsOptional	  = 1
										  ,@Status		  = @S_Status	 OUT
										  ,@Message		  = @M_Message   OUT;	   
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[HolidayDetails];	
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateInterviewScheduleCandidateDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateInterviewScheduleCandidateDetails]
 Description		:	Procedure used to Update the new InterviewScheduleCandidateDetails 
														(When Click on Update Button in InterviewSchedule PopupPage)
 Input Parameter	:	@LoginUserId, @CandidateId, @InterviewType, @InterviewDate, @StartTime, @TotalDuration
						,@InterviewLocationId, @Evaluation, @EvaluatorId, @InterviewScheduleStatusId
						,@InterviewDescription.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @CandidateId is already Exists, then 
							1.1 Logic is update the InterviewScheduleCandidateDetails table have the columns of 
										InterviewType				AS	@InterviewType
										,InterviewDate				AS	@InterviewDate
										,StartTime					AS	@StartTime
										,TotalDuration				AS	@TotalDuration
										,InterviewLocationId		AS	@InterviewLocationId
										,Evaluation					AS	@Evaluation
										,EvaluatorId				AS	@EvaluatorId
										,InterviewScheduleStatusId	AS	@InterviewScheduleStatusId
										,InterviewDescription		AS	@InterviewDescription
										,UpdatedBy					AS	@LoginUserId
										,UpdatedDate				AS	GETDATE()
							1.2 Through the Error message as @Status = 0 & 
									@Message = 'Given InterviewScheduleDetails are Updated Successfully.'
						2. If the Given @CandidateId is Not Exists, then 
							2.1 Logic is insert into InterviewScheduleCandidateDetails table have the columns of 
									InterviewType				AS	@InterviewType
									,InterviewDate				AS	@InterviewDate
									,StartTime					AS	@StartTime
									,TotalDuration				AS	@TotalDuration
									,InterviewLocationId		AS	@InterviewLocationId
									,Evaluation					AS	@Evaluation
									,EvaluatorId				AS	@EvaluatorId
									,InterviewScheduleStatusId	AS	@InterviewScheduleStatusId
									,InterviewDescription		AS	@InterviewDescription
									,CreatedBy					AS	@LoginUserId
							2.2 Then return the output parameter values @Status = 1 & 
									@Message = 'New InterviewScheduleDetails are Added Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateInterviewScheduleCandidateDetails]
(
	@LoginUserId										INT		
	,@CandidateId										INT	
	,@CandidateStatusId									TINYINT
	,@TVP_InterviewScheduleCandidateDetails				TVP_InterviewScheduleCandidateDetails			READONLY
	,@TVP_InterviewLevelMainInterviewerMappingDetails	TVP_InterviewLevelMainInterviewerMappingDetails	READONLY
	,@TVP_InterviewLevelSubInterviewerMappingDetails	TVP_InterviewLevelSubInterviewerMappingDetails	READONLY
	,@TVP_CandidateDocumentMappingDetails				TVP_CandidateDocumentMappingDetails				READONLY
	,@Status											BIT												OUT	
	,@Message											NVARCHAR(500)									OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY	
		BEGIN TRAN
			IF (SELECT COUNT(1) FROM @TVP_InterviewScheduleCandidateDetails) > 0 AND @CandidateStatusId = 1
			BEGIN 
				UPDATE	[dbo].[CandidateDetails]
				SET		CandidateStatusId	= 2
						,UpdatedBy			= @LoginUserId
						,UpdatedDate		= GETDATE()
				WHERE	CandidateId			= @CandidateId;
			END 
			ELSE 
			BEGIN 
				UPDATE	[dbo].[CandidateDetails]
				SET		CandidateStatusId	= @CandidateStatusId
						,UpdatedBy			= @LoginUserId
						,UpdatedDate		= GETDATE()
				WHERE	CandidateId			= @CandidateId;
			END 

			DELETE 
			FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails]
			WHERE	CandidateId = @CandidateId;
			
			DELETE 
			FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails]
			WHERE	CandidateId = @CandidateId;

			DROP TABLE IF EXISTS #OutPut
			CREATE TABLE #OutPut
			(
				RowNumber						INT
				,InterviewScheduleCandidateId	INT
			);

			MERGE	[dbo].[InterviewScheduleCandidateDetails]	AS TARGET  
			USING	@TVP_InterviewScheduleCandidateDetails		AS SOURCE  
				ON	TARGET.InterviewScheduleCandidateId = SOURCE.InterviewScheduleCandidateId   
				AND TARGET.CandidateId = @CandidateId
			WHEN MATCHED THEN  
			UPDATE    
			SET		TARGET.InterviewType					=	SOURCE.InterviewType			
					,TARGET.InterviewDate					=	SOURCE.InterviewDate			
					,TARGET.StartTime						=	SOURCE.StartTime				
					,TARGET.TotalDuration					=	SOURCE.TotalDuration			
					,TARGET.InterviewLocationId				=	SOURCE.InterviewLocationId	
					,TARGET.InterviewURL					=	SOURCE.InterviewURL		
					,TARGET.Evaluation						=	SOURCE.Evaluation				
					,TARGET.EvaluatorId						=	SOURCE.EvaluatorId				
					,TARGET.InterviewScheduleStatusId		=	SOURCE.InterviewScheduleStatusId
					,TARGET.InterviewDescription			=	SOURCE.InterviewDescription	
					,TARGET.ApproverComments				=	SOURCE.ApproverComments
					,TARGET.IsEmailSended					=	SOURCE.IsEmailSended
					,TARGET.RowNumber						=	SOURCE.RowNumber
					,TARGET.UpdatedBy						=	@LoginUserId
					,TARGET.UpdatedDate						=	GETDATE()
			WHEN NOT MATCHED BY TARGET THEN  
			INSERT	(InterviewType, InterviewDate, StartTime, TotalDuration, InterviewLocationId, InterviewURL
					,Evaluation, EvaluatorId, InterviewScheduleStatusId, InterviewDescription, ApproverComments
					,CandidateId, IsEmailSended, RowNumber, CreatedBy)  
			VALUES	(SOURCE.InterviewType			
					 ,SOURCE.InterviewDate			
					 ,SOURCE.StartTime				
					 ,SOURCE.TotalDuration			
					 ,SOURCE.InterviewLocationId
					 ,SOURCE.InterviewURL
					 ,SOURCE.Evaluation				
					 ,SOURCE.EvaluatorId				
					 ,SOURCE.InterviewScheduleStatusId
					 ,SOURCE.InterviewDescription	
					 ,SOURCE.ApproverComments
					 ,@CandidateId
					 ,SOURCE.IsEmailSended
					 ,SOURCE.RowNumber
					 ,@LoginUserId)
			WHEN NOT MATCHED BY SOURCE AND TARGET.CandidateId = @CandidateId THEN  
			DELETE
			OUTPUT	SOURCE.RowNumber, INSERTED.InterviewScheduleCandidateId
			INTO	#OutPut(RowNumber, InterviewScheduleCandidateId);

			INSERT INTO InterviewLevelMainInterviewerMappingDetails (InterviewScheduleCandidateId, MainInterviewerId
						,CandidateId, RowNumber, CreatedBy)
			SELECT		OT.InterviewScheduleCandidateId, TVP.MainInterviewerId, @CandidateId, TVP.RowNumber
						,@LoginUserId
			FROM		@TVP_InterviewLevelMainInterviewerMappingDetails AS TVP
			JOIN		#OutPut AS OT
				ON	TVP.RowNumber = OT.RowNumber;
				
			INSERT INTO InterviewLevelSubInterviewerMappingDetails(InterviewScheduleCandidateId, SubInterviewerId,
                        CandidateId, RowNumber, CreatedBy)
			SELECT		OT.InterviewScheduleCandidateId, TVP.SubInterviewerId, @CandidateId, TVP.RowNumber
						,@LoginUserId
			FROM		@TVP_InterviewLevelSubInterviewerMappingDetails AS TVP
			JOIN		#OutPut AS OT
				ON	TVP.RowNumber = OT.RowNumber;

			IF @CandidateStatusId = 9
			BEGIN
				MERGE	[dbo].[CandidateDocumentMappingDetails]	AS TARGET  
				USING	@TVP_CandidateDocumentMappingDetails	AS SOURCE  
					ON	TARGET.CandidateDocumentMappingId = SOURCE.CandidateDocumentMappingId   
					AND TARGET.CandidateId = @CandidateId
				WHEN MATCHED THEN  
				UPDATE    
				SET		TARGET.InterviewDocumentId				=	SOURCE.InterviewDocumentId			
						,TARGET.DucumentFileName				=	SOURCE.DucumentFileName			
						,TARGET.DucumentFilePath				=	SOURCE.DucumentFilePath	
						,TARGET.IsActive						=	SOURCE.IsActive
						,TARGET.UpdatedBy						=	@LoginUserId
						,TARGET.UpdatedDate						=	GETDATE()
				WHEN NOT MATCHED BY TARGET THEN  
				INSERT	(InterviewDocumentId, DucumentFileName, DucumentFilePath, CandidateId, IsActive, CreatedBy)  
				VALUES	(SOURCE.InterviewDocumentId			
						,SOURCE.DucumentFileName			
						,SOURCE.DucumentFilePath	
						,@CandidateId		
						,SOURCE.IsActive
						,@LoginUserId)
				WHEN NOT MATCHED BY SOURCE AND TARGET.CandidateId = @CandidateId THEN  
				DELETE;
			END 

			DECLARE @Email					NVARCHAR(100)
					,@ContactNumber			NVARCHAR(200)
					,@EmployeeCompanyId		NVARCHAR(50)
					,@EmployeeId			INT
					,@ClientId				INT;
					
			SELECT	@Email = Email
					,@ContactNumber = ContactNumber
			FROM	[dbo].[CandidateDetails] CD
			WHERE	CandidateId = @CandidateId
			AND		CD.CompanyId = @CompanyId;

			SELECT	@EmployeeCompanyId = CONCAT(EmpIdPrefix, (SUBSTRING(EmployeeCompanyId, LEN(EmpIdPrefix) + 1, LEN(EmployeeCompanyId) ) + 1))
			FROM	CompanySettingDetails CSD
			JOIN	(			
						SELECT	EmployeeCompanyId
								,EmployeeId
								,CompanyId
								,ROW_NUMBER() OVER(ORDER BY EmployeeId DESC) AS RN
						FROM	[dbo].[EmployeeDetails]
						WHERE	CompanyId = 1
					) AS CD
				ON	CSD.CompanyId = CD.CompanyId
			WHERE	RN = 1;

			IF @CandidateStatusId = 10
			BEGIN 
				IF NOT EXISTS (SELECT 1 FROM [dbo].[EmployeeDetails] WHERE OfficialEmail = @Email AND ContactNo = @ContactNumber AND CompanyId = @CompanyId)
				BEGIN 
					INSERT INTO [dbo].[EmployeeDetails](EmployeeCompanyId, FirstName, LastName, OfficialEmail
								,[Password], [Address], City, [State], Country, Zipcode, ContactNo, DateOfJoining
								,BranchId, DepartmentId, DesignationId, ReportingPersonId, UserGroupId, IsLoginUser
								,EmployeeTypeId, GradeTypeId, EmployeeStatusId, CandidateId, CompanyId, CreatedBy)
					SELECT	@EmployeeCompanyId, FirstName, LastName, Email, 'Login@123', [Address], City, [State]
							,Country, Zipcode, ContactNumber, ExpJoiningDate, HiringLocationId, DepartmentId
							,DesignationId, ReportingPersonId, 3, 1, EmploymentTypeId, GradeTypeId
							,EmployeeStatusId, @CandidateId, @CompanyId, @LoginUserId
					FROM	[dbo].[CandidateDetails] CD
					JOIN	[dbo].[JobCreationDetails] JCD
						ON	CD.JobCreationId = JCD.JobCreationId
					WHERE	CandidateId = @CandidateId;

					SELECT	@EmployeeId = SCOPE_IDENTITY();

					INSERT INTO [dbo].[EmployeePersonalDetails](GenderId, DateOfBirth, ReligionId, MaritalStatusId
							,Nationality, PersonalEmail, AadharNo, PANNo, PassportNo, PassportExpDate
							,EmployeeId, CreatedBy)
					SELECT	GenderId, DateOfBirth, ReligionId, MaritalStatusId
							,Nationality, PersonalEmail, AadharNo, PANNo, PassportNo, PassportExpDate
							,@EmployeeId, @LoginUserId
					FROM	[dbo].[CandidateDetails] CD
					WHERE	CandidateId = @CandidateId;

					INSERT INTO [dbo].[EmployeeSalaryDetails](PayTypeId, PaymentTypeId, CTC, EmployeeId, CreatedBy)
					SELECT	PayTypeId, PaymentTypeId, ExpectCTC, @EmployeeId, @LoginUserId
					FROM	[dbo].[CandidateDetails] CD
					WHERE	CandidateId = @CandidateId;

					INSERT INTO [dbo].[EmployeePFDetails](UANNumber, PFNumber, EmployeeId, CreatedBy)
					SELECT	UANNumber, PFNumber, @EmployeeId, @LoginUserId
					FROM	[dbo].[CandidateDetails] CD
					WHERE	CandidateId = @CandidateId;

					SELECT	@ClientId = SUBSTRING(DB_NAME(), CHARINDEX('_', DB_NAME()) + 1, LEN(DB_NAME()));

					INSERT INTO [TetroPAY].[dbo].[UserDetails](FirstName, LastName, UserPhoneNumber, UserEmail
								,UserPassword, UserGroupId, ClientId, ChildEmployeeId, CompanyId, CreatedBy)
					SELECT	FirstName, LastName, ContactNumber, Email, 'Login@123', 3, @ClientId, @EmployeeId
							,@CompanyId, @LoginUserId
					FROM	[dbo].[CandidateDetails] CD
				END 
			END 

		IF @@TRANCOUNT >= 0  
		COMMIT TRAN  

		SELECT	@Status   = 1        
				,@Message = 'InterviewScheduleDetails are updated Successfully.';   
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status											BIT
			,@M_Message											NVARCHAR(500)
			,@TVP_InterviewScheduleCandidateDetails				TVP_InterviewScheduleCandidateDetails
			,@TVP_InterviewLevelMainInterviewerMappingDetails	TVP_InterviewLevelMainInterviewerMappingDetails
			,@TVP_InterviewLevelSubInterviewerMappingDetails	TVP_InterviewLevelSubInterviewerMappingDetails
			,@TVP_CandidateDocumentMappingDetails				TVP_CandidateDocumentMappingDetails

	INSERT INTO @TVP_InterviewScheduleCandidateDetails(InterviewScheduleCandidateId, InterviewType, InterviewDate
				,StartTime, TotalDuration, InterviewLocationId, InterviewURL, Evaluation, EvaluatorId
				,InterviewScheduleStatusId, InterviewDescription, ApproverComments, RowNumber)
	VALUES		(36, 'Face to Face', '2025-01-28', '10:00', '02:00', 2, NULL, 4.5, 1, 1
				, 'Yeah we conduction the exam', 'yeah he is performents is ok.', 1)
				,(37, 'Virtual', '2025-01-30', '13:00', '02:30', NULL,'www.tetrosoft.com',3, 3, 3
					,'Yeah we conduction the Second level', 'yeah he is performents is poor', 2);
				
	INSERT INTO @TVP_InterviewLevelMainInterviewerMappingDetails(MainInterviewerId, RowNumber)
	VALUES		(1, 1), (2, 1), (3, 2);
	
	INSERT INTO @TVP_InterviewLevelSubInterviewerMappingDetails(SubInterviewerId, RowNumber)
	VALUES		(4, 1), (5, 1), (6, 1), (10, 2);

	INSERT INTO @TVP_CandidateDocumentMappingDetails(CandidateDocumentMappingId, InterviewDocumentId, DucumentFileName
				,DucumentFilePath, IsActive)
	VALUES		(171, 1, 'DucumentFileName_1','DucumentFilePath_1', 1)
				,(172, 2, 'DucumentFileName_2','DucumentFilePath_2', 1)
				,(173, 3, 'DucumentFileName_3','DucumentFilePath_3', 1)
				,(174, 4, 'DucumentFileName_4','DucumentFilePath_4', 1)
				,(175, 5, 'DucumentFileName_5','DucumentFilePath_5', 1)
				,(176, 6, 'DucumentFileName_6','DucumentFilePath_6', 1)
				,(177, 7, 'DucumentFileName_7','DucumentFilePath_7', 1)
				,(178, 8, 'DucumentFileName_8','DucumentFilePath_8', 1)
				,(179, 9, 'DucumentFileName_9','DucumentFilePath_9', 1)
				,(180, 10, 'DucumentFileName_10','DucumentFilePath_10', 1);

	EXEC [dbo].[USP_UpdateInterviewScheduleCandidateDetails]	@LoginUserId										= 1
																,@CandidateId										= 1
																,@CandidateStatusId									= 10
																,@TVP_InterviewScheduleCandidateDetails				= @TVP_InterviewScheduleCandidateDetails
																,@TVP_InterviewLevelMainInterviewerMappingDetails	= @TVP_InterviewLevelMainInterviewerMappingDetails
																,@TVP_InterviewLevelSubInterviewerMappingDetails	= @TVP_InterviewLevelSubInterviewerMappingDetails
																,@TVP_CandidateDocumentMappingDetails				= @TVP_CandidateDocumentMappingDetails
																,@Status											= @S_Status		OUT
																,@Message											= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT	*
	FROM	[dbo].[CandidateDetails]
	WHERE	CandidateId = 1;
	SELECT	*
	FROM	[dbo].[InterviewScheduleCandidateDetails]
	WHERE	CandidateId = 1;
	SELECT	*
	FROM	[dbo].[InterviewLevelMainInterviewerMappingDetails]
	WHERE	CandidateId = 1;
	SELECT	*
	FROM	[dbo].[InterviewLevelSubInterviewerMappingDetails]
	WHERE	CandidateId = 1;
	SELECT	*
	FROM	[dbo].[CandidateDocumentMappingDetails]
	WHERE	CandidateId = 1;

	SELECT * FROM InterviewStatusDetails
	SELECT * FROM InterviewDocumentDetails
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateJobCreationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateJobCreationDetails]
 Description		:	Procedure used to Update the JobCreationDetails 
																(When Click on Update Button in JobCreation PopupPage)
 Input Parameter	:	@LoginUserId, @JobCreationId, @JobId, @JobPostType, @JobName, @JobCategoryId, @EmploymentTypeId
						,@DepartmentId, @PrimarySkill, @SecondarySkill, @HiringLocationId, @HiringManagerId
						,@NoOfOpening, @OpeningDate, @ExpiryDate, @SalaryMinRange, @SalaryMaxRange, @MinExperience
						,@MaxExperience, @JobCreationStatusId, @JobCreationDescription, @JobCreationSkillSet.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	20-01-2025
 Version			:	1.0 
 Comment			:	1. If the Given @JobId is already Exists, then 
							1.1 Through the Error message as @Status = 0 & @Message = 'Given JobId is already Exist.'
						2. If the Given @JobId is Not Exists, then 
							2.1 Logic will Update the JobCreationDetails table have the Columns of 
									JobId					AS	@JobId
									,JobPostType			AS	@JobPostType
									,JobName				AS	@JobName
									,JobCategoryId			AS	@JobCategoryId
									,EmploymentTypeId		AS	@EmploymentTypeId
									,DepartmentId			AS	@DepartmentId
									,PrimarySkill			AS	@PrimarySkill
									,SecondarySkill			AS	@SecondarySkill
									,HiringLocationId		AS	@HiringLocationId
									,HiringManagerId		AS	@HiringManagerId
									,NoOfOpening			AS	@NoOfOpening
									,OpeningDate			AS	@OpeningDate
									,ExpiryDate				AS	@ExpiryDate
									,SalaryMinRange			AS	@SalaryMinRange
									,SalaryMaxRange			AS	@SalaryMaxRange
									,MinExperience			AS	@MinExperience
									,MaxExperience			AS	@MaxExperience
									,JobCreationStatusId	AS	@JobCreationStatusId
									,JobCreationDescription	AS	@JobCreationDescription
									,JobCreationSkillSet	AS	@JobCreationSkillSet
									,CreatedBy				AS	@LoginUserId for the Given @JobCreationId.
							2.2 Then return the output parameter values @Status = 1 & 
									@Message = 'JobCreationDetails are Updated Successfully.'
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateJobCreationDetails]
(
	@LoginUserId				INT		
	,@JobCreationId				INT
	,@JobId						NVARCHAR(50)
	,@JobPostType				NVARCHAR(50)	
	,@JobName					NVARCHAR(200)	
	,@JobCategoryId				INT				
	,@EmploymentTypeId			TINYINT			
	,@DepartmentId				TINYINT			
	,@PrimarySkill				NVARCHAR(100)	
	,@SecondarySkill			NVARCHAR(100)
	,@HiringLocationId			TINYINT			
	,@HiringManagerId			INT				
	,@NoOfOpening				INT				
	,@OpeningDate				DATE
	,@ExpiryDate				DATE
	,@SalaryMinRange			NUMERIC(11,2)
	,@SalaryMaxRange			NUMERIC(11,2)
	,@MinExperience				NUMERIC(4,2)
	,@MaxExperience				NUMERIC(4,2)
	,@JobCreationStatusId		TINYINT
	,@JobCreationDescription	NVARCHAR(MAX)
	,@JobCreationSkillSet		NVARCHAR(MAX)
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY				
		IF EXISTS( SELECT 1 FROM [dbo].[JobCreationDetails] WHERE JobId = @JobId AND JobCreationId <> @JobCreationId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Given JobId is already Exist.';
			RETURN;
		END
		ELSE 
		BEGIN	
			BEGIN TRAN 
				UPDATE	[dbo].[JobCreationDetails]
				SET		JobId						=	@JobId
						,JobPostType				=	@JobPostType
						,JobName					=	@JobName
						,JobCategoryId				=	@JobCategoryId
						,EmploymentTypeId			=	@EmploymentTypeId
						,DepartmentId				=	@DepartmentId
						,PrimarySkill				=	@PrimarySkill
						,SecondarySkill				=	@SecondarySkill
						,HiringLocationId			=	@HiringLocationId
						,HiringManagerId			=	@HiringManagerId
						,NoOfOpening				=	@NoOfOpening
						,OpeningDate				=	@OpeningDate
						,ExpiryDate					=	@ExpiryDate
						,SalaryMinRange				=	@SalaryMinRange
						,SalaryMaxRange				=	@SalaryMaxRange
						,MinExperience				=	@MinExperience
						,MaxExperience				=	@MaxExperience
						,JobCreationStatusId		=	@JobCreationStatusId
						,JobCreationDescription		=	@JobCreationDescription
						,JobCreationSkillSet		=	@JobCreationSkillSet
						,UpdatedBy					=	@LoginUserId			
						,UpdatedDate				=	GETDATE()
				WHERE	JobCreationId				=	@JobCreationId
				AND		CompanyId					=	@CompanyId;					

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'JobCreationDetails are Updated Successfully.'; 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateJobCreationDetails]	@LoginUserId				= 1
												,@JobCreationId				= 1
												,@JobId						= 'J_102'
												,@JobPostType				= 'External'
												,@JobName					= 'DB Developer'
