												,@EmploymentTypeId			= 2
												,@DepartmentId				= 3
												,@PrimarySkill				= 'DB'
												,@SecondarySkill			= 'Oracle'
												,@HiringLocationId			= 2
												,@HiringManagerId			= 1
												,@NoOfOpening				= 20
												,@OpeningDate				= '2025-01-18'
												,@ExpiryDate				= '2025-02-09'
												,@SalaryMinRange			= 50000
												,@SalaryMaxRange			= 100000
												,@MinExperience				= 3
												,@MaxExperience				= 6
												,@JobCreationStatusId		= 1
												,@JobCreationDescription	= 'A detailed document outlining the responsibilities, qualifications, skills, and other relevant details for a specific role within an organization. Below is a generic' 
												,@JobCreationSkillSet		= 'A detailed document outlining the responsibilities, qualifications, skills, and other relevant details for a specific role within an organization. Below is a generic' 
												,@Status					= @S_Status		OUT
												,@Message					= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	 
	SELECT	*
	FROM	[dbo].[JobCreationDetails];
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateLeaveDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================================
Procedure Name		: [dbo].[USP_UpdateLeaveDetails]
Description			: Procedure used to Update the exixting LeaveDetails(When Click On Update in Leave Screen)
Input Parameters	: @LoginUserId,@EmployeeId,@LeaveId,@LeaveTypeId,@FromDate,@ToDate,@IsHalfDay,@LeaveDescription,@LeaveStatusId    
Output Parameters	: @Status,@Message
Author				: Dharani.M
Created On			: 23-08-2023
Version				: 1.0
Comments			: 1.If the Given FromDate is already Mapped with another LeaveId, then
						  1.1 Returns the Error msg as Status = 0 And Message = "Entered FromDate is already Mapped with another LeaveId"
						  1.2 If Not exists, then Update the LeaveDetails have the columns of
								LeaveTypeId			AS @LeaveTypeId
								,FromDate			AS @FromDate
								,ToDate				AS @ToDate
								,IsHalfDay			AS @IsHalfDay
								,NoOfDays			AS @NoOfDays Using DateDiff FromDate And ToDate
								,RemainingLeaves	AS @RemainingLeaves
								,LeaveDescription	AS @LeaveDescription
								,LeaveStatusId		AS @LeaveStatusId
								,UpdatedBy			AS @EmployeeId
								,UpdatedDate		AS GETDATE() for the given LeaveId.
						   1.3 Then Return the Success msg as @Status = 1 and @Message = "The LeaveDetails Updated Successfully."
==========================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateLeaveDetails]
(
	@LoginUserId			INT
	,@EmployeeId			INT
	,@LeaveId				INT
	,@LeaveTypeId			TINYINT
	,@FromDate				DATE
	,@ToDate				DATE
	,@IsHalfDay				BIT
	,@IsFirstHalf			BIT				= NULL
	,@NoOfDays				NUMERIC(5,2)
	,@LeaveDescription		NVARCHAR(200)
	,@LeaveStatusId			TINYINT
	,@Comments				NVARCHAR(1000)	
	,@Status				BIT				OUT
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId	INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF EXISTS (SELECT	1
					FROM	[dbo].[LeaveDetails]  
					WHERE	LeaveId <> @LeaveId
					AND		EmployeeId = @EmployeeId
					AND		LeaveStatusId IN (1, 2, 3)
					AND		((FromDate = @FromDate AND ToDate = @ToDate)
					OR		(@FromDate BETWEEN FromDate AND ToDate)
					OR		(@ToDate BETWEEN FromDate AND ToDate)
					OR		(FromDate BETWEEN @FromDate AND @ToDate) 
					OR		(ToDate BETWEEN @FromDate AND @ToDate)))
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Entered LeaveDate is already Exists.';
			RETURN;
		END
		ELSE
		BEGIN 
			BEGIN TRAN
				UPDATE	[dbo].[LeaveDetails]
				SET		LeaveTypeId			= @LeaveTypeId
						,FromDate			= @FromDate	
						,ToDate				= @ToDate	
						,IsHalfDay			= @IsHalfDay
						,IsFirstHalf		= @IsFirstHalf
						,NoOfDays			= @NoOfDays
						,LeaveDescription	= @LeaveDescription
						,LeaveStatusId		= @LeaveStatusId 
						,EmployeeId			= @EmployeeId 
						,Comments			= @Comments
						,Updatedby			= @LoginUserId 
						,UpdatedDate  		= GETDATE()
				WHERE	LeaveId				= @LeaveId
				AND		CompanyId			= @CompanyId;

				IF @LeaveStatusId IN (3, 4)
				BEGIN
					--Restrict the number of occurance not more than twice in NotificationDetails table
					IF (	SELECT	COUNT(1) 
							FROM	[dbo].[NotificationDetails] 
							WHERE	NotificationModuleRefId = @LeaveId 
							AND		NotificationTypeName = 'Leave') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
									,MessageTo, DetailedMessage, EmployeeId, SMSStatus, NotificationStatus, SMS_To
									,MessageStatusId, IsAuto, CompanyId, UpdatedBy, UpdatedDate)							
						SELECT	@LeaveId
								,'Leave'
								,1
								,'Employee'
								,CASE WHEN @LeaveStatusId = 3 THEN CONCAT('Dear ', ED.FirstName, ', Your Leave request has been approved on ' 
															,CONVERT(NVARCHAR(30),LD.FromDate,105),' to ', CONVERT(NVARCHAR(30),LD.ToDate,105))
									ELSE CONCAT('Dear ', ED.FirstName, ', Your Leave request has been rejected on ' 
															,CONVERT(NVARCHAR(30),LD.FromDate,105),' to ', CONVERT(NVARCHAR(30),LD.ToDate,105))
								END
								,@EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,3
								,1
								,@CompanyId
								,@LoginUserId
								,GETDATE()
						FROM	[dbo].[LeaveDetails] AS LD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = LD.EmployeeId			
						WHERE	LeaveId = @LeaveId
						AND		LD.CompanyId = @CompanyId;
					END
				END 
				
			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status		= 1   
					,@Message	= 'LeaveDetails are Updated Successfully.';
					
			IF @LeaveStatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @LeaveStatusId = 3 THEN 'Approval of Leave' ELSE 'Rejected of Leave' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @LeaveStatusId = 3 THEN CONCAT('This is to inform you that your request for Leave for '
									,CONVERT(NVARCHAR(50),@FromDate,106), ' to ', CONVERT(NVARCHAR(50),@ToDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for Leave for '
									,CONVERT(NVARCHAR(50),@ToDate,106), ' to ',CONVERT(NVARCHAR(50),@ToDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	LD.EmployeeId, LD.LeaveId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId
								FROM	[dbo].[LeaveDetails] LD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	LD.Updatedby = ED.EmployeeId 
								WHERE	LD.CompanyId = @CompanyId 
								AND		LeaveId = @LeaveId
								) AS LD
						ON	LD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END
	END TRY  
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateLeaveDetails]	@LoginUserId		= 1
										,@EmployeeId		= 3
										,@LeaveId			= 42
										,@LeaveTypeId		= 3
										,@FromDate			= '2025-02-04'
										,@ToDate			= '2025-02-05'
				 						,@IsHalfDay			= 0
										,@IsFirstHalf		= NULL 
										,@NoOfDays			= 2
										,@LeaveStatusId		= 3
										,@LeaveDescription	= ' '
										,@Comments			= 'Nothing to say'
										,@Status			= @S_Status		OUT
										,@Message			= @M_Message	OUT;
												 
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[LeaveDetails];
	SELECT	* 
	FROM	[dbo].[NotificationDetails];

	SELECT * FROM EmployeeDetails
	SELECT	*
	FROM	[dbo].[LeaveStatusDetails];
=================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateleavetypeDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*================================================================================================================================================
 Procedure Name	    :   [USP_UpdateLeavetypeDetails]
 Description		:	Procedure used to UpDate The Leavetypedetails(When Click on Update Button in LeaveType PopupPage)
 Input Parameter	:	@LoginUserId,@LeavetypeId,@Leavetypename,@LeaveCount,@LeavePeriod,@IsCarryForward,@LeaveTypeDescription		
 Output Parameters	:	@Status, @Message
 Author				:	Dharani
 Created on			:	27-11-2023
 Version			:	1.0 
 Comment			:	1.Declare the CompanyId to get CompanyId for Given LoginUserID to use Where Conditions.
						2. Check the Given LeaveTypename is already exists or not?
						     2.1 If Exists,returns the Error msg as Status = 0 And Message = "Entered LeaveTypeName was already Existed with another LeaveTypeId"
							 2.2 If Not exists, Update the LeaveTypedetails for the columns 
										LeaveTypeName			AS @LeaveTypeName
										,LeaveCount				AS @LeaveCount
										,LeavePeriod			AS @LeavePeriod	
										,IsCarryForward			AS @IsCarryForward
										,LeaveTypeDescription	AS @LeaveTypeDescription
										,UpdatedBy				AS LoginUserId
										,UpdatedDate			AS GETDATE() 
							2.3Then Return the Success message as @Status  = 1, @Message = "Updated Successfully."
===================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateleavetypeDetails]
(
	@LoginUserId							INT
	,@LeaveTypeId							TINYINT
	,@LeaveTypeName							NVARCHAR(100)
	,@LeaveTypeDescription					NVARCHAR(200)
	,@TVP_LeaveTypeGradeMappingDetails		TVP_LeaveTypeGradeMappingDetails	READONLY 
	,@Status								BIT									OUT	
	,@Message								NVARCHAR(500)						OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--Logic to get CompanyId for Given LoginUserID to use Where Conditions
	DECLARE @CompanyId TINYINT;
	   
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
        --If Exists, returns the Error Message as Status = 0 And Message = "Entered LeaveTypeName was already Existed with another LeaveTypeId"		
		IF EXISTS(SELECT 1 FROM [dbo].[LeavetypeDetails] WHERE Leavetypename = @Leavetypename AND LeavetypeId <> LeavetypeId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	 @Status  =  0
		 			,@Message = 'Entered Leavetypename was already Existed with another LeavetypeId';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN 			
				--If Not Exists, returns Status = 0 And Message = 'The Leavetypedetails are updated'		
				UPDATE	 [dbo].[Leavetypedetails]
				SET		LeaveTypeName			= @LeaveTypeName
						,LeaveTypeDescription	= @LeaveTypeDescription
						,Updatedby				= @LoginUserId 
						,UpdatedDate  			= GETDATE()
				WHERE	LeavetypeId				= @LeavetypeId 
				AND		CompanyId				= @CompanyId;

				DELETE 
				FROM	[dbo].[LeaveTypeGradeMappingDetails]
				WHERE	LeavetypeId	= @LeavetypeId;
			
				INSERT INTO [dbo].[LeaveTypeGradeMappingDetails](LeaveTypeId, GradeTypeId, LeaveCount, LeavePeriod
							,IsCarryForward, MaxCarryForward, PermissionCount, CreatedBy)
				SELECT		@LeaveTypeId, GradeTypeId, CASE WHEN @LeaveTypeId <> 1 THEN [Count] ELSE NULL END, LeavePeriod, IsCarryForward, MaxCarryForward
							,CASE WHEN	@LeaveTypeId = 1 THEN [Count] ELSE NULL END, @LoginUserId
				FROM		@TVP_LeaveTypeGradeMappingDetails;

			IF @@TRANCOUNT > 0
			COMMIT TRAN

			SELECT	@Status		=  1   
					,@Message	=  'Changes Saved Successfully.';
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status							BIT
		    ,@M_Message							NVARCHAR(500)
			,@TVP_LeaveTypeGradeMappingDetails	TVP_LeaveTypeGradeMappingDetails;

	INSERT INTO @TVP_LeaveTypeGradeMappingDetails(GradeTypeId, Count, LeavePeriod, IsCarryForward, MaxCarryForward)
	VALUES		(1, '03:50', 'Monthly', 1, NULL)
				,(2,'03:00', 'Yearly', 0, NULL);

	EXEC [dbo].[USP_UpdateLeavetypeDetails]	@LoginUserId						=	1
											,@LeaveTypeId						=	1
											,@Leavetypename						=	'Permission'
											,@LeaveTypeDescription				=	'Permission'
											,@TVP_LeaveTypeGradeMappingDetails	=	@TVP_LeaveTypeGradeMappingDetails
  										    ,@Status							=	@S_Status		OUT
										    ,@Message							=	@M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;
	       
	SELECT	*
	FROM	[dbo].[LeavetypeDetails];				       
	SELECT	*
	FROM	[dbo].[LeaveTypeGradeMappingDetails];
=================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateLoanDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*======================================================================================================================================================================
 Procedure Name		:	[dbo].[USP_UpdateLoanDetails]
 Description		:	Procedure used to Update the existing LoanDetails ( When Click on Update Button in Loan Screen popup)
 Input Parameter	:	@LoginUserId,@EmployeeId,@LoanId, @LoanDate, @LoanAmount,@NoOfDue, @DueAmount, @CompletedDue,@PendingAmount,@PendingDues,@LoanStatusId@Description				
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	29-08-2023
 Version			:	1.0 
 Comment			:   1. procedure will used to update the LoanDetails have the columns of 
									LoanDate		AS  @LoanDate		
									,LoanAmount		AS  @LoanAmount	
									,NoOfDues		AS  @NoOfDues		
									,DueAmount		AS  @DueAmount	
									,CompletedDue	AS  @CompletedDue	
									,PendingAmount	AS  @PendingAmount
									,PendingDues	AS  @PendingDues	
									,LoanStatusId	AS  @LoanStatusId	
									,Description	AS  @Description	
									,CompanyId		AS  @CompanyId
									,UpdatedBy		AS  @EmployeeId
									,UpdatedDate	AS  GETDATE() for the given LoanId.
						2.Then return the output Parameter values as @Status = 1 and @Message = 'The LoanDetails are updated Successfully.'
=============================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateLoanDetails]
(
	@LoginUserId		INT
	,@EmployeeId		INT
	,@LoanId			INT
	,@LoanDate			DATETIME	
	,@LoanAmount		NUMERIC(11,2)	
	,@NoOfDues			INT
	,@DueAmount			NUMERIC(11,2)
	,@CompletedDue		INT
	,@PendingAmount		NUMERIC(11,2)
	,@PendingDues		INT
	,@LoanStatusId		TINYINT
	,@Description		NVARCHAR(500)
	,@Comments			NVARCHAR(500)
	,@Status			BIT				OUT
	,@Message			NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;
 
	DECLARE @CompanyId		TINYINT
			,@Start			INT		= 0
			,@End			INT		= @NoOfDues - 1
			,@LoanDueDate	DATE;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	DROP TABLE IF EXISTS #TempTable;
	CREATE TABLE #TempTable
	(
		Id		INT		IDENTITY(1,1),
		[Date]	DATE	
	);

	SET @LoanDueDate = DATEFROMPARTS(YEAR(@LoanDate), MONTH(@LoanDate), 1);
	 
	WHILE @Start <= @End
	BEGIN 
		INSERT INTO #TempTable([Date])
		VALUES		(DATEADD(MONTH, @Start, @LoanDueDate));

		SET @Start = @Start + 1
	END 
	 
	BEGIN TRY
		BEGIN TRAN 
			UPDATE	[dbo].[LoanDetails]
			SET		EmployeeId			=	@EmployeeId
					,LoanDate			=	@LoanDate				
					,LoanAmount			=	@LoanAmount	
					,NoOfDues			=	@NoOfDues		
					,DueAmount			=	@DueAmount	
					,CompletedDue		=	@CompletedDue	
					,PendingAmount		=	@PendingAmount	
					,PendingDues		=	@PendingDues
					,LoanStatusId		=	@LoanStatusId
					,[Description]		=	@Description	
					,Comments			=	@Comments
					,CompanyId			=	@CompanyId
					,UpdatedBy			=	@LoginUserId
					,UpdatedDate		=	GETDATE()
			WHERE	LoanId				=	@LoanId 
			AND		CompanyId			=	@CompanyId;

			IF NOT EXISTS (	SELECT 1 FROM [dbo].[LoanDueDetails] WHERE @LoanStatusId = 3 AND LoanId = @LoanId)
			BEGIN 
				INSERT INTO [dbo].[LoanDueDetails](LoanDueDate, LoanDueAmount, Isclosed, LoanId, CreatedBy)
				SELECT		[Date], @DueAmount, 0, @LoanId, @LoginUserId
				FROM	#TempTable;
			END 

			IF @LoanStatusId IN (3, 4)
			BEGIN
				IF (SELECT COUNT(1)	FROM [dbo].[NotificationDetails] WHERE NotificationModuleRefId = @LoanId
					AND	NotificationTypeName = 'Loan') <> 2
				BEGIN		
					INSERT INTO [dbo].[NotificationDetails](NotificationModuleRefId, NotificationTypeName, IsInternal
								,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
								,SMS_To, IsAuto, CompanyId, CreatedBy)							
					SELECT	@LoanId
							,'Loan'
							,1
							,'Employee'
							,CASE WHEN @LoanStatusId = 3 THEN CONCAT('Dear, ',  ED.FirstName, ' Your Loan request has been approved on ' 
										,CONVERT(NVARCHAR(30),LD.LoanDate,106) , ' .Please Contact Our Manager.')
								ELSE CONCAT('Dear, ',  ED.FirstName, ' Your Loan request has been rejected on ' 
								,CONVERT(NVARCHAR(30),LD.LoanDate,106) , ' .Please Contact Our Manager.')
							END
							,3
							,ED.EmployeeId  
							,'Open'
							,'Open'       
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
					FROM	[dbo].[LoanDetails] AS LD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	LD.EmployeeId = ED.EmployeeId			
					WHERE	LoanId = @LoanId
					AND		LD.CompanyId = @CompanyId;
				END
			END

		IF @@TRANCOUNT >= 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'LoanDetails are Updated Successfully.';
				
		IF @LoanStatusId IN (3, 4)
		BEGIN 
			IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				SELECT	DISTINCT ED.OfficialEmail AS ToMail
						,CASE WHEN @LoanStatusId = 3 THEN 'Approval of Loan' ELSE 'Rejected of Loan' 
						END AS [Subject]
						,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
						,'I hope you are doing well.' AS SecondLine
						,CASE WHEN @LoanStatusId = 3 THEN CONCAT('This is to inform you that your request for Loan on '
								,CONVERT(NVARCHAR(50),@LoanDate,106),' and the Loan amount of ', @LoanAmount
								,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
							ELSE CONCAT('This is to inform you that your request for Loan on '
								,CONVERT(NVARCHAR(50),@LoanDate,106),' and the Loan amount of ', @LoanAmount
								,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId)
								,'}, and the reason is ', @Comments,'.')
						END AS ThirdLine
						,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
						,'For any further assistance, feel free to reach out.' AS FifthLine
						,'Thank You.' AS SixthLine
				FROM	[dbo].[EmployeeDetails] ED 
				LEFT JOIN (	SELECT	LD.EmployeeId, LD.LoanId, EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
									,EmployeeCompanyId
							FROM	[dbo].[LoanDetails] LD
							JOIN	[dbo].[EmployeeDetails] ED
								ON	LD.Updatedby = ED.EmployeeId 
							WHERE	LD.CompanyId = @CompanyId 
							AND		LoanId = @LoanId
							) AS LD
					ON	LD.EmployeeId = ED.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==========================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500)
			  
	EXEC [dbo].[USP_UpdateLoanDetails]	@LoginUserId	= 1
										,@EmployeeId	= 3
										,@LoanId		= 3
										,@LoanDate		= '2025-01-22'	
										,@LoanAmount	= 10000		
										,@NoOfDues		= 5
										,@DueAmount		= 0
										,@CompletedDue	= 0
										,@PendingAmount	= 10000
										,@PendingDues	= 5
										,@LoanStatusId	= 4
										,@Description	= ' ' 
										,@Comments		= 'Nothing'
										,@Status		= @S_Status	 OUT
										,@Message		= @M_Message OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* FROM	[dbo].[LoanDetails];
	SELECT * FROM [dbo].[LeavestatusDetails];
	
	SELECT * FROM [dbo].[NotificationDetails] ORDER BY 
	SELECT	* FROM	[dbo].[EmployeeDetails];
	SELECT	* FROM	[dbo].[LoanDueDetails];
 ============================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateMasterInfoDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*============================================================================================================================================================  
 Procedure Name		:	[USP_UpdateMasterInfoDetails]
 Description		:	Procedure is used to update the MasterInfoDetails (When click on Update button in MasterInfo popup)
 Input Parameter	:	@LoginUserId ,@MasterInfoId	,@ModuleName, @MasterInfoName, @MasterInfoDescription
 Output Parameters	:	@Status, @Message
 Author				:	Nithya.M
 Created on			:	08-08-2023
 Version			:	1.0 
 Comment			:	1.If the Entered DepartmentName is already mapped with another DepartmentId,then
							1.1 Return the output Parameter values as @Status = 0 and ,@Message = 'Entered DepartmentName is already mapped with another DepartmentId'.								
							1.2 If the Entered DepartmentName is not mapped with another DepartmentId,then
							1.3 Logic to update the DepartmentDetails have the columns of 
									DepartmentName			AS @MasterInfoName
									,DepartmentDescription	AS @MasterInfoDescription
									,UpdatedBy				AS @LoginUserId 
									,UpdatedDate			AS GETDATE() for the given DepartmentId.												
							1.4 Then return the output Parameters values as @Status = 1 and @Message = 'The DepartmenDetails are updated'. 
						2.If the Entered DesignationName is already mapped with another DesignationId,then
							2.1 Return the output Parameter values as @Status = 0 and ,@Message = 'Entered DesignationName is already mapped with another DesignationId'.								
							2.2 If the Entered DesignationName is not mapped with another DesignationId,then
							2.3 Logic to update the DesignationDetails have the columns of 
									,DesignationName			AS @MasterInfoName
									,DesignationDescription		AS @MasterInfoDescription
									,UpdatedBy					AS @LoginUserId 
									,Updateddate				AS GETDATE() for the given DesignationId.															
							2.4 Then return the output Parameters values as @Status = 1 and @Message = 'The DesignationDetails are updated'. 
						3. If the Entered ClaimTypename is already mapped with another ClaimTypeId,then
							3.1 Then return the output Parameter values as @Status = 0 and ,@Message = 'Entered ClaimTypeName is already mapped with another ClaimTypeId'.								
							3.2 If the Entered ClaimTypename is not mapped with another ClaimTypeId,then
							3.3 Logic to update the LeaveTypeDetails have the columns of 
									 ClaimTypeName				AS @MasterInfoName
									,ClaimTypeDescription		AS @MasterInfoDescription
									,UpdatedBy					AS @LoginUserId
									,Updateddate				AS GETDATE() for the given ClaimTypeId.															
							3.4 Then return the output Parameters values as @Status = 1 and @Message = 'The ClaimTypeDetails are Updated'.
================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateMasterInfoDetails]
(
	@LoginUserId			INT
	,@MasterInfoId			TINYINT
	,@ModuleName			NVARCHAR(100)
	,@MasterInfoName		NVARCHAR(100)
	,@MasterInfoDescription NVARCHAR(200)
	,@Status				BIT				OUT	
	,@Message				NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId TINYINT;

	--Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions.
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		--IF the given @ModuleName is Department.
		IF @ModuleName = 'Department'
		BEGIN
			--If the Entered DepartmentName is already exist, Then return the output Parameter values as @Status = 0 and ,@Message = 'Entered DepartmentName is already mapped with another DepartmentId'.	
			IF EXISTS(SELECT 1 FROM [dbo].[DepartmentDetails] WHERE DepartmentName = @MasterInfoName AND DepartmentId <> @MasterInfoId AND CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status		= 0
						,@Message	= 'Entered DepartmentName is already mapped with another DepartmentId';
				RETURN;
			END
			ELSE
			BEGIN
				BEGIN TRAN 			
					--Logic to update the given DepartmentDetails.			
					UPDATE [dbo].[DepartmentDetails]
					SET		DepartmentName			= @MasterInfoName	
							,DepartmentDescription	= @MasterInfoDescription
							,UpdatedBy				= @LoginUserId 
							,UpdatedDate			= GETDATE()
					WHERE	DepartmentId			= @MasterInfoId 
					AND		CompanyId				= @CompanyId;

				IF @@TRANCOUNT >0
				COMMIT TRAN

				SELECT	@Status		= 1   
						,@Message	= 'Changes Saved Successfully.';
			END
		END
		--IF the given @ModuleName is Designation
		ELSE IF @ModuleName = 'Designation'
		BEGIN
			--If the Entered Designationname is already exist, Then return the output Parameter values as @Status = 0 and ,@Message = 'Entered DesignationName is already mapped with another DesignationId'.
			IF EXISTS(SELECT 1 FROM [dbo].[DesignationDetails] WHERE DesignationName = @MasterInfoName AND DesignationId <> @MasterInfoId AND CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status		= 0
						,@Message	= 'Entered DesignationName is already mapped with another DesignationId';
				RETURN;
			END
			ELSE
			BEGIN
				BEGIN TRAN 			
					--Logic to update the given DesignationDetails				
					UPDATE [dbo].[DesignationDetails]
					SET		DesignationName			= @MasterInfoName	
							,DesignationDescription	= @MasterInfoDescription
							,UpdatedBy				= @LoginUserId 
							,UpdatedDate			= GETDATE()
					WHERE	DesignationId			= @MasterInfoId 
					AND		CompanyId				= @CompanyId;

				IF @@TRANCOUNT >0
				COMMIT TRAN

				SELECT	@Status		= 1   
						,@Message	= 'Changes Saved Successfully.';
			END
		END
		--IF the given @ModuleName is ClaimType
		ELSE IF @ModuleName = 'ClaimType'
		BEGIN
			--If the Entered LeaveTypename is already mapped, Then return the output Parameter values as @Status = 0 and ,@Message = 'Entered ClaimTypeName is already mapped with another LeaveTypeId'.
			IF EXISTS(SELECT 1 FROM [dbo].[ClaimTypeDetails] WHERE ClaimTypeName = @MasterInfoName AND ClaimTypeId <> @MasterInfoId AND CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status		= 0
						,@Message	= 'Entered ClaimTypeName is already mapped with another ClaimTypeId';
				RETURN;
			END
			ELSE
			BEGIN
				BEGIN TRAN 			
					-- Logic to update the given LeaveTypeDetails				
					UPDATE [dbo].[ClaimTypeDetails]
					SET		 ClaimTypeName			= @MasterInfoName	
							,ClaimTypeDescription	= @MasterInfoDescription
							,UpdatedBy				= @LoginUserId 
							,UpdatedDate			= GETDATE()
					WHERE	ClaimTypeId				= @MasterInfoId 
					AND		CompanyId				= @CompanyId;

				IF @@TRANCOUNT >0
				COMMIT TRAN

				SELECT	@Status		= 1   
						,@Message	= 'Changes Saved Successfully.';
			END
		END
		--IF the given @ModuleName is GradeType
		ELSE IF @ModuleName = 'GradeType'
		BEGIN
			--If the Entered GradeTypename is already mapped, Then return the output Parameter values as @Status = 0 and ,@Message = 'Entered GradeTypeName is already mapped with another GradeType.'.
			IF EXISTS(SELECT 1 FROM [dbo].[GradeTypeDetails] WHERE GradeTypeName = @MasterInfoName AND GradeTypeId <> @MasterInfoId AND CompanyId = @CompanyId)
			BEGIN
				SELECT	@Status		= 0
						,@Message	= 'Entered GradeTypeName is already mapped with another GradeType.';
				RETURN;
			END
			ELSE
			BEGIN
				BEGIN TRAN 			
					-- Logic to update the given GradeTypeDetails				
					UPDATE [dbo].[GradeTypeDetails]
					SET		 GradeTypeName			= @MasterInfoName	
							,GradeTypeDescription	= @MasterInfoDescription
							,UpdatedBy				= @LoginUserId 
							,UpdatedDate			= GETDATE()
					WHERE	GradeTypeId				= @MasterInfoId 
					AND		CompanyId				= @CompanyId;

				IF @@TRANCOUNT >0
				COMMIT TRAN

				SELECT	@Status		= 1   
						,@Message	= 'Changes Saved Successfully.';
			END
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
