/*==============================================================================================================================================================
 Procedure Name	    :	[dbo].[USP_UpdateNoticationCategoryDetails]
 Description		:	Procedure used to retrieve the NoticationCategoryDetails
													(1. When click on Setting in side navigation bar
													 2. When click on Edit option in NoticationCategory master info)
 Input Parameter	:	@LoginUserId, @NoticationCategoryId, @IsActiveStatus
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	01-02-2025
 Version			:	1.0
 Comment			:	1. Logic to update the NoticationCategoryDetails table have the column of
								IsActiveStatus AS @IsActiveStatus for the Given @NoticationCategoryId
=====================================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateNoticationCategoryDetails]
(	
	@LoginUserId				INT
	,@NoticationCategoryId		INT
	,@NoticationCategoryName	NVARCHAR(100)
	,@Email						NVARCHAR(100)
	,@SMTPNumber				NVARCHAR(100)
	,@IsActiveStatus			BIT
	,@IsActive					BIT
	,@Status					BIT				OUT	
	,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE	@CompanyId	TINYINT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF EXISTS (	SELECT	1
					FROM	[dbo].[NoticationCategoryDetails] 
					WHERE	NoticationCategoryId = @NoticationCategoryId 
					AND		CompanyId = @CompanyId)
		BEGIN 
			BEGIN TRAN 
				UPDATE	[dbo].[NoticationCategoryDetails]
				SET		NoticationCategoryName	=	@NoticationCategoryName
						,Email					=	@Email					
						,SMTPNumber				=	@SMTPNumber				
						,IsActiveStatus			=	@IsActiveStatus				
						,IsActive				=	@IsActive			
						,UpdatedBy				=	@LoginUserId
						,UpdatedDate			=	GETDATE()
				WHERE	NoticationCategoryId	=	@NoticationCategoryId
				AND		CompanyId				=	@CompanyId;

			IF @@TRANCOUNT >= 0

			COMMIT TRAN
			SELECT	@Status		= 1 
					,@Message	= 'Changes Saved Successfully.';
		END 
		ELSE 
		BEGIN 
			BEGIN TRAN 
				INSERT INTO [dbo].[NoticationCategoryDetails](NoticationCategoryName, Email, SMTPNumber
							,IsActiveStatus, CompanyId, IsActive, CreatedBy)
				VALUES		(@NoticationCategoryName	
							,@Email						
							,@SMTPNumber				
							,@IsActiveStatus
							,@CompanyId
							,@IsActive	
							,@LoginUserId);

			IF @@TRANCOUNT >= 0

			COMMIT TRAN
			SELECT	@Status		= 1 
					,@Message	= 'Record Added Successfully.';
		END 
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	 @Status   = 0
				,@Message  = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
