/*=============================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateOverTimeDetails]
 Description		:	Procedure Used to Uodate the OverTimeDetails (1.When click on Update Button in OverTime Info Popup Page)
 Input Parameter	:	@LoginUserId, @TVP_OverTimeDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-02-2024
 Version			:	1.0 
 Comments			:	1.Logic will Update the OverTimeDetails have the Columns of 
									EmployeeId		    AS EmployeeId	
									,[Date]			    AS [Date]		
									,StartTime		    AS StartTime	
									,EndTime		    AS EndTime	
									,TotalHours		    AS TotalHours
									,OverTimeStatusId	AS OverTimeStatusId
									,Comments			AS Comments for the Given OverTimeId.
						2. Then return the output parameter values @Status = 1 & @Message = 'Changes Saved Successfully.'
=============================================================================================================================================*/
CREATE PROCEDURE [dbo].[USP_UpdateOverTimeDetails]
(
	@LoginUserId				INT
	,@TVP_OverTimeDetails		TVP_OverTimeDetails		READONLY
	,@Status					BIT						OUT
	,@Message					NVARCHAR(500)			OUT
)
AS
BEGIN 
	SET NOCOUNT ON;

	DECLARE @CompanyId				TINYINT
			,@OverTimeId			INT
			,@OverTimeStatusId		TINYINT
			,@LeaveStatusName		NVARCHAR(50)
			,@UserGroupId		TINYINT;;

	SELECT	@CompanyId = CompanyId
			,@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	SELECT	@LeaveStatusName = LeaveStatusName
	FROM	[dbo].[LeaveStatusDetails]
	WHERE	LeaveStatusId = @OverTimeStatusId;

	BEGIN TRY
		IF @OverTimeStatusId = 3 AND @UserGroupId = 3
		BEGIN
			SELECT @Status   = 0 
				   ,@Message = 'You are not a eligible to approve the "Approved" status.' ;
			RETURN;
		END
		ELSE
		BEGIN TRAN
			MERGE	[dbo].[OverTimeDetails] AS TARGET
			USING	@TVP_OverTimeDetails AS SOURCE
				ON	TARGET.OverTimeId = SOURCE.OverTimeId   
			WHEN MATCHED THEN
			UPDATE 
			SET		TARGET.EmployeeId			= SOURCE.EmployeeId
					,TARGET.[Date]				= SOURCE.[Date]
					,TARGET.IsForeNoon			= SOURCE.IsForeNoon
					,TARGET.StartTime			= SOURCE.StartTime
					,TARGET.EndTime				= SOURCE.EndTime
					,TARGET.TotalHours			= SOURCE.TotalHours
					,TARGET.OverTimeStatusId	= SOURCE.OverTimeStatusId
					,TARGET.Comments			= SOURCE.Comments
					,TARGET.Updatedby			= @LoginUserId
					,TARGET.UpdatedDate			= GETDATE()
			WHEN NOT MATCHED THEN
			INSERT	(EmployeeId, [Date], IsForeNoon, StartTime, EndTime, TotalHours, OverTimeStatusId, Comments
					,CompanyId, CreatedBy, CreatedDate)
			VALUES	(SOURCE.EmployeeId
					,SOURCE.[Date]
					,SOURCE.IsForeNoon
					,SOURCE.StartTime
					,SOURCE.EndTime
					,SOURCE.TotalHours
					,SOURCE.OverTimeStatusId
					,SOURCE.Comments
					,@CompanyId
					,@LoginUserId
					,GETDATE())
			WHEN NOT MATCHED BY SOURCE AND TARGET.OverTimeId IN (SELECT DISTINCT OverTimeId FROM @TVP_OverTimeDetails) THEN
			DELETE;

			IF @LeaveStatusName  = 'Approved'
			BEGIN
				--Restrict the number of occurance not more than twice in NotificationDetails table
				IF (SELECT COUNT(1) FROM [dbo].[NotificationDetails] WHERE NotificationModuleRefId = @OverTimeId) <> 2
				BEGIN						
					INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId,NotificationTypeName,IsInternal, MessageTo, 
								DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus, SMS_To, IsAuto
								,CompanyId, UpdatedBy, UpdatedDate)							
					SELECT	@OverTimeId
							,'OverTime'
							,1
							,'Employee'
							,'Dear ' + ED.EmployeeImage + ED.FirstName+ ', Your Leave'+ QUOTENAME( OTD.OverTimeId) + ' request has been approved on ' 
							+ CAST(OTD.StartTime AS NVARCHAR(20)) +' To' + CAST(OTD.EndTime AS NVARCHAR(20))  + '. Please Contact our Manager.' 
							,2
							,ED.EmployeeId         
							,'Open'
							,'Open'
							,ED.ContactNo
							,1
							,@CompanyId
							,@LoginUserId
							,GETDATE()
					FROM	@TVP_OverTimeDetails AS OTD
					JOIN	[dbo].[EmployeeDetails] AS ED
						ON	ED.EmployeeId = OTD.EmployeeId	
				END
			END 

		IF @@TRANCOUNT >0
		COMMIT TRAN

		SELECT	@Status    = 1   
				,@Message  = 'Changes Saved Successfully.';  
	
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*============================================================================================================================================
	DECLARE	@Status					BIT
			,@Message				NVARCHAR(500)
			,@TVP_OverTimeDetails	TVP_OverTimeDetails

	INSERT INTO @TVP_OverTimeDetails (OverTimeId, EmployeeId, [Date], IsForeNoon,StartTime, EndTime, TotalHours,OverTimeStatusId,Comments)
	VALUES		(80, 4, '2024-08-26', 1,'12:00', '13:00', '1',2,' ')
				,(81, 5, '2024-08-26', 1,'06:00', '08:30', '2',2,' ')
				,(NULL, 6, '2024-03-02', 1,'06:23', '08:12', '2',2,' ');

	EXEC	[dbo].[USP_UpdateOverTimeDetails]	@LoginUserId			= 1	
												,@TVP_OverTimeDetails	= @TVP_OverTimeDetails
												,@Status				=  @Status  OUT
												,@Message				=  @Message OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM OverTimeDetails
	
	SELECT * FROM OverTimeDetails_NewId

	SELECT * FROM EmployeeDetails

=============================================================================================================================================*/

GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateOverTimeDetailsWithCursor]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
