/*=============================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateOverTimeDetails]
 Description		:	Procedure Used to Uodate the OverTimeDetails (1.When click on Update Button in OverTime Info Popup Page)
 Input Parameter	:	@LoginUserId, @TVP_OverTimeDetails
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	29-02-2024
 Version			:	1.0 
 Comments			:	1.Logic will Update the OverTimeDetails have the Columns of 
									EmployeeId		    AS EmployeeId	
									,[Date]			    AS [Date]		
									,StartTime		    AS StartTime	
									,EndTime		    AS EndTime	
									,TotalHours		    AS TotalHours
									,OverTimeStatusId	AS OverTimeStatusId
									,Comments			AS Comments for the Given OverTimeId.
						2. Then return the output parameter values @Status = 1 & @Message = 'Changes Saved Successfully.'
=============================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateOverTimeDetailsWithCursor]
(
    @LoginUserId            INT,
    @TVP_OverTimeDetails    TVP_OverTimeDetails READONLY,
    @Status                 BIT OUT,
    @Message                NVARCHAR(500) OUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Declare cursor to iterate through the TVP
        DECLARE OverTimeCursor CURSOR FOR
        SELECT OverTimeId, EmployeeId, [Date], IsForeNoon, StartTime, EndTime, TotalHours, OverTimeStatusId, Comments
        FROM @TVP_OverTimeDetails;

        -- Variables to hold each row's data
        DECLARE @OverTimeId INT, @EmployeeId INT, @Date DATE, @IsForeNoon BIT;
        DECLARE @StartTime TIME, @EndTime TIME, @TotalHours NVARCHAR(500);
        DECLARE @OverTimeStatusId INT, @Comments NVARCHAR(500);

        -- Open the cursor
        OPEN OverTimeCursor;

        -- Fetch the first row
        FETCH NEXT FROM OverTimeCursor INTO @OverTimeId, @EmployeeId, @Date, @IsForeNoon, @StartTime, @EndTime, @TotalHours, @OverTimeStatusId, @Comments;

        -- Loop through each row in the TVP
        WHILE @@FETCH_STATUS = 0
        BEGIN
            -- If OverTimeId exists, perform update
            IF EXISTS (SELECT 1 FROM dbo.OverTimeDetails WHERE OverTimeId = @OverTimeId)
            BEGIN
                UPDATE dbo.OverTimeDetails
                SET EmployeeId = @EmployeeId,
                    [Date] = @Date,
                    IsForeNoon = @IsForeNoon,
                    StartTime = @StartTime,
                    EndTime = @EndTime,
                    TotalHours = @TotalHours,
                    OverTimeStatusId = @OverTimeStatusId,
                    Comments = @Comments,
                    UpdatedBy = @LoginUserId,
                    UpdatedDate = GETDATE()
                WHERE OverTimeId = @OverTimeId;
            END
            -- If OverTimeId doesn't exist, perform insert
            ELSE
            BEGIN
                INSERT INTO dbo.OverTimeDetails
                (
                    EmployeeId, [Date], IsForeNoon, StartTime, EndTime, TotalHours, 
                    OverTimeStatusId, Comments, CompanyId, CreatedBy, CreatedDate
                )
                VALUES
                (
                    @EmployeeId, @Date, @IsForeNoon, @StartTime, @EndTime, @TotalHours, 
                    @OverTimeStatusId, @Comments, 
                    (SELECT CompanyId FROM dbo.EmployeeDetails WHERE EmployeeId = @LoginUserId), 
                    @LoginUserId, GETDATE()
                );
            END

            -- Fetch the next row from the cursor
            FETCH NEXT FROM OverTimeCursor INTO @OverTimeId, @EmployeeId, @Date, @IsForeNoon, @StartTime, @EndTime, @TotalHours, @OverTimeStatusId, @Comments;
        END;

        -- Close and deallocate the cursor
        CLOSE OverTimeCursor;
        DEALLOCATE OverTimeCursor;

        -- Delete records from the OverTimeDetails table that are not in the TVP
        DELETE FROM dbo.OverTimeDetails
        WHERE NOT EXISTS (
            SELECT 1
            FROM @TVP_OverTimeDetails TVP
            WHERE dbo.OverTimeDetails.OverTimeId = TVP.OverTimeId
        );

        -- Commit the transaction if everything succeeded
        COMMIT TRANSACTION;

        -- Set success status and message
        SELECT @Status = 1, @Message = 'Changes saved successfully.';
    END TRY
    BEGIN CATCH
        -- Rollback transaction in case of error
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- Set error status and message
        SELECT @Status = 0, @Message = ERROR_MESSAGE();
    END CATCH
END
/*============================================================================================================================================
