			,@Message				NVARCHAR(500)
			,@TVP_OverTimeDetails	TVP_OverTimeDetails

	INSERT INTO @TVP_OverTimeDetails (OverTimeId, EmployeeId, [Date], IsForeNoon,StartTime, EndTime, TotalHours,OverTimeStatusId,Comments)
	VALUES		(47, 7, '2024-08-29', 1,'09:00', '12:00', '2',2,' ')
				,(48, 14, '2024-08-01', 1,'12:00', '13:00', '1',2,' ')
				,(NULL, 4, '2024-08-02', 1,'06:00', '08:30', '2',2,' ');

	EXEC	[dbo].[USP_UpdateOverTimeDetails]	@LoginUserId			= 1	
												,@TVP_OverTimeDetails	= @TVP_OverTimeDetails
												,@Status				=  @Status  OUT
												,@Message				=  @Message OUT;

	SELECT @Status AS STATUS, @Message AS MESSAGE;

	SELECT * FROM OverTimeDetails

	SELECT * FROM EmployeeDetails

=============================================================================================================================================*/
