/*============================================================================================================================================  
 Procedure Name		:	[DBO].[USP_UpdatePayrollSettingDetails]
 Description		:	Procedure used to update the PayrollSettingDetails (When Click on Update Button in setting PopupPage)
 Input Parameter	:	@LoginUserId,@CompanyId,@IsPayrollManual,@PayrollDate,@SalaryPaymentMode,@PayslipModel,@Currency,@AdvanceLimit		
 						,@LoanLimit,@TVP_CompanyWorkingDayDetails.
 Output Parameters	:	@Status, @Message
 Author				:	Dharani.M 
 Created on			:	26-10-2023	
 Version			:	1.0 
 Comment			:	1.Update the PayrollSettingDetails table have the column of  
								IsPayrollManual		= @IsPayrollManual	
								,PayrollDate		= @PayrollDate		
								,SalaryPaymentMode	= @SalaryPaymentMode	
								,PayslipModel		= @PayslipModel		
								,Currency			= @Currency			
								,AdvanceLimit		= @AdvanceLimit		
								,LoanLimit			= @LoanLimit		
								,CompanyId			= @CompanyId 
								,UpdatedBy			= @LoginUserId 
								,UpdatedDate		= GETDATE()
							Or Else Insert the PayrollSettingDetails table have the columns of 
								IsPayrollManual		= @IsPayrollManual	
								,PayrollDate		= @PayrollDate		
								,SalaryPaymentMode	= @SalaryPaymentMode
								,PayslipModel		= @PayslipModel		
								,Currency			= @Currency			
								,AdvanceLimit		= @AdvanceLimit		
								,LoanLimit			= @LoanLimit
								,CompanyId			= @CompanyId 
								,CreatedBy			= @LoginUserId 
								,CreatedDate		= GETDATE()		
						2.Use merge statement to update, insert, delete data(s) in CompanyWorkingDayDetails table by using Table valued parameter  
									@TVP_CompanyWorkingDayDetails
						3.Then return the output Parameters values as @Status = 1 and @Message = 'The CompanyDetails are Updated'.
===================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdatePayrollSettingDetails]
(
	@LoginUserId						INT
	,@CompanyId							TINYINT
	,@IsPayrollManual					BIT	
	,@ProcessingMonth					NVARCHAR(50)
	,@PayrollDate						INT				= NULL
	,@PaymentTypeId						TINYINT
	--,@PayslipModel						NVARCHAR(25)
	,@CurrencyId						INT
	,@AdvanceLimit						NVARCHAR(50)
	,@LoanLimit							NVARCHAR(50)
	,@PayTypeId							TINYINT
	,@BankName							NVARCHAR(100)
	,@AccountType						NVARCHAR(100)
	,@AccountName						NVARCHAR(100)
	,@AccountNumber						NVARCHAR(100)	
	,@IFSCCode							NVARCHAR(100) 
	,@IsEmpIdAutomatic					BIT				
	,@EmpIdPrefix						NVARCHAR(50)	= NULL
	,@EmpIdStartingFrom					INT				= NULL
	,@NoticePeriod						INT
	,@TVP_CompanyWorkingDayDetails		TVP_CompanyWorkingDayDetails	READONLY 
	,@Status							BIT								OUT	
	,@Message							NVARCHAR(500)					OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRAN 
			IF EXISTS (SELECT 1 FROM [PayrollSettingDetails] WHERE CompanyId = @CompanyId)
			BEGIN 
				UPDATE	[DBO].[PayrollSettingDetails]
				SET		IsPayrollManual			=	@IsPayrollManual	
						,ProcessingMonth		=	@ProcessingMonth
						,PayrollDate			=	@PayrollDate		
						,PaymentTypeId			=	@PaymentTypeId	
						--,PayslipModel			=	@PayslipModel		
						,CurrencyId				=	@CurrencyId			
						,AdvanceLimit			=	@AdvanceLimit	
						,LoanLimit				=	@LoanLimit		
						,NoticePeriod			=	@NoticePeriod
						,PayTypeId				=	@PayTypeId
						,UpdatedBy				=	@LoginUserId 
						,UpdatedDate			=	GETDATE()
				WHERE	CompanyId				=	@CompanyId;
			END 
			ELSE 
			BEGIN 
				INSERT INTO [DBO].[PayrollsettingDetails] (IsPayrollManual,ProcessingMonth, PayrollDate, PaymentTypeId
							,CurrencyId, AdvanceLimit, LoanLimit, NoticePeriod, PayTypeId, CompanyId
							,CreatedBy, CreatedDate)
				VALUES		(@IsPayrollManual	
							,@ProcessingMonth
							,@PayrollDate		
							,@PaymentTypeId
							--,@PayslipModel		
							,@CurrencyId			
							,@AdvanceLimit		
							,@LoanLimit	
							,@NoticePeriod
							,@PayTypeId
							,@CompanyId
							,@LoginUserId
							,GETDATE())
			END

			IF EXISTS (SELECT 1 FROM [CompanyBankDetails] WHERE CompanyId = @CompanyId)
			BEGIN 
				UPDATE	[dbo].[CompanyBankDetails]
				SET		BankName				=	@BankName
						,AccountType			=	@AccountType
						,AccountName			=	@AccountName
						,AccountNumber			=	@AccountNumber
						,IFSCCode				=	@IFSCCode	
						,UpdatedBy				=	@LoginUserId 
						,UpdatedDate			=	GETDATE()
				WHERE	CompanyId				=	@CompanyId;
			END 
			ELSE 
			BEGIN 
				INSERT INTO [dbo].[CompanyBankDetails](BankName, AccountType, AccountName, AccountNumber, IFSCCode
							,CompanyId, CreatedBy, CreatedDate)
				VALUES		(@BankName
							,@AccountType
							,@AccountName
							,@AccountNumber
							,@IFSCCode
							,@CompanyId
							,@LoginUserId
							,GETDATE())
			END 

			-- If the Given @CompanyId is already EXIST, then Update or ELse Insert into CompanySettingDetails table.
			IF EXISTS (SELECT 1 FROM [CompanySettingDetails] WHERE CompanyId = @CompanyId)
			BEGIN 
				UPDATE	[dbo].[CompanySettingDetails]
				SET		IsEmpIdAutomatic		=	@IsEmpIdAutomatic	
						,EmpIdPrefix			=	@EmpIdPrefix
						,EmpIdStartingFrom		=	@EmpIdStartingFrom
						,UpdatedBy				=	@LoginUserId 
						,UpdatedDate			=	GETDATE()
				WHERE	CompanyId				=	@CompanyId 
			END 
			ELSE 
			BEGIN 
				INSERT INTO [dbo].[CompanySettingDetails](IsEmpIdAutomatic, EmpIdPrefix, EmpIdStartingFrom, CompanyId
							,CreatedBy, CreatedDate)
				VALUES		(@IsEmpIdAutomatic	
							,@EmpIdPrefix		
							,@EmpIdStartingFrom	
							,@CompanyId
							,@LoginUserId
							,GETDATE());
			END

			--Use merge statement to update, insert, delete data(s) in ComoanyWorkingDayDetails table by using Table valued parameter.
			MERGE	[DBO].[CompanyWorkingDayDetails]	AS TARGET
			USING	@TVP_CompanyWorkingDayDetails		AS SOURCE
				ON	TARGET.CompanyWorkingDayId = SOURCE.CompanyWorkingDayId
			AND		TARGET.CompanyId = @CompanyId

			--If the record are matched then update the ComoanyWorkingDayDetails table .
			WHEN MATCHED THEN
			UPDATE
			SET	TARGET.[Day]		       = SOURCE.[Day]         
				,TARGET.[IsWorkingDay]	   = SOURCE.IsWorkingDay	
				,TARGET.Updatedby	       = @LoginUserId
				,TARGET.UpdatedDate	       = GETDATE()

			--If not matched then insert the record in ComoanyWorkingDayDetails table.
			WHEN NOT MATCHED BY TARGET THEN
			INSERT	([Day], IsWorkingDay, CompanyId, CreatedBy, CreatedDate)			
			VALUES	(SOURCE.[Day]           				
					,SOURCE.IsWorkingDay						
					,@CompanyId						
					,@LoginUserId
					,GETDATE())

			--If not matched by source then delete the record in target table.
			WHEN NOT MATCHED BY SOURCE AND TARGET.CompanyId = @CompanyId  THEN
			DELETE;

		IF @@TRANCOUNT > 0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Changes Saved Successfully.';

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*==================================================================================================================
	DECLARE	@S_Status	BIT
			,@M_Message	NVARCHAR(500)
			,@TVP_CompanyWorkingDayDetails TVP_CompanyWorkingDayDetails

	INSERT INTO @TVP_CompanyWorkingDayDetails (CompanyWorkingDayId,day,IsWorkingDay,CompanyId)
    VALUES		(1,'Monday',1,1)
				,(2,'Tuesday',1,1)
				,(3,'Wednesday',1,1)
				,(4,'Thursday',1,1)
				,(5,'Friday',1,1)
				,(6,'Saturday',1,1)
				,(7,'Sunday',1,1);

	EXEC [DBO].[USP_UpdatePayrollSettingDetails]	@LoginUserId					= 1
													,@CompanyId						= 1
													,@IsPayrollManual				= 1
													,@ProcessingMonth				= ''
													,@PayrollDate					= 5
													,@PaymentTypeId					= 1
												--	,@PayslipModel					= 'Advance'
													,@CurrencyId						= 'Indian Rupees(INR)'
													,@AdvanceLimit					= 'Manual'
													,@LoanLimit						= 'Manual'
													,@PayTypeId						=  1
													,@BankName						= ''
													,@AccountType					= ''
													,@AccountName					= ''
													,@AccountNumber					= ''
													,@IFSCCode						= ''
													,@TVP_CompanyWorkingDayDetails	= @TVP_CompanyWorkingDayDetails
													,@Status						= @S_Status		OUT
													,@Message						= @M_Message	OUT;

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	*
	FROM	[DBO].[CompanyDetails]; 
	
	SELECT	*
	FROM	[DBO].[PayrollSettingDetails]; 
	
	SELECT	*
