/*=========================================================================================================================================================
 Procedure Name	    :   [dbo].[USP_UpdatePermissionDetails]
 Description		:	Procedure used to update The PermissionDetails
															(When Click on Update option in Permission popup Screen)
 Input Parameter	:	@LoginUserId, @PermissionId, @EmployeeId, @PermissionDate, @StartTime, @EndTime
						,@PermissionStatusId, @PermissionDescription, @Comments.
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	23-08-2023
 Version			:	1.0 
 Comment			:   1. If the Given @PermissionDate is already Mapped another @PermissionId, then
						     1.1 Through the Error msg as @Status = 0 And 
									@Message = "Given PermissionDate is already Exist."
						2. If Not exists, then Update the PermissionDetails have the column of
								EmployeeId					AS	@EmployeeId
								,PermissionDate				AS	@PermissionDate
								,StartTime					AS	@StartTime
								,EndTime					AS	@EndTime
								,PermissionStatusId			AS	@PermissionStatusId
								,PermissionDescription		AS	@PermissionDescription
								,Comments					AS	@Comments
								,UpdatedBy					AS	@LoginUserId
								,UpdatedDate				AS	GETDATE()
							2.1 Then through the Success msg as @Status = 1 & 
									@Message = "PermissionDetails are Updated Successfully."
===========================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdatePermissionDetails]
(
	 @LoginUserId				INT
	 ,@PermissionId				INT
	 ,@EmployeeId				INT
	 ,@PermissionDate			DATE
	 ,@StartTime				TIME
     ,@EndTime					TIME	
	 ,@PermissionStatusId		TINYINT
	 ,@PermissionDescription	NVARCHAR(400)	
	 ,@Comments					NVARCHAR(1000)
     ,@Status					BIT				OUT	
	 ,@Message					NVARCHAR(500)	OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @CompanyId	INT;

	SELECT	@CompanyId = CompanyId
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
        IF EXISTS (	SELECT	1 FROM [dbo].[PermissionDetails] 
					WHERE	PermissionId <> @PermissionId AND PermissionDate = @PermissionDate 
					AND		EmployeeId = @EmployeeId AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status		= 0
					,@Message	= 'Given PermissionDate is already Exist.';
			RETURN;
		END
		ELSE 
		BEGIN
			BEGIN TRAN
				UPDATE  [dbo].[PermissionDetails]
				SET		EmployeeId				= @EmployeeId
						,PermissionDate			= @PermissionDate
						,StartTime				= @StartTime
						,EndTime				= @EndTime
						,NumberOfHours			= CAST(DATEADD(MINUTE,DATEDIFF(MINUTE, CAST(@StartTime AS DATETIME), CAST(@EndTime AS DATETIME)),'00:00:00') AS TIME)
						,PermissionStatusId		= @PermissionStatusId
						,PermissionDescription	= @PermissionDescription
						,Comments				= @Comments
						,Updatedby				= @LoginUserId 
						,UpdatedDate  			= GETDATE()
				WHERE	PermissionId			= @PermissionId 
				AND		CompanyId				= @CompanyId;

				IF @PermissionStatusId IN (3, 4)
				BEGIN
					IF (SELECT	COUNT(1) FROM [dbo].[NotificationDetails] 
						WHERE	NotificationModuleRefId = @PermissionId
						AND		NotificationTypeName = 'Permission') <> 2
					BEGIN						
						INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName
									,IsInternal, MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus
									,NotificationStatus, SMS_To, IsAuto, CompanyId, CreatedBy)							
						SELECT	@PermissionId
								,'Permission'
								,1
								,'Employee'
								,CASE WHEN @PermissionStatusId = 3 THEN 
										CONCAT('Dear ', ED.FirstName, ', Your Permission', QUOTENAME( PD.PermissionId), ' request has been approved on ' 
											,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
										,' To ',
											RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END)
									ELSE CONCAT('Dear ', ED.FirstName, ', Your Permission', QUOTENAME( PD.PermissionId), ' request has been rejected on ' 
											,RIGHT('0' + CAST(DATEPART(HOUR, CAST(StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
										,' To ',
											RIGHT('0' + CAST(DATEPART(HOUR, CAST(EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
											RIGHT('0' + CAST(DATEPART(MINUTE, CAST(EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
											CASE WHEN DATEPART(HOUR, CAST(EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
											, '. Please Contact our Manager.')
								END 
								,3
								,ED.EmployeeId         
								,'Open'
								,'Open'
								,ED.ContactNo
								,1
								,@CompanyId
								,@LoginUserId
						FROM	[dbo].[PermissionDetails] AS PD
						JOIN	[dbo].[EmployeeDetails] AS ED
							ON	ED.EmployeeId = PD.EmployeeId			
						WHERE	PermissionId = @PermissionId;
					END
				END 

			IF @@TRANCOUNT >= 0
			COMMIT TRAN

			SELECT	@Status		= 1   
					,@Message	= 'PermissionDetails are Updated Successfully.';
					
			IF @PermissionStatusId IN (3, 4)
			BEGIN 
				IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
				BEGIN 
					SELECT	Email AS FromMail
							,SMTPNumber
					FROM	NoticationCategoryDetails
					WHERE	IsActive = 1;

					SELECT	DISTINCT ED.OfficialEmail AS ToMail
							,CASE WHEN @PermissionStatusId = 3 THEN 'Approval of Permission' ELSE 'Rejected of Permission' 
							END AS [Subject]
							,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
							,'I hope you are doing well.' AS SecondLine
							,CASE WHEN @PermissionStatusId = 3 THEN CONCAT('This is to inform you that your request for Permission '
								,RIGHT('0' + CAST(DATEPART(HOUR, CAST(@StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
								RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
								CASE WHEN DATEPART(HOUR, CAST(@StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END,' to ',
								RIGHT('0' + CAST(DATEPART(HOUR, CAST(@EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
								RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
								CASE WHEN DATEPART(HOUR, CAST(@EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
								,' on ',CONVERT(NVARCHAR(50),@PermissionDate,106)
									,' has been approved by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}.')
								ELSE CONCAT('This is to inform you that your request for Permission '
									,RIGHT('0' + CAST(DATEPART(HOUR, CAST(@StartTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@StartTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(@StartTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END,' to ',
									RIGHT('0' + CAST(DATEPART(HOUR, CAST(@EndTime AS TIME)) % 12 AS VARCHAR), 2) + ':' + 
									RIGHT('0' + CAST(DATEPART(MINUTE, CAST(@EndTime AS TIME)) AS VARCHAR), 2) + ' ' +
									CASE WHEN DATEPART(HOUR, CAST(@EndTime AS TIME)) >= 12 THEN 'PM' ELSE 'AM' END
									,' on ',CONVERT(NVARCHAR(50),@PermissionDate,106)
									,' has been Rejected by {', EmployeeName, QUOTENAME(LD.EmployeeCompanyId),'}. The reason is ',@Comments)
							END AS ThirdLine
							,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
							,'For any further assistance, feel free to reach out.' AS FifthLine
							,'Thank You.' AS SixthLine
					FROM	[dbo].[EmployeeDetails] ED 
					LEFT JOIN (	SELECT	PD.EmployeeId, PD.PermissionId, EmployeeImage
										,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
										,EmployeeCompanyId
								FROM	[dbo].[PermissionDetails] PD
								JOIN	[dbo].[EmployeeDetails] ED
									ON	PD.Updatedby = ED.EmployeeId 
								WHERE	PD.CompanyId = @CompanyId 
								AND		PermissionId = @PermissionId
								) AS LD
						ON	LD.EmployeeId = ED.EmployeeId
					WHERE	ED.EmployeeId = @EmployeeId;
				END 
			END 
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdatePermissionDetails]	@LoginUserId	        = 1
												,@EmployeeId		    = 3
												,@PermissionId          = 41
												,@PermissionDate		= '2025-01-04'
												,@StartTime             = '11:20:00'
												,@EndTime		        = '13:00:00'
												,@PermissionStatusId	= 4
												,@PermissionDescription = 'Permission'
												,@Comments				= 'Your Permission has been rejected.'
												,@Status		        = @S_Status	OUT
												,@Message		        = @M_Message	OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[PermissionDetails];
	SELECT *
	FROM	[dbo].[NotificationDetails];

	select * from LeaveStatusDetails
=================================================================================================================================*/
