/****** Object:  StoredProcedure [dbo].[USP_UpdateRegularizationDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==============================================================================================================================================
 Procedure Name	    :   [dbo].[USP_UpdateRegularizationDetails]
 Description		:	Procedure used to UpDate The RegularizationDetails
														(When Click on Update option in Regularization popup Screen)
 Input Parameter	:	@LoginUserId, @RegularizationId, @EmployeeId, @Date, @StartTime, @EndTime, @Reason
						,@RegularizationStatusId.
 Output Parameters	:	@Status, @Message
 Author				:	Prakash.P
 Created on			:	06-04-2024
 Version			:	1.0 
 Comment			:   1. If the Given @Date & EmployeeId is already Exists with another @RegularizationId, then 
							1.1 Through the Error message as @Status = 0 & @Message = 'Given Date is already Exists.'
						2. IF the Given @Date & EmployeeId is already not Exists, then 
							2.1 Update the RegularizationDetails table have the column of
								EmployeeId					AS @EmployeeId
								,Date						AS @Date
								,StartTime					AS @StartTime
								,EndTime					AS @EndTime
								,Reason						AS @Reason
								,RegularizationStatusId		AS @RegularizationStatusId
								,UpdatedBy					AS @LoginUserId
							2.2 Then Return the Success msg as @Status = 1
								@Message = "RegularizationDetails are Updated Successfully."
=================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateRegularizationDetails]
(
	@LoginUserId					INT
	,@RegularizationId				INT
	,@EmployeeId					INT
	,@Date							DATE
	,@PunchType						NVARCHAR(50)
	,@InOutTime						TIME
	,@Reason						NVARCHAR(500)
	,@RegularizationStatusId		TINYINT
	,@Comments						NVARCHAR(2000)
	,@Status						BIT             OUT
	,@Message						NVARCHAR(500)   OUT
)   
AS
BEGIN
    SET NOCOUNT ON;

	DECLARE	@CompanyId	INT;
            
    SELECT  @CompanyId = CompanyId
    FROM    [dbo].[EmployeeDetails]
    WHERE   EmployeeId = @LoginUserId;

    BEGIN TRY
        BEGIN TRAN
			UPDATE [dbo].[RegularizationDetails]
			SET     EmployeeId					= @EmployeeId
					,[Date]						= @Date
					,PunchType					= @PunchType
					,InOutTime					= @InOutTime
					,Reason						= @Reason
					,RegularizationStatusId		= @RegularizationStatusId
					,Comments					= @Comments
					,Updatedby					= @LoginUserId
					,UpdatedDate				= GETDATE()
			WHERE   RegularizationId			= @RegularizationId 
			AND     CompanyId					= @CompanyId;

			IF	@RegularizationStatusId = 3
			BEGIN
				INSERT INTO [dbo].[AttendanceLogDetails](PunchDate, PunchTime, [Status], IsManual, [Description]
							, AttendanceStatusId, EmployeeId, CompanyId, CreatedBy)
				VALUES		(@Date, @InOutTime, CASE WHEN @PunchType = 1 THEN 1 ELSE 0 END, 1, NULL, 3
							,@EmployeeId, @CompanyId, @LoginUserId);

				UPDATE	ALD
				SET		[Status] = CASE	WHEN (	SELECT	COUNT(*) 
												FROM	[dbo].[AttendanceLogDetails] ALD2
												WHERE	ALD2.EmployeeId = ALD.EmployeeId 
												AND		ALD2.PunchDate = ALD.PunchDate 
												AND		CONVERT(TIME, ALD2.PunchTime) <= CONVERT(TIME, ALD.PunchTime)) %2 = 1 
											THEN 1 ELSE 0 END
				FROM	[dbo].[AttendanceLogDetails] ALD
				WHERE	EmployeeId = @EmployeeId
				AND		PunchDate = @Date
			END 

			-- NotificationDetails
			IF @RegularizationStatusId IN (3, 4)
			BEGIN
				INSERT INTO [dbo].[NotificationDetails] (NotificationModuleRefId, NotificationTypeName, IsInternal
							,MessageTo, DetailedMessage, MessageStatusId, EmployeeId, SMSStatus, NotificationStatus
							,SMS_To, IsAuto, CompanyId, CreatedBy)	                     
				SELECT  @RegularizationId
						,'Regularization'
						,1
						,'Employee'
						,CASE WHEN @RegularizationStatusId = 3 THEN 
							CONCAT('Dear ', ED.FirstName, ', Your Regularization request has been approved on ' 
									,CONVERT(NVARCHAR(50),@Date,105),'.')
								ELSE CONCAT('Dear ', ED.FirstName, ', Your Regularization request has been rejected on ' 
									,CONVERT(NVARCHAR(50),@Date,105),'.')
								END			
						,3
						,@EmployeeId
						,'Open'
						,'Open'
						,ED.ContactNo
						,1
						,@CompanyId
						,@LoginUserId
				FROM    [dbo].[RegularizationDetails] AS RD
				JOIN    [dbo].[EmployeeDetails] AS ED
					ON  ED.EmployeeId = RD.EmployeeId            
				WHERE   RegularizationId = @RegularizationId;
			END

		IF @@TRANCOUNT >= 0
        COMMIT TRAN

        SELECT	@Status		= 1
				,@Message	= 'RegularizationDetails are Updated Successfully.';

		IF @RegularizationStatusId IN (3, 4)
		BEGIN 
			IF EXISTS(SELECT 1 FROM NoticationCategoryDetails WHERE NoticationCategoryName LIKE '%Email%' AND IsActive = 1 AND CompanyId = @CompanyId)
			BEGIN 
				SELECT	Email AS FromMail
						,SMTPNumber
				FROM	NoticationCategoryDetails
				WHERE	IsActive = 1;

				SELECT	DISTINCT ED.OfficialEmail AS ToMail
						,CASE WHEN @RegularizationStatusId = 3 THEN 'Approval of Attendance Regularization' 
							ELSE 'Rejected of Attendance Regularization' END AS [Subject]
						,CONCAT('Dear ',CONCAT(ED.FirstName,' ',ED.LastName),',') AS FirstLine
						,'I hope you are doing well.' AS SecondLine
						,CASE WHEN @RegularizationStatusId = 3 THEN CONCAT('This is to inform you that your request for attendance regularization for ', CONVERT(NVARCHAR(50),@Date,106)
																			,' has been approved by {', EmployeeName, QUOTENAME(RVD.EmployeeCompanyId),'}.')
							ELSE CONCAT('This is to inform you that your request for attendance regularization for ', CONVERT(NVARCHAR(50),@Date,106)
											,' has been Rejected by {', EmployeeName, QUOTENAME(RVD.EmployeeCompanyId),'}.')
						END AS ThirdLine
						,'Please verify the changes at your end and let us know in case of any discrepancies.' AS FourthLine
						,'For any further assistance, feel free to reach out.' AS FifthLine
						,'Thank You.' AS SixthLine
				FROM	EmployeeDetails ED 
				LEFT JOIN (	SELECT	RD.EmployeeId, RegularizationId, EmployeeImage
									,CONCAT(ED.FirstName,' ',ED.LastName) AS EmployeeName
									,EmployeeCompanyId
							FROM	[dbo].[RegularizationDetails] RD
							JOIN	[dbo].[Employeedetails] ED
								ON	RD.Updatedby = ED.EmployeeId 
							WHERE	RD.CompanyId = @CompanyId 
							AND		RegularizationId = @RegularizationId
							) AS RVD
					ON	RVD.EmployeeId = ED.EmployeeId
				WHERE	ED.EmployeeId = @EmployeeId;
			END 
		END 
    END TRY
    BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(), ''));
    END CATCH
END
/*================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500);

	EXEC [dbo].[USP_UpdateRegularizationDetails]	@LoginUserId				= 1
													,@RegularizationId			= 52
													,@EmployeeId				= 3
													,@Date						= '2025-01-30'
													,@PunchType					= '1'
													,@InOutTime					= '09:30'
													,@Reason					= 'I forgot to CheckIn'
													,@RegularizationStatusId	= 3
													,@Comments					= 'I am approved the request.'
													,@Status					= @S_Status		OUT
													,@Message					= @M_Message	OUT;
	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT	* 
	FROM	[dbo].[RegularizationDetails]  
	SELECT *
	FROM	[dbo].[NotificationDetails];

	select	* 
	from	AttendanceLogDetails 
	WHERE	EmployeeId = 3
	AND		PunchDate = '2025-01-28'
	ORDER BY PunchTime ASC;
	
	select	* 
	from	LeaveStatusDetails 
=================================================================================================================================*/
	
GO
