/*====================================================================================================================================================  
 Procedure Name		:	[USP_UpdateSalaryComponentsDetails]
 Description		:	Procedure used to insert the new Claimdetails (When Click on Insert Button in ClaimInfo PopupPage)
 Input Parameter	:	@LoginUserId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@TVP_AttachmentDetails
 Output Parameters	:	@Status,@Message
 Author				:	Tharani.T
 Created on			:	016-09-2024
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateSalaryComponentsDetails]
(
	@LoginUserId					INT	
	,@SalaryComponentsId			INT
	,@ComponentName					NVARCHAR(50)
	,@SalaryComponentTypeId			INT
	,@ComponentAliasNameId			TINYINT
	,@CalculationTypeId				INT
	,@EarningAmount					NUMERIC(11,2)
	,@EarningType					NVARCHAR(20)
	,@Description					NVARCHAR(500)
	,@Status						BIT						OUT	
	,@Message						NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId		TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY			
		BEGIN TRAN  
			UPDATE  [dbo].[SalaryComponentsDetails]
			SET		ComponentName				= @ComponentName
					,SalaryComponentTypeId		= @SalaryComponentTypeId
					,ComponentAliasNameId		= @ComponentAliasNameId
					,CalculationTypeId			= @CalculationTypeId
					,EarningAmount				= @EarningAmount
					,EarningType				= @EarningType
					,[Description]				= @Description
					,Updatedby					= @LoginUserId 
					,UpdatedDate  				= GETDATE()
			WHERE	SalaryComponentsId			= @SalaryComponentsId 
			AND		CompanyId					= @CompanyId;

		IF @@TRANCOUNT >0
		COMMIT TRAN

		SELECT	@Status   = 1   
				,@Message = 'Changes Saved Successfully.';
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status	BIT
			,@M_Message	NVARCHAR(500)	

	EXEC [dbo].[USP_UpdateSalaryComponentsDetails]	@LoginUserId				= 1
													,@SalaryComponentsId		= 9
													,@ComponentName				='Bonus'
													,@SalaryComponentTypeId		= 2
													,@ComponentAliasNameId		= 1
													,@CalculationTypeId			= 3
													,@EarningAmount				= 213.00
													,@EarningType				= '₹'
													,@Description				= ''
													,@Status					= @S_Status		OUT
													,@Message					= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	 
	SELECT	* 
	FROM	[dbo].[SalaryComponentsDetails];

