/*====================================================================================================================================================  
 Procedure Name		:	[dbo].[USP_UpdateSalaryStructureDetails]
 Description		:	Procedure used to insert the new SalaryStructureDetails (When Click on Insert Button in Structure PopupPage)
 Input Parameter	:	@LoginUserId,@ClaimDate,@ClaimTypeId,@RequestedBy,@ClaimDescription,@ClaimAmount,@TVP_AttachmentDetails
 Output Parameters	:	@Status,@Message
 Author				:	Prakash.P
 Created on			:	03-10-2024
 Version			:	1.0 
 Comment			:	
=====================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateSalaryStructureDetails]
(
	@LoginUserId									INT	
	,@SalaryStructureId								INT
	,@SalaryStructureName							NVARCHAR(100)
	,@TVP_SalaryStructureComponentMappingDetails	TVP_SalaryStructureComponentMappingDetails	READONLY
	,@Status										BIT											OUT	
	,@Message										NVARCHAR(500)								OUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @CompanyId	TINYINT;

	SELECT	@CompanyId	= CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		IF EXISTS(	SELECT	1
					FROM	[dbo].[SalaryStructureDetails] 
					WHERE  SalaryStructurename = @SalaryStructureName
					AND		SalaryStructureId <> @SalaryStructureId
				  )
		BEGIN
			SELECT	 @Status  = 0
					,@Message = 'Entered SalaryStructureName is already Exist.';
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN  
				UPDATE  [dbo].[SalaryStructureDetails]
				SET		SalaryStructureName			= @SalaryStructureName
						,Updatedby					= @LoginUserId 
						,UpdatedDate  				= GETDATE()
				WHERE	SalaryStructureId			= @SalaryStructureId 
				AND		CompanyId					= @CompanyId;

				MERGE	[dbo].[SalaryStructureComponentMappingDetails]	AS TARGET
				USING	@TVP_SalaryStructureComponentMappingDetails		AS SOURCE
					ON	TARGET.SalaryStructureComponentMappingId = SOURCE.SalaryStructureComponentMappingId
					AND	TARGET.SalaryStructureId = @SalaryStructureId   
				WHEN MATCHED THEN
				UPDATE 
				SET		TARGET.SalaryStructureId	=	SOURCE.SalaryStructureId
						,TARGET.SalaryComponentsId	=	SOURCE.SalaryComponentsId
						,TARGET.IsActive			=	SOURCE.IsActive
						,TARGET.Updatedby			=	@LoginUserId
						,TARGET.UpdatedDate			=	GETDATE()
				WHEN NOT MATCHED THEN
				INSERT	(SalaryStructureId, SalaryComponentsId, IsActive, CreatedBy, CreatedDate)
				VALUES	(SOURCE.SalaryStructureId
						,SOURCE.SalaryComponentsId
						,SOURCE.IsActive
						,@LoginUserId
						,GETDATE())
				WHEN NOT MATCHED BY SOURCE AND TARGET.SalaryStructureId  = @SalaryStructureId THEN 
				DELETE;

			IF @@TRANCOUNT >0
			COMMIT TRAN

			SELECT	@Status   = 1   
					,@Message = 'Changes Saved Successfully.';
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT	@Status   = 0
				,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE	 @S_Status										BIT
			,@M_Message										NVARCHAR(500)	
			,@TVP_SalaryStructureComponentMappingDetails	TVP_SalaryStructureComponentMappingDetails;

	INSERT INTO @TVP_SalaryStructureComponentMappingDetails(SalaryComponentsId, IsActive, SalaryStructureId)
	VALUES		(2, 1, 1) 
				,(3, 0, 1)
				,(4, 0, 1);

	EXEC [dbo].[USP_UpdateSalaryStructureDetails]	@LoginUserId									= 1
													,@SalaryStructureId								= 2
													,@SalaryStructureName							= 'Structure 1'
													,@TVP_SalaryStructureComponentMappingDetails	= @TVP_SalaryStructureComponentMappingDetails
													,@Status										= @S_Status		OUT
													,@Message										= @M_Message	OUT;

	 SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	 
	SELECT	* 
	FROM	[dbo].[SalaryComponentsDetails];
	SELECT	* 
	FROM	[dbo].[SalaryStructureDetails];
	SELECT	* 
	FROM	[dbo].[SalaryStructureComponentMappingDetails];
======================================================================================================================================*/
GO
