/*=================================================================================================================================================
 Procedure Name		:	[dbo].[USP_UpdateStatutoryESIDetails]
 Description		:	Procedure used to Update the Existing BranchDetails(When Click on Update Button in setting Page)
 Input Parameter	:	@LoginUserId, @BranchName, @Address, @City, @State, @Country, @ZipCode, @ContactNumber, @Email
 Output Parameters	:	@Status, @Message
 Author				:	Tharani T
 Created on			:	22-02-2023
 Version			:	1.0 
 Comment			:	
=======================================================================================================================================================*/
CREATE         PROCEDURE [dbo].[USP_UpdateStatutoryESIDetails]
(
	@LoginUserId				INT	
	,@EmployeeESIId				INT
	,@EmployeeESINumber			NVARCHAR(50)
	,@DeductionCycle			NVARCHAR(50)
	,@EmployeeContribution		NVARCHAR(50)
	,@EmployerContribution		NVARCHAR(50)
	,@ISEmployerContribution	BIT
	,@Status					BIT						OUT
	,@Message					NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;

    DECLARE  @CompanyId TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status   = 1  
				,@Message = 'Changes Saved Successfully'; 

		--If NOT Exists, returns the Error msg as Status = 0 And Message = "Given BranchName is already mapped with another BranchId"		
		IF  EXISTS (SELECT 1 FROM [dbo].[ESIDetails] WHERE EmployeeESIId	 <> @EmployeeESIId	 AND EmployeeESINumber = @EmployeeESINumber AND CompanyId = @CompanyId)
		BEGIN
			SELECT	@Status   = 0 
					,@Message = 'Given BranchName is already mapped with another BranchId'
			RETURN;
		END
		ELSE
		BEGIN
			BEGIN TRAN
				UPDATE	[dbo].[ESIDetails]
				SET		EmployeeESINumber			= @EmployeeESINumber	
						,DeductionCycle				= @DeductionCycle	
						,EmployeeContribution		= @EmployeeContribution
						,EmployerContribution		= @EmployerContribution
						,ISEmployerContribution		= @ISEmployerContribution
						,UpdatedBy		= @LoginUserId
						,UpdatedDate	= GETDATE()
				WHERE	EmployeeESIId	= @EmployeeESIId
				AND		CompanyId		= @CompanyId;

			IF @@TRANCOUNT > 0
			COMMIT TRAN		
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status   = 0
			   ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE @S_Status BIT
			,@M_Message NVARCHAR(500)
		
	EXEC [dbo].[USP_UpdateStatutoryESIDetails]	@LoginUserId				=1
												,@EmployeeESIId				=1
												,@EmployeeESINumber			=""
												,@DeductionCycle			=""
												,@EmployeeContribution		=""
												,@EmployerContribution		=""
												,@ISEmployerContribution	=0
												,@Status		=  @S_Status OUT
												,@Message		=  @M_Message OUT;  

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[ESIDetails];
======================================================================================================================================*/
			
GO
