/*=================================================================================================================================================
 Procedure Name		:	[dbo].[USP_UpdateStatutoryProfessionalTaxDetails]
 Description		:	Procedure used to Update the Existing BranchDetails(When Click on Update Button in setting Page)
 Input Parameter	:	@LoginUserId, @BranchName, @Address, @City, @State, @Country, @ZipCode, @ContactNumber, @Email
 Output Parameters	:	@Status, @Message
 Author				:	Tharani T
 Created on			:	22-02-2023
 Version			:	1.0 
 Comment			:	
=======================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UpdateStatutoryProfessionalTaxDetails]
(
	@LoginUserId								INT	
	,@ProfessionalTaxId							INT
	,@WorkLocationId							INT
	,@ProfessionalTaxNumber						NVARCHAR(50)
	,@DeductionCycle							NVARCHAR(50)	,@TVP_ProfessionalTaxSlabMappingDetails		TVP_ProfessionalTaxSlabMappingDetails READONLY
	,@Status									BIT						OUT
	,@Message									NVARCHAR(500)			OUT
)
AS
BEGIN
	SET NOCOUNT ON;

    DECLARE  @CompanyId TINYINT;

	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId = @LoginUserId;

	BEGIN TRY
		SELECT	@Status   = 1  
				,@Message = 'Changes Saved Successfully'; 

		BEGIN
			BEGIN TRAN
				UPDATE	[dbo].[ProfessionalTaxDetails]	
				SET		WorkLocationId				= @WorkLocationId	
						,ProfessionalTaxNumber		= @ProfessionalTaxNumber	
						,DeductionCycle				= @DeductionCycle
						,UpdatedBy					= @LoginUserId
						,UpdatedDate				= GETDATE()
				WHERE	ProfessionalTaxId			= @ProfessionalTaxId
				AND		CompanyId					= @CompanyId;

			MERGE	[dbo].[ProfessionalTaxSlabMappingDetails]	AS TARGET  
			USING	@TVP_ProfessionalTaxSlabMappingDetails		AS SOURCE  
				ON	TARGET.ProfessionalTaxId = @ProfessionalTaxId
				AND TARGET.ProfessionalTaxSlabMappingId = SOURCE.ProfessionalTaxSlabMappingId    
			WHEN MATCHED THEN  
			UPDATE    
			SET		TARGET.StartRange				= SOURCE.StartRange  
					,TARGET.EndRange				= SOURCE.EndRange  
					,TARGET.HalfYearlyTaxAmount		= SOURCE.HalfYearlyTaxAmount    
					,TARGET.Updatedby				= @LoginUserId  
					,TARGET.UpdatedDate				= GETDATE()   
			WHEN NOT MATCHED BY Target THEN  
			INSERT (StartRange,EndRange,HalfYearlyTaxAmount,ProfessionalTaxId, CreatedBy,CreatedDate)  
			VALUES (SOURCE.StartRange
					,SOURCE.EndRange
					,SOURCE.HalfYearlyTaxAmount
					,@ProfessionalTaxId
					,@LoginUserId
					,GETDATE())
			WHEN NOT MATCHED BY SOURCE AND TARGET.ProfessionalTaxId = @ProfessionalTaxId THEN  
			DELETE;  

			IF @@TRANCOUNT >= 0
			COMMIT TRAN		
		END
	END TRY
	BEGIN CATCH
		ROLLBACK TRAN;
		SELECT @Status   = 0
			   ,@Message = CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
/*====================================================================================================================================
	DECLARE @S_Status BIT
			,@M_Message NVARCHAR(500)
		
	EXEC [dbo].[USP_UpdateStatutoryProfessionalTaxDetails]	@LoginUserId					=1
															,@EmployeePFId					=1
															,@EmployeePFNumber				=""
															,@DeductionCycle				=""
															,@EmployeeContributionRateId	=""
															,@EmployerContributionRateId	=""
															,@VoluntaryProvidentFund		=0
															,@Status						=  @S_Status OUT
															,@Message						=  @M_Message OUT;  

	SELECT @S_Status AS STATUS, @M_Message AS MESSAGE;

	SELECT * 
	FROM	[dbo].[ProfessionalTaxDetails];
======================================================================================================================================*/
GO
/****** Object:  StoredProcedure [dbo].[USP_UpdateUserAccessDetails]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*=====================================================================================================================================     
	Procedure Name		: [USP_UpdateUserAccessDetails]	      
	Description			: Procedure used to update the UserAccessDetail(When click on tickBox in User Access screen)   
	Input Parameters	: @LoginUserId, @EmployeeId    
	Output Parameters	: @Status, @Message      
	Author				: Nithya.M     
	Created On			: 11-03-2023     
	Version				: 1.0     
	Comments			:	1.If The Given ModuleActionId And UserGroupId is Exists, then
								Update the @IsAccess(1/0) in the UserGroupActionMappingDetails table.
							 1.1 Then through the error message  as @Status = 1 & @Message = 'UserAccessDetails are Updated SuccessFully.'
							2. If The Given ModuleActionId And UserGroupId is Not Exists,then
								Insert into the given @LoginUserId, @ModuleActionId, @UserGroupId,  @IsActive in the UserGroupActionMappingDetails Table.
===========================================================================================================================================*/         
CREATE     PROCEDURE [dbo].[USP_UpdateUserAccessDetails]	    
(    
	@LoginUserId		INT     
	,@ModuleActionId	INT  
	,@UserGroupId		TINYINT  
	,@IsActive			BIT       
	,@Status			BIT			  OUT          
	,@Message			NVARCHAR(500) OUT          
)    
AS    
BEGIN
	SET NOCOUNT ON;
		
	DECLARE @CompanyId TINYINT;

	-- Logic To Get CompanyId Of Given LoginUserId to Use In Below Where Conditions
	SELECT	@CompanyId = CompanyId 
	FROM	[dbo].[EmployeeDetails]
	WHERE	EmployeeId= @LoginUserId;

	BEGIN TRY
		BEGIN TRAN  
			--If the  ModuleActionId And UserGroupId is Exists are not? 
			IF EXISTS (SELECT 1 FROM [dbo].[UserGroupActionMappingDetails] WHERE ModuleActionId = @ModuleActionId AND UserGroupId = @UserGroupId)  
			BEGIN  
				--Update the UserGroupActionMappingDetails table
				UPDATE	[dbo].[UserGroupActionMappingDetails] 
				SET		IsActive		= @IsActive
						,UpdatedBy		= @LoginUserId
						,UpdatedDate	= GETDATE() 
				WHERE	ModuleActionId	= @ModuleActionId 
				AND		UserGroupId		= @UserGroupId;

				SELECT	@Status		= 1   
						,@Message	= 'Changes Saved Successfully.';
			END  
			ELSE   
			BEGIN  
				--Insert into the UserGroupActionMappingDetails table
				INSERT INTO [dbo].[UserGroupActionMappingDetails](ModuleActionId, UserGroupId, IsActive
							,CreatedBy, CreatedDate)  
				VALUES		(@ModuleActionId, @UserGroupId, @IsActive, @LoginUserId, GETDATE());

				SELECT	@Status		= 1   
						,@Message	= 'Record Added Successfully.';
			END

		IF @@TRANCOUNT >0
		COMMIT TRAN

	END TRY
	BEGIN CATCH
		ROLLBACK TRAN; 
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END 
