/****** Object:  StoredProcedure [dbo].[USP_UserLogin_New]    Script Date: 18-02-2025 21:14:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*==========================================================================================================================================================
	Procedure Name		:  USP_UserLogin_New
	Description			:  SP to validate the UserLogin Credential(When Click on Login Button)
	Input Parameters	:  @EmployeeId
	Output Parameters	:  @Status, @Message
	Author				:  Nithya.M
	Created On			:  02-08-2023
	Version				:  1.0
	Comments			:  1.Return the Resultset for UserAccess for LoggedIn user.
=============================================================================================================================================================*/
CREATE   PROCEDURE [dbo].[USP_UserLogin_New]
(
	@EmployeeId	NVARCHAR(100)
	,@Status	BIT				OUT
	,@Message	NVARCHAR(500)   OUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @UserGroupId TINYINT;

	SELECT	@UserGroupId = UserGroupId
	FROM	[dbo].[EmployeeDetails] 
	WHERE	EmployeeId = @EmployeeId;

	BEGIN TRY
		BEGIN
			--UserAccess Info.
			SELECT	@UserGroupId AS UserGroupId
					,MAD.ModuleId AS ActionId     
					,MD.ModuleName  AS Module  
					,MAD.ModuleActionName AS ModuleAction  
					,IsParent
					,ParentModuleId
					,CASE WHEN ISNULL(RAD.IsActive,0) = 0 THEN 0 ELSE 1 END IsHasAccess
			FROM	[dbo].[ModuleDetails] MD
			LEFT JOIN	[dbo].[ModuleActionDetails] MAD 
				ON	MD.ModuleId = MAD.ModuleId
			LEFT JOIN ( SELECT	ED.UserGroupId
								,UGAP.ModuleActionId AS AccessId
								,UGAP.Isactive 
						FROM	[dbo].[UserGroupActionMappingDetails] UGAP     
						JOIN	[dbo].[UserGroupDetails] UGD     
							ON	UGAP.UserGroupId = UGD.UserGroupId       
						JOIN	(	SELECT	* 
									FROM	[dbo].[EmployeeDetails] 
									WHERE	EmployeeId = @EmployeeId
									AND		IsActive = 1 
								) ED     
							ON	ED.UserGroupId  = UGD.UserGroupId 							
						) RAD 
				ON MAD.ModuleActionId = RAD.AccessId 				      
			WHERE	MAD.IsActive = 1;
			END
				SELECT	@Status		= 1 
						,@Message	= NULL;	
	END TRY
	BEGIN CATCH
		SELECT	@Status		= 0
				,@Message	= CONVERT(NVARCHAR(500), ISNULL(ERROR_MESSAGE(),''));
	END CATCH
END
